		{
			if (string.IsNullOrEmpty(encounterCulture?.EncounterBackgroundMesh))
			{
				TaleWorlds.Library.Debug.FailedAssert("Background mesh is invalid for current encounter", "C:\\BuildAgent\\work\\mb3\\Source\\Bannerlord\\TaleWorlds.CampaignSystem\\Helpers.cs", "GetEncounterCultureBackgroundMesh", 829);
				return string.Empty;
