		public static Clan GetRandomClanForNotable(Hero notable)
		{
			float num = 0f;
			List<Clan> list = new List<Clan>();
			if (notable.IsPreacher)
			{
				num = 0.5f;
				list = Clan.NonBanditFactions.Where((Clan x) => x.IsSect).ToList();
			}
			if (notable.IsGangLeader)
			{
				num = 0.5f;
				list = Clan.NonBanditFactions.Where((Clan x) => x.IsMafia).ToList();
			}
			if (MBRandom.RandomFloat >= num)
			{
				return null;
			}
			foreach (Hero notable2 in notable.HomeSettlement.Notables)
			{
				if (list.Contains(notable2.SupporterOf))
				{
					list.Remove(notable2.SupporterOf);
				}
			}
			float num2 = 0f;
			ILookup<Clan, Settlement> lookup = Settlement.All.Where((Settlement x) => x.IsTown || x.IsHideout).ToLookup((Settlement x) => x.OwnerClan);
			foreach (Clan item in list)
			{
				num2 += GetProbabilityForClan(item, lookup[item], notable);
			}
			num2 *= MBRandom.RandomFloat;
			foreach (Clan item2 in list)
			{
				num2 -= GetProbabilityForClan(item2, lookup[item2], notable);
				if (num2 <= 0f)
				{
					return item2;
				}
			}
			return null;
		}

		private static float GetProbabilityForClan(Clan clan, IEnumerable<Settlement> applicableSettlements, Hero notable)
		{
			float num = 1f;
			if (clan.Culture == notable.Culture)
			{
				num *= 3f;
			}
			float num2 = float.MaxValue;
			foreach (Settlement applicableSettlement in applicableSettlements)
			{
				float num3 = applicableSettlement.Position.DistanceSquared(notable.HomeSettlement.Position);
				if (num3 < num2)
				{
					num2 = num3;
				}
			}
			return num / num2;
		}

		public static CampaignTime GetRandomBirthDayForAge(float age)
		{
			float valueInDays = MBRandom.RandomFloatRanged(0f, CampaignTime.Now.GetDayOfYear);
			float valueInYears = (float)CampaignTime.Now.GetYear - age;
			return CampaignTime.Days(valueInDays) + CampaignTime.Years(valueInYears);
		}

		public static void GetRandomDeathDayAndBirthDay(int deathAge, out CampaignTime birthday, out CampaignTime deathday)
		{
			int daysInYear = CampaignTime.DaysInYear;
			int num = MBRandom.RandomInt(daysInYear);
			birthday = CampaignTime.Years(CampaignTime.Now.GetYear - deathAge - 1) - CampaignTime.Days(num);
			deathday = birthday + CampaignTime.Years(deathAge) + CampaignTime.Days(MBRandom.RandomInt(daysInYear - 1));
		}

		public static float StartRecruitingMoneyLimit(Hero hero)
		{
			if (hero.Clan == Clan.PlayerClan)
			{
				return 0f;
			}
			return 50f + ((hero.PartyBelongedTo != null) ? ((float)TaleWorlds.Library.MathF.Min(150, hero.PartyBelongedTo.MemberRoster.TotalManCount) * 20f) : 0f);
		}

		public static float StartRecruitingMoneyLimitForClanLeader(Hero hero)
		{
			if (hero.Clan == Clan.PlayerClan)
			{
				return 0f;
			}
			return 50f + ((hero.Clan != null && hero.Clan.Leader != null && hero.Clan.Leader.PartyBelongedTo != null) ? ((float)hero.Clan.Leader.PartyBelongedTo.TotalWage + (float)hero.Clan.Leader.PartyBelongedTo.MemberRoster.TotalManCount * 40f) : 0f);
		}

		public static TextObject GetPersonalityTraitChangeName(TraitObject traitObject, Hero hero, bool isPositive)
		{
			if (DefaultTraits.Personality.Contains(traitObject))
			{
				int traitLevel = hero.GetTraitLevel(traitObject);
				string id = "str_trait_name_" + traitObject.StringId.ToLower();
				string variation = (isPositive ? "3" : "1");
				if (traitLevel < 0)
				{
					variation = (isPositive ? "3" : "0");
				}
				else if (traitLevel > 0)
				{
					variation = (isPositive ? "4" : "1");
				}
				return GameTexts.FindText(id, variation);
			}
			TaleWorlds.Library.Debug.FailedAssert("Given trait is not a personality trait!", "C:\\BuildAgent\\work\\mb3\\Source\\Bannerlord\\TaleWorlds.CampaignSystem\\Helpers.cs", "GetPersonalityTraitChangeName", 2998);
			return TextObject.GetEmpty();
		}
	}
	public static class PartyBaseHelper
	{
		public static void SortRoster(MobileParty mobileParty)
		{
			CharacterObject characterObject = null;
			foreach (TroopRosterElement item in mobileParty.MemberRoster.GetTroopRoster())
			{
				if (characterObject == null || characterObject.Tier < item.Character.Tier)
				{
					characterObject = item.Character;
					if (characterObject.Tier == Campaign.Current.Models.CharacterStatsModel.MaxCharacterTier)
					{
						break;
					}
				}
			}
			if (characterObject != null)
			{
				mobileParty.MemberRoster.SwapTroopsAtIndices(mobileParty.MemberRoster.FindIndexOfTroop(characterObject), 0);
			}
		}

		public static TextObject GetPartySizeText(PartyBase party)
		{
			if (party.NumberOfHealthyMembers == party.NumberOfAllMembers)
			{
				return new TextObject(party.NumberOfHealthyMembers.ToString());
			}
			MBTextManager.SetTextVariable("HEALTHY_NUM", party.NumberOfHealthyMembers);
			MBTextManager.SetTextVariable("WOUNDED_NUM", party.NumberOfAllMembers - party.NumberOfHealthyMembers);
			return GameTexts.FindText("str_party_health");
		}

		public static TextObject GetPartySizeText(int healtyNumber, int woundedNumber, bool isInspected)
		{
			string seed = "";
			if (isInspected)
			{
				if (woundedNumber == 0)
				{
					return new TextObject(healtyNumber);
				}
				TextObject textObject = GameTexts.FindText("str_party_health");
				textObject.SetTextVariable("HEALTHY_NUM", healtyNumber);
				textObject.SetTextVariable("WOUNDED_NUM", woundedNumber);
				return textObject;
			}
			string text = new int[4] { 0, 10, 100, 1000 }.Where((int t) => t < healtyNumber + woundedNumber).Aggregate(seed, (string current, int t) => current + "?");
			return new TextObject("{=!}" + text);
		}

		public static string GetShipSizeText(int shipCount, bool isInspected)
		{
			if (isInspected)
			{
				return shipCount.ToString();
			}
			return "?";
		}

		public static float FindPartySizeNormalLimit(MobileParty mobileParty)
		{
			int num = Math.Min((mobileParty.LeaderHero != null && mobileParty.Party.Owner?.Clan != null && mobileParty.LeaderHero != mobileParty.Party.Owner.Clan.Leader) ? mobileParty.LeaderHero.CharacterObject.TroopWage : 0, mobileParty.TotalWage);
			int a = (int)((float)(mobileParty.PaymentLimit - num) / Campaign.Current.AverageWage) + 1;
			int num2 = TaleWorlds.Library.MathF.Max(1, TaleWorlds.Library.MathF.Min(a, mobileParty.Party.PartySizeLimit));
			return TaleWorlds.Library.MathF.Max(0.1f, (float)num2 / (float)mobileParty.Party.PartySizeLimit);
		}

