		{
			List<TextObject> list = new List<TextObject>();
			if (name == null)
			{
				TaleWorlds.Library.Debug.FailedAssert("Calling IsFactionNameApplicable with null string!", "C:\\BuildAgent\\work\\mb3\\Source\\Bannerlord\\TaleWorlds.CampaignSystem\\Helpers.cs", "IsFactionNameApplicable", 5560);
				name = string.Empty;
			}
			if (name.Length > 50 || name.Length < 1)
			{
				TextObject item = GameTexts.FindText("str_faction_name_invalid_character_count").SetTextVariable("MIN", 1).SetTextVariable("MAX", 50);
				list.Add(item);
			}
			if (Common.TextContainsSpecialCharacters(name))
