	public static class BarterHelper
	{
		private static bool ItemExistsInBarterables(List<Barterable> barterables, ItemBarterable itemBarterable)
		{
			return barterables.AnyQ((Barterable x) => x is ItemBarterable { ItemRosterElement: { EquipmentElement: var equipmentElement } } && equipmentElement.Item == itemBarterable.ItemRosterElement.EquipmentElement.Item);
		}

		public static IEnumerable<(Barterable barterable, int count)> GetAutoBalanceBarterablesAdd(BarterData barterData, IFaction factionToBalanceFor, IFaction offerer, Hero offererHero, float fulfillRatio = 1f)
		{
			List<Barterable> offeredBarterables = barterData.GetOfferedBarterables();
			List<Barterable> list = barterData.GetBarterables().WhereQ((Barterable x) => x.OriginalOwner == offererHero && (!(x is ItemBarterable itemBarterable) || !ItemExistsInBarterables(barterData.GetOfferedBarterables(), itemBarterable))).ToList();
			int num = 0;
			foreach (Barterable item in offeredBarterables)
			{
				num += item.GetValueForFaction(factionToBalanceFor);
			}
			List<(Barterable, int)> list2 = new List<(Barterable, int)>();
			int num2 = (int)((0f - fulfillRatio) * (float)num);
			bool flag = false;
			while (num2 > 0 && !flag)
			{
				float num3 = 0f;
				Barterable barterable = null;
				for (int i = 0; i < list.Count; i++)
				{
					Barterable barterable2 = list[i];
					float num4 = 0f;
					if (!barterable2.IsOffered || barterable2.CurrentAmount < barterable2.MaxAmount)
					{
						int unitValueForFaction = barterable2.GetUnitValueForFaction(factionToBalanceFor);
						int unitValueForFaction2 = barterable2.GetUnitValueForFaction(offerer);
						int num5 = barterable2.MaxAmount - barterable2.CurrentAmount;
						if (barterable2 is GoldBarterable && unitValueForFaction * num5 >= num2)
						{
							barterable = barterable2;
							break;
						}
						if (unitValueForFaction > 0)
						{
							if (unitValueForFaction2 >= 0)
							{
								num4 = 10000000f;
							}
							else
							{
								num4 = (float)(-unitValueForFaction) / (float)unitValueForFaction2;
								if (unitValueForFaction > num2)
								{
									num4 = (float)unitValueForFaction / (float)(-unitValueForFaction2 + (unitValueForFaction - num2));
								}
							}
						}
					}
					if (num4 > num3)
					{
						num3 = num4;
						barterable = barterable2;
					}
				}
				if (barterable == null)
				{
					flag = true;
					continue;
				}
				int unitValueForFaction3 = barterable.GetUnitValueForFaction(factionToBalanceFor);
				int num6 = barterable.MaxAmount;
				if (barterable.IsOffered)
				{
					num6 -= barterable.CurrentAmount;
				}
				int num7 = TaleWorlds.Library.MathF.Min(TaleWorlds.Library.MathF.Ceiling((float)num2 / (float)unitValueForFaction3), num6);
				list2.Add((barterable, num7));
				list.Remove(barterable);
				num2 -= num7 * unitValueForFaction3;
			}
			return list2;
		}

		public static IEnumerable<(Barterable barterable, int count)> GetAutoBalanceBarterablesToRemove(BarterData barterData, IFaction factionToBalanceFor, IFaction offerer, Hero offererHero)
		{
			List<Barterable> offeredBarterables = barterData.GetOfferedBarterables();
			int num = 0;
			foreach (Barterable item in offeredBarterables)
			{
				num += item.GetValueForFaction(factionToBalanceFor);
			}
			List<(Barterable, int)> list = new List<(Barterable, int)>();
			int num2 = num;
			bool flag = false;
			while (num2 > 0 && !flag)
			{
				float num3 = 0f;
				Barterable barterable = null;
				for (int i = 0; i < offeredBarterables.Count; i++)
				{
					Barterable barterable2 = offeredBarterables[i];
					float num4 = 0f;
					if (barterable2.CurrentAmount > 0)
					{
						int unitValueForFaction = barterable2.GetUnitValueForFaction(factionToBalanceFor);
						int unitValueForFaction2 = barterable2.GetUnitValueForFaction(offerer);
						if (unitValueForFaction > 0)
						{
							num4 = ((unitValueForFaction2 < 0) ? ((float)(-unitValueForFaction2) / (float)unitValueForFaction) : (-10000f));
						}
					}
					if (num4 > num3)
					{
						num3 = num4;
						barterable = barterable2;
					}
				}
				if (barterable == null)
				{
					flag = true;
					continue;
				}
				int unitValueForFaction3 = barterable.GetUnitValueForFaction(factionToBalanceFor);
				int currentAmount = barterable.CurrentAmount;
				int num5 = TaleWorlds.Library.MathF.Min(TaleWorlds.Library.MathF.Ceiling((float)num2 / (float)unitValueForFaction3), currentAmount);
				list.Add((barterable, num5));
				offeredBarterables.Remove(barterable);
				num2 -= num5 * unitValueForFaction3;
			}
			return list;
		}
	}
	public static class BuildingHelper
	{
		public static void CheckIfBuildingIsComplete(Building building)
		{
			if ((float)building.GetConstructionCost() <= building.BuildingProgress)
			{
				if (building.CurrentLevel < 3)
				{
					building.LevelUp();
				}
				if (building.CurrentLevel == 3)
				{
					building.BuildingProgress = building.GetConstructionCost();
				}
				building.Town.BuildingsInProgress.Dequeue();
			}
		}

		public static void ChangeDefaultBuilding(Building newDefault, Town town)
		{
			foreach (Building building in town.Buildings)
			{
				if (building.IsCurrentlyDefault)
				{
					building.IsCurrentlyDefault = false;
				}
				if (building == newDefault)
				{
					building.IsCurrentlyDefault = true;
				}
			}
		}

		public static void ChangeCurrentBuildingQueue(List<Building> buildings, Town town)
		{
			town.BuildingsInProgress.Clear();
			foreach (Building building in buildings)
			{
				if (!building.BuildingType.IsDailyProject)
				{
					town.BuildingsInProgress.Enqueue(building);
				}
				else
				{
					TaleWorlds.Library.Debug.FailedAssert("DefaultProject in building queue", "C:\\BuildAgent\\work\\mb3\\Source\\Bannerlord\\TaleWorlds.CampaignSystem\\Helpers.cs", "ChangeCurrentBuildingQueue", 7278);
				}
			}
		}

		public static float GetProgressOfBuilding(Building building, Town town)
		{
			foreach (Building building2 in town.Buildings)
			{
				if (building2 == building)
				{
					return building.BuildingProgress / (float)building.GetConstructionCost();
				}
			}
			TaleWorlds.Library.Debug.FailedAssert(string.Concat(building.Name, "is not a project of", town.Name), "C:\\BuildAgent\\work\\mb3\\Source\\Bannerlord\\TaleWorlds.CampaignSystem\\Helpers.cs", "GetProgressOfBuilding", 7293);
			return 0f;
		}

		public static int GetDaysToComplete(Building building, Town town)
		{
			BuildingConstructionModel buildingConstructionModel = Campaign.Current.Models.BuildingConstructionModel;
			foreach (Building building2 in town.Buildings)
			{
				if (building2 != building)
				{
					continue;
				}
				float num = (float)building.GetConstructionCost() - building.BuildingProgress;
				int num2 = (int)town.Construction;
				if (num2 != 0)
				{
					int num3 = (int)(num / (float)num2);
					int num4 = (town.IsCastle ? buildingConstructionModel.CastleBoostCost : buildingConstructionModel.TownBoostCost);
					if (town.BoostBuildingProcess >= num4)
					{
						int num5 = town.BoostBuildingProcess / num4;
						if (num3 > num5)
						{
							int num6 = num5 * num2;
							int num7 = Campaign.Current.Models.BuildingConstructionModel.CalculateDailyConstructionPowerWithoutBoost(town);
							return num5 + TaleWorlds.Library.MathF.Max((int)((num - (float)num6) / (float)num7), 1);
						}
					}
					return TaleWorlds.Library.MathF.Max(num3, 1);
				}
				return -1;
			}
			TaleWorlds.Library.Debug.FailedAssert(string.Concat(building.Name, "is not a project of", town.Name), "C:\\BuildAgent\\work\\mb3\\Source\\Bannerlord\\TaleWorlds.CampaignSystem\\Helpers.cs", "GetDaysToComplete", 7335);
			return 0;
		}

		public static int GetTierOfBuilding(BuildingType buildingType, Town town)
		{
			foreach (Building building in town.Buildings)
			{
				if (building.BuildingType == buildingType)
				{
					return building.CurrentLevel;
				}
			}
			TaleWorlds.Library.Debug.FailedAssert(string.Concat(buildingType.Name, "is not a project of", town.Name), "C:\\BuildAgent\\work\\mb3\\Source\\Bannerlord\\TaleWorlds.CampaignSystem\\Helpers.cs", "GetTierOfBuilding", 7349);
			return 0;
		}

		public static void BoostBuildingProcessWithGold(int gold, Town town)
		{
			if (gold < town.BoostBuildingProcess)
			{
				GiveGoldAction.ApplyBetweenCharacters(null, Hero.MainHero, town.BoostBuildingProcess - gold);
			}
			else if (gold > town.BoostBuildingProcess)
			{
				GiveGoldAction.ApplyBetweenCharacters(Hero.MainHero, null, gold - town.BoostBuildingProcess);
			}
			town.BoostBuildingProcess = gold;
		}
	}
