	public interface IMbEvent
	{
		void AddNonSerializedListener(object owner, Action action);

		void ClearListeners(object o);
	}
	public class MbEvent : IMbEvent
	{
		internal class EventHandlerRec
		{
			public EventHandlerRec Next;

			internal Action Action { get; private set; }

			internal object Owner { get; private set; }

			public EventHandlerRec(object owner, Action action)
			{
				Action = action;
				Owner = owner;
			}
		}

		private EventHandlerRec _nonSerializedListenerList;

		public void AddNonSerializedListener(object owner, Action action)
		{
			EventHandlerRec eventHandlerRec = new EventHandlerRec(owner, action);
			EventHandlerRec nonSerializedListenerList = _nonSerializedListenerList;
			_nonSerializedListenerList = eventHandlerRec;
			eventHandlerRec.Next = nonSerializedListenerList;
		}

		public void Invoke()
		{
			InvokeList(_nonSerializedListenerList);
		}

		private void InvokeList(EventHandlerRec list)
		{
			while (list != null)
			{
				list.Action();
				list = list.Next;
			}
		}

		public void ClearListeners(object o)
		{
			ClearListenerOfList(ref _nonSerializedListenerList, o);
		}

		private void ClearListenerOfList(ref EventHandlerRec list, object o)
		{
			EventHandlerRec eventHandlerRec = list;
			while (eventHandlerRec != null && eventHandlerRec.Owner != o)
			{
				eventHandlerRec = eventHandlerRec.Next;
			}
			if (eventHandlerRec == null)
			{
				return;
			}
			EventHandlerRec eventHandlerRec2 = list;
			if (eventHandlerRec2 == eventHandlerRec)
			{
				list = eventHandlerRec2.Next;
				return;
			}
			while (eventHandlerRec2 != null)
			{
				if (eventHandlerRec2.Next == eventHandlerRec)
				{
					eventHandlerRec2.Next = eventHandlerRec.Next;
				}
				else
				{
					eventHandlerRec2 = eventHandlerRec2.Next;
				}
			}
		}
	}
	public class MBCampaignEvent
	{
		public delegate void CampaignEventDelegate(MBCampaignEvent campaignEvent, params object[] delegateParams);

		public string description;

		protected List<CampaignEventDelegate> handlers = new List<CampaignEventDelegate>();

		[CachedData]
		protected CampaignTime NextTriggerTime;

		public CampaignTime TriggerPeriod { get; private set; }

		public CampaignTime InitialWait { get; private set; }

		public bool isEventDeleted { get; set; }

		public MBCampaignEvent(string eventName)
		{
			description = eventName;
		}

		public MBCampaignEvent(CampaignTime triggerPeriod, CampaignTime initialWait)
		{
			TriggerPeriod = triggerPeriod;
			InitialWait = initialWait;
			NextTriggerTime = CampaignTime.Now + InitialWait;
			isEventDeleted = false;
		}

		public void AddHandler(CampaignEventDelegate gameEventDelegate)
		{
			handlers.Add(gameEventDelegate);
		}

		public void RunHandlers(params object[] delegateParams)
		{
			for (int i = 0; i < handlers.Count; i++)
			{
				handlers[i](this, delegateParams);
			}
		}

		public void Unregister(object instance)
		{
			for (int i = 0; i < handlers.Count; i++)
			{
				if (handlers[i].Target == instance)
				{
					handlers.RemoveAt(i);
					i--;
				}
			}
		}

		public void CheckUpdate()
		{
			while (NextTriggerTime.IsPast && !isEventDeleted)
			{
				RunHandlers(CampaignTime.Now);
				NextTriggerTime += TriggerPeriod;
			}
		}

		public void DeletePeriodicEvent()
