				{
					result = (PartyBelongedToAsPrisoner.IsSettlement ? PartyBelongedToAsPrisoner.Settlement : (PartyBelongedToAsPrisoner.IsMobile ? PartyBelongedToAsPrisoner.MobileParty.CurrentSettlement : null));
