		public IEnumerable<Hero> Siblings
		{
			get
			{
				if (Father != null)
				{
					foreach (Hero child in Father._children)
					{
						if (child != this)
						{
							yield return child;
						}
					}
				}
				else
				{
					if (Mother == null)
					{
						yield break;
					}
					foreach (Hero child2 in Mother._children)
					{
						if (child2 != this)
						{
							yield return child2;
						}
					}
				}
			}
		}

