	internal class DialogFlowLine
	{
		internal TextObject Text;

		internal string InputToken;

		internal string OutputToken;

		internal bool ByPlayer;

		internal ConversationSentence.OnConditionDelegate ConditionDelegate;

		internal ConversationSentence.OnClickableConditionDelegate ClickableConditionDelegate;

		internal ConversationSentence.OnConsequenceDelegate ConsequenceDelegate;

		internal ConversationSentence.OnMultipleConversationConsequenceDelegate SpeakerDelegate;

		internal ConversationSentence.OnMultipleConversationConsequenceDelegate ListenerDelegate;

		internal bool IsRepeatable;

		internal bool IsSpecialOption;

		internal bool IsUsedOnce;

		public List<KeyValuePair<TextObject, List<GameTextManager.ChoiceTag>>> Variations { get; private set; }

		public bool HasVariation => Variations.Count > 0;

		internal DialogFlowLine()
		{
			Variations = new List<KeyValuePair<TextObject, List<GameTextManager.ChoiceTag>>>();
		}

		public void AddVariation(TextObject text, List<GameTextManager.ChoiceTag> list)
		{
			Variations.Add(new KeyValuePair<TextObject, List<GameTextManager.ChoiceTag>>(text, list));
		}
	}
	internal class DialogFlowContext
	{
		internal readonly string Token;

		internal readonly bool ByPlayer;

		internal readonly DialogFlowContext Parent;

		internal readonly bool OptionsUsedOnlyOnce;

		public DialogFlowContext(string token, bool byPlayer, DialogFlowContext parent, bool optionsUsedOnlyOnce)
		{
			Token = token;
			ByPlayer = byPlayer;
			Parent = parent;
			OptionsUsedOnlyOnce = optionsUsedOnlyOnce;
		}
	}
	public class DialogFlow
	{
		internal readonly List<DialogFlowLine> Lines = new List<DialogFlowLine>();

		internal readonly int Priority;

		private string _currentToken;

		private DialogFlowLine _lastLine;

		private DialogFlowContext _curDialogFlowContext;

		private DialogFlow(string startingToken, int priority = 100)
		{
			_currentToken = startingToken;
			Priority = priority;
		}

		private DialogFlow Line(TextObject text, bool byPlayer, ConversationSentence.OnMultipleConversationConsequenceDelegate speakerDelegate = null, ConversationSentence.OnMultipleConversationConsequenceDelegate listenerDelegate = null, bool isRepeatable = false, string inputToken = null, string outputToken = null)
		{
			string text2 = outputToken ?? Campaign.Current.ConversationManager.CreateToken();
			AddLine(text, inputToken ?? _currentToken, text2, byPlayer, speakerDelegate, listenerDelegate, isRepeatable);
			_currentToken = text2;
			return this;
		}

		public DialogFlow Variation(string text, params object[] propertiesAndWeights)
		{
			return Variation(new TextObject(text), propertiesAndWeights);
		}

		public DialogFlow Variation(TextObject text, params object[] propertiesAndWeights)
		{
			for (int i = 0; i < propertiesAndWeights.Length; i += 2)
			{
				string tagName = (string)propertiesAndWeights[i];
				int weight = Convert.ToInt32(propertiesAndWeights[i + 1]);
				List<GameTextManager.ChoiceTag> list = new List<GameTextManager.ChoiceTag>();
				list.Add(new GameTextManager.ChoiceTag(tagName, weight));
				Lines[Lines.Count - 1].AddVariation(text, list);
			}
			return this;
		}

		public DialogFlow NpcLine(string npcText, ConversationSentence.OnMultipleConversationConsequenceDelegate speakerDelegate = null, ConversationSentence.OnMultipleConversationConsequenceDelegate listenerDelegate = null, string inputToken = null, string outputToken = null)
		{
			return NpcLine(new TextObject(npcText), speakerDelegate, listenerDelegate, inputToken, outputToken);
		}

		public DialogFlow NpcLine(TextObject npcText, ConversationSentence.OnMultipleConversationConsequenceDelegate speakerDelegate = null, ConversationSentence.OnMultipleConversationConsequenceDelegate listenerDelegate = null, string inputToken = null, string outputToken = null)
		{
			return Line(npcText, byPlayer: false, speakerDelegate, listenerDelegate, isRepeatable: false, inputToken, outputToken);
		}

		public DialogFlow NpcLineWithVariation(string npcText, ConversationSentence.OnMultipleConversationConsequenceDelegate speakerDelegate = null, ConversationSentence.OnMultipleConversationConsequenceDelegate listenerDelegate = null, string inputToken = null, string outputToken = null)
		{
			DialogFlow result = Line(TextObject.GetEmpty(), byPlayer: false, speakerDelegate, listenerDelegate, isRepeatable: false, inputToken, outputToken);
			List<GameTextManager.ChoiceTag> list = new List<GameTextManager.ChoiceTag>
			{
				new GameTextManager.ChoiceTag("DefaultTag", 1)
			};
			Lines[Lines.Count - 1].AddVariation(new TextObject(npcText), list);
			return result;
		}

		public DialogFlow NpcLineWithVariation(TextObject npcText, ConversationSentence.OnMultipleConversationConsequenceDelegate speakerDelegate = null, ConversationSentence.OnMultipleConversationConsequenceDelegate listenerDelegate = null, string inputToken = null, string outputToken = null)
		{
			DialogFlow result = Line(TextObject.GetEmpty(), byPlayer: false, speakerDelegate, listenerDelegate, isRepeatable: false, inputToken, outputToken);
			List<GameTextManager.ChoiceTag> list = new List<GameTextManager.ChoiceTag>
			{
				new GameTextManager.ChoiceTag("DefaultTag", 1)
			};
			Lines[Lines.Count - 1].AddVariation(npcText, list);
			return result;
		}

		public DialogFlow PlayerLine(string playerText, ConversationSentence.OnMultipleConversationConsequenceDelegate listenerDelegate = null, string inputToken = null, string outputToken = null)
		{
			return Line(new TextObject(playerText), byPlayer: true, null, listenerDelegate, isRepeatable: false, inputToken, outputToken);
		}

		public DialogFlow PlayerLine(TextObject playerText, ConversationSentence.OnMultipleConversationConsequenceDelegate listenerDelegate = null, string inputToken = null, string outputToken = null)
		{
			return Line(playerText, byPlayer: true, null, listenerDelegate, isRepeatable: false, inputToken, outputToken);
		}

		private DialogFlow BeginOptions(bool byPlayer, string inputToken = null, bool optionUsedOnce = false)
		{
			_curDialogFlowContext = new DialogFlowContext(inputToken ?? _currentToken, byPlayer, _curDialogFlowContext, optionUsedOnce);
			return this;
		}

		public DialogFlow BeginPlayerOptions(string inputToken = null, bool optionUsedOnce = false)
		{
			return BeginOptions(byPlayer: true, inputToken, optionUsedOnce);
		}

		public DialogFlow BeginNpcOptions(string inputToken = null, bool optionUsedOnce = false)
		{
			return BeginOptions(byPlayer: false, inputToken, optionUsedOnce);
		}

		private DialogFlow Option(TextObject text, bool byPlayer, ConversationSentence.OnMultipleConversationConsequenceDelegate speakerDelegate = null, ConversationSentence.OnMultipleConversationConsequenceDelegate listenerDelegate = null, bool isRepeatable = false, bool isSpecialOption = false, string inputToken = null, string outputToken = null)
		{
			string text2 = outputToken ?? Campaign.Current.ConversationManager.CreateToken();
			AddLine(text, inputToken ?? _curDialogFlowContext.Token, text2, byPlayer, speakerDelegate, listenerDelegate, isRepeatable, isSpecialOption, _curDialogFlowContext.OptionsUsedOnlyOnce);
			_currentToken = text2;
			return this;
		}

		public DialogFlow PlayerOption(string text, ConversationSentence.OnMultipleConversationConsequenceDelegate listenerDelegate = null, string inputToken = null, string outputToken = null)
		{
			return PlayerOption(new TextObject(text), listenerDelegate, inputToken, outputToken);
		}

		public DialogFlow PlayerOption(TextObject text, ConversationSentence.OnMultipleConversationConsequenceDelegate listenerDelegate = null, string inputToken = null, string outputToken = null)
		{
			Option(text, byPlayer: true, null, listenerDelegate, isRepeatable: false, isSpecialOption: false, inputToken, outputToken);
			return this;
		}

		public DialogFlow PlayerSpecialOption(TextObject text, ConversationSentence.OnMultipleConversationConsequenceDelegate listenerDelegate = null, string inputToken = null, string outputToken = null)
		{
			Option(text, byPlayer: true, null, listenerDelegate, isRepeatable: false, isSpecialOption: true, inputToken, outputToken);
			return this;
		}

		public DialogFlow PlayerRepeatableOption(TextObject text, ConversationSentence.OnMultipleConversationConsequenceDelegate listenerDelegate = null, string inputToken = null, string outputToken = null)
		{
			Option(text, byPlayer: true, null, listenerDelegate, isRepeatable: true, isSpecialOption: false, inputToken, outputToken);
			return this;
		}

		public DialogFlow NpcOption(string text, ConversationSentence.OnConditionDelegate conditionDelegate, ConversationSentence.OnMultipleConversationConsequenceDelegate speakerDelegate = null, ConversationSentence.OnMultipleConversationConsequenceDelegate listenerDelegate = null, string inputToken = null, string outputToken = null)
		{
			Option(new TextObject(text), byPlayer: false, speakerDelegate, listenerDelegate, isRepeatable: false, isSpecialOption: false, inputToken, outputToken);
			_lastLine.ConditionDelegate = conditionDelegate;
			return this;
		}

		public DialogFlow NpcOption(TextObject text, ConversationSentence.OnConditionDelegate conditionDelegate, ConversationSentence.OnMultipleConversationConsequenceDelegate speakerDelegate = null, ConversationSentence.OnMultipleConversationConsequenceDelegate listenerDelegate = null, string inputToken = null, string outputToken = null)
		{
			Option(text, byPlayer: false, speakerDelegate, listenerDelegate, isRepeatable: false, isSpecialOption: false, inputToken, outputToken);
			_lastLine.ConditionDelegate = conditionDelegate;
			return this;
		}

		public DialogFlow NpcOptionWithVariation(string text, ConversationSentence.OnConditionDelegate conditionDelegate, ConversationSentence.OnMultipleConversationConsequenceDelegate speakerDelegate = null, ConversationSentence.OnMultipleConversationConsequenceDelegate listenerDelegate = null, string inputToken = null, string outputToken = null)
		{
			NpcOptionWithVariation(new TextObject(text), conditionDelegate, speakerDelegate, listenerDelegate, inputToken, outputToken);
			return this;
		}

		public DialogFlow NpcOptionWithVariation(TextObject text, ConversationSentence.OnConditionDelegate conditionDelegate, ConversationSentence.OnMultipleConversationConsequenceDelegate speakerDelegate = null, ConversationSentence.OnMultipleConversationConsequenceDelegate listenerDelegate = null, string inputToken = null, string outputToken = null)
		{
			Option(TextObject.GetEmpty(), byPlayer: false, speakerDelegate, listenerDelegate, isRepeatable: false, isSpecialOption: false, inputToken, outputToken);
			List<GameTextManager.ChoiceTag> list = new List<GameTextManager.ChoiceTag>();
			list.Add(new GameTextManager.ChoiceTag("DefaultTag", 1));
			_lastLine.AddVariation(text, list);
			_lastLine.ConditionDelegate = conditionDelegate;
			return this;
		}

		private DialogFlow EndOptions(bool byPlayer)
		{
			_curDialogFlowContext = _curDialogFlowContext.Parent;
			return this;
		}

		public DialogFlow EndPlayerOptions()
		{
			return EndOptions(byPlayer: true);
		}

		public DialogFlow EndNpcOptions()
		{
			return EndOptions(byPlayer: false);
		}

		public DialogFlow Condition(ConversationSentence.OnConditionDelegate conditionDelegate)
		{
			_lastLine.ConditionDelegate = conditionDelegate;
			return this;
		}

		public DialogFlow ClickableCondition(ConversationSentence.OnClickableConditionDelegate clickableConditionDelegate)
		{
			_lastLine.ClickableConditionDelegate = clickableConditionDelegate;
			return this;
		}

		public DialogFlow Consequence(ConversationSentence.OnConsequenceDelegate consequenceDelegate)
		{
			_lastLine.ConsequenceDelegate = consequenceDelegate;
			return this;
		}

		public static DialogFlow CreateDialogFlow(string inputToken = null, int priority = 100)
		{
			return new DialogFlow(inputToken ?? Campaign.Current.ConversationManager.CreateToken(), priority);
		}

		private DialogFlowLine AddLine(TextObject text, string inputToken, string outputToken, bool byPlayer, ConversationSentence.OnMultipleConversationConsequenceDelegate speakerDelegate, ConversationSentence.OnMultipleConversationConsequenceDelegate listenerDelegate, bool isRepeatable, bool isSpecialOption = false, bool usedOncePerConversation = false)
		{
			DialogFlowLine dialogFlowLine = new DialogFlowLine();
			dialogFlowLine.Text = text;
			dialogFlowLine.InputToken = inputToken;
			dialogFlowLine.OutputToken = outputToken;
			dialogFlowLine.ByPlayer = byPlayer;
			dialogFlowLine.SpeakerDelegate = speakerDelegate;
			dialogFlowLine.ListenerDelegate = listenerDelegate;
			dialogFlowLine.IsRepeatable = isRepeatable;
			dialogFlowLine.IsSpecialOption = isSpecialOption;
			dialogFlowLine.IsUsedOnce = usedOncePerConversation;
			Lines.Add(dialogFlowLine);
			_lastLine = dialogFlowLine;
			return dialogFlowLine;
		}

		public DialogFlow NpcDefaultOption(string text)
		{
			return NpcOption(text, null);
		}

		public DialogFlow GenerateToken(out string token)
		{
			token = Campaign.Current.ConversationManager.CreateToken();
			return this;
		}

		public DialogFlow GotoDialogState(string input)
		{
			_lastLine.OutputToken = input;
			_currentToken = input;
			return this;
		}

		public DialogFlow GotoDialogStateBranched(string input, ConversationSentence.OnConditionDelegate conditionDelegate, string alternative)
		{
			string text = ((conditionDelegate != null && conditionDelegate()) ? input : alternative);
			_lastLine.OutputToken = text;
			_currentToken = text;
			return this;
		}

		public DialogFlow GetOutputToken(out string oState)
		{
			oState = _lastLine.OutputToken;
			return this;
		}

		public DialogFlow GoBackToDialogState(string iState)
		{
			_currentToken = iState;
			return this;
		}

		public DialogFlow CloseDialog()
		{
			GotoDialogState("close_window");
			return this;
		}

		private ConversationSentence AddDialogLine(ConversationSentence dialogLine)
		{
			Campaign.Current.ConversationManager.AddDialogLine(dialogLine);
			return dialogLine;
		}

		public ConversationSentence AddPlayerLine(string id, string inputToken, string outputToken, string text, ConversationSentence.OnConditionDelegate conditionDelegate, ConversationSentence.OnConsequenceDelegate consequenceDelegate, object relatedObject, int priority = 100, ConversationSentence.OnClickableConditionDelegate clickableConditionDelegate = null, ConversationSentence.OnPersuasionOptionDelegate persuasionOptionDelegate = null, ConversationSentence.OnMultipleConversationConsequenceDelegate speakerDelegate = null, ConversationSentence.OnMultipleConversationConsequenceDelegate listenerDelegate = null)
		{
			return AddDialogLine(new ConversationSentence(id, new TextObject(text), inputToken, outputToken, conditionDelegate, clickableConditionDelegate, consequenceDelegate, 1u, priority, 0, 0, relatedObject, withVariation: false, speakerDelegate, listenerDelegate, persuasionOptionDelegate));
		}

		public ConversationSentence AddDialogLine(string id, string inputToken, string outputToken, string text, ConversationSentence.OnConditionDelegate conditionDelegate, ConversationSentence.OnConsequenceDelegate consequenceDelegate, object relatedObject, int priority = 100, ConversationSentence.OnClickableConditionDelegate clickableConditionDelegate = null, ConversationSentence.OnMultipleConversationConsequenceDelegate speakerDelegate = null, ConversationSentence.OnMultipleConversationConsequenceDelegate listenerDelegate = null)
		{
			return AddDialogLine(new ConversationSentence(id, new TextObject(text), inputToken, outputToken, conditionDelegate, clickableConditionDelegate, consequenceDelegate, 0u, priority, 0, 0, relatedObject, withVariation: false, speakerDelegate, listenerDelegate));
		}
	}
	public static class EncounterManager
	{
		public static EncounterModel EncounterModel => Campaign.Current.Models.EncounterModel;

		public static void Tick(float dt)
		{
			HandleEncounters(dt);
		}

		private static void HandleEncounters(float dt)
		{
			if (Campaign.Current.TimeControlMode != 0)
			{
				for (int i = 0; i < Campaign.Current.MobileParties.Count; i++)
				{
					HandleEncounterForMobileParty(Campaign.Current.MobileParties[i], dt);
				}
			}
		}

		public static void HandleEncounterForMobileParty(MobileParty mobileParty, float dt)
		{
			if (!mobileParty.IsActive || mobileParty.AttachedTo != null || mobileParty.MapEventSide != null || (mobileParty.CurrentSettlement != null && !mobileParty.IsGarrison) || (mobileParty.BesiegedSettlement != null && mobileParty.ShortTermBehavior != AiBehavior.AssaultSettlement) || (!mobileParty.IsCurrentlyEngagingParty && !mobileParty.IsCurrentlyEngagingSettlement && (mobileParty.Ai.AiBehaviorInteractable == null || mobileParty.ShortTermBehavior != AiBehavior.GoToPoint || mobileParty.Ai.AiBehaviorInteractable is PartyBase { IsSettlement: not false } || mobileParty.Ai.AiBehaviorInteractable is PartyBase { IsMobile: not false } || (mobileParty.Party == PartyBase.MainParty && PlayerEncounter.Current != null))))
			{
				return;
			}
			if (PlayerEncounter.EncounteredMobileParty == mobileParty)
			{
				PlayerEncounter current = PlayerEncounter.Current;
				if (current == null || current.PlayerSide != 0)
				{
					return;
				}
			}
			if ((!mobileParty.IsCurrentlyEngagingSettlement || mobileParty.ShortTermTargetSettlement == null || mobileParty.ShortTermTargetSettlement != mobileParty.CurrentSettlement) && (!mobileParty.IsCurrentlyEngagingParty || (mobileParty.ShortTermTargetParty.IsActive && (mobileParty.ShortTermTargetParty.CurrentSettlement == null || (mobileParty.ShortTermTargetParty.MapEvent != null && (mobileParty.ShortTermTargetParty.MapEvent.GetLeaderParty(BattleSideEnum.Attacker).MapFaction == mobileParty.MapFaction || mobileParty.ShortTermTargetParty.MapEvent.GetLeaderParty(BattleSideEnum.Defender).MapFaction == mobileParty.MapFaction))))) && mobileParty.Ai.AiBehaviorInteractable.CanPartyInteract(mobileParty, dt))
			{
				mobileParty.Ai.AiBehaviorInteractable.OnPartyInteraction(mobileParty);
			}
		}

		public static void StartPartyEncounter(PartyBase attackerParty, PartyBase defenderParty)
		{
			bool flag = PartyBase.MainParty.MapEvent != null && (PartyBase.MainParty.MapEvent.InvolvedParties.Contains(attackerParty) || PartyBase.MainParty.MapEvent.InvolvedParties.Contains(defenderParty));
			if (defenderParty == PartyBase.MainParty && PlayerSiege.PlayerSiegeEvent != null)
			{
				TaleWorlds.Library.Debug.Print("\nPlayerSiege is interrupted\n", 0, TaleWorlds.Library.Debug.DebugColor.DarkGreen, 64uL);
			}
			if (attackerParty == PartyBase.MainParty || defenderParty == PartyBase.MainParty)
			{
				MapEvent mapEvent = PartyBase.MainParty.MapEvent;
				if (mapEvent != null && PlayerEncounter.IsActive && mapEvent.AttackerSide.TroopCount > 0 && mapEvent.DefenderSide.TroopCount > 0)
				{
					PlayerEncounter.Current.OnPartyJoinEncounter(attackerParty.MobileParty);
				}
				else if (((attackerParty == PartyBase.MainParty || defenderParty == PartyBase.MainParty) && !PlayerEncounter.IsActive) || (PlayerEncounter.EncounterSettlement != null && Settlement.CurrentSettlement != null && PlayerEncounter.EncounterSettlement == Settlement.CurrentSettlement))
				{
					RestartPlayerEncounter(attackerParty, defenderParty);
				}
			}
			else if (flag)
			{
				RestartPlayerEncounter(attackerParty, defenderParty);
			}
			else if (attackerParty.IsActive && defenderParty.IsActive && (attackerParty.MobileParty.Army == null || defenderParty != PartyBase.MainParty))
			{
				if (attackerParty.MapFaction == defenderParty.MapFaction)
				{
					attackerParty.MapEventSide = defenderParty.MapEventSide;
				}
				else
				{
					StartBattleAction.Apply(attackerParty, defenderParty);
				}
			}
			if (defenderParty.SiegeEvent != null && defenderParty != PartyBase.MainParty && defenderParty.SiegeEvent.BesiegerCamp != null && defenderParty.SiegeEvent.BesiegerCamp.HasInvolvedPartyForEventType(PartyBase.MainParty) && (MobileParty.MainParty.Army == null || MobileParty.MainParty.Army.LeaderParty == MobileParty.MainParty))
			{
				StartPartyEncounter(PartyBase.MainParty, attackerParty);
			}
			if (attackerParty != PartyBase.MainParty && attackerParty.MapEvent != null && attackerParty.MapEvent.IsSallyOut && attackerParty.MapEvent.MapEventSettlement == MobileParty.MainParty.CurrentSettlement && MobileParty.MainParty.Army == null)
			{
				GameMenu.SwitchToMenu("join_sally_out");
			}
		}

		public static void StartSettlementEncounter(MobileParty attackerParty, Settlement settlement)
		{
			if (attackerParty.DefaultBehavior == AiBehavior.BesiegeSettlement && attackerParty.TargetSettlement == settlement && attackerParty.ShortTermBehavior != AiBehavior.AssaultSettlement)
			{
				if (attackerParty.BesiegedSettlement == null)
				{
					if (settlement.SiegeEvent == null)
					{
						Campaign.Current.SiegeEventManager.StartSiegeEvent(settlement, attackerParty);
					}
					else
					{
						MapEventSide mapEventSide = settlement.SiegeEvent.BesiegerCamp.LeaderParty.MapEventSide;
						attackerParty.BesiegerCamp = settlement.SiegeEvent.BesiegerCamp;
						if (mapEventSide != null)
						{
							attackerParty.MapEventSide = mapEventSide;
						}
					}
				}
				if (settlement.Party.MapEvent == null)
				{
					return;
				}
			}
			if (attackerParty.DefaultBehavior == AiBehavior.DefendSettlement && attackerParty.IsCurrentlyAtSea && attackerParty.IsTargetingPort && settlement.SiegeEvent != null)
			{
				if (settlement.SiegeEvent.IsBlockadeActive)
				{
					if (settlement.SiegeEvent.BesiegerCamp.LeaderParty.MapEventSide == null)
					{
						BlockadeBattleMapEvent.CreateBlockadeBattleMapEvent(attackerParty.Party, settlement.SiegeEvent.BesiegerCamp.LeaderParty.Party, isSallyOut: false);
					}
					else
					{
						attackerParty.Party.MapEventSide = settlement.SiegeEvent.BesiegerCamp.LeaderParty.MapEventSide.OtherSide;
					}
					return;
				}
				if (settlement.Party.MapEvent != null)
				{
					EnterSettlementAction.ApplyForParty(attackerParty, settlement);
					attackerParty.Party.MapEventSide = settlement.Party.MapEventSide;
					return;
				}
			}
			if (!attackerParty.IsVillager && attackerParty != MobileParty.MainParty && settlement.IsVillage && settlement.Village.VillageState == Village.VillageStates.Looted)
			{
				attackerParty.SetMoveModeHold();
				return;
			}
			if (attackerParty == MobileParty.MainParty)
			{
				PlayerEncounter.Start();
				MapEvent mapEvent = settlement.Party.MapEvent;
				if (mapEvent != null && mapEvent.IsRaid && attackerParty.MapFaction.IsAtWarWith(settlement.MapFaction))
				{
					MBList<MapEventParty> mBList = mapEvent.DefenderSide.Parties.WhereQ((MapEventParty x) => x.Party.IsMobile && x.Party.MobileParty.IsLordParty && x.Party.MemberRoster.TotalHealthyCount > 0).ToMBList();
					if (mBList.AnyQ())
					{
						PartyBase party = mBList[0].Party;
						PartyBase leaderParty = mapEvent.GetLeaderParty(BattleSideEnum.Attacker);
						MBReadOnlyList<MapEventParty> mBReadOnlyList = mapEvent.PartiesOnSide(BattleSideEnum.Attacker);
						StartBattleAction.Apply(party, leaderParty);
						foreach (MapEventParty item in mBList)
						{
							if (item.Party != party)
							{
								item.Party.MapEventSide = party.MapEventSide;
							}
						}
						foreach (MapEventParty item2 in mBReadOnlyList)
						{
							if (item2.Party != leaderParty)
							{
								item2.Party.MapEventSide = leaderParty.MapEventSide;
							}
						}
						PlayerEncounter.Current.Init(leaderParty, party);
					}
					else
					{
						PlayerEncounter.Current.Init(attackerParty.Party, settlement.Party, settlement);
					}
				}
				else
				{
					PlayerEncounter.Current.Init(attackerParty.Party, settlement.Party, settlement);
				}
				return;
			}
			if (attackerParty.Aggressiveness > 0.01f && PartyBase.MainParty.MapEvent != null && PartyBase.MainParty.MapEvent.MapEventSettlement == settlement)
			{
				if (PlayerEncounter.IsActive)
				{
					if (attackerParty.MapFaction == MobileParty.MainParty.MapFaction || (PartyBase.MainParty.MapEvent.AttackerSide.LeaderParty != PartyBase.MainParty && PartyBase.MainParty.MapEvent.DefenderSide.LeaderParty != PartyBase.MainParty))
					{
						PlayerEncounter.Current.OnPartyJoinEncounter(attackerParty);
					}
					else
					{
						if (PlayerEncounter.IsActive)
						{
							PlayerEncounter.Finish();
						}
						RestartPlayerEncounter(attackerParty.Party, PartyBase.MainParty);
					}
				}
			}
			else
			{
				bool flag = MobileParty.MainParty.CurrentSettlement == settlement;
				MapEvent mapEvent2 = settlement.Party.MapEvent;
				if (mapEvent2 != null && !mapEvent2.IsFinalized && (mapEvent2.AttackerSide.MapFaction == attackerParty.MapFaction || mapEvent2.DefenderSide.MapFaction == attackerParty.MapFaction))
				{
					if (flag && attackerParty.AttachedTo == null)
					{
						PlayerEncounter.Finish();
					}
					settlement.Party.MapEventSide = ((mapEvent2.AttackerSide.MapFaction == attackerParty.MapFaction) ? mapEvent2.DefenderSide : mapEvent2.AttackerSide);
				}
				else if (settlement.Party.MapEvent == null && attackerParty != MobileParty.MainParty && attackerParty.ShortTermBehavior == AiBehavior.RaidSettlement && attackerParty.ShortTermTargetSettlement == settlement && FactionManager.IsAtWarAgainstFaction(attackerParty.MapFaction, settlement.MapFaction))
				{
					if (flag)
					{
						PlayerEncounter.Finish(forcePlayerOutFromSettlement: false);
					}
					if (settlement.SettlementHitPoints > 0.001f)
					{
						StartBattleAction.ApplyStartRaid(attackerParty, settlement);
					}
					if (flag)
					{
						if (MobileParty.MainParty.MapFaction == settlement.MapFaction)
						{
							PlayerEncounter.Start();
							PlayerEncounter.Current.Init(attackerParty.Party, settlement.Party, settlement);
						}
						else
						{
							LeaveSettlementAction.ApplyForParty(MobileParty.MainParty);
						}
					}
				}
				else if (attackerParty != MobileParty.MainParty && attackerParty.ShortTermBehavior == AiBehavior.AssaultSettlement && attackerParty.ShortTermTargetSettlement == settlement && FactionManager.IsAtWarAgainstFaction(attackerParty.MapFaction, settlement.MapFaction))
				{
					if (flag)
					{
						PlayerEncounter.Finish(forcePlayerOutFromSettlement: false);
					}
					bool flag2 = settlement.Party.MapEvent == null;
					StartBattleAction.ApplyStartAssaultAgainstWalls(attackerParty, settlement);
					if (attackerParty.MapEvent.DefenderSide.TroopCount == 0 && (PlayerSiege.PlayerSiegeEvent == null || PlayerSiege.PlayerSide != 0 || MobileParty.MainParty.CurrentSettlement != settlement))
					{
						bool num = MobileParty.MainParty.BesiegedSettlement == settlement;
						if (num && PlayerEncounter.Current == null)
						{
							StartSettlementEncounter((MobileParty.MainParty.Army != null) ? MobileParty.MainParty.Army.LeaderParty : MobileParty.MainParty, settlement);
							MobileParty.MainParty.MapEventSide = ((PlayerSiege.PlayerSide != 0) ? attackerParty.MapEventSide : attackerParty.MapEventSide.OtherSide);
						}
						attackerParty.MapEvent.SetOverrideWinner(BattleSideEnum.Attacker);
						attackerParty.MapEvent.FinalizeEvent();
						if (num)
						{
							GameMenu.SwitchToMenu("menu_settlement_taken");
						}
						return;
					}
					if (attackerParty.ShortTermBehavior == AiBehavior.AssaultSettlement && flag2 && attackerParty != MobileParty.MainParty && PlayerEncounter.Current != null && PlayerEncounter.EncounterSettlement == settlement && MobileParty.MainParty.CurrentSettlement == null)
					{
						PlayerEncounter.Finish();
					}
					if (MobileParty.MainParty.BesiegedSettlement == settlement && (MobileParty.MainParty.Army == null || MobileParty.MainParty.Army.LeaderParty == MobileParty.MainParty))
					{
						StartSettlementEncounter(MobileParty.MainParty, settlement);
					}
					else if (flag)
					{
						if (attackerParty.MapEvent.CanPartyJoinBattle(PartyBase.MainParty, settlement.BattleSide))
						{
							PlayerEncounter.Start();
							PlayerEncounter.Current.Init(attackerParty.Party, settlement.Party, settlement);
						}
						else
						{
							LeaveSettlementAction.ApplyForParty(MobileParty.MainParty);
						}
					}
				}
				else if (((attackerParty.ShortTermBehavior == AiBehavior.GoToSettlement || attackerParty.ShortTermBehavior == AiBehavior.FleeToGate) && attackerParty.ShortTermTargetSettlement == settlement) || attackerParty.Ai.IsDisabled || (attackerParty.Army != null && attackerParty.Army.LeaderParty.AttachedParties.Contains(attackerParty) && attackerParty.Army.LeaderParty.CurrentSettlement == settlement))
				{
					EnterSettlementAction.ApplyForParty(attackerParty, settlement);
				}
			}
			bool flag3 = attackerParty != null && (attackerParty.Army == null || attackerParty.Army.LeaderParty == attackerParty) && attackerParty.CurrentSettlement == settlement && !attackerParty.IsVillager && !attackerParty.IsMilitia && attackerParty != MobileParty.MainParty && attackerParty.MapEvent == null && settlement != null && settlement.IsVillage;
			if (attackerParty.Army != null && attackerParty.Army.LeaderParty == attackerParty && attackerParty != MobileParty.MainParty && !flag3)
			{
				foreach (MobileParty attachedParty in attackerParty.Army.LeaderParty.AttachedParties)
				{
					if (attachedParty.MapEvent == null)
					{
						StartSettlementEncounter(attachedParty, settlement);
					}
				}
			}
			if (flag3)
			{
				LeaveSettlementAction.ApplyForParty(attackerParty);
				attackerParty.SetMoveModeHold();
				if (attackerParty != MobileParty.MainParty && (MobileParty.MainParty.Army == null || attackerParty != MobileParty.MainParty.Army.LeaderParty))
				{
					attackerParty.Ai.RethinkAtNextHourlyTick = true;
				}
			}
		}

		private static void RestartPlayerEncounter(PartyBase attackerParty, PartyBase defenderParty)
		{
			Settlement settlement = null;
			bool interruptedWhileLooting = false;
			if (MobileParty.MainParty.MapEvent != null && MobileParty.MainParty.MapEvent.IsRaid)
			{
				settlement = MobileParty.MainParty.MapEvent.MapEventSettlement;
				interruptedWhileLooting = MobileParty.MainParty.MapEvent.WasEverInLootingPhase;
			}
			if (PlayerEncounter.Current != null && (PlayerEncounter.EncounteredParty != attackerParty || PartyBase.MainParty != defenderParty) && (PlayerEncounter.EncounteredParty != defenderParty || PartyBase.MainParty != attackerParty))
			{
				PlayerEncounter.Finish(forcePlayerOutFromSettlement: false);
			}
			if (PlayerEncounter.Current == null)
			{
				PlayerEncounter.Start();
			}
			if (attackerParty == PartyBase.MainParty && defenderParty.IsMobile && defenderParty.MobileParty.IsCurrentlyEngagingParty && defenderParty.MobileParty.ShortTermTargetParty == MobileParty.MainParty)
			{
				attackerParty = defenderParty;
				defenderParty = PartyBase.MainParty;
			}
			PlayerEncounter.Current.Init(attackerParty, defenderParty, settlement);
			PlayerEncounter.Current.InterruptedWhileLooting = interruptedWhileLooting;
		}
	}
	public struct ExplainedNumber
	{
		private class StatExplainer
		{
			public enum OperationType
			{
				Base,
				Add,
				Multiply,
				LimitMin,
				LimitMax
			}

			public readonly struct ExplanationLine
			{
				public readonly float Number;

				public readonly string Name;

				public readonly OperationType OperationType;

				public ExplanationLine(string name, float number, OperationType operationType)
				{
					Name = name;
					Number = number;
					OperationType = operationType;
				}
			}

			public List<ExplanationLine> Lines { get; private set; } = new List<ExplanationLine>();


			public ExplanationLine? BaseLine { get; private set; }

			public ExplanationLine? LimitMinLine { get; private set; }

			public ExplanationLine? LimitMaxLine { get; private set; }

			public List<(string name, float number)> GetLines(float baseNumber, float unclampedResultNumber, TextObject overrideBaseLineText = null, TextObject overrideMaximumLineText = null, TextObject overrideMinimumLineText = null)
			{
				List<(string, float)> list = new List<(string, float)>();
				if (BaseLine.HasValue)
				{
					list.Add(((overrideBaseLineText != null) ? overrideBaseLineText.ToString() : BaseLine.Value.Name, BaseLine.Value.Number));
				}
				foreach (ExplanationLine line in Lines)
				{
					float num = line.Number;
					if (line.OperationType == OperationType.Multiply)
					{
						num = baseNumber * num * 0.01f;
					}
					list.Add((line.Name, num));
				}
				if (LimitMinLine.HasValue && LimitMinLine.Value.Number > unclampedResultNumber)
				{
					list.Add(((overrideMinimumLineText != null) ? overrideMinimumLineText.ToString() : LimitMinLine.Value.Name, LimitMinLine.Value.Number - unclampedResultNumber));
				}
				if (LimitMaxLine.HasValue && LimitMaxLine.Value.Number < unclampedResultNumber)
				{
					list.Add(((overrideMaximumLineText != null) ? overrideMaximumLineText.ToString() : LimitMaxLine.Value.Name, LimitMaxLine.Value.Number - unclampedResultNumber));
				}
				return list;
			}

			public void AddLine(string name, float number, OperationType opType)
			{
				ExplanationLine explanationLine = new ExplanationLine(name, number, opType);
				switch (opType)
				{
				case OperationType.Add:
				case OperationType.Multiply:
				{
					int num = -1;
					for (int i = 0; i < Lines.Count; i++)
					{
						if (Lines[i].Name.Equals(name) && Lines[i].OperationType == opType)
						{
							num = i;
							break;
						}
					}
					if (num < 0)
					{
						Lines.Add(explanationLine);
						break;
					}
					explanationLine = new ExplanationLine(name, number + Lines[num].Number, opType);
					Lines[num] = explanationLine;
					break;
				}
				case OperationType.Base:
					BaseLine = explanationLine;
					break;
				case OperationType.LimitMin:
					LimitMinLine = explanationLine;
					break;
				case OperationType.LimitMax:
					LimitMaxLine = explanationLine;
					break;
				}
			}
		}

		private static readonly TextObject LimitMinText = new TextObject("{=GNalaRaN}Minimum");

		private static readonly TextObject LimitMaxText = new TextObject("{=cfjTtxWv}Maximum");

		private static readonly TextObject BaseText = new TextObject("{=basevalue}Base");

		private float? _limitMinValue;

		private float? _limitMaxValue;

		private StatExplainer _explainer;

		public float ResultNumber => TaleWorlds.Library.MathF.Clamp(_unclampedResultNumber, LimitMinValue, LimitMaxValue);

		public int RoundedResultNumber => TaleWorlds.Library.MathF.Round(ResultNumber);

		public float BaseNumber { get; private set; }

		public bool IncludeDescriptions => _explainer != null;

		public float LimitMinValue
		{
			get
			{
				if (!_limitMinValue.HasValue)
				{
					return float.MinValue;
				}
				return _limitMinValue.Value;
			}
		}

		public float LimitMaxValue
		{
			get
			{
				if (!_limitMaxValue.HasValue)
				{
					return float.MaxValue;
				}
				return _limitMaxValue.Value;
			}
		}

		public float SumOfFactors { get; private set; }

		private float _unclampedResultNumber => BaseNumber + BaseNumber * SumOfFactors;

		public ExplainedNumber(float baseNumber = 0f, bool includeDescriptions = false, TextObject baseText = null)
		{
			BaseNumber = baseNumber;
			_explainer = (includeDescriptions ? new StatExplainer() : null);
			SumOfFactors = 0f;
			_limitMinValue = float.MinValue;
			_limitMaxValue = float.MaxValue;
			if (_explainer != null && !BaseNumber.ApproximatelyEqualsTo(0f))
			{
				_explainer.AddLine((baseText ?? BaseText).ToString(), BaseNumber, StatExplainer.OperationType.Base);
			}
		}

		public string GetExplanations()
		{
			if (_explainer == null)
			{
				return "";
			}
			MBStringBuilder mBStringBuilder = default(MBStringBuilder);
			mBStringBuilder.Initialize(16, "GetExplanations");
			foreach (var line in _explainer.GetLines(BaseNumber, _unclampedResultNumber))
			{
				string value = string.Format("{0} : {1}{2:0.##}\n", line.name, (line.number > 0.001f) ? "+" : "", line.number);
				mBStringBuilder.Append(value);
			}
			return mBStringBuilder.ToStringAndRelease();
		}

		public List<(string name, float number)> GetLines()
		{
			if (_explainer == null)
			{
				return new List<(string, float)>();
			}
			return _explainer.GetLines(BaseNumber, _unclampedResultNumber);
		}

		public void AddFromExplainedNumber(ExplainedNumber explainedNumber, TextObject baseText)
		{
			if (explainedNumber._explainer != null && _explainer != null)
			{
				TextObject textObject = new TextObject("{=HKoLNyIm}{BASE} Maximum");
				TextObject textObject2 = new TextObject("{=0Fliz2vk}{BASE} Minimum");
				textObject.SetTextVariable("BASE", baseText);
				textObject2.SetTextVariable("BASE", baseText);
				foreach (var line in explainedNumber._explainer.GetLines(explainedNumber.BaseNumber, explainedNumber._unclampedResultNumber, baseText, textObject, textObject2))
				{
					_explainer.AddLine(line.name, line.number, StatExplainer.OperationType.Add);
				}
			}
			BaseNumber += explainedNumber.ResultNumber;
		}

		public void SubtractFromExplainedNumber(ExplainedNumber explainedNumber, TextObject baseText)
		{
			if (explainedNumber._explainer != null && _explainer != null)
			{
				TextObject textObject = new TextObject("{=HKoLNyIm}{BASE} Maximum");
				TextObject textObject2 = new TextObject("{=0Fliz2vk}{BASE} Minimum");
				textObject.SetTextVariable("BASE", baseText);
				textObject2.SetTextVariable("BASE", baseText);
				foreach (var line in explainedNumber._explainer.GetLines(explainedNumber.BaseNumber, explainedNumber._unclampedResultNumber, baseText, textObject, textObject2))
				{
					_explainer.AddLine(line.name, 0f - line.number, StatExplainer.OperationType.Add);
				}
			}
			BaseNumber -= explainedNumber.ResultNumber;
		}

		public void Add(float value, TextObject description = null, TextObject variable = null)
		{
			if (value.ApproximatelyEqualsTo(0f))
			{
				return;
			}
			BaseNumber += value;
			if (_explainer != null && description != null && !value.ApproximatelyEqualsTo(0f))
			{
				if (variable != null)
				{
					description.SetTextVariable("A0", variable);
				}
				_explainer.AddLine(description.ToString(), value, StatExplainer.OperationType.Add);
			}
		}

		public void AddFactor(float value, TextObject description = null)
		{
			if (!value.ApproximatelyEqualsTo(0f))
			{
				SumOfFactors += value;
				if (description != null && _explainer != null && !value.ApproximatelyEqualsTo(0f))
				{
					_explainer.AddLine(description.ToString(), TaleWorlds.Library.MathF.Round(value, 3) * 100f, StatExplainer.OperationType.Multiply);
				}
			}
		}

		public void LimitMin(float minValue)
		{
			_limitMinValue = minValue;
			if (_explainer != null)
			{
				_explainer.AddLine(LimitMinText.ToString(), minValue, StatExplainer.OperationType.LimitMin);
			}
		}

		public void LimitMax(float maxValue, TextObject description = null)
		{
			_limitMaxValue = maxValue;
			if (_explainer != null)
			{
				_explainer.AddLine((description ?? LimitMaxText).ToString(), maxValue, StatExplainer.OperationType.LimitMax);
			}
		}

		public void Clamp(float minValue, float maxValue)
		{
			LimitMin(minValue);
			LimitMax(maxValue);
		}
	}
