	public class DeclareDragonBannerSceneNotificationItem : SceneNotificationData
	{
		private const int NumberOfCharacters = 17;

		private readonly CampaignTime _creationCampaignTime;

		public bool PlayerWantsToRestore { get; }

		public override string SceneID => "scn_cutscene_declare_dragon_banner";

		public override TextObject TitleText
		{
			get
			{
				GameTexts.SetVariable("PLAYER_WANTS_RESTORE", PlayerWantsToRestore ? 1 : 0);
				GameTexts.SetVariable("DAY_OF_YEAR", CampaignSceneNotificationHelper.GetFormalDayAndSeasonText(_creationCampaignTime));
				GameTexts.SetVariable("YEAR", _creationCampaignTime.GetYear);
				return GameTexts.FindText("str_declare_dragon_banner");
			}
		}

		public override Banner[] GetBanners()
		{
			return new Banner[1] { Hero.MainHero.ClanBanner };
		}

		public override SceneNotificationCharacter[] GetSceneNotificationCharacters()
		{
			List<SceneNotificationCharacter> list = new List<SceneNotificationCharacter>();
			IOrderedEnumerable<Hero> clanHeroesPool = from h in Hero.MainHero.Clan.Heroes
				where !h.IsChild && h.IsAlive && h != Hero.MainHero
				orderby h.Level
				select h;
			for (int i = 0; i < 17; i++)
			{
				SceneNotificationCharacter characterAtIndex = GetCharacterAtIndex(i, clanHeroesPool);
				list.Add(characterAtIndex);
			}
			return list.ToArray();
		}

		public DeclareDragonBannerSceneNotificationItem(bool playerWantsToRestore)
		{
			PlayerWantsToRestore = playerWantsToRestore;
			_creationCampaignTime = CampaignTime.Now;
		}

		private SceneNotificationCharacter GetCharacterAtIndex(int index, IOrderedEnumerable<Hero> clanHeroesPool)
		{
			bool flag = false;
			int num = -1;
			string objectName = string.Empty;
			switch (index)
			{
			case 0:
				objectName = "battanian_picked_warrior";
				num = 0;
				break;
			case 1:
				objectName = "imperial_infantryman";
				break;
			case 2:
				objectName = "imperial_veteran_infantryman";
				break;
			case 3:
				objectName = "sturgian_warrior";
				num = 1;
				break;
			case 4:
				objectName = "imperial_menavliaton";
				break;
			case 5:
				objectName = "sturgian_ulfhednar";
				num = 2;
				break;
			case 6:
				objectName = "aserai_recruit";
				break;
			case 7:
				objectName = "aserai_skirmisher";
				break;
			case 8:
				objectName = "aserai_veteran_faris";
				break;
			case 9:
				objectName = "imperial_legionary";
				num = 3;
				break;
			case 10:
				objectName = "mountain_bandits_bandit";
				break;
			case 11:
				objectName = "mountain_bandits_chief";
				break;
			case 12:
				objectName = "forest_people_tier_3";
				num = 4;
				break;
			case 13:
				objectName = "mountain_bandits_raider";
				break;
			case 14:
				flag = true;
				break;
			case 15:
				objectName = "vlandian_pikeman";
				break;
			case 16:
				objectName = "vlandian_voulgier";
				break;
			}
			uint customColor = uint.MaxValue;
			uint customColor2 = uint.MaxValue;
			CharacterObject characterObject;
			if (flag)
			{
				characterObject = CharacterObject.PlayerCharacter;
				customColor = Hero.MainHero.MapFaction.Color;
				customColor2 = Hero.MainHero.MapFaction.Color2;
			}
			else if (num != -1 && clanHeroesPool.ElementAtOrDefault(num) != null)
			{
				Hero hero = clanHeroesPool.ElementAtOrDefault(num);
				characterObject = hero.CharacterObject;
				customColor = hero.MapFaction.Color;
				customColor2 = hero.MapFaction.Color2;
			}
			else
			{
				characterObject = MBObjectManager.Instance.GetObject<CharacterObject>(objectName);
			}
			Equipment equipment = characterObject.FirstBattleEquipment.Clone();
			CampaignSceneNotificationHelper.RemoveWeaponsFromEquipment(ref equipment, removeHelmet: true);
			return new SceneNotificationCharacter(characterObject, equipment, default(BodyProperties), useCivilianEquipment: false, customColor, customColor2);
		}
	}
	public class EmpireConspiracyBeginsSceneNotificationItem : SceneNotificationData
	{
		private const int AudienceNumber = 8;

		private readonly uint[] _audienceColors = new uint[4] { 4278914065u, 4284308292u, 4281543757u, 4282199842u };

		private readonly CampaignTime _creationCampaignTime;

		public Hero PlayerHero { get; }

		public Kingdom Empire { get; }

		public bool IsConspiracyAgainstEmpire { get; }

		public override string SceneID => "scn_empire_conspiracy_start_notification";

		public override TextObject TitleText
		{
			get
			{
				GameTexts.SetVariable("DAY_OF_YEAR", CampaignSceneNotificationHelper.GetFormalDayAndSeasonText(_creationCampaignTime));
				GameTexts.SetVariable("YEAR", _creationCampaignTime.GetYear);
				if (IsConspiracyAgainstEmpire)
				{
					return GameTexts.FindText("str_empire_conspiracy_begins_antiempire");
				}
				return GameTexts.FindText("str_empire_conspiracy_begins_proempire");
			}
		}

		public override Banner[] GetBanners()
		{
			return new Banner[1] { Empire.Banner };
		}

		public override SceneNotificationCharacter[] GetSceneNotificationCharacters()
		{
			List<SceneNotificationCharacter> list = new List<SceneNotificationCharacter>();
			for (int i = 0; i < 8; i++)
			{
				Equipment equipment = MBObjectManager.Instance.GetObject<MBEquipmentRoster>("conspirator_cutscene_template").DefaultEquipment.Clone();
				CampaignSceneNotificationHelper.RemoveWeaponsFromEquipment(ref equipment);
				CharacterObject facePropertiesFromAudienceIndex = GetFacePropertiesFromAudienceIndex(playerWantsRestore: false, i);
				BodyProperties bodyProperties = facePropertiesFromAudienceIndex.GetBodyProperties(equipment, MBRandom.RandomInt(100));
				uint customColor = _audienceColors[MBRandom.RandomInt(_audienceColors.Length)];
				uint customColor2 = _audienceColors[MBRandom.RandomInt(_audienceColors.Length)];
				list.Add(new SceneNotificationCharacter(facePropertiesFromAudienceIndex, equipment, bodyProperties, useCivilianEquipment: false, customColor, customColor2));
			}
			return list.ToArray();
		}

		public EmpireConspiracyBeginsSceneNotificationItem(Hero playerHero, Kingdom empire, bool isConspiracyAgainstEmpire)
		{
			PlayerHero = playerHero;
			Empire = empire;
			IsConspiracyAgainstEmpire = isConspiracyAgainstEmpire;
			_creationCampaignTime = CampaignTime.Now;
		}

		private CharacterObject GetFacePropertiesFromAudienceIndex(bool playerWantsRestore, int audienceMemberIndex)
		{
			if (!playerWantsRestore)
			{
				return MBObjectManager.Instance.GetObject<CharacterObject>("villager_empire");
			}
			string objectName = (audienceMemberIndex % 8) switch
			{
				0 => "villager_battania", 
				1 => "villager_khuzait", 
				2 => "villager_vlandia", 
				3 => "villager_aserai", 
				4 => "villager_battania", 
				5 => "villager_sturgia", 
				_ => "villager_battania", 
			};
			return MBObjectManager.Instance.GetObject<CharacterObject>(objectName);
		}
	}
	public abstract class EmpireConspiracySupportsSceneNotificationItemBase : SceneNotificationData
	{
