		private void SetCurrentStateAsInitial()
		{
			for (int i = 0; i < _rostersBackup.Length; i++)
			{
				_rostersBackup[i] = new ItemRoster(_rosters[i]);
			}
			_partyInitialEquipment = new PartyEquipment(OwnerParty);
			if (IsOtherPartyFromPlayerClan && LeftMemberRoster != null)
			{
				_otherPartyInitialEquipment = new PartyEquipment(OtherParty.MobileParty);
			}
		}

		public ItemRosterElement? FindItemFromSide(InventorySide side, EquipmentElement item)
		{
			int num = _rosters[(int)side].FindIndexOfElement(item);
			if (num >= 0)
			{
				return _rosters[(int)side].ElementAt(num);
			}
			return null;
		}
	}
	public class TransferCommandResult
	{
		public Equipment ResultSideEquipment => ResultSide switch
		{
			InventoryLogic.InventorySide.CivilianEquipment => TransferCharacter?.FirstCivilianEquipment, 
			InventoryLogic.InventorySide.BattleEquipment => TransferCharacter?.FirstBattleEquipment, 
			InventoryLogic.InventorySide.StealthEquipment => TransferCharacter?.FirstStealthEquipment, 
			_ => null, 
		};

		public CharacterObject TransferCharacter { get; private set; }

		public InventoryLogic.InventorySide ResultSide { get; private set; }

		public ItemRosterElement EffectedItemRosterElement { get; private set; }

		public int EffectedNumber { get; private set; }

		public int FinalNumber { get; private set; }

		public EquipmentIndex EffectedEquipmentIndex { get; private set; }

		public TransferCommandResult()
		{
		}

		public TransferCommandResult(InventoryLogic.InventorySide resultSide, ItemRosterElement effectedItemRosterElement, int effectedNumber, int finalNumber, EquipmentIndex effectedEquipmentIndex, CharacterObject transferCharacter)
		{
			ResultSide = resultSide;
			EffectedItemRosterElement = effectedItemRosterElement;
			EffectedNumber = effectedNumber;
			FinalNumber = finalNumber;
			EffectedEquipmentIndex = effectedEquipmentIndex;
			TransferCharacter = transferCharacter;
		}
	}
	public struct TransferCommand
	{
		public Equipment FromSideEquipment => FromSide switch
		{
			InventoryLogic.InventorySide.CivilianEquipment => Character?.FirstCivilianEquipment, 
			InventoryLogic.InventorySide.BattleEquipment => Character?.FirstBattleEquipment, 
			InventoryLogic.InventorySide.StealthEquipment => Character?.FirstStealthEquipment, 
			_ => null, 
		};

		public Equipment ToSideEquipment => ToSide switch
		{
			InventoryLogic.InventorySide.CivilianEquipment => Character?.FirstCivilianEquipment, 
			InventoryLogic.InventorySide.BattleEquipment => Character?.FirstBattleEquipment, 
			InventoryLogic.InventorySide.StealthEquipment => Character?.FirstStealthEquipment, 
			_ => null, 
		};

		public InventoryLogic.InventorySide FromSide { get; private set; }

		public InventoryLogic.InventorySide ToSide { get; private set; }

		public EquipmentIndex FromEquipmentIndex { get; private set; }

		public EquipmentIndex ToEquipmentIndex { get; private set; }

		public int Amount { get; private set; }

		public ItemRosterElement ElementToTransfer { get; private set; }

		public CharacterObject Character { get; private set; }

		public static TransferCommand Transfer(int amount, InventoryLogic.InventorySide fromSide, InventoryLogic.InventorySide toSide, ItemRosterElement elementToTransfer, EquipmentIndex fromEquipmentIndex, EquipmentIndex toEquipmentIndex, CharacterObject character)
		{
			TransferCommand result = default(TransferCommand);
			result.FromSide = fromSide;
			result.ToSide = toSide;
			result.ElementToTransfer = elementToTransfer;
			result.FromEquipmentIndex = fromEquipmentIndex;
			result.ToEquipmentIndex = toEquipmentIndex;
			result.Character = character;
			result.Amount = amount;
			return result;
		}
	}
