		[Flags]
		public enum IssueQuestFlags
		{
			None = 0,
			AvailableIssue = 1,
			ActiveIssue = 2,
			ActiveStoryQuest = 4,
			TrackedIssue = 8,
			TrackedStoryQuest = 0x10
		}

		public static IssueQuestFlags[] IssueQuestFlagsValues = (IssueQuestFlags[])Enum.GetValues(typeof(IssueQuestFlags));

		public OnConditionDelegate OnCondition;

		public OnConsequenceDelegate OnConsequence;

		public GameMenu.MenuAndOptionType Type { get; private set; }

		public LeaveType OptionLeaveType { get; set; }

		public IssueQuestFlags OptionQuestData { get; set; }

		public string IdString { get; private set; }

		public TextObject Text { get; private set; }

		public TextObject Text2 { get; private set; }

		public TextObject Tooltip { get; private set; }

		public bool IsLeave { get; private set; }

		public bool IsRepeatable { get; private set; }

		public bool IsEnabled { get; private set; }

		public object RelatedObject { get; private set; }

		internal GameMenuOption()
		{
			Text = null;
			Tooltip = null;
			IsEnabled = true;
		}

		public GameMenuOption(GameMenu.MenuAndOptionType type, string idString, TextObject text, TextObject text2, OnConditionDelegate condition, OnConsequenceDelegate consequence, bool isLeave = false, bool isRepeatable = false, object relatedObject = null)
		{
			Type = type;
			IdString = idString;
			Text = text;
			Text2 = text2;
			OnCondition = condition;
			OnConsequence = consequence;
			Tooltip = null;
			IsRepeatable = isRepeatable;
			IsEnabled = true;
			IsLeave = isLeave;
			RelatedObject = relatedObject;
		}

		public bool GetConditionsHold(Game game, MenuContext menuContext)
		{
			if (OnCondition != null)
			{
				MenuCallbackArgs menuCallbackArgs = new MenuCallbackArgs(menuContext, Text);
				bool result = OnCondition(menuCallbackArgs);
				IsEnabled = menuCallbackArgs.IsEnabled;
				Tooltip = menuCallbackArgs.Tooltip;
				OptionQuestData = menuCallbackArgs.OptionQuestData;
				OptionLeaveType = menuCallbackArgs.optionLeaveType;
				return result;
			}
			return true;
		}

		public void RunConsequence(MenuContext menuContext)
		{
			if (OnConsequence != null)
			{
				MenuCallbackArgs args = new MenuCallbackArgs(menuContext, Text);
				OnConsequence(args);
			}
			menuContext.OnConsequence(this);
		}

		public void SetEnable(bool isEnable)
		{
			IsEnabled = isEnable;
		}
	}
	public class MenuCallbackArgs
	{
		public float DeltaTime;

		public bool IsEnabled = true;

		public TextObject Text;

		public TextObject Tooltip;

		public GameMenuOption.IssueQuestFlags OptionQuestData;

		public GameMenuOption.LeaveType optionLeaveType;

		public TextObject MenuTitle;

		public MenuContext MenuContext { get; private set; }

		public MapState MapState { get; private set; }

		public MenuCallbackArgs(MenuContext menuContext, TextObject text)
		{
			MenuContext = menuContext;
			Text = text;
		}

		public MenuCallbackArgs(MapState mapState, TextObject text)
		{
			MapState = mapState;
			Text = text;
		}

		public MenuCallbackArgs(MapState mapState, TextObject text, float dt)
		{
			MapState = mapState;
			Text = text;
			DeltaTime = dt;
		}
	}
	public class WaitMenuOption
	{
		public delegate bool OnConditionDelegate(MenuCallbackArgs args);

		public delegate void OnConsequenceDelegate(MenuCallbackArgs args);

		private string _idString;

		private TextObject _text;

		private string _tooltip;

		private MethodInfo _methodOnCondition;

		public OnConditionDelegate OnCondition;

		private MethodInfo _methodOnConsequence;

		public OnConsequenceDelegate OnConsequence;

		private bool _isLeave;

		public int Priority { get; private set; }

		public TextObject Text => _text;

		public string IdString => _idString;

		public string Tooltip => _tooltip;

		public bool IsLeave => _isLeave;

		internal WaitMenuOption()
		{
			Priority = 100;
			_text = null;
			_tooltip = "";
		}

		internal WaitMenuOption(string idString, TextObject text, OnConditionDelegate condition, OnConsequenceDelegate consequence, int priority = 100, string tooltip = "")
		{
			_idString = idString;
			_text = text;
			OnCondition = condition;
			OnConsequence = consequence;
			Priority = priority;
			_tooltip = tooltip;
		}

		public bool GetConditionsHold(Game game, MapState mapState)
		{
			if (OnCondition != null)
			{
				MenuCallbackArgs args = new MenuCallbackArgs(mapState, Text);
				return OnCondition(args);
			}
			return true;
		}

		public void RunConsequence(Game game, MapState mapState)
		{
			if (OnConsequence != null)
			{
				MenuCallbackArgs args = new MenuCallbackArgs(mapState, Text);
				OnConsequence(args);
			}
		}

		public void Deserialize(XmlNode node, Type typeOfWaitMenusCallbacks)
		{
			if (node.Attributes == null)
			{
				throw new TWXmlLoadException("node.Attributes != null");
			}
			_idString = node.Attributes["id"].Value;
			XmlNode xmlNode = node.Attributes["text"];
			if (xmlNode != null)
			{
				_text = new TextObject(xmlNode.InnerText);
			}
			if (node.Attributes["is_leave"] != null)
			{
				_isLeave = true;
			}
			XmlNode xmlNode2 = node.Attributes["on_condition"];
			if (xmlNode2 != null)
			{
				string innerText = xmlNode2.InnerText;
				_methodOnCondition = typeOfWaitMenusCallbacks.GetMethod(innerText);
				if (_methodOnCondition == null)
				{
					throw new MBNotFoundException("Can not find WaitMenuOption condition:" + innerText);
				}
				OnCondition = (OnConditionDelegate)Delegate.CreateDelegate(typeof(OnConditionDelegate), null, _methodOnCondition);
			}
			XmlNode xmlNode3 = node.Attributes["on_consequence"];
			if (xmlNode3 != null)
			{
				string innerText2 = xmlNode3.InnerText;
				_methodOnConsequence = typeOfWaitMenusCallbacks.GetMethod(innerText2);
				if (_methodOnConsequence == null)
				{
					throw new MBNotFoundException("Can not find WaitMenuOption consequence:" + innerText2);
				}
				OnConsequence = (OnConsequenceDelegate)Delegate.CreateDelegate(typeof(OnConsequenceDelegate), null, _methodOnConsequence);
			}
		}
	}
}
