							MBTextManager.SetTextVariable("ENCOUNTER_TEXT", textObject6, sendClients: true);
						}
					}
					else
					{
						TaleWorlds.Library.Debug.FailedAssert("settlement encounter, but there is no MapEvent, menu text will be wrong", "C:\\BuildAgent\\work\\mb3\\Source\\Bannerlord\\TaleWorlds.CampaignSystem\\GameMenus\\GameMenuInitializationHandlers\\DefaultEncounter.cs", "game_menu_encounter_on_init", 327);
						TextObject textObject7 = GameTexts.FindText("str_you_have_encountered_settlement_to_siege");
						textObject7.SetTextVariable("SETTLEMENT", currentSettlement.Name);
