				}
			}
			else if (MobileParty.MainParty.MapEvent != null && !MobileParty.MainParty.MapEvent.IsSallyOut && PlayerEncounter.CheckIfLeadingAvaliable() && PlayerEncounter.GetLeadingHero() != Hero.MainHero)
