		{
			return 200;
		}

		public override float GetAllianceFactorForDeclaringWar(IFaction factionDeclaresWar, IFaction factionDeclaredWar)
		{
			if (factionDeclaresWar.IsKingdomFaction && factionDeclaredWar.IsKingdomFaction)
			{
				bool flag = false;
				float num = 1f;
				Kingdom kingdom = (Kingdom)factionDeclaresWar;
				Kingdom kingdom2 = (Kingdom)factionDeclaredWar;
				foreach (Kingdom alliedKingdom in kingdom.AlliedKingdoms)
				{
					if (alliedKingdom == kingdom2)
					{
						num *= 0.5f;
						break;
					}
					if (!flag && alliedKingdom.IsAtWarWith(kingdom2))
					{
						num = ((GetThreateningNeighbor(kingdom, out var _, out var _).threateningKingdom != kingdom2) ? (num * 1.3f) : (num * 1.5f));
						flag = true;
					}
				}
				return num;
			}
			return 1f;
		}

		public override float GetAllianceFactorForDeclaringPeace(IFaction factionDeclaresPeace, IFaction factionDeclaredPeace)
		{
			if (factionDeclaresPeace.IsKingdomFaction && factionDeclaredPeace.IsKingdomFaction)
			{
				float num = 1f;
				Kingdom obj = (Kingdom)factionDeclaresPeace;
				Kingdom other = (Kingdom)factionDeclaredPeace;
				foreach (Kingdom alliedKingdom in obj.AlliedKingdoms)
				{
					if (alliedKingdom.IsAtWarWith(other))
					{
						num *= 0.7f;
						break;
					}
				}
				return num;
			}
			return 1f;
		}

		public override Clan GetProposerClanForAllianceDecision(Kingdom proposerKingdom, Kingdom proposedKingdom)
		{
			TextObject explanation;
			Clan clan = ((proposerKingdom.RulingClan != Clan.PlayerClan && Campaign.Current.Models.AllianceModel.GetSupportScoreOfStartingAllianceForClan(proposerKingdom, proposedKingdom, proposerKingdom.RulingClan, out explanation) > 0f) ? proposerKingdom.RulingClan : null);
			if (clan == null)
			{
				List<(Clan, float)> list = new List<(Clan, float)>(proposerKingdom.Clans.Count);
				foreach (Clan clan2 in proposerKingdom.Clans)
				{
					if (!clan2.IsUnderMercenaryService && clan2 != Clan.PlayerClan)
					{
						float supportScoreOfStartingAllianceForClan = Campaign.Current.Models.AllianceModel.GetSupportScoreOfStartingAllianceForClan(proposerKingdom, proposedKingdom, clan2, out explanation);
						if (supportScoreOfStartingAllianceForClan > 0f)
						{
							list.Add((clan2, supportScoreOfStartingAllianceForClan));
						}
					}
				}
				clan = ((list.Count <= 0) ? ((proposerKingdom == Clan.PlayerClan.Kingdom) ? Clan.PlayerClan : proposerKingdom.RulingClan) : list.MaxBy<(Clan, float), float>(((Clan Clan, float Score) x) => x.Score).Item1);
			}
			return clan;
		}

		private (Kingdom threateningKingdom, float threatScore) GetThreateningNeighbor(Kingdom querierKingdom, out float exposureScore, out float powerRatio)
		{
			HashSet<Settlement> hashSet = new HashSet<Settlement>();
			Dictionary<Kingdom, float> dictionary = new Dictionary<Kingdom, float>();
			float num = 0f;
			foreach (Town fief in querierKingdom.Fiefs)
			{
				foreach (Settlement neighborFortification in fief.GetNeighborFortifications(MobileParty.NavigationType.All))
				{
					if (neighborFortification.MapFaction != querierKingdom && neighborFortification.MapFaction.IsKingdomFaction && !hashSet.Contains(neighborFortification))
					{
						Kingdom key = (Kingdom)neighborFortification.MapFaction;
						if (dictionary.ContainsKey(key))
						{
							dictionary[key] += 1f;
						}
						else
						{
							dictionary.Add(key, 1f);
						}
						num += 1f;
						hashSet.Add(neighborFortification);
					}
				}
			}
			float num2 = 0f;
			Kingdom item = null;
			exposureScore = 0f;
			powerRatio = 0f;
			foreach (KeyValuePair<Kingdom, float> item2 in dictionary)
			{
				float exposureScore2;
				float powerRatio2;
				float num3 = CalculateThreatScore(item2.Value, num, CalculateKingdomStrength(item2.Key), CalculateKingdomStrength(querierKingdom), out exposureScore2, out powerRatio2);
				if (num2 < num3)
				{
					item = item2.Key;
					num2 = num3;
					exposureScore = exposureScore2;
					powerRatio = powerRatio2;
				}
			}
			return (threateningKingdom: item, threatScore: num2);
		}

		private bool IsThereMarriageBetweenClans(Clan clan1, Clan clan2)
		{
			if (!clan1.AliveLords.AnyQ((Hero x) => x.Spouse?.Father?.Clan == clan2))
			{
				return clan2.AliveLords.AnyQ((Hero x) => x.Spouse?.Father?.Clan == clan1);
			}
			return true;
		}

		private TextObject BuildExplanationForAlliance(Kingdom other, List<(float, TextObject)> explanationList)
		{
			TextObject textObject = null;
			textObject = _kingdomNotConsederingAllianceText;
			List<TextObject> list = new List<TextObject>();
			foreach (var item2 in explanationList.OrderBy(((float, TextObject) x) => x.Item1))
			{
				TextObject item = item2.Item2;
				list.Add(item);
				if (list.Count >= 3)
				{
					break;
				}
			}
			TextObject variable = GameTexts.GameTextHelper.MergeTextObjectsWithSymbol(list, new TextObject("{=!}{newline}"));
			textObject.SetTextVariable("REASONS_BY_LINE", variable);
			textObject.SetTextVariable("KINGDOM", other.Name);
			return textObject;
		}

		private int GetCallToWarCostForCalledKingdom(Kingdom calledKingdom, Kingdom kingdomToCallToWarAgainst)
		{
			TextObject reason;
			float scoreOfDeclaringWar = Campaign.Current.Models.DiplomacyModel.GetScoreOfDeclaringWar(calledKingdom, kingdomToCallToWarAgainst, calledKingdom.RulingClan, out reason);
			float num = Campaign.Current.Models.DiplomacyModel.GetDecisionMakingThreshold(kingdomToCallToWarAgainst) - scoreOfDeclaringWar;
			if (num <= 0f)
			{
				return 0;
			}
			float valueOfSettlementsForFaction = Campaign.Current.Models.DiplomacyModel.GetValueOfSettlementsForFaction(calledKingdom);
			float num2 = num / (valueOfSettlementsForFaction + 1f);
			double num3 = (double)calledKingdom.Fiefs.SumQ((Town x) => x.Prosperity) * 0.35;
			return (int)((double)num2 * num3 * Campaign.Current.Models.AllianceModel.MaxDurationOfWarParticipation.ToDays);
		}

		private int GetCallToWarBudgetOfCallingKingdom(Kingdom callingKingdom, Kingdom calledKingdom, Kingdom kingdomToCallToWarAgainst)
		{
			float num = CalculateKingdomStrength(callingKingdom);
			float num2 = CalculateKingdomStrength(calledKingdom);
			float num3 = CalculateKingdomStrength(kingdomToCallToWarAgainst);
			double num4 = (double)callingKingdom.Fiefs.SumQ((Town x) => x.Prosperity) * 0.35;
			float num5 = num - num3;
			if (num5.ApproximatelyEqualsTo(0f))
			{
				return int.MinValue;
			}
			return (int)((double)TaleWorlds.Library.MathF.Clamp(0f - num2 / num5, float.MinValue, 1f) * num4 * Campaign.Current.Models.AllianceModel.MaxDurationOfWarParticipation.ToDays);
		}

		private bool AreKingdomsNeighbors(Kingdom kingdom1, Kingdom kingdom2)
		{
			if (kingdom1 == kingdom2 || kingdom1.Fiefs.Count == 0 || kingdom2.Fiefs.Count == 0)
			{
				return false;
			}
			foreach (Town fief in kingdom1.Fiefs)
			{
				foreach (Settlement neighborFortification in fief.GetNeighborFortifications(MobileParty.NavigationType.All))
				{
					if (neighborFortification.MapFaction == kingdom2)
					{
						return true;
					}
				}
			}
			return false;
		}

		private float CalculateThreatScore(float neighborScore, float totalNeighborScore, float powerOfThreat, float powerOfQuerier, out float exposureScore, out float powerRatio)
		{
			if (powerOfQuerier <= 0f || totalNeighborScore <= 0f)
			{
				exposureScore = 0f;
				powerRatio = 0f;
				return 0f;
			}
			exposureScore = MBMath.Map(neighborScore / totalNeighborScore, 0f, 1f, 1f, 2f);
			powerRatio = TaleWorlds.Library.MathF.Clamp(powerOfThreat / powerOfQuerier, 0f, 3f);
			return (TaleWorlds.Library.MathF.Min(exposureScore, 1.7f) + 0.4f + powerRatio) * 130f;
		}

		private float GetThreatEffect(float threatScoreForQuerier, float threatScoreForQueried)
		{
			return 0.08f * (threatScoreForQueried + threatScoreForQuerier) * 0.66f;
		}

		private float GetRelationshipEffect(Kingdom querierKingdom, Kingdom queriedKingdom)
		{
			if (querierKingdom.Leader != null && queriedKingdom.Leader != null)
			{
				int relation = querierKingdom.Leader.GetRelation(queriedKingdom.Leader);
				int traitLevel = querierKingdom.Leader.GetTraitLevel(DefaultTraits.Calculating);
				if (relation > 0 || traitLevel <= 0)
				{
					return TaleWorlds.Library.MathF.Clamp(relation, -100f, 100f) * 0.08f;
				}
			}
			return 0f;
		}

		private float GetMarriageEffect(Kingdom querierKingdom, Kingdom queriedKingdom)
		{
			if (IsThereMarriageBetweenClans(querierKingdom.RulingClan, queriedKingdom.RulingClan))
			{
				return 8f;
			}
			if (querierKingdom.Leader != null && queriedKingdom.RulingClan.AliveLords.AnyQ((Hero x) => x.Spouse?.Father?.MapFaction == queriedKingdom))
			{
				return 4f;
			}
			return 0f;
		}

		private float GetAtWarWithAllyEffect(Kingdom querierKingdom, Kingdom queriedKingdom)
		{
			return (queriedKingdom.FactionsAtWarWith.AnyQ((IFaction x) => x.IsKingdomFaction && querierKingdom.IsAllyWith((Kingdom)x)) ? (-100f) : 0f) * 0.08f;
		}

		private float GetAtWarWithEnemyEffect(Kingdom querierKingdom, Kingdom queriedKingdom)
		{
			return (queriedKingdom.FactionsAtWarWith.AnyQ((IFaction x) => x.IsKingdomFaction && querierKingdom.IsAtWarWith((Kingdom)x)) ? 100f : 0f) * 0.08f;
		}

		private float GetAtWarOrPeaceEffect(Kingdom queriedKingdom)
		{
			return (queriedKingdom.FactionsAtWarWith.AnyQ((IFaction x) => x.IsKingdomFaction) ? (-5f) : 25f) * 0.08f;
		}

		private float GetFiefWithSameCultureEffect(Kingdom querierKingdom, Kingdom queriedKingdom)
		{
			float num = queriedKingdom.Fiefs.Count;
			if (num > 0f)
			{
				return TaleWorlds.Library.MathF.Clamp((float)queriedKingdom.Fiefs.Count((Town fief) => fief.Culture == querierKingdom.Culture) / num * -200f, -200f, 0f) * 0.08f;
			}
			return 0f;
		}

		private float GetHonorableKingEffect(Kingdom querierKingdom, Kingdom queriedKingdom)
		{
			if (querierKingdom.Leader != null)
			{
				int traitLevel = querierKingdom.Leader.GetTraitLevel(DefaultTraits.Honor);
				int traitLevel2 = queriedKingdom.Leader.GetTraitLevel(DefaultTraits.Honor);
				if (traitLevel > 0)
				{
					return 4f;
				}
				if (traitLevel < 0 && traitLevel2 > 0)
				{
					return -4f;
				}
			}
			return 0f;
		}

		private float GetTradeAgreementEffect(Kingdom querierKingdom, Kingdom queriedKingdom)
		{
			ITradeAgreementsCampaignBehavior tradeAgreementsCampaignBehavior = TradeAgreementsCampaignBehavior;
			if (tradeAgreementsCampaignBehavior != null && tradeAgreementsCampaignBehavior.HasTradeAgreement(querierKingdom, queriedKingdom, out var _))
			{
				return 4f;
			}
			return 0f;
		}

		private float GetCommonThreatEffect(Kingdom threateningKingdomForQuerier, Kingdom threateningKingdomForQueried)
		{
			if (threateningKingdomForQuerier != null && threateningKingdomForQueried != null && threateningKingdomForQuerier == threateningKingdomForQueried)
			{
				return 8f;
			}
			return 0f;
		}

		private float GetAlliancePenalty(Kingdom kingdom)
		{
			if (kingdom.AlliedKingdoms.Count > 0)
			{
				float num = -48f;
				if (kingdom == Clan.PlayerClan.Kingdom)
				{
					num *= 0.5f;
				}
				return num;
			}
			return 0f;
		}

		private TextObject GetAlliancePenaltyText(Kingdom kingdom, bool includeDescription)
		{
			TextObject textObject = ((kingdom == Clan.PlayerClan.Kingdom) ? _tooManyAlliancePlayerPenaltyText : _tooManyAllianceAIPenaltyText);
			if (includeDescription)
			{
				textObject.SetTextVariable("NUMBER_OF_ALLIES", kingdom.AlliedKingdoms.Count);
				textObject.SetTextVariable("KINGDOM_NAME", kingdom.Name);
				textObject.SetTextVariable("MAX_NUMBER_OF_ALLIES", Campaign.Current.Models.AllianceModel.MaxNumberOfAlliances);
			}
			return textObject;
		}

		private bool CanMakeAllianceWithPlayerSupport(Kingdom proposingKingdom, Kingdom proposedKingdom, Clan evaluatingClan)
		{
			if (proposingKingdom == Clan.PlayerClan.Kingdom && evaluatingClan == Clan.PlayerClan)
			{
				return true;
			}
			KingdomElection kingdomElection = new KingdomElection(new StartAllianceDecision(evaluatingClan, proposedKingdom));
			DecisionOutcome supportedOutcome = kingdomElection.PossibleOutcomes.FirstOrDefault((DecisionOutcome x) => x is StartAllianceDecision.StartAllianceDecisionOutcome startAllianceDecisionOutcome && startAllianceDecisionOutcome.ShouldAllianceBeStarted);
			kingdomElection.SetupResultWithoutPlayerSupport();
			return kingdomElection.GetWinChanceWithPlayerSupport(supportedOutcome, Supporter.SupportWeights.FullyPush) > 0.5f;
		}

		private float CalculateKingdomStrength(Kingdom kingdom)
		{
			float num = 0f;
			foreach (Clan clan in kingdom.Clans)
			{
				if (!clan.IsUnderMercenaryService)
				{
					num += clan.CurrentTotalStrength;
				}
			}
			return num;
		}
	}
	public class DefaultArmyManagementCalculationModel : ArmyManagementCalculationModel
	{
		private const float MinimumInfluenceNeededToCreateArmy = 100f;

		private readonly TextObject _numberOfPartiesText = GameTexts.FindText("str_number_of_parties");

		private readonly TextObject _numberOfStarvingPartiesText = GameTexts.FindText("str_number_of_starving_parties");

		private readonly TextObject _numberOfLowMoralePartiesText = GameTexts.FindText("str_number_of_low_morale_parties");

		private readonly TextObject _numberOfLessMemberPartiesText = GameTexts.FindText("str_number_of_less_member_parties");

		public override float AIMobilePartySizeRatioToCallToArmy => 0.6f;

		public override float PlayerMobilePartySizeRatioToCallToArmy => 0.4f;

		public override float MinimumNeededFoodInDaysToCallToArmy => 15f;

		public override float MaximumDistanceToCallToArmy => Campaign.Current.GetAverageDistanceBetweenClosestTwoTownsWithNavigationType(MobileParty.NavigationType.All) * 8f;

		public override int InfluenceValuePerGold => 40;

		public override int AverageCallToArmyCost => 20;

		public override int CohesionThresholdForDispersion => 10;

		public override float MaximumWaitTime => (float)CampaignTime.HoursInDay * 3f;

		public override float DailyBeingAtArmyInfluenceAward(MobileParty armyMemberParty)
		{
			float num = (armyMemberParty.Party.EstimatedStrength + 20f) / 200f;
			if (PartyBaseHelper.HasFeat(armyMemberParty.Party, DefaultCulturalFeats.EmpireArmyInfluenceFeat))
			{
				num += num * DefaultCulturalFeats.EmpireArmyInfluenceFeat.EffectBonus;
			}
			return num;
		}

		public override int CalculatePartyInfluenceCost(MobileParty armyLeaderParty, MobileParty party)
		{
			if (armyLeaderParty.LeaderHero != null && party.LeaderHero != null && armyLeaderParty.LeaderHero.Clan == party.LeaderHero.Clan)
			{
				return 0;
			}
			float num = armyLeaderParty.LeaderHero.GetRelation(party.LeaderHero);
			float partySizeScore = GetPartySizeScore(party);
			float b = TaleWorlds.Library.MathF.Round(party.Party.EstimatedStrength);
			float num2 = (armyLeaderParty.IsMainParty ? Campaign.Current.Models.ArmyManagementCalculationModel.PlayerMobilePartySizeRatioToCallToArmy : Campaign.Current.Models.ArmyManagementCalculationModel.AIMobilePartySizeRatioToCallToArmy);
			float num3 = ((num < 0f) ? (1f + TaleWorlds.Library.MathF.Sqrt(TaleWorlds.Library.MathF.Abs(TaleWorlds.Library.MathF.Max(-100f, num))) / 10f) : (1f - TaleWorlds.Library.MathF.Sqrt(TaleWorlds.Library.MathF.Abs(TaleWorlds.Library.MathF.Min(100f, num))) / 20f));
			float num4 = 0.5f + TaleWorlds.Library.MathF.Min(1000f, b) / 100f;
			float num5 = 0.5f + 1f * (1f - (partySizeScore - num2) / (1f - num2));
			float landRatio;
			float distanceBetweenMobilePartyToMobileParty = DistanceHelper.GetDistanceBetweenMobilePartyToMobileParty(party, armyLeaderParty, party.NavigationCapability, out landRatio);
			float num6 = 1f + 1f * TaleWorlds.Library.MathF.Pow(TaleWorlds.Library.MathF.Min(Campaign.MapDiagonal * 10f, TaleWorlds.Library.MathF.Max(1f, distanceBetweenMobilePartyToMobileParty)) / Campaign.MapDiagonal, 0.67f);
			float num7 = ((party.LeaderHero != null) ? party.LeaderHero.RandomFloat(0.75f, 1.25f) : 1f);
			float num8 = 1f;
			float num9 = 1f;
			float num10 = 1f;
			if (armyLeaderParty.LeaderHero?.Clan.Kingdom != null)
			{
				if (armyLeaderParty.LeaderHero.Clan.Tier >= 5 && armyLeaderParty.LeaderHero.Clan.Kingdom.ActivePolicies.Contains(DefaultPolicies.Marshals))
				{
					num8 -= 0.1f;
				}
				if (armyLeaderParty.LeaderHero.Clan.Kingdom.ActivePolicies.Contains(DefaultPolicies.RoyalCommissions))
				{
					num8 = ((armyLeaderParty.LeaderHero != armyLeaderParty.LeaderHero.Clan.Kingdom.Leader) ? (num8 + 0.1f) : (num8 - 0.3f));
				}
				if (party.LeaderHero != null)
				{
					if (armyLeaderParty.LeaderHero.Clan.Kingdom.ActivePolicies.Contains(DefaultPolicies.LordsPrivyCouncil) && party.LeaderHero.Clan.Tier <= 4)
					{
						num8 += 0.2f;
					}
					if (armyLeaderParty.LeaderHero.Clan.Kingdom.ActivePolicies.Contains(DefaultPolicies.Senate) && party.LeaderHero.Clan.Tier <= 2)
					{
						num8 += 0.1f;
					}
				}
				if (armyLeaderParty.LeaderHero.GetPerkValue(DefaultPerks.Leadership.InspiringLeader))
				{
					num9 += DefaultPerks.Leadership.InspiringLeader.PrimaryBonus;
				}
				if (armyLeaderParty.LeaderHero.GetPerkValue(DefaultPerks.Tactics.CallToArms))
				{
					num9 += DefaultPerks.Tactics.CallToArms.SecondaryBonus;
				}
			}
			if (PartyBaseHelper.HasFeat(armyLeaderParty.Party, DefaultCulturalFeats.VlandianArmyInfluenceFeat))
			{
				num10 += DefaultCulturalFeats.VlandianArmyInfluenceFeat.EffectBonus;
			}
			if (PartyBaseHelper.HasFeat(armyLeaderParty.Party, DefaultCulturalFeats.SturgianArmyInfluenceCostFeat))
			{
				num10 += DefaultCulturalFeats.SturgianArmyInfluenceCostFeat.EffectBonus;
			}
			return (int)(0.65f * num3 * num4 * num7 * num6 * num5 * num8 * num9 * num10 * (float)AverageCallToArmyCost);
		}

		public override bool CanLordCreateArmy(MobileParty mobileParty, out MBList<MobileParty> possibleArmyMembers)
		{
			possibleArmyMembers = new MBList<MobileParty>();
			Kingdom kingdom = mobileParty.MapFaction as Kingdom;
			if (!mobileParty.IsCurrentlyAtSea && mobileParty.LeaderHero.Clan.Influence > 100f && !mobileParty.LeaderHero.Clan.IsUnderMercenaryService && (float)mobileParty.GetNumDaysForFoodToLast() > Campaign.Current.Models.MobilePartyAIModel.NeededFoodsInDaysThresholdForSiege && kingdom.FactionsAtWarWith.AnyQ((IFaction x) => x.Fiefs.Any()) && mobileParty.PartySizeRatio > Campaign.Current.Models.ArmyManagementCalculationModel.AIMobilePartySizeRatioToCallToArmy && (mobileParty.LeaderHero.Clan.Leader == mobileParty.LeaderHero || (mobileParty.LeaderHero.Clan.Leader.PartyBelongedTo == null && mobileParty.LeaderHero.Clan.WarPartyComponents != null && mobileParty.LeaderHero.Clan.WarPartyComponents.FirstOrDefault() == mobileParty.WarPartyComponent)))
			{
				GetInfluenceBudgetWhileCreatingArmy(mobileParty);
				List<(MobileParty, float, int)> list = new List<(MobileParty, float, int)>();
				foreach (WarPartyComponent warPartyComponent in mobileParty.MapFaction.WarPartyComponents)
				{
					MobileParty mobileParty2 = warPartyComponent.MobileParty;
					Hero leaderHero = mobileParty2.LeaderHero;
					if (!mobileParty2.IsLordParty || mobileParty2.Army != null || mobileParty2 == mobileParty || leaderHero == null || mobileParty2.IsMainParty || leaderHero == leaderHero.MapFaction.Leader || mobileParty2.Ai.DoNotMakeNewDecisions || mobileParty2.CurrentSettlement?.SiegeEvent != null || mobileParty2.IsDisbanding || !((float)mobileParty2.GetNumDaysForFoodToLast() > Campaign.Current.Models.ArmyManagementCalculationModel.MinimumNeededFoodInDaysToCallToArmy) || !(mobileParty2.PartySizeRatio > Campaign.Current.Models.ArmyManagementCalculationModel.AIMobilePartySizeRatioToCallToArmy) || !leaderHero.CanLeadParty() || mobileParty2.IsInRaftState || mobileParty2.MapEvent != null || mobileParty2.BesiegedSettlement != null)
					{
						continue;
					}
					IDisbandPartyCampaignBehavior campaignBehavior = Campaign.Current.GetCampaignBehavior<IDisbandPartyCampaignBehavior>();
					if (campaignBehavior != null && campaignBehavior.IsPartyWaitingForDisband(mobileParty2))
					{
						continue;
					}
					float maximumDistanceToCallToArmy = Campaign.Current.Models.ArmyManagementCalculationModel.MaximumDistanceToCallToArmy;
					if (!(DistanceHelper.GetDistanceBetweenMobilePartyToMobileParty(mobileParty2, mobileParty, mobileParty2.NavigationCapability, out var _) < maximumDistanceToCallToArmy))
					{
						continue;
					}
					bool flag = false;
					foreach (var item2 in list)
					{
						if (item2.Item1 == mobileParty2)
						{
							flag = true;
							break;
						}
					}
					if (!flag)
					{
						int num = Campaign.Current.Models.ArmyManagementCalculationModel.CalculatePartyInfluenceCost(mobileParty, mobileParty2);
						float estimatedStrength = mobileParty2.Party.EstimatedStrength;
						float num2 = 1f - (float)mobileParty2.Party.MemberRoster.TotalWounded / (float)mobileParty2.Party.MemberRoster.TotalManCount;
						float item = estimatedStrength / ((float)num + 0.1f) * num2;
						list.Add((mobileParty2, item, num));
					}
				}
				list = list.OrderByQ(((MobileParty, float, int) x) => x.Item2).ToListQ();
				int count = kingdom.WarPartyComponents.Count;
				int num3 = kingdom.Armies.SumQ((Army x) => x.Parties.Count);
				int num4 = TaleWorlds.Library.MathF.Ceiling((float)count * 0.7f - (float)num3);
				if (num4 > 0)
				{
					if (num4 < list.Count)
					{
						list.RemoveRange(num4, list.Count - num4);
					}
					possibleArmyMembers = list.SelectQ(((MobileParty, float, int) x) => x.Item1).ToMBList();
					if (possibleArmyMembers.AnyQ())
					{
						if (kingdom.Settlements.Count == 0)
						{
							return true;
						}
						float num5 = mobileParty.Party.GetCustomStrength(BattleSideEnum.Attacker, MapEvent.PowerCalculationContext.Siege);
						foreach (MobileParty possibleArmyMember in possibleArmyMembers)
						{
							num5 += possibleArmyMember.Party.GetCustomStrength(BattleSideEnum.Attacker, MapEvent.PowerCalculationContext.Siege);
						}
						if (num5 < 1000f)
						{
							possibleArmyMembers.Clear();
							return false;
						}
						return true;
					}
				}
			}
			return false;
		}

		public override int CalculateTotalInfluenceCost(Army army, float percentage)
		{
			int num = CalculateTotalInfluenceCostInternal(army, percentage);
			if (army != MobileParty.MainParty.Army)
			{
				num = (int)((float)num * 0.25f);
			}
			return num;
		}

		private int CalculateTotalInfluenceCostInternal(Army army, float percentage)
		{
			int num = 0;
			foreach (MobileParty item in army.Parties.Where((MobileParty p) => !p.IsMainParty))
			{
				num += CalculatePartyInfluenceCost(army.LeaderParty, item);
			}
			ExplainedNumber explainedNumber = new ExplainedNumber(num);
			if (army.LeaderParty.MapFaction.IsKingdomFaction && ((Kingdom)army.LeaderParty.MapFaction).ActivePolicies.Contains(DefaultPolicies.RoyalCommissions))
			{
				explainedNumber.AddFactor(-0.3f, DefaultPolicies.RoyalCommissions.Name);
			}
			if (army.LeaderParty.LeaderHero.GetPerkValue(DefaultPerks.Tactics.Encirclement))
			{
				explainedNumber.AddFactor(DefaultPerks.Tactics.Encirclement.SecondaryBonus);
			}
			return TaleWorlds.Library.MathF.Ceiling(explainedNumber.ResultNumber * percentage / 100f);
		}

