		private const int PartyGoldIncomeThreshold = 10000;

		private const int payGarrisonWagesTreshold = 8000;

		private const int payClanPartiesTreshold = 4000;

		private const int payLeaderPartyWageTreshold = 2000;

		private ITradeAgreementsCampaignBehavior TradeAgreementsBehavior
		{
			get
			{
				if (_tradeAgreementsCampaignBehavior == null)
				{
					_tradeAgreementsCampaignBehavior = Campaign.Current.GetCampaignBehavior<ITradeAgreementsCampaignBehavior>();
				}
				return _tradeAgreementsCampaignBehavior;
			}
		}

		public override int PartyGoldLowerThreshold => 5000;

		public override ExplainedNumber CalculateClanGoldChange(Clan clan, bool includeDescriptions = false, bool applyWithdrawals = false, bool includeDetails = false)
		{
			ExplainedNumber goldChange = new ExplainedNumber(0f, includeDescriptions);
			CalculateClanIncomeInternal(clan, ref goldChange, applyWithdrawals, includeDetails);
			CalculateClanExpensesInternal(clan, ref goldChange, applyWithdrawals, includeDetails);
			return goldChange;
		}

		public override ExplainedNumber CalculateClanIncome(Clan clan, bool includeDescriptions = false, bool applyWithdrawals = false, bool includeDetails = false)
		{
			ExplainedNumber goldChange = new ExplainedNumber(0f, includeDescriptions);
			CalculateClanIncomeInternal(clan, ref goldChange, applyWithdrawals, includeDetails);
			return goldChange;
		}

		private void CalculateClanIncomeInternal(Clan clan, ref ExplainedNumber goldChange, bool applyWithdrawals = false, bool includeDetails = false)
		{
			if (clan.IsEliminated)
			{
				return;
			}
			if (clan.Kingdom?.RulingClan == clan)
			{
				AddRulingClanIncome(clan, ref goldChange, applyWithdrawals, includeDetails);
			}
			if (clan != Clan.PlayerClan && (!clan.MapFaction.IsKingdomFaction || clan.IsUnderMercenaryService) && clan.Fiefs.Count == 0)
			{
				int num = clan.Tier * (80 + (clan.IsUnderMercenaryService ? 40 : 0));
				goldChange.Add(num);
			}
			AddMercenaryIncome(clan, ref goldChange, applyWithdrawals);
			AddSettlementIncome(clan, ref goldChange, applyWithdrawals, includeDetails);
			CalculateHeroIncomeFromWorkshops(clan.Leader, ref goldChange, applyWithdrawals);
			AddIncomeFromParties(clan, ref goldChange, applyWithdrawals, includeDetails);
			if (clan == Clan.PlayerClan)
			{
				AddPlayerClanIncomeFromOwnedAlleys(ref goldChange);
			}
			if (!clan.IsUnderMercenaryService)
			{
				AddIncomeFromTribute(clan, ref goldChange, applyWithdrawals, includeDetails);
				AddIncomeFromCallToWarAgrements(clan, ref goldChange, applyWithdrawals);
				if (clan.Kingdom != null && TradeAgreementsBehavior != null)
				{
					AddIncomeFromTradeAgreements(clan, ref goldChange, applyWithdrawals, includeDetails);
				}
			}
			if (clan.Gold < 30000 && clan.Kingdom != null && clan.Leader != Hero.MainHero && !clan.IsUnderMercenaryService)
			{
				AddIncomeFromKingdomBudget(clan, ref goldChange, applyWithdrawals);
			}
			Hero leader = clan.Leader;
			if (leader != null && leader.GetPerkValue(DefaultPerks.Trade.SpringOfGold))
			{
				int num2 = TaleWorlds.Library.MathF.Min(1000, TaleWorlds.Library.MathF.Round((float)clan.Leader.Gold * DefaultPerks.Trade.SpringOfGold.PrimaryBonus));
				goldChange.Add(num2, DefaultPerks.Trade.SpringOfGold.Name);
			}
		}

		public void CalculateClanExpensesInternal(Clan clan, ref ExplainedNumber goldChange, bool applyWithdrawals = false, bool includeDetails = false)
		{
			AddExpensesFromPartiesAndGarrisons(clan, ref goldChange, applyWithdrawals, includeDetails);
			if (!clan.IsUnderMercenaryService)
			{
				AddExpensesForHiredMercenaries(clan, ref goldChange, applyWithdrawals);
				AddExpensesForTributes(clan, ref goldChange, applyWithdrawals);
			}
			AddExpensesForAutoRecruitment(clan, ref goldChange, applyWithdrawals);
			if (clan.Gold > 100000 && clan.Kingdom != null && clan.Leader != Hero.MainHero && !clan.IsUnderMercenaryService)
			{
				int num = (int)(((float)clan.Gold - 100000f) * 0.01f);
				if (applyWithdrawals)
				{
					clan.Kingdom.KingdomBudgetWallet += num;
				}
				goldChange.Add(-num, _kingdomBudgetText);
			}
			if (clan.DebtToKingdom > 0)
			{
				AddPaymentForDebts(clan, ref goldChange, applyWithdrawals);
			}
			if (Clan.PlayerClan == clan)
			{
				AddPlayerExpenseForWorkshops(ref goldChange);
			}
			if (!clan.IsUnderMercenaryService)
			{
				AddExpensesForCallToWarAgreements(clan, ref goldChange, applyWithdrawals);
			}
		}

		private void AddPlayerExpenseForWorkshops(ref ExplainedNumber goldChange)
		{
			int num = 0;
			foreach (Workshop ownedWorkshop in Hero.MainHero.OwnedWorkshops)
			{
				if (ownedWorkshop.Capital < Campaign.Current.Models.WorkshopModel.CapitalLowLimit)
				{
					num -= ownedWorkshop.Expense;
				}
			}
			goldChange.Add(num, _shopExpenseText);
		}

		public override ExplainedNumber CalculateClanExpenses(Clan clan, bool includeDescriptions = false, bool applyWithdrawals = false, bool includeDetails = false)
		{
			ExplainedNumber goldChange = new ExplainedNumber(0f, includeDescriptions);
			CalculateClanExpensesInternal(clan, ref goldChange, applyWithdrawals, includeDetails);
			return goldChange;
		}

		private void AddPaymentForDebts(Clan clan, ref ExplainedNumber goldChange, bool applyWithdrawals)
		{
			if (clan.Kingdom != null && clan.DebtToKingdom > 0)
			{
				int num = clan.DebtToKingdom;
				if (applyWithdrawals)
				{
					num = TaleWorlds.Library.MathF.Min(num, (int)((float)clan.Gold + goldChange.ResultNumber));
					clan.DebtToKingdom -= num;
				}
				goldChange.Add(-num, _debtText);
			}
		}

		private void AddRulingClanIncome(Clan clan, ref ExplainedNumber goldChange, bool applyWithdrawals, bool includeDetails)
		{
			ExplainedNumber explainedNumber = new ExplainedNumber(0f, goldChange.IncludeDescriptions);
			Kingdom kingdom = clan.Kingdom;
			if (kingdom.ActivePolicies.Contains(DefaultPolicies.LandTax))
			{
				float num = 0f;
				foreach (Village village in kingdom.Villages)
				{
					if (!village.IsOwnerUnassigned && village.Settlement.OwnerClan != clan && village.VillageState != Village.VillageStates.Looted && village.VillageState != Village.VillageStates.BeingRaided)
					{
						int num2 = (int)((float)village.TradeTaxAccumulated / RevenueSmoothenFraction());
						num += (float)num2 * 0.05f;
					}
				}
				if (num > 1E-05f)
				{
					explainedNumber.Add((int)num, DefaultPolicies.LandTax.Name);
				}
			}
			if (kingdom.ActivePolicies.Contains(DefaultPolicies.WarTax))
			{
				float num3 = 0f;
				foreach (Town fief in kingdom.Fiefs)
				{
					num3 += Campaign.Current.Models.SettlementTaxModel.CalculateTownTax(fief).ResultNumber;
				}
				int num4 = (int)(num3 * 0.05f);
				explainedNumber.Add(num4, DefaultPolicies.WarTax.Name);
			}
			if (kingdom.ActivePolicies.Contains(DefaultPolicies.CrownDuty))
			{
				foreach (Town fief2 in kingdom.Fiefs)
				{
					int num5 = (int)((float)fief2.TradeTaxAccumulated * 0.05f);
					explainedNumber.Add(num5, DefaultPolicies.CrownDuty.Name);
					if (applyWithdrawals)
					{
						fief2.TradeTaxAccumulated -= num5;
					}
				}
			}
			if (kingdom.ActivePolicies.Contains(DefaultPolicies.DebasementOfTheCurrency))
			{
				int count = kingdom.Fiefs.Count;
				explainedNumber.Add(count * 100, DefaultPolicies.DebasementOfTheCurrency.Name);
			}
			int num6 = 0;
			int num7 = 0;
			foreach (Settlement settlement in clan.Settlements)
			{
				if (!settlement.IsTown)
				{
					continue;
				}
				if (kingdom.ActivePolicies.Contains(DefaultPolicies.RoadTolls))
				{
					int num8 = settlement.Town.TradeTaxAccumulated / 30;
					if (applyWithdrawals)
					{
						settlement.Town.TradeTaxAccumulated -= num8;
					}
					num6 += num8;
				}
				if (kingdom.ActivePolicies.Contains(DefaultPolicies.StateMonopolies))
				{
					num7 += (int)((float)settlement.Town.Workshops.Sum((Workshop t) => t.ProfitMade) * 0.05f);
				}
				if (num6 > 0)
				{
					explainedNumber.Add(num6, DefaultPolicies.RoadTolls.Name);
				}
				if (num7 > 0)
				{
					explainedNumber.Add(num7, DefaultPolicies.StateMonopolies.Name);
				}
			}
			if (!explainedNumber.ResultNumber.ApproximatelyEqualsTo(0f))
			{
				if (!includeDetails)
				{
					goldChange.Add(explainedNumber.ResultNumber, GameTexts.FindText("str_policies"));
				}
				else
				{
					goldChange.AddFromExplainedNumber(explainedNumber, GameTexts.FindText("str_policies"));
				}
			}
		}

		private void AddExpensesForHiredMercenaries(Clan clan, ref ExplainedNumber goldChange, bool applyWithdrawals)
		{
			Kingdom kingdom = clan.Kingdom;
			if (kingdom == null)
			{
				return;
			}
			float num = CalculateShareFactor(clan);
			if (kingdom.MercenaryWallet < 0)
			{
				int num2 = (int)((float)(-kingdom.MercenaryWallet) * num);
				ApplyShareForExpenses(clan, ref goldChange, applyWithdrawals, num2, _mercenaryExpensesText);
				if (applyWithdrawals)
				{
					kingdom.MercenaryWallet += num2;
				}
			}
		}

		private void AddExpensesForTributes(Clan clan, ref ExplainedNumber goldChange, bool applyWithdrawals)
		{
			Kingdom kingdom = clan.Kingdom;
			if (kingdom == null)
			{
				return;
			}
			float num = CalculateShareFactor(clan);
			if (kingdom.TributeWallet < 0)
			{
				int num2 = (int)((float)(-kingdom.TributeWallet) * num);
				ApplyShareForExpenses(clan, ref goldChange, applyWithdrawals, num2, _tributeExpensesText);
				if (applyWithdrawals)
				{
					kingdom.TributeWallet += num2;
				}
			}
		}

		private void AddExpensesForCallToWarAgreements(Clan clan, ref ExplainedNumber goldChange, bool applyWithdrawals)
		{
			Kingdom kingdom = clan.Kingdom;
			if (kingdom != null && kingdom.CallToWarWallet < 0)
			{
				float num = CalculateShareFactor(clan);
				int num2 = (int)((float)(-kingdom.CallToWarWallet) * num);
				int num3 = num2;
				int num4 = (int)((float)clan.Gold + goldChange.ResultNumber);
				if (applyWithdrawals && num4 - num3 < 5000)
				{
					num3 = TaleWorlds.Library.MathF.Max(0, num4 - 5000);
					clan.DebtToKingdom += num2 - num3;
				}
				ApplyShareForExpenses(clan, ref goldChange, applyWithdrawals, num3, _callToWarExpenses);
				if (applyWithdrawals)
				{
					kingdom.CallToWarWallet += num2;
				}
			}
		}

		private static void ApplyShareForExpenses(Clan clan, ref ExplainedNumber goldChange, bool applyWithdrawals, int expenseShare, TextObject mercenaryExpensesText)
		{
			if (applyWithdrawals)
			{
				int num = (int)((float)clan.Gold + goldChange.ResultNumber);
				if (expenseShare > num)
				{
					int num2 = expenseShare - num;
					expenseShare = num;
					clan.DebtToKingdom += num2;
				}
			}
			goldChange.Add(-expenseShare, mercenaryExpensesText);
		}

		private void AddSettlementIncome(Clan clan, ref ExplainedNumber goldChange, bool applyWithdrawals, bool includeDetails)
		{
			ExplainedNumber explainedNumber = new ExplainedNumber(0f, goldChange.IncludeDescriptions);
			foreach (Town fief in clan.Fiefs)
			{
				ExplainedNumber explainedNumber2 = Campaign.Current.Models.SettlementTaxModel.CalculateTownTax(fief);
				ExplainedNumber explainedNumber3 = Campaign.Current.Models.ClanFinanceModel.CalculateTownIncomeFromTariffs(clan, fief, applyWithdrawals);
				int num = Campaign.Current.Models.ClanFinanceModel.CalculateTownIncomeFromProjects(fief);
				if (explainedNumber.IncludeDescriptions)
				{
					explainedNumber.Add((int)explainedNumber2.ResultNumber, Game.Current.GameTextManager.FindText(_townTaxStr), fief.Name);
					explainedNumber.Add((int)explainedNumber3.ResultNumber, Game.Current.GameTextManager.FindText(_tariffTaxStr), fief.Name);
					explainedNumber.Add(num, _projectsIncomeText);
				}
				else
				{
					explainedNumber.Add((int)explainedNumber2.ResultNumber);
					explainedNumber.Add((int)explainedNumber3.ResultNumber);
					explainedNumber.Add(num);
				}
				foreach (Village village in fief.Villages)
				{
					int num2 = CalculateVillageIncome(clan, village, applyWithdrawals);
					explainedNumber.Add(num2, village.Name);
				}
			}
			if (!includeDetails)
			{
				goldChange.Add(explainedNumber.ResultNumber, _settlementIncome);
			}
			else
			{
				goldChange.AddFromExplainedNumber(explainedNumber, _settlementIncome);
			}
		}

		public override ExplainedNumber CalculateTownIncomeFromTariffs(Clan clan, Town town, bool applyWithdrawals = false)
		{
			ExplainedNumber bonuses = new ExplainedNumber((int)((float)town.TradeTaxAccumulated / RevenueSmoothenFraction()));
			int num = TaleWorlds.Library.MathF.Round(bonuses.ResultNumber);
			PerkHelper.AddPerkBonusForTown(DefaultPerks.Trade.ContentTrades, town, ref bonuses);
			PerkHelper.AddPerkBonusForTown(DefaultPerks.Crossbow.Steady, town, ref bonuses);
			PerkHelper.AddPerkBonusForTown(DefaultPerks.Roguery.SaltTheEarth, town, ref bonuses);
			PerkHelper.AddPerkBonusForTown(DefaultPerks.Steward.GivingHands, town, ref bonuses);
			CalculateSettlementProjectTariffBonuses(town, ref bonuses);
			if (applyWithdrawals)
			{
				town.TradeTaxAccumulated -= num;
				if (clan == Clan.PlayerClan)
				{
					CampaignEventDispatcher.Instance.OnPlayerEarnedGoldFromAsset(AssetIncomeType.Taxes, (int)bonuses.ResultNumber);
				}
			}
			return bonuses;
		}

		private void CalculateSettlementProjectTariffBonuses(Town town, ref ExplainedNumber result)
		{
			town.AddEffectOfBuildings(BuildingEffectEnum.TariffIncome, ref result);
		}

		public override int CalculateTownIncomeFromProjects(Town town)
		{
			ExplainedNumber result = default(ExplainedNumber);
			if (town.CurrentDefaultBuilding != null && town.Governor != null && town.Governor.GetPerkValue(DefaultPerks.Engineering.ArchitecturalCommisions))
			{
				result.Add((int)DefaultPerks.Engineering.ArchitecturalCommisions.SecondaryBonus);
			}
			town.AddEffectOfBuildings(BuildingEffectEnum.DenarByBoundVillageHeartPerDay, ref result);
			return (int)result.ResultNumber;
		}

		public override int CalculateVillageIncome(Clan clan, Village village, bool applyWithdrawals = false)
		{
			int num = ((village.VillageState != Village.VillageStates.Looted && village.VillageState != Village.VillageStates.BeingRaided) ? ((int)((float)village.TradeTaxAccumulated / RevenueSmoothenFraction())) : 0);
			int num2 = num;
			if (clan.Kingdom != null && clan.Kingdom.RulingClan != clan && clan.Kingdom.ActivePolicies.Contains(DefaultPolicies.LandTax))
			{
				num -= (int)(0.05f * (float)num);
			}
			if (village.Bound.Town != null && village.Bound.Town.Governor != null && village.Bound.Town.Governor.GetPerkValue(DefaultPerks.Scouting.ForestKin))
			{
				num += TaleWorlds.Library.MathF.Round((float)num * DefaultPerks.Scouting.ForestKin.SecondaryBonus);
			}
			if (village.Bound?.Town?.Governor != null && village.Bound.Town.Governor.GetPerkValue(DefaultPerks.Steward.Logistician))
			{
				num += TaleWorlds.Library.MathF.Round((float)num * DefaultPerks.Steward.Logistician.SecondaryBonus);
			}
			if (applyWithdrawals)
			{
				village.TradeTaxAccumulated -= num2;
				if (clan == Clan.PlayerClan)
				{
					CampaignEventDispatcher.Instance.OnPlayerEarnedGoldFromAsset(AssetIncomeType.Taxes, num);
				}
			}
			return num;
		}

		private static float CalculateShareFactor(Clan clan)
		{
			Kingdom kingdom = clan.Kingdom;
			int num = kingdom.Fiefs.Sum((Town x) => x.IsCastle ? 1 : 3) + 1 + kingdom.Clans.Count;
			return (float)(clan.Fiefs.Sum((Town x) => x.IsCastle ? 1 : 3) + ((clan == kingdom.RulingClan) ? 1 : 0) + 1) / (float)num;
		}

		private void AddMercenaryIncome(Clan clan, ref ExplainedNumber goldChange, bool applyWithdrawals)
		{
			if (clan.IsUnderMercenaryService && clan.Leader != null && clan.Kingdom != null)
			{
				int num = TaleWorlds.Library.MathF.Ceiling(clan.Influence * (1f / Campaign.Current.Models.ClanFinanceModel.RevenueSmoothenFraction())) * clan.MercenaryAwardMultiplier;
				if (applyWithdrawals)
				{
					clan.Kingdom.MercenaryWallet -= num;
				}
				goldChange.Add(num, _mercenaryText);
			}
		}

		private void AddIncomeFromKingdomBudget(Clan clan, ref ExplainedNumber goldChange, bool applyWithdrawals)
		{
			int num = ((clan.Gold < 5000) ? 2000 : ((clan.Gold < 10000) ? 1500 : ((clan.Gold < 20000) ? 1000 : 500)));
			num *= ((clan.Kingdom.KingdomBudgetWallet <= 1000000) ? 1 : 2);
			num *= ((clan.Leader != clan.Kingdom.Leader) ? 1 : 2);
			int num2 = TaleWorlds.Library.MathF.Min(clan.Kingdom.KingdomBudgetWallet, num);
			if (applyWithdrawals)
			{
				clan.Kingdom.KingdomBudgetWallet -= num2;
			}
			goldChange.Add(num2, _kingdomSupportText);
		}

		private void AddPlayerClanIncomeFromOwnedAlleys(ref ExplainedNumber goldChange)
		{
			int num = 0;
			foreach (Alley ownedAlley in Hero.MainHero.OwnedAlleys)
			{
				num += Campaign.Current.Models.AlleyModel.GetDailyIncomeOfAlley(ownedAlley);
			}
			goldChange.Add(num, _alleyText);
		}

		private void AddIncomeFromTribute(Clan clan, ref ExplainedNumber goldChange, bool applyWithdrawals, bool includeDetails)
		{
			ExplainedNumber explainedNumber = new ExplainedNumber(0f, goldChange.IncludeDescriptions);
			IFaction mapFaction = clan.MapFaction;
			float num = 1f;
			if (clan.Kingdom != null)
			{
				num = CalculateShareFactor(clan);
			}
			foreach (StanceLink stance in FactionHelper.GetStances(mapFaction))
			{
				IFaction faction = ((stance.Faction1 == mapFaction) ? stance.Faction2 : stance.Faction1);
				int dailyTributeToPay = stance.GetDailyTributeToPay(mapFaction);
				if (mapFaction.IsAtWarWith(faction) || dailyTributeToPay >= 0)
				{
					continue;
				}
				int num2 = (int)((float)dailyTributeToPay * num);
				if (applyWithdrawals)
				{
					faction.TributeWallet += num2;
					if (stance.Faction1 == mapFaction)
					{
						stance.TotalTributePaidFrom2To1 += -num2;
					}
					if (stance.Faction2 == mapFaction)
					{
						stance.TotalTributePaidFrom1To2 += -num2;
					}
					CampaignEventDispatcher.Instance.OnClanEarnedGoldFromTribute(clan, faction);
					if (clan == Clan.PlayerClan)
					{
						CampaignEventDispatcher.Instance.OnPlayerEarnedGoldFromAsset(AssetIncomeType.TributesEarned, -num2);
					}
				}
				explainedNumber.Add(-num2, Game.Current.GameTextManager.FindText(_tributeIncomeStr), faction.InformalName);
			}
			if (!includeDetails)
			{
				goldChange.Add(explainedNumber.ResultNumber, _tributeIncomes);
			}
			else
			{
				goldChange.AddFromExplainedNumber(explainedNumber, _tributeIncomes);
			}
		}

		private void AddIncomeFromTradeAgreements(Clan clan, ref ExplainedNumber goldChange, bool applyWithdrawals, bool includeDetails)
		{
			foreach (Kingdom item in Kingdom.All)
			{
				if (item != clan.Kingdom && !item.IsEliminated && TradeAgreementsBehavior.HasTradeAgreement(item, clan.Kingdom, out var tradeAgreement))
				{
					AddIncomeFromTradeAgreements(clan, ref tradeAgreement, ref goldChange, applyWithdrawals, includeDetails);
				}
			}
		}

		private void AddIncomeFromTradeAgreements(Clan clan, ref TradeAgreementsCampaignBehavior.TradeAgreement tradeAgreement, ref ExplainedNumber goldChange, bool applyWithdrawals, bool includeDetails)
		{
			bool flag = clan.Kingdom == tradeAgreement.Kingdom1;
			int num = (flag ? tradeAgreement.Kingdom1GoldGained : tradeAgreement.Kingdom2GoldGained);
			if (num <= 0)
			{
				return;
			}
			ExplainedNumber explainedNumber = new ExplainedNumber(0f, goldChange.IncludeDescriptions);
			float num2 = 1f / (float)clan.Kingdom.Clans.Count((Clan x) => !x.IsUnderMercenaryService);
			int num3 = (int)((float)num * num2);
			if (num3 > 0)
			{
				TextObject textObject = Game.Current.GameTextManager.FindText("str_finance_trade_agreement_income").SetTextVariable("KINGDOM", flag ? tradeAgreement.Kingdom2.Name : tradeAgreement.Kingdom1.Name);
				explainedNumber.Add(num3, textObject);
				if (!includeDetails)
				{
					goldChange.Add(explainedNumber.ResultNumber, textObject);
				}
				else
				{
					goldChange.AddFromExplainedNumber(explainedNumber, textObject);
				}
				if (applyWithdrawals)
				{
					TradeAgreementsBehavior.OnTradeGoldDistributedInKingdom(tradeAgreement.Kingdom1, tradeAgreement.Kingdom2, clan, num3);
				}
			}
		}

		private void AddIncomeFromCallToWarAgrements(Clan clan, ref ExplainedNumber goldChange, bool applyWithdrawals)
		{
			if (clan.Kingdom == null || clan.Kingdom.CallToWarWallet <= 0)
			{
				return;
			}
			float num = CalculateShareFactor(clan);
			int num2 = (int)((float)clan.Kingdom.CallToWarWallet * num);
			if (applyWithdrawals)
			{
				clan.Kingdom.CallToWarWallet -= num2;
				if (clan == Clan.PlayerClan)
				{
					CampaignEventDispatcher.Instance.OnPlayerEarnedGoldFromAsset(AssetIncomeType.TributesEarned, num2);
				}
			}
			goldChange.Add(num2, _callToWarIncomes);
		}

		private void AddIncomeFromParties(Clan clan, ref ExplainedNumber goldChange, bool applyWithdrawals, bool includeDetails)
		{
			ExplainedNumber explainedNumber = new ExplainedNumber(0f, goldChange.IncludeDescriptions);
			foreach (Hero aliveLord in clan.AliveLords)
			{
				foreach (CaravanPartyComponent ownedCaravan in aliveLord.OwnedCaravans)
				{
					if (ownedCaravan.MobileParty.IsActive && ownedCaravan.MobileParty.LeaderHero != clan.Leader && (ownedCaravan.MobileParty.IsLordParty || ownedCaravan.MobileParty.IsGarrison || ownedCaravan.MobileParty.IsCaravan))
					{
						int num = AddIncomeFromParty(ownedCaravan.MobileParty, clan, ref goldChange, applyWithdrawals);
						explainedNumber.Add(num, Game.Current.GameTextManager.FindText(ownedCaravan.MobileParty.CaravanPartyComponent.CanHaveNavalNavigationCapability ? _convoyIncomeStr : _caravanIncomeStr), (ownedCaravan.Leader != null) ? ownedCaravan.Leader.Name : ownedCaravan.Name);
					}
				}
			}
			foreach (Hero companion in clan.Companions)
			{
				foreach (CaravanPartyComponent ownedCaravan2 in companion.OwnedCaravans)
				{
					if (ownedCaravan2.MobileParty.IsActive && ownedCaravan2.MobileParty.LeaderHero != clan.Leader && (ownedCaravan2.MobileParty.IsLordParty || ownedCaravan2.MobileParty.IsGarrison || ownedCaravan2.MobileParty.IsCaravan))
					{
						int num2 = AddIncomeFromParty(ownedCaravan2.MobileParty, clan, ref goldChange, applyWithdrawals);
						explainedNumber.Add(num2, Game.Current.GameTextManager.FindText(ownedCaravan2.MobileParty.CaravanPartyComponent.CanHaveNavalNavigationCapability ? _convoyIncomeStr : _caravanIncomeStr), (ownedCaravan2.Leader != null) ? ownedCaravan2.Leader.Name : ownedCaravan2.Name);
					}
				}
			}
			foreach (WarPartyComponent warPartyComponent in clan.WarPartyComponents)
			{
				if (warPartyComponent.MobileParty.IsActive && warPartyComponent.MobileParty.LeaderHero != clan.Leader && (warPartyComponent.MobileParty.IsLordParty || warPartyComponent.MobileParty.IsGarrison || warPartyComponent.MobileParty.IsCaravan))
				{
					int num3 = AddIncomeFromParty(warPartyComponent.MobileParty, clan, ref goldChange, applyWithdrawals);
					explainedNumber.Add(num3, Game.Current.GameTextManager.FindText(_partyIncomeStr), warPartyComponent.MobileParty.Name);
				}
			}
			if (!includeDetails)
			{
				goldChange.Add(explainedNumber.ResultNumber, _caravanAndPartyIncome);
			}
			else
			{
				goldChange.AddFromExplainedNumber(explainedNumber, _caravanAndPartyIncome);
			}
		}

		private int AddIncomeFromParty(MobileParty party, Clan clan, ref ExplainedNumber goldChange, bool applyWithdrawals)
		{
			int num = 0;
			if (party.IsActive && party.LeaderHero != clan.Leader && (party.IsLordParty || party.IsGarrison || party.IsCaravan))
			{
				int partyTradeGold = party.PartyTradeGold;
				if (partyTradeGold > 10000)
				{
					num = (partyTradeGold - 10000) / 10;
					if (applyWithdrawals)
					{
						party.PartyTradeGold -= num;
						if (party.LeaderHero != null && num > 0)
						{
							SkillLevelingManager.OnTradeProfitMade(party.LeaderHero, num);
						}
						if (party.Party.Owner?.Clan?.Leader != null && party.IsCaravan && party.Party.Owner.Clan.Leader.GetPerkValue(DefaultPerks.Trade.GreatInvestor) && num > 0)
						{
							party.Party.Owner.Clan.AddRenown(DefaultPerks.Trade.GreatInvestor.PrimaryBonus);
						}
						if (clan == Clan.PlayerClan && party.IsCaravan)
						{
							CampaignEventDispatcher.Instance.OnPlayerEarnedGoldFromAsset(AssetIncomeType.Caravan, num);
						}
					}
				}
			}
			return num;
		}

		private void AddExpensesFromPartiesAndGarrisons(Clan clan, ref ExplainedNumber goldChange, bool applyWithdrawals, bool includeDetails)
		{
			ExplainedNumber explainedNumber = new ExplainedNumber(0f, goldChange.IncludeDescriptions);
			int num = AddExpenseFromLeaderParty(clan, goldChange, applyWithdrawals);
			explainedNumber.Add(num, _mainPartywageText);
			foreach (Hero aliveLord in clan.AliveLords)
			{
				foreach (CaravanPartyComponent ownedCaravan in aliveLord.OwnedCaravans)
				{
					if (ownedCaravan.MobileParty.IsActive && ownedCaravan.MobileParty.LeaderHero != clan.Leader)
					{
						int num2 = AddPartyExpense(ownedCaravan.MobileParty, clan, goldChange, applyWithdrawals);
						if (explainedNumber.IncludeDescriptions)
						{
							explainedNumber.Add(num2, Game.Current.GameTextManager.FindText(_partyExpensesStr), ownedCaravan.Name);
						}
						else
						{
							explainedNumber.Add(num2);
						}
					}
				}
			}
			foreach (Hero companion in clan.Companions)
			{
				foreach (CaravanPartyComponent ownedCaravan2 in companion.OwnedCaravans)
				{
					int num3 = AddPartyExpense(ownedCaravan2.MobileParty, clan, goldChange, applyWithdrawals);
					if (explainedNumber.IncludeDescriptions)
					{
						explainedNumber.Add(num3, Game.Current.GameTextManager.FindText(_partyExpensesStr), ownedCaravan2.Name);
					}
					else
					{
						explainedNumber.Add(num3);
					}
				}
			}
			foreach (WarPartyComponent warPartyComponent in clan.WarPartyComponents)
			{
				if (warPartyComponent.MobileParty.IsActive && warPartyComponent.MobileParty.LeaderHero != clan.Leader)
				{
					int num4 = AddPartyExpense(warPartyComponent.MobileParty, clan, goldChange, applyWithdrawals);
					if (explainedNumber.IncludeDescriptions)
					{
						explainedNumber.Add(num4, Game.Current.GameTextManager.FindText(_partyExpensesStr), warPartyComponent.Name);
					}
					else
					{
						explainedNumber.Add(num4);
					}
				}
			}
			foreach (Town fief in clan.Fiefs)
			{
				if (fief.GarrisonParty != null && fief.GarrisonParty.IsActive)
				{
					int num5 = AddPartyExpense(fief.GarrisonParty, clan, goldChange, applyWithdrawals);
					if (explainedNumber.IncludeDescriptions)
					{
						TextObject textObject = new TextObject("{=fsTBcLvA}{SETTLEMENT} Garrison");
						textObject.SetTextVariable("SETTLEMENT", fief.Name);
						explainedNumber.Add(num5, Game.Current.GameTextManager.FindText(_partyExpensesStr), textObject);
					}
					else
					{
						explainedNumber.Add(num5);
					}
				}
			}
			if (!includeDetails)
			{
				goldChange.Add(explainedNumber.ResultNumber, _garrisonAndPartyExpenses);
			}
			else
			{
				goldChange.AddFromExplainedNumber(explainedNumber, _garrisonAndPartyExpenses);
			}
		}

		private void AddExpensesForAutoRecruitment(Clan clan, ref ExplainedNumber goldChange, bool applyWithdrawals = false)
		{
			int num = clan.AutoRecruitmentExpenses / 5;
			if (applyWithdrawals)
			{
				clan.AutoRecruitmentExpenses -= num;
			}
			goldChange.Add(-num, _autoRecruitmentText);
		}

		private int AddExpenseFromLeaderParty(Clan clan, ExplainedNumber goldChange, bool applyWithdrawals)
		{
			MobileParty mobileParty = clan.Leader?.PartyBelongedTo;
			if (mobileParty != null)
			{
				int num = clan.Gold + (int)goldChange.ResultNumber;
				if (num < 2000 && applyWithdrawals && clan != Clan.PlayerClan)
				{
					num = 0;
				}
				return -CalculatePartyWage(mobileParty, num, applyWithdrawals);
			}
			return 0;
		}

		private int AddPartyExpense(MobileParty party, Clan clan, ExplainedNumber goldChange, bool applyWithdrawals)
		{
			int num = clan.Gold + (int)goldChange.ResultNumber;
			int num2 = num;
			if (num < (party.IsGarrison ? 8000 : 4000) && applyWithdrawals && clan != Clan.PlayerClan)
			{
				num2 = ((party.LeaderHero != null && party.PartyTradeGold < 500) ? TaleWorlds.Library.MathF.Min(num, 250) : 0);
			}
			int num3 = CalculatePartyWage(party, num2, applyWithdrawals);
			int partyTradeGold = party.PartyTradeGold;
			if (applyWithdrawals)
			{
				if (party.IsLordParty && party.LeaderHero == null)
				{
					party.ActualClan.Leader.Gold -= num3;
				}
				else
				{
					party.PartyTradeGold -= num3;
				}
			}
			partyTradeGold -= num3;
			if (partyTradeGold < PartyGoldLowerThreshold)
			{
				int num4 = PartyGoldLowerThreshold - partyTradeGold;
				if (party.IsLordParty && party.LeaderHero == null)
				{
					num4 = num3;
				}
				if (applyWithdrawals)
				{
					num4 = TaleWorlds.Library.MathF.Min(num4, num2);
					party.PartyTradeGold += num4;
				}
				return -num4;
			}
			return 0;
		}

		public override int CalculateOwnerIncomeFromCaravan(MobileParty caravan)
		{
			return (int)((float)TaleWorlds.Library.MathF.Max(0, caravan.PartyTradeGold - Campaign.Current.Models.CaravanModel.GetInitialTradeGold(caravan.Owner, caravan.CaravanPartyComponent.CanHaveNavalNavigationCapability, eliteCaravan: false)) / RevenueSmoothenFraction());
		}

		public override int CalculateOwnerIncomeFromWorkshop(Workshop workshop)
		{
			return (int)((float)TaleWorlds.Library.MathF.Max(0, workshop.ProfitMade) / RevenueSmoothenFraction());
		}

		private void CalculateHeroIncomeFromAssets(Hero hero, ref ExplainedNumber goldChange, bool applyWithdrawals)
		{
			int num = 0;
			foreach (CaravanPartyComponent ownedCaravan in hero.OwnedCaravans)
			{
				if (ownedCaravan.MobileParty.PartyTradeGold > Campaign.Current.Models.CaravanModel.GetInitialTradeGold(ownedCaravan.Owner, ownedCaravan.CanHaveNavalNavigationCapability, eliteCaravan: false))
				{
					int num2 = Campaign.Current.Models.ClanFinanceModel.CalculateOwnerIncomeFromCaravan(ownedCaravan.MobileParty);
					if (applyWithdrawals)
					{
						ownedCaravan.MobileParty.PartyTradeGold -= num2;
						SkillLevelingManager.OnTradeProfitMade(hero, num2);
					}
					if (num2 > 0)
					{
						num += num2;
					}
				}
			}
			goldChange.Add(num, goldChange.IncludeDescriptions ? Game.Current.GameTextManager.FindText(_caravanIncomeStr) : null);
			CalculateHeroIncomeFromWorkshops(hero, ref goldChange, applyWithdrawals);
			if (hero.CurrentSettlement == null)
			{
				return;
			}
			foreach (Alley alley in hero.CurrentSettlement.Alleys)
			{
				if (alley.Owner == hero)
				{
					goldChange.Add(30f, alley.Name);
				}
			}
		}

		private void CalculateHeroIncomeFromWorkshops(Hero hero, ref ExplainedNumber goldChange, bool applyWithdrawals)
		{
			int num = 0;
			int num2 = 0;
			foreach (Workshop ownedWorkshop in hero.OwnedWorkshops)
			{
				int num3 = Campaign.Current.Models.ClanFinanceModel.CalculateOwnerIncomeFromWorkshop(ownedWorkshop);
				num += num3;
				if (applyWithdrawals && num3 > 0)
				{
					ownedWorkshop.ChangeGold(-num3);
					if (hero == Hero.MainHero)
					{
						CampaignEventDispatcher.Instance.OnPlayerEarnedGoldFromAsset(AssetIncomeType.Workshop, num3);
					}
				}
				if (num3 > 0)
				{
					num2++;
				}
			}
			goldChange.Add(num, _shopIncomeText);
			if (hero.Clan != null && (hero.Clan.Leader?.GetPerkValue(DefaultPerks.Trade.ArtisanCommunity) ?? false) && applyWithdrawals && num2 > 0)
			{
				hero.Clan.AddRenown((float)num2 * DefaultPerks.Trade.ArtisanCommunity.PrimaryBonus);
			}
		}

		public override float RevenueSmoothenFraction()
		{
			return 5f;
		}

		private int CalculatePartyWage(MobileParty mobileParty, int budget, bool applyWithdrawals)
		{
			int totalWage = mobileParty.TotalWage;
			int num = totalWage;
			if (applyWithdrawals)
			{
				num = TaleWorlds.Library.MathF.Min(totalWage, budget);
				ApplyMoraleEffect(mobileParty, totalWage, num);
			}
			return num;
		}

		public override int CalculateNotableDailyGoldChange(Hero hero, bool applyWithdrawals)
		{
			ExplainedNumber goldChange = new ExplainedNumber(0f, includeDescriptions: false, null);
			CalculateHeroIncomeFromAssets(hero, ref goldChange, applyWithdrawals);
			return (int)goldChange.ResultNumber;
		}

		private static void ApplyMoraleEffect(MobileParty mobileParty, int wage, int paymentAmount)
		{
			if (paymentAmount < wage && wage > 0)
			{
				float num = 1f - (float)paymentAmount / (float)wage;
				float num2 = (float)Campaign.Current.Models.PartyMoraleModel.GetDailyNoWageMoralePenalty(mobileParty) * num;
				if (mobileParty.HasUnpaidWages < num)
				{
					num2 += (float)Campaign.Current.Models.PartyMoraleModel.GetDailyNoWageMoralePenalty(mobileParty) * (num - mobileParty.HasUnpaidWages);
				}
				mobileParty.RecentEventsMorale += num2;
				mobileParty.HasUnpaidWages = num;
				MBTextManager.SetTextVariable("reg1", TaleWorlds.Library.MathF.Round(TaleWorlds.Library.MathF.Abs(num2), 1));
				if (mobileParty == MobileParty.MainParty)
				{
					MBInformationManager.AddQuickInformation(GameTexts.FindText("str_party_loses_moral_due_to_insufficent_funds"));
				}
			}
			else
			{
				mobileParty.HasUnpaidWages = 0f;
			}
		}
	}
	public class DefaultClanMemberPartyRoleModel : ClanMemberPartyRoleModel
	{
		public override int MaximumPartyRoleAssignmentCount => 2;

		public override IEnumerable<PartyRole> GetAssignablePartyRoles()
		{
			yield return PartyRole.Quartermaster;
			yield return PartyRole.Scout;
			yield return PartyRole.Surgeon;
			yield return PartyRole.Engineer;
		}

		public override SkillObject GetRelevantSkillForPartyRole(PartyRole role)
		{
			switch (role)
			{
			case PartyRole.Engineer:
				return DefaultSkills.Engineering;
			case PartyRole.Quartermaster:
				return DefaultSkills.Steward;
			case PartyRole.Scout:
				return DefaultSkills.Scouting;
			case PartyRole.Surgeon:
				return DefaultSkills.Medicine;
			default:
				TaleWorlds.Library.Debug.FailedAssert($"Undefined clan role relevant skill {role}", "C:\\BuildAgent\\work\\mb3\\Source\\Bannerlord\\TaleWorlds.CampaignSystem\\GameComponents\\DefaultClanMemberRoleModel.cs", "GetRelevantSkillForPartyRole", 43);
				return null;
			}
		}

		public override bool IsHeroAssignableForPartyRole(Hero hero, PartyRole role, MobileParty party)
		{
			if (Campaign.Current.Models.ClanMemberPartyRoleModel.DoesHeroHaveEnoughSkillForPartyRole(hero, role, party))
			{
				return hero.CanBeGovernorOrHavePartyRole();
			}
			return false;
		}

		public override bool DoesHeroHaveEnoughSkillForPartyRole(Hero hero, PartyRole role, MobileParty party)
		{
			if (party.GetHeroPartyRoles(hero).Contains(role))
			{
				return true;
			}
			switch (role)
			{
			case PartyRole.Surgeon:
			case PartyRole.Engineer:
			case PartyRole.Scout:
			case PartyRole.Quartermaster:
				return Campaign.Current.Models.ClanMemberPartyRoleModel.IsHeroAssignableForPartyRoleInParty(role, hero, party);
			case PartyRole.None:
				return true;
			default:
				TaleWorlds.Library.Debug.FailedAssert($"Undefined clan role is asked if assignable {role}", "C:\\BuildAgent\\work\\mb3\\Source\\Bannerlord\\TaleWorlds.CampaignSystem\\GameComponents\\DefaultClanMemberRoleModel.cs", "DoesHeroHaveEnoughSkillForPartyRole", 73);
				return false;
			}
		}

		public override bool IsHeroAssignableForPartyRoleInParty(PartyRole role, Hero hero, MobileParty party)
		{
			if (hero.PartyBelongedTo == party && hero != party.GetRoleHolder(role))
			{
				return hero.GetSkillValue(Campaign.Current.Models.ClanMemberPartyRoleModel.GetRelevantSkillForPartyRole(role)) >= 0;
			}
			return false;
		}
	}
	public class DefaultClanPoliticsModel : ClanPoliticsModel
	{
		private static readonly TextObject _supporterStr = new TextObject("{=RzFyGnWJ}Supporters");

		private static readonly TextObject _crimeStr = new TextObject("{=MvxW9rmf}Criminal");

		private static readonly TextObject _armyMemberStr = new TextObject("{=XAdBVsXV}Clan members in an army");

		private static readonly TextObject _townProjectStr = new TextObject("{=8Yb3IVvb}Settlement Buildings");

		private static readonly TextObject _courtshipPerkStr = new TextObject("{=zgzDwZKZ}Courtship from clan parties");

		private static readonly TextObject _mercenaryStr = new TextObject("{=qcaaJLhx}Mercenary Contract");

		private static readonly TextObject _kingBonusStr = new TextObject("{=JNS46jsG}King bonus");

		public override ExplainedNumber CalculateInfluenceChange(Clan clan, bool includeDescriptions = false)
		{
			ExplainedNumber influenceChange = new ExplainedNumber(0f, includeDescriptions);
			CalculateInfluenceChangeInternal(clan, ref influenceChange);
			return influenceChange;
		}

		private void CalculateInfluenceChangeInternal(Clan clan, ref ExplainedNumber influenceChange)
		{
			if (clan.Leader.GetPerkValue(DefaultPerks.Charm.ImmortalCharm))
			{
				influenceChange.Add(DefaultPerks.Charm.ImmortalCharm.PrimaryBonus, DefaultPerks.Charm.ImmortalCharm.Name);
			}
			if (clan.IsUnderMercenaryService)
			{
				int num = TaleWorlds.Library.MathF.Ceiling(clan.Influence * (1f / Campaign.Current.Models.ClanFinanceModel.RevenueSmoothenFraction()));
				influenceChange.Add(-num, _mercenaryStr);
			}
			float num2 = 0f;
			foreach (WarPartyComponent warPartyComponent in clan.WarPartyComponents)
			{
				MobileParty mobileParty = warPartyComponent.MobileParty;
				if (mobileParty.Army != null && mobileParty.Army.LeaderParty != mobileParty && mobileParty.LeaderHero != null && mobileParty.Army.LeaderParty.LeaderHero != null && warPartyComponent.Clan != mobileParty.Army.LeaderParty.LeaderHero.Clan)
				{
					num2 += Campaign.Current.Models.ArmyManagementCalculationModel.DailyBeingAtArmyInfluenceAward(mobileParty);
				}
			}
			influenceChange.Add(num2, _armyMemberStr);
			if (clan.MapFaction.Leader == clan.Leader && clan.MapFaction.IsKingdomFaction)
			{
				influenceChange.Add(3f, _kingBonusStr);
			}
			foreach (Settlement settlement in clan.Settlements)
			{
				if (settlement.IsFortification)
				{
					settlement.Town.AddEffectOfBuildings(BuildingEffectEnum.Influence, ref influenceChange);
				}
			}
			if (clan == Clan.PlayerClan && clan.MapFaction.MainHeroCrimeRating > 0f)
			{
				int num3 = (int)(clan.MapFaction.MainHeroCrimeRating * -0.5f);
				influenceChange.Add(num3, _crimeStr);
			}
			float num4 = 0f;
			foreach (Hero supporterNotable in clan.SupporterNotables)
			{
				if (supporterNotable.CurrentSettlement != null)
				{
					float influenceBonusToClan = Campaign.Current.Models.NotablePowerModel.GetInfluenceBonusToClan(supporterNotable);
					num4 += influenceBonusToClan;
				}
			}
			if (num4 > 0f)
			{
				influenceChange.Add(num4, _supporterStr);
			}
			if (clan.Kingdom != null && !clan.IsUnderMercenaryService)
			{
				CalculateInfluenceChangeDueToPolicies(clan, ref influenceChange);
			}
			CalculateInfluenceChangeDueToIssues(clan, ref influenceChange);
		}

		private void CalculateInfluenceChangeDueToIssues(Clan clan, ref ExplainedNumber influenceChange)
		{
			Campaign.Current.Models.IssueModel.GetIssueEffectOfClan(DefaultIssueEffects.ClanInfluence, clan, ref influenceChange);
		}

		private void CalculateInfluenceChangeDueToPolicies(Clan clan, ref ExplainedNumber influenceChange)
		{
			if (clan.Kingdom.ActivePolicies.Contains(DefaultPolicies.FeudalInheritance))
			{
				influenceChange.Add(0.1f * (float)clan.Settlements.Count, DefaultPolicies.FeudalInheritance.Name);
			}
			if (clan.Kingdom.ActivePolicies.Contains(DefaultPolicies.Serfdom))
			{
				influenceChange.Add(0.2f * (float)clan.Settlements.Count((Settlement t) => t.IsVillage), DefaultPolicies.Serfdom.Name);
			}
			if (clan.Kingdom.ActivePolicies.Contains(DefaultPolicies.LordsPrivyCouncil) && clan.Tier >= 5)
			{
				influenceChange.Add(0.5f, DefaultPolicies.LordsPrivyCouncil.Name);
			}
			if (clan.Kingdom.ActivePolicies.Contains(DefaultPolicies.Senate) && clan.Tier >= 3)
			{
				influenceChange.Add(0.5f, DefaultPolicies.Senate.Name);
			}
			if (clan.Kingdom.ActivePolicies.Contains(DefaultPolicies.NobleRetinues) && clan.Tier >= 5)
			{
				influenceChange.Add(-1f, DefaultPolicies.NobleRetinues.Name);
			}
			if (clan.Kingdom.ActivePolicies.Contains(DefaultPolicies.Bailiffs))
			{
				int num = clan.Settlements.Count((Settlement settlement) => settlement.IsTown && settlement.Town.Security > 60f);
				influenceChange.Add(num, DefaultPolicies.Bailiffs.Name);
			}
			if (clan.Kingdom.ActivePolicies.Contains(DefaultPolicies.CouncilOfTheCommons))
			{
				float num2 = 0f;
				foreach (Settlement settlement in clan.Settlements)
				{
					num2 += (float)settlement.Notables.Count * 0.1f;
				}
				influenceChange.Add(num2, DefaultPolicies.CouncilOfTheCommons.Name);
			}
			if (clan.Kingdom.ActivePolicies.Contains(DefaultPolicies.TrialByJury))
			{
				influenceChange.Add(-1f, DefaultPolicies.TrialByJury.Name);
			}
			if (clan.Kingdom.ActivePolicies.Contains(DefaultPolicies.Lawspeakers))
			{
				float value = ((clan.Leader.GetSkillValue(DefaultSkills.Charm) > 100) ? 1f : (-1f));
				influenceChange.Add(value, DefaultPolicies.Lawspeakers.Name);
			}
			if (clan == clan.Kingdom.RulingClan)
			{
				if (clan.Kingdom.ActivePolicies.Contains(DefaultPolicies.SacredMajesty))
				{
					influenceChange.Add(3f, DefaultPolicies.SacredMajesty.Name);
				}
				if (clan.Kingdom.ActivePolicies.Contains(DefaultPolicies.Marshals))
				{
					influenceChange.Add(-1f, DefaultPolicies.Marshals.Name);
				}
			}
			else
			{
				if (clan.Kingdom.ActivePolicies.Contains(DefaultPolicies.SacredMajesty))
				{
					influenceChange.Add(-0.5f, DefaultPolicies.SacredMajesty.Name);
				}
				if (clan.Kingdom.ActivePolicies.Contains(DefaultPolicies.RoyalGuard))
				{
					influenceChange.Add(-0.2f, DefaultPolicies.RoyalGuard.Name);
				}
			}
		}

		public override float CalculateSupportForPolicyInClan(Clan clan, PolicyObject policy)
		{
			float num = 1f;
			float num2 = (float)clan.Leader.GetTraitLevel(DefaultTraits.Authoritarian) * policy.AuthoritarianWeight * num;
			float num3 = (float)clan.Leader.GetTraitLevel(DefaultTraits.Egalitarian) * policy.EgalitarianWeight * num;
			float num4 = (float)clan.Leader.GetTraitLevel(DefaultTraits.Oligarchic) * policy.OligarchicWeight * num;
			float num5 = 0f;
			float num6 = 0f;
			float num7 = 0f;
			if (clan.Tier == 1)
			{
				num5 = policy.EgalitarianWeight;
				num7 = 0f;
				num6 = 0f;
			}
			else if (clan.Tier == 2)
			{
				num5 = policy.EgalitarianWeight;
				num7 = 0f;
				num6 = 0f;
			}
			else if (clan.Tier == 3)
			{
				num5 = policy.EgalitarianWeight;
				num7 = 0f;
				num6 = 0f;
			}
			else if (clan.Tier == 4)
			{
				num5 = 0f;
				num7 = policy.OligarchicWeight;
				num6 = 0f;
			}
			else if (clan.Tier == 5)
			{
				num5 = 0f;
				num7 = policy.OligarchicWeight;
				num6 = 0f;
			}
			else
			{
				num5 = 0f;
				num7 = policy.OligarchicWeight;
				num6 = 0f;
			}
			float num8 = 0f;
			if (clan.Kingdom.RulingClan == clan)
			{
				if (clan.Leader.GetTraitLevel(DefaultTraits.Oligarchic) > 0 || clan.Leader.GetTraitLevel(DefaultTraits.Egalitarian) > 0)
				{
					num8 = -0.5f;
				}
				else if (clan.Leader.GetTraitLevel(DefaultTraits.Authoritarian) > 0)
				{
					num8 = 1f;
				}
			}
			return TaleWorlds.Library.MathF.Clamp(0f + (num2 + num3 + num4 + num5 + num7 + num6 + num8), -2f, 2f);
		}

		public override float CalculateRelationshipChangeWithSponsor(Clan clan, Clan sponsorClan)
		{
			return TaleWorlds.Library.MathF.Lerp(-2f, 2f, TaleWorlds.Library.MathF.Clamp((float)clan.Leader.GetRelation(sponsorClan.Leader) / 60f, 0f, 1f));
		}

		public override int GetInfluenceRequiredToOverrideKingdomDecision(DecisionOutcome popularOption, DecisionOutcome overridingOption, KingdomDecision decision)
		{
			float totalSupportPoints = popularOption.TotalSupportPoints;
			float num = overridingOption.TotalSupportPoints;
			float num2 = 0f;
			if (decision.Kingdom.RulingClan == Clan.PlayerClan)
			{
				if (totalSupportPoints == num + 1f)
				{
					num += 1f;
					num2 += (float)decision.GetInfluenceCostOfSupport(Clan.PlayerClan, Supporter.SupportWeights.SlightlyFavor);
				}
				else if (totalSupportPoints == num + 2f)
				{
					num += 2f;
					num2 += (float)decision.GetInfluenceCostOfSupport(Clan.PlayerClan, Supporter.SupportWeights.StronglyFavor);
				}
				else if (totalSupportPoints > num + 2f)
				{
					num += 3f;
					num2 += (float)decision.GetInfluenceCostOfSupport(Clan.PlayerClan, Supporter.SupportWeights.FullyPush);
				}
			}
			if (totalSupportPoints > num)
			{
				float num3 = (totalSupportPoints - num) / 3f * (float)decision.GetInfluenceCostOfSupport(decision.Kingdom.RulingClan, Supporter.SupportWeights.FullyPush) * 1.4f;
				if (decision.Kingdom.RulingClan != Clan.PlayerClan)
				{
					num3 *= 0.8f;
				}
				num2 += num3;
			}
			num2 = 5 * (int)(num2 / 5f);
			if (totalSupportPoints > num && decision.Kingdom.ActivePolicies.Contains(DefaultPolicies.RoyalPrivilege))
			{
				num2 *= 0.8f;
			}
			return (int)num2;
		}

		public override bool CanHeroBeGovernor(Hero hero)
		{
			if (hero.IsActive && !hero.IsChild && !hero.IsHumanPlayerCharacter && !hero.IsPartyLeader && !hero.IsFugitive && !hero.IsReleased && !hero.IsTraveling && !hero.IsPrisoner && hero.CanBeGovernorOrHavePartyRole() && !hero.IsSpecial)
			{
				return !hero.IsTemplate;
			}
			return false;
		}
	}
	public class DefaultClanTierModel : ClanTierModel
	{
		private static readonly int[] TierLowerRenownLimits = new int[7] { 0, 50, 150, 350, 900, 2350, 6150 };

		private readonly TextObject _partyLimitBonusText = GameTexts.FindText("str_clan_tier_party_limit_bonus");

		private readonly TextObject _companionLimitBonusText = GameTexts.FindText("str_clan_tier_companion_limit_bonus");

		private readonly TextObject _mercenaryEligibleText = GameTexts.FindText("str_clan_tier_mercenary_eligible");

		private readonly TextObject _vassalEligibleText = GameTexts.FindText("str_clan_tier_vassal_eligible");

		private readonly TextObject _additionalCurrentPartySizeBonus = GameTexts.FindText("str_clan_tier_party_size_bonus");

		private readonly TextObject _additionalWorkshopCountBonus = GameTexts.FindText("str_clan_tier_workshop_count_bonus");

		private readonly TextObject _kingdomEligibleText = GameTexts.FindText("str_clan_tier_kingdom_eligible");

		public override int MinClanTier => 0;

		public override int MaxClanTier => 6;

		public override int MercenaryEligibleTier => 1;

		public override int VassalEligibleTier => 2;

		public override int BannerEligibleTier => 0;

		public override int RebelClanStartingTier => 3;

		public override int CompanionToLordClanStartingTier => 2;

		private int KingdomEligibleTier => Campaign.Current.Models.KingdomCreationModel.MinimumClanTierToCreateKingdom;

		public override int CalculateInitialRenown(Clan clan)
		{
			int num = TierLowerRenownLimits[clan.Tier];
			int num2 = ((clan.Tier >= MaxClanTier) ? (TierLowerRenownLimits[MaxClanTier] + 1500) : TierLowerRenownLimits[clan.Tier + 1]);
			int maxValue = (int)((float)num2 - (float)(num2 - num) * 0.4f);
			return MBRandom.RandomInt(num, maxValue);
		}

		public override int CalculateInitialInfluence(Clan clan)
		{
			return (int)(150f + (float)MBRandom.RandomInt((int)((float)CalculateInitialRenown(clan) / 15f)) + (float)MBRandom.RandomInt(MBRandom.RandomInt(MBRandom.RandomInt(400))));
		}

		public override int CalculateTier(Clan clan)
		{
			int result = MinClanTier;
			for (int i = MinClanTier + 1; i <= MaxClanTier; i++)
			{
				if (clan.Renown >= (float)TierLowerRenownLimits[i])
				{
					result = i;
				}
			}
			return result;
		}

		public override (ExplainedNumber, bool) HasUpcomingTier(Clan clan, out TextObject extraExplanation, bool includeDescriptions = false)
		{
			bool flag = clan.Tier < MaxClanTier;
			ExplainedNumber item = new ExplainedNumber(0f, includeDescriptions);
			extraExplanation = null;
			if (flag)
			{
				int num = GetPartyLimitForTier(clan, clan.Tier + 1) - GetPartyLimitForTier(clan, clan.Tier);
				if (num != 0)
				{
					item.Add(num, _partyLimitBonusText);
				}
				int num2 = GetCompanionLimitFromTier(clan.Tier + 1) - GetCompanionLimitFromTier(clan.Tier);
				if (num2 != 0)
				{
					item.Add(num2, _companionLimitBonusText);
				}
				int nextClanTierPartySizeEffectChangeForHero = Campaign.Current.Models.PartySizeLimitModel.GetNextClanTierPartySizeEffectChangeForHero(clan.Leader);
				if (nextClanTierPartySizeEffectChangeForHero > 0)
				{
					item.Add(nextClanTierPartySizeEffectChangeForHero, _additionalCurrentPartySizeBonus);
				}
				int num3 = Campaign.Current.Models.WorkshopModel.GetMaxWorkshopCountForClanTier(clan.Tier + 1) - Campaign.Current.Models.WorkshopModel.GetMaxWorkshopCountForClanTier(clan.Tier);
				if (num3 > 0)
				{
					item.Add(num3, _additionalWorkshopCountBonus);
				}
				if (clan.Tier + 1 == MercenaryEligibleTier)
				{
					extraExplanation = _mercenaryEligibleText;
				}
				else if (clan.Tier + 1 == VassalEligibleTier)
				{
					extraExplanation = _vassalEligibleText;
				}
				else if (clan.Tier + 1 == KingdomEligibleTier)
				{
					extraExplanation = _kingdomEligibleText;
				}
			}
			return (item, flag);
		}

		public override int GetRequiredRenownForTier(int tier)
		{
			return TierLowerRenownLimits[tier];
		}

		public override int GetPartyLimitForTier(Clan clan, int clanTierToCheck)
		{
			ExplainedNumber result = new ExplainedNumber(0f, includeDescriptions: false, null);
			if (!clan.IsMinorFaction)
			{
				if (clanTierToCheck < 3)
				{
					result.Add(1f);
				}
				else if (clanTierToCheck < 5)
				{
					result.Add(2f);
				}
				else
				{
					result.Add(3f);
				}
			}
			else
			{
				result.Add(TaleWorlds.Library.MathF.Clamp(clanTierToCheck, 1f, 4f));
			}
			AddPartyLimitPerkEffects(clan, ref result);
			return TaleWorlds.Library.MathF.Round(result.ResultNumber);
		}

		private void AddPartyLimitPerkEffects(Clan clan, ref ExplainedNumber result)
		{
			if (clan.Leader != null && clan.Leader.GetPerkValue(DefaultPerks.Leadership.TalentMagnet))
			{
				result.Add(DefaultPerks.Leadership.TalentMagnet.SecondaryBonus, DefaultPerks.Leadership.TalentMagnet.Name);
			}
		}

		public override int GetCompanionLimit(Clan clan)
		{
			int num = GetCompanionLimitFromTier(clan.Tier);
			if (clan.Leader.GetPerkValue(DefaultPerks.Leadership.WePledgeOurSwords))
			{
				num += (int)DefaultPerks.Leadership.WePledgeOurSwords.PrimaryBonus;
			}
			if (clan.Leader.GetPerkValue(DefaultPerks.Charm.Camaraderie))
			{
				num += (int)DefaultPerks.Charm.Camaraderie.SecondaryBonus;
			}
			return num;
		}

		private int GetCompanionLimitFromTier(int clanTier)
		{
			return clanTier + 3;
		}
	}
	public class DefaultCombatSimulationModel : CombatSimulationModel
	{
		public override ExplainedNumber SimulateHit(CharacterObject strikerTroop, CharacterObject struckTroop, PartyBase strikerParty, PartyBase struckParty, float strikerAdvantage, MapEvent battle, float strikerSideMorale, float struckSideMorale)
		{
			float troopPower = Campaign.Current.Models.MilitaryPowerModel.GetTroopPower(strikerTroop, strikerParty.Side, strikerParty.MapEvent.SimulationContext, strikerParty.MapEventSide.LeaderSimulationModifier);
			float troopPower2 = Campaign.Current.Models.MilitaryPowerModel.GetTroopPower(struckTroop, struckParty.Side, struckParty.MapEvent.SimulationContext, struckParty.MapEventSide.LeaderSimulationModifier);
			int num = (int)((0.5f + 0.5f * MBRandom.RandomFloat) * (40f * TaleWorlds.Library.MathF.Pow(troopPower / troopPower2, 0.7f) * strikerAdvantage));
			ExplainedNumber effectiveDamage = new ExplainedNumber(num);
			if (strikerParty.IsMobile && struckParty.IsMobile)
			{
				CalculateSimulationDamagePerkEffects(strikerTroop, struckTroop, strikerParty.MobileParty, struckParty.MobileParty, ref effectiveDamage, battle);
			}
			CalculateSimulationMoraleEffects(strikerSideMorale, struckSideMorale, ref effectiveDamage);
			return effectiveDamage;
		}

		public override ExplainedNumber SimulateHit(Ship strikerShip, Ship struckShip, PartyBase strikerParty, PartyBase struckParty, SiegeEngineType siegeEngine, float strikerAdvantage, MapEvent battle, out int troopCasualties)
		{
			troopCasualties = 0;
			return new ExplainedNumber(0f, includeDescriptions: false, null);
		}

		private static void CalculateSimulationMoraleEffects(float strikerMorale, float struckMorale, ref ExplainedNumber effectiveDamage)
		{
			float num = TaleWorlds.Library.MathF.Min(strikerMorale - 50f, 0f);
			float num2 = TaleWorlds.Library.MathF.Max(struckMorale - 50f, 0f);
			effectiveDamage.AddFactor((num - num2) * 0.005f);
		}

		private static void CalculateSimulationDamagePerkEffects(CharacterObject strikerTroop, CharacterObject struckTroop, MobileParty strikerParty, MobileParty struckParty, ref ExplainedNumber effectiveDamage, MapEvent battle)
		{
			if (!strikerParty.IsCurrentlyAtSea && strikerTroop.IsInfantry && struckTroop.IsMounted)
			{
				PerkHelper.AddPerkBonusForParty(DefaultPerks.Tactics.TightFormations, strikerParty, isPrimaryBonus: true, ref effectiveDamage);
			}
			if (!strikerParty.IsCurrentlyAtSea && struckParty.HasPerk(DefaultPerks.Tactics.LooseFormations) && struckTroop.IsInfantry && strikerTroop.IsRanged)
			{
				PerkHelper.AddPerkBonusForParty(DefaultPerks.Tactics.LooseFormations, struckParty, isPrimaryBonus: true, ref effectiveDamage);
			}
			TerrainType faceTerrainType = Campaign.Current.MapSceneWrapper.GetFaceTerrainType(strikerParty.CurrentNavigationFace);
			if (faceTerrainType == TerrainType.Snow || faceTerrainType == TerrainType.Forest)
			{
				PerkHelper.AddPerkBonusForParty(DefaultPerks.Tactics.ExtendedSkirmish, strikerParty, isPrimaryBonus: true, ref effectiveDamage);
			}
			if (faceTerrainType == TerrainType.Plain || faceTerrainType == TerrainType.Steppe || faceTerrainType == TerrainType.Desert)
			{
				PerkHelper.AddPerkBonusForParty(DefaultPerks.Tactics.DecisiveBattle, strikerParty, isPrimaryBonus: true, ref effectiveDamage);
			}
			if (!strikerParty.IsCurrentlyAtSea && !strikerParty.IsBandit && struckParty.IsBandit)
			{
				PerkHelper.AddPerkBonusForParty(DefaultPerks.Tactics.LawKeeper, strikerParty, isPrimaryBonus: true, ref effectiveDamage);
			}
			if (!strikerParty.IsCurrentlyAtSea)
			{
				PerkHelper.AddPerkBonusForParty(DefaultPerks.Tactics.Coaching, strikerParty, isPrimaryBonus: true, ref effectiveDamage);
			}
			if (!struckParty.IsCurrentlyAtSea && struckTroop.Tier >= 3)
			{
				PerkHelper.AddPerkBonusForParty(DefaultPerks.Tactics.EliteReserves, struckParty, isPrimaryBonus: true, ref effectiveDamage);
			}
			if (!strikerParty.IsCurrentlyAtSea && strikerParty.MemberRoster.TotalHealthyCount > struckParty.MemberRoster.TotalHealthyCount)
			{
				PerkHelper.AddPerkBonusForParty(DefaultPerks.Tactics.Encirclement, strikerParty, isPrimaryBonus: true, ref effectiveDamage);
			}
			if (!strikerParty.IsCurrentlyAtSea && strikerParty.MemberRoster.TotalHealthyCount < struckParty.MemberRoster.TotalHealthyCount)
			{
				PerkHelper.AddPerkBonusForParty(DefaultPerks.Tactics.Counteroffensive, strikerParty, isPrimaryBonus: false, ref effectiveDamage);
			}
			bool flag = false;
			foreach (MapEventParty item in battle.PartiesOnSide(BattleSideEnum.Defender))
			{
				if (item.Party == struckParty.Party)
				{
					flag = true;
					break;
				}
			}
			bool flag2 = !flag;
			bool flag3 = flag2;
			if (battle.IsSiegeAssault && flag2 && strikerParty.HasPerk(DefaultPerks.Tactics.Besieged))
			{
				PerkHelper.AddPerkBonusForParty(DefaultPerks.Tactics.Besieged, strikerParty, isPrimaryBonus: true, ref effectiveDamage);
			}
			if (flag && !strikerParty.IsCurrentlyAtSea && strikerParty.HasPerk(DefaultPerks.Scouting.Vanguard))
			{
				effectiveDamage.AddFactor(DefaultPerks.Scouting.Vanguard.PrimaryBonus, DefaultPerks.Scouting.Vanguard.Name);
			}
			if ((battle.IsSiegeOutside || battle.IsSallyOut) && flag3 && !strikerParty.IsCurrentlyAtSea)
			{
				PerkHelper.AddPerkBonusForParty(DefaultPerks.Scouting.Rearguard, strikerParty, isPrimaryBonus: false, ref effectiveDamage);
			}
			if (battle.IsSallyOut && flag && !strikerParty.IsCurrentlyAtSea && strikerParty.HasPerk(DefaultPerks.Scouting.Vanguard, checkSecondaryRole: true))
			{
				effectiveDamage.AddFactor(DefaultPerks.Scouting.Vanguard.SecondaryBonus, DefaultPerks.Scouting.Vanguard.Name);
			}
			if (battle.IsFieldBattle && flag2 && !strikerParty.IsCurrentlyAtSea)
			{
				PerkHelper.AddPerkBonusForParty(DefaultPerks.Tactics.Counteroffensive, strikerParty, isPrimaryBonus: true, ref effectiveDamage);
			}
			if (strikerParty.Army != null && strikerParty.LeaderHero != null && strikerParty.Army.LeaderParty == strikerParty)
			{
				PerkHelper.AddEpicPerkBonusForCharacter(DefaultPerks.Tactics.TacticalMastery, strikerParty.LeaderHero.CharacterObject, DefaultSkills.Tactics, applyPrimaryBonus: true, ref effectiveDamage, Campaign.Current.Models.CharacterDevelopmentModel.MinSkillRequiredForEpicPerkBonus, strikerParty.IsCurrentlyAtSea);
			}
		}

		public override float GetMaximumSiegeEquipmentProgress(Settlement settlement)
		{
			float num = 0f;
			if (settlement.SiegeEvent != null && settlement.IsFortification)
			{
				foreach (SiegeEvent.SiegeEngineConstructionProgress item in settlement.SiegeEvent.GetSiegeEventSide(BattleSideEnum.Attacker).SiegeEngines.AllSiegeEngines())
				{
					if (!item.IsConstructed && item.Progress > num)
					{
						num = item.Progress;
					}
				}
			}
			return num;
		}

		public override int GetNumberOfEquipmentsBuilt(Settlement settlement)
		{
			if (settlement.SiegeEvent != null && settlement.IsFortification)
			{
				bool flag = false;
				int num = 0;
				int num2 = 0;
				int num3 = 0;
				foreach (SiegeEvent.SiegeEngineConstructionProgress item in settlement.SiegeEvent.GetSiegeEventSide(BattleSideEnum.Attacker).SiegeEngines.AllSiegeEngines())
				{
					if (item.IsConstructed)
					{
						if (item.SiegeEngine == DefaultSiegeEngineTypes.Ram)
						{
							flag = true;
						}
						else if (item.SiegeEngine == DefaultSiegeEngineTypes.SiegeTower)
						{
							num++;
						}
						else if (item.SiegeEngine == DefaultSiegeEngineTypes.Trebuchet || item.SiegeEngine == DefaultSiegeEngineTypes.Onager || item.SiegeEngine == DefaultSiegeEngineTypes.Ballista)
						{
							num2++;
						}
						else if (item.SiegeEngine == DefaultSiegeEngineTypes.FireOnager || item.SiegeEngine == DefaultSiegeEngineTypes.FireBallista)
						{
							num3++;
						}
					}
				}
				return (flag ? 1 : 0) + num + num2 + num3;
			}
			return 0;
		}

		public override float GetSettlementAdvantage(Settlement settlement)
		{
			if (settlement.SiegeEvent != null && settlement.IsFortification)
			{
				int wallLevel = settlement.Town.GetWallLevel();
				bool flag = false;
				bool flag2 = false;
				int num = 0;
				int num2 = 0;
				int num3 = 0;
				foreach (SiegeEvent.SiegeEngineConstructionProgress item in settlement.SiegeEvent.GetSiegeEventSide(BattleSideEnum.Attacker).SiegeEngines.AllSiegeEngines())
				{
					if (!item.IsConstructed)
					{
						continue;
					}
					if (item.SiegeEngine == DefaultSiegeEngineTypes.Ram || item.SiegeEngine == DefaultSiegeEngineTypes.ImprovedRam)
					{
						if (item.SiegeEngine == DefaultSiegeEngineTypes.ImprovedRam)
						{
							flag2 = true;
						}
						flag = true;
					}
					else if (item.SiegeEngine == DefaultSiegeEngineTypes.SiegeTower)
					{
						num++;
					}
					else if (item.SiegeEngine == DefaultSiegeEngineTypes.Trebuchet || item.SiegeEngine == DefaultSiegeEngineTypes.Onager || item.SiegeEngine == DefaultSiegeEngineTypes.Ballista)
					{
						num2++;
					}
					else if (item.SiegeEngine == DefaultSiegeEngineTypes.FireOnager || item.SiegeEngine == DefaultSiegeEngineTypes.FireBallista)
					{
						num3++;
					}
				}
				float num4 = 4f + (float)(wallLevel - 1);
				if (settlement.SettlementTotalWallHitPoints < 1E-05f)
				{
					num4 *= 0.25f;
				}
				float num5 = 1f + num4;
				float num6 = 1f + ((flag || num > 0) ? 0.25f : 0f) + (flag2 ? 0.24f : (flag ? 0.16f : 0f)) + ((num > 1) ? 0.24f : ((num == 1) ? 0.16f : 0f)) + (float)num2 * 0.08f + (float)num3 * 0.12f;
				float baseNumber = num5 / num6;
				ExplainedNumber effectiveAdvantage = new ExplainedNumber(baseNumber);
				ISiegeEventSide siegeEventSide = settlement.SiegeEvent.GetSiegeEventSide(BattleSideEnum.Attacker);
				CalculateSettlementAdvantagePerkEffects(settlement, ref effectiveAdvantage, siegeEventSide);
				return effectiveAdvantage.ResultNumber;
			}
			if (settlement.IsVillage)
			{
				return 1.25f;
			}
			return 1f;
		}

		private static void CalculateSettlementAdvantagePerkEffects(Settlement settlement, ref ExplainedNumber effectiveAdvantage, ISiegeEventSide opposingSide)
		{
			if (opposingSide.GetInvolvedPartiesForEventType().Any((PartyBase x) => x.MobileParty.HasPerk(DefaultPerks.Tactics.OnTheMarch) && !x.MobileParty.IsCurrentlyAtSea))
			{
				effectiveAdvantage.AddFactor(DefaultPerks.Tactics.OnTheMarch.PrimaryBonus, DefaultPerks.Tactics.OnTheMarch.Name);
			}
			if (PerkHelper.GetPerkValueForTown(DefaultPerks.Tactics.OnTheMarch, settlement.Town))
			{
				PerkHelper.AddPerkBonusForTown(DefaultPerks.Tactics.OnTheMarch, settlement.Town, ref effectiveAdvantage);
			}
		}

		public override (int defenderRounds, int attackerRounds) GetSimulationTicksForBattleRound(MapEvent mapEvent)
		{
			MapEvent.BattleTypes eventType = mapEvent.EventType;
			Settlement mapEventSettlement = mapEvent.MapEventSettlement;
			int item = 0;
			int item2 = 0;
			int numRemainingSimulationTroops = mapEvent.DefenderSide.NumRemainingSimulationTroops;
			int numRemainingSimulationTroops2 = mapEvent.AttackerSide.NumRemainingSimulationTroops;
			if (!mapEvent.IsInvulnerable)
			{
				if (eventType == MapEvent.BattleTypes.Siege && mapEventSettlement.CurrentSiegeState != Settlement.SiegeState.InTheLordsHall && ((mapEventSettlement.IsTown && numRemainingSimulationTroops > 100) || (mapEventSettlement.IsCastle && numRemainingSimulationTroops > 30)))
				{
					float num = GetSettlementAdvantage(mapEventSettlement) * 0.7f;
					item2 = TaleWorlds.Library.MathF.Round(1.5f + TaleWorlds.Library.MathF.Pow(numRemainingSimulationTroops, 0.3f)) * 2;
					item = TaleWorlds.Library.MathF.Round(0.5f + TaleWorlds.Library.MathF.Max(1f + TaleWorlds.Library.MathF.Pow(numRemainingSimulationTroops, 0.3f) * num, (float)((numRemainingSimulationTroops + 1) / (numRemainingSimulationTroops2 + 1)))) * 2;
				}
				else if (numRemainingSimulationTroops <= 10)
				{
					item = Math.Max(TaleWorlds.Library.MathF.Round(TaleWorlds.Library.MathF.Min((float)numRemainingSimulationTroops2 * 3f, (float)numRemainingSimulationTroops * 0.3f)), 1);
					item2 = Math.Max(TaleWorlds.Library.MathF.Round(TaleWorlds.Library.MathF.Min((float)numRemainingSimulationTroops * 3f, (float)numRemainingSimulationTroops2 * 0.3f)), 1);
				}
				else
				{
					item = TaleWorlds.Library.MathF.Round(TaleWorlds.Library.MathF.Min((float)numRemainingSimulationTroops2 * 2f, TaleWorlds.Library.MathF.Pow(numRemainingSimulationTroops, 0.6f)));
					item2 = TaleWorlds.Library.MathF.Round(TaleWorlds.Library.MathF.Min((float)numRemainingSimulationTroops * 2f, TaleWorlds.Library.MathF.Pow(numRemainingSimulationTroops2, 0.6f)));
				}
				if (mapEvent.RetreatingSide != BattleSideEnum.None)
				{
					if (mapEvent.RetreatingSide == BattleSideEnum.Attacker)
					{
						item2 = 0;
					}
					else
					{
						item = 0;
					}
				}
			}
			return (defenderRounds: item, attackerRounds: item2);
		}

		public override void GetBattleAdvantage(MapEvent mapEvent, out ExplainedNumber defenderAdvantage, out ExplainedNumber attackerAdvantage)
		{
			defenderAdvantage = GetPartyBattleAdvantage(mapEvent, mapEvent.DefenderSide.LeaderParty, mapEvent.AttackerSide.LeaderParty);
			attackerAdvantage = GetPartyBattleAdvantage(mapEvent, mapEvent.AttackerSide.LeaderParty, mapEvent.DefenderSide.LeaderParty);
			if (mapEvent.EventType == MapEvent.BattleTypes.Siege)
			{
				attackerAdvantage.AddFactor(-0.1f);
			}
		}

		private static ExplainedNumber GetPartyBattleAdvantage(MapEvent mapEvent, PartyBase party, PartyBase opposingParty)
		{
			ExplainedNumber explainedNumber = new ExplainedNumber(1f);
			if (party.LeaderHero != null)
			{
				if (!mapEvent.IsNavalMapEvent)
				{
					SkillHelper.AddSkillBonusForCharacter(DefaultSkillEffects.TacticsAdvantage, party.LeaderHero.CharacterObject, ref explainedNumber);
				}
				if (party.IsMobile && opposingParty.Culture.IsBandit && !party.MobileParty.IsCurrentlyAtSea)
				{
					PerkHelper.AddPerkBonusForParty(DefaultPerks.Scouting.Patrols, party.MobileParty, isPrimaryBonus: false, ref explainedNumber);
				}
			}
			if (party.IsMobile && !party.MobileParty.IsCurrentlyAtSea && opposingParty.IsMobile && party.LeaderHero != null && opposingParty.LeaderHero != null && party.MobileParty.HasPerk(DefaultPerks.Tactics.PreBattleManeuvers, checkSecondaryRole: true))
			{
				int num = party.LeaderHero.GetSkillValue(DefaultSkills.Tactics) - opposingParty.LeaderHero.GetSkillValue(DefaultSkills.Tactics);
				if (num > 0)
				{
					explainedNumber.Add((float)num * 0.01f);
				}
			}
			return explainedNumber;
		}

