	public class DefaultCombatXpModel : CombatXpModel
	{
		public override float CaptainRadius => 10f;

		public override SkillObject GetSkillForWeapon(WeaponComponentData weapon, bool isSiegeEngineHit)
		{
			SkillObject result = DefaultSkills.Athletics;
			if (isSiegeEngineHit)
			{
				result = DefaultSkills.Engineering;
			}
			else if (weapon != null)
			{
				result = weapon.RelevantSkill;
			}
			return result;
		}

		public override ExplainedNumber GetXpFromHit(CharacterObject attackerTroop, CharacterObject captain, CharacterObject attackedTroop, PartyBase attackerParty, int damage, bool isFatal, MissionTypeEnum missionType)
		{
			int num = attackedTroop.MaxHitPoints();
			float leaderModifier = 0f;
			BattleSideEnum side = BattleSideEnum.Attacker;
			MapEvent.PowerCalculationContext context = MapEvent.PowerCalculationContext.PlainBattle;
			if (attackerParty?.MapEvent != null)
			{
				leaderModifier = attackerParty.MapEventSide.LeaderSimulationModifier;
				side = attackerParty.Side;
				context = attackerParty.MapEvent.SimulationContext;
			}
			float troopPower = Campaign.Current.Models.MilitaryPowerModel.GetTroopPower(attackedTroop, side.GetOppositeSide(), context, leaderModifier);
			float num2 = Campaign.Current.Models.MilitaryPowerModel.GetTroopPower(attackerTroop, side, context, leaderModifier) + 0.5f;
			float num3 = troopPower + 0.5f;
			int num4 = TaleWorlds.Library.MathF.Min(damage, num) + (isFatal ? num : 0);
			float num5 = 0.4f * num2 * num3 * (float)num4;
			num5 *= GetXpfMultiplierForMissionType(missionType);
			ExplainedNumber xpToGain = new ExplainedNumber(num5);
			if (attackerParty != null)
			{
				GetBattleXpBonusFromPerks(attackerParty, ref xpToGain, attackerTroop);
			}
			bool flag = attackerParty == null || !attackerParty.IsMobile || attackerParty.MobileParty.IsCurrentlyAtSea;
			if (captain != null && captain.IsHero && !flag && captain.GetPerkValue(DefaultPerks.Leadership.InspiringLeader))
			{
				xpToGain.AddFactor(DefaultPerks.Leadership.InspiringLeader.SecondaryBonus, DefaultPerks.Leadership.InspiringLeader.Name);
			}
			return xpToGain;
		}

		private static float GetXpfMultiplierForMissionType(MissionTypeEnum missionType)
		{
			return missionType switch
			{
				MissionTypeEnum.NoXp => 0f, 
				MissionTypeEnum.PracticeFight => 0.0625f, 
				MissionTypeEnum.Tournament => 0.33f, 
				MissionTypeEnum.SimulationBattle => 0.9f, 
				MissionTypeEnum.Battle => 1f, 
				_ => 1f, 
			};
		}

		public override float GetXpMultiplierFromShotDifficulty(float shotDifficulty)
		{
			if (shotDifficulty > 14.4f)
			{
				shotDifficulty = 14.4f;
			}
			return MBMath.Lerp(0f, 2f, (shotDifficulty - 1f) / 13.4f);
		}

		private static void GetBattleXpBonusFromPerks(PartyBase party, ref ExplainedNumber xpToGain, CharacterObject troop)
		{
			if (party.IsMobile && party.MobileParty.LeaderHero != null)
			{
				if (!troop.IsRanged)
				{
					if (!party.MobileParty.IsCurrentlyAtSea && party.MobileParty.HasPerk(DefaultPerks.OneHanded.Trainer, checkSecondaryRole: true))
					{
						xpToGain.AddFactor(DefaultPerks.OneHanded.Trainer.SecondaryBonus, DefaultPerks.OneHanded.Trainer.Name);
					}
					PerkHelper.AddPerkBonusForParty(DefaultPerks.TwoHanded.BaptisedInBlood, party.MobileParty, isPrimaryBonus: false, ref xpToGain, party.MobileParty.IsCurrentlyAtSea);
				}
				if (troop.HasThrowingWeapon() && party.MobileParty.HasPerk(DefaultPerks.Throwing.Resourceful, checkSecondaryRole: true))
				{
					xpToGain.AddFactor(DefaultPerks.Throwing.Resourceful.SecondaryBonus, DefaultPerks.Throwing.Resourceful.Name);
				}
				if (troop.IsInfantry)
				{
					PerkHelper.AddPerkBonusForParty(DefaultPerks.OneHanded.CorpsACorps, party.MobileParty, isPrimaryBonus: true, ref xpToGain, party.MobileParty.IsCurrentlyAtSea);
				}
				PerkHelper.AddPerkBonusForParty(DefaultPerks.OneHanded.LeadByExample, party.MobileParty, isPrimaryBonus: true, ref xpToGain, party.MobileParty.IsCurrentlyAtSea);
				if (troop.IsRanged)
				{
					PerkHelper.AddPerkBonusForParty(DefaultPerks.Crossbow.MountedCrossbowman, party.MobileParty, isPrimaryBonus: false, ref xpToGain, party.MobileParty.IsCurrentlyAtSea);
					PerkHelper.AddPerkBonusForParty(DefaultPerks.Bow.BullsEye, party.MobileParty, isPrimaryBonus: true, ref xpToGain, party.MobileParty.IsCurrentlyAtSea);
				}
				if (troop.Culture.IsBandit && party.MobileParty.HasPerk(DefaultPerks.Roguery.NoRestForTheWicked))
				{
					xpToGain.AddFactor(DefaultPerks.Roguery.NoRestForTheWicked.PrimaryBonus, DefaultPerks.Roguery.NoRestForTheWicked.Name);
				}
			}
			if (party.IsMobile && party.MobileParty.IsGarrison && party.MobileParty.CurrentSettlement?.Town.Governor != null)
			{
				PerkHelper.AddPerkBonusForTown(DefaultPerks.TwoHanded.ProjectileDeflection, party.MobileParty.CurrentSettlement.Town, ref xpToGain);
				if (troop.IsMounted)
				{
					PerkHelper.AddPerkBonusForTown(DefaultPerks.Polearm.Guards, party.MobileParty.CurrentSettlement.Town, ref xpToGain);
				}
			}
		}
	}
	public class DefaultCompanionHiringPriceCalculationModel : CompanionHiringPriceCalculationModel
	{
		public override int GetCompanionHiringPrice(Hero companion)
		{
			ExplainedNumber stat = new ExplainedNumber(0f, includeDescriptions: false, null);
			Town town = companion.CurrentSettlement?.Town;
			if (town == null)
			{
				town = SettlementHelper.FindNearestTownToMobileParty(MobileParty.MainParty, MobileParty.NavigationType.All);
			}
			float num = 0f;
			for (EquipmentIndex equipmentIndex = EquipmentIndex.WeaponItemBeginSlot; equipmentIndex < EquipmentIndex.NumEquipmentSetSlots; equipmentIndex++)
			{
				EquipmentElement itemRosterElement = companion.CharacterObject.Equipment[equipmentIndex];
				if (itemRosterElement.Item != null)
				{
					num += (float)town.GetItemPrice(itemRosterElement);
				}
			}
			for (EquipmentIndex equipmentIndex2 = EquipmentIndex.WeaponItemBeginSlot; equipmentIndex2 < EquipmentIndex.NumEquipmentSetSlots; equipmentIndex2++)
			{
				EquipmentElement itemRosterElement2 = companion.CharacterObject.FirstCivilianEquipment[equipmentIndex2];
				if (itemRosterElement2.Item != null)
				{
					num += (float)town.GetItemPrice(itemRosterElement2);
				}
			}
			stat.Add(num / 2f);
			stat.Add(companion.CharacterObject.Level * 10);
			if (Hero.MainHero.IsPartyLeader && Hero.MainHero.GetPerkValue(DefaultPerks.Steward.PaidInPromise))
			{
				stat.AddFactor(DefaultPerks.Steward.PaidInPromise.PrimaryBonus);
			}
			if (Hero.MainHero.PartyBelongedTo != null)
			{
				PerkHelper.AddPerkBonusForParty(DefaultPerks.Trade.GreatInvestor, Hero.MainHero.PartyBelongedTo, isPrimaryBonus: false, ref stat);
			}
			return (int)stat.ResultNumber;
		}
	}
	public class DefaultCrimeModel : CrimeModel
	{
		private const float ModerateCrimeRatingThreshold = 30f;

		private const float SevereCrimeRatingThreshold = 65f;

		public override float DeclareWarCrimeRatingThreshold => 60f;

		public override bool DoesPlayerHaveAnyCrimeRating(IFaction faction)
		{
			return faction.MainHeroCrimeRating > 0f;
		}

		public override bool IsPlayerCrimeRatingSevere(IFaction faction)
		{
			return faction.MainHeroCrimeRating >= 65f;
		}

		public override bool IsPlayerCrimeRatingModerate(IFaction faction)
		{
			if (faction.MainHeroCrimeRating > 30f)
			{
				return faction.MainHeroCrimeRating <= 65f;
			}
			return false;
		}

		public override bool IsPlayerCrimeRatingMild(IFaction faction)
		{
			if (faction.MainHeroCrimeRating > 0f)
			{
				return faction.MainHeroCrimeRating <= 30f;
			}
			return false;
		}

		public override float GetCost(IFaction faction, PaymentMethod paymentMethod, float minimumCrimeRating)
		{
			float x = TaleWorlds.Library.MathF.Max(0f, faction.MainHeroCrimeRating - minimumCrimeRating);
			return paymentMethod switch
			{
				PaymentMethod.Gold => (int)(TaleWorlds.Library.MathF.Pow(x, 1.2f) * 100f), 
				PaymentMethod.Influence => TaleWorlds.Library.MathF.Pow(x, 1.2f), 
				_ => 0f, 
			};
		}

		public override ExplainedNumber GetDailyCrimeRatingChange(IFaction faction, bool includeDescriptions = false)
		{
			ExplainedNumber bonuses = new ExplainedNumber(0f, includeDescriptions);
			int num = faction.Settlements.Count((Settlement x) => x.IsTown && x.Alleys.Any((Alley y) => y.Owner == Hero.MainHero));
			bonuses.Add((float)num * Campaign.Current.Models.AlleyModel.GetDailyCrimeRatingOfAlley, includeDescriptions ? new TextObject("{=t87T82jq}Owned alleys") : null);
			if (faction.MainHeroCrimeRating.ApproximatelyEqualsTo(0f))
			{
				return bonuses;
			}
			Clan clan = faction as Clan;
			if (Hero.MainHero.Clan == faction)
			{
				bonuses.Add(-5f, includeDescriptions ? new TextObject("{=eNtRt6F5}Your own Clan") : null);
			}
			else if (faction.IsKingdomFaction && faction.Leader == Hero.MainHero)
			{
				bonuses.Add(-5f, includeDescriptions ? new TextObject("{=xer2bta5}Your own Kingdom") : null);
			}
			else if (Hero.MainHero.MapFaction == faction)
			{
				bonuses.Add(-1.5f, includeDescriptions ? new TextObject("{=QRwaQIbm}Is in Kingdom") : null);
			}
			else if (clan != null && Hero.MainHero.MapFaction == clan.Kingdom)
			{
				bonuses.Add(-1.25f, includeDescriptions ? new TextObject("{=hXGByLG9}Sharing the same Kingdom") : null);
			}
			else if (Hero.MainHero.Clan.IsAtWarWith(faction))
			{
				bonuses.Add(-0.25f, includeDescriptions ? new TextObject("{=BYTrUJyj}In War") : null);
			}
			else
			{
				bonuses.Add(-1f, includeDescriptions ? new TextObject("{=basevalue}Base") : null);
			}
			PerkHelper.AddPerkBonusForCharacter(DefaultPerks.Roguery.WhiteLies, Hero.MainHero.CharacterObject, isPrimaryBonus: true, ref bonuses);
			return bonuses;
		}

		public override float GetMaxCrimeRating()
		{
			return 100f;
		}

		public override float GetMinAcceptableCrimeRating(IFaction faction)
		{
			if (faction != Hero.MainHero.MapFaction)
			{
				return 30f;
			}
			return 20f;
		}

		public override float GetCrimeRatingAfterPunishment()
		{
			return 25f;
		}
	}
