		public override DiplomacyStance GetDefaultDiplomaticStance(IFaction faction1, IFaction faction2)
		{
			if (IsAtConstantWar(faction1, faction2))
			{
				return DiplomacyStance.War;
			}
			return DiplomacyStance.Neutral;
		}

		public override bool IsAtConstantWar(IFaction faction1, IFaction faction2)
		{
			if (((faction1.IsOutlaw && faction1.IsMinorFaction && faction2.IsKingdomFaction) || (faction2.IsOutlaw && faction2.IsMinorFaction && faction1.IsKingdomFaction)) && faction1.Culture == faction2.Culture)
			{
				return true;
			}
			if (GetShallowDiplomaticStance(faction1, faction2) == DiplomacyStance.War)
			{
				return true;
			}
			return false;
		}

		private static WarStats CalculateWarStatsForPeace(IFaction faction, IFaction targetFaction, IFaction evaluatingFaction)
		{
			float num = 0f;
			float num2 = 0f;
			bool flag = evaluatingFaction.MapFaction == faction.MapFaction;
			float val = faction.WarPartyComponents.Sum((WarPartyComponent x) => x.Party.EstimatedStrength);
			float num3 = (flag ? faction.Fiefs.Sum((Town x) => x.GarrisonParty?.Party.EstimatedStrength ?? 0f) : (faction.Fiefs.Sum((Town x) => x.GarrisonParty?.Party.EstimatedStrength ?? 0f) * 0.7f));
			if (faction.IsKingdomFaction)
			{
				foreach (Clan clan in ((Kingdom)faction).Clans)
				{
					if (!clan.IsUnderMercenaryService)
					{
						int partyLimitForTier = Campaign.Current.Models.ClanTierModel.GetPartyLimitForTier(clan, clan.Tier);
						num2 += (float)(partyLimitForTier * 64);
					}
				}
			}
			num += num3 + Math.Max(val, num2);
			float num4 = 0f;
			foreach (IFaction item in faction.FactionsAtWarWith.Where((IFaction x) => x != targetFaction))
			{
				float num5 = 0f;
				if (item.IsBanditFaction || (item.IsMinorFaction && item.Leader != Hero.MainHero) || !item.IsKingdomFaction)
				{
					continue;
				}
				int num6 = 0;
				foreach (Clan item2 in ((Kingdom)item).Clans.Where((Clan x) => !x.IsUnderMercenaryService))
				{
					num6 += Campaign.Current.Models.ClanTierModel.GetPartyLimitForTier(item2, item2.Tier);
				}
				num5 += (float)(num6 * 64);
				float val2 = item.WarPartyComponents.Sum((WarPartyComponent x) => x.Party.EstimatedStrength);
				num4 += Math.Max(val2, num5);
			}
			WarStats result = default(WarStats);
			result.Strength = num;
			result.ValueOfSettlements = Campaign.Current.Models.DiplomacyModel.GetValueOfSettlementsForFaction(faction);
			result.TotalStrengthOfEnemies = (flag ? (num4 * 0.6f) : num4);
			return result;
		}

		private static WarStats CalculateWarStatsForWar(IFaction faction, IFaction targetFaction, IFaction evaluatingFaction)
		{
			float val = faction.WarPartyComponents.Sum((WarPartyComponent x) => x.Party.EstimatedStrength);
			float num = faction.Fiefs.Sum((Town x) => x.GarrisonParty?.Party.EstimatedStrength ?? 0f);
			float num2 = 0f;
			float num3 = 0f;
			bool flag = evaluatingFaction.MapFaction == faction.MapFaction;
			if (faction.IsKingdomFaction)
			{
				foreach (Clan clan in ((Kingdom)faction).Clans)
				{
					if (!clan.IsUnderMercenaryService)
					{
						int partyLimitForTier = Campaign.Current.Models.ClanTierModel.GetPartyLimitForTier(clan, clan.Tier);
						num3 += (float)(partyLimitForTier * 64);
					}
				}
			}
			num2 += num + Math.Max(val, num3);
			float num4 = 0f;
			float num5 = 0f;
			foreach (IFaction item in faction.FactionsAtWarWith.Where((IFaction x) => x.MapFaction != targetFaction.MapFaction))
			{
				if (item.IsBanditFaction || (item.IsMinorFaction && item.Leader != Hero.MainHero) || !item.IsKingdomFaction)
				{
					continue;
				}
				int num6 = 0;
				foreach (Clan item2 in ((Kingdom)item).Clans.Where((Clan x) => !x.IsUnderMercenaryService))
				{
					num6 += Campaign.Current.Models.ClanTierModel.GetPartyLimitForTier(item2, item2.Tier);
				}
				num5 += (float)(num6 * 64);
				float val2 = item.WarPartyComponents.Sum((WarPartyComponent x) => x.Party.EstimatedStrength);
				float num7 = item.Fiefs.Sum((Town x) => x.GarrisonParty?.Party.EstimatedStrength ?? 0f) + Math.Max(num5, val2);
				num4 += num7;
			}
			WarStats result = default(WarStats);
			result.Strength = num2;
			result.ValueOfSettlements = Campaign.Current.Models.DiplomacyModel.GetValueOfSettlementsForFaction(faction);
			result.TotalStrengthOfEnemies = (flag ? (num4 * 1.1f) : num4);
			return result;
		}

		private static float GetExposureScoreToOtherFaction(IFaction factionDeclaresWar, IFaction factionDeclaredWar)
		{
			HashSet<Settlement> hashSet = new HashSet<Settlement>();
			float num = 0f;
			float num2 = 0f;
			if (factionDeclaresWar.Fiefs.Count == 0 || factionDeclaredWar.Fiefs.Count == 0)
			{
				return 1f;
			}
			foreach (Town fief in factionDeclaresWar.Fiefs)
			{
				foreach (Settlement neighborFortification in fief.GetNeighborFortifications(MobileParty.NavigationType.All))
				{
					if (neighborFortification.MapFaction != factionDeclaresWar && !hashSet.Contains(neighborFortification))
					{
						if (neighborFortification.MapFaction == factionDeclaredWar)
						{
							num2 += 1f;
						}
						num += 1f;
						hashSet.Add(neighborFortification);
					}
				}
			}
			if (num2 < 1f)
			{
				return float.MinValue;
			}
			return 0.8f + num2 / num;
		}

		private static float CalculateBenefitScore(WarStats faction1Stats, WarStats faction2Stats)
		{
			float num = TaleWorlds.Library.MathF.Clamp(faction2Stats.ValueOfSettlements, 10000f, 10000000f);
			float num2 = (faction2Stats.Strength + faction1Stats.TotalStrengthOfEnemies) / faction1Stats.Strength;
			float num3 = TaleWorlds.Library.MathF.Clamp(1f / (1f + num2 * num2), 0.1f, 0.9f);
			return num * num3;
		}

		private static float CalculateRiskScore(WarStats faction1Stats, WarStats faction2Stats)
		{
			float num = TaleWorlds.Library.MathF.Clamp(faction1Stats.ValueOfSettlements, 10000f, 10000000f);
			float num2 = faction1Stats.Strength / (faction2Stats.Strength + faction1Stats.TotalStrengthOfEnemies);
			float num3 = TaleWorlds.Library.MathF.Clamp(1f / (1f + num2 * num2), 0.1f, 0.9f);
			return num * num3;
		}

		private static float AdjustValueOfSettlements(float valueOfSettlements)
		{
			if (!(valueOfSettlements > 2000000f))
			{
				return valueOfSettlements + 10000f;
			}
			return (valueOfSettlements - 2000000f) * 0.5f + 10000f + 2000000f;
		}

		private static float GetRelationScore(IFaction factionDeclaresWar, IFaction factionDeclaredWar, IFaction evaluatingFaction)
		{
			int relationWithClan = factionDeclaresWar.Leader.Clan.GetRelationWithClan(factionDeclaredWar.Leader.Clan);
			int relationWithClan2 = evaluatingFaction.Leader.Clan.GetRelationWithClan(factionDeclaredWar.Leader.Clan);
			float num = (float)(relationWithClan + relationWithClan2) / 2f;
			float result = 0f;
			if (num < 0f)
			{
				if (factionDeclaresWar.CurrentTotalStrength > factionDeclaredWar.CurrentTotalStrength * 2f)
				{
					result = -250f * num;
				}
				else
				{
					float num2 = factionDeclaresWar.CurrentTotalStrength / (2f * factionDeclaredWar.CurrentTotalStrength);
					result = -250f * (num2 * num2) * num;
				}
			}
			return result;
		}

		private static float GetSameCultureTownScore(IFaction factionDeclaresWar, IFaction factionDeclaredWar)
		{
			float b = factionDeclaredWar.Settlements.Sum((Settlement s) => (s.Culture != factionDeclaresWar.Culture || !s.IsFortification) ? 0f : (s.Town.Prosperity * 0.5f * 50f));
			float num = TaleWorlds.Library.MathF.Min(100000f, b);
			return 0.3f * num;
		}

		private static void UpdateOurBenefitMinusOurRiskBasedOnEvaluatingFaction(IFaction evaluatingFaction, ref float ourBenefit, ref float ourRisk)
		{
			if (!ourBenefit.ApproximatelyEqualsTo(ourRisk) && !evaluatingFaction.IsKingdomFaction && evaluatingFaction.Leader != evaluatingFaction.MapFaction.Leader)
			{
				bool flag = ourBenefit > ourRisk;
				if (flag && evaluatingFaction.Leader.GetTraitLevel(DefaultTraits.Valor) != 0)
				{
					ourBenefit *= 1f - 0.05f * (float)TaleWorlds.Library.MathF.Min(2, TaleWorlds.Library.MathF.Max(-2, evaluatingFaction.Leader.GetTraitLevel(DefaultTraits.Valor)));
				}
				else if (!flag && evaluatingFaction.Leader.GetTraitLevel(DefaultTraits.Calculating) != 0)
				{
					ourRisk *= 1f + 0.05f * (float)TaleWorlds.Library.MathF.Min(2, TaleWorlds.Library.MathF.Max(-2, evaluatingFaction.Leader.GetTraitLevel(DefaultTraits.Calculating)));
				}
			}
		}
	}
	public class DefaultDisguiseDetectionModel : DisguiseDetectionModel
	{
		public override float CalculateDisguiseDetectionProbability(Settlement settlement)
		{
			float num = 0f;
			int num2 = 0;
			if (settlement.Town != null && settlement.Town.GarrisonParty != null)
			{
				foreach (TroopRosterElement item in settlement.Town.GarrisonParty.MemberRoster.GetTroopRoster())
				{
					num2 += item.Number;
					num += (float)(item.Number * item.Character.Level);
				}
			}
			num /= (float)TaleWorlds.Library.MathF.Max(1, num2);
			float num3 = 0.3f + 0.003f * (float)Hero.MainHero.GetSkillValue(DefaultSkills.Roguery) - 0.005f * num - TaleWorlds.Library.MathF.Max(0.15f, 0.00015f * Clan.PlayerClan.Renown);
			if (Hero.MainHero.CharacterObject.GetPerkValue(DefaultPerks.Roguery.TwoFaced) && num3 > 0f)
			{
				num3 += num3 * DefaultPerks.Roguery.TwoFaced.PrimaryBonus;
			}
			return TaleWorlds.Library.MathF.Clamp(num3, 0f, 1f);
		}
	}
	public class DefaultEmissaryModel : EmissaryModel
	{
		public override int EmissaryRelationBonusForMainClan => 5;

		public override bool IsEmissary(Hero hero)
		{
			if ((hero.CompanionOf == Clan.PlayerClan || hero.Clan == Clan.PlayerClan) && hero.PartyBelongedTo == null && hero.CurrentSettlement != null && hero.CurrentSettlement.IsFortification && !hero.IsPrisoner)
			{
				return hero.Age >= (float)Campaign.Current.Models.AgeModel.HeroComesOfAge;
			}
			return false;
		}
	}
	public class DefaultEncounterGameMenuModel : EncounterGameMenuModel
	{
		public override string GetEncounterMenu(PartyBase attackerParty, PartyBase defenderParty, out bool startBattle, out bool joinBattle)
		{
			PartyBase encounteredPartyBase = MapEventHelper.GetEncounteredPartyBase(attackerParty, defenderParty);
			joinBattle = false;
			startBattle = false;
			if (defenderParty == null)
			{
				return "camp";
			}
			if (encounteredPartyBase.IsSettlement)
			{
				Settlement settlement = encounteredPartyBase.Settlement;
				if (settlement.IsVillage)
				{
					if (encounteredPartyBase.MapEvent != null && encounteredPartyBase.MapEvent.IsRaid)
					{
						if (settlement.LastAttackerParty != null && settlement.LastAttackerParty != MobileParty.MainParty && MobileParty.MainParty.MapFaction.IsAtWarWith(settlement.MapFaction))
						{
							return "raid_occupied";
						}
						if (MobileParty.MainParty.Army != null && MobileParty.MainParty.Army.LeaderParty != MobileParty.MainParty && encounteredPartyBase.MapEvent.AttackerSide.LeaderParty == MobileParty.MainParty.Army.LeaderParty.Party && encounteredPartyBase.MapEvent.DefenderSide.TroopCount <= 0)
						{
							joinBattle = true;
							if (!encounteredPartyBase.MapEvent.IsRaid)
							{
								return "army_wait";
							}
							return "raiding_village";
						}
						if ((MobileParty.MainParty.Army != null && MobileParty.MainParty.Army.LeaderParty != MobileParty.MainParty && attackerParty == MobileParty.MainParty.Army.LeaderParty.Party) || (MobileParty.MainParty.CurrentSettlement == settlement && MobileParty.MainParty.MapFaction == settlement.MapFaction))
						{
							joinBattle = true;
							return "encounter";
						}
						return "join_encounter";
					}
					if (settlement.MapFaction == MobileParty.MainParty.MapFaction && MobileParty.MainParty.Army != null && attackerParty == MobileParty.MainParty.Army.LeaderParty.Party && MobileParty.MainParty.Army.LeaderParty != MobileParty.MainParty)
					{
						return "army_wait_at_settlement";
					}
					return "village_outside";
				}
				if (settlement.IsFortification)
				{
					if (PlayerSiege.PlayerSiegeEvent != null && PlayerSiege.PlayerSide == BattleSideEnum.Defender && settlement.Party.MapEvent == null)
					{
						return "menu_siege_strategies";
					}
					if (settlement.Party.SiegeEvent != null && ((settlement.Party.MapEvent == null && (settlement.Town.GarrisonParty == null || settlement.Town.GarrisonParty.MapEvent == null || settlement.Town.GarrisonParty.MapEvent.IsSallyOut)) || MobileParty.MainParty.MapFaction == settlement.MapFaction))
					{
						if (settlement.Party.SiegeEvent.BesiegerCamp.LeaderParty == MobileParty.MainParty)
						{
							return "continue_siege_after_attack";
						}
						if (MobileParty.MainParty.BesiegedSettlement == null && MobileParty.MainParty.CurrentSettlement == null)
						{
							if (settlement.Party.SiegeEvent.BesiegerCamp.LeaderParty.MapEvent != null && (settlement.Party.SiegeEvent.BesiegerCamp.LeaderParty.MapEvent.IsSiegeOutside || settlement.Party.SiegeEvent.BesiegerCamp.LeaderParty.MapEvent.IsSallyOut || settlement.Party.SiegeEvent.BesiegerCamp.LeaderParty.MapEvent.IsBlockade))
							{
								return "join_encounter";
							}
							if (MobileParty.MainParty.IsCurrentlyAtSea)
							{
								if (!settlement.Party.SiegeEvent.IsBlockadeActive || settlement.Party.SiegeEvent.BesiegerCamp.LeaderParty.MapEvent == null)
								{
									return "naval_town_outside";
								}
								return "join_encounter";
							}
							return "join_siege_event";
						}
					}
					if (settlement.Party.MapEvent != null)
					{
						if ((MobileParty.MainParty.Army != null && MobileParty.MainParty.Army.LeaderParty != MobileParty.MainParty && attackerParty == MobileParty.MainParty.Army.LeaderParty.Party) || (MobileParty.MainParty.CurrentSettlement == settlement && settlement.Party.MapEvent.CanPartyJoinBattle(PartyBase.MainParty, settlement.BattleSide)))
						{
							return "encounter";
						}
						if (MobileParty.MainParty.IsCurrentlyAtSea)
						{
							if (!settlement.Party.SiegeEvent.IsBlockadeActive || settlement.Party.SiegeEvent.BesiegerCamp.LeaderParty.MapEvent == null)
							{
								return "naval_town_outside";
							}
							return "join_encounter";
						}
						return "join_siege_event";
					}
					if (settlement.MapFaction == MobileParty.MainParty.MapFaction && MobileParty.MainParty.Army != null && MobileParty.MainParty.Army.LeaderParty != MobileParty.MainParty)
					{
						return "army_wait_at_settlement";
					}
					if (settlement.IsCastle)
					{
						return "castle_outside";
					}
					if (MobileParty.MainParty.IsCurrentlyAtSea)
					{
						return "naval_town_outside";
					}
					return "town_outside";
				}
				if (settlement.IsHideout)
				{
					return "hideout_place";
				}
				if (settlement.SettlementComponent is RetirementSettlementComponent)
				{
					return "retirement_place";
				}
				return "";
			}
			if (encounteredPartyBase.MapEvent != null)
			{
				if (MobileParty.MainParty.CurrentSettlement != null || (MobileParty.MainParty.Army != null && MobileParty.MainParty.Army.LeaderParty != MobileParty.MainParty))
				{
					if ((encounteredPartyBase.MapEvent.IsBlockade || encounteredPartyBase.MapEvent.IsBlockadeSallyOut) && !Settlement.CurrentSettlement.SiegeEvent.IsBlockadeActive)
					{
						startBattle = false;
						joinBattle = false;
						return "besiegers_lift_the_blockade";
					}
					joinBattle = true;
					return "encounter";
				}
				if (encounteredPartyBase.SiegeEvent != null && encounteredPartyBase.MapEvent.IsSiegeAssault)
				{
					if (MobileParty.MainParty.IsCurrentlyAtSea)
					{
						if (!encounteredPartyBase.SiegeEvent.IsBlockadeActive || encounteredPartyBase.SiegeEvent.BesiegerCamp.LeaderParty.MapEvent == null)
						{
							return "naval_town_outside";
						}
						return "join_encounter";
					}
					return "join_siege_event";
				}
				Settlement mapEventSettlement = encounteredPartyBase.MapEvent.MapEventSettlement;
				if (mapEventSettlement != null && mapEventSettlement.IsVillage && mapEventSettlement.IsUnderRaid && mapEventSettlement.LastAttackerParty != null && mapEventSettlement.LastAttackerParty != MobileParty.MainParty && !MobileParty.MainParty.MapFaction.IsAtWarWith(defenderParty.MapFaction))
				{
					return "raid_occupied";
				}
				return "join_encounter";
			}
			if (encounteredPartyBase.IsMobile)
			{
				if ((encounteredPartyBase.MobileParty.IsGarrison && MobileParty.MainParty.BesiegedSettlement != null) || (MobileParty.MainParty.CurrentSettlement != null && encounteredPartyBase.MobileParty.BesiegedSettlement == MobileParty.MainParty.CurrentSettlement))
				{
					if (PlayerEncounter.Current.ForceBlockadeSallyOutAttack && !Settlement.CurrentSettlement.SiegeEvent.IsBlockadeActive)
					{
						startBattle = false;
						joinBattle = false;
						return "besiegers_lift_the_blockade";
					}
					startBattle = true;
					joinBattle = false;
					if (encounteredPartyBase.MobileParty.IsGarrison && encounteredPartyBase.MobileParty.IsTargetingPort)
					{
						return "player_blockade_got_attacked";
					}
					return "encounter";
				}
				if (encounteredPartyBase.SiegeEvent != null)
				{
					if (MobileParty.MainParty.IsCurrentlyAtSea)
					{
						if (!encounteredPartyBase.SiegeEvent.IsBlockadeActive || encounteredPartyBase.SiegeEvent.BesiegerCamp.LeaderParty.MapEvent == null)
						{
							return "naval_town_outside";
						}
						return "join_encounter";
					}
					return "join_siege_event";
				}
				return "encounter_meeting";
			}
			return null;
		}

