	public class DefaultInformationRestrictionModel : InformationRestrictionModel
	{
		public bool IsDisabledByCheat;

		public override bool DoesPlayerKnowDetailsOf(Settlement settlement)
		{
			if (settlement.MapFaction == PartyBase.MainParty.MapFaction || settlement.IsInspected)
			{
				return true;
			}
			Settlement settlement2 = (settlement.IsVillage ? settlement.Village.Bound : settlement);
			if (!settlement2.IsFortification)
			{
				return true;
			}
			EmissaryModel emissaryModel = Campaign.Current.Models.EmissaryModel;
			foreach (Hero hero in Clan.PlayerClan.Heroes)
			{
				if (emissaryModel.IsEmissary(hero) && hero.CurrentSettlement == settlement2)
				{
					return true;
				}
			}
			foreach (Workshop ownedWorkshop in Hero.MainHero.OwnedWorkshops)
			{
				if (ownedWorkshop.Settlement == settlement2)
				{
					return true;
				}
			}
			foreach (Alley ownedAlley in Hero.MainHero.OwnedAlleys)
			{
				if (ownedAlley.Settlement == settlement2)
				{
					return true;
				}
			}
			if (IsDisabledByCheat)
			{
				return true;
			}
			return false;
		}

		public override bool DoesPlayerKnowDetailsOf(Hero hero)
		{
			if (hero.Clan != Clan.PlayerClan && !hero.IsDead && (hero.MapFaction == null || !hero.MapFaction.IsKingdomFaction || hero.MapFaction.Leader != hero) && !hero.IsKnownToPlayer)
			{
				return IsDisabledByCheat;
			}
			return true;
		}
	}
	public class DefaultInventoryCapacityModel : InventoryCapacityModel
	{
		private const int _itemAverageWeight = 10;

		private const float TroopsFactor = 2f;

		private const float SpareMountsFactor = 2f;

		private const float PackAnimalsFactor = 10f;

		private static readonly TextObject _textTroops = new TextObject("{=5k4dxUEJ}Troops");

		private static readonly TextObject _textBase = new TextObject("{=basevalue}Base");

		private static readonly TextObject _textSpareMounts = new TextObject("{=rCiKbsyW}Spare Mounts");

		private static readonly TextObject _textPackAnimals = new TextObject("{=dI1AOyqh}Pack Animals");

		private static readonly TextObject _textMountsAndPackAnimals = new TextObject("{=Sb1MKbvP}Mounts and Pack Animals");

		private static readonly TextObject _textLiveStocksAnimals = new TextObject("{=KxUgSAKi}Live Stock Animals");

		private static readonly TextObject _textItems = new TextObject("{=U7er3V9s}Items");

		public override int GetItemAverageWeight()
		{
			return 10;
		}

		public override float GetItemEffectiveWeight(EquipmentElement equipmentElement, MobileParty mobileParty, bool isCurrentlyAtSea, out TextObject description)
		{
			if (equipmentElement.Item.HasHorseComponent)
			{
				description = _textMountsAndPackAnimals;
				return 0f;
			}
			description = _textItems;
			return equipmentElement.GetEquipmentElementWeight();
		}

		public override ExplainedNumber CalculateInventoryCapacity(MobileParty mobileParty, bool isCurrentlyAtSea, bool includeDescriptions = false, int additionalTroops = 0, int additionalSpareMounts = 0, int additionalPackAnimals = 0, bool includeFollowers = false)
		{
			ExplainedNumber result = new ExplainedNumber(0f, includeDescriptions);
			PartyBase party = mobileParty.Party;
			int num = party.NumberOfMounts;
			int num2 = party.NumberOfHealthyMembers;
			int num3 = party.NumberOfPackAnimals;
			if (includeFollowers)
			{
				foreach (MobileParty attachedParty in mobileParty.AttachedParties)
				{
					num += attachedParty.Party.NumberOfMounts;
					num2 += attachedParty.Party.NumberOfHealthyMembers;
					num3 += attachedParty.Party.NumberOfPackAnimals;
				}
			}
			if (mobileParty.HasPerk(DefaultPerks.Steward.ArenicosHorses) && !isCurrentlyAtSea)
			{
				num2 += TaleWorlds.Library.MathF.Round((float)num2 * DefaultPerks.Steward.ArenicosHorses.PrimaryBonus);
			}
			if (!mobileParty.IsCurrentlyAtSea && mobileParty.HasPerk(DefaultPerks.Steward.ForcedLabor))
			{
				num2 += party.PrisonRoster.TotalHealthyCount;
			}
			result.Add(10f, _textBase);
			result.Add((float)num2 * 2f * 10f, _textTroops);
			if (!isCurrentlyAtSea)
			{
				result.Add((float)num * 2f * 10f, _textSpareMounts);
				ExplainedNumber explainedNumber = new ExplainedNumber((float)num3 * 10f * 10f);
				if (mobileParty.HasPerk(DefaultPerks.Scouting.BeastWhisperer, checkSecondaryRole: true))
				{
					explainedNumber.AddFactor(DefaultPerks.Scouting.BeastWhisperer.SecondaryBonus, DefaultPerks.Scouting.BeastWhisperer.Name);
				}
				if (mobileParty.HasPerk(DefaultPerks.Riding.DeeperSacks))
				{
					explainedNumber.AddFactor(DefaultPerks.Riding.DeeperSacks.PrimaryBonus, DefaultPerks.Riding.DeeperSacks.Name);
				}
				if (mobileParty.HasPerk(DefaultPerks.Steward.ArenicosMules))
				{
					explainedNumber.AddFactor(DefaultPerks.Steward.ArenicosMules.PrimaryBonus, DefaultPerks.Steward.ArenicosMules.Name);
				}
				result.Add(explainedNumber.ResultNumber, _textPackAnimals);
				if (mobileParty.HasPerk(DefaultPerks.Trade.CaravanMaster))
				{
					result.AddFactor(DefaultPerks.Trade.CaravanMaster.PrimaryBonus, DefaultPerks.Trade.CaravanMaster.Name);
				}
			}
			result.LimitMin(10f);
			return result;
		}

		public override ExplainedNumber CalculateTotalWeightCarried(MobileParty mobileParty, bool isCurrentlyAtSea, bool includeDescriptions = false)
		{
			ExplainedNumber result = new ExplainedNumber(0f, includeDescriptions, _textItems);
			InventoryCapacityModel inventoryCapacityModel = Campaign.Current.Models.InventoryCapacityModel;
			foreach (ItemRosterElement item in mobileParty.ItemRoster)
			{
				TextObject description;
				float itemEffectiveWeight = inventoryCapacityModel.GetItemEffectiveWeight(item.EquipmentElement, mobileParty, isCurrentlyAtSea, out description);
				result.Add(itemEffectiveWeight * (float)item.Amount, description);
			}
			return result;
		}
	}
	public class DefaultIssueModel : IssueModel
	{
		private static readonly TextObject SettlementIssuesText = new TextObject("{=EQLgVYk0}Settlement Issues");

		private static readonly TextObject HeroIssueText = GameTexts.FindText("str_issues");

		private static readonly TextObject RelatedSettlementIssuesText = new TextObject("{=umNyHc3A}Bound Village Issues");

		private static readonly TextObject ClanIssuesText = new TextObject("{=jdl8G8JS}Clan Issues");

		public override int IssueOwnerCoolDownInDays => 30;

		public override float GetIssueDifficultyMultiplier()
		{
			return MBMath.ClampFloat(Campaign.Current.PlayerProgress, 0.1f, 1f);
		}

		public override void GetIssueEffectsOfSettlement(IssueEffect issueEffect, Settlement settlement, ref ExplainedNumber explainedNumber)
		{
			foreach (Hero aliveLord in settlement.OwnerClan.AliveLords)
			{
				if (aliveLord.Issue != null)
				{
					GetIssueEffectOfHeroInternal(issueEffect, aliveLord, ref explainedNumber, SettlementIssuesText);
				}
			}
			foreach (Hero item in settlement.HeroesWithoutParty)
			{
				if (item.Issue != null)
				{
					GetIssueEffectOfHeroInternal(issueEffect, item, ref explainedNumber, SettlementIssuesText);
				}
			}
			if (!settlement.IsTown && !settlement.IsCastle)
			{
				return;
			}
			foreach (Village boundVillage in settlement.BoundVillages)
			{
				foreach (Hero notable in boundVillage.Settlement.Notables)
				{
					if (notable.Issue != null)
					{
						GetIssueEffectOfHeroInternal(issueEffect, notable, ref explainedNumber, RelatedSettlementIssuesText);
					}
				}
			}
		}

		public override void GetIssueEffectOfHero(IssueEffect issueEffect, Hero hero, ref ExplainedNumber explainedNumber)
		{
			GetIssueEffectOfHeroInternal(issueEffect, hero, ref explainedNumber, HeroIssueText);
		}

		public override void GetIssueEffectOfClan(IssueEffect issueEffect, Clan clan, ref ExplainedNumber explainedNumber)
		{
			float num = 0f;
			foreach (Hero aliveLord in clan.AliveLords)
			{
				if (aliveLord.Issue != null)
				{
					IssueBase issue = aliveLord.Issue;
					num += issue.GetActiveIssueEffectAmount(issueEffect);
				}
			}
			explainedNumber.Add(num, ClanIssuesText);
		}

		public override (int, int) GetCausalityForHero(Hero alternativeSolutionHero, IssueBase issue)
		{
			(SkillObject, int) issueAlternativeSolutionSkill = GetIssueAlternativeSolutionSkill(alternativeSolutionHero, issue);
			int skillValue = alternativeSolutionHero.GetSkillValue(issueAlternativeSolutionSkill.Item1);
			float value = 0.8f;
			if (skillValue != 0)
			{
				value = (float)(issueAlternativeSolutionSkill.Item2 / skillValue) * 0.1f;
			}
			value = MBMath.ClampFloat(value, 0.2f, 0.8f);
			int num = TaleWorlds.Library.MathF.Ceiling((float)issue.GetTotalAlternativeSolutionNeededMenCount() * value);
			return (MBMath.ClampInt(2 * (num / 3), 1, num), num);
		}

		public override float GetFailureRiskForHero(Hero alternativeSolutionHero, IssueBase issue)
		{
			(SkillObject, int) issueAlternativeSolutionSkill = GetIssueAlternativeSolutionSkill(alternativeSolutionHero, issue);
			return MBMath.ClampFloat((float)(issueAlternativeSolutionSkill.Item2 - alternativeSolutionHero.GetSkillValue(issueAlternativeSolutionSkill.Item1)) * 0.5f / 100f, 0f, 0.9f);
		}

		public override CampaignTime GetDurationOfResolutionForHero(Hero alternativeSolutionHero, IssueBase issue)
		{
			(SkillObject, int) issueAlternativeSolutionSkill = GetIssueAlternativeSolutionSkill(alternativeSolutionHero, issue);
			int skillValue = alternativeSolutionHero.GetSkillValue(issueAlternativeSolutionSkill.Item1);
			float num = 10f;
			if (skillValue != 0)
			{
				num = MBMath.ClampFloat(issueAlternativeSolutionSkill.Item2 / skillValue, 0f, 10f);
			}
			return CampaignTime.Days((float)issue.GetBaseAlternativeSolutionDurationInDays() + 2f * num);
		}

		public override int GetTroopsRequiredForHero(Hero alternativeSolutionHero, IssueBase issue)
		{
			(SkillObject, int) issueAlternativeSolutionSkill = GetIssueAlternativeSolutionSkill(alternativeSolutionHero, issue);
			int skillValue = alternativeSolutionHero.GetSkillValue(issueAlternativeSolutionSkill.Item1);
			float value = 1.2f;
			if (skillValue != 0)
			{
				value = (float)issueAlternativeSolutionSkill.Item2 / (float)skillValue;
			}
			value = MBMath.ClampFloat(value, 0.2f, 1.2f);
			return (int)((float)issue.AlternativeSolutionBaseNeededMenCount * value);
		}

		public override (SkillObject, int) GetIssueAlternativeSolutionSkill(Hero hero, IssueBase issue)
		{
			return issue.GetAlternativeSolutionSkill(hero);
		}

		private void GetIssueEffectOfHeroInternal(IssueEffect issueEffect, Hero hero, ref ExplainedNumber explainedNumber, TextObject customText)
		{
			float activeIssueEffectAmount = hero.Issue.GetActiveIssueEffectAmount(issueEffect);
			if (!activeIssueEffectAmount.ApproximatelyEqualsTo(0f))
			{
				explainedNumber.Add(activeIssueEffectAmount, customText);
			}
		}

		public override bool CanTroopsReturnFromAlternativeSolution()
		{
			if (!Hero.MainHero.IsPrisoner && (!MobileParty.MainParty.IsCurrentlyAtSea || Settlement.CurrentSettlement != null))
			{
				return MobileParty.MainParty.MapEvent == null;
			}
			return false;
		}
	}
	public class DefaultItemDiscardModel : ItemDiscardModel
	{
		public override bool PlayerCanDonateItem(ItemObject item)
		{
			bool result = false;
			if (item.HasWeaponComponent)
			{
				result = MobileParty.MainParty.HasPerk(DefaultPerks.Steward.GivingHands);
			}
			else if (item.HasArmorComponent)
			{
				result = MobileParty.MainParty.HasPerk(DefaultPerks.Steward.PaidInPromise, checkSecondaryRole: true);
			}
			return result;
		}

		public override int GetXpBonusForDiscardingItem(ItemObject item, int amount = 1)
		{
			int num = 0;
			if (PlayerCanDonateItem(item))
			{
				switch (item.Tier)
				{
				case ItemObject.ItemTiers.Tier1:
					num = 75;
					break;
				case ItemObject.ItemTiers.Tier2:
					num = 150;
					break;
				case ItemObject.ItemTiers.Tier3:
					num = 250;
					break;
				case ItemObject.ItemTiers.Tier4:
				case ItemObject.ItemTiers.Tier5:
				case ItemObject.ItemTiers.Tier6:
					num = 300;
					break;
				default:
					num = 35;
					break;
				}
			}
			return num * amount;
		}

		public override int GetXpBonusForDiscardingItems(ItemRoster itemRoster)
		{
			float num = 0f;
			for (int i = 0; i < itemRoster.Count; i++)
			{
				ItemObject itemAtIndex = itemRoster.GetItemAtIndex(i);
				num += (float)GetXpBonusForDiscardingItem(itemAtIndex, itemRoster.GetElementNumber(i));
			}
			return TaleWorlds.Library.MathF.Floor(num);
		}
	}
	public class DefaultKingdomCreationModel : KingdomCreationModel
	{
		public override int MinimumClanTierToCreateKingdom => 4;

		public override int MinimumNumberOfSettlementsOwnedToCreateKingdom => 1;

		public override int MinimumTroopCountToCreateKingdom => 100;

		public override int MaximumNumberOfInitialPolicies => 4;

		public override bool IsPlayerKingdomCreationPossible(out List<TextObject> explanations)
		{
			bool result = true;
			explanations = new List<TextObject>();
			if (Hero.MainHero.MapFaction.IsKingdomFaction)
			{
				result = false;
				TextObject item = new TextObject("{=w5b79MmE}Player clan should be independent.");
				explanations.Add(item);
			}
			if (Clan.PlayerClan.Tier < MinimumClanTierToCreateKingdom)
			{
				result = false;
				TextObject textObject = new TextObject("{=j0UDi2AN}Clan tier should be at least {TIER}.");
				textObject.SetTextVariable("TIER", MinimumClanTierToCreateKingdom);
				explanations.Add(textObject);
			}
			if (Clan.PlayerClan.Settlements.Count((Settlement t) => t.IsTown || t.IsCastle) < MinimumNumberOfSettlementsOwnedToCreateKingdom)
			{
				result = false;
				TextObject textObject2 = new TextObject("{=YsGSgaba}Number of towns or castles you own should be at least {SETTLEMENT_COUNT}.");
				textObject2.SetTextVariable("SETTLEMENT_COUNT", MinimumNumberOfSettlementsOwnedToCreateKingdom);
				explanations.Add(textObject2);
			}
			if (Clan.PlayerClan.Fiefs.Sum((Town t) => t.GarrisonParty?.MemberRoster?.TotalHealthyCount ?? 0) + Clan.PlayerClan.WarPartyComponents.Sum((WarPartyComponent t) => t.MobileParty.MemberRoster.TotalHealthyCount) < MinimumTroopCountToCreateKingdom)
			{
				result = false;
				TextObject textObject3 = new TextObject("{=K2txLdOS}You should have at least {TROOP_COUNT} men ready to fight.");
				textObject3.SetTextVariable("TROOP_COUNT", MinimumTroopCountToCreateKingdom);
				explanations.Add(textObject3);
			}
			return result;
		}

		public override bool IsPlayerKingdomAbdicationPossible(out List<TextObject> explanations)
		{
			explanations = new List<TextObject>();
			bool num = Clan.PlayerClan.Kingdom != null && Clan.PlayerClan.Kingdom.RulingClan == Clan.PlayerClan;
			bool flag = MobileParty.MainParty.MapEvent != null || MobileParty.MainParty.SiegeEvent != null;
			bool flag2 = num && !Clan.PlayerClan.Kingdom.UnresolvedDecisions.IsEmpty();
			if (!num)
			{
				explanations.Add(new TextObject("{=s1ERZ4ZR}You must be the king"));
			}
			if (flag)
			{
				explanations.Add(new TextObject("{=uaMmmhRV}You must conclude your current encounter"));
			}
			if (flag2)
			{
				explanations.Add(new TextObject("{=etKrpcHe}You must resolve pending decisions"));
			}
			if (num && !flag)
			{
				return !flag2;
			}
			return false;
		}

		public override IEnumerable<CultureObject> GetAvailablePlayerKingdomCultures()
		{
			List<CultureObject> list = new List<CultureObject>();
			list.Add(Clan.PlayerClan.Culture);
			foreach (Settlement item in Clan.PlayerClan.Settlements.Where((Settlement t) => t.IsTown || t.IsCastle))
			{
				if (!list.Contains(item.Culture))
				{
					list.Add(item.Culture);
				}
			}
			foreach (CultureObject item2 in list)
			{
				yield return item2;
			}
		}
	}
	public class DefaultKingdomDecisionPermissionModel : KingdomDecisionPermissionModel
	{
		private IAllianceCampaignBehavior _allianceCampaignBehavior;

		private IAllianceCampaignBehavior AllianceCampaignBehavior
		{
			get
			{
				if (_allianceCampaignBehavior == null)
				{
					_allianceCampaignBehavior = Campaign.Current.GetCampaignBehavior<IAllianceCampaignBehavior>();
				}
				return _allianceCampaignBehavior;
			}
		}

		public override bool IsPolicyDecisionAllowed(PolicyObject policy)
		{
			return true;
		}

		public override bool IsWarDecisionAllowedBetweenKingdoms(Kingdom kingdom1, Kingdom kingdom2, out TextObject reason)
		{
			reason = null;
			return true;
		}

		public override bool IsPeaceDecisionAllowedBetweenKingdoms(Kingdom kingdom1, Kingdom kingdom2, out TextObject reason)
		{
			reason = null;
			Kingdom callingKingdom = null;
			if (Campaign.Current.Models.DiplomacyModel.IsAtConstantWar(kingdom1, kingdom2))
			{
				reason = new TextObject("{=eNPupZOp}These kingdoms can not declare peace at this time.");
				return false;
			}
			IAllianceCampaignBehavior allianceCampaignBehavior = AllianceCampaignBehavior;
			if (allianceCampaignBehavior != null && allianceCampaignBehavior.IsAtWarByCallToWarAgreement(kingdom1, kingdom2, out callingKingdom))
			{
				reason = GetExplanationForPeaceOfferWithCallToWar(callingKingdom, kingdom1, kingdom2);
				return false;
			}
			IAllianceCampaignBehavior allianceCampaignBehavior2 = AllianceCampaignBehavior;
			if (allianceCampaignBehavior2 != null && allianceCampaignBehavior2.IsAtWarByCallToWarAgreement(kingdom2, kingdom1, out callingKingdom))
			{
				reason = GetExplanationForPeaceOfferWithCallToWar(callingKingdom, kingdom2, kingdom1);
				return false;
			}
			if (!Campaign.Current.Models.DiplomacyModel.IsPeaceSuitable(kingdom1, kingdom2))
			{
				reason = new TextObject("{=JkQ7fmcX}The enemy is not open to negotiations.");
				return false;
			}
			return true;
		}

		public override bool IsAnnexationDecisionAllowed(Settlement annexedSettlement)
		{
			return true;
		}

		public override bool IsExpulsionDecisionAllowed(Clan expelledClan)
		{
			return true;
		}

		public override bool IsKingSelectionDecisionAllowed(Kingdom kingdom)
		{
			return true;
		}

		public override bool IsStartAllianceDecisionAllowedBetweenKingdoms(Kingdom kingdom1, Kingdom kingdom2, out TextObject reason)
		{
			reason = null;
			return true;
		}

		private TextObject GetExplanationForPeaceOfferWithCallToWar(Kingdom callingKingdom, Kingdom calledKingdom, Kingdom kingdomToCallToWarAgainst)
		{
			TextObject empty = TextObject.GetEmpty();
			if (calledKingdom == Clan.PlayerClan.Kingdom)
			{
				empty = new TextObject("{=M6wsjpNN}Your realm is not allowed to negotiate peace with {KINGDOM_TO_CALL_TO_WAR_AGAINST} due to your Call to War Agreement with {CALLING_KINGDOM}.");
				empty.SetTextVariable("KINGDOM_TO_CALL_TO_WAR_AGAINST", kingdomToCallToWarAgainst.Name);
				empty.SetTextVariable("CALLING_KINGDOM", callingKingdom.Name);
			}
			else if (kingdomToCallToWarAgainst == Clan.PlayerClan.Kingdom)
			{
				empty = new TextObject("{=CiFKYMKb}Your realm is not allowed to negotiate peace with {CALLED_KINGDOM} due to their Call to War Agreement with {CALLING_KINGDOM}.");
				empty.SetTextVariable("CALLED_KINGDOM", calledKingdom.Name);
				empty.SetTextVariable("CALLING_KINGDOM", callingKingdom.Name);
			}
			else
			{
				empty = new TextObject("{=mc0wmdkb}{KINGDOM_NAME} is not allowed to negotiate peace with {CALLED_KINGDOM} due to their Call to War Agreement with {CALLING_KINGDOM}.");
				empty.SetTextVariable("KINGDOM_NAME", kingdomToCallToWarAgainst.Name);
				empty.SetTextVariable("CALLED_KINGDOM", calledKingdom.Name);
				empty.SetTextVariable("CALLING_KINGDOM", callingKingdom.Name);
			}
			return empty;
		}
	}
