	public class DefaultMapDistanceModel : MapDistanceModel
	{
		private INavigationCache _navigationCache;

		public override int RegionSwitchCostFromLandToSea => 0;

		public override int RegionSwitchCostFromSeaToLand => 0;

		public override float MaximumSpawnDistanceForCompanionsAfterDisband => 150f;

		public override void RegisterDistanceCache(MobileParty.NavigationType navigationCapability, INavigationCache cacheToRegister)
		{
			_navigationCache = cacheToRegister;
			cacheToRegister.FinalizeInitialization();
		}

		public override float GetMaximumDistanceBetweenTwoConnectedSettlements(MobileParty.NavigationType navigationCapabilities)
		{
			return _navigationCache?.MaximumDistanceBetweenTwoConnectedSettlements ?? 0f;
		}

		public override float GetLandRatioOfPathBetweenSettlements(Settlement fromSettlement, Settlement toSettlement, bool isFromPort, bool isTargetingPort)
		{
			if (_navigationCache != null)
			{
				_navigationCache.GetSettlementToSettlementDistanceWithLandRatio(fromSettlement, isAtSea1: false, toSettlement, isAtSea2: false, out var landRatio);
				return landRatio;
			}
			return 1f;
		}

		public override float GetDistance(Settlement fromSettlement, Settlement toSettlement, bool isFromPort = false, bool isTargetingPort = false, MobileParty.NavigationType navigationCapability = MobileParty.NavigationType.Default)
		{
			float landRatio;
			return GetDistance(fromSettlement, toSettlement, isFromPort, isTargetingPort, MobileParty.NavigationType.Default, out landRatio);
		}

		public override float GetDistance(Settlement fromSettlement, Settlement toSettlement, bool isFromPort, bool isTargetingPort, MobileParty.NavigationType navigationCapability, out float landRatio)
		{
			float result = float.MaxValue;
			landRatio = 1f;
			if (fromSettlement != null && toSettlement != null)
			{
				if (fromSettlement != toSettlement)
				{
					return _navigationCache.GetSettlementToSettlementDistanceWithLandRatio(fromSettlement, isFromPort, toSettlement, isTargetingPort, out landRatio);
				}
				result = 0f;
			}
			return result;
		}

		public override float GetDistance(MobileParty fromMobileParty, Settlement toSettlement, bool isTargetingPort, MobileParty.NavigationType customCapability, out float estimatedLandRatio)
		{
			float value = 100000000f;
			estimatedLandRatio = 1f;
			if (fromMobileParty.CurrentNavigationFace.FaceIndex == toSettlement.GatePosition.Face.FaceIndex)
			{
				if (Campaign.Current.Models.PartyNavigationModel.IsTerrainTypeValidForNavigationType(Campaign.Current.MapSceneWrapper.GetFaceTerrainType(fromMobileParty.Position.Face), MobileParty.NavigationType.Default))
				{
					value = fromMobileParty.Position.Distance(toSettlement.GatePosition);
				}
			}
			else if (fromMobileParty.IsCurrentlyAtSea)
			{
				value = 100000000f;
			}
			else
			{
				Settlement item = Campaign.Current.Models.MapDistanceModel.GetClosestEntranceToFace(fromMobileParty.CurrentNavigationFace, MobileParty.NavigationType.Default).Item1;
				if (item != null)
				{
					value = fromMobileParty.Position.Distance(toSettlement.GatePosition) - item.GatePosition.Distance(toSettlement.GatePosition) + Campaign.Current.Models.MapDistanceModel.GetDistance(item, toSettlement, isFromPort: false, isTargetingPort: false, MobileParty.NavigationType.Default);
				}
			}
			return MBMath.ClampFloat(value, 0f, float.MaxValue);
		}

		public override float GetDistance(MobileParty fromMobileParty, MobileParty toMobileParty, MobileParty.NavigationType customCapability, out float landRatio)
		{
			Campaign.Current.Models.MapDistanceModel.GetDistance(fromMobileParty, toMobileParty, customCapability, 100000000f, out var distance, out landRatio);
			return distance;
		}

		public override bool GetDistance(MobileParty fromMobileParty, MobileParty toMobileParty, MobileParty.NavigationType customCapability, float maxDistance, out float distance, out float landRatio)
		{
			landRatio = 1f;
			distance = float.MaxValue;
			if (fromMobileParty.CurrentNavigationFace.FaceIndex == toMobileParty.CurrentNavigationFace.FaceIndex)
			{
				if (Campaign.Current.Models.PartyNavigationModel.IsTerrainTypeValidForNavigationType(Campaign.Current.MapSceneWrapper.GetFaceTerrainType(fromMobileParty.Position.Face), MobileParty.NavigationType.Default))
				{
					distance = fromMobileParty.Position.Distance(toMobileParty.Position);
				}
			}
			else if (fromMobileParty.IsCurrentlyAtSea || toMobileParty.IsCurrentlyAtSea)
			{
				distance = float.MaxValue;
			}
			else
			{
				distance = fromMobileParty.Position.Distance(toMobileParty.Position);
			}
			distance = MBMath.ClampFloat(distance, 0f, float.MaxValue);
			return distance <= maxDistance;
		}

		public override float GetDistance(MobileParty fromMobileParty, in CampaignVec2 toPoint, MobileParty.NavigationType customCapability, out float landRatio)
		{
			float value = float.MaxValue;
			landRatio = 1f;
			PathFaceRecord face = toPoint.Face;
			if (fromMobileParty.CurrentNavigationFace.FaceIndex == face.FaceIndex)
			{
				if (Campaign.Current.Models.PartyNavigationModel.IsTerrainTypeValidForNavigationType(Campaign.Current.MapSceneWrapper.GetFaceTerrainType(fromMobileParty.Position.Face), MobileParty.NavigationType.Default))
				{
					value = fromMobileParty.Position.Distance(toPoint);
				}
			}
			else
			{
				MapDistanceModel mapDistanceModel = Campaign.Current.Models.MapDistanceModel;
				(Settlement, bool) closestEntranceToFace = mapDistanceModel.GetClosestEntranceToFace(fromMobileParty.CurrentNavigationFace, MobileParty.NavigationType.Default);
				(Settlement, bool) closestEntranceToFace2 = mapDistanceModel.GetClosestEntranceToFace(face, MobileParty.NavigationType.Default);
				var (settlement, _) = closestEntranceToFace;
				var (settlement2, _) = closestEntranceToFace2;
				if (settlement != null && settlement2 != null)
				{
					value = fromMobileParty.Position.Distance(toPoint) - settlement.GatePosition.Distance(settlement2.GatePosition) + GetDistance(settlement, settlement2, isFromPort: false, isTargetingPort: false, MobileParty.NavigationType.Default);
				}
			}
			return MBMath.ClampFloat(value, 0f, float.MaxValue);
		}

		public override float GetDistance(Settlement fromSettlement, in CampaignVec2 toPoint, bool isFromPort, MobileParty.NavigationType customCapability)
		{
			float value = float.MaxValue;
			CampaignVec2 campaignVec = (isFromPort ? fromSettlement.PortPosition : fromSettlement.GatePosition);
			PathFaceRecord face = toPoint.Face;
			PathFaceRecord face2 = campaignVec.Face;
			if (face2.FaceIndex == face.FaceIndex)
			{
				if (Campaign.Current.Models.PartyNavigationModel.IsTerrainTypeValidForNavigationType(Campaign.Current.MapSceneWrapper.GetFaceTerrainType(face2), MobileParty.NavigationType.Default))
				{
					value = campaignVec.Distance(toPoint);
				}
			}
			else
			{
				MapDistanceModel mapDistanceModel = Campaign.Current.Models.MapDistanceModel;
				Settlement item = mapDistanceModel.GetClosestEntranceToFace(face, MobileParty.NavigationType.Default).Item1;
				if (item != null)
				{
					value = fromSettlement.GatePosition.Distance(toPoint) - fromSettlement.GatePosition.Distance(item.GatePosition) + mapDistanceModel.GetDistance(fromSettlement, item, isFromPort: false, isTargetingPort: false, MobileParty.NavigationType.Default);
				}
			}
			return MBMath.ClampFloat(value, 0f, 100000000f);
		}

		public override float GetPortToGateDistanceForSettlement(Settlement settlement)
		{
			return 100000000f;
		}

		public override bool PathExistBetweenPoints(in CampaignVec2 fromPoint, in CampaignVec2 toPoint, MobileParty.NavigationType navigationType)
		{
			if (fromPoint.IsOnLand)
			{
				return toPoint.IsOnLand;
			}
			return false;
		}

		public override (Settlement, bool) GetClosestEntranceToFace(PathFaceRecord face, MobileParty.NavigationType navigationCapabilities)
		{
			bool isAtSea;
			return (_navigationCache.GetClosestSettlementToFaceIndex(face.FaceIndex, out isAtSea), isAtSea);
		}

		public override MBReadOnlyList<Settlement> GetNeighborsOfFortification(Town town, MobileParty.NavigationType navigationCapabilities)
		{
			return _navigationCache.GetNeighbors(town.Settlement);
		}

		public override float GetTransitionCostAdjustment(Settlement settlement1, bool isFromPort, Settlement settlement2, bool isTargetingPort, bool fromIsCurrentlyAtSea, bool toIsCurrentlyAtSea)
		{
			return 0f;
		}
	}
	public class DefaultMapTrackModel : MapTrackModel
	{
		private const float MinimumTrackSize = 0.1f;

		private const float MaximumTrackSize = 1f;

		private static TextObject _defaultTrackTitle = new TextObject("{=maptrack}Track");

		public override float MaxTrackLife => 28f;

		public override float GetMaxTrackSpottingDistanceForMainParty()
		{
			ExplainedNumber explainedNumber = new ExplainedNumber(0f, includeDescriptions: false, null);
			SkillHelper.AddSkillBonusForParty(DefaultSkillEffects.TrackingRadius, MobileParty.MainParty, ref explainedNumber);
			if (!MobileParty.MainParty.IsCurrentlyAtSea)
			{
				PerkHelper.AddPerkBonusForParty(DefaultPerks.Scouting.Ranger, MobileParty.MainParty, isPrimaryBonus: true, ref explainedNumber);
			}
			return explainedNumber.ResultNumber;
		}

		public override bool CanPartyLeaveTrack(MobileParty mobileParty)
		{
			if (mobileParty.SiegeEvent == null && mobileParty.MapEvent == null && mobileParty.IsActive && !mobileParty.IsCurrentlyAtSea && !mobileParty.IsGarrison && !mobileParty.IsMilitia && !mobileParty.IsBanditBossParty && !mobileParty.IsMainParty)
			{
				return mobileParty.AttachedTo == null;
			}
			return false;
		}

		public override int GetTrackLife(MobileParty mobileParty)
		{
			bool flag = Campaign.Current.MapSceneWrapper.GetFaceTerrainType(mobileParty.CurrentNavigationFace) == TerrainType.Snow;
			int num = mobileParty.MemberRoster.TotalManCount + mobileParty.PrisonRoster.TotalManCount;
			float num2 = TaleWorlds.Library.MathF.Min(1f, (0.5f * MBRandom.RandomFloat + 0.5f + (float)num * 0.007f) / 2f) * (flag ? 0.5f : 1f);
			if (MobileParty.MainParty.HasPerk(DefaultPerks.Scouting.Tracker) && !mobileParty.IsCurrentlyAtSea)
			{
				num2 = TaleWorlds.Library.MathF.Min(1f, num2 * (1f + DefaultPerks.Scouting.Tracker.PrimaryBonus));
			}
			return TaleWorlds.Library.MathF.Round(Campaign.Current.Models.MapTrackModel.MaxTrackLife * num2);
		}

		public override float GetTrackDetectionDifficultyForMainParty(Track track, float trackSpottingDistance)
		{
			int size = track.Size;
			float elapsedHoursUntilNow = track.CreationTime.ElapsedHoursUntilNow;
			float num = (track.Position.ToVec2() - MobileParty.MainParty.Position.ToVec2()).Length / trackSpottingDistance;
			float num2 = -75f + elapsedHoursUntilNow / MaxTrackLife * 100f + num * 100f + TaleWorlds.Library.MathF.Max(0f, 100f - (float)size) * (CampaignTime.Now.IsNightTime ? 10f : 1f);
			if (MobileParty.MainParty.HasPerk(DefaultPerks.Scouting.Ranger, checkSecondaryRole: true) && !MobileParty.MainParty.IsCurrentlyAtSea)
			{
				num2 -= num2 * DefaultPerks.Scouting.Ranger.SecondaryBonus;
			}
			return num2;
		}

		public override float GetSkillFromTrackDetected(Track track)
		{
			float num = 0.2f * (1f + track.CreationTime.ElapsedHoursUntilNow) * (1f + 0.02f * TaleWorlds.Library.MathF.Max(0f, 100f - (float)track.NumberOfAllMembers));
			if (track.IsEnemy)
			{
				num *= ((track.PartyType == Track.PartyTypeEnum.Lord) ? 10f : ((track.PartyType == Track.PartyTypeEnum.Bandit) ? 4f : ((track.PartyType == Track.PartyTypeEnum.Caravan) ? 3f : 2f)));
			}
			return num;
		}

		public override float GetSkipTrackChance(MobileParty mobileParty)
		{
			float num = mobileParty.MemberRoster.TotalManCount + mobileParty.PrisonRoster.TotalManCount;
			return TaleWorlds.Library.MathF.Max(0.5f - num * 0.01f, 0f);
		}

		public override TextObject TrackTitle(Track track)
		{
			if (!track.IsPointer)
			{
				Hero effectiveScout = MobileParty.MainParty.EffectiveScout;
				if (effectiveScout == null || effectiveScout.GetSkillValue(DefaultSkills.Scouting) <= 270)
				{
					return _defaultTrackTitle;
				}
				return track.PartyName;
			}
			return track.PartyName;
		}

		private string UncertainifyNumber(float num, float baseNum, int skillLevel)
		{
			float num2 = baseNum * TaleWorlds.Library.MathF.Max(0f, 1f - (float)(skillLevel / 30) * 0.1f);
			float num3 = num - num % num2;
			float num4 = num3 + num2;
			if (num2 < 0.0001f)
			{
				return num.ToString();
			}
			return num3.ToString("0.0") + "-" + num4.ToString("0.0");
		}

		private string UncertainifyNumber(int num, int baseNum, int skillLevel)
		{
			int num2 = TaleWorlds.Library.MathF.Round((float)baseNum * TaleWorlds.Library.MathF.Max(0f, 1f - (float)(skillLevel / 30) * 0.1f));
			if (num2 <= 1)
			{
				return num.ToString();
			}
			int num3 = num - num % num2;
			int num4 = num3 + num2;
			if (num3 == 0)
			{
				num3 = 1;
			}
			if (num3 >= num4)
			{
				return num.ToString();
			}
			return num3 + "-" + num4;
		}

		public override IEnumerable<(TextObject, string)> GetTrackDescription(Track track)
		{
			List<(TextObject, string)> list = new List<(TextObject, string)>();
			if (!track.IsPointer && track.IsAlive)
			{
				int skillLevel = MobileParty.MainParty.EffectiveScout?.GetSkillValue(DefaultSkills.Scouting) ?? 0;
				ExplainedNumber explainedNumber = default(ExplainedNumber);
				SkillHelper.AddSkillBonusForParty(DefaultSkillEffects.TrackingTrackInformation, MobileParty.MainParty, ref explainedNumber);
				int num = TaleWorlds.Library.MathF.Floor(explainedNumber.ResultNumber);
				if (num >= 1)
				{
					int num2 = track.NumberOfAllMembers + track.NumberOfPrisoners;
					list.Add((new TextObject("{=rmydcPP3}Party Size:"), UncertainifyNumber(num2, 10, skillLevel)));
				}
				if (num >= 2)
				{
					TextObject textObject = new TextObject("{=Lak0x7Sa}{HOURS} {?HOURS==1}hour{?}hours{\\?}");
					int variable = TaleWorlds.Library.MathF.Ceiling(track.CreationTime.ElapsedHoursUntilNow);
					textObject.SetTextVariable("HOURS", variable);
					list.Add((new TextObject("{=0aU9dtvV}Time:"), textObject.ToString()));
				}
				if (num >= 3)
				{
					list.Add((new TextObject("{=PThYJE2U}Party Speed:"), UncertainifyNumber(TaleWorlds.Library.MathF.Round(track.Speed, 2), 1f, skillLevel)));
				}
				if (num >= 4)
				{
					list.Add((new TextObject("{=ZULIWupm}Mounted Troops:"), UncertainifyNumber(track.NumberOfMenWithHorse, 10, skillLevel)));
				}
				if (num >= 5 && num < 10)
				{
					list.Add((new TextObject("{=1pdBdqKn}Party Type:"), GameTexts.FindText("str_party_type", track.PartyType.ToString()).ToString()));
				}
				if (num >= 6)
				{
					list.Add((new TextObject("{=pHrxeTdc}Prisoners:"), UncertainifyNumber(track.NumberOfPrisoners, 10, skillLevel)));
				}
				if (num >= 7)
				{
					list.Add((new TextObject("{=aa1yFm6q}Pack Animals:"), UncertainifyNumber(track.NumberOfPackAnimals, 10, skillLevel)));
				}
				if (num >= 8)
				{
					TextObject textObject2 = (track.IsEnemy ? GameTexts.FindText("str_yes") : GameTexts.FindText("str_no"));
					list.Add((new TextObject("{=6REUNz1g}Enemy Party:"), textObject2.ToString()));
				}
				if (num >= 9)
				{
					list.Add((new TextObject("{=dicpCcb2}Party Culture:"), track.Culture.Name.ToString()));
				}
				if (num >= 10)
				{
					list.Add((new TextObject("{=BVIm1HPw}Party Name:"), track.PartyName.ToString()));
				}
			}
			return list;
		}

		public override uint GetTrackColor(Track track)
		{
			if (track.IsPointer)
			{
				return new Vec3(1f, 1f, 1f).ToARGB;
			}
			Vec3 vec = new Vec3(0.6f, 0.95f, 0.2f);
			Vec3 vec2 = new Vec3(0.45f, 0.55f, 0.2f);
			Vec3 vec3 = new Vec3(0.15f, 0.25f, 0.4f);
			Vec3 zero = Vec3.Zero;
			if (track.IsEnemy)
			{
				Hero effectiveScout = MobileParty.MainParty.EffectiveScout;
				if (effectiveScout != null && effectiveScout.GetSkillValue(DefaultSkills.Scouting) > 240)
				{
					vec = new Vec3(0.99f, 0.5f, 0.1f);
					vec2 = new Vec3(0.75f, 0.4f, 0.3f);
					vec3 = new Vec3(0.5f, 0.1f, 0.4f);
				}
			}
			float num = TaleWorlds.Library.MathF.Min(track.CreationTime.ElapsedHoursUntilNow / Campaign.Current.Models.MapTrackModel.MaxTrackLife, 1f);
			if (num < 0.35f)
			{
				num /= 0.35f;
				zero = num * vec2 + (1f - num) * vec;
			}
			else
			{
				num -= 0.35f;
				num /= 0.65f;
				zero = num * vec3 + (1f - num) * vec2;
			}
			return zero.ToARGB;
		}

		public override float GetTrackScale(Track track)
		{
			if (track.IsPointer)
			{
				return 1f;
			}
			float b = 0.1f + 0.001f * (float)(track.NumberOfAllMembers + track.NumberOfPrisoners);
			return TaleWorlds.Library.MathF.Min(1f, b);
		}
	}
	public class DefaultMapVisibilityModel : MapVisibilityModel
	{
		private const float PartySpottingDifficultyInForests = 0.3f;

		public override float MaximumSeeingRange()
		{
			return 60f;
		}

		public override float GetPartySeeingRangeBase(MobileParty party)
		{
			if (!Campaign.Current.IsNight)
			{
				return 12f;
			}
			return 6f;
		}

		public override ExplainedNumber GetPartySpottingRange(MobileParty party, bool includeDescriptions = false)
		{
			float partySeeingRangeBase = Campaign.Current.Models.MapVisibilityModel.GetPartySeeingRangeBase(party);
			ExplainedNumber explainedNumber = new ExplainedNumber(partySeeingRangeBase, includeDescriptions);
			SkillHelper.AddSkillBonusForParty(DefaultSkillEffects.TrackingSpottingDistance, party, ref explainedNumber);
			if (!party.IsCurrentlyAtSea)
			{
				PerkHelper.AddPerkBonusForParty(DefaultPerks.Bow.EagleEye, party, isPrimaryBonus: false, ref explainedNumber);
			}
			Hero effectiveScout = party.EffectiveScout;
			if (effectiveScout != null)
			{
				TerrainType faceTerrainType = Campaign.Current.MapSceneWrapper.GetFaceTerrainType(party.CurrentNavigationFace);
				if (faceTerrainType == TerrainType.Forest && PartyBaseHelper.HasFeat(party.Party, DefaultCulturalFeats.BattanianForestSpeedFeat))
				{
					explainedNumber.AddFactor(0.15f, GameTexts.FindText("str_culture"));
				}
				if (!party.IsCurrentlyAtSea)
				{
					if ((faceTerrainType == TerrainType.Plain || faceTerrainType == TerrainType.Steppe) && effectiveScout.GetPerkValue(DefaultPerks.Scouting.WaterDiviner))
					{
						explainedNumber.AddFactor(DefaultPerks.Scouting.WaterDiviner.PrimaryBonus, DefaultPerks.Scouting.WaterDiviner.Name);
					}
					if (Campaign.Current.IsNight)
					{
						PerkHelper.AddPerkBonusForParty(DefaultPerks.Scouting.NightRunner, party, isPrimaryBonus: false, ref explainedNumber);
					}
					else
					{
						PerkHelper.AddPerkBonusForParty(DefaultPerks.Scouting.DayTraveler, party, isPrimaryBonus: false, ref explainedNumber);
					}
				}
				if (!party.IsMoving && !party.IsCurrentlyAtSea && party.StationaryStartTime.ElapsedHoursUntilNow >= 1f)
				{
					PerkHelper.AddPerkBonusForParty(DefaultPerks.Scouting.VantagePoint, party, isPrimaryBonus: false, ref explainedNumber);
				}
				if (effectiveScout.GetPerkValue(DefaultPerks.Scouting.MountedScouts) && !party.IsCurrentlyAtSea)
				{
					float num = 0f;
					for (int i = 0; i < party.MemberRoster.Count; i++)
					{
						if (party.MemberRoster.GetCharacterAtIndex(i).DefaultFormationClass.Equals(FormationClass.Cavalry))
						{
							num += (float)party.MemberRoster.GetElementNumber(i);
						}
					}
					if (num / (float)party.MemberRoster.TotalManCount >= 0.5f)
					{
						explainedNumber.AddFactor(DefaultPerks.Scouting.MountedScouts.PrimaryBonus, DefaultPerks.Scouting.MountedScouts.Name);
					}
				}
			}
			explainedNumber.LimitMax(Campaign.Current.Models.MapVisibilityModel.MaximumSeeingRange(), new TextObject("{=6qv6Hdww}Limit"));
			return explainedNumber;
		}

		public override float GetPartySpottingRatioForMainPartySeeingRange(MobileParty party)
		{
			float num = 1f;
			if (Campaign.Current.MapSceneWrapper.GetFaceTerrainType(party.CurrentNavigationFace) == TerrainType.Forest)
			{
				float num2 = -0.3f;
				if (MobileParty.MainParty.HasPerk(DefaultPerks.Scouting.KeenSight))
				{
					num2 += num2 * DefaultPerks.Scouting.KeenSight.PrimaryBonus;
				}
				num += num2;
			}
			int num3 = ((party.Army != null && party.Army.LeaderParty == party) ? party.Army.TotalManCount : party.MemberRoster.TotalManCount);
			return MBMath.ClampFloat(1.1f - 0.5f * TaleWorlds.Library.MathF.Pow(System.MathF.E, (float)(-num3) / 200f), 0f, 1f) * num;
		}

		public override float GetHideoutSpottingDistance()
		{
			if (MobileParty.MainParty.HasPerk(DefaultPerks.Scouting.RumourNetwork, checkSecondaryRole: true))
			{
				return MobileParty.MainParty.SeeingRange * 1.2f * (1f + DefaultPerks.Scouting.RumourNetwork.SecondaryBonus);
			}
			return MobileParty.MainParty.SeeingRange * 1.2f;
		}
	}
	public class DefaultMapWeatherModel : MapWeatherModel
	{
		private struct SunPosition
		{
			public float Angle { get; private set; }

			public float Altitude { get; private set; }

			public SunPosition(float angle, float altitude)
			{
				this = default(SunPosition);
				Angle = angle;
				Altitude = altitude;
			}
		}

		private const float MinSunAngle = 0f;

		private const float MaxSunAngle = 50f;

		private const float MinEnvironmentMultiplier = 0.001f;

		private const float DayEnvironmentMultiplier = 1f;

		private const float NightEnvironmentMultiplier = 0.001f;

		private const float SnowStartThreshold = 0.55f;

		private const float DenseSnowStartThreshold = 0.85f;

		private const float NoSnowDelta = 0.1f;

		private const float WetThreshold = 0.6f;

		private const float WetThresholdForTexture = 0.3f;

		private const float LightRainStartThreshold = 0.7f;

		private const float DenseRainStartThreshold = 0.85f;

		private const float SnowFrequencyModifier = 0.1f;

		private const float RainFrequencyModifier = 0.45f;

		private const float MaxSnowCoverage = 0.75f;

		private const float WaveMultiplierForSettlements = 0.3f;

		private WeatherEvent[] _weatherDataCache;

		private AtmosphereGrid _atmosphereGrid;

		private bool _sunIsMoon;

		private float SunRiseNorm => (float)CampaignTime.SunRise / (float)CampaignTime.HoursInDay;

		private float SunSetNorm => (float)CampaignTime.SunSet / (float)CampaignTime.HoursInDay;

		private float DayTime => CampaignTime.SunSet - CampaignTime.SunRise;

		public override CampaignTime WeatherUpdatePeriod => CampaignTime.Hours(4f);

		public override CampaignTime WeatherUpdateFrequency => new CampaignTime(WeatherUpdatePeriod.NumTicks / (Campaign.Current.DefaultWeatherNodeDimension * Campaign.Current.DefaultWeatherNodeDimension));

		private CampaignTime PreviousRainDataCheckForWetness => CampaignTime.Hours(24f);

		private uint GetSeed(CampaignTime campaignTime, Vec2 position)
		{
			campaignTime += new CampaignTime(Campaign.Current.UniqueGameId.GetHashCode());
			GetNodePositionForWeather(position, out var xIndex, out var yIndex);
			uint num = (uint)(campaignTime.ToHours / WeatherUpdatePeriod.ToHours);
			if (campaignTime.ToSeconds % WeatherUpdatePeriod.ToSeconds < WeatherUpdateFrequency.ToSeconds * (double)(xIndex * Campaign.Current.DefaultWeatherNodeDimension + yIndex))
			{
				num--;
			}
			return num;
		}

		public override AtmosphereState GetInterpolatedAtmosphereState(CampaignTime timeOfYear, Vec3 pos)
		{
			if (_atmosphereGrid == null)
			{
				_atmosphereGrid = new AtmosphereGrid();
				_atmosphereGrid.Initialize();
			}
			return _atmosphereGrid.GetInterpolatedStateInfo(pos);
		}

		private Vec2 GetNodePositionForWeather(Vec2 pos, out int xIndex, out int yIndex)
		{
			if (Campaign.Current.MapSceneWrapper != null)
			{
				Vec2 terrainSize = Campaign.Current.MapSceneWrapper.GetTerrainSize();
				float num = terrainSize.X / (float)Campaign.Current.DefaultWeatherNodeDimension;
				float num2 = terrainSize.Y / (float)Campaign.Current.DefaultWeatherNodeDimension;
				xIndex = (int)(pos.x / num);
				yIndex = (int)(pos.y / num2);
				float a = (float)xIndex * num;
				float b = (float)yIndex * num2;
				return new Vec2(a, b);
			}
			xIndex = 0;
			yIndex = 0;
			return Vec2.Zero;
		}

		public override AtmosphereInfo GetAtmosphereModel(CampaignVec2 position)
		{
			float hourOfDayNormalized = GetHourOfDayNormalized();
			GetSeasonTimeFactorOfCampaignTime(CampaignTime.Now, out var timeFactorForSnow, out var _);
			SunPosition sunPosition = GetSunPosition(hourOfDayNormalized, timeFactorForSnow);
			float environmentMultiplier = GetEnvironmentMultiplier(sunPosition);
			float modifiedEnvironmentMultiplier = GetModifiedEnvironmentMultiplier(environmentMultiplier);
			modifiedEnvironmentMultiplier = TaleWorlds.Library.MathF.Max(TaleWorlds.Library.MathF.Pow(modifiedEnvironmentMultiplier, 1.5f), 0.001f);
			Vec3 sunColor = GetSunColor(environmentMultiplier);
			AtmosphereState gridInfo = GetInterpolatedAtmosphereState(CampaignTime.Now, position.AsVec3());
			float temperature = GetTemperature(ref gridInfo, timeFactorForSnow);
			float humidity = GetHumidity(ref gridInfo, timeFactorForSnow);
			Campaign.Current.Models.MapWeatherModel.UpdateWeatherForPosition(position, CampaignTime.Now);
			GetSeasonRainAndSnowDataForOpeningMission(position.ToVec2(), out var selectedSeason, out var isRaining, out var rainValue, out var snowFallDensity);
			string selectedAtmosphereId = GetSelectedAtmosphereId(selectedSeason, isRaining, snowFallDensity, rainValue);
			TerrainType terrainTypeAtPosition = Campaign.Current.MapSceneWrapper.GetTerrainTypeAtPosition(in position);
			AtmosphereInfo result = default(AtmosphereInfo);
			result.Seed = (uint)CampaignTime.Now.ToSeconds;
			result.SunInfo.Altitude = sunPosition.Altitude;
			result.SunInfo.Angle = sunPosition.Angle;
			result.SunInfo.Color = sunColor;
			result.SunInfo.Brightness = GetSunBrightness(environmentMultiplier);
			result.SunInfo.Size = GetSunSize(environmentMultiplier);
			result.SunInfo.RayStrength = GetSunRayStrength(environmentMultiplier);
			result.SunInfo.MaxBrightness = GetSunBrightness(1f, forceDay: true);
			result.RainInfo.Density = rainValue;
			result.SnowInfo.Density = snowFallDensity;
			result.AmbientInfo.EnvironmentMultiplier = TaleWorlds.Library.MathF.Max(modifiedEnvironmentMultiplier * 0.5f, 0.001f);
			result.AmbientInfo.AmbientColor = GetAmbientFogColor(modifiedEnvironmentMultiplier);
			result.AmbientInfo.MieScatterStrength = GetMieScatterStrength(environmentMultiplier);
			result.AmbientInfo.RayleighConstant = GetRayleighConstant(environmentMultiplier);
			result.SkyInfo.Brightness = GetSkyBrightness(hourOfDayNormalized, environmentMultiplier);
			result.FogInfo.Density = GetFogDensity(environmentMultiplier, position.AsVec3());
			result.FogInfo.Color = GetFogColor(modifiedEnvironmentMultiplier);
			result.FogInfo.Falloff = 1.48f;
			result.TimeInfo.TimeOfDay = GetHourOfDay();
			result.TimeInfo.WinterTimeFactor = GetWinterTimeFactor(CampaignTime.Now);
			result.TimeInfo.DrynessFactor = GetDrynessFactor(CampaignTime.Now);
			result.TimeInfo.NightTimeFactor = GetNightTimeFactor();
			result.TimeInfo.Season = (int)selectedSeason;
			result.NauticalInfo.WaveStrength = GetWaveStrengthForPosition(position);
			result.NauticalInfo.WindVector = Campaign.Current.Models.MapWeatherModel.GetWindForPosition(position);
			result.NauticalInfo.CanUseLowAltitudeAtmosphere = 0;
			result.NauticalInfo.UseSceneWindDirection = 1;
			result.NauticalInfo.IsRiverBattle = ((terrainTypeAtPosition == TerrainType.River) ? 1 : 0);
			result.NauticalInfo.UsesNavalSimulatedWater = ((terrainTypeAtPosition == TerrainType.River || terrainTypeAtPosition == TerrainType.Water || terrainTypeAtPosition == TerrainType.OpenSea || terrainTypeAtPosition == TerrainType.CoastalSea) ? 1 : 0);
			result.AreaInfo.Temperature = temperature;
			result.AreaInfo.Humidity = humidity;
			result.PostProInfo.MinExposure = MBMath.Lerp(-3f, -2f, GetExposureCoefficientBetweenDayNight());
			result.PostProInfo.MaxExposure = MBMath.Lerp(2f, 0f, modifiedEnvironmentMultiplier);
			result.PostProInfo.BrightpassThreshold = MBMath.Lerp(0.7f, 0.9f, modifiedEnvironmentMultiplier);
			result.PostProInfo.MiddleGray = 0.1f;
			result.InterpolatedAtmosphereName = selectedAtmosphereId;
			return result;
		}

		public override void InitializeCaches()
		{
			_weatherDataCache = new WeatherEvent[Campaign.Current.DefaultWeatherNodeDimension * Campaign.Current.DefaultWeatherNodeDimension];
		}

		public override WeatherEvent UpdateWeatherForPosition(CampaignVec2 position, CampaignTime ct)
		{
			GetSnowAndRainDataForPosition(position.ToVec2(), ct, out var snowValue, out var rainValue);
			Vec2 position2;
			if (snowValue > 0.55f)
			{
				float snowValue2 = snowValue;
				position2 = position.ToVec2();
				return SetIsBlizzardOrSnowFromFunction(snowValue2, ct, in position2);
			}
			float rainValue2 = rainValue;
			position2 = position.ToVec2();
			return SetIsRainingOrWetFromFunction(rainValue2, ct, in position2);
		}

		private WeatherEvent SetIsBlizzardOrSnowFromFunction(float snowValue, CampaignTime campaignTime, in Vec2 position)
		{
			int defaultWeatherNodeDimension = Campaign.Current.DefaultWeatherNodeDimension;
			int xIndex;
			int yIndex;
			Vec2 adjustedPosition = GetNodePositionForWeather(position, out xIndex, out yIndex);
			if (snowValue >= 0.65000004f)
			{
				float frequency = (snowValue - 0.55f) / 0.45f;
				uint seed = GetSeed(campaignTime, position);
				bool currentWeatherInAdjustedPosition = GetCurrentWeatherInAdjustedPosition(seed, frequency, 0.1f, in adjustedPosition);
				_weatherDataCache[yIndex * defaultWeatherNodeDimension + xIndex] = (currentWeatherInAdjustedPosition ? WeatherEvent.Blizzard : WeatherEvent.Snowy);
			}
			else
			{
				_weatherDataCache[yIndex * defaultWeatherNodeDimension + xIndex] = ((snowValue > 0.55f) ? WeatherEvent.Snowy : WeatherEvent.Clear);
			}
			return _weatherDataCache[yIndex * defaultWeatherNodeDimension + xIndex];
		}

		private WeatherEvent SetIsRainingOrWetFromFunction(float rainValue, CampaignTime campaignTime, in Vec2 position)
		{
			int defaultWeatherNodeDimension = Campaign.Current.DefaultWeatherNodeDimension;
			int xIndex;
			int yIndex;
			Vec2 adjustedPosition = GetNodePositionForWeather(position, out xIndex, out yIndex);
			if (rainValue >= 0.6f)
			{
				float frequency = (rainValue - 0.6f) / 0.39999998f;
				uint seed = GetSeed(campaignTime, position);
				_weatherDataCache[yIndex * defaultWeatherNodeDimension + xIndex] = WeatherEvent.Clear;
				if (GetCurrentWeatherInAdjustedPosition(seed, frequency, 0.45f, in adjustedPosition))
				{
					_weatherDataCache[yIndex * defaultWeatherNodeDimension + xIndex] = WeatherEvent.HeavyRain;
				}
				else
				{
					CampaignTime campaignTime2 = new CampaignTime(campaignTime.NumTicks - WeatherUpdatePeriod.NumTicks);
					uint seed2 = GetSeed(campaignTime2, position);
					GetSnowAndRainDataForPosition(position, campaignTime2, out var snowValue, out var rainValue2);
					float frequency2 = (rainValue2 - 0.6f) / 0.39999998f;
					while (campaignTime.NumTicks - campaignTime2.NumTicks < PreviousRainDataCheckForWetness.NumTicks)
					{
						if (GetCurrentWeatherInAdjustedPosition(seed2, frequency2, 0.45f, in adjustedPosition))
						{
							_weatherDataCache[yIndex * defaultWeatherNodeDimension + xIndex] = WeatherEvent.LightRain;
							break;
						}
						campaignTime2 = new CampaignTime(campaignTime2.NumTicks - WeatherUpdatePeriod.NumTicks);
						seed2 = GetSeed(campaignTime2, position);
						GetSnowAndRainDataForPosition(position, campaignTime2, out snowValue, out rainValue2);
						frequency2 = (rainValue2 - 0.6f) / 0.39999998f;
					}
				}
			}
			else
			{
				_weatherDataCache[yIndex * defaultWeatherNodeDimension + xIndex] = WeatherEvent.Clear;
			}
			return _weatherDataCache[yIndex * defaultWeatherNodeDimension + xIndex];
		}

		private bool GetCurrentWeatherInAdjustedPosition(uint seed, float frequency, float chanceModifier, in Vec2 adjustedPosition)
		{
			return frequency * chanceModifier > MBRandom.RandomFloatWithSeed(seed, (uint)(Campaign.MapDiagonal * adjustedPosition.X + adjustedPosition.Y));
		}

		private string GetSelectedAtmosphereId(CampaignTime.Seasons selectedSeason, bool isRaining, float snowValue, float rainValue)
		{
			string result = "semicloudy_field_battle";
			if (Settlement.CurrentSettlement != null && (Settlement.CurrentSettlement.IsFortification || Settlement.CurrentSettlement.IsVillage))
			{
				result = "semicloudy_" + Settlement.CurrentSettlement.Culture.StringId;
			}
			if (selectedSeason == CampaignTime.Seasons.Winter)
			{
				result = ((!(snowValue >= 0.85f)) ? "semi_snowy" : "dense_snowy");
			}
			else
			{
				if (rainValue > 0.6f)
				{
					result = "wet";
				}
				if (isRaining)
				{
					result = ((!(rainValue >= 0.85f)) ? "semi_rainy" : "dense_rainy");
				}
			}
			return result;
		}

		private void GetSeasonRainAndSnowDataForOpeningMission(Vec2 position, out CampaignTime.Seasons selectedSeason, out bool isRaining, out float rainValue, out float snowFallDensity)
		{
			WeatherEvent weatherEventInPosition = Campaign.Current.Models.MapWeatherModel.GetWeatherEventInPosition(position);
			WeatherEventEffectOnTerrain weatherEffectOnTerrainForPosition = Campaign.Current.Models.MapWeatherModel.GetWeatherEffectOnTerrainForPosition(position);
			selectedSeason = CampaignTime.Now.GetSeasonOfYear;
			rainValue = 0f;
			snowFallDensity = 0.85f;
			isRaining = false;
			switch (weatherEventInPosition)
			{
			case WeatherEvent.Clear:
				if (selectedSeason == CampaignTime.Seasons.Winter)
				{
					selectedSeason = ((CampaignTime.Now.GetDayOfSeason <= CampaignTime.DaysInSeason / 2) ? CampaignTime.Seasons.Autumn : CampaignTime.Seasons.Spring);
				}
				break;
			case WeatherEvent.LightRain:
				if (selectedSeason == CampaignTime.Seasons.Winter)
				{
					selectedSeason = ((CampaignTime.Now.GetDayOfSeason <= CampaignTime.DaysInSeason / 2) ? CampaignTime.Seasons.Autumn : CampaignTime.Seasons.Spring);
				}
				rainValue = 0.7f;
				break;
			case WeatherEvent.HeavyRain:
				if (selectedSeason == CampaignTime.Seasons.Winter)
				{
					selectedSeason = ((CampaignTime.Now.GetDayOfSeason <= CampaignTime.DaysInSeason / 2) ? CampaignTime.Seasons.Autumn : CampaignTime.Seasons.Spring);
				}
				isRaining = true;
				rainValue = 0.85f + MBRandom.RandomFloatRanged(0f, 0.14999998f);
				break;
			case WeatherEvent.Snowy:
				selectedSeason = CampaignTime.Seasons.Winter;
				rainValue = 0.55f;
				snowFallDensity = 0.55f + MBRandom.RandomFloatRanged(0f, 0.3f);
				break;
			case WeatherEvent.Blizzard:
				selectedSeason = CampaignTime.Seasons.Winter;
				rainValue = 0.85f;
				snowFallDensity = 0.85f;
				break;
			case WeatherEvent.Storm:
				isRaining = true;
				rainValue = 0.85f + MBRandom.RandomFloatRanged(0f, 0.14999998f);
				snowFallDensity = ((selectedSeason != CampaignTime.Seasons.Winter) ? 0f : snowFallDensity);
				break;
			}
			if (weatherEffectOnTerrainForPosition == WeatherEventEffectOnTerrain.Wet)
			{
				rainValue = TaleWorlds.Library.MathF.Max(0.6f, rainValue);
			}
		}

		private SunPosition GetSunPosition(float hourNorm, float seasonFactor)
		{
			float altitude;
			float angle;
			if (hourNorm >= SunRiseNorm && hourNorm < SunSetNorm)
			{
				_sunIsMoon = false;
				float amount = (hourNorm - SunRiseNorm) / (SunSetNorm - SunRiseNorm);
				altitude = MBMath.Lerp(0f, 180f, amount);
				angle = 50f * seasonFactor;
			}
			else
			{
				_sunIsMoon = true;
				if (hourNorm >= SunSetNorm)
				{
					hourNorm -= 1f;
				}
				float num = (hourNorm - (SunSetNorm - 1f)) / (SunRiseNorm - (SunSetNorm - 1f));
				num = ((num < 0f) ? 0f : ((num > 1f) ? 1f : num));
				altitude = MBMath.Lerp(180f, 0f, num);
				angle = 50f * seasonFactor;
			}
			return new SunPosition(angle, altitude);
		}

		private Vec3 GetSunColor(float environmentMultiplier)
		{
			if (!_sunIsMoon)
			{
				return new Vec3(1f, 1f - (1f - TaleWorlds.Library.MathF.Pow(environmentMultiplier, 0.3f)) / 2f, 0.9f - (1f - TaleWorlds.Library.MathF.Pow(environmentMultiplier, 0.3f)) / 2.5f);
			}
			Vec3 v = new Vec3(0.85f - TaleWorlds.Library.MathF.Pow(environmentMultiplier, 0.4f), 0.8f - TaleWorlds.Library.MathF.Pow(environmentMultiplier, 0.5f), 0.8f - TaleWorlds.Library.MathF.Pow(environmentMultiplier, 0.8f));
			return Vec3.Vec3Max(v, new Vec3(0.05f, 0.05f, 0.1f));
		}

		private float GetSunBrightness(float environmentMultiplier, bool forceDay = false)
		{
			if (!_sunIsMoon || forceDay)
			{
				float a = TaleWorlds.Library.MathF.Sin(TaleWorlds.Library.MathF.Pow((environmentMultiplier - 0.001f) / 0.999f, 1.2f) * (System.MathF.PI / 2f)) * 85f;
				return TaleWorlds.Library.MathF.Min(TaleWorlds.Library.MathF.Max(a, 0.2f), 35f);
			}
			return 0.2f;
		}

		private float GetSunSize(float envMultiplier)
		{
			return 0.1f + (1f - envMultiplier) / 8f;
		}

		private float GetSunRayStrength(float envMultiplier)
		{
			return TaleWorlds.Library.MathF.Min(TaleWorlds.Library.MathF.Max(TaleWorlds.Library.MathF.Sin(TaleWorlds.Library.MathF.Pow((envMultiplier - 0.001f) / 0.999f, 0.4f) * System.MathF.PI / 2f) - 0.15f, 0.01f), 0.5f);
		}

		private float GetEnvironmentMultiplier(SunPosition sunPos)
		{
			float num = ((!_sunIsMoon) ? (sunPos.Altitude / 180f * 2f) : (sunPos.Altitude / 180f * 2f));
			num = ((num > 1f) ? (2f - num) : num);
			num = TaleWorlds.Library.MathF.Pow(num, 0.5f);
			float num2 = 1f - 1f / 90f * sunPos.Angle;
			float num3 = MBMath.ClampFloat(num * num2, 0f, 1f);
			return MBMath.ClampFloat(TaleWorlds.Library.MathF.Min(TaleWorlds.Library.MathF.Sin(num3 * num3) * 2f, 1f), 0f, 1f) * 0.999f + 0.001f;
		}

		private float GetModifiedEnvironmentMultiplier(float envMultiplier)
		{
			float num;
			if (!_sunIsMoon)
			{
				num = (envMultiplier - 0.001f) / 0.999f;
				return num * 0.999f + 0.001f;
			}
			num = (envMultiplier - 0.001f) / 0.999f;
			return num * 0f + 0.001f;
		}

		private float GetSkyBrightness(float hourNorm, float envMultiplier)
		{
			float num = 0f;
			float x = (envMultiplier - 0.001f) / 0.999f;
			if (!_sunIsMoon)
			{
				num = TaleWorlds.Library.MathF.Sin(TaleWorlds.Library.MathF.Pow(x, 1.3f) * (System.MathF.PI / 2f)) * 80f;
				num -= 1f;
				return TaleWorlds.Library.MathF.Min(TaleWorlds.Library.MathF.Max(num, 0.055f), 25f);
			}
			return 0.055f;
		}

		private float GetFogDensity(float environmentMultiplier, Vec3 pos)
		{
			float num = (_sunIsMoon ? 0.5f : 0.4f);
			float num2 = 1f - environmentMultiplier;
			float num3 = 1f - MBMath.ClampFloat((pos.z - 30f) / 200f, 0f, 0.9f);
			return TaleWorlds.Library.MathF.Min((0f + num * num2) * num3, 10f);
		}

		private Vec3 GetFogColor(float environmentMultiplier)
		{
			if (!_sunIsMoon)
			{
				return new Vec3(1f - (1f - environmentMultiplier) / 7f, 0.75f - environmentMultiplier / 4f, 0.55f - environmentMultiplier / 5f);
			}
			Vec3 v = new Vec3(1f - environmentMultiplier * 10f, 0.75f + environmentMultiplier * 1.5f, 0.65f + environmentMultiplier * 2f);
			return Vec3.Vec3Max(v, new Vec3(0.55f, 0.59f, 0.6f));
		}

		private Vec3 GetAmbientFogColor(float moddedEnvMul)
		{
			return Vec3.Vec3Min(new Vec3(0.15f, 0.3f, 0.5f) + new Vec3(moddedEnvMul / 3f, moddedEnvMul / 2f, moddedEnvMul / 1.5f), new Vec3(1f, 1f, 1f));
		}

		private float GetMieScatterStrength(float envMultiplier)
		{
			return (1f + (1f - envMultiplier)) * 10f;
		}

		private float GetRayleighConstant(float envMultiplier)
		{
			float num = (envMultiplier - 0.001f) / 0.999f;
			return TaleWorlds.Library.MathF.Min(TaleWorlds.Library.MathF.Max(1f - TaleWorlds.Library.MathF.Sin(TaleWorlds.Library.MathF.Pow(num, 0.45f) * System.MathF.PI / 2f) + (0.14f + num * 2f), 0.65f), 0.99f);
		}

		private float GetHourOfDay()
		{
			return (float)(CampaignTime.Now.ToHours % (double)CampaignTime.HoursInDay);
		}

		private float GetHourOfDayNormalized()
		{
			return GetHourOfDay() / (float)CampaignTime.HoursInDay;
		}

		private float GetNightTimeFactor()
		{
			float num = GetHourOfDay() - (float)CampaignTime.SunRise;
			for (num %= (float)CampaignTime.HoursInDay; num < 0f; num += (float)CampaignTime.HoursInDay)
			{
			}
			num = TaleWorlds.Library.MathF.Max(num - DayTime, 0f);
			return TaleWorlds.Library.MathF.Min(num / 0.1f, 1f);
		}

		private float GetExposureCoefficientBetweenDayNight()
		{
			float hourOfDay = GetHourOfDay();
			float result = 0f;
			if (hourOfDay > (float)CampaignTime.SunRise && hourOfDay < (float)(CampaignTime.SunRise + 2))
			{
				result = 1f - (hourOfDay - (float)CampaignTime.SunRise) / 2f;
			}
			if (hourOfDay < (float)CampaignTime.SunSet && hourOfDay > (float)(CampaignTime.SunSet - 2))
			{
				result = (hourOfDay - (float)(CampaignTime.SunSet - 2)) / 2f;
			}
			if (hourOfDay > (float)CampaignTime.SunSet || hourOfDay < (float)CampaignTime.SunRise)
			{
				result = 1f;
			}
			return result;
		}

		public override void GetSnowAndRainDataForPosition(Vec2 position, CampaignTime ct, out float snowValue, out float rainValue)
		{
			int xIndex;
			int yIndex;
			Vec2 nodePositionForWeather = GetNodePositionForWeather(position, out xIndex, out yIndex);
			float snowAmountAtPosition = Campaign.Current.MapSceneWrapper.GetSnowAmountAtPosition(position);
			float rainAmountAtPosition = Campaign.Current.MapSceneWrapper.GetRainAmountAtPosition(nodePositionForWeather);
			float value = snowAmountAtPosition / 255f;
			float value2 = rainAmountAtPosition / 255f;
			Campaign.Current.Models.MapWeatherModel.GetSeasonTimeFactorOfCampaignTime(ct, out var timeFactorForSnow, out var timeFactorForRain);
			float num = MBMath.Lerp(0.55f, -0.1f, timeFactorForSnow);
			float num2 = MBMath.Lerp(0.7f, 0.3f, timeFactorForRain);
			float num3 = MBMath.SmoothStep(num - 0.65f, num + 0.65f, value);
			float num4 = MBMath.SmoothStep(num2 - 0.45f, num2 + 0.45f, value2);
			snowValue = MBMath.Lerp(0f, num3, num3);
			rainValue = num4;
		}

		public override WeatherEvent GetWeatherEventInPosition(Vec2 pos)
		{
			GetNodePositionForWeather(pos, out var xIndex, out var yIndex);
			return _weatherDataCache[yIndex * Campaign.Current.DefaultWeatherNodeDimension + xIndex];
		}

		public override WeatherEventEffectOnTerrain GetWeatherEffectOnTerrainForPosition(Vec2 pos)
		{
			return GetWeatherEventInPosition(pos) switch
			{
				WeatherEvent.Clear => WeatherEventEffectOnTerrain.Default, 
				WeatherEvent.LightRain => WeatherEventEffectOnTerrain.Wet, 
				WeatherEvent.HeavyRain => WeatherEventEffectOnTerrain.Wet, 
				WeatherEvent.Snowy => WeatherEventEffectOnTerrain.Wet, 
				WeatherEvent.Blizzard => WeatherEventEffectOnTerrain.Wet, 
				_ => WeatherEventEffectOnTerrain.Default, 
			};
		}

		private float GetWinterTimeFactor(CampaignTime timeOfYear)
		{
			float result = 0f;
			if (timeOfYear.GetSeasonOfYear == CampaignTime.Seasons.Winter)
			{
				float amount = TaleWorlds.Library.MathF.Abs((float)Math.IEEERemainder(CampaignTime.Now.ToSeasons, 1.0));
				result = MBMath.SplitLerp(0f, 0.75f, 0f, 0.5f, amount, 1E-05f);
			}
			return result;
		}

		private float GetDrynessFactor(CampaignTime timeOfYear)
		{
			float result = 0f;
			float num = TaleWorlds.Library.MathF.Abs((float)Math.IEEERemainder(CampaignTime.Now.ToSeasons, 1.0));
			switch (timeOfYear.GetSeasonOfYear)
			{
			case CampaignTime.Seasons.Summer:
			{
				float amount = MBMath.ClampFloat(num * 2f, 0f, 1f);
				result = MBMath.Lerp(0f, 1f, amount);
				break;
			}
			case CampaignTime.Seasons.Autumn:
				result = 1f;
				break;
			case CampaignTime.Seasons.Winter:
				result = MBMath.Lerp(1f, 0f, num);
				break;
			}
			return result;
		}

		public override void GetSeasonTimeFactorOfCampaignTime(CampaignTime ct, out float timeFactorForSnow, out float timeFactorForRain, bool snapCampaignTimeToWeatherPeriod = true)
		{
			if (snapCampaignTimeToWeatherPeriod)
			{
				ct = CampaignTime.Hours((int)(ct.ToHours / WeatherUpdatePeriod.ToHours / 2.0) * (int)WeatherUpdatePeriod.ToHours * 2);
			}
			float yearProgress = (float)ct.ToSeasons % 4f;
			timeFactorForSnow = CalculateTimeFactorForSnow(yearProgress);
			timeFactorForRain = CalculateTimeFactorForRain(yearProgress);
		}

		private float CalculateTimeFactorForSnow(float yearProgress)
		{
			float result = 0f;
			if (yearProgress > 1.5f && (double)yearProgress <= 3.5)
			{
				result = MBMath.Map(yearProgress, 1.5f, 3.5f, 0f, 1f);
			}
			else if (yearProgress <= 1.5f)
			{
				result = MBMath.Map(yearProgress, 0f, 1.5f, 0.75f, 0f);
			}
			else if (yearProgress > 3.5f)
			{
				result = MBMath.Map(yearProgress, 3.5f, 4f, 1f, 0.75f);
			}
			return result;
		}

		private float CalculateTimeFactorForRain(float yearProgress)
		{
			float result = 0f;
			if (yearProgress > 1f && (double)yearProgress <= 2.5)
			{
				result = MBMath.Map(yearProgress, 1f, 2.5f, 0f, 1f);
			}
			else if (yearProgress <= 1f)
			{
				result = MBMath.Map(yearProgress, 0f, 1f, 1f, 0f);
			}
			else if (yearProgress > 2.5f)
			{
				result = 1f;
			}
			return result;
		}

		private float GetTemperature(ref AtmosphereState gridInfo, float seasonFactor)
		{
			if (gridInfo == null)
			{
				return 0f;
			}
			float temperatureAverage = gridInfo.TemperatureAverage;
			float num = (seasonFactor - 0.5f) * -2f;
			float num2 = gridInfo.TemperatureVariance * num;
			return temperatureAverage + num2;
		}

		private float GetHumidity(ref AtmosphereState gridInfo, float seasonFactor)
		{
			if (gridInfo == null)
			{
				return 0f;
			}
			float humidityAverage = gridInfo.HumidityAverage;
			float num = (seasonFactor - 0.5f) * 2f;
			float num2 = gridInfo.HumidityVariance * num;
			return MBMath.ClampFloat(humidityAverage + num2, 0f, 100f);
		}

		public override Vec2 GetWindForPosition(CampaignVec2 position)
		{
			return Vec2.Side * 0.26f;
		}

		private float GetWaveStrengthForPosition(CampaignVec2 position)
		{
			if (position.IsOnLand)
			{
				return 0.26f;
			}
			return Campaign.Current.Models.MapWeatherModel.GetWindForPosition(position).Length;
		}
	}
	public class DefaultMarriageModel : MarriageModel
	{
		private const float BaseMarriageChanceForNpcs = 0.002f;

		public override int MinimumMarriageAgeMale => 18;

		public override int MinimumMarriageAgeFemale => 18;

		public override bool IsCoupleSuitableForMarriage(Hero firstHero, Hero secondHero)
		{
			if (!IsClanSuitableForMarriage(firstHero.Clan) || !IsClanSuitableForMarriage(secondHero.Clan) || (firstHero.Clan?.Leader == firstHero && secondHero.Clan?.Leader == secondHero) || firstHero.IsFemale == secondHero.IsFemale || AreHeroesRelated(firstHero, secondHero, 3))
			{
				return false;
			}
			Hero courtedHeroInOtherClan = Romance.GetCourtedHeroInOtherClan(firstHero, secondHero);
			if (courtedHeroInOtherClan != null && courtedHeroInOtherClan != secondHero)
			{
				return false;
			}
			Hero courtedHeroInOtherClan2 = Romance.GetCourtedHeroInOtherClan(secondHero, firstHero);
			if (courtedHeroInOtherClan2 != null && courtedHeroInOtherClan2 != firstHero)
			{
				return false;
			}
			if (firstHero.CanMarry())
			{
				return secondHero.CanMarry();
			}
			return false;
		}

		public override bool IsClanSuitableForMarriage(Clan clan)
		{
			if (clan != null && !clan.IsBanditFaction && !clan.IsRebelClan)
			{
				return !clan.IsEliminated;
			}
			return false;
		}

		public override float NpcCoupleMarriageChance(Hero firstHero, Hero secondHero)
		{
			if (IsCoupleSuitableForMarriage(firstHero, secondHero))
			{
				float num = 0.002f;
				num *= 1f + (firstHero.Age - (float)Campaign.Current.Models.AgeModel.HeroComesOfAge) / 50f;
				num *= 1f + (secondHero.Age - (float)Campaign.Current.Models.AgeModel.HeroComesOfAge) / 50f;
				num *= 1f - TaleWorlds.Library.MathF.Abs(secondHero.Age - firstHero.Age) / 50f;
				if (firstHero.Clan.Kingdom != secondHero.Clan.Kingdom)
				{
					num *= 0.5f;
				}
				float num2 = 0.5f + (float)firstHero.Clan.GetRelationWithClan(secondHero.Clan) / 200f;
				return num * num2;
			}
			return 0f;
		}

		public override bool ShouldNpcMarriageBetweenClansBeAllowed(Clan consideringClan, Clan targetClan)
		{
			if (targetClan != consideringClan && !consideringClan.IsAtWarWith(targetClan))
			{
				return consideringClan.GetRelationWithClan(targetClan) >= -50;
			}
			return false;
		}

		public override List<Hero> GetAdultChildrenSuitableForMarriage(Hero hero)
		{
			List<Hero> list = new List<Hero>();
			foreach (Hero child in hero.Children)
			{
				if (child.CanMarry())
				{
					list.Add(child);
				}
			}
			return list;
		}

		private bool AreHeroesRelatedAux1(Hero firstHero, Hero secondHero, int ancestorDepth)
		{
			if (firstHero != secondHero)
			{
				if (ancestorDepth > 0)
				{
					if (secondHero.Mother == null || !AreHeroesRelatedAux1(firstHero, secondHero.Mother, ancestorDepth - 1))
					{
						if (secondHero.Father != null)
						{
							return AreHeroesRelatedAux1(firstHero, secondHero.Father, ancestorDepth - 1);
						}
						return false;
					}
					return true;
				}
				return false;
			}
			return true;
		}

		private bool AreHeroesRelatedAux2(Hero firstHero, Hero secondHero, int ancestorDepth, int secondAncestorDepth)
		{
			if (!AreHeroesRelatedAux1(firstHero, secondHero, secondAncestorDepth))
			{
				if (ancestorDepth > 0)
				{
					if (firstHero.Mother == null || !AreHeroesRelatedAux2(firstHero.Mother, secondHero, ancestorDepth - 1, secondAncestorDepth))
					{
						if (firstHero.Father != null)
						{
							return AreHeroesRelatedAux2(firstHero.Father, secondHero, ancestorDepth - 1, secondAncestorDepth);
						}
						return false;
					}
					return true;
				}
				return false;
			}
			return true;
		}

		private bool AreHeroesRelated(Hero firstHero, Hero secondHero, int ancestorDepth)
		{
			return AreHeroesRelatedAux2(firstHero, secondHero, ancestorDepth, ancestorDepth);
		}

		public override int GetEffectiveRelationIncrease(Hero firstHero, Hero secondHero)
		{
			ExplainedNumber explainedNumber = new ExplainedNumber(20f);
			SkillHelper.AddSkillBonusForCharacter(DefaultSkillEffects.CharmRelationBonus, firstHero.IsFemale ? secondHero.CharacterObject : firstHero.CharacterObject, ref explainedNumber);
			return TaleWorlds.Library.MathF.Round(explainedNumber.ResultNumber);
		}

		public override bool IsSuitableForMarriage(Hero maidenOrSuitor)
		{
			if (maidenOrSuitor.IsActive && maidenOrSuitor.Spouse == null && maidenOrSuitor.IsLord && !maidenOrSuitor.IsMinorFactionHero && !maidenOrSuitor.IsNotable && !maidenOrSuitor.IsTemplate && maidenOrSuitor.PartyBelongedTo?.MapEvent == null && maidenOrSuitor.PartyBelongedTo?.Army == null)
			{
				IMarriageOfferCampaignBehavior campaignBehavior = Campaign.Current.GetCampaignBehavior<IMarriageOfferCampaignBehavior>();
				if (campaignBehavior != null && campaignBehavior.IsHeroEngaged(maidenOrSuitor))
				{
					return false;
				}
				if (maidenOrSuitor.IsFemale)
				{
					return maidenOrSuitor.CharacterObject.Age >= (float)MinimumMarriageAgeFemale;
				}
				return maidenOrSuitor.CharacterObject.Age >= (float)MinimumMarriageAgeMale;
			}
			return false;
		}

		public override Clan GetClanAfterMarriage(Hero firstHero, Hero secondHero)
		{
			if (firstHero.IsHumanPlayerCharacter)
			{
				return firstHero.Clan;
			}
			if (secondHero.IsHumanPlayerCharacter)
			{
				return secondHero.Clan;
			}
			if (firstHero.Clan.Leader == firstHero)
			{
				return firstHero.Clan;
			}
			if (secondHero.Clan.Leader == secondHero)
			{
				return secondHero.Clan;
			}
			if (!firstHero.IsFemale)
			{
				return firstHero.Clan;
			}
			return secondHero.Clan;
		}
	}
