		}

		private int GetStarvationMoralePenalty(MobileParty party)
		{
			return -30;
		}

		private int GetNoWageMoralePenalty(MobileParty party)
		{
			return -20;
		}

		public override float GetStandardBaseMorale(PartyBase party)
		{
			return 50f;
