	public class DefaultPartyTroopUpgradeModel : PartyTroopUpgradeModel
	{
		public override bool CanPartyUpgradeTroopToTarget(PartyBase upgradingParty, CharacterObject upgradeableCharacter, CharacterObject upgradeTarget)
		{
			bool flag = Campaign.Current.Models.PartyTroopUpgradeModel.DoesPartyHaveRequiredItemsForUpgrade(upgradingParty, upgradeTarget);
			PerkObject requiredPerk;
			bool flag2 = Campaign.Current.Models.PartyTroopUpgradeModel.DoesPartyHaveRequiredPerksForUpgrade(upgradingParty, upgradeableCharacter, upgradeTarget, out requiredPerk);
			return Campaign.Current.Models.PartyTroopUpgradeModel.IsTroopUpgradeable(upgradingParty, upgradeableCharacter) && upgradeableCharacter.UpgradeTargets.Contains(upgradeTarget) && flag2 && flag;
		}

		public override bool IsTroopUpgradeable(PartyBase party, CharacterObject character)
		{
			if (!character.IsHero)
			{
				return character.UpgradeTargets.Length != 0;
			}
			return false;
		}

		public override int GetXpCostForUpgrade(PartyBase party, CharacterObject characterObject, CharacterObject upgradeTarget)
		{
			if (upgradeTarget != null && characterObject.UpgradeTargets.Contains(upgradeTarget))
			{
				int tier = upgradeTarget.Tier;
				int num = 0;
				for (int i = characterObject.Tier + 1; i <= tier; i++)
				{
					if (i <= 1)
					{
						num += 100;
						continue;
					}
					switch (i)
					{
					case 2:
						num += 300;
						break;
					case 3:
						num += 550;
						break;
					case 4:
						num += 900;
						break;
					case 5:
						num += 1300;
						break;
					case 6:
						num += 1700;
						break;
					case 7:
						num += 2100;
						break;
					default:
					{
						int num2 = upgradeTarget.Level + 4;
						num += (int)(1.333f * (float)num2 * (float)num2);
						break;
					}
					}
				}
				return num;
			}
			return 100000000;
		}

		public override ExplainedNumber GetGoldCostForUpgrade(PartyBase party, CharacterObject characterObject, CharacterObject upgradeTarget)
		{
			PartyWageModel partyWageModel = Campaign.Current.Models.PartyWageModel;
			int roundedResultNumber = partyWageModel.GetTroopRecruitmentCost(upgradeTarget, null, withoutItemCost: true).RoundedResultNumber;
			int roundedResultNumber2 = partyWageModel.GetTroopRecruitmentCost(characterObject, null, withoutItemCost: true).RoundedResultNumber;
			bool flag = characterObject.Occupation == Occupation.Mercenary || characterObject.Occupation == Occupation.Gangster;
			ExplainedNumber stat = new ExplainedNumber((float)(roundedResultNumber - roundedResultNumber2) / ((!flag) ? 2f : 3f));
			if (party.MobileParty.HasPerk(DefaultPerks.Steward.SoundReserves))
			{
				PerkHelper.AddPerkBonusForParty(DefaultPerks.Steward.SoundReserves, party.MobileParty, isPrimaryBonus: true, ref stat);
			}
			if (characterObject.IsRanged && party.MobileParty.HasPerk(DefaultPerks.Bow.RenownedArcher, checkSecondaryRole: true))
			{
				PerkHelper.AddPerkBonusForParty(DefaultPerks.Bow.RenownedArcher, party.MobileParty, isPrimaryBonus: false, ref stat);
			}
			if (characterObject.IsMounted && PartyBaseHelper.HasFeat(party, DefaultCulturalFeats.KhuzaitRecruitUpgradeFeat))
			{
				stat.AddFactor(DefaultCulturalFeats.KhuzaitRecruitUpgradeFeat.EffectBonus, GameTexts.FindText("str_culture"));
			}
			if (flag && party.MobileParty.HasPerk(DefaultPerks.Steward.Contractors))
			{
				PerkHelper.AddPerkBonusForParty(DefaultPerks.Steward.Contractors, party.MobileParty, isPrimaryBonus: true, ref stat);
			}
			return stat;
		}

		public override int GetSkillXpFromUpgradingTroops(PartyBase party, CharacterObject troop, int numberOfTroops)
		{
			return (troop.Level + 10) * numberOfTroops;
		}

		public override bool DoesPartyHaveRequiredItemsForUpgrade(PartyBase party, CharacterObject upgradeTarget)
		{
			ItemCategory upgradeRequiresItemFromCategory = upgradeTarget.UpgradeRequiresItemFromCategory;
			if (upgradeRequiresItemFromCategory != null)
			{
				int num = 0;
				for (int i = 0; i < party.ItemRoster.Count; i++)
				{
					ItemRosterElement itemRosterElement = party.ItemRoster[i];
					if (itemRosterElement.EquipmentElement.Item.ItemCategory == upgradeRequiresItemFromCategory)
					{
						num += itemRosterElement.Amount;
					}
				}
				return num > 0;
			}
			return true;
		}

		public override bool DoesPartyHaveRequiredPerksForUpgrade(PartyBase party, CharacterObject character, CharacterObject upgradeTarget, out PerkObject requiredPerk)
		{
			requiredPerk = null;
			if (character.Culture.IsBandit && !upgradeTarget.Culture.IsBandit)
			{
				requiredPerk = DefaultPerks.Leadership.VeteransRespect;
				return party.MobileParty.HasPerk(requiredPerk, checkSecondaryRole: true);
			}
			return true;
		}

		public override float GetUpgradeChanceForTroopUpgrade(PartyBase party, CharacterObject troop, int upgradeTargetIndex)
		{
			float result = 1f;
			int num = troop.UpgradeTargets.Length;
			if (num > 1 && upgradeTargetIndex >= 0 && upgradeTargetIndex < num)
			{
				if (party.LeaderHero != null && party.LeaderHero.PreferredUpgradeFormation != FormationClass.NumberOfAllFormations)
				{
					FormationClass preferredUpgradeFormation = party.LeaderHero.PreferredUpgradeFormation;
					if (CharacterHelper.SearchForFormationInTroopTree(troop.UpgradeTargets[upgradeTargetIndex], preferredUpgradeFormation))
					{
						result = 9999f;
					}
				}
				else
				{
					int num2 = party.LeaderHero?.RandomValue ?? party.Id.GetHashCode();
					int deterministicHashCode = troop.StringId.GetDeterministicHashCode();
					uint num3 = (uint)((num2 >> troop.Tier * 3) ^ deterministicHashCode);
					if (upgradeTargetIndex == num3 % num)
					{
						result = 9999f;
					}
				}
			}
			return result;
		}
	}
	public class DefaultPartyWageModel : PartyWageModel
	{
		private readonly TextObject _cultureText = GameTexts.FindText("str_culture");

		private readonly TextObject _buildingEffects = GameTexts.FindText("str_building_effects");

		private const float MercenaryWageFactor = 1.5f;

		public override int MaxWagePaymentLimit => 10000;

		public override int GetCharacterWage(CharacterObject character)
		{
			int num = character.Tier switch
			{
				0 => 1, 
				1 => 2, 
				2 => 3, 
				3 => 5, 
				4 => 8, 
				5 => 12, 
				6 => 17, 
				_ => 23, 
			};
			if (character.Occupation == Occupation.Mercenary)
			{
				num = (int)((float)num * 1.5f);
			}
			return num;
		}

		public override ExplainedNumber GetTotalWage(MobileParty mobileParty, TroopRoster troopRoster, bool includeDescriptions = false)
		{
			int num = 0;
			int num2 = 0;
			int num3 = 0;
			int num4 = 0;
			int num5 = 0;
			int num6 = 0;
			bool flag = !mobileParty.HasPerk(DefaultPerks.Steward.AidCorps);
			int num7 = 0;
			int num8 = 0;
			for (int i = 0; i < troopRoster.Count; i++)
			{
				TroopRosterElement elementCopyAtIndex = troopRoster.GetElementCopyAtIndex(i);
				CharacterObject character = elementCopyAtIndex.Character;
				if (!flag)
				{
					_ = elementCopyAtIndex.Number;
					_ = elementCopyAtIndex.WoundedNumber;
				}
				else
				{
					_ = elementCopyAtIndex.Number;
				}
				if (character.IsHero)
				{
					bool flag2 = mobileParty.IsMainParty && character.HeroObject.Clan == Clan.PlayerClan && character.HeroObject.Occupation == Occupation.Lord;
					if (elementCopyAtIndex.Character.HeroObject != character.HeroObject.Clan?.Leader && !flag2)
					{
						num = ((mobileParty.LeaderHero == null || !mobileParty.LeaderHero.GetPerkValue(DefaultPerks.Steward.PaidInPromise)) ? (num + character.TroopWage) : (num + TaleWorlds.Library.MathF.Round((float)character.TroopWage * (1f + DefaultPerks.Steward.PaidInPromise.PrimaryBonus))));
					}
					continue;
				}
				int num9 = character.TroopWage * elementCopyAtIndex.Number;
				num += num9;
				if (character.Culture.IsBandit)
				{
					num6 += num9;
				}
				if (character.IsInfantry)
				{
					num2 += num9;
				}
				if (character.IsMounted)
				{
					num3 += num9;
				}
				if (character.Occupation == Occupation.CaravanGuard)
				{
					num7 += num9;
				}
				if (character.Occupation == Occupation.Mercenary)
				{
					num8 += num9;
				}
				if (character.IsRanged)
				{
					num4 += num9;
					if (character.Tier >= 4)
					{
						num5 += num9;
					}
				}
			}
			if (mobileParty.LeaderHero != null && mobileParty.LeaderHero.GetPerkValue(DefaultPerks.Roguery.DeepPockets))
			{
				num -= num6;
				ExplainedNumber bonuses = new ExplainedNumber(num6);
				PerkHelper.AddPerkBonusForCharacter(DefaultPerks.Roguery.DeepPockets, mobileParty.LeaderHero.CharacterObject, isPrimaryBonus: false, ref bonuses);
				num += (int)bonuses.ResultNumber;
			}
			if (num5 > 0)
			{
				num -= num5;
				ExplainedNumber stat = new ExplainedNumber(num5);
				PerkHelper.AddPerkBonusForParty(DefaultPerks.Crossbow.PickedShots, mobileParty, isPrimaryBonus: true, ref stat, mobileParty.IsCurrentlyAtSea);
				num += (int)stat.ResultNumber;
			}
			ExplainedNumber bonuses2 = new ExplainedNumber(num, includeDescriptions);
			bonuses2.LimitMin(0f);
			ExplainedNumber result = new ExplainedNumber(1f);
			if (mobileParty.IsGarrison && mobileParty.CurrentSettlement?.Town != null)
			{
				if (mobileParty.CurrentSettlement.IsFortification)
				{
					PerkHelper.AddPerkBonusForTown(DefaultPerks.OneHanded.MilitaryTradition, mobileParty.CurrentSettlement.Town, ref bonuses2);
					PerkHelper.AddPerkBonusForTown(DefaultPerks.TwoHanded.Berserker, mobileParty.CurrentSettlement.Town, ref bonuses2);
					PerkHelper.AddPerkBonusForTown(DefaultPerks.Steward.DrillSergant, mobileParty.CurrentSettlement.Town, ref bonuses2);
					float troopRatio = (float)num2 / bonuses2.BaseNumber;
					CalculatePartialGarrisonWageReduction(troopRatio, mobileParty, DefaultPerks.Polearm.StandardBearer, ref bonuses2, isSecondaryEffect: true);
					float troopRatio2 = (float)num4 / bonuses2.BaseNumber;
					CalculatePartialGarrisonWageReduction(troopRatio2, mobileParty, DefaultPerks.Crossbow.PeasantLeader, ref bonuses2, isSecondaryEffect: true);
					float troopRatio3 = (float)num3 / bonuses2.BaseNumber;
					CalculatePartialGarrisonWageReduction(troopRatio3, mobileParty, DefaultPerks.Riding.CavalryTactics, ref bonuses2, isSecondaryEffect: true);
				}
				if (mobileParty.CurrentSettlement.IsCastle)
				{
					PerkHelper.AddPerkBonusForTown(DefaultPerks.Bow.HunterClan, mobileParty.CurrentSettlement.Town, ref bonuses2);
					PerkHelper.AddPerkBonusForTown(DefaultPerks.Steward.StiffUpperLip, mobileParty.CurrentSettlement.Town, ref bonuses2);
				}
				if (mobileParty.CurrentSettlement.Owner.Culture.HasFeat(DefaultCulturalFeats.EmpireGarrisonWageFeat))
				{
					bonuses2.AddFactor(DefaultCulturalFeats.EmpireGarrisonWageFeat.EffectBonus, _cultureText);
				}
				mobileParty.CurrentSettlement.Town.AddEffectOfBuildings(BuildingEffectEnum.GarrisonWageReduction, ref result);
			}
			float value = ((mobileParty.LeaderHero != null && mobileParty.LeaderHero.Clan.Kingdom != null && !mobileParty.LeaderHero.Clan.IsUnderMercenaryService && mobileParty.LeaderHero.Clan.Kingdom.ActivePolicies.Contains(DefaultPolicies.MilitaryCoronae)) ? 0.1f : 0f);
			if (mobileParty.HasPerk(DefaultPerks.Trade.SwordForBarter, checkSecondaryRole: true))
			{
				float num10 = (float)num7 / bonuses2.BaseNumber;
				if (num10 > 0f)
				{
					float value2 = DefaultPerks.Trade.SwordForBarter.SecondaryBonus * num10;
					bonuses2.AddFactor(value2, DefaultPerks.Trade.SwordForBarter.Name);
				}
			}
			if (mobileParty.HasPerk(DefaultPerks.Steward.Contractors))
			{
				float num11 = (float)num8 / bonuses2.BaseNumber;
				if (num11 > 0f)
				{
					float value3 = DefaultPerks.Steward.Contractors.PrimaryBonus * num11;
					bonuses2.AddFactor(value3, DefaultPerks.Steward.Contractors.Name);
				}
			}
			if (mobileParty.HasPerk(DefaultPerks.Trade.MercenaryConnections, checkSecondaryRole: true))
			{
				float num12 = (float)num8 / bonuses2.BaseNumber;
				if (num12 > 0f)
				{
					float value4 = DefaultPerks.Trade.MercenaryConnections.SecondaryBonus * num12;
					bonuses2.AddFactor(value4, DefaultPerks.Trade.MercenaryConnections.Name);
				}
			}
			bonuses2.AddFactor(value, DefaultPolicies.MilitaryCoronae.Name);
			bonuses2.AddFactor(result.ResultNumber - 1f, _buildingEffects);
			if (PartyBaseHelper.HasFeat(mobileParty.Party, DefaultCulturalFeats.AseraiIncreasedWageFeat))
			{
				bonuses2.AddFactor(DefaultCulturalFeats.AseraiIncreasedWageFeat.EffectBonus, _cultureText);
			}
			if (!mobileParty.IsCurrentlyAtSea && mobileParty.HasPerk(DefaultPerks.Steward.Frugal))
			{
				bonuses2.AddFactor(DefaultPerks.Steward.Frugal.PrimaryBonus, DefaultPerks.Steward.Frugal.Name);
			}
			if (mobileParty.Army != null)
			{
				PerkHelper.AddPerkBonusForParty(DefaultPerks.Steward.EfficientCampaigner, mobileParty, isPrimaryBonus: false, ref bonuses2, mobileParty.IsCurrentlyAtSea);
			}
			if (mobileParty.SiegeEvent != null && mobileParty.SiegeEvent.BesiegerCamp.HasInvolvedPartyForEventType(mobileParty.Party) && mobileParty.HasPerk(DefaultPerks.Steward.MasterOfWarcraft))
			{
				bonuses2.AddFactor(DefaultPerks.Steward.MasterOfWarcraft.PrimaryBonus, DefaultPerks.Steward.MasterOfWarcraft.Name);
			}
			if (mobileParty.EffectiveQuartermaster != null)
			{
				PerkHelper.AddEpicPerkBonusForCharacter(DefaultPerks.Steward.PriceOfLoyalty, mobileParty.EffectiveQuartermaster.CharacterObject, DefaultSkills.Steward, applyPrimaryBonus: true, ref bonuses2, Campaign.Current.Models.CharacterDevelopmentModel.MaxSkillRequiredForEpicPerkBonus);
			}
			if (mobileParty.CurrentSettlement != null && mobileParty.LeaderHero != null && mobileParty.LeaderHero.GetPerkValue(DefaultPerks.Trade.ContentTrades))
			{
				bonuses2.AddFactor(DefaultPerks.Trade.ContentTrades.SecondaryBonus, DefaultPerks.Trade.ContentTrades.Name);
			}
			return bonuses2;
		}

		private void CalculatePartialGarrisonWageReduction(float troopRatio, MobileParty mobileParty, PerkObject perk, ref ExplainedNumber garrisonWageReductionMultiplier, bool isSecondaryEffect)
		{
			if (troopRatio > 0f && mobileParty.CurrentSettlement.Town.Governor != null && PerkHelper.GetPerkValueForTown(perk, mobileParty.CurrentSettlement.Town))
			{
				garrisonWageReductionMultiplier.AddFactor(isSecondaryEffect ? (perk.SecondaryBonus * troopRatio) : (perk.PrimaryBonus * troopRatio), perk.Name);
			}
		}

		public override ExplainedNumber GetTroopRecruitmentCost(CharacterObject troop, Hero buyerHero, bool withoutItemCost = false)
		{
			ExplainedNumber result = ((troop.Level <= 1) ? new ExplainedNumber(10f) : ((troop.Level <= 6) ? new ExplainedNumber(20f) : ((troop.Level <= 11) ? new ExplainedNumber(50f) : ((troop.Level <= 16) ? new ExplainedNumber(100f) : ((troop.Level <= 21) ? new ExplainedNumber(200f) : ((troop.Level <= 26) ? new ExplainedNumber(400f) : ((troop.Level <= 31) ? new ExplainedNumber(600f) : ((troop.Level > 36) ? new ExplainedNumber(1500f) : new ExplainedNumber(1000f)))))))));
			if (troop.Equipment.Horse.Item != null && !withoutItemCost)
			{
				if (troop.Level < 26)
				{
					result.Add(150f);
				}
				else
				{
					result.Add(500f);
				}
			}
			bool flag = troop.Occupation == Occupation.Mercenary || troop.Occupation == Occupation.Gangster || troop.Occupation == Occupation.CaravanGuard;
			if (flag)
			{
				result.Add(result.BaseNumber * 2f);
			}
			if (buyerHero != null)
			{
				if (troop.Tier >= 2 && buyerHero.GetPerkValue(DefaultPerks.Throwing.HeadHunter))
				{
					result.AddFactor(DefaultPerks.Throwing.HeadHunter.SecondaryBonus);
				}
				if (troop.IsInfantry)
				{
					if (buyerHero.GetPerkValue(DefaultPerks.OneHanded.ChinkInTheArmor))
					{
						result.AddFactor(DefaultPerks.OneHanded.ChinkInTheArmor.SecondaryBonus);
					}
					if (buyerHero.GetPerkValue(DefaultPerks.TwoHanded.ShowOfStrength))
					{
						result.AddFactor(DefaultPerks.TwoHanded.ShowOfStrength.SecondaryBonus);
					}
					if (buyerHero.GetPerkValue(DefaultPerks.Polearm.HardyFrontline))
					{
						result.AddFactor(DefaultPerks.Polearm.HardyFrontline.SecondaryBonus);
					}
				}
				else if (troop.IsRanged)
				{
					if (buyerHero.GetPerkValue(DefaultPerks.Bow.RenownedArcher))
					{
						result.AddFactor(DefaultPerks.Bow.RenownedArcher.SecondaryBonus);
					}
					if (buyerHero.GetPerkValue(DefaultPerks.Crossbow.Piercer))
					{
						result.AddFactor(DefaultPerks.Crossbow.Piercer.SecondaryBonus);
					}
				}
				if (troop.IsMounted && buyerHero.Culture.HasFeat(DefaultCulturalFeats.KhuzaitRecruitUpgradeFeat))
				{
					result.AddFactor(DefaultCulturalFeats.KhuzaitRecruitUpgradeFeat.EffectBonus, _cultureText);
				}
				if (buyerHero.IsPartyLeader && buyerHero.GetPerkValue(DefaultPerks.Steward.Frugal))
				{
					result.AddFactor(DefaultPerks.Steward.Frugal.SecondaryBonus);
				}
				if (flag)
				{
					if (buyerHero.GetPerkValue(DefaultPerks.Trade.SwordForBarter))
					{
						result.AddFactor(DefaultPerks.Trade.SwordForBarter.PrimaryBonus);
					}
					if (buyerHero.GetPerkValue(DefaultPerks.Charm.SlickNegotiator))
					{
						result.AddFactor(DefaultPerks.Charm.SlickNegotiator.PrimaryBonus);
					}
				}
				result.LimitMin(1f);
			}
			return result;
		}
	}
	public class DefaultPersuasionModel : PersuasionModel
	{
		public override int GetSkillXpFromPersuasion(PersuasionDifficulty difficulty, int argumentDifficultyBonusCoefficient)
		{
			return (int)(difficulty - 0) / 1 * 5 * argumentDifficultyBonusCoefficient;
		}

		public override void GetChances(PersuasionOptionArgs optionArgs, out float successChance, out float critSuccessChance, out float critFailChance, out float failChance, float difficultyMultiplier)
		{
			float defaultSuccessChance = GetDefaultSuccessChance(optionArgs, difficultyMultiplier);
			switch (optionArgs.ArgumentStrength)
			{
			case PersuasionArgumentStrength.ExtremelyHard:
				successChance = defaultSuccessChance * 0.05f;
				critFailChance = defaultSuccessChance * 0.15f;
				break;
			case PersuasionArgumentStrength.VeryHard:
				successChance = defaultSuccessChance * 0.15f;
				critFailChance = defaultSuccessChance * 0.2f;
				break;
			case PersuasionArgumentStrength.Hard:
				successChance = defaultSuccessChance * 0.35f;
				critFailChance = defaultSuccessChance * 0.15f;
				break;
			case PersuasionArgumentStrength.Easy:
				successChance = defaultSuccessChance * 0.7f;
				critFailChance = 0f;
				break;
			case PersuasionArgumentStrength.VeryEasy:
				successChance = defaultSuccessChance * 0.8f;
				critFailChance = 0f;
				break;
			case PersuasionArgumentStrength.ExtremelyEasy:
				successChance = defaultSuccessChance * 0.9f;
				critFailChance = 0f;
				break;
			default:
				successChance = defaultSuccessChance * 0.55f;
				critFailChance = defaultSuccessChance * 0.15f;
				break;
			}
			float bonusSuccessChance = GetBonusSuccessChance(optionArgs);
			successChance = TaleWorlds.Library.MathF.Clamp(successChance * bonusSuccessChance, 0f, 1f);
			critFailChance = TaleWorlds.Library.MathF.Clamp(critFailChance * (2f - bonusSuccessChance), 0f, 1f);
			critSuccessChance = 0f;
			if (optionArgs.GivesCriticalSuccess)
			{
				critSuccessChance = successChance;
				successChance = 0f;
			}
			if (critSuccessChance > 0f && Hero.MainHero.GetPerkValue(DefaultPerks.Charm.MeaningfulFavors))
			{
				critSuccessChance = TaleWorlds.Library.MathF.Clamp(critSuccessChance + critSuccessChance * DefaultPerks.Charm.MeaningfulFavors.PrimaryBonus, 0f, 1f);
			}
			failChance = 1f - critSuccessChance - successChance - critFailChance;
		}

		private float GetDefaultSuccessChance(PersuasionOptionArgs optionArgs, float difficultyMultiplier)
		{
			int skillValue = Hero.MainHero.GetSkillValue(optionArgs.SkillUsed);
			float num = ((optionArgs.TraitEffect == TraitEffect.Positive) ? Hero.MainHero.GetTraitLevel(optionArgs.TraitUsed) : (-Hero.MainHero.GetTraitLevel(optionArgs.TraitUsed)));
			num = MBMath.ClampFloat((optionArgs.TraitUsed != null) ? num : 0f, -1f, 2f);
			float num2 = 0f;
			num2 = ((num <= 0f) ? (0.2f + (num - -1f) * 0.4f) : ((!(num <= 1f)) ? (1.2f + (num - 1f) * 0.4f) : (0.6f + (num - 0f) * 0.6f)));
			return TaleWorlds.Library.MathF.Clamp((100f - difficultyMultiplier / (0.01f * (100f + (float)skillValue * num2))) / 100f, 0.1f, 1f);
		}

		private float GetBonusSuccessChance(PersuasionOptionArgs optionArgs)
		{
			ExplainedNumber explainedNumber = new ExplainedNumber(1f);
			explainedNumber.AddFactor(TaleWorlds.Library.MathF.Clamp((float)(Hero.MainHero.GetSkillValue(optionArgs.SkillUsed) / Campaign.Current.Models.CharacterDevelopmentModel.MaxSkillRequiredForEpicPerkBonus) * 0.2f, 0f, 0.2f), optionArgs.SkillUsed.Name);
			if (Hero.MainHero.GetPerkValue(DefaultPerks.Athletics.ImposingStature))
			{
				explainedNumber.AddFactor(DefaultPerks.Athletics.ImposingStature.PrimaryBonus, DefaultPerks.Athletics.ImposingStature.Name);
			}
			float persuasionBonusChance = Campaign.Current.Models.DifficultyModel.GetPersuasionBonusChance();
			if (persuasionBonusChance > 0f)
			{
				explainedNumber.AddFactor(persuasionBonusChance, GameTexts.FindText("str_game_difficulty"));
			}
			return explainedNumber.ResultNumber;
		}

		public override void GetEffectChances(PersuasionOptionArgs option, out float moveToNextStageChance, out float blockRandomOptionChance, float difficultyMultiplier)
		{
			moveToNextStageChance = 0f;
			blockRandomOptionChance = 0f;
			if (option.CanMoveToTheNextReservation || option.CanBlockOtherOption)
			{
				moveToNextStageChance = (option.CanMoveToTheNextReservation ? 1f : 0f);
				blockRandomOptionChance = (option.CanBlockOtherOption ? 1f : 0f);
			}
		}

		public override PersuasionArgumentStrength GetArgumentStrengthBasedOnTargetTraits(CharacterObject character, Tuple<TraitObject, int>[] traitCorrelations)
		{
			float num = 0f;
			float num2 = 1f;
			for (int i = 0; i < traitCorrelations.Length; i++)
			{
				num2 += (float)(character.GetTraitLevel(traitCorrelations[i].Item1) * traitCorrelations[i].Item2);
				num += (float)TaleWorlds.Library.MathF.Abs(traitCorrelations[i].Item2);
				num2 += (float)(CharacterObject.PlayerCharacter.GetTraitLevel(traitCorrelations[i].Item1) * traitCorrelations[i].Item2);
				num += (float)TaleWorlds.Library.MathF.Abs(traitCorrelations[i].Item2);
			}
			if (num2 > num / 6f)
			{
				return PersuasionArgumentStrength.VeryEasy;
			}
			if (num2 > 0f)
			{
				return PersuasionArgumentStrength.ExtremelyEasy;
			}
			if (num2 < num / -6f)
			{
				return PersuasionArgumentStrength.VeryHard;
			}
			if (num2 < 0f)
			{
				return PersuasionArgumentStrength.Hard;
			}
			return PersuasionArgumentStrength.Normal;
		}

		public override float CalculateInitialPersuasionProgress(CharacterObject character, float goalValue, float successValue)
		{
			if (!character.IsHero)
			{
				return 0f;
			}
			return TaleWorlds.Library.MathF.Max(0f, character.HeroObject.GetRelationWithPlayer() * successValue) / (float)Campaign.Current.Models.DiplomacyModel.MaxRelationLimit;
		}

		public override float CalculatePersuasionGoalValue(CharacterObject oneToOneConversationCharacter, float successValue)
		{
			ExplainedNumber explainedNumber = new ExplainedNumber(successValue);
			if (CharacterObject.OneToOneConversationCharacter != null && CharacterObject.OneToOneConversationCharacter.IsHero)
			{
				if (CharacterObject.OneToOneConversationCharacter.HeroObject.Culture == Hero.MainHero.Culture && Hero.MainHero.GetPerkValue(DefaultPerks.Charm.MoralLeader))
				{
					explainedNumber.Add(DefaultPerks.Charm.MoralLeader.PrimaryBonus, DefaultPerks.Charm.MoralLeader.Name);
				}
				else if (CharacterObject.OneToOneConversationCharacter.HeroObject.Culture != Hero.MainHero.Culture && Hero.MainHero.GetPerkValue(DefaultPerks.Charm.NaturalLeader))
				{
					explainedNumber.Add(DefaultPerks.Charm.NaturalLeader.PrimaryBonus, DefaultPerks.Charm.NaturalLeader.Name);
				}
			}
			explainedNumber.LimitMin(1f);
			return explainedNumber.ResultNumber;
		}

		public override float GetDifficulty(PersuasionDifficulty difficulty)
		{
			return difficulty switch
			{
				PersuasionDifficulty.VeryEasy => 0.9f, 
				PersuasionDifficulty.Easy => 0.8f, 
				PersuasionDifficulty.EasyMedium => 0.7f, 
				PersuasionDifficulty.Medium => 0.6f, 
				PersuasionDifficulty.MediumHard => 0.5f, 
				PersuasionDifficulty.Hard => 0.4f, 
				PersuasionDifficulty.VeryHard => 0.3f, 
				PersuasionDifficulty.UltraHard => 0.2f, 
				PersuasionDifficulty.Impossible => 0.1f, 
				_ => 1f, 
			};
		}
	}
	public class DefaultPlayerProgressionModel : PlayerProgressionModel
	{
		public override float GetPlayerProgress()
		{
			return MBMath.ClampFloat((float)Clan.PlayerClan.Fiefs.Count * 0.1f + Clan.PlayerClan.CurrentTotalStrength * 0.0008f + Clan.PlayerClan.Renown * 1.5E-05f + (float)Clan.PlayerClan.AliveLords.Count * 0.002f + (float)Clan.PlayerClan.Companions.Count * 0.01f + (float)Clan.PlayerClan.SupporterNotables.Count * 0.001f + (float)Hero.MainHero.OwnedCaravans.Count * 0.01f + (float)PartyBase.MainParty.NumberOfAllMembers * 0.002f + (float)CharacterObject.PlayerCharacter.Level * 0.002f, 0f, 1f);
		}
	}
	public class DefaultPregnancyModel : PregnancyModel
	{
		private const int MinPregnancyAge = 18;

		private const int MaxPregnancyAge = 45;

		public override float PregnancyDurationInDays => (Campaign.Current.Options.AccelerationMode == GameAccelerationMode.Fast) ? 18 : 36;

		public override float MaternalMortalityProbabilityInLabor => 0.015f;

		public override float StillbirthProbability => 0.01f;

		public override float DeliveringFemaleOffspringProbability => 0.51f;

		public override float DeliveringTwinsProbability => 0.03f;

		private bool IsHeroAgeSuitableForPregnancy(Hero hero)
		{
			if (hero.Age >= 18f)
			{
				return hero.Age <= 45f;
			}
			return false;
		}

		public override float GetDailyChanceOfPregnancyForHero(Hero hero)
		{
			int num = hero.Children.Count + 1;
			float num2 = 4 + 4 * hero.Clan.Tier;
			int count = hero.Clan.AliveLords.Count;
			float num3 = ((hero != Hero.MainHero && hero.Spouse != Hero.MainHero) ? Math.Min(1f, (2f * num2 - (float)count) / num2) : 1f);
			float num4 = (1.2f - (hero.Age - 18f) * 0.04f) / (float)(num * num) * 0.12f * num3;
			float baseNumber = ((hero.Spouse != null && IsHeroAgeSuitableForPregnancy(hero)) ? num4 : 0f);
			ExplainedNumber explainedNumber = new ExplainedNumber(baseNumber);
			if (hero.GetPerkValue(DefaultPerks.Charm.Virile) || hero.Spouse.GetPerkValue(DefaultPerks.Charm.Virile))
			{
				explainedNumber.AddFactor(DefaultPerks.Charm.Virile.PrimaryBonus, DefaultPerks.Charm.Virile.Name);
			}
			return explainedNumber.ResultNumber;
		}
	}
	public class DefaultPrisonBreakModel : PrisonBreakModel
	{
		private const int BasePrisonBreakCost = 1000;

		public override int GetNumberOfGuardsToSpawn(Settlement settlement)
		{
			int num = (int)Math.Ceiling(2f + settlement.Town.Security / 30f);
			int num2 = settlement.Town.GetWallLevel() - 1;
			return num + num2;
		}

		public override bool CanPlayerStagePrisonBreak(Settlement settlement)
		{
			bool result = false;
			if (settlement.IsFortification)
			{
				MobileParty garrisonParty = settlement.Town.GarrisonParty;
				bool flag = (garrisonParty != null && garrisonParty.PrisonRoster.TotalHeroes > 0) || settlement.Party.PrisonRoster.TotalHeroes > 0;
				result = settlement.MapFaction != Clan.PlayerClan.MapFaction && !DiplomacyHelper.IsSameFactionAndNotEliminated(settlement.MapFaction, Clan.PlayerClan.MapFaction) && flag;
			}
			return result;
		}

		public override int GetPrisonBreakStartCost(Hero prisonerHero)
		{
			int num = TaleWorlds.Library.MathF.Ceiling((float)Campaign.Current.Models.RansomValueCalculationModel.PrisonerRansomValue(prisonerHero.CharacterObject) / 2000f * prisonerHero.CurrentSettlement.Town.Security * 40f - (float)(Hero.MainHero.GetSkillValue(DefaultSkills.Roguery) * 10));
			num = ((num >= 100) ? (num / 100 * 100) : 0);
			return num + 1000;
		}

		public override int GetRelationRewardOnPrisonBreak(Hero prisonerHero)
		{
			return 15;
		}

		public override float GetRogueryRewardOnPrisonBreak(Hero prisonerHero, bool isSuccess)
		{
			return isSuccess ? MBRandom.RandomInt(2000, 4500) : MBRandom.RandomInt(500, 1000);
		}
	}
	public class DefaultPrisonerDonationModel : PrisonerDonationModel
	{
		public override float CalculateRelationGainAfterHeroPrisonerDonate(PartyBase donatingParty, Hero donatedHero, Settlement donatedSettlement)
		{
			float result = 0f;
			int num = Campaign.Current.Models.RansomValueCalculationModel.PrisonerRansomValue(donatedHero.CharacterObject, donatingParty.LeaderHero);
			int relation = donatedHero.GetRelation(donatedSettlement.OwnerClan.Leader);
			if (relation <= 0)
			{
				float num2 = 1f - (float)relation / 200f;
				result = (donatedHero.IsKingdomLeader ? (TaleWorlds.Library.MathF.Min(40f, TaleWorlds.Library.MathF.Pow(num, 0.5f) * 0.5f) * num2) : ((donatedHero.Clan.Leader != donatedHero) ? (TaleWorlds.Library.MathF.Min(20f, TaleWorlds.Library.MathF.Pow(num, 0.5f) * 0.1f) * num2) : (TaleWorlds.Library.MathF.Min(30f, TaleWorlds.Library.MathF.Pow(num, 0.5f) * 0.25f) * num2)));
			}
			return result;
		}

		public override float CalculateInfluenceGainAfterPrisonerDonation(PartyBase donatingParty, CharacterObject donatedPrisoner, Settlement donatedSettlement)
		{
			return TaleWorlds.Library.MathF.Pow(Campaign.Current.Models.RansomValueCalculationModel.PrisonerRansomValue(donatedPrisoner, donatingParty.LeaderHero), 0.4f) * 0.2f;
		}

		public override float CalculateInfluenceGainAfterTroopDonation(PartyBase donatingParty, CharacterObject donatedCharacter, Settlement donatedSettlement)
		{
			Hero leaderHero = donatingParty.LeaderHero;
			ExplainedNumber stat = new ExplainedNumber(donatedCharacter.GetPower() / 3f);
			if (leaderHero != null && leaderHero.GetPerkValue(DefaultPerks.Steward.Relocation))
			{
				PerkHelper.AddPerkBonusForParty(DefaultPerks.Steward.Relocation, donatingParty.MobileParty, isPrimaryBonus: true, ref stat);
			}
			return stat.ResultNumber;
		}
	}
	public class DefaultPrisonerRecruitmentCalculationModel : PrisonerRecruitmentCalculationModel
	{
		private const int AILordMinTierRequirementForRecruitPrisoners = 2;

		public override int GetConformityNeededToRecruitPrisoner(CharacterObject character)
		{
			return (character.Level + 6) * (character.Level + 6) - 10;
		}

		public override ExplainedNumber GetConformityChangePerHour(PartyBase party, CharacterObject troopToBoost)
		{
			ExplainedNumber stat = new ExplainedNumber(10f);
			if (party.LeaderHero != null)
			{
				stat.Add((float)party.LeaderHero.GetSkillValue(DefaultSkills.Leadership) * 0.05f);
			}
			if (troopToBoost.Tier <= 3 && party.MobileParty != null && !party.MobileParty.IsCurrentlyAtSea)
			{
				PerkHelper.AddPerkBonusForParty(DefaultPerks.Leadership.FerventAttacker, party.MobileParty, isPrimaryBonus: false, ref stat);
			}
			if (troopToBoost.Tier >= 4 && !party.MobileParty.IsCurrentlyAtSea && party.MobileParty.HasPerk(DefaultPerks.Leadership.StoutDefender, checkSecondaryRole: true))
			{
				stat.AddFactor(DefaultPerks.Leadership.StoutDefender.SecondaryBonus);
			}
			if (troopToBoost.Occupation != Occupation.Bandit && !party.MobileParty.IsCurrentlyAtSea && party.MobileParty.HasPerk(DefaultPerks.Leadership.LoyaltyAndHonor, checkSecondaryRole: true))
			{
				stat.AddFactor(DefaultPerks.Leadership.LoyaltyAndHonor.SecondaryBonus);
			}
			if (troopToBoost.IsInfantry)
			{
				PerkHelper.AddPerkBonusForParty(DefaultPerks.Leadership.LeadByExample, party.MobileParty, isPrimaryBonus: true, ref stat, party.MobileParty.IsCurrentlyAtSea);
			}
			if (troopToBoost.IsRanged)
			{
				PerkHelper.AddPerkBonusForParty(DefaultPerks.Leadership.TrustedCommander, party.MobileParty, isPrimaryBonus: true, ref stat, party.MobileParty.IsCurrentlyAtSea);
			}
			if (troopToBoost.Occupation == Occupation.Bandit && !party.MobileParty.IsCurrentlyAtSea && party.MobileParty.HasPerk(DefaultPerks.Roguery.Promises, checkSecondaryRole: true))
			{
				stat.AddFactor(DefaultPerks.Roguery.Promises.SecondaryBonus);
			}
			return stat;
		}

		public override int GetPrisonerRecruitmentMoraleEffect(PartyBase party, CharacterObject character, int num)
		{
			if (character.Culture == party.LeaderHero?.Culture)
			{
				MobileParty mobileParty = party.MobileParty;
				if (mobileParty != null && mobileParty.HasPerk(DefaultPerks.Leadership.Presence, checkSecondaryRole: true))
				{
					goto IL_0058;
				}
			}
			if (character.Occupation == Occupation.Bandit)
			{
				MobileParty mobileParty2 = party.MobileParty;
				if (mobileParty2 != null && mobileParty2.HasPerk(DefaultPerks.Roguery.TwoFaced, checkSecondaryRole: true))
				{
					goto IL_0058;
				}
			}
			int num2 = ((character.Occupation != Occupation.Bandit) ? (-1) : (-2));
			return num2 * num;
			IL_0058:
			return 0;
		}

		public override bool IsPrisonerRecruitable(PartyBase party, CharacterObject character, out int conformityNeeded)
		{
			if (!character.IsRegular || character.Tier > Campaign.Current.Models.CharacterStatsModel.MaxCharacterTier || character.Tier < 2 || character.Culture.IsBandit)
			{
				conformityNeeded = 0;
				return false;
			}
			int elementXp = party.MobileParty.PrisonRoster.GetElementXp(character);
			conformityNeeded = GetConformityNeededToRecruitPrisoner(character);
			return elementXp >= conformityNeeded;
		}

		public override bool ShouldPartyRecruitPrisoners(PartyBase party)
		{
			if (party.IsMobile && party.PartySizeLimit > party.MobileParty.MemberRoster.TotalManCount && !party.MobileParty.IsWageLimitExceeded() && !party.MobileParty.IsPatrolParty)
			{
				if (!(party.MobileParty.Morale > 30f))
				{
					return party.MobileParty.HasPerk(DefaultPerks.Leadership.Presence, checkSecondaryRole: true);
				}
				return true;
			}
			return false;
		}

		public override int CalculateRecruitableNumber(PartyBase party, CharacterObject character)
		{
			if (character.IsHero || party.PrisonRoster.Count == 0 || party.PrisonRoster.TotalRegulars <= 0)
			{
				return 0;
			}
			int conformityNeededToRecruitPrisoner = Campaign.Current.Models.PrisonerRecruitmentCalculationModel.GetConformityNeededToRecruitPrisoner(character);
			int elementXp = party.PrisonRoster.GetElementXp(character);
			return TaleWorlds.Library.MathF.Min(b: party.PrisonRoster.GetElementNumber(character), a: elementXp / conformityNeededToRecruitPrisoner);
		}
	}
	public class DefaultRaidModel : RaidModel
	{
		private MBReadOnlyList<(ItemObject, float)> _commonLootItems;

		private MBReadOnlyList<(ItemObject, float)> CommonLootItemSpawnChances
		{
			get
			{
				if (_commonLootItems == null)
				{
					List<(ItemObject, float)> list = new List<(ItemObject, float)>
					{
						(DefaultItems.Hides, 1f),
						(DefaultItems.HardWood, 1f),
						(DefaultItems.Tools, 1f),
						(DefaultItems.Grain, 1f),
						(Campaign.Current.ObjectManager.GetObject<ItemObject>("linen"), 1f),
						(Campaign.Current.ObjectManager.GetObject<ItemObject>("sheep"), 1f),
						(Campaign.Current.ObjectManager.GetObject<ItemObject>("mule"), 1f),
						(Campaign.Current.ObjectManager.GetObject<ItemObject>("pottery"), 1f)
					};
					for (int num = list.Count - 1; num >= 0; num--)
					{
						ItemObject item = list[num].Item1;
						float item2 = 100f / ((float)item.Value + 1f);
						list[num] = (item, item2);
					}
					_commonLootItems = new MBReadOnlyList<(ItemObject, float)>(list);
				}
				return _commonLootItems;
			}
		}

		public override int GoldRewardForEachLostHearth => 4;

		public override ExplainedNumber CalculateHitDamage(MapEventSide attackerSide, float settlementHitPoints)
		{
			float num = (TaleWorlds.Library.MathF.Sqrt(attackerSide.TroopCount) + 5f) / 900f;
			ExplainedNumber result = new ExplainedNumber(num * (float)CampaignTime.DeltaTime.ToHours);
			foreach (MapEventParty party in attackerSide.Parties)
			{
				if (party.Party.MobileParty?.LeaderHero != null && party.Party.MobileParty.LeaderHero.GetPerkValue(DefaultPerks.Roguery.NoRestForTheWicked))
				{
					result.AddFactor(DefaultPerks.Roguery.NoRestForTheWicked.SecondaryBonus);
				}
			}
			return result;
		}

		public override ExplainedNumber GetRaidLootMultiplier(PartyBase receivingParty)
		{
			return new ExplainedNumber(1f);
		}

		public override MBReadOnlyList<(ItemObject, float)> GetCommonLootItemScores()
		{
			return CommonLootItemSpawnChances;
		}
	}
	public class DefaultRansomValueCalculationModel : RansomValueCalculationModel
	{
		public override int PrisonerRansomValue(CharacterObject prisoner, Hero sellerHero = null)
		{
			int roundedResultNumber = Campaign.Current.Models.PartyWageModel.GetTroopRecruitmentCost(prisoner, null).RoundedResultNumber;
			float num = 0f;
			float num2 = 0f;
			float num3 = 1f;
			if (prisoner.HeroObject?.Clan != null)
			{
				num = (float)(prisoner.HeroObject.Clan.Tier + 2) * 200f * ((!prisoner.HeroObject.IsClanLeader) ? 1f : (prisoner.HeroObject.IsKingdomLeader ? 6f : 2.5f));
				num2 = TaleWorlds.Library.MathF.Sqrt(TaleWorlds.Library.MathF.Max(0, prisoner.HeroObject.Gold)) * 6f;
				if (prisoner.HeroObject.Clan.Kingdom != null)
				{
					int count = prisoner.HeroObject.Clan.Kingdom.Fiefs.Count;
					num3 = ((!prisoner.HeroObject.MapFaction.IsKingdomFaction) ? 1f : ((count < 8) ? (((float)count + 1f) / 9f) : (1f + TaleWorlds.Library.MathF.Sqrt(count - 8) * 0.1f)));
				}
				else
				{
					num3 = 0.5f;
				}
			}
			float num4 = ((prisoner.HeroObject != null) ? (num + num2) : 0f);
			int num5 = (int)(((float)roundedResultNumber + num4) * ((!prisoner.IsHero) ? 0.25f : 1f) * num3);
			if (sellerHero != null)
			{
				if (!prisoner.IsHero)
				{
					if (sellerHero.GetPerkValue(DefaultPerks.Roguery.Manhunter) && sellerHero.PartyBelongedTo != null && !sellerHero.PartyBelongedTo.IsCurrentlyAtSea)
					{
						num5 = TaleWorlds.Library.MathF.Round((float)num5 + (float)num5 * DefaultPerks.Roguery.Manhunter.PrimaryBonus);
					}
				}
				else if (sellerHero.IsPartyLeader && sellerHero.GetPerkValue(DefaultPerks.Roguery.RansomBroker))
				{
					float num6 = DefaultPerks.Roguery.RansomBroker.PrimaryBonus;
					if (sellerHero.PartyBelongedTo.IsCurrentlyAtSea)
					{
						num6 *= 0.5f;
					}
					num5 = TaleWorlds.Library.MathF.Round((float)num5 + (float)num5 * num6);
				}
			}
			if (num5 != 0)
			{
				return num5;
			}
			return 1;
		}
	}
