			disabledText = null;
			if (settlement.Town.HasTournament)
			{
				return Campaign.Current.IsDay;
			}
			return false;
		}

		private bool CanMainHeroTrade(Settlement settlement, out bool disableOption, out TextObject disabledText)
		{
			if (settlement.IsVillage)
			{
				Village village = Settlement.CurrentSettlement.Village;
				if (village.VillageState == Village.VillageStates.BeingRaided)
				{
					disabledText = null;
					disableOption = false;
					return false;
				}
				bool flag = settlement.MapFaction.IsAtWarWith(Hero.MainHero.MapFaction);
				TextObject textObject = new TextObject("{=vYHVlydb}You cannot trade with a hostile village.");
				if (village.VillageState == Village.VillageStates.Normal && village.Owner.ItemRoster.Count > 0)
				{
					disableOption = flag;
					disabledText = (disableOption ? textObject : null);
					return !disableOption;
				}
				if (village.Gold > 0)
				{
					disableOption = flag;
					disabledText = (disableOption ? textObject : new TextObject("{=FbowXAC0}There are no available products right now."));
					return false;
				}
				disableOption = flag;
				disabledText = (disableOption ? textObject : new TextObject("{=bmfo7CaO}Village shop is not available right now."));
				return false;
			}
			if (Campaign.Current.IsMainHeroDisguised && !Hero.MainHero.GetPerkValue(DefaultPerks.Roguery.SmugglerConnections))
			{
				disableOption = true;
				TextObject textObject2 = new TextObject("{=HVUHHuVA}{PERK_NAME} perk required to trade while in disguise.");
				textObject2.SetTextVariable("PERK_NAME", DefaultPerks.Roguery.SmugglerConnections.Name);
				disabledText = textObject2;
				return false;
			}
			disableOption = false;
			disabledText = null;
			return true;
		}

		private bool CanMainHeroWaitInSettlement(Settlement settlement, out bool disableOption, out TextObject disabledText)
		{
			disableOption = false;
			disabledText = null;
			if (Campaign.Current.IsMainHeroDisguised)
			{
				disableOption = true;
				disabledText = new TextObject("{=dN5Qc9vN}You cannot wait in town while in disguise.");
				return false;
			}
			if (settlement.IsVillage)
			{
				if (settlement.Party.MapEvent != null)
				{
					disableOption = true;
					disabledText = new TextObject("{=dN5Qc7vN}You cannot wait in village while it is being raided.");
					return false;
				}
				if (settlement.MapFaction.IsAtWarWith(Hero.MainHero.MapFaction))
				{
					disableOption = true;
					disabledText = new TextObject("{=s7aas7L4}You cannot wait in a hostile village.");
					return false;
				}
			}
			if (MobileParty.MainParty.Army != null && MobileParty.MainParty.Army.LeaderParty != MobileParty.MainParty)
			{
				disableOption = true;
				disabledText = new TextObject("{=tjsld7WT}You cannot wait in town while you're a member of an army.");
				return false;
			}
			return true;
		}
	}
	public class DefaultSettlementEconomyModel : SettlementEconomyModel
	{
		private class CategoryValues
		{
			public Dictionary<ItemCategory, int> PriceDict;

			public CategoryValues()
			{
				PriceDict = new Dictionary<ItemCategory, int>();
				foreach (ItemObject item in Items.All)
				{
					PriceDict[item.GetItemCategory()] = item.Value;
				}
			}

			public int GetValueOfCategory(ItemCategory category)
			{
				int value = 1;
				PriceDict.TryGetValue(category, out value);
				return value;
			}
		}

		private CategoryValues _categoryValues;

		private const int ProsperityLuxuryTreshold = 3000;

		private const float dailyChangeFactor = 0.15f;

		private const float oneMinusDailyChangeFactor = 0.85f;

		private CategoryValues CategoryValuesCache
		{
			get
			{
				if (_categoryValues == null)
				{
					_categoryValues = new CategoryValues();
				}
				return _categoryValues;
			}
		}

		public override (float, float) GetSupplyDemandForCategory(Town town, ItemCategory category, float dailySupply, float dailyDemand, float oldSupply, float oldDemand)
		{
			float b = oldSupply * 0.85f + dailySupply * 0.15f;
			float item = oldDemand * 0.85f + dailyDemand * 0.15f;
			b = TaleWorlds.Library.MathF.Max(0.1f, b);
			return (b, item);
		}

		public override float GetDailyDemandForCategory(Town town, ItemCategory category, int extraProsperity)
		{
			float num = TaleWorlds.Library.MathF.Max(0f, town.Prosperity + (float)extraProsperity);
			float num2 = TaleWorlds.Library.MathF.Max(0f, town.Prosperity - 3000f);
			float num3 = category.BaseDemand * num;
			float num4 = category.LuxuryDemand * num2;
			float result = num3 + num4;
			if (category.BaseDemand < 1E-08f)
			{
				result = num * 0.01f;
			}
			return result;
		}

		public override int GetTownGoldChange(Town town)
		{
			float num = 10000f + town.Prosperity * 12f - (float)town.Gold;
			return TaleWorlds.Library.MathF.Round(0.25f * num);
		}

		public override float CalculateDailySettlementBudgetForItemCategory(Town town, float demand, ItemCategory category)
		{
			return demand * TaleWorlds.Library.MathF.Pow(town.GetItemCategoryPriceIndex(category), 0.3f);
		}

		public override float GetDemandChangeFromValue(float purchaseValue)
		{
			return purchaseValue * 0.15f;
		}

		public override float GetEstimatedDemandForCategory(Town town, ItemData itemData, ItemCategory category)
		{
			return Campaign.Current.Models.SettlementEconomyModel.GetDailyDemandForCategory(town, category, 1000);
		}
	}
	public class DefaultSettlementFoodModel : SettlementFoodModel
	{
		private readonly TextObject ProsperityText = GameTexts.FindText("str_prosperity");

		private readonly TextObject GarrisonText = GameTexts.FindText("str_garrison");

		private readonly TextObject LandsAroundSettlementText = GameTexts.FindText("str_lands_around_settlement");

		private readonly TextObject NormalVillagesText = GameTexts.FindText("str_normal_villages");

		private readonly TextObject RaidedVillagesText = GameTexts.FindText("str_raided_villages");

		private readonly TextObject VillagesUnderSiegeText = GameTexts.FindText("str_villages_under_siege");

		private readonly TextObject FoodBoughtByCiviliansText = GameTexts.FindText("str_food_bought_by_civilians");

		private const int FoodProductionPerVillage = 10;

		public override int FoodStocksUpperLimit => 300;

		public override int NumberOfProsperityToEatOneFood => 40;

		public override int NumberOfMenOnGarrisonToEatOneFood => 20;

		public override int CastleFoodStockUpperLimitBonus => 150;

		public override ExplainedNumber CalculateTownFoodStocksChange(Town town, bool includeMarketStocks = true, bool includeDescriptions = false)
		{
			return CalculateTownFoodChangeInternal(town, includeMarketStocks, includeDescriptions);
		}

		private ExplainedNumber CalculateTownFoodChangeInternal(Town town, bool includeMarketStocks, bool includeDescriptions)
		{
			ExplainedNumber bonuses = new ExplainedNumber(0f, includeDescriptions);
			ExplainedNumber bonuses2 = new ExplainedNumber(0f, includeDescriptions);
			ExplainedNumber bonuses3 = new ExplainedNumber(town.Prosperity / (float)NumberOfProsperityToEatOneFood);
			ExplainedNumber bonuses4 = new ExplainedNumber((((float?)town.GarrisonParty?.Party.NumberOfAllMembers) ?? 0f) / (float)NumberOfMenOnGarrisonToEatOneFood);
			if (town.IsUnderSiege)
			{
				PerkHelper.AddPerkBonusForTown(DefaultPerks.Steward.Gourmet, town, ref bonuses4);
				PerkHelper.AddPerkBonusForTown(DefaultPerks.Medicine.TriageTent, town, ref bonuses2);
			}
			PerkHelper.AddPerkBonusForTown(DefaultPerks.Steward.MasterOfWarcraft, town, ref bonuses3);
			bonuses2.Add(bonuses3.ResultNumber, ProsperityText);
			bonuses2.Add(bonuses4.ResultNumber, GarrisonText);
			town.AddEffectOfBuildings(BuildingEffectEnum.FoodConsumption, ref bonuses2);
			Kingdom kingdom = town.Settlement.OwnerClan?.Kingdom;
			if (kingdom != null && kingdom.HasPolicy(DefaultPolicies.HuntingRights))
			{
				bonuses.Add(2f, DefaultPolicies.HuntingRights.Name);
			}
			if (!town.IsUnderSiege)
			{
				int num = (town.IsTown ? 15 : 10);
				bonuses.Add(num, LandsAroundSettlementText);
				foreach (Village boundVillage in town.Owner.Settlement.BoundVillages)
				{
					float value = 0f;
					if (boundVillage.VillageState == Village.VillageStates.Normal)
					{
						value = (boundVillage.GetHearthLevel() + 1) * 6;
					}
					bonuses.Add(value, boundVillage.Name);
				}
				town.AddEffectOfBuildings(BuildingEffectEnum.FoodProduction, ref bonuses);
			}
			else
			{
				PerkHelper.AddPerkBonusForTown(DefaultPerks.Roguery.DirtyFighting, town, ref bonuses);
			}
			if (includeMarketStocks)
			{
				foreach (Town.SellLog soldItem in town.SoldItems)
				{
					if (soldItem.Category.Properties == ItemCategory.Property.BonusToFoodStores)
					{
						bonuses.Add(soldItem.Number, includeDescriptions ? soldItem.Category.GetName() : null);
					}
				}
			}
			ExplainedNumber explainedNumber = new ExplainedNumber(0f, includeDescriptions);
			explainedNumber.AddFromExplainedNumber(bonuses, null);
			explainedNumber.SubtractFromExplainedNumber(bonuses2, null);
			GetSettlementFoodChangeDueToIssues(town, ref explainedNumber);
			return explainedNumber;
		}

		private static void GetSettlementFoodChangeDueToIssues(Town town, ref ExplainedNumber explainedNumber)
		{
			Campaign.Current.Models.IssueModel.GetIssueEffectsOfSettlement(DefaultIssueEffects.SettlementFood, town.Settlement, ref explainedNumber);
		}
	}
	public class DefaultSettlementGarrisonModel : SettlementGarrisonModel
