		private static readonly TextObject TownWallsText = new TextObject("{=SlmhqqH8}Town Walls");

		private static readonly TextObject MoraleText = new TextObject("{=UjL7jVYF}Morale");

		private static readonly TextObject FoodShortageText = new TextObject("{=qTFKvGSg}Food Shortage");

		private readonly TextObject SurplusFoodText = GameTexts.FindText("str_surplus_food");

		private readonly TextObject VillageBeingRaided = GameTexts.FindText("str_village_being_raided");

		private readonly TextObject VillageLooted = GameTexts.FindText("str_village_looted");

		private readonly TextObject TownIsUnderSiege = GameTexts.FindText("str_villages_under_siege");

		private readonly TextObject RetiredText = GameTexts.FindText("str_retired");

		private readonly TextObject PaymentIsLessText = GameTexts.FindText("str_payment_is_less");

		private readonly TextObject UnpaidWagesText = GameTexts.FindText("str_unpaid_wages");

		private readonly TextObject RebellionText = GameTexts.FindText("str_rebel_settlement");

		private const int MaximumDailyAutoRecruitmentCount = 1;

		public override int GetMaximumDailyAutoRecruitmentCount(Town town)
		{
			return 1;
		}

		public override ExplainedNumber CalculateBaseGarrisonChange(Settlement settlement, bool includeDescriptions = false)
		{
			ExplainedNumber explainedNumber = new ExplainedNumber(0f, includeDescriptions);
			if ((settlement.IsTown || settlement.IsCastle) && settlement.OwnerClan.IsRebelClan && (settlement.OwnerClan.MapFaction == null || !settlement.OwnerClan.MapFaction.IsKingdomFaction))
			{
				explainedNumber.Add(2f, RebellionText);
			}
			Campaign.Current.Models.IssueModel.GetIssueEffectsOfSettlement(DefaultIssueEffects.SettlementGarrison, settlement, ref explainedNumber);
			return explainedNumber;
		}

		public override int FindNumberOfTroopsToTakeFromGarrison(MobileParty mobileParty, Settlement settlement, float defaultIdealGarrisonStrengthPerWalledCenter = 0f)
		{
			MobileParty garrisonParty = settlement.Town.GarrisonParty;
			float num = 0f;
			if (garrisonParty != null)
			{
				num = garrisonParty.Party.CalculateCurrentStrength();
				float num2 = 100f;
				if (garrisonParty.HasLimitedWage())
				{
					num2 = (float)garrisonParty.PaymentLimit / Campaign.Current.AverageWage;
					num2 /= 1.5f;
				}
				else
				{
					num2 = ((defaultIdealGarrisonStrengthPerWalledCenter > 0.1f) ? defaultIdealGarrisonStrengthPerWalledCenter : FactionHelper.FindIdealGarrisonStrengthPerWalledCenter(mobileParty.MapFaction as Kingdom, settlement.OwnerClan));
					float num3 = FactionHelper.OwnerClanEconomyEffectOnGarrisonSizeConstant(settlement.OwnerClan);
					num2 *= num3;
					num2 *= (settlement.IsTown ? 2f : 1f);
				}
				int partySizeLimit = mobileParty.Party.PartySizeLimit;
				int numberOfAllMembers = mobileParty.Party.NumberOfAllMembers;
				float num4 = (float)partySizeLimit / (float)numberOfAllMembers;
				float num5 = TaleWorlds.Library.MathF.Min(11f, num4 * TaleWorlds.Library.MathF.Sqrt(num4)) - 1f;
				float num6 = TaleWorlds.Library.MathF.Pow(num / num2, 1.5f);
				float num7 = ((mobileParty.LeaderHero.Clan.Leader == mobileParty.LeaderHero) ? 2f : 1f);
				int num8 = 0;
				if (num5 * num6 * num7 > 1f)
				{
					num8 = MBRandom.RoundRandomized(num5 * num6 * num7);
				}
				int num9 = 25;
				num9 *= ((!settlement.IsTown) ? 1 : 2);
				if (num8 > garrisonParty.Party.MemberRoster.TotalRegulars - num9)
				{
					num8 = garrisonParty.Party.MemberRoster.TotalRegulars - num9;
				}
				return num8;
			}
			return 0;
		}

		public override int FindNumberOfTroopsToLeaveToGarrison(MobileParty mobileParty, Settlement settlement)
		{
			MobileParty garrisonParty = settlement.Town.GarrisonParty;
			float num = 0f;
			if (garrisonParty != null)
			{
				num = garrisonParty.Party.CalculateCurrentStrength();
			}
			float num2 = 100f;
			if (garrisonParty != null && garrisonParty.HasLimitedWage())
			{
				num2 = (float)garrisonParty.PaymentLimit / Campaign.Current.AverageWage;
			}
			else
			{
				num2 = FactionHelper.FindIdealGarrisonStrengthPerWalledCenter(mobileParty.MapFaction as Kingdom, settlement.OwnerClan);
				float num3 = FactionHelper.OwnerClanEconomyEffectOnGarrisonSizeConstant(settlement.OwnerClan);
				float num4 = FactionHelper.SettlementProsperityEffectOnGarrisonSizeConstant(settlement.Town);
				float num5 = FactionHelper.SettlementFoodPotentialEffectOnGarrisonSizeConstant(settlement);
				num2 *= num3;
				num2 *= num4;
				num2 *= num5;
			}
			if (num < num2)
			{
				int numberOfRegularMembers = mobileParty.Party.NumberOfRegularMembers;
				float num6 = 1f + (float)mobileParty.Party.MemberRoster.TotalWoundedRegulars / (float)mobileParty.Party.NumberOfRegularMembers;
				int partySizeLimit = mobileParty.Party.PartySizeLimit;
				float num7 = TaleWorlds.Library.MathF.Pow(TaleWorlds.Library.MathF.Min(2f, (float)numberOfRegularMembers / (float)partySizeLimit), 1.2f) * 0.75f;
				float num8 = (1f - num / num2) * (1f - num / num2);
				float num9 = 1f;
				if (mobileParty.Army != null)
				{
					num8 = TaleWorlds.Library.MathF.Min(num8, 0.7f);
					num9 = 0.3f + mobileParty.Army.CalculateCurrentStrength() / mobileParty.Party.CalculateCurrentStrength() * 0.025f;
				}
				float num10 = (settlement.Town.IsOwnerUnassigned ? 0.75f : 0.5f);
				if (settlement.OwnerClan == mobileParty.LeaderHero.Clan || settlement.OwnerClan == mobileParty.Party.Owner.MapFaction.Leader.Clan)
				{
					num10 = 1f;
				}
				float num11 = TaleWorlds.Library.MathF.Min(0.7f, num7 * num8 * num10 * num6 * num9);
				if ((float)numberOfRegularMembers * num11 > 1f)
				{
					return MBRandom.RoundRandomized((float)numberOfRegularMembers * num11);
				}
			}
			return 0;
		}

		public override float GetMaximumDailyRepairAmount(Settlement settlement)
		{
			if (settlement.IsUnderSiege || settlement.SettlementWallSectionHitPointsRatioList.All((float ratio) => ratio >= 1f))
			{
				return 0f;
			}
			ExplainedNumber result = new ExplainedNumber(settlement.MaxHitPointsOfOneWallSection * (float)settlement.WallSectionCount * 0.04f);
			if (settlement.IsFortification)
			{
				settlement.Town.AddEffectOfBuildings(BuildingEffectEnum.WallRepairSpeed, ref result);
			}
			return result.ResultNumber;
		}
	}
	public class DefaultSettlementLoyaltyModel : SettlementLoyaltyModel
	{
		private const float StarvationLoyaltyEffect = -1f;

		private const int AdditionalStarvationLoyaltyEffectAfterDays = 14;

		private const float NotableSupportsOwnerLoyaltyEffect = 0.5f;

		private const float NotableSupportsEnemyLoyaltyEffect = -0.5f;

		private readonly TextObject StarvingText = GameTexts.FindText("str_starving");

		private static readonly TextObject CultureText = new TextObject("{=YjoXyFDX}Owner Culture");

		private static readonly TextObject GovernorCultureText = new TextObject("{=5Vo8dJub}Governor's Culture");

		private static readonly TextObject NoGovernorText = new TextObject("{=NH5N3kP5}No governor");

		private readonly TextObject NotableText = GameTexts.FindText("str_notable_relations");

		private readonly TextObject CrimeText = GameTexts.FindText("str_governor_criminal");

		private readonly TextObject GovernorText = GameTexts.FindText("str_notable_governor");

		private readonly TextObject SecurityText = GameTexts.FindText("str_security");

		private readonly TextObject LoyaltyText = GameTexts.FindText("str_loyalty");

		private readonly TextObject LoyaltyDriftText = GameTexts.FindText("str_loyalty_drift");

		private readonly TextObject CorruptionText = GameTexts.FindText("str_corruption");

		public override float HighLoyaltyProsperityEffect => 0.5f;

		public override int LowLoyaltyProsperityEffect => -1;

		public override int ThresholdForTaxBoost => 75;

		public override int ThresholdForTaxCorruption => 50;

		public override int ThresholdForHigherTaxCorruption => 25;

		public override int ThresholdForProsperityBoost => 75;

		public override int ThresholdForProsperityPenalty => 25;

		public override int AdditionalStarvationPenaltyStartDay => 14;

		public override int AdditionalStarvationLoyaltyEffect => -1;

		public override int RebellionStartLoyaltyThreshold => 15;

		public override int RebelliousStateStartLoyaltyThreshold => 25;

		public override int LoyaltyBoostAfterRebellionStartValue => 5;

		public override int MilitiaBoostPercentage => 200;

		public override float ThresholdForNotableRelationBonus => 75f;

		public override int DailyNotableRelationBonus => 1;

		public override int SettlementLoyaltyChangeDueToSecurityThreshold => 50;

		public override int MaximumLoyaltyInSettlement => 100;

		public override int LoyaltyDriftMedium => 50;

		public override float HighSecurityLoyaltyEffect => 1f;

		public override float LowSecurityLoyaltyEffect => -2f;

		public override float GovernorSameCultureLoyaltyEffect => 1f;

		public override float GovernorDifferentCultureLoyaltyEffect => -1f;

		public override float SettlementOwnerDifferentCultureLoyaltyEffect => -3f;

		public override ExplainedNumber CalculateLoyaltyChange(Town town, bool includeDescriptions = false)
		{
			return CalculateLoyaltyChangeInternal(town, includeDescriptions);
		}

		public override void CalculateGoldGainDueToHighLoyalty(Town town, ref ExplainedNumber explainedNumber)
		{
			float value = MBMath.Map(town.Loyalty, ThresholdForTaxBoost, 100f, 0f, 0.2f);
			explainedNumber.AddFactor(value, LoyaltyText);
		}

		public override void CalculateGoldCutDueToLowLoyalty(Town town, ref ExplainedNumber explainedNumber)
		{
			float value = MBMath.Map(town.Loyalty, ThresholdForHigherTaxCorruption, ThresholdForTaxCorruption, -0.5f, 0f);
			explainedNumber.AddFactor(value, CorruptionText);
		}

		private ExplainedNumber CalculateLoyaltyChangeInternal(Town town, bool includeDescriptions = false)
		{
			ExplainedNumber explainedNumber = new ExplainedNumber(0f, includeDescriptions);
			GetSettlementLoyaltyChangeDueToFoodStocks(town, ref explainedNumber);
			GetSettlementLoyaltyChangeDueToGovernorCulture(town, ref explainedNumber);
			GetSettlementLoyaltyChangeDueToOwnerCulture(town, ref explainedNumber);
			GetSettlementLoyaltyChangeDueToPolicies(town, ref explainedNumber);
			GetSettlementLoyaltyChangeDueToProjects(town, ref explainedNumber);
			GetSettlementLoyaltyChangeDueToIssues(town, ref explainedNumber);
			GetSettlementLoyaltyChangeDueToSecurity(town, ref explainedNumber);
			GetSettlementLoyaltyChangeDueToNotableRelations(town, ref explainedNumber);
			GetSettlementLoyaltyChangeDueToGovernorPerks(town, ref explainedNumber);
			GetSettlementLoyaltyChangeDueToLoyaltyDrift(town, ref explainedNumber);
			return explainedNumber;
		}

		private void GetSettlementLoyaltyChangeDueToGovernorPerks(Town town, ref ExplainedNumber explainedNumber)
		{
			PerkHelper.AddPerkBonusForTown(DefaultPerks.Leadership.HeroicLeader, town, ref explainedNumber);
			PerkHelper.AddPerkBonusForTown(DefaultPerks.Medicine.PhysicianOfPeople, town, ref explainedNumber);
			PerkHelper.AddPerkBonusForTown(DefaultPerks.Athletics.Durable, town, ref explainedNumber);
			PerkHelper.AddPerkBonusForTown(DefaultPerks.Bow.Discipline, town, ref explainedNumber);
			PerkHelper.AddPerkBonusForTown(DefaultPerks.Riding.WellStraped, town, ref explainedNumber);
			float num = 0f;
			for (int i = 0; i < town.Settlement.Parties.Count; i++)
			{
				MobileParty mobileParty = town.Settlement.Parties[i];
				if (mobileParty.ActualClan != town.OwnerClan)
				{
					continue;
				}
				if (mobileParty.IsMainParty)
				{
					for (int j = 0; j < mobileParty.MemberRoster.Count; j++)
					{
						CharacterObject characterAtIndex = mobileParty.MemberRoster.GetCharacterAtIndex(j);
						if (characterAtIndex.IsHero && characterAtIndex.HeroObject.GetPerkValue(DefaultPerks.Charm.Parade))
						{
							num += DefaultPerks.Charm.Parade.PrimaryBonus;
						}
					}
				}
				else if (mobileParty.LeaderHero != null && mobileParty.LeaderHero.GetPerkValue(DefaultPerks.Charm.Parade))
				{
					num += DefaultPerks.Charm.Parade.PrimaryBonus;
				}
			}
			foreach (Hero item in town.Settlement.HeroesWithoutParty)
			{
				if (item.Clan == town.OwnerClan && item.GetPerkValue(DefaultPerks.Charm.Parade))
				{
					num += DefaultPerks.Charm.Parade.PrimaryBonus;
				}
			}
			if (num > 0f)
			{
				explainedNumber.Add(num, DefaultPerks.Charm.Parade.Name);
			}
		}

		private void GetSettlementLoyaltyChangeDueToNotableRelations(Town town, ref ExplainedNumber explainedNumber)
		{
			float num = 0f;
			foreach (Hero notable in town.Settlement.Notables)
			{
				if (notable.SupporterOf != null)
				{
					if (notable.SupporterOf == town.Settlement.OwnerClan)
					{
						num += 0.5f;
					}
					else if (town.MapFaction.IsAtWarWith(notable.SupporterOf.MapFaction))
					{
						num += -0.5f;
					}
				}
			}
			if (!num.ApproximatelyEqualsTo(0f))
			{
				explainedNumber.Add(num, NotableText);
			}
		}

		private void GetSettlementLoyaltyChangeDueToOwnerCulture(Town town, ref ExplainedNumber explainedNumber)
		{
			if (town.Settlement.OwnerClan.Culture != town.Settlement.Culture)
			{
				explainedNumber.Add(SettlementOwnerDifferentCultureLoyaltyEffect, CultureText);
			}
		}

		private void GetSettlementLoyaltyChangeDueToPolicies(Town town, ref ExplainedNumber explainedNumber)
		{
			Kingdom kingdom = town.Owner.Settlement.OwnerClan.Kingdom;
			if (kingdom == null)
			{
				return;
			}
			if (kingdom.ActivePolicies.Contains(DefaultPolicies.Citizenship))
			{
				if (town.Settlement.OwnerClan.Culture == town.Settlement.Culture)
				{
					explainedNumber.Add(0.5f, DefaultPolicies.Citizenship.Name);
				}
				else
				{
					explainedNumber.Add(-0.5f, DefaultPolicies.Citizenship.Name);
				}
			}
			if (kingdom.ActivePolicies.Contains(DefaultPolicies.HuntingRights))
			{
				explainedNumber.Add(-0.2f, DefaultPolicies.HuntingRights.Name);
			}
			if (kingdom.ActivePolicies.Contains(DefaultPolicies.GrazingRights))
			{
				explainedNumber.Add(0.5f, DefaultPolicies.GrazingRights.Name);
			}
			if (kingdom.ActivePolicies.Contains(DefaultPolicies.TrialByJury))
			{
				explainedNumber.Add(0.5f, DefaultPolicies.TrialByJury.Name);
			}
			if (town.IsTown && kingdom.ActivePolicies.Contains(DefaultPolicies.ImperialTowns))
			{
				if (kingdom.RulingClan == town.Settlement.OwnerClan)
				{
					explainedNumber.Add(1f, DefaultPolicies.ImperialTowns.Name);
				}
				else
				{
					explainedNumber.Add(-0.3f, DefaultPolicies.ImperialTowns.Name);
				}
			}
			if (kingdom.ActivePolicies.Contains(DefaultPolicies.ForgivenessOfDebts))
			{
				explainedNumber.Add(2f, DefaultPolicies.ForgivenessOfDebts.Name);
			}
			if (kingdom.ActivePolicies.Contains(DefaultPolicies.TribunesOfThePeople) && town.IsTown)
			{
				explainedNumber.Add(1f, DefaultPolicies.TribunesOfThePeople.Name);
			}
			if (kingdom.ActivePolicies.Contains(DefaultPolicies.DebasementOfTheCurrency))
			{
				explainedNumber.Add(-1f, DefaultPolicies.DebasementOfTheCurrency.Name);
			}
		}

		private void GetSettlementLoyaltyChangeDueToGovernorCulture(Town town, ref ExplainedNumber explainedNumber)
		{
			if (town.Governor != null)
			{
				explainedNumber.Add((town.Governor.Culture == town.Culture) ? GovernorSameCultureLoyaltyEffect : GovernorDifferentCultureLoyaltyEffect, GovernorCultureText);
			}
		}

		private void GetSettlementLoyaltyChangeDueToFoodStocks(Town town, ref ExplainedNumber explainedNumber)
		{
			if (town.Settlement.IsStarving)
			{
				float num = -1f;
				if (town.Settlement.Party.DaysStarving > 14f)
				{
					num += -1f;
				}
				explainedNumber.Add(num, StarvingText);
			}
		}

		private void GetSettlementLoyaltyChangeDueToSecurity(Town town, ref ExplainedNumber explainedNumber)
		{
			float value = ((town.Security > (float)SettlementLoyaltyChangeDueToSecurityThreshold) ? MBMath.Map(town.Security, SettlementLoyaltyChangeDueToSecurityThreshold, MaximumLoyaltyInSettlement, 0f, HighSecurityLoyaltyEffect) : MBMath.Map(town.Security, 0f, SettlementLoyaltyChangeDueToSecurityThreshold, LowSecurityLoyaltyEffect, 0f));
			explainedNumber.Add(value, SecurityText);
		}

		private void GetSettlementLoyaltyChangeDueToProjects(Town town, ref ExplainedNumber explainedNumber)
		{
			town.AddEffectOfBuildings(BuildingEffectEnum.Loyalty, ref explainedNumber);
		}

		private void GetSettlementLoyaltyChangeDueToIssues(Town town, ref ExplainedNumber explainedNumber)
		{
			Campaign.Current.Models.IssueModel.GetIssueEffectsOfSettlement(DefaultIssueEffects.SettlementLoyalty, town.Settlement, ref explainedNumber);
		}

		private void GetSettlementLoyaltyChangeDueToLoyaltyDrift(Town town, ref ExplainedNumber explainedNumber)
		{
			explainedNumber.Add(-0.1f * (town.Loyalty - (float)LoyaltyDriftMedium), LoyaltyDriftText);
		}
	}
	public class DefaultSettlementMilitiaModel : SettlementMilitiaModel
	{
		private static readonly TextObject BaseText = new TextObject("{=militarybase}Base");

		private static readonly TextObject FromHearthsText = new TextObject("{=ecdZglky}From Hearths");

		private static readonly TextObject FromProsperityText = new TextObject("{=cTmiNAlI}From Prosperity");

		private static readonly TextObject RetiredText = new TextObject("{=gHnfFi1s}Retired");

		private static readonly TextObject MilitiaFromMarketText = new TextObject("{=7ve3bQxg}Weapons From Market");

		private static readonly TextObject LowLoyaltyText = new TextObject("{=SJ2qsRdF}Low Loyalty");

		private static readonly TextObject CultureText = GameTexts.FindText("str_culture");

		private const int AutoSpawnMilitiaDayMultiplierAfterSiege = 25;

		private const int BaseFortificationMilitiaChange = 2;

		private const float BaseVillageMilitiaChange = 0.5f;

		public override int MilitiaToSpawnAfterSiege(Town town)
		{
			return 2 * (45 + MBRandom.RandomInt(10));
		}

		public override ExplainedNumber CalculateMilitiaChange(Settlement settlement, bool includeDescriptions = false)
		{
			return CalculateMilitiaChangeInternal(settlement, includeDescriptions);
		}

		public override ExplainedNumber CalculateVeteranMilitiaSpawnChance(Settlement settlement)
		{
			ExplainedNumber result = default(ExplainedNumber);
			Hero hero = null;
			if (settlement.IsFortification && settlement.Town.Governor != null)
			{
				hero = settlement.Town.Governor;
			}
			else if (settlement.IsVillage && settlement.Village.TradeBound?.Town.Governor != null)
			{
				hero = settlement.Village.TradeBound.Town.Governor;
			}
			if (hero != null)
			{
				if (hero.GetPerkValue(DefaultPerks.Leadership.CitizenMilitia))
				{
					result.Add(DefaultPerks.Leadership.CitizenMilitia.PrimaryBonus);
				}
				if (hero.GetPerkValue(DefaultPerks.Polearm.Drills))
				{
					result.Add(DefaultPerks.Polearm.Drills.PrimaryBonus);
				}
				if (hero.GetPerkValue(DefaultPerks.Steward.SevenVeterans))
				{
					result.Add(DefaultPerks.Steward.SevenVeterans.PrimaryBonus);
				}
			}
			if (settlement.OwnerClan.Culture.HasFeat(DefaultCulturalFeats.BattanianMilitiaFeat))
			{
				result.Add(DefaultCulturalFeats.BattanianMilitiaFeat.EffectBonus);
			}
			if (settlement.IsFortification)
			{
				settlement.Town.AddEffectOfBuildings(BuildingEffectEnum.MilitiaVeterancyChance, ref result);
			}
			if (settlement.OwnerClan.Kingdom != null && settlement.OwnerClan.Kingdom.ActivePolicies.Contains(DefaultPolicies.LandGrantsForVeteran))
			{
				result.AddFactor(0.1f);
			}
			return result;
		}

		public override void CalculateMilitiaSpawnRate(Settlement settlement, out float meleeTroopRate, out float rangedTroopRate)
		{
			meleeTroopRate = 0.5f;
			rangedTroopRate = 1f - meleeTroopRate;
		}

		private static ExplainedNumber CalculateMilitiaChangeInternal(Settlement settlement, bool includeDescriptions = false)
		{
			ExplainedNumber result = new ExplainedNumber(0f, includeDescriptions);
			if (settlement.IsVillage && settlement.Village.VillageState != 0)
			{
				return result;
			}
			float militia = settlement.Militia;
			if (settlement.IsFortification)
			{
				result.Add(2f, BaseText);
			}
			else if (settlement.IsVillage)
			{
				result.Add(0.5f, BaseText);
			}
			float value = (0f - militia) * 0.025f;
			result.Add(value, RetiredText);
			if (settlement.IsVillage)
			{
				float value2 = settlement.Village.Hearth / 400f;
				result.Add(value2, FromHearthsText);
			}
			else if (settlement.IsFortification)
			{
				float num = settlement.Town.Prosperity / 1000f;
				result.Add(num, FromProsperityText);
				if (settlement.Town.InRebelliousState)
				{
					float num2 = MBMath.Map(settlement.Town.Loyalty, 0f, Campaign.Current.Models.SettlementLoyaltyModel.RebelliousStateStartLoyaltyThreshold, Campaign.Current.Models.SettlementLoyaltyModel.MilitiaBoostPercentage, 0f);
					float value3 = TaleWorlds.Library.MathF.Abs(num * (num2 * 0.01f));
					result.Add(value3, LowLoyaltyText);
				}
			}
			if (settlement.IsTown)
			{
				int num3 = settlement.Town.SoldItems.Sum((Town.SellLog x) => (x.Category.Properties == ItemCategory.Property.BonusToMilitia) ? x.Number : 0);
				if (num3 > 0)
				{
					result.Add(0.2f * (float)num3, MilitiaFromMarketText);
				}
				if (settlement.OwnerClan.Kingdom != null)
				{
					if (settlement.OwnerClan.Kingdom.ActivePolicies.Contains(DefaultPolicies.Serfdom) && settlement.IsTown)
					{
						result.Add(-1f, DefaultPolicies.Serfdom.Name);
					}
					if (settlement.OwnerClan.Kingdom.ActivePolicies.Contains(DefaultPolicies.Cantons))
					{
						result.Add(1f, DefaultPolicies.Cantons.Name);
					}
				}
				if (settlement.OwnerClan.Culture.HasFeat(DefaultCulturalFeats.BattanianMilitiaFeat))
				{
					result.Add(DefaultCulturalFeats.BattanianMilitiaFeat.EffectBonus, CultureText);
				}
			}
			if (settlement.IsCastle || settlement.IsTown)
			{
				settlement.Town.AddEffectOfBuildings(BuildingEffectEnum.Militia, ref result);
				if (settlement.IsCastle && settlement.Town.InRebelliousState)
				{
					settlement.Town.AddEffectOfBuildings(BuildingEffectEnum.MilitiaReduction, ref result);
				}
				GetSettlementMilitiaChangeDueToPolicies(settlement, ref result);
				GetSettlementMilitiaChangeDueToPerks(settlement, ref result);
				GetSettlementMilitiaChangeDueToIssues(settlement, ref result);
			}
			return result;
		}

		private static void GetSettlementMilitiaChangeDueToPerks(Settlement settlement, ref ExplainedNumber result)
		{
			if (settlement.Town != null && settlement.Town.Governor != null)
			{
				PerkHelper.AddPerkBonusForTown(DefaultPerks.OneHanded.SwiftStrike, settlement.Town, ref result);
				PerkHelper.AddPerkBonusForTown(DefaultPerks.Polearm.KeepAtBay, settlement.Town, ref result);
				PerkHelper.AddPerkBonusForTown(DefaultPerks.Bow.MerryMen, settlement.Town, ref result);
				PerkHelper.AddPerkBonusForTown(DefaultPerks.Crossbow.LongShots, settlement.Town, ref result);
				PerkHelper.AddPerkBonusForTown(DefaultPerks.Throwing.SlingingCompetitions, settlement.Town, ref result);
				if (settlement.IsUnderSiege)
				{
					PerkHelper.AddPerkBonusForTown(DefaultPerks.Roguery.ArmsDealer, settlement.Town, ref result);
				}
				PerkHelper.AddPerkBonusForTown(DefaultPerks.Steward.SevenVeterans, settlement.Town, ref result);
			}
		}

		private static void GetSettlementMilitiaChangeDueToPolicies(Settlement settlement, ref ExplainedNumber result)
		{
			Kingdom kingdom = settlement.OwnerClan.Kingdom;
			if (kingdom != null && kingdom.ActivePolicies.Contains(DefaultPolicies.Citizenship))
			{
				result.Add(1f, DefaultPolicies.Citizenship.Name);
			}
		}

		private static void GetSettlementMilitiaChangeDueToIssues(Settlement settlement, ref ExplainedNumber result)
		{
			Campaign.Current.Models.IssueModel.GetIssueEffectsOfSettlement(DefaultIssueEffects.SettlementMilitia, settlement, ref result);
		}
	}
	public class DefaultSettlementPatrolModel : SettlementPatrolModel
	{
		public override CampaignTime GetPatrolPartySpawnDuration(Settlement settlement, bool naval)
		{
			Building guardHouse = GetGuardHouse(settlement);
			return CampaignTime.Days(10f - ((float)guardHouse.CurrentLevel - 1f) * 2f);
		}

		public override bool CanSettlementHavePatrolParties(Settlement settlement, bool naval)
		{
			if (settlement.OwnerClan != null && !settlement.OwnerClan.IsRebelClan && settlement.IsTown)
			{
				return HasGuardHouse(settlement);
			}
			return false;
		}

		private bool HasGuardHouse(Settlement settlement)
		{
			return GetGuardHouse(settlement) != null;
		}

		private Building GetGuardHouse(Settlement settlement)
		{
			if (settlement.Town != null)
			{
				foreach (Building building in settlement.Town.Buildings)
				{
					if (building.BuildingType == DefaultBuildingTypes.SettlementGuardHouse && building.CurrentLevel > 0)
					{
						return building;
					}
				}
			}
			return null;
		}

		public override PartyTemplateObject GetPartyTemplateForPatrolParty(Settlement settlement, bool naval)
		{
			Building guardHouse = GetGuardHouse(settlement);
			if (guardHouse != null)
			{
				return (int)Campaign.Current.Models.BuildingEffectModel.GetBuildingEffect(guardHouse, BuildingEffectEnum.PatrolPartyStrength).ResultNumber switch
				{
					1 => settlement.OwnerClan.Culture.SettlementPatrolPartyTemplateWeak, 
					2 => settlement.OwnerClan.Culture.SettlementPatrolPartyTemplateModerate, 
					3 => settlement.OwnerClan.Culture.SettlementPatrolPartyTemplateStrong, 
					_ => settlement.OwnerClan.Culture.SettlementPatrolPartyTemplateWeak, 
				};
			}
			return null;
		}
	}
	public class DefaultSettlementProsperityModel : SettlementProsperityModel
	{
		private readonly TextObject SurplusFoodText = GameTexts.FindText("str_surplus_food");

		private readonly TextObject LoyaltyText = GameTexts.FindText("str_loyalty");

		private static readonly TextObject FoodShortageText = new TextObject("{=qTFKvGSg}Food Shortage");

		private static readonly TextObject ProsperityFromMarketText = new TextObject("{=RNT5hMVb}Goods From Market");

		private static readonly TextObject RaidedText = new TextObject("{=RVas572P}Raided");

		private static readonly TextObject HousingCostsText = new TextObject("{=ByRAgJy4}Housing Costs");

		public override ExplainedNumber CalculateProsperityChange(Town fortification, bool includeDescriptions = false)
		{
			ExplainedNumber explainedNumber = new ExplainedNumber(0f, includeDescriptions);
			CalculateProsperityChangeInternal(fortification, ref explainedNumber);
			return explainedNumber;
		}

		public override ExplainedNumber CalculateHearthChange(Village village, bool includeDescriptions = false)
		{
			ExplainedNumber result = new ExplainedNumber(0f, includeDescriptions);
			CalculateHearthChangeInternal(village, ref result, includeDescriptions);
			return result;
		}

		private void CalculateHearthChangeInternal(Village village, ref ExplainedNumber result, bool includeDescriptions)
		{
			if (village.VillageState == Village.VillageStates.Normal)
			{
				result = new ExplainedNumber((village.Hearth < 300f) ? 4f : ((village.Hearth < 600f) ? 1.2f : 0.2f), includeDescriptions);
			}
			if (village.VillageState == Village.VillageStates.Looted)
			{
				result.Add(-1f, RaidedText);
			}
			if (village.Settlement.OwnerClan != null && village.Settlement.OwnerClan.Kingdom != null && village.Settlement.OwnerClan.Kingdom.ActivePolicies.Contains(DefaultPolicies.GrazingRights))
			{
				result.Add(-0.25f, DefaultPolicies.GrazingRights.Name);
			}
			if (village.Bound != null && village.VillageState == Village.VillageStates.Normal)
			{
				PerkHelper.AddPerkBonusForTown(DefaultPerks.Medicine.BushDoctor, village.Bound.Town, ref result);
				PerkHelper.AddPerkBonusForTown(DefaultPerks.Athletics.Energetic, village.Bound.Town, ref result);
				PerkHelper.AddPerkBonusForTown(DefaultPerks.Steward.AidCorps, village.Bound.Town, ref result);
				if (village.Bound.IsFortification)
				{
					village.Bound.Town.AddEffectOfBuildings(BuildingEffectEnum.VillageHeartsPerDay, ref result);
				}
			}
			if (village.Settlement.OwnerClan.Culture.HasFeat(DefaultCulturalFeats.EmpireVillageHearthFeat) && result.ResultNumber >= 0f)
			{
				result.AddFactor(DefaultCulturalFeats.EmpireVillageHearthFeat.EffectBonus, GameTexts.FindText("str_culture"));
			}
			Campaign.Current.Models.IssueModel.GetIssueEffectsOfSettlement(DefaultIssueEffects.VillageHearth, village.Settlement, ref result);
		}

		private void CalculateProsperityChangeInternal(Town fortification, ref ExplainedNumber explainedNumber)
		{
			float foodChange = fortification.FoodChange;
			if (fortification.Owner.IsStarving)
			{
				ExplainedNumber bonuses = new ExplainedNumber((foodChange < 0f) ? ((int)foodChange) : 0);
				PerkHelper.AddPerkBonusForTown(DefaultPerks.Medicine.HelpingHands, fortification, ref bonuses);
				explainedNumber.Add(bonuses.ResultNumber * 0.5f, FoodShortageText);
			}
			if (fortification.IsTown)
			{
				if (fortification.Prosperity < 250f)
				{
					explainedNumber.Add(6f, HousingCostsText);
				}
				else if (fortification.Prosperity < 500f)
				{
					explainedNumber.Add(5f, HousingCostsText);
				}
				else if (fortification.Prosperity < 750f)
				{
					explainedNumber.Add(4f, HousingCostsText);
				}
				else if (fortification.Prosperity < 1000f)
				{
					explainedNumber.Add(3f, HousingCostsText);
				}
				else if (fortification.Prosperity < 1250f)
				{
					explainedNumber.Add(2f, HousingCostsText);
				}
				else if (fortification.Prosperity < 1500f)
				{
					explainedNumber.Add(1f, HousingCostsText);
				}
				if (fortification.Prosperity > 21000f)
				{
					explainedNumber.Add(-6f, HousingCostsText);
				}
				else if (fortification.Prosperity > 18000f)
				{
					explainedNumber.Add(-5f, HousingCostsText);
				}
				else if (fortification.Prosperity > 15000f)
				{
					explainedNumber.Add(-4f, HousingCostsText);
				}
				else if (fortification.Prosperity > 12000f)
				{
					explainedNumber.Add(-3f, HousingCostsText);
				}
				else if (fortification.Prosperity > 9000f)
				{
					explainedNumber.Add(-2f, HousingCostsText);
				}
				else if (fortification.Prosperity > 6000f)
				{
					explainedNumber.Add(-1f, HousingCostsText);
				}
			}
			int num = fortification.FoodStocksUpperLimit();
			int num2 = (int)(fortification.FoodStocks + foodChange) - num;
			if (num2 > 0)
			{
				explainedNumber.Add((float)num2 * 0.1f, SurplusFoodText);
			}
			if (fortification.IsTown)
			{
				int num3 = fortification.SoldItems.Sum((Town.SellLog x) => (x.Category.Properties == ItemCategory.Property.BonusToProsperity) ? x.Number : 0);
				if (num3 > 0)
				{
					explainedNumber.Add((float)num3 * 0.1f, ProsperityFromMarketText);
				}
			}
			PerkHelper.AddPerkBonusForTown(DefaultPerks.Medicine.PristineStreets, fortification, ref explainedNumber);
			if (PerkHelper.GetPerkValueForTown(DefaultPerks.Engineering.Apprenticeship, fortification))
			{
				float num4 = 0f;
				foreach (Building item in fortification.Buildings.Where((Building x) => !x.BuildingType.IsDailyProject && x.CurrentLevel > 0))
				{
					_ = item;
					num4 += DefaultPerks.Engineering.Apprenticeship.SecondaryBonus;
				}
				if (num4 > 0f && explainedNumber.ResultNumber > 0f)
				{
					explainedNumber.AddFactor(num4, DefaultPerks.Engineering.Apprenticeship.Name);
				}
			}
			fortification.AddEffectOfBuildings(BuildingEffectEnum.Prosperity, ref explainedNumber);
			foreach (Building building in fortification.Buildings)
			{
				if (building.CurrentLevel > 0 && !building.BuildingType.IsMilitaryProject && !building.BuildingType.IsDailyProject)
				{
					PerkHelper.AddPerkBonusForTown(DefaultPerks.Medicine.CleanInfrastructure, fortification, ref explainedNumber);
				}
			}
			if (fortification.Loyalty > (float)Campaign.Current.Models.SettlementLoyaltyModel.ThresholdForProsperityBoost && foodChange > 0f)
			{
				explainedNumber.Add(Campaign.Current.Models.SettlementLoyaltyModel.HighLoyaltyProsperityEffect, LoyaltyText);
			}
			else if (fortification.Loyalty <= (float)Campaign.Current.Models.SettlementLoyaltyModel.ThresholdForProsperityPenalty)
			{
				explainedNumber.Add(Campaign.Current.Models.SettlementLoyaltyModel.LowLoyaltyProsperityEffect, LoyaltyText);
			}
			if ((fortification.IsTown || fortification.IsCastle) && !fortification.CurrentBuilding.IsCurrentlyDefault && fortification.Governor != null && fortification.Governor.GetPerkValue(DefaultPerks.Trade.TrickleDown))
			{
				explainedNumber.Add(DefaultPerks.Trade.TrickleDown.SecondaryBonus, DefaultPerks.Trade.TrickleDown.Name);
			}
			if (fortification.Settlement.OwnerClan.Kingdom != null && fortification.IsTown)
			{
				if (fortification.Settlement.OwnerClan.Kingdom.ActivePolicies.Contains(DefaultPolicies.RoadTolls))
				{
					explainedNumber.Add(-0.2f, DefaultPolicies.RoadTolls.Name);
				}
				if (fortification.Settlement.OwnerClan.Kingdom.RulingClan == fortification.Settlement.OwnerClan && fortification.Settlement.OwnerClan.Kingdom.ActivePolicies.Contains(DefaultPolicies.ImperialTowns))
				{
					explainedNumber.Add(1f, DefaultPolicies.ImperialTowns.Name);
				}
				if (fortification.Settlement.OwnerClan.Kingdom.ActivePolicies.Contains(DefaultPolicies.CrownDuty))
				{
					explainedNumber.Add(-1f, DefaultPolicies.CrownDuty.Name);
				}
				if (fortification.Settlement.OwnerClan.Kingdom.ActivePolicies.Contains(DefaultPolicies.WarTax))
				{
					explainedNumber.Add(-1f, DefaultPolicies.WarTax.Name);
				}
			}
			GetSettlementProsperityChangeDueToIssues(fortification.Settlement, ref explainedNumber);
		}

		private void GetSettlementProsperityChangeDueToIssues(Settlement settlement, ref ExplainedNumber result)
		{
			Campaign.Current.Models.IssueModel.GetIssueEffectsOfSettlement(DefaultIssueEffects.SettlementProsperity, settlement, ref result);
		}
	}
	public class DefaultSettlementSecurityModel : SettlementSecurityModel
	{
		private const float GarrisonHighSecurityGain = 3f;

		private const float GarrisonLowSecurityPenalty = -3f;

		private const float NearbyHideoutPenalty = -2f;

		private const float VillageLootedSecurityEffect = -2f;

		private const float UnderSiegeSecurityEffect = -3f;

		private const float MaxProsperityEffect = -5f;

		private const float PerProsperityEffect = -0.0005f;

		private readonly TextObject GarrisonText = GameTexts.FindText("str_garrison");

		private readonly TextObject LootedVillagesText = GameTexts.FindText("str_looted_villages");

		private readonly TextObject CorruptionText = GameTexts.FindText("str_corruption");

		private readonly TextObject NearbyHideoutText = GameTexts.FindText("str_nearby_hideout");

		private readonly TextObject UnderSiegeText = GameTexts.FindText("str_under_siege");

		private readonly TextObject ProsperityText = GameTexts.FindText("str_prosperity");

		private readonly TextObject Security = GameTexts.FindText("str_security");

		private readonly TextObject SecurityDriftText = GameTexts.FindText("str_security_drift");

		private readonly TextObject PatrolPartiesText = GameTexts.FindText("str_patrol_parties");

		public override int MaximumSecurityInSettlement => 100;

		public override int SecurityDriftMedium => 50;

		public override float MapEventSecurityEffectRadius => 50f;

		public override float HideoutClearedSecurityEffectRadius => 100f;

		public override int HideoutClearedSecurityGain => 6;

		public override int ThresholdForTaxCorruption => 50;

		public override int ThresholdForHigherTaxCorruption => 0;

		public override int ThresholdForTaxBoost => 75;

		public override int SettlementTaxBoostPercentage => 5;

		public override int SettlementTaxPenaltyPercentage => 10;

		public override int ThresholdForNotableRelationBonus => 75;

		public override int ThresholdForNotableRelationPenalty => 50;

		public override int DailyNotableRelationBonus => 1;

		public override int DailyNotableRelationPenalty => -1;

		public override int DailyNotablePowerBonus => 1;

		public override int DailyNotablePowerPenalty => -1;

		public override ExplainedNumber CalculateSecurityChange(Town town, bool includeDescriptions = false)
		{
			ExplainedNumber explainedNumber = new ExplainedNumber(0f, includeDescriptions);
			CalculateInfestedHideoutEffectsOnSecurity(town, ref explainedNumber);
			CalculateRaidedVillageEffectsOnSecurity(town, ref explainedNumber);
			CalculateUnderSiegeEffectsOnSecurity(town, ref explainedNumber);
			CalculateProsperityEffectOnSecurity(town, ref explainedNumber);
			CalculateGarrisonEffectsOnSecurity(town, ref explainedNumber);
			CalculatePolicyEffectsOnSecurity(town, ref explainedNumber);
			CalculateGovernorEffectsOnSecurity(town, ref explainedNumber);
			CalculateProjectEffectsOnSecurity(town, ref explainedNumber);
			CalculateIssueEffectsOnSecurity(town, ref explainedNumber);
			CalculatePerkEffectsOnSecurity(town, ref explainedNumber);
			CalculateSecurityDrift(town, ref explainedNumber);
			CalculateSettlementProjectSecurityBonuses(town, ref explainedNumber);
			CalculateSettlementPatrolPartiesBonuses(town, ref explainedNumber);
			return explainedNumber;
		}

		private void CalculateSettlementPatrolPartiesBonuses(Town town, ref ExplainedNumber result)
		{
			if (town.Settlement.PatrolParty == null)
			{
				return;
			}
			foreach (Building building in town.Buildings)
			{
				if (building.BuildingType == DefaultBuildingTypes.SettlementGuardHouse && building.CurrentLevel > 0)
				{
					result.Add((float)building.CurrentLevel * 0.5f + 0.5f, PatrolPartiesText);
					break;
				}
			}
		}

		private void CalculateSettlementProjectSecurityBonuses(Town town, ref ExplainedNumber result)
		{
			town.AddEffectOfBuildings(BuildingEffectEnum.SecurityPerDay, ref result);
		}

		private void CalculateProsperityEffectOnSecurity(Town town, ref ExplainedNumber explainedNumber)
		{
			explainedNumber.Add(TaleWorlds.Library.MathF.Max(-5f, -0.0005f * town.Prosperity), ProsperityText);
		}

		private void CalculateUnderSiegeEffectsOnSecurity(Town town, ref ExplainedNumber explainedNumber)
		{
			if (town.Settlement.IsUnderSiege)
			{
				explainedNumber.Add(-3f, UnderSiegeText);
			}
		}

		private void CalculateRaidedVillageEffectsOnSecurity(Town town, ref ExplainedNumber explainedNumber)
		{
			float num = 0f;
			foreach (Village boundVillage in town.Settlement.BoundVillages)
			{
				if (boundVillage.VillageState == Village.VillageStates.Looted)
				{
					num += -2f;
					break;
				}
			}
			explainedNumber.Add(num, LootedVillagesText);
		}

		private void CalculateInfestedHideoutEffectsOnSecurity(Town town, ref ExplainedNumber explainedNumber)
		{
			float num = Campaign.Current.EstimatedAverageBanditPartySpeed * (float)CampaignTime.HoursInDay * 0.5f;
			foreach (Hideout item in Hideout.All)
			{
				if (item.IsInfested && Campaign.Current.Models.MapDistanceModel.GetDistance(town.Settlement, item.Settlement, isFromPort: false, isTargetingPort: false, MobileParty.NavigationType.Default) < num)
				{
					explainedNumber.Add(-2f, NearbyHideoutText);
					break;
				}
			}
		}

		private void CalculateSecurityDrift(Town town, ref ExplainedNumber explainedNumber)
		{
			explainedNumber.Add(-1f * (town.Security - (float)SecurityDriftMedium) / 15f, SecurityDriftText);
		}

		private void CalculatePolicyEffectsOnSecurity(Town town, ref ExplainedNumber explainedNumber)
		{
			Kingdom kingdom = town.Settlement.OwnerClan.Kingdom;
			if (kingdom == null)
			{
				return;
			}
			if (town.IsTown)
			{
				if (kingdom.ActivePolicies.Contains(DefaultPolicies.Bailiffs))
				{
					explainedNumber.Add(1f, DefaultPolicies.Bailiffs.Name);
				}
				if (kingdom.ActivePolicies.Contains(DefaultPolicies.Serfdom))
				{
					explainedNumber.Add(1f, DefaultPolicies.Serfdom.Name);
				}
				if (kingdom.ActivePolicies.Contains(DefaultPolicies.Magistrates))
				{
					explainedNumber.Add(1f, DefaultPolicies.Magistrates.Name);
				}
			}
			if (kingdom.ActivePolicies.Contains(DefaultPolicies.TrialByJury))
			{
				explainedNumber.Add(-0.2f, DefaultPolicies.TrialByJury.Name);
			}
		}

		private void CalculateGovernorEffectsOnSecurity(Town town, ref ExplainedNumber explainedNumber)
		{
		}

		private void CalculateGarrisonEffectsOnSecurity(Town town, ref ExplainedNumber result)
		{
			if (town.GarrisonParty != null && town.GarrisonParty.MemberRoster.Count != 0 && town.GarrisonParty.MemberRoster.TotalHealthyCount != 0)
			{
				ExplainedNumber bonuses = new ExplainedNumber(0.01f);
				PerkHelper.AddPerkBonusForTown(DefaultPerks.OneHanded.StandUnited, town, ref bonuses);
				CalculateStrengthOfGarrisonParty(town.GarrisonParty.Party, out var totalStrength, out var archerStrength, out var cavalryStrength);
				float num = totalStrength * bonuses.ResultNumber;
				result.Add(num, GarrisonText);
				if (PerkHelper.GetPerkValueForTown(DefaultPerks.Leadership.Authority, town))
				{
					result.Add(num * DefaultPerks.Leadership.Authority.PrimaryBonus, DefaultPerks.Leadership.Authority.Name);
				}
				if (PerkHelper.GetPerkValueForTown(DefaultPerks.Riding.ReliefForce, town))
				{
					float num2 = cavalryStrength / totalStrength;
					result.Add(num * num2 * DefaultPerks.Riding.ReliefForce.SecondaryBonus, DefaultPerks.Riding.ReliefForce.Name);
				}
				float num3 = archerStrength / totalStrength;
				if (PerkHelper.GetPerkValueForTown(DefaultPerks.Bow.MountedArchery, town))
				{
					result.Add(num * num3 * DefaultPerks.Bow.MountedArchery.SecondaryBonus, DefaultPerks.Bow.MountedArchery.Name);
				}
				if (PerkHelper.GetPerkValueForTown(DefaultPerks.Bow.RangersSwiftness, town))
				{
					result.Add(num * num3 * DefaultPerks.Bow.RangersSwiftness.SecondaryBonus, DefaultPerks.Bow.RangersSwiftness.Name);
				}
				if (PerkHelper.GetPerkValueForTown(DefaultPerks.Crossbow.RenownMarksmen, town))
				{
					result.Add(num * num3 * DefaultPerks.Crossbow.RenownMarksmen.SecondaryBonus, DefaultPerks.Crossbow.RenownMarksmen.Name);
				}
			}
		}

		private void CalculateStrengthOfGarrisonParty(PartyBase party, out float totalStrength, out float archerStrength, out float cavalryStrength)
		{
			totalStrength = 0f;
			archerStrength = 0f;
			cavalryStrength = 0f;
			float leaderModifier = 0f;
			MapEvent.PowerCalculationContext context = MapEvent.PowerCalculationContext.Siege;
			BattleSideEnum side = BattleSideEnum.Defender;
			if (party.MapEvent != null)
			{
				side = party.Side;
				leaderModifier = party.LeaderHero?.PowerModifier ?? 0f;
				context = party.MapEvent.SimulationContext;
			}
			for (int i = 0; i < party.MemberRoster.Count; i++)
			{
				TroopRosterElement elementCopyAtIndex = party.MemberRoster.GetElementCopyAtIndex(i);
				if (elementCopyAtIndex.Character != null)
				{
					float troopPower = Campaign.Current.Models.MilitaryPowerModel.GetTroopPower(elementCopyAtIndex.Character, side, context, leaderModifier);
					float num = (float)(elementCopyAtIndex.Number - elementCopyAtIndex.WoundedNumber) * troopPower;
					if (elementCopyAtIndex.Character.IsMounted)
					{
						cavalryStrength += num;
					}
					if (elementCopyAtIndex.Character.IsRanged)
					{
						archerStrength += num;
					}
					totalStrength += num;
				}
			}
		}

		private void CalculatePerkEffectsOnSecurity(Town town, ref ExplainedNumber result)
		{
			float num = (float)town.Settlement.Parties.Where(delegate(MobileParty x)
			{
				Clan actualClan = x.ActualClan;
				return actualClan != null && !actualClan.IsAtWarWith(town.MapFaction) && (x.LeaderHero?.GetPerkValue(DefaultPerks.Leadership.Presence) ?? false);
			}).Count() * DefaultPerks.Leadership.Presence.PrimaryBonus;
			if (num > 0f)
			{
				result.Add(num, DefaultPerks.Leadership.Presence.Name);
			}
			if (town.Governor != null && town.Governor.GetPerkValue(DefaultPerks.Roguery.KnowHow))
			{
				PerkHelper.AddPerkBonusForTown(DefaultPerks.Roguery.KnowHow, town, ref result);
			}
			PerkHelper.AddPerkBonusForTown(DefaultPerks.OneHanded.ToBeBlunt, town, ref result);
			PerkHelper.AddPerkBonusForTown(DefaultPerks.Throwing.Focus, town, ref result);
			PerkHelper.AddPerkBonusForTown(DefaultPerks.Polearm.Skewer, town, ref result);
			PerkHelper.AddPerkBonusForTown(DefaultPerks.Tactics.Gensdarmes, town, ref result);
		}

		private void CalculateProjectEffectsOnSecurity(Town town, ref ExplainedNumber explainedNumber)
		{
		}

		private void CalculateIssueEffectsOnSecurity(Town town, ref ExplainedNumber explainedNumber)
		{
			Campaign.Current.Models.IssueModel.GetIssueEffectsOfSettlement(DefaultIssueEffects.SettlementSecurity, town.Settlement, ref explainedNumber);
		}

		public override float GetLootedNearbyPartySecurityEffect(Town town, float sumOfAttackedPartyStrengths)
		{
			return -1f * sumOfAttackedPartyStrengths * 0.005f;
		}

		public override float GetNearbyBanditPartyDefeatedSecurityEffect(Town town, float sumOfAttackedPartyStrengths)
		{
			return sumOfAttackedPartyStrengths * 0.005f;
		}

		public override void CalculateGoldGainDueToHighSecurity(Town town, ref ExplainedNumber explainedNumber)
		{
			float num = MBMath.Map(town.Security, ThresholdForTaxBoost, MaximumSecurityInSettlement, 0f, SettlementTaxBoostPercentage);
			explainedNumber.AddFactor(num * 0.01f, Security);
		}

		public override void CalculateGoldCutDueToLowSecurity(Town town, ref ExplainedNumber explainedNumber)
		{
			float num = MBMath.Map(town.Security, ThresholdForHigherTaxCorruption, ThresholdForTaxCorruption, SettlementTaxPenaltyPercentage, 0f);
			explainedNumber.AddFactor(-1f * num * 0.01f, CorruptionText);
		}
	}
	public class DefaultSettlementTaxModel : SettlementTaxModel
	{
		private readonly TextObject ProsperityText = GameTexts.FindText("str_prosperity");

		private static readonly TextObject VeryLowLoyalty = new TextObject("{=CcQzFnpN}Very Low Loyalty");

		public override float SettlementCommissionRateTown => 0.7f;

		public override float SettlementCommissionRateVillage => 1f;

		public override int SettlementCommissionDecreaseSecurityThreshold => 75;

		public override int MaximumDecreaseBasedOnSecuritySecurity => 10;

		public override float GetTownTaxRatio(Town town)
		{
			float num = 1f;
			if (town.Settlement.OwnerClan.Kingdom != null && town.Settlement.OwnerClan.Kingdom.ActivePolicies.Contains(DefaultPolicies.CrownDuty))
			{
				num += 0.05f;
			}
			return SettlementCommissionRateTown * num;
		}

		public override float GetVillageTaxRatio(Village village)
		{
			float num = SettlementCommissionRateVillage;
			if (village.Settlement.OwnerClan.Kingdom != null && village.Settlement.OwnerClan.Kingdom.ActivePolicies.Contains(DefaultPolicies.LandGrantsForVeteran))
			{
				num -= num * 0.05f;
			}
			return num;
		}

		public override float GetTownCommissionChangeBasedOnSecurity(Town town, float commission)
		{
			if (town.Security < (float)SettlementCommissionDecreaseSecurityThreshold)
			{
				float num = MBMath.Map((float)SettlementCommissionDecreaseSecurityThreshold - town.Security, 0f, SettlementCommissionDecreaseSecurityThreshold, MaximumDecreaseBasedOnSecuritySecurity, 0f);
				commission -= commission * (num * 0.01f);
				return commission;
			}
			return commission;
		}

		public override ExplainedNumber CalculateTownTax(Town town, bool includeDescriptions = false)
		{
			ExplainedNumber result = new ExplainedNumber(0f, includeDescriptions);
			CalculateDailyTaxInternal(town, ref result);
			return result;
		}

		private float CalculateDailyTax(Town town, ref ExplainedNumber explainedNumber)
		{
			float prosperity = town.Prosperity;
			float num = 1f;
			if (town.Settlement.OwnerClan.Kingdom != null && town.Settlement.OwnerClan.Kingdom.ActivePolicies.Contains(DefaultPolicies.CouncilOfTheCommons))
			{
				num -= 0.05f;
			}
			float num2 = 0.35f;
			float value = prosperity * num2 * num;
			explainedNumber.Add(value, ProsperityText);
			return explainedNumber.ResultNumber;
		}

		private void CalculateDailyTaxInternal(Town town, ref ExplainedNumber result)
		{
			float rawTax = CalculateDailyTax(town, ref result);
			CalculatePolicyGoldCut(town, rawTax, ref result);
			if (PerkHelper.GetPerkValueForTown(DefaultPerks.Bow.QuickDraw, town))
			{
				PerkHelper.AddPerkBonusForTown(DefaultPerks.Bow.QuickDraw, town, ref result);
			}
			if (town.Governor != null)
			{
				if (town.Governor.GetPerkValue(DefaultPerks.Steward.Logistician))
				{
					PerkHelper.AddPerkBonusForTown(DefaultPerks.Steward.Logistician, town, ref result);
				}
				if (town.Governor.GetPerkValue(DefaultPerks.Steward.PriceOfLoyalty))
				{
					int num = town.Governor.GetSkillValue(DefaultSkills.Steward) - Campaign.Current.Models.CharacterDevelopmentModel.MinSkillRequiredForEpicPerkBonus;
					result.AddFactor(DefaultPerks.Steward.PriceOfLoyalty.SecondaryBonus * (float)num, DefaultPerks.Steward.PriceOfLoyalty.Name);
				}
				if (PerkHelper.GetPerkValueForTown(DefaultPerks.Scouting.DesertBorn, town))
				{
					PerkHelper.AddPerkBonusForTown(DefaultPerks.Scouting.DesertBorn, town, ref result);
				}
			}
			if (town.IsTown && town.OwnerClan.Culture.HasFeat(DefaultCulturalFeats.KhuzaitDecreasedTaxFeat))
			{
				result.AddFactor(DefaultCulturalFeats.KhuzaitDecreasedTaxFeat.EffectBonus, GameTexts.FindText("str_culture"));
			}
			GetSettlementTaxChangeDueToIssues(town, ref result);
			CalculateSettlementTaxDueToSecurity(town, ref result);
			CalculateSettlementTaxDueToLoyalty(town, ref result);
			CalculateSettlementTaxDueToBuildings(town, ref result);
			result.Clamp(0f, float.MaxValue);
		}

		private void CalculateSettlementTaxDueToSecurity(Town town, ref ExplainedNumber explainedNumber)
		{
			SettlementSecurityModel settlementSecurityModel = Campaign.Current.Models.SettlementSecurityModel;
			if (town.Security >= (float)settlementSecurityModel.ThresholdForTaxBoost)
			{
				settlementSecurityModel.CalculateGoldGainDueToHighSecurity(town, ref explainedNumber);
			}
			else if (town.Security >= (float)settlementSecurityModel.ThresholdForHigherTaxCorruption && town.Security < (float)settlementSecurityModel.ThresholdForTaxCorruption)
			{
				settlementSecurityModel.CalculateGoldCutDueToLowSecurity(town, ref explainedNumber);
			}
		}

		private void CalculateSettlementTaxDueToLoyalty(Town town, ref ExplainedNumber explainedNumber)
		{
			SettlementLoyaltyModel settlementLoyaltyModel = Campaign.Current.Models.SettlementLoyaltyModel;
			if (town.Loyalty >= (float)settlementLoyaltyModel.ThresholdForTaxBoost)
			{
				settlementLoyaltyModel.CalculateGoldGainDueToHighLoyalty(town, ref explainedNumber);
			}
			else if (town.Loyalty >= (float)settlementLoyaltyModel.ThresholdForHigherTaxCorruption && town.Loyalty <= (float)settlementLoyaltyModel.ThresholdForTaxCorruption)
			{
				settlementLoyaltyModel.CalculateGoldCutDueToLowLoyalty(town, ref explainedNumber);
			}
			else if (town.Loyalty < (float)settlementLoyaltyModel.ThresholdForHigherTaxCorruption)
			{
				explainedNumber.AddFactor(-1f, VeryLowLoyalty);
			}
		}

		private void CalculateSettlementTaxDueToBuildings(Town town, ref ExplainedNumber result)
		{
			town.AddEffectOfBuildings(BuildingEffectEnum.TaxPerDay, ref result);
			town.AddEffectOfBuildings(BuildingEffectEnum.DenarByBoundVillageHeartPerDay, ref result);
		}

		private void CalculatePolicyGoldCut(Town town, float rawTax, ref ExplainedNumber explainedNumber)
		{
			if (!town.MapFaction.IsKingdomFaction)
			{
				return;
			}
			Kingdom kingdom = (Kingdom)town.MapFaction;
			if (town.IsTown)
			{
				if (kingdom.ActivePolicies.Contains(DefaultPolicies.Magistrates))
				{
					explainedNumber.Add(-0.05f * rawTax, DefaultPolicies.Magistrates.Name);
				}
				if (kingdom.ActivePolicies.Contains(DefaultPolicies.Bailiffs))
				{
					explainedNumber.Add(-0.05f * rawTax, DefaultPolicies.Bailiffs.Name);
				}
				if (kingdom.ActivePolicies.Contains(DefaultPolicies.TribunesOfThePeople))
				{
					explainedNumber.Add(-0.05f * rawTax, DefaultPolicies.TribunesOfThePeople.Name);
				}
			}
			if (kingdom.ActivePolicies.Contains(DefaultPolicies.Cantons))
			{
				explainedNumber.Add(-0.1f * rawTax, DefaultPolicies.Cantons.Name);
			}
		}

		private void GetSettlementTaxChangeDueToIssues(Town center, ref ExplainedNumber result)
		{
			Campaign.Current.Models.IssueModel.GetIssueEffectsOfSettlement(DefaultIssueEffects.SettlementTax, center.Owner.Settlement, ref result);
		}

		public override int CalculateVillageTaxFromIncome(Village village, int marketIncome)
		{
			if (marketIncome == 0)
			{
				return 0;
			}
			return (int)((float)marketIncome * Campaign.Current.Models.SettlementTaxModel.GetVillageTaxRatio(village));
		}
	}
	public class DefaultSettlementValueModel : SettlementValueModel
	{
		private const float BenefitRatioForFaction = 0.33f;

		private const float CastleMultiplier = 1.25f;

