	public class DefaultTradeAgreementModel : TradeAgreementModel
	{
		private const float MaxExposureEffect = 30f;

		private const float MarriageBetweenRulingClansBonus = 10f;

		private const float MarriageBetweenKingdomsBonus = 5f;

		private const float AlliedScoreBonus = 5f;

		private const float WarWithAllyPenalty = -15f;

		private const float WarWithAnyKingdomPenalty = -1.5f;

		private const float NoWarBonus = 2.5f;

		private const float ProsperityCheckRange = 2500f;

		private static readonly TextObject _kingdomsAtWarText = new TextObject("{=vo7kAlkR}The kingdoms are at war.");

		private static readonly TextObject _eliminatedKingdomText = new TextObject("{=ZeNt57yM}The kingdom is eliminated.");

		private static readonly TextObject _existingTradeAgreementText = new TextObject("{=8HXcla1b}These kingdoms already have a trade agreement.");

		private static readonly TextObject _maximumNumberOfTradeAgreementsText = new TextObject("{=DJ51OJWj}You already have maximum number of trade agreements.");

		private static readonly TextObject _noTownText = new TextObject("{=QQ4bi6Zr}You don't own any towns.");

		private static readonly TextObject _landlockedText = new TextObject("{=Ig8l75Rg}One of the kingdoms is landlocked.");

		private static readonly TextObject _kingdomsNotNeighborsText = new TextObject("{=Bu6YdMme}Kingdoms aren't neighbors.");

		private static readonly TextObject _limitedSharedBordersText = new TextObject("{=EapZFDGF}Limited shared borders");

		private static readonly TextObject _relationsText = new TextObject("{=3YVDMg5X}Low relations between rulers");

		private static readonly TextObject _warWithAlliedText = new TextObject("{=tT91z3AL}Your realm is at war with their ally.");

		private static readonly TextObject _warText = new TextObject("{=FaEOnF8q}Your realm is a participant in a war.");

		private static readonly TextObject _lowSecurityText = new TextObject("{=aTuRql06}Target faction is concerned by security of towns in your realm.");

		private static readonly TextObject _higherQuerierProsperityText = new TextObject("{=ji8oPOXU}Your realm is not open to negotiation as target faction’s prosperity is too low.");

		private static readonly TextObject _higherQueriedProsperityText = new TextObject("{=lYaumdUj}Your realm has lower prosperity then target faction.");

		private static readonly TextObject _recentWarText = new TextObject("{=lDIz0nEY}Recent war");

		private const int MaxReasonsInExplanation = 3;

		private ITradeAgreementsCampaignBehavior _tradeAgreementsBehavior;

		private ITradeAgreementsCampaignBehavior TradeAgreementsCampaignBehavior
		{
			get
			{
				if (_tradeAgreementsBehavior == null)
				{
					_tradeAgreementsBehavior = Campaign.Current.GetCampaignBehavior<ITradeAgreementsCampaignBehavior>();
				}
				return _tradeAgreementsBehavior;
			}
		}

		public override int GetInfluenceCostOfProposingTradeAgreement(Clan proposerClan)
		{
			return 200;
		}

		public override int GetMaximumTradeAgreementCount(Kingdom kingdom)
		{
			return 2;
		}

		public override bool CanMakeTradeAgreement(Kingdom querierKingdom, Kingdom queriedKingdom, bool checkOtherSideSupport, out TextObject reason, bool includeReason = false)
		{
			reason = (includeReason ? TextObject.GetEmpty() : null);
			if (querierKingdom.IsAtWarWith(queriedKingdom))
			{
				reason = _kingdomsAtWarText;
				return false;
			}
			if (queriedKingdom.IsEliminated)
			{
				reason = _eliminatedKingdomText;
				return false;
			}
			ITradeAgreementsCampaignBehavior tradeAgreementsCampaignBehavior = TradeAgreementsCampaignBehavior;
			if (tradeAgreementsCampaignBehavior != null && tradeAgreementsCampaignBehavior.HasTradeAgreement(querierKingdom, queriedKingdom, out var _))
			{
				reason = _existingTradeAgreementText;
				return false;
			}
			if (Kingdom.All.Count((Kingdom x) => x != querierKingdom && !x.IsEliminated && (TradeAgreementsCampaignBehavior?.HasTradeAgreement(querierKingdom, x, out var _) ?? false)) >= Campaign.Current.Models.TradeAgreementModel.GetMaximumTradeAgreementCount(querierKingdom))
			{
				reason = _maximumNumberOfTradeAgreementsText;
				return false;
			}
			if (Kingdom.All.Count((Kingdom x) => x != queriedKingdom && !x.IsEliminated && (TradeAgreementsCampaignBehavior?.HasTradeAgreement(queriedKingdom, x, out var _) ?? false)) >= Campaign.Current.Models.TradeAgreementModel.GetMaximumTradeAgreementCount(querierKingdom))
			{
				if (includeReason)
				{
					reason = new TextObject("{=O6zpuLGa}{OTHER_KINGDOM} already has maximum number of trade agreements.");
					reason.SetTextVariable("OTHER_KINGDOM", queriedKingdom.Name);
				}
				return false;
			}
			if (querierKingdom.Towns.Count == 0)
			{
				reason = _noTownText;
				return false;
			}
			if (queriedKingdom.Towns.Count == 0)
			{
				if (includeReason)
				{
					reason = new TextObject("{=XkbKOO3v}{OTHER_KINGDOM} does not own any towns.");
					reason.SetTextVariable("OTHER_KINGDOM", queriedKingdom.Name);
				}
				return false;
			}
			if (!querierKingdom.Fiefs.Any((Town x) => x.GetNeighborFortifications(MobileParty.NavigationType.All).Any((Settlement y) => y.MapFaction == queriedKingdom)))
			{
				reason = _kingdomsNotNeighborsText;
				return false;
			}
			if ((querierKingdom.Towns.All((Town x) => x.Settlement.HasPort) && queriedKingdom.Towns.All((Town x) => !x.Settlement.HasPort)) || (querierKingdom.Towns.All((Town x) => !x.Settlement.HasPort) && queriedKingdom.Towns.All((Town x) => x.Settlement.HasPort)))
			{
				reason = _landlockedText;
				return false;
			}
			if (checkOtherSideSupport)
			{
				TradeAgreementDecision tradeAgreementDecision = new TradeAgreementDecision(queriedKingdom.RulingClan, querierKingdom);
				KingdomElection kingdomElection = new KingdomElection(tradeAgreementDecision);
				kingdomElection.SetupResultWithoutPlayerSupport();
				if (queriedKingdom == Clan.PlayerClan.Kingdom)
				{
					DecisionOutcome supportedOutcome = kingdomElection.PossibleOutcomes.FirstOrDefault((DecisionOutcome x) => x is TradeAgreementDecision.TradeAgreementDecisionOutcome tradeAgreementDecisionOutcome && tradeAgreementDecisionOutcome.ShouldTradeAgreementStart);
					return kingdomElection.GetWinChanceWithPlayerSupport(supportedOutcome, Supporter.SupportWeights.FullyPush) > 0.5f;
				}
				if (kingdomElection.GetWinChanceForSponsor(queriedKingdom.RulingClan) < 0.5f)
				{
					tradeAgreementDecision.CalculateSupport(queriedKingdom.RulingClan, out reason);
					return false;
				}
			}
			return true;
		}

		public override float GetScoreOfStartingTradeAgreement(Kingdom querierKingdom, Kingdom queriedKingdom, Clan clan, out TextObject detailedBreakdownTooltip, bool includeExplanation = false)
		{
			detailedBreakdownTooltip = null;
			float securityEffect = GetSecurityEffect(queriedKingdom);
			float relationEffectBetweenRulers = GetRelationEffectBetweenRulers(querierKingdom, queriedKingdom);
			float allianceEffect = GetAllianceEffect(querierKingdom, queriedKingdom);
			bool isAtWarWithAlliedKingdom;
			bool isAtWarWithAnyKingdom;
			float diplomacyEffect = GetDiplomacyEffect(querierKingdom, queriedKingdom, out isAtWarWithAlliedKingdom, out isAtWarWithAnyKingdom);
			float marriageEffect = GetMarriageEffect(querierKingdom, queriedKingdom);
			float querierKingdomAverageProsperity;
			float queriedKingdomAverageProsperity;
			float prosperityEffect = GetProsperityEffect(querierKingdom, queriedKingdom, out querierKingdomAverageProsperity, out queriedKingdomAverageProsperity);
			float exposureEffect = GetExposureEffect(querierKingdom, queriedKingdom);
			float num = 0f;
			if (querierKingdom == Clan.PlayerClan.Kingdom && !Clan.PlayerClan.IsUnderMercenaryService)
			{
				num += GetSubjectiveEffect(queriedKingdom, clan);
			}
			float value = securityEffect + prosperityEffect + relationEffectBetweenRulers + allianceEffect + diplomacyEffect + exposureEffect + num + marriageEffect;
			if (includeExplanation)
			{
				List<(float, TextObject)> list = new List<(float, TextObject)>();
				if (securityEffect < 0f)
				{
					list.Add((TaleWorlds.Library.MathF.Abs(securityEffect), _lowSecurityText));
				}
				if (relationEffectBetweenRulers < 0f)
				{
					list.Add(((float)Campaign.Current.Models.DiplomacyModel.MaxRelationLimit * 0.1f - relationEffectBetweenRulers, _relationsText));
				}
				if (isAtWarWithAlliedKingdom)
				{
					list.Add((TaleWorlds.Library.MathF.Abs(-15f), _warWithAlliedText));
				}
				else if (isAtWarWithAnyKingdom)
				{
					list.Add((TaleWorlds.Library.MathF.Abs(-1.5f), _warText));
				}
				if (list.Sum(((float, TextObject) x) => x.Item1).ApproximatelyEqualsTo(0f))
				{
					if (querierKingdomAverageProsperity > queriedKingdomAverageProsperity)
					{
						list.Add((1f, _higherQuerierProsperityText));
					}
					else
					{
						list.Add((1f, _higherQueriedProsperityText));
					}
					if (exposureEffect < 30f)
					{
						list.Add((1f, _limitedSharedBordersText));
					}
				}
				list = list.OrderByDescending(((float, TextObject) x) => x.Item1).ToList();
				List<TextObject> list2 = new List<TextObject>();
				foreach (var item in list)
				{
					list2.Add(item.Item2);
					if (list2.Count >= 3)
					{
						break;
					}
				}
				TextObject variable = GameTexts.GameTextHelper.MergeTextObjectsWithSymbol(list2, new TextObject("{=!}{newline}"));
				detailedBreakdownTooltip = new TextObject("{=jXcb9oHi}{KINGDOM} is not considering a trade agreement with your realm due to:{newline}{newline}{REASONS_BY_LINE}");
				detailedBreakdownTooltip.SetTextVariable("KINGDOM", querierKingdom.Name);
				detailedBreakdownTooltip.SetTextVariable("REASONS_BY_LINE", variable);
			}
			return MBMath.ClampFloat(value, 0f, 100f);
		}

		private float GetMarriageEffect(Kingdom querierKingdom, Kingdom queriedKingdom)
		{
			if (IsThereMarriageBetweenClans(queriedKingdom.RulingClan, querierKingdom.RulingClan))
			{
				return 10f;
			}
			if (queriedKingdom.Clans.AnyQ((Clan clan) => clan != queriedKingdom.RulingClan && IsThereMarriageBetweenClans(querierKingdom.RulingClan, clan)))
			{
				return 5f;
			}
			return 0f;
		}

		private bool IsThereMarriageBetweenClans(Clan clan1, Clan clan2)
		{
			if (!clan1.AliveLords.Any((Hero x) => x.OriginClan == clan2))
			{
				return clan2.AliveLords.Any((Hero x) => x.OriginClan == clan1);
			}
			return true;
		}

		private float GetSubjectiveEffect(Kingdom queriedKingdom, Clan clan)
		{
			return (float)clan.Leader.GetRelation(queriedKingdom.Leader) * 0.25f + clan.Leader.RandomFloatWithSeed((uint)CampaignTime.Now.ToWeeks, -10f, 10f);
		}

		private float GetAllianceEffect(Kingdom querierKingdom, Kingdom queriedKingdom)
		{
			if (queriedKingdom.IsAllyWith(querierKingdom))
			{
				return 5f;
			}
			return 0f;
		}

		private float GetDiplomacyEffect(Kingdom querierKingdom, Kingdom queriedKingdom, out bool isAtWarWithAlliedKingdom, out bool isAtWarWithAnyKingdom)
		{
			isAtWarWithAlliedKingdom = querierKingdom.AlliedKingdoms.Any((Kingdom x) => x.IsAtWarWith(queriedKingdom));
			isAtWarWithAnyKingdom = isAtWarWithAlliedKingdom || Kingdom.All.Any((Kingdom x) => !x.IsEliminated && x != queriedKingdom && x != querierKingdom && x.IsAtWarWith(queriedKingdom));
			return 2.5f;
		}

		private float GetRelationEffectBetweenRulers(Kingdom querierKingdom, Kingdom queriedKingdom)
		{
			return (float)querierKingdom.Leader.GetRelation(queriedKingdom.Leader) * 0.1f;
		}

		private float GetProsperityEffect(Kingdom querierKingdom, Kingdom queriedKingdom, out float querierKingdomAverageProsperity, out float queriedKingdomAverageProsperity)
		{
			querierKingdomAverageProsperity = GetAverageProsperityOfTownsInKingdom(querierKingdom);
			queriedKingdomAverageProsperity = GetAverageProsperityOfTownsInKingdom(queriedKingdom);
			return (2500f - TaleWorlds.Library.MathF.Clamp(TaleWorlds.Library.MathF.Abs(queriedKingdomAverageProsperity - querierKingdomAverageProsperity), 0.1f, 2500f)) / 2500f * 45f;
		}

		private float GetAverageProsperityOfTownsInKingdom(Kingdom kingdom)
		{
			if (kingdom.Towns.Count > 0)
			{
				float num = 0f;
				for (int i = 0; i < kingdom.Towns.Count; i++)
				{
					num += kingdom.Towns[i].Prosperity;
				}
				return num / (float)kingdom.Towns.Count;
			}
			return 0f;
		}

		private float GetSecurityEffect(Kingdom queriedKingdom)
		{
			if (queriedKingdom.Towns.Count > 0)
			{
				float num = 0f;
				for (int i = 0; i < queriedKingdom.Towns.Count; i++)
				{
					num += queriedKingdom.Towns[i].Security;
				}
				return TaleWorlds.Library.MathF.Clamp((num / (float)queriedKingdom.Towns.Count - 85f) * 0.4f, -5f, 0f);
			}
			return 0f;
		}

		public override CampaignTime GetTradeAgreementDurationInYears(Kingdom iniatatingKingdom, Kingdom otherKingdom)
		{
			return CampaignTime.Years(1f);
		}

		private float GetExposureEffect(Kingdom querierKingdom, Kingdom queriedKingdom)
		{
			float result = 0f;
			if (queriedKingdom.Fiefs.Count > 0 && querierKingdom.Fiefs.Count > 0)
			{
				HashSet<Settlement> hashSet = new HashSet<Settlement>();
				int num = 0;
				int num2 = 0;
				foreach (Town fief in querierKingdom.Fiefs)
				{
					foreach (Settlement neighborFortification in fief.GetNeighborFortifications(MobileParty.NavigationType.All))
					{
						if (neighborFortification.IsFortification && !hashSet.Contains(neighborFortification) && neighborFortification.MapFaction != querierKingdom)
						{
							if (neighborFortification.MapFaction == queriedKingdom)
							{
								num2++;
							}
							num++;
							hashSet.Add(neighborFortification);
						}
					}
				}
				result = Math.Min((float)num2 / (float)num * 50f, 30f);
			}
			return result;
		}

		public override int GetProfitPerCaravanVisit(MobileParty mobileParty)
		{
			return 500;
		}
	}
	public class DefaultTradeItemPriceFactorModel : TradeItemPriceFactorModel
	{
		private const float MinPriceFactor = 0.1f;

		private const float MaxPriceFactor = 10f;

		private const float MinPriceFactorNonTrade = 0.8f;

		private const float MaxPriceFactorNonTrade = 1.3f;

		private const float HighTradePenaltyBaseValue = 1.5f;

		private const float PackAnimalTradePenalty = 0.8f;

		private const float MountTradePenalty = 0.8f;

		public override float GetTradePenalty(ItemObject item, MobileParty clientParty, PartyBase merchant, bool isSelling, float inStore, float supply, float demand)
		{
			Settlement settlement = merchant?.Settlement;
			float num = 0.06f;
			bool flag = clientParty?.IsCaravan ?? false;
			bool num2 = merchant != null && merchant.MobileParty?.IsCaravan == true;
			if (clientParty != null && merchant != null && clientParty.MapFaction.IsAtWarWith(merchant.MapFaction))
			{
				num += 0.5f;
			}
			if (!item.IsTradeGood && !item.IsAnimal && !item.HasHorseComponent && !flag && isSelling)
			{
				ExplainedNumber explainedNumber = new ExplainedNumber(1.5f + Math.Max(0f, item.Tierf - 1f) * 0.25f);
				if (item.IsCraftedWeapon && item.IsCraftedByPlayer && clientParty != null && clientParty.HasPerk(DefaultPerks.Crafting.ArtisanSmith))
				{
					explainedNumber.AddFactor(DefaultPerks.Crafting.ArtisanSmith.PrimaryBonus);
				}
				num += explainedNumber.ResultNumber;
			}
			if (item.HasHorseComponent && item.HorseComponent.IsPackAnimal && !flag && isSelling)
			{
				num += 0.8f;
			}
			if (item.HasHorseComponent && item.HorseComponent.IsMount && !flag && isSelling)
			{
				num += 0.8f;
			}
			if (settlement != null && settlement.IsVillage)
			{
				num += (isSelling ? 1f : 0.1f);
			}
			if (num2)
			{
				if (item.ItemCategory == DefaultItemCategories.PackAnimal && !isSelling)
				{
					num += 2f;
				}
				num += (isSelling ? 1f : 0.1f);
			}
			bool flag2 = clientParty == null;
			if (flag)
			{
				num *= 0.5f;
			}
			else if (flag2)
			{
				num *= 0.2f;
			}
			float num3 = ((clientParty != null) ? Campaign.Current.Models.PartyTradeModel.GetTradePenaltyFactor(clientParty) : 1f);
			num *= num3;
			ExplainedNumber stat = new ExplainedNumber(num);
			if (clientParty != null)
			{
				if (settlement != null && clientParty.MapFaction == settlement.MapFaction)
				{
					if (settlement.IsVillage)
					{
						PerkHelper.AddPerkBonusForParty(DefaultPerks.Scouting.VillageNetwork, clientParty, isPrimaryBonus: true, ref stat);
					}
					else if (settlement.IsTown)
					{
						PerkHelper.AddPerkBonusForParty(DefaultPerks.Scouting.RumourNetwork, clientParty, isPrimaryBonus: true, ref stat);
					}
				}
				if (item.IsTradeGood)
				{
					if (clientParty.HasPerk(DefaultPerks.Trade.WholeSeller) && isSelling)
					{
						PerkHelper.AddPerkBonusForParty(DefaultPerks.Trade.WholeSeller, clientParty, isPrimaryBonus: true, ref stat);
					}
					if (isSelling && item.IsFood && clientParty.LeaderHero != null)
					{
						PerkHelper.AddPerkBonusForCharacter(DefaultPerks.Trade.GranaryAccountant, clientParty.LeaderHero.CharacterObject, isPrimaryBonus: true, ref stat);
					}
				}
				else if (!item.IsTradeGood && clientParty.HasPerk(DefaultPerks.Trade.Appraiser) && isSelling)
				{
					PerkHelper.AddPerkBonusForParty(DefaultPerks.Trade.Appraiser, clientParty, isPrimaryBonus: true, ref stat);
				}
				if (PartyBaseHelper.HasFeat(clientParty.Party, DefaultCulturalFeats.AseraiTraderFeat))
				{
					stat.AddFactor(-0.1f);
				}
				if (item.WeaponComponent != null && isSelling)
				{
					PerkHelper.AddPerkBonusForParty(DefaultPerks.Roguery.ArmsDealer, clientParty, isPrimaryBonus: true, ref stat);
				}
				if (!isSelling && item.IsFood)
				{
					PerkHelper.AddPerkBonusForParty(DefaultPerks.Trade.InsurancePlans, clientParty, isPrimaryBonus: false, ref stat);
				}
				if (item.HorseComponent != null && item.HorseComponent.IsPackAnimal && clientParty.HasPerk(DefaultPerks.Steward.ArenicosMules, checkSecondaryRole: true))
				{
					PerkHelper.AddPerkBonusForParty(DefaultPerks.Steward.ArenicosMules, clientParty, isPrimaryBonus: false, ref stat);
				}
				if (item.IsMountable)
				{
					if (clientParty.HasPerk(DefaultPerks.Riding.DeeperSacks, checkSecondaryRole: true))
					{
						stat.AddFactor(DefaultPerks.Riding.DeeperSacks.SecondaryBonus, DefaultPerks.Riding.DeeperSacks.Name);
					}
					if (clientParty.LeaderHero != null && clientParty.LeaderHero.GetPerkValue(DefaultPerks.Steward.ArenicosHorses))
					{
						PerkHelper.AddPerkBonusForCharacter(DefaultPerks.Steward.ArenicosHorses, clientParty.LeaderHero.CharacterObject, isPrimaryBonus: false, ref stat);
					}
				}
				if (clientParty.IsMainParty && Hero.MainHero.GetPerkValue(DefaultPerks.Roguery.SmugglerConnections) && merchant?.MapFaction != null && merchant.MapFaction.MainHeroCrimeRating > 0f)
				{
					PerkHelper.AddPerkBonusForParty(DefaultPerks.Roguery.SmugglerConnections, clientParty, isPrimaryBonus: false, ref stat);
				}
				if (!isSelling && merchant != null && merchant.IsSettlement && merchant.Settlement.IsVillage && clientParty.HasPerk(DefaultPerks.Trade.DistributedGoods, checkSecondaryRole: true))
				{
					PerkHelper.AddPerkBonusForParty(DefaultPerks.Trade.DistributedGoods, clientParty, isPrimaryBonus: false, ref stat);
				}
				if (isSelling && item.HasHorseComponent && clientParty.HasPerk(DefaultPerks.Trade.LocalConnection, checkSecondaryRole: true))
				{
					stat.AddFactor(DefaultPerks.Trade.LocalConnection.SecondaryBonus, DefaultPerks.Trade.LocalConnection.Name);
				}
				if (isSelling && (item.ItemCategory == DefaultItemCategories.Pottery || item.ItemCategory == DefaultItemCategories.Tools || item.ItemCategory == DefaultItemCategories.Jewelry || item.ItemCategory == DefaultItemCategories.Cotton) && clientParty.LeaderHero != null)
				{
					PerkHelper.AddPerkBonusForCharacter(DefaultPerks.Trade.TradeyardForeman, clientParty.LeaderHero.CharacterObject, isPrimaryBonus: true, ref stat);
				}
				if (!isSelling && (item.ItemCategory == DefaultItemCategories.Clay || item.ItemCategory == DefaultItemCategories.Iron || item.ItemCategory == DefaultItemCategories.Silver || item.ItemCategory == DefaultItemCategories.Cotton) && clientParty.HasPerk(DefaultPerks.Trade.RapidDevelopment))
				{
					PerkHelper.AddPerkBonusForParty(DefaultPerks.Trade.RapidDevelopment, clientParty, isPrimaryBonus: false, ref stat);
				}
			}
			return stat.ResultNumber;
		}

		private float GetPriceFactor(ItemObject item, MobileParty tradingParty, PartyBase merchant, float inStoreValue, float supply, float demand, bool isSelling)
		{
			float basePriceFactor = GetBasePriceFactor(item.GetItemCategory(), inStoreValue, supply, demand, isSelling, item.Value);
			float tradePenalty = GetTradePenalty(item, tradingParty, merchant, isSelling, inStoreValue, supply, demand);
			if (!isSelling)
			{
				return basePriceFactor * (1f + tradePenalty);
			}
			return basePriceFactor * 1f / (1f + tradePenalty);
		}

		public override float GetBasePriceFactor(ItemCategory itemCategory, float inStoreValue, float supply, float demand, bool isSelling, int transferValue)
		{
			if (isSelling)
			{
				inStoreValue += (float)transferValue;
			}
			float value = TaleWorlds.Library.MathF.Pow(demand / (0.1f * supply + inStoreValue * 0.04f + 2f), itemCategory.IsAnimal ? 0.3f : 0.6f);
			if (itemCategory.IsTradeGood)
			{
				return TaleWorlds.Library.MathF.Clamp(value, 0.1f, 10f);
			}
			return TaleWorlds.Library.MathF.Clamp(value, 0.8f, 1.3f);
		}

		public override int GetPrice(EquipmentElement itemRosterElement, MobileParty clientParty, PartyBase merchant, bool isSelling, float inStoreValue, float supply, float demand)
		{
			float priceFactor = GetPriceFactor(itemRosterElement.Item, clientParty, merchant, inStoreValue, supply, demand, isSelling);
			float f = (float)itemRosterElement.ItemValue * priceFactor;
			int num = (isSelling ? TaleWorlds.Library.MathF.Floor(f) : TaleWorlds.Library.MathF.Ceiling(f));
			if (!isSelling && merchant?.MobileParty != null && merchant.MobileParty.IsCaravan && clientParty.HasPerk(DefaultPerks.Trade.SilverTongue, checkSecondaryRole: true))
			{
				num = TaleWorlds.Library.MathF.Ceiling((float)num * (1f - DefaultPerks.Trade.SilverTongue.SecondaryBonus));
			}
			return TaleWorlds.Library.MathF.Max(num, 1);
		}

		public override int GetTheoreticalMaxItemMarketValue(ItemObject item)
		{
			if (item.IsTradeGood || item.IsAnimal)
			{
				return TaleWorlds.Library.MathF.Round((float)item.Value * 10f);
			}
			return TaleWorlds.Library.MathF.Round((float)item.Value * 1.3f);
		}
	}
	public class DefaultTroopSacrificeModel : TroopSacrificeModel
	{
		public const int MinimumNumberOfTroopsRequiredForGetAway = 8;

		public override int BreakOutArmyLeaderRelationPenalty => -5;

		public override int BreakOutArmyMemberRelationPenalty => -1;

		public override ExplainedNumber GetLostTroopCountForBreakingInBesiegedSettlement(MobileParty party, SiegeEvent siegeEvent)
		{
			return GetLostTroopCount(party, siegeEvent, party.IsTargetingPort && party.IsCurrentlyAtSea);
		}

		public override ExplainedNumber GetLostTroopCountForBreakingOutOfBesiegedSettlement(MobileParty party, SiegeEvent siegeEvent, bool isBreakingOutFromPort)
		{
			return GetLostTroopCount(party, siegeEvent, isBreakingOutFromPort);
		}

		public override int GetNumberOfTroopsSacrificedForTryingToGetAway(BattleSideEnum playerBattleSide, MapEvent mapEvent)
		{
			mapEvent.RecalculateStrengthOfSides();
			MapEventSide mapEventSide = mapEvent.GetMapEventSide(playerBattleSide);
			float num = mapEvent.StrengthOfSide[(int)playerBattleSide] + 1f;
			float a = mapEvent.StrengthOfSide[(int)playerBattleSide.GetOppositeSide()] / num;
			int num2 = PartyBase.MainParty.NumberOfRegularMembers;
			if (MobileParty.MainParty.Army != null)
			{
				foreach (MobileParty attachedParty in MobileParty.MainParty.Army.LeaderParty.AttachedParties)
				{
					num2 += attachedParty.Party.NumberOfRegularMembers;
				}
			}
			int num3 = mapEventSide.CountTroops((FlattenedTroopRosterElement x) => x.State == RosterTroopState.Active && !x.Troop.IsHero);
			float baseNumber = (float)num2 * TaleWorlds.Library.MathF.Pow(TaleWorlds.Library.MathF.Min(a, 3f), 1.3f) * 0.1f + 5f;
			ExplainedNumber explainedNumber = new ExplainedNumber(baseNumber);
			SkillHelper.AddSkillBonusForCharacter(DefaultSkillEffects.TacticsTroopSacrificeReduction, CharacterObject.PlayerCharacter, ref explainedNumber);
			explainedNumber = new ExplainedNumber(TaleWorlds.Library.MathF.Max(1, TaleWorlds.Library.MathF.Round(explainedNumber.ResultNumber)));
			if (!MobileParty.MainParty.IsCurrentlyAtSea)
			{
				PerkHelper.AddPerkBonusForParty(DefaultPerks.Tactics.SwiftRegroup, MobileParty.MainParty, isPrimaryBonus: false, ref explainedNumber);
			}
			if (explainedNumber.ResultNumber <= (float)num3)
			{
				return TaleWorlds.Library.MathF.Round(explainedNumber.ResultNumber);
			}
			return -1;
		}

		private ExplainedNumber GetLostTroopCount(MobileParty party, SiegeEvent siegeEvent, bool isFromPort)
		{
			if (isFromPort && !siegeEvent.IsBlockadeActive)
			{
				return new ExplainedNumber(0f, includeDescriptions: false, null);
			}
			int num = 5;
			float num2 = 0f;
			foreach (PartyBase item in siegeEvent.BesiegerCamp.GetInvolvedPartiesForEventType())
			{
				num2 += (isFromPort ? item.GetCustomStrength(BattleSideEnum.Attacker, MapEvent.PowerCalculationContext.SeaBattle) : item.GetCustomStrength(BattleSideEnum.Attacker, MapEvent.PowerCalculationContext.PlainBattle));
			}
			float num3;
			int num4;
			if (party.Army != null && party.Army.LeaderParty == party)
			{
				num3 = (isFromPort ? party.Army.LeaderParty.Party.GetCustomStrength(BattleSideEnum.Defender, MapEvent.PowerCalculationContext.SeaBattle) : party.Army.LeaderParty.Party.GetCustomStrength(BattleSideEnum.Defender, MapEvent.PowerCalculationContext.PlainBattle));
				foreach (MobileParty attachedParty in party.Army.LeaderParty.AttachedParties)
				{
					num3 += (isFromPort ? attachedParty.Party.GetCustomStrength(BattleSideEnum.Defender, MapEvent.PowerCalculationContext.SeaBattle) : attachedParty.Party.GetCustomStrength(BattleSideEnum.Defender, MapEvent.PowerCalculationContext.PlainBattle));
				}
				num4 = party.Army.TotalRegularCount;
			}
			else
			{
				num3 = (isFromPort ? party.Party.GetCustomStrength(BattleSideEnum.Defender, MapEvent.PowerCalculationContext.SeaBattle) : party.Party.GetCustomStrength(BattleSideEnum.Defender, MapEvent.PowerCalculationContext.PlainBattle));
				num4 = party.MemberRoster.TotalRegulars;
			}
			float num5 = TaleWorlds.Library.MathF.Clamp(0.12f * TaleWorlds.Library.MathF.Pow((num2 + 1f) / (num3 + 1f), 0.25f), 0.12f, 0.24f);
			ExplainedNumber explainedNumber = new ExplainedNumber(num5 * (float)num4);
			SkillHelper.AddSkillBonusForCharacter(DefaultSkillEffects.TacticsTroopSacrificeReduction, CharacterObject.PlayerCharacter, ref explainedNumber);
			explainedNumber = new ExplainedNumber(num + (int)explainedNumber.ResultNumber);
			PerkHelper.AddPerkBonusForParty(DefaultPerks.Tactics.Improviser, MobileParty.MainParty, isPrimaryBonus: false, ref explainedNumber, isFromPort);
			return explainedNumber;
		}

		public override bool CanPlayerGetAwayFromEncounter(out TextObject explanation)
		{
			explanation = TextObject.GetEmpty();
			int num = PartyBase.MainParty.NumberOfHealthyMembers - PartyBase.MainParty.MemberRoster.TotalHeroes;
			if (MobileParty.MainParty.Army != null && (MobileParty.MainParty.Army.LeaderParty == MobileParty.MainParty || MobileParty.MainParty.AttachedTo != null))
			{
				foreach (MobileParty attachedParty in MobileParty.MainParty.Army.LeaderParty.AttachedParties)
				{
					num += attachedParty.Party.NumberOfHealthyMembers - attachedParty.Party.MemberRoster.TotalHeroes;
				}
			}
			if (num <= 8 || Campaign.Current.Models.TroopSacrificeModel.GetNumberOfTroopsSacrificedForTryingToGetAway(PlayerEncounter.Current.PlayerSide, PlayerEncounter.Battle) == -1)
			{
				explanation = new TextObject("{=MTbOGRCF}You don't have enough men!");
				return false;
			}
			return true;
		}

		public override void GetShipsToSacrificeForTryingToGetAway(BattleSideEnum playerBattleSide, MapEvent mapEvent, out MBList<Ship> shipsToCapture, out Ship shipToTakeDamage, out float damageToApplyForLastShip)
		{
			shipsToCapture = new MBList<Ship>();
			shipToTakeDamage = null;
			damageToApplyForLastShip = 0f;
		}
	}
	public class DefaultTroopSupplierProbabilityModel : TroopSupplierProbabilityModel
	{
		public override void EnqueueTroopSpawnProbabilitiesAccordingToUnitSpawnPrioritization(MapEventParty battleParty, FlattenedTroopRoster priorityTroops, bool includePlayer, int sizeOfSide, bool forcePriorityTroops, List<(FlattenedTroopRosterElement, MapEventParty, float)> priorityList)
		{
			UnitSpawnPrioritizations unitSpawnPrioritizations = UnitSpawnPrioritizations.HighLevel;
			bool flag = PlayerEncounter.Battle?.IsSiegeAmbush ?? false;
			if (battleParty.Party == PartyBase.MainParty && !flag)
			{
				unitSpawnPrioritizations = Game.Current.UnitSpawnPrioritization;
			}
			if (includePlayer)
			{
				List<KeyValuePair<int, FlattenedTroopRosterElement>> list = new List<KeyValuePair<int, FlattenedTroopRosterElement>>();
				List<KeyValuePair<int, FlattenedTroopRosterElement>> list2 = new List<KeyValuePair<int, FlattenedTroopRosterElement>>();
				List<KeyValuePair<int, FlattenedTroopRosterElement>> list3 = new List<KeyValuePair<int, FlattenedTroopRosterElement>>();
				List<KeyValuePair<int, FlattenedTroopRosterElement>> list4 = new List<KeyValuePair<int, FlattenedTroopRosterElement>>();
				int[] array = new int[8];
				for (int i = 0; i < 8; i++)
				{
					array[i] = 0;
				}
				int num = 0;
				foreach (FlattenedTroopRosterElement troop in battleParty.Troops)
				{
					if (CanTroopJoinBattle(troop, includePlayer))
					{
						int key = 0;
						switch (unitSpawnPrioritizations)
						{
						case UnitSpawnPrioritizations.Default:
							key = -num;
							break;
						case UnitSpawnPrioritizations.HighLevel:
							key = troop.Troop.Level;
							break;
						case UnitSpawnPrioritizations.LowLevel:
							key = -troop.Troop.Level;
							break;
						case UnitSpawnPrioritizations.Homogeneous:
						{
							int formationClass = (int)troop.Troop.GetFormationClass();
							key = -array[formationClass];
							array[formationClass]++;
							break;
						}
						}
						bool isHero = troop.Troop.IsHero;
						if (isHero && troop.Troop.IsPlayerCharacter)
						{
							key = int.MaxValue;
						}
						bool flag2 = false;
						if (priorityTroops != null)
						{
							foreach (FlattenedTroopRosterElement priorityTroop in priorityTroops)
							{
								if (priorityTroop.Troop == troop.Troop)
								{
									flag2 = true;
									break;
								}
							}
						}
						if (flag2)
						{
							priorityTroops.Remove(priorityTroops.FindIndexOfCharacter(troop.Troop));
							if (isHero)
							{
								list3.Add(new KeyValuePair<int, FlattenedTroopRosterElement>(key, troop));
							}
							else
							{
								list4.Add(new KeyValuePair<int, FlattenedTroopRosterElement>(key, troop));
							}
						}
						else if (isHero)
						{
							list2.Add(new KeyValuePair<int, FlattenedTroopRosterElement>(key, troop));
						}
						else
						{
							list.Add(new KeyValuePair<int, FlattenedTroopRosterElement>(key, troop));
						}
					}
					num++;
				}
				if (unitSpawnPrioritizations == UnitSpawnPrioritizations.Homogeneous)
				{
					for (int j = 0; j < list.Count; j++)
					{
						KeyValuePair<int, FlattenedTroopRosterElement> keyValuePair = list[j];
						int formationClass2 = (int)keyValuePair.Value.Troop.GetFormationClass();
						int key2 = keyValuePair.Key * list.Count / array[formationClass2];
						list[j] = new KeyValuePair<int, FlattenedTroopRosterElement>(key2, keyValuePair.Value);
					}
				}
				list3 = list3.OrderByQ((KeyValuePair<int, FlattenedTroopRosterElement> x) => x.Key).ToList();
				list4 = list4.OrderByQ((KeyValuePair<int, FlattenedTroopRosterElement> x) => x.Key).ToList();
				list2 = list2.OrderByQ((KeyValuePair<int, FlattenedTroopRosterElement> x) => x.Key).ToList();
				list = list.OrderByQ((KeyValuePair<int, FlattenedTroopRosterElement> x) => x.Key).ToList();
				for (int k = 0; k < list3.Count; k++)
				{
					priorityList.Add((list3[k].Value, battleParty, 3f + (float)(k + 1) / (float)list3.Count));
				}
				for (int l = 0; l < list4.Count; l++)
				{
					priorityList.Add((list4[l].Value, battleParty, 2f + (float)(l + 1) / (float)list4.Count));
				}
				for (int m = 0; m < list2.Count; m++)
				{
					priorityList.Add((list2[m].Value, battleParty, 1f + (float)(m + 1) / (float)list2.Count));
				}
				for (int n = 0; n < list.Count; n++)
				{
					priorityList.Add((list[n].Value, battleParty, (float)(n + 1) / (float)list.Count));
				}
				return;
			}
			foreach (FlattenedTroopRosterElement troop2 in battleParty.Troops)
			{
				if (CanTroopJoinBattle(troop2, includePlayer))
				{
					priorityList.Add((troop2, battleParty, 2.1474836E+09f));
				}
			}
		}

		private bool CanTroopJoinBattle(FlattenedTroopRosterElement troopRoster, bool includePlayer)
		{
			if (!troopRoster.IsWounded && !troopRoster.IsRouted && !troopRoster.IsKilled)
			{
				if (!includePlayer)
				{
					return !troopRoster.Troop.IsPlayerCharacter;
				}
				return true;
			}
			return false;
		}
	}
	public class DefaultValuationModel : ValuationModel
	{
		public override float GetMilitaryValueOfParty(MobileParty party)
		{
			return party.Party.CalculateCurrentStrength() * 15f;
		}

		public override float GetValueOfTroop(CharacterObject troop)
		{
			return troop.GetPower() * 15f;
		}

		public override float GetValueOfHero(Hero hero)
		{
			if (hero.Clan != null)
			{
				return ((float)hero.Clan.Gold * 0.15f + (float)((1 + hero.Clan.Tier * hero.Clan.Tier) * 500)) * ((hero.Clan.Leader == hero) ? 4f : 1f);
			}
			return 500f;
		}
	}
	public class DefaultVassalRewardsModel : VassalRewardsModel
	{
		private const int VassalRewardBannerLevel = 2;

		public override int RelationRewardWithLeader => 10;

		public override float InfluenceReward => 10f;

		public override ItemRoster GetEquipmentRewardsForJoiningKingdom(Kingdom kingdom)
		{
			ItemRoster itemRoster = new ItemRoster();
			foreach (ItemObject vassalRewardItem in kingdom.Culture.VassalRewardItems)
			{
				itemRoster.AddToCounts(vassalRewardItem, 1);
			}
			ItemObject randomBannerAtLevel = GetRandomBannerAtLevel(2, kingdom.Culture);
			if (randomBannerAtLevel != null)
			{
				itemRoster.AddToCounts(randomBannerAtLevel, 1);
			}
			return itemRoster;
		}

		private ItemObject GetRandomBannerAtLevel(int bannerLevel, CultureObject culture = null)
		{
			MBList<ItemObject> e = Campaign.Current.Models.BannerItemModel.GetPossibleRewardBannerItems().ToMBList();
			if (culture == null)
			{
				return e.GetRandomElementWithPredicate((ItemObject i) => (i.ItemComponent as BannerComponent).BannerLevel == bannerLevel);
			}
			return e.GetRandomElementWithPredicate((ItemObject i) => (i.ItemComponent as BannerComponent).BannerLevel == bannerLevel && i.Culture == culture);
		}

		public override TroopRoster GetTroopRewardsForJoiningKingdom(Kingdom kingdom)
		{
			TroopRoster troopRoster = TroopRoster.CreateDummyTroopRoster();
			foreach (PartyTemplateStack stack in kingdom.Culture.VassalRewardTroopsPartyTemplate.Stacks)
			{
				troopRoster.AddToCounts(stack.Character, stack.MaxValue);
			}
			return troopRoster;
		}
	}
	public class DefaultVillageProductionCalculatorModel : VillageProductionCalculatorModel
	{
		private readonly TextObject _cultureEffect = GameTexts.FindText("str_culture");

		public override ExplainedNumber CalculateDailyProductionAmount(Village village, ItemObject item)
		{
			ExplainedNumber bonuses = new ExplainedNumber(0f, includeDescriptions: false, null);
			if (village.VillageState == Village.VillageStates.Normal)
			{
				foreach (var production in village.VillageType.Productions)
				{
					var (itemObject, num) = production;
					if (itemObject != item)
					{
						continue;
					}
					if (village.TradeBound != null)
					{
						float num2 = (float)(village.GetHearthLevel() + 1) * 0.5f;
						if (item.IsMountable && item.Tier == ItemObject.ItemTiers.Tier2 && PerkHelper.GetPerkValueForTown(DefaultPerks.Riding.Shepherd, village.TradeBound.Town) && MBRandom.RandomFloat < DefaultPerks.Riding.Shepherd.SecondaryBonus)
						{
							num += 1f;
						}
						bonuses.Add(num * num2);
						if (item.ItemCategory == DefaultItemCategories.Grain || item.ItemCategory == DefaultItemCategories.Olives || item.ItemCategory == DefaultItemCategories.Fish || item.ItemCategory == DefaultItemCategories.DateFruit)
						{
							PerkHelper.AddPerkBonusForTown(DefaultPerks.Trade.GranaryAccountant, village.TradeBound.Town, ref bonuses);
						}
						else if (item.ItemCategory == DefaultItemCategories.Clay || item.ItemCategory == DefaultItemCategories.Iron || item.ItemCategory == DefaultItemCategories.Cotton || item.ItemCategory == DefaultItemCategories.Silver)
						{
							PerkHelper.AddPerkBonusForTown(DefaultPerks.Trade.TradeyardForeman, village.TradeBound.Town, ref bonuses);
						}
						if (item.IsTradeGood)
						{
							PerkHelper.AddPerkBonusForTown(DefaultPerks.Athletics.Steady, village.TradeBound.Town, ref bonuses);
						}
						if (item.IsAnimal)
						{
							PerkHelper.AddPerkBonusForTown(DefaultPerks.Medicine.PerfectHealth, village.TradeBound.Town, ref bonuses);
						}
						PerkHelper.AddPerkBonusForTown(DefaultPerks.Riding.Breeder, village.TradeBound.Town, ref bonuses);
					}
					if ((item.ItemCategory == DefaultItemCategories.Sheep || item.ItemCategory == DefaultItemCategories.Cow || item.ItemCategory == DefaultItemCategories.WarHorse || item.ItemCategory == DefaultItemCategories.Horse || item.ItemCategory == DefaultItemCategories.PackAnimal) && village.Settlement.OwnerClan.Culture.HasFeat(DefaultCulturalFeats.KhuzaitAnimalProductionFeat))
					{
						bonuses.AddFactor(DefaultCulturalFeats.KhuzaitAnimalProductionFeat.EffectBonus, _cultureEffect);
					}
					if (item.ItemCategory == DefaultItemCategories.Grain && village.Settlement.OwnerClan.Culture.HasFeat(DefaultCulturalFeats.SturgianGrainProductionFeat))
					{
						bonuses.AddFactor(DefaultCulturalFeats.SturgianGrainProductionFeat.EffectBonus, _cultureEffect);
					}
					if (village.Bound.IsFortification)
					{
						village.Bound.Town.AddEffectOfBuildings(BuildingEffectEnum.VillageProduction, ref bonuses);
					}
					if (village.Bound.IsCastle && village.Settlement.OwnerClan.Culture.HasFeat(DefaultCulturalFeats.VlandianCastleVillageProductionFeat))
					{
						bonuses.AddFactor(DefaultCulturalFeats.VlandianCastleVillageProductionFeat.EffectBonus, _cultureEffect);
					}
				}
			}
			return bonuses;
		}

		public override float CalculateDailyFoodProductionAmount(Village village)
		{
			if (village.VillageState != 0)
			{
				return 0f;
			}
			float num = village.GetHearthLevel() + 1;
			if (GetIssueEffectOnFoodProduction(village.Settlement, out var issueEffect))
			{
				num *= issueEffect;
			}
			return num;
		}

		private bool GetIssueEffectOnFoodProduction(Settlement settlement, out float issueEffect)
		{
			issueEffect = 1f;
			if (settlement.IsVillage)
			{
				foreach (Hero item in SettlementHelper.GetAllHeroesOfSettlement(settlement, includePrisoners: false))
				{
					if (item.Issue != null && item.MapFaction == settlement.MapFaction)
					{
						float activeIssueEffectAmount = item.Issue.GetActiveIssueEffectAmount(DefaultIssueEffects.HalfVillageProduction);
						if (activeIssueEffectAmount != 0f)
						{
							issueEffect *= activeIssueEffectAmount;
						}
					}
				}
			}
			return !issueEffect.ApproximatelyEqualsTo(1f);
		}

		public override float CalculateProductionSpeedOfItemCategory(ItemCategory item)
		{
			float num = 0f;
			foreach (VillageType item2 in VillageType.All)
			{
				float productionPerDay = item2.GetProductionPerDay(item);
				if (productionPerDay > num)
				{
					num = productionPerDay;
				}
			}
			return num;
		}
	}
	public class DefaultVillageTradeModel : VillageTradeModel
	{
		public override float TradeBoundDistanceLimitAsDays(MobileParty.NavigationType navigationType)
		{
			return Campaign.Current.GetAverageDistanceBetweenClosestTwoTownsWithNavigationType(navigationType) * 3f / (Campaign.Current.EstimatedAverageVillagerPartySpeed * (float)CampaignTime.HoursInDay);
		}

		public override Settlement GetTradeBoundToAssignForVillage(Village village)
		{
			MobileParty.NavigationType navigationType = MobileParty.NavigationType.Default;
			Settlement settlement = SettlementHelper.FindNearestSettlementToSettlement(village.Settlement, navigationType, (Settlement x) => x.IsTown && x.Town.MapFaction == village.Settlement.MapFaction);
			float distanceLimit = Campaign.Current.Models.VillageTradeModel.TradeBoundDistanceLimitAsDays(navigationType) * Campaign.Current.EstimatedAverageVillagerPartySpeed * (float)CampaignTime.HoursInDay;
			if (settlement != null && Campaign.Current.Models.MapDistanceModel.GetDistance(settlement, village.Settlement, isFromPort: false, isTargetingPort: false, navigationType) < distanceLimit)
			{
				return settlement;
			}
			Settlement settlement2 = SettlementHelper.FindNearestSettlementToSettlement(village.Settlement, navigationType, (Settlement x) => x.IsTown && x.Town.MapFaction != village.Settlement.MapFaction && !x.Town.MapFaction.IsAtWarWith(village.Settlement.MapFaction) && Campaign.Current.Models.MapDistanceModel.GetDistance(x, village.Settlement, isFromPort: false, isTargetingPort: false, navigationType) <= distanceLimit);
			if (settlement2 != null && Campaign.Current.Models.MapDistanceModel.GetDistance(settlement2, village.Settlement, isFromPort: false, isTargetingPort: false, navigationType) < distanceLimit)
			{
				return settlement2;
			}
			return null;
		}
	}
	public class DefaultVoiceOverModel : VoiceOverModel
	{
		private const string ImperialHighClass = "imperial_high";

		private const string ImperialLowClass = "imperial_low";

		private const string VlandianClass = "vlandian";

		private const string SturgianClass = "sturgian";

		private const string KhuzaitClass = "khuzait";

		private const string AseraiClass = "aserai";

		private const string BattanianClass = "battanian";

		private const string ForestBanditClass = "forest_bandits";

		private const string SeaBanditClass = "sea_raiders";

		private const string MountainBanditClass = "mountain_bandits";

		private const string DesertBanditClass = "desert_bandits";

		private const string SteppeBanditClass = "steppe_bandits";

		private const string LootersClass = "looters";

		private const string Male = "male";

		private const string Female = "female";

		private const string GenericPersonaId = "generic";

		public override string GetSoundPathForCharacter(CharacterObject character, VoiceObject voiceObject)
		{
			if (voiceObject == null)
			{
				return "";
			}
			string text = "";
			string value = character.StringId + "_" + (CharacterObject.PlayerCharacter.IsFemale ? "female" : "male");
			foreach (string voicePath in voiceObject.VoicePaths)
			{
				if (voicePath.Contains(value))
				{
					text = voicePath;
					break;
				}
				if (voicePath.Contains(character.StringId + "_"))
				{
					text = voicePath;
				}
			}
			if (string.IsNullOrEmpty(text))
			{
				string accentClass = Campaign.Current.Models.VoiceOverModel.GetAccentClass(character.Culture, ConversationTagHelper.UsesHighRegister(character));
				TaleWorlds.Library.Debug.Print("accentClass: " + accentClass);
				string text2 = (character.IsFemale ? "female" : "male");
				string stringId = character.GetPersona().StringId;
				List<string> possibleVoicePaths = new List<string>();
				List<string> list = new List<string>();
				list.Add(".+\\\\" + accentClass + "_" + text2 + "_" + stringId + "_.+");
				list.Add(".+\\\\" + accentClass + "_" + text2 + "_generic_.+");
				CheckPossibleMatches(voiceObject, list, ref possibleVoicePaths);
				if (possibleVoicePaths.IsEmpty())
				{
					list.Clear();
					list.Add(".+\\\\" + accentClass + "_" + stringId + "_.+");
					list.Add(".+\\\\" + accentClass + "_generic_.+");
					list.Add(".+\\\\" + text2 + "_" + stringId + "_.+");
					list.Add(".+\\\\" + text2 + "_generic_.+");
					CheckPossibleMatches(voiceObject, list, ref possibleVoicePaths);
					if (possibleVoicePaths.IsEmpty())
					{
						list.Clear();
						list.Add(".+\\\\" + stringId + "_.+");
						list.Add(".+\\\\generic_.+");
						list.Add(".+" + accentClass + "_.+");
						CheckPossibleMatches(voiceObject, list, ref possibleVoicePaths, doubleCheckForGender: true, character.IsFemale);
					}
				}
				if (!possibleVoicePaths.IsEmpty())
				{
					text = (character.IsHero ? possibleVoicePaths[character.HeroObject.RandomInt(possibleVoicePaths.Count)] : ((MobileParty.ConversationParty == null) ? possibleVoicePaths.GetRandomElement() : possibleVoicePaths[MobileParty.ConversationParty.RandomInt(possibleVoicePaths.Count)]));
				}
			}
			if (string.IsNullOrEmpty(text))
			{
				return "";
			}
			TaleWorlds.Library.Debug.Print("[VOICEOVER]Sound path found: " + BasePath.Name + text);
			text = text.Replace("$PLATFORM", "PC");
			return text + ".ogg";
		}

		private void CheckPossibleMatches(VoiceObject voiceObject, List<string> possibleMatches, ref List<string> possibleVoicePaths, bool doubleCheckForGender = false, bool isFemale = false)
		{
			foreach (string possibleMatch in possibleMatches)
			{
				Regex regex = new Regex(possibleMatch, RegexOptions.IgnoreCase);
				foreach (string voicePath in voiceObject.VoicePaths)
				{
					if (!regex.Match(voicePath).Success || possibleVoicePaths.Contains(voicePath))
					{
						continue;
					}
					if (doubleCheckForGender)
					{
						if (voicePath.Contains("_male") || voicePath.Contains("_female"))
						{
							string value = (isFemale ? "_female" : "_male");
							if (voicePath.Contains(value))
							{
								possibleVoicePaths.Add(voicePath);
							}
						}
					}
					else
					{
						possibleVoicePaths.Add(voicePath);
					}
				}
			}
		}

		public override string GetAccentClass(CultureObject culture, bool isHighClass)
		{
			if (culture.StringId == "empire")
			{
				if (isHighClass)
				{
					return "imperial_high";
				}
				return "imperial_low";
			}
			if (culture.StringId == "vlandia")
			{
				return "vlandian";
			}
			if (culture.StringId == "sturgia")
			{
				return "sturgian";
			}
			if (culture.StringId == "khuzait")
			{
				return "khuzait";
			}
			if (culture.StringId == "aserai")
			{
				return "aserai";
			}
			if (culture.StringId == "battania")
			{
				return "battanian";
			}
			if (culture.StringId == "forest_bandits")
			{
				return "forest_bandits";
			}
			if (culture.StringId == "sea_raiders")
			{
				return "sea_raiders";
			}
			if (culture.StringId == "mountain_bandits")
			{
				return "mountain_bandits";
			}
			if (culture.StringId == "desert_bandits")
			{
				return "desert_bandits";
			}
			if (culture.StringId == "steppe_bandits")
			{
				return "steppe_bandits";
			}
			if (culture.StringId == "looters")
			{
				return "looters";
			}
			return "";
		}
