	public class DefaultVolunteerModel : VolunteerModel
	{
		public override int MaxVolunteerTier => 4;

		public override int MaximumIndexHeroCanRecruitFromHero(Hero buyerHero, Hero sellerHero, int useValueAsRelation = -101)
		{
			int num = MaximumIndexCanPartyRecruitFromHeroInternal(buyerHero, sellerHero);
			int num2 = ((useValueAsRelation < -100) ? buyerHero.GetRelation(sellerHero) : useValueAsRelation);
			int num3 = ((num2 >= 100) ? 7 : ((num2 >= 80) ? 6 : ((num2 >= 60) ? 5 : ((num2 >= 40) ? 4 : ((num2 >= 20) ? 3 : ((num2 >= 10) ? 2 : ((num2 >= 5) ? 1 : ((num2 < 0) ? (-1) : 0))))))));
			int num4 = ((sellerHero.CurrentSettlement != null && buyerHero.MapFaction == sellerHero.CurrentSettlement.MapFaction) ? 1 : 0);
			int num5 = ((buyerHero != Hero.MainHero) ? 1 : 0);
			int num6 = ((sellerHero.CurrentSettlement != null && buyerHero.MapFaction.IsAtWarWith(sellerHero.CurrentSettlement.MapFaction)) ? (-(1 + num5)) : 0);
			if (buyerHero.IsMinorFactionHero && sellerHero.CurrentSettlement != null && sellerHero.CurrentSettlement.IsVillage)
			{
				num6 = 0;
			}
			int num7 = 0;
			if (sellerHero.IsMerchant && buyerHero.GetPerkValue(DefaultPerks.Trade.ArtisanCommunity))
			{
				num7 += (int)DefaultPerks.Trade.ArtisanCommunity.SecondaryBonus;
			}
			if (sellerHero.Culture == buyerHero.Culture && buyerHero.GetPerkValue(DefaultPerks.Leadership.CombatTips))
			{
				num7 += (int)DefaultPerks.Leadership.CombatTips.SecondaryBonus;
			}
			if (sellerHero.IsRuralNotable && buyerHero.GetPerkValue(DefaultPerks.Charm.Firebrand))
			{
				num7 += (int)DefaultPerks.Charm.Firebrand.SecondaryBonus;
			}
			if (sellerHero.IsUrbanNotable && buyerHero.GetPerkValue(DefaultPerks.Charm.FlexibleEthics))
			{
				num7 += (int)DefaultPerks.Charm.FlexibleEthics.SecondaryBonus;
			}
			if (sellerHero.IsArtisan && buyerHero.PartyBelongedTo != null && buyerHero.PartyBelongedTo.EffectiveEngineer != null && buyerHero.PartyBelongedTo.EffectiveEngineer.GetPerkValue(DefaultPerks.Engineering.EngineeringGuilds))
			{
				num7 += (int)DefaultPerks.Engineering.EngineeringGuilds.PrimaryBonus;
			}
			return TaleWorlds.Library.MathF.Min(6, num + num3 + num4 + num5 + num6 + num7);
		}

		public override int MaximumIndexGarrisonCanRecruitFromHero(Settlement settlement, Hero sellerHero)
		{
			return MaximumIndexCanPartyRecruitFromHeroInternal(settlement.Owner, sellerHero);
		}

		private int MaximumIndexCanPartyRecruitFromHeroInternal(Hero buyerHero, Hero sellerHero)
		{
			Settlement currentSettlement = sellerHero.CurrentSettlement;
			int num = 1;
			int num2 = ((buyerHero == Hero.MainHero) ? Campaign.Current.Models.DifficultyModel.GetPlayerRecruitSlotBonus() : 0);
			int num3 = 0;
			if (sellerHero.IsGangLeader && currentSettlement != null && currentSettlement.OwnerClan == buyerHero.Clan)
			{
				if (currentSettlement.IsTown)
				{
					Hero governor = currentSettlement.Town.Governor;
					if (governor != null && governor.GetPerkValue(DefaultPerks.Roguery.OneOfTheFamily))
					{
						goto IL_009a;
					}
				}
				if (currentSettlement.IsVillage)
				{
					Hero governor2 = currentSettlement.Village.Bound.Town.Governor;
					if (governor2 != null && governor2.GetPerkValue(DefaultPerks.Roguery.OneOfTheFamily))
					{
						goto IL_009a;
					}
				}
			}
			goto IL_00a8;
			IL_009a:
			num3 += (int)DefaultPerks.Roguery.OneOfTheFamily.SecondaryBonus;
			goto IL_00a8;
			IL_00a8:
			return TaleWorlds.Library.MathF.Min(6, TaleWorlds.Library.MathF.Max(0, num + num2 + num3));
		}

		public override float GetDailyVolunteerProductionProbability(Hero hero, int index, Settlement settlement)
		{
			float num = 0.7f;
			int num2 = 0;
			foreach (Town fief in hero.CurrentSettlement.MapFaction.Fiefs)
			{
				num2 += (fief.IsTown ? (((fief.Prosperity < 3000f) ? 1 : ((fief.Prosperity < 6000f) ? 2 : 3)) + fief.Villages.Count) : fief.Villages.Count);
			}
			float num3 = ((num2 < 46) ? ((float)num2 / 46f * ((float)num2 / 46f)) : 1f);
			num += ((hero.CurrentSettlement != null && num3 < 1f) ? ((1f - num3) * 0.2f) : 0f);
			float baseNumber = 0.75f * TaleWorlds.Library.MathF.Clamp(TaleWorlds.Library.MathF.Pow(num, index + 1), 0f, 1f);
			ExplainedNumber explainedNumber = new ExplainedNumber(baseNumber);
			if (hero.Clan?.Kingdom != null && hero.Clan.Kingdom.ActivePolicies.Contains(DefaultPolicies.Cantons))
			{
				explainedNumber.AddFactor(0.2f);
			}
			Town town = (settlement.IsTown ? settlement.Town : settlement.Village.TradeBound?.Town);
			if (town != null && hero.IsAlive && hero.VolunteerTypes[index] != null && hero.VolunteerTypes[index].IsMounted && PerkHelper.GetPerkValueForTown(DefaultPerks.Riding.CavalryTactics, town))
			{
				explainedNumber.AddFactor(DefaultPerks.Riding.CavalryTactics.PrimaryBonus);
			}
			return explainedNumber.ResultNumber;
		}

		public override CharacterObject GetBasicVolunteer(Hero sellerHero)
		{
			if (sellerHero.IsRuralNotable && sellerHero.CurrentSettlement.Village.Bound.IsCastle)
			{
				return sellerHero.Culture.EliteBasicTroop;
			}
			return sellerHero.Culture.BasicTroop;
		}

		public override bool CanHaveRecruits(Hero hero)
		{
			Occupation occupation = hero.Occupation;
			if (occupation == Occupation.Mercenary || (uint)(occupation - 17) <= 5u)
			{
				return true;
			}
			return false;
		}
	}
	public class DefaultWallHitPointCalculationModel : WallHitPointCalculationModel
	{
		public override float CalculateMaximumWallHitPoint(Town town)
		{
			if (town == null)
			{
				return 0f;
			}
			return CalculateMaximumWallHitPointInternal(town);
		}

		private float CalculateMaximumWallHitPointInternal(Town town)
		{
			float num = 0f;
			switch (town.GetWallLevel())
			{
			case 1:
				num += 30000f;
				break;
			case 2:
				num += 50000f;
				break;
			case 3:
				num += 67000f;
				break;
			default:
				TaleWorlds.Library.Debug.FailedAssert(string.Concat("Settlement \"", town.Name, "\" has a wrong wall level set."), "C:\\BuildAgent\\work\\mb3\\Source\\Bannerlord\\TaleWorlds.CampaignSystem\\GameComponents\\DefaultWallHitPointCalculationModel.cs", "CalculateMaximumWallHitPointInternal", 35);
				num += -1f;
				break;
			}
			Hero governor = town.Governor;
			if (governor != null && governor.GetPerkValue(DefaultPerks.Engineering.EngineeringGuilds))
			{
				num += num * DefaultPerks.Engineering.EngineeringGuilds.SecondaryBonus;
			}
			return num;
		}
	}
	public class DefaultWorkshopModel : WorkshopModel
	{
		public override int WarehouseCapacity => 6000;

		public override int DaysForPlayerSaveWorkshopFromBankruptcy => 3;

		public override int CapitalLowLimit => 5000;

		public override int InitialCapital => 10000;

		public override int DailyExpense => 100;

		public override int DefaultWorkshopCountInSettlement => 4;

		public override int MaximumWorkshopsPlayerCanHave => GetMaxWorkshopCountForClanTier(Campaign.Current.Models.ClanTierModel.MaxClanTier);

		public override ExplainedNumber GetEffectiveConversionSpeedOfProduction(Workshop workshop, float speed, bool includeDescription)
		{
			ExplainedNumber result = new ExplainedNumber(speed, includeDescription);
			Settlement settlement = workshop.Settlement;
			if (settlement.OwnerClan.Kingdom != null)
			{
				if (settlement.OwnerClan.Kingdom.ActivePolicies.Contains(DefaultPolicies.ForgivenessOfDebts))
				{
					result.AddFactor(-0.05f, DefaultPolicies.ForgivenessOfDebts.Name);
				}
				if (settlement.OwnerClan.Kingdom.ActivePolicies.Contains(DefaultPolicies.StateMonopolies))
				{
					result.AddFactor(-0.1f, DefaultPolicies.StateMonopolies.Name);
				}
			}
			if (settlement.IsFortification)
			{
				settlement.Town.AddEffectOfBuildings(BuildingEffectEnum.WorkshopProduction, ref result);
			}
			PerkHelper.AddPerkBonusForTown(DefaultPerks.Trade.MercenaryConnections, settlement.Town, ref result);
			PerkHelper.AddPerkBonusForCharacter(DefaultPerks.Steward.Sweatshops, workshop.Owner.CharacterObject, isPrimaryBonus: true, ref result);
			return result;
		}

		public override int GetMaxWorkshopCountForClanTier(int tier)
		{
			return tier + 1;
		}

		public override int GetCostForPlayer(Workshop workshop)
		{
			return workshop.WorkshopType.EquipmentCost + (int)workshop.Settlement.Town.Prosperity * 4 + InitialCapital / 5;
		}

		public override int GetCostForNotable(Workshop workshop)
		{
			return (workshop.WorkshopType.EquipmentCost + (int)workshop.Settlement.Town.Prosperity / 2 + workshop.Capital) / 2;
		}

		public override Hero GetNotableOwnerForWorkshop(Workshop workshop)
		{
			List<(Hero, float)> list = new List<(Hero, float)>();
			foreach (Hero notable in workshop.Settlement.Notables)
			{
				if (notable.IsAlive && notable != workshop.Owner)
				{
					int count = notable.OwnedWorkshops.Count;
					float item = Math.Max(notable.Power, 0f) / TaleWorlds.Library.MathF.Pow(10f, count);
					list.Add((notable, item));
				}
			}
			return MBRandom.ChooseWeighted(list);
		}

		public override int GetConvertProductionCost(WorkshopType workshopType)
		{
			return workshopType.EquipmentCost;
		}

		public override bool CanPlayerSellWorkshop(Workshop workshop, out TextObject explanation)
		{
			Campaign.Current.Models.WorkshopModel.GetCostForNotable(workshop);
			Hero notableOwnerForWorkshop = Campaign.Current.Models.WorkshopModel.GetNotableOwnerForWorkshop(workshop);
			explanation = ((notableOwnerForWorkshop == null) ? new TextObject("{=oqPf2Gdp}There isn't any prospective buyer in the town.") : null);
			return notableOwnerForWorkshop != null;
		}

		public override float GetTradeXpPerWarehouseProduction(EquipmentElement production)
		{
			return (float)production.GetBaseValue() * 0.1f;
		}
	}
