			_currentSentence = -1;
			ResetRepeatedDialogSystem();
			_lastSelectedDialogObject = null;
			TaleWorlds.Library.Debug.Print("--------------- Conversation Start --------------- ", 0, TaleWorlds.Library.Debug.DebugColor.White, 4503599627370496uL);
			TaleWorlds.Library.Debug.Print(string.Concat("Conversation character name: ", OneToOneConversationCharacter.Name, "\nid: ", OneToOneConversationCharacter.StringId, "\nculture:", OneToOneConversationCharacter.Culture, "\npersona:", OneToOneConversationCharacter.GetPersona().Name));
			_mainAgent.OnConversationStarted();
			if (CampaignMission.Current != null)
			{
				foreach (IAgent conversationAgent in ConversationAgents)
				{
					CampaignMission.Current.OnConversationStart(conversationAgent, setActionsInstantly);
