				_speakerAgent = agent;
				if (_speakerAgent != null && _speakerAgent.Character is CharacterObject)
				{
					StringHelpers.SetCharacterProperties("SPEAKER", agent.Character as CharacterObject);
				}
			}
		}

		private void SetListenerAgent(IAgent agent)
