		public override float DetermineSupport(Clan clan, DecisionOutcome possibleOutcome)
		{
			_ = clan.Leader;
			DeclareWarDecisionOutcome obj = (DeclareWarDecisionOutcome)possibleOutcome;
			float num = (float)new DeclareWarBarterable(base.Kingdom, FactionToDeclareWarOn).GetValueForFaction(clan) * Campaign.Current.Models.DiplomacyModel.DenarsToInfluence();
			if (obj.ShouldWarBeDeclared)
			{
				int num2 = clan.Leader.GetTraitLevel(DefaultTraits.Valor) * 20 - clan.Leader.GetTraitLevel(DefaultTraits.Mercy) * 10;
				return num + (float)num2;
			}
			float num3 = 0f - num;
			int num4 = -clan.Leader.GetTraitLevel(DefaultTraits.Valor) * 20 + clan.Leader.GetTraitLevel(DefaultTraits.Mercy) * 10;
			return num3 + (float)num4;
		}
