		public static Clan GetProposerClanForPlayerKingdom(Kingdom target)
		{
			if (Clan.PlayerClan.Kingdom == null)
			{
				return null;
			}
			TextObject explanation;
			Clan clan = ((Clan.PlayerClan.Kingdom.RulingClan != Clan.PlayerClan && Campaign.Current.Models.TradeAgreementModel.GetScoreOfStartingTradeAgreement(Clan.PlayerClan.Kingdom, target, Clan.PlayerClan.Kingdom.RulingClan, out explanation) > 50f) ? Clan.PlayerClan.Kingdom.RulingClan : null);
			if (clan == null)
			{
				TextObject explanation3;
				List<Clan> list = Clan.PlayerClan.Kingdom.Clans.Where((Clan x) => !x.IsUnderMercenaryService && x != Clan.PlayerClan && Campaign.Current.Models.TradeAgreementModel.GetScoreOfStartingTradeAgreement(Clan.PlayerClan.Kingdom, target, x, out explanation3) > 50f).ToList();
				clan = ((list.Count <= 0) ? Clan.PlayerClan : list.MaxBy((Clan x) => Campaign.Current.Models.TradeAgreementModel.GetScoreOfStartingTradeAgreement(Clan.PlayerClan.Kingdom, target, x, out var _)));
			}
			return clan;
		}

