		{
			foreach (DecisionOutcome possibleOutcome in possibleOutcomes)
			{
				if (((TradeAgreementDecisionOutcome)possibleOutcome).ShouldTradeAgreementStart)
				{
					possibleOutcome.SetSponsor(base.ProposerClan);
