		public void UpdateTournamentPrize(bool includePlayer, bool removeCurrentPrize = false)
		{
			if (removeCurrentPrize)
			{
				Prize = null;
			}
			Prize = GetTournamentPrize(includePlayer, _lastRecordedLordCountForTournamentPrize);
		}
	}
	public class FightTournamentGame : TournamentGame
	{
		private const int LordLimitForEliteReward = 4;

		private const int EliteRewardLordCountToDivideRewards = 10;

		private const int EliteRewardGroupCount = 2;

		private const int RegularRewardMinimumValue = 1600;

		private const int RegularRewardMaximumValue = 5000;

		private const int ParticipateTournamentMinimumSkillLimit = 100;

		private const float RegularBannerRewardChance = 0.05f;

		public const int ParticipantTroopMinimumTierLimit = 3;

		private MBList<ItemObject> _possibleBannerRewardItemObjectsCache;

		private MBList<ItemObject> _possibleRegularRewardItemObjectsCache;

		private MBList<ItemObject> _possibleEliteRewardItemObjectsCache;

		public override int MaxTeamSize => 4;

		public override int MaxTeamNumberPerMatch => 4;

		public override int RemoveTournamentAfterDays => 15;

		public override int MaximumParticipantCount => 16;

		internal static void AutoGeneratedStaticCollectObjectsFightTournamentGame(object o, List<object> collectedObjects)
		{
			((FightTournamentGame)o).AutoGeneratedInstanceCollectObjects(collectedObjects);
		}

		protected override void AutoGeneratedInstanceCollectObjects(List<object> collectedObjects)
		{
			base.AutoGeneratedInstanceCollectObjects(collectedObjects);
		}

		public FightTournamentGame(Town town)
			: base(town)
		{
			base.Mode = QualificationMode.TeamScore;
		}

		public override bool CanBeAParticipant(CharacterObject character, bool considerSkills)
		{
			if (!character.IsHero)
			{
				return character.Tier >= 3;
			}
			if (considerSkills)
			{
				if (character.HeroObject.GetSkillValue(DefaultSkills.OneHanded) < 100)
				{
					return character.HeroObject.GetSkillValue(DefaultSkills.TwoHanded) >= 100;
				}
				return true;
			}
			return true;
		}

		public override TextObject GetMenuText()
		{
			int num = GetParticipantCharacters(Settlement.CurrentSettlement, includePlayer: false).Count((CharacterObject p) => p.IsHero);
			TextObject textObject = new TextObject("{=!}{TOURNAMENT_EXPLANATION} {PRIZE_EXPLANATION}");
			textObject.SetTextVariable("TOURNAMENT_EXPLANATION", GameTexts.FindText("str_fighting_menu_text"));
			TextObject textObject2;
			if (num > 0)
			{
				textObject2 = new TextObject("{=GuWWKgEm}As you approach the arena, you overhear gossip about the contestants and prizes. Apparently there {?(NOBLE_COUNT > 1)}are {NOBLE_COUNT} lords{?}is 1 lord{\\?} with renowned fighting skills present in the city who plan to enter the tournament. Given this turnout, the organizers are offering {.a} \"{.%}{TOURNAMENT_PRIZE}{.%}\" for the victor.");
				textObject2.SetTextVariable("NOBLE_COUNT", num);
				textObject2.SetTextVariable("TOURNAMENT_PRIZE", base.Prize.Name);
			}
			else
			{
				textObject2 = new TextObject("{=mnAdqeGu}As you approach the arena, you overhear gossip about the contestants and prizes. Apparently there are no lords who plan to compete, but the winner will still receive a {TOURNAMENT_PRIZE}.");
				textObject2.SetTextVariable("TOURNAMENT_PRIZE", base.Prize.Name);
			}
			textObject.SetTextVariable("PRIZE_EXPLANATION", textObject2);
			return textObject;
		}

		public override void OpenMission(Settlement settlement, bool isPlayerParticipating)
		{
			int upgradeLevel = ((!settlement.IsTown) ? 1 : settlement.Town.GetWallLevel());
			SandBoxMission.OpenTournamentFightMission(LocationComplex.Current.GetScene("arena", upgradeLevel), this, settlement, settlement.Culture, isPlayerParticipating);
		}

		public override MBList<CharacterObject> GetParticipantCharacters(Settlement settlement, bool includePlayer = true)
		{
			MBList<CharacterObject> mBList = new MBList<CharacterObject>();
			if (includePlayer)
			{
				mBList.Add(CharacterObject.PlayerCharacter);
			}
			for (int i = 0; i < settlement.Parties.Count; i++)
			{
				if (mBList.Count >= MaximumParticipantCount)
				{
					break;
				}
				Hero leaderHero = settlement.Parties[i].LeaderHero;
				if (CanNpcJoinTournament(leaderHero, mBList, considerSkills: true))
				{
					if (leaderHero.CurrentSettlement != settlement)
					{
						TaleWorlds.Library.Debug.Print(leaderHero.StringId + " is in settlement.Parties list but current settlement is not, tournament settlement: " + settlement.StringId);
					}
					mBList.Add(leaderHero.CharacterObject);
				}
			}
			for (int j = 0; j < settlement.HeroesWithoutParty.Count; j++)
			{
				if (mBList.Count >= MaximumParticipantCount)
				{
					break;
				}
				Hero hero = settlement.HeroesWithoutParty[j];
				if (CanNpcJoinTournament(hero, mBList, considerSkills: true) && hero.IsLord)
				{
					if (hero.CurrentSettlement != settlement)
					{
						TaleWorlds.Library.Debug.Print(hero.StringId + " is in settlement.HeroesWithoutParty list but current settlement is not, tournament settlement: " + settlement.StringId);
					}
					mBList.Add(hero.CharacterObject);
				}
			}
			for (int k = 0; k < settlement.HeroesWithoutParty.Count; k++)
			{
				if (mBList.Count >= MaximumParticipantCount)
				{
					break;
				}
				Hero hero2 = settlement.HeroesWithoutParty[k];
				if (CanNpcJoinTournament(hero2, mBList, considerSkills: true) && !hero2.IsLord)
				{
					if (hero2.CurrentSettlement != settlement)
					{
						TaleWorlds.Library.Debug.Print(hero2.StringId + " is in settlement.HeroesWithoutParty list but current settlement is not, tournament settlement: " + settlement.StringId);
					}
					mBList.Add(hero2.CharacterObject);
				}
			}
			for (int l = 0; l < settlement.Parties.Count; l++)
			{
				if (mBList.Count >= MaximumParticipantCount)
				{
					break;
				}
				foreach (TroopRosterElement item2 in settlement.Parties[l].MemberRoster.GetTroopRoster())
				{
					if (mBList.Count >= MaximumParticipantCount)
					{
						break;
					}
					CharacterObject character = item2.Character;
					if (character.IsHero && character.HeroObject.Clan == Clan.PlayerClan && CanNpcJoinTournament(character.HeroObject, mBList, considerSkills: true))
					{
						if (character.HeroObject.CurrentSettlement != settlement)
						{
							TaleWorlds.Library.Debug.Print(character.HeroObject.StringId + " is in settlement.HeroesWithoutParty list but current settlement is not, tournament settlement: " + settlement.StringId);
						}
						mBList.Add(character);
					}
				}
			}
			int num = 0;
			int num2 = 0;
			int num3 = 0;
			if (mBList.Count < MaximumParticipantCount && settlement.Town.GarrisonParty != null)
			{
				int num4 = MaximumParticipantCount - mBList.Count;
				foreach (TroopRosterElement item3 in settlement.Town.GarrisonParty.MemberRoster.GetTroopRoster())
				{
					if (CanBeAParticipant(item3.Character, considerSkills: false))
					{
						if (!mBList.Contains(item3.Character) && item3.Character.Tier == 3 && (float)num4 * 0.4f > (float)num)
						{
							mBList.Add(item3.Character);
							num++;
						}
						else if (!mBList.Contains(item3.Character) && item3.Character.Tier == 4 && (float)num4 * 0.4f > (float)num2)
						{
							mBList.Add(item3.Character);
							num2++;
						}
						else if (!mBList.Contains(item3.Character) && item3.Character.Tier == 5 && (float)num4 * 0.2f > (float)num3)
						{
							mBList.Add(item3.Character);
							num3++;
						}
					}
					if (mBList.Count >= MaximumParticipantCount)
					{
						break;
					}
				}
			}
			if (mBList.Count < MaximumParticipantCount)
			{
				List<CharacterObject> list = new List<CharacterObject>();
				CharacterObject basicTroop = ((settlement != null) ? settlement.Culture : Game.Current.ObjectManager.GetObject<CultureObject>("empire")).BasicTroop;
				GetUpgradeTargets(basicTroop, ref list);
				int num5 = MaximumParticipantCount - mBList.Count;
				foreach (CharacterObject item4 in list)
				{
					if (!mBList.Contains(item4) && item4.Tier == 3 && (float)num5 * 0.4f > (float)num)
					{
						mBList.Add(item4);
						num++;
					}
					else if (!mBList.Contains(item4) && item4.Tier == 4 && (float)num5 * 0.4f > (float)num2)
					{
						mBList.Add(item4);
						num2++;
					}
					else if (!mBList.Contains(item4) && item4.Tier == 5 && (float)num5 * 0.2f > (float)num3)
					{
						mBList.Add(item4);
						num3++;
					}
					if (mBList.Count >= MaximumParticipantCount)
					{
						break;
					}
				}
				if (!list.IsEmpty())
				{
					while (mBList.Count < MaximumParticipantCount)
					{
						list.Shuffle();
						for (int m = 0; m < list.Count; m++)
						{
							if (mBList.Count >= MaximumParticipantCount)
							{
								break;
							}
							mBList.Add(list[m]);
						}
					}
				}
			}
			while (mBList.Count < MaximumParticipantCount)
			{
				CultureObject cultureObject = ((settlement != null) ? settlement.Culture : Game.Current.ObjectManager.GetObject<CultureObject>("empire"));
				CharacterObject item = ((MBRandom.RandomFloat > 0.5f) ? cultureObject.BasicTroop : cultureObject.EliteBasicTroop);
				mBList.Add(item);
			}
			SortTournamentParticipants(mBList);
			return mBList;
		}

		private bool CanNpcJoinTournament(Hero hero, MBList<CharacterObject> participantCharacters, bool considerSkills)
		{
			if (hero != null && !hero.IsWounded && !hero.IsNoncombatant && !participantCharacters.Contains(hero.CharacterObject) && hero != Hero.MainHero && hero.Age >= (float)Campaign.Current.Models.AgeModel.HeroComesOfAge && (hero.IsLord || hero.IsWanderer))
			{
				return CanBeAParticipant(hero.CharacterObject, considerSkills);
			}
			return false;
		}

		private void GetUpgradeTargets(CharacterObject troop, ref List<CharacterObject> list)
		{
			if (!list.Contains(troop) && CanBeAParticipant(troop, considerSkills: false))
			{
				list.Add(troop);
			}
			CharacterObject[] upgradeTargets = troop.UpgradeTargets;
			foreach (CharacterObject troop2 in upgradeTargets)
			{
				GetUpgradeTargets(troop2, ref list);
			}
		}

		private void SortTournamentParticipants(MBList<CharacterObject> participantCharacters)
		{
			for (int i = 0; i < participantCharacters.Count - 1; i++)
			{
				for (int num = participantCharacters.Count - 1; num > i; num--)
				{
					if (GetTroopPriorityPointForTournament(participantCharacters[num]) > GetTroopPriorityPointForTournament(participantCharacters[i]))
					{
						CharacterObject value = participantCharacters[num];
						CharacterObject value2 = participantCharacters[i];
						participantCharacters[num] = value2;
						participantCharacters[i] = value;
					}
				}
			}
		}

		private int GetTroopPriorityPointForTournament(CharacterObject troop)
		{
			int num = 40000;
			if (troop == CharacterObject.PlayerCharacter)
			{
				num += 80000;
			}
			if (troop.IsHero)
			{
				num += 20000;
			}
			if (troop.IsHero && troop.HeroObject.IsPlayerCompanion)
			{
				return num + 10000;
			}
			if (troop.HeroObject?.Clan != null)
			{
				return num + (int)(troop.HeroObject.Clan?.Renown).Value;
			}
			return num + troop.Level;
		}

		protected override ItemObject GetTournamentPrize(bool includePlayer, int lastRecordedLordCountForTournamentPrize)
		{
			int num = GetParticipantCharacters(base.Town.Settlement, includePlayer).Count((CharacterObject p) => p.IsHero);
			if (lastRecordedLordCountForTournamentPrize != num || base.Prize == null)
			{
				_lastRecordedLordCountForTournamentPrize = num;
				if (num < 4)
				{
					ItemObject itemObject = null;
					if (MBRandom.RandomFloat < 0.05f)
					{
						if (_possibleBannerRewardItemObjectsCache == null || _possibleBannerRewardItemObjectsCache.IsEmpty())
						{
							MBList<ItemObject> regularRewardItems = Campaign.Current.Models.TournamentModel.GetRegularRewardItems(base.Town, 1600, 5000);
							_possibleBannerRewardItemObjectsCache = new MBList<ItemObject>();
							foreach (ItemObject item in regularRewardItems)
							{
								if (item.IsBannerItem)
								{
									_possibleBannerRewardItemObjectsCache.Add(item);
								}
							}
						}
						itemObject = _possibleBannerRewardItemObjectsCache.GetRandomElement();
					}
					if (itemObject == null)
					{
						if (_possibleRegularRewardItemObjectsCache == null || _possibleRegularRewardItemObjectsCache.IsEmpty())
						{
							_possibleRegularRewardItemObjectsCache = Campaign.Current.Models.TournamentModel.GetRegularRewardItems(base.Town, 1600, 5000);
							_possibleRegularRewardItemObjectsCache.Sort((ItemObject x, ItemObject y) => x.Value.CompareTo(y.Value));
						}
						int num2 = _possibleRegularRewardItemObjectsCache.Count / 4;
						int num3 = Math.Min(_possibleRegularRewardItemObjectsCache.Count, num2 * (num + 1));
						int minValue = Math.Max(0, num3 - num2);
						itemObject = _possibleRegularRewardItemObjectsCache[MBRandom.RandomInt(minValue, num3)];
					}
					if (itemObject != null)
					{
						return itemObject;
					}
					if (_possibleEliteRewardItemObjectsCache == null || _possibleEliteRewardItemObjectsCache.IsEmpty())
					{
						_possibleEliteRewardItemObjectsCache = Campaign.Current.Models.TournamentModel.GetEliteRewardItems(base.Town, 1600, 5000);
					}
					return _possibleEliteRewardItemObjectsCache.GetRandomElement();
				}
				if (_possibleEliteRewardItemObjectsCache == null || _possibleEliteRewardItemObjectsCache.IsEmpty())
				{
					_possibleEliteRewardItemObjectsCache = Campaign.Current.Models.TournamentModel.GetEliteRewardItems(base.Town, 1600, 5000);
					_possibleEliteRewardItemObjectsCache.Sort((ItemObject x, ItemObject y) => x.Value.CompareTo(y.Value));
				}
				int minValue2 = 0;
				int maxValue = _possibleEliteRewardItemObjectsCache.Count;
				if (num < 10)
				{
					maxValue = _possibleEliteRewardItemObjectsCache.Count / 2;
				}
				else
				{
					minValue2 = _possibleEliteRewardItemObjectsCache.Count / 2;
				}
				return _possibleEliteRewardItemObjectsCache[MBRandom.RandomInt(minValue2, maxValue)];
			}
			return base.Prize;
		}
	}
	public class TournamentManager : ITournamentManager
	{
		[SaveableField(1)]
		private List<TournamentGame> _activeTournaments;

		[SaveableField(4)]
		private readonly Dictionary<Hero, int> _worldWideTournamentLeaderboard;

		internal static void AutoGeneratedStaticCollectObjectsTournamentManager(object o, List<object> collectedObjects)
		{
			((TournamentManager)o).AutoGeneratedInstanceCollectObjects(collectedObjects);
		}

		protected virtual void AutoGeneratedInstanceCollectObjects(List<object> collectedObjects)
		{
			collectedObjects.Add(_activeTournaments);
			collectedObjects.Add(_worldWideTournamentLeaderboard);
		}

		internal static object AutoGeneratedGetMemberValue_activeTournaments(object o)
		{
			return ((TournamentManager)o)._activeTournaments;
		}

		internal static object AutoGeneratedGetMemberValue_worldWideTournamentLeaderboard(object o)
		{
			return ((TournamentManager)o)._worldWideTournamentLeaderboard;
		}

		public TournamentManager()
		{
			_worldWideTournamentLeaderboard = new Dictionary<Hero, int>();
			_activeTournaments = new List<TournamentGame>();
		}

		public void AddTournament(TournamentGame game)
		{
			_activeTournaments.Add(game);
			CampaignEventDispatcher.Instance.OnTournamentStarted(game.Town);
		}

		public void RemoveTournament(TournamentGame game)
		{
			_activeTournaments.Remove(game);
		}

		public TournamentGame GetTournamentGame(Town town)
		{
			return _activeTournaments.Find((TournamentGame x) => x != null && x.Town == town);
		}

		public void OnPlayerJoinMatch(Type gameType)
		{
		}

		public void OnPlayerJoinTournament(Type gameType, Settlement settlement)
		{
			CampaignEventDispatcher.Instance.OnPlayerJoinedTournament(settlement.Town, isParticipant: true);
			TournamentGame tournamentGame = GetTournamentGame(settlement.Town);
			_activeTournaments.Remove(tournamentGame);
		}

		public void OnPlayerWatchTournament(Type gameType, Settlement settlement)
		{
			CampaignEventDispatcher.Instance.OnPlayerJoinedTournament(settlement.Town, isParticipant: false);
			TournamentGame tournamentGame = GetTournamentGame(settlement.Town);
			_activeTournaments.Remove(tournamentGame);
		}

		public void OnPlayerWinMatch(Type gameType)
		{
		}

		public void OnPlayerWinTournament(Type gameType)
		{
		}

		public List<KeyValuePair<Hero, int>> GetLeaderboard()
		{
			return _worldWideTournamentLeaderboard.OrderByDescending(delegate(KeyValuePair<Hero, int> pair)
			{
				KeyValuePair<Hero, int> keyValuePair = pair;
				return keyValuePair.Value;
			}).ToList();
		}

		public int GetLeaderBoardRank(Hero hero)
		{
			return GetLeaderboard().FindIndex((KeyValuePair<Hero, int> kvp) => kvp.Key == hero) + 1;
		}

		public Hero GetLeaderBoardLeader()
		{
			Dictionary<Hero, int> worldWideTournamentLeaderboard = _worldWideTournamentLeaderboard;
			Hero result = null;
			int num = -1;
			foreach (Hero key in worldWideTournamentLeaderboard.Keys)
			{
				int num2 = worldWideTournamentLeaderboard[key];
				if (num2 > num)
				{
					num = num2;
					result = key;
				}
			}
			return result;
		}

		public void InitializeLeaderboardEntry(Hero hero, int initialVictories = 0)
		{
			_worldWideTournamentLeaderboard[hero] = initialVictories;
		}

		public void AddLeaderboardEntry(Hero hero)
		{
			_worldWideTournamentLeaderboard.TryGetValue(hero, out var value);
			_worldWideTournamentLeaderboard[hero] = value + 1;
		}

		public void DeleteLeaderboardEntry(Hero hero)
		{
			if (_worldWideTournamentLeaderboard.ContainsKey(hero))
			{
				_worldWideTournamentLeaderboard.Remove(hero);
			}
		}

		public void ResolveTournament(TournamentGame tournament, Town town)
		{
			if (!town.IsUnderSiege)
			{
				MBList<CharacterObject> participantCharacters = tournament.GetParticipantCharacters(tournament.Town.Settlement, includePlayer: false);
				SimulateTournament(participantCharacters, tournament.Town, out var winner);
				if (winner.IsHero)
				{
					AddLeaderboardEntry(winner.HeroObject);
					GivePrizeToWinner(tournament, winner.HeroObject, isPlayerParticipated: false);
				}
				CampaignEventDispatcher.Instance.OnTournamentFinished(winner, participantCharacters, tournament.Town, tournament.Prize);
			}
			else
			{
				CampaignEventDispatcher.Instance.OnTournamentCancelled(town);
			}
			RemoveTournament(tournament);
		}

		private void SimulateTournament(MBList<CharacterObject> participants, Town town, out CharacterObject winner)
		{
			float num = -1f;
			winner = null;
			foreach (CharacterObject participant in participants)
			{
				if (participant.IsHero)
				{
					var (skill, num2) = Campaign.Current.Models.TournamentModel.GetSkillXpGainFromTournament(town);
					participant.HeroObject.HeroDeveloper.AddSkillXp(skill, num2);
				}
				float num3 = Campaign.Current.Models.TournamentModel.GetTournamentSimulationScore(participant) * (0.75f + 0.25f * MBRandom.RandomFloat);
				if (num3 > num)
				{
					winner = participant;
					num = num3;
				}
			}
		}

		public void GivePrizeToWinner(TournamentGame tournament, Hero winner, bool isPlayerParticipated)
		{
			if (!isPlayerParticipated)
			{
				tournament.UpdateTournamentPrize(isPlayerParticipated);
			}
			if (winner.PartyBelongedTo == MobileParty.MainParty)
			{
				winner.PartyBelongedTo.ItemRoster.AddToCounts(tournament.Prize, 1);
			}
			else if (winner.Clan != null)
			{
				GiveGoldAction.ApplyBetweenCharacters(null, winner.Clan.Leader, tournament.Town.MarketData.GetPrice(tournament.Prize));
			}
		}
	}
	public interface ITournamentManager
	{
		void AddTournament(TournamentGame game);

		TournamentGame GetTournamentGame(Town town);

		void OnPlayerJoinMatch(Type gameType);

		void OnPlayerJoinTournament(Type gameType, Settlement settlement);

		void OnPlayerWatchTournament(Type gameType, Settlement settlement);

		void OnPlayerWinMatch(Type gameType);

		void OnPlayerWinTournament(Type gameType);

		void InitializeLeaderboardEntry(Hero hero, int initialVictories = 0);

		void AddLeaderboardEntry(Hero hero);

		void GivePrizeToWinner(TournamentGame tournament, Hero winner, bool isPlayerParticipated);

		void DeleteLeaderboardEntry(Hero hero);

		List<KeyValuePair<Hero, int>> GetLeaderboard();

		int GetLeaderBoardRank(Hero hero);

		Hero GetLeaderBoardLeader();

		void ResolveTournament(TournamentGame tournament, Town town);
	}
	public class TournamentCampaignBehavior : CampaignBehaviorBase
	{
		private const int TournamentCooldownDurationAsDays = 15;

		private Dictionary<Town, CampaignTime> _lastCreatedTournamentDatesInTowns = new Dictionary<Town, CampaignTime>();

		public override void RegisterEvents()
		{
			CampaignEvents.DailyTickSettlementEvent.AddNonSerializedListener(this, DailyTickSettlement);
			CampaignEvents.OnSessionLaunchedEvent.AddNonSerializedListener(this, OnSessionLaunched);
			CampaignEvents.OnNewGameCreatedPartialFollowUpEndEvent.AddNonSerializedListener(this, OnNewGameCreatedPartialFollowUpEnd);
			CampaignEvents.HeroKilledEvent.AddNonSerializedListener(this, OnHeroKilled);
			CampaignEvents.TournamentFinished.AddNonSerializedListener(this, OnTournamentFinished);
			CampaignEvents.DailyTickEvent.AddNonSerializedListener(this, OnDailyTick);
			CampaignEvents.OnGameLoadedEvent.AddNonSerializedListener(this, OnGameLoaded);
			CampaignEvents.TownRebelliosStateChanged.AddNonSerializedListener(this, OnTownRebelliousStateChanged);
			CampaignEvents.OnSiegeEventStartedEvent.AddNonSerializedListener(this, OnSiegeEventStarted);
		}

		private void OnNewGameCreatedPartialFollowUpEnd(CampaignGameStarter starter)
		{
			Campaign.Current.TournamentManager.InitializeLeaderboardEntry(Hero.MainHero);
			InitializeTournamentLeaderboard();
			for (int i = 0; i < 3; i++)
			{
				foreach (Town allTown in Town.AllTowns)
				{
					if (allTown.IsTown)
					{
						ConsiderStartOrEndTournament(allTown);
					}
				}
			}
		}

		private void OnDailyTick()
		{
			Hero leaderBoardLeader = Campaign.Current.TournamentManager.GetLeaderBoardLeader();
			if (leaderBoardLeader != null && leaderBoardLeader.IsAlive && leaderBoardLeader.Clan != null)
			{
				leaderBoardLeader.Clan.AddRenown(1f);
			}
		}

		private void OnGameLoaded(CampaignGameStarter campaignGameStarter)
		{
			foreach (Town allTown in Town.AllTowns)
			{
				TournamentGame tournamentGame = Campaign.Current.TournamentManager.GetTournamentGame(allTown);
				if (tournamentGame != null && tournamentGame.Prize != null && (tournamentGame.Prize == DefaultItems.Trash || !tournamentGame.Prize.IsReady))
				{
					tournamentGame.UpdateTournamentPrize(includePlayer: false, removeCurrentPrize: true);
				}
			}
			foreach (KeyValuePair<Town, CampaignTime> item in _lastCreatedTournamentDatesInTowns.ToList())
			{
				if (item.Value.ElapsedDaysUntilNow >= 15f)
				{
					_lastCreatedTournamentDatesInTowns.Remove(item.Key);
				}
			}
		}

		private void OnTownRebelliousStateChanged(Town town, bool rebelliousState)
		{
			if (town.InRebelliousState)
			{
				TournamentGame tournamentGame = Campaign.Current.TournamentManager.GetTournamentGame(town);
				if (tournamentGame != null)
				{
					Campaign.Current.TournamentManager.ResolveTournament(tournamentGame, town);
				}
			}
		}

		private void OnSiegeEventStarted(SiegeEvent siegeEvent)
		{
			Town town = siegeEvent.BesiegedSettlement.Town;
			if (town != null)
			{
				TournamentGame tournamentGame = Campaign.Current.TournamentManager.GetTournamentGame(town);
				if (tournamentGame != null)
				{
					Campaign.Current.TournamentManager.ResolveTournament(tournamentGame, town);
				}
			}
		}

		public override void SyncData(IDataStore dataStore)
		{
			dataStore.SyncData("_lastCreatedTournamentTimesInTowns", ref _lastCreatedTournamentDatesInTowns);
		}

		private void OnHeroKilled(Hero victim, Hero killer, KillCharacterAction.KillCharacterActionDetail detail, bool showNotification)
		{
			Campaign.Current.TournamentManager.DeleteLeaderboardEntry(victim);
		}

		public void OnSessionLaunched(CampaignGameStarter campaignGameStarter)
		{
			AddDialogs(campaignGameStarter);
			AddGameMenus(campaignGameStarter);
		}

		private void DailyTickSettlement(Settlement settlement)
		{
			if (settlement.IsTown)
			{
				ConsiderStartOrEndTournament(settlement.Town);
			}
		}

		private void ConsiderStartOrEndTournament(Town town)
		{
			if (_lastCreatedTournamentDatesInTowns.TryGetValue(town, out var value) && !(value.ElapsedDaysUntilNow >= 15f))
			{
				return;
			}
			ITournamentManager tournamentManager = Campaign.Current.TournamentManager;
			TournamentGame tournamentGame = tournamentManager.GetTournamentGame(town);
			if (tournamentGame != null && tournamentGame.CreationTime.ElapsedDaysUntilNow >= (float)tournamentGame.RemoveTournamentAfterDays)
			{
				tournamentManager.ResolveTournament(tournamentGame, town);
			}
			if (tournamentGame == null)
			{
				if (MBRandom.RandomFloat < Campaign.Current.Models.TournamentModel.GetTournamentStartChance(town))
				{
					tournamentManager.AddTournament(Campaign.Current.Models.TournamentModel.CreateTournament(town));
					if (!_lastCreatedTournamentDatesInTowns.ContainsKey(town))
					{
						_lastCreatedTournamentDatesInTowns.Add(town, CampaignTime.Now);
					}
					else
					{
						_lastCreatedTournamentDatesInTowns[town] = CampaignTime.Now;
					}
				}
			}
			else if (tournamentGame.CreationTime.ElapsedDaysUntilNow < (float)tournamentGame.RemoveTournamentAfterDays && MBRandom.RandomFloat < Campaign.Current.Models.TournamentModel.GetTournamentEndChance(tournamentGame))
			{
				tournamentManager.ResolveTournament(tournamentGame, town);
			}
		}

		private void OnTournamentFinished(CharacterObject winner, MBReadOnlyList<CharacterObject> participants, Town town, ItemObject prize)
		{
			if (winner.IsHero && winner.HeroObject.Clan != null)
			{
				winner.HeroObject.Clan.AddRenown(Campaign.Current.Models.TournamentModel.GetRenownReward(winner.HeroObject, town));
				GainKingdomInfluenceAction.ApplyForDefault(winner.HeroObject, Campaign.Current.Models.TournamentModel.GetInfluenceReward(winner.HeroObject, town));
			}
		}

		private float GetTournamentSimulationScore(Hero hero)
		{
			return Campaign.Current.Models.TournamentModel.GetTournamentSimulationScore(hero.CharacterObject);
		}

		private void InitializeTournamentLeaderboard()
		{
			Hero[] array = Hero.AllAliveHeroes.Where((Hero x) => x.IsLord && GetTournamentSimulationScore(x) > 1.5f).ToArray();
			int numLeaderboardVictoriesAtGameStart = Campaign.Current.Models.TournamentModel.GetNumLeaderboardVictoriesAtGameStart();
			if (array.Length < 3)
			{
				return;
			}
			List<Hero> list = new List<Hero>();
			for (int i = 0; i < numLeaderboardVictoriesAtGameStart; i++)
			{
				list.Clear();
				for (int j = 0; j < 16; j++)
				{
					Hero item = array[MBRandom.RandomInt(array.Length)];
					list.Add(item);
				}
				Hero hero = null;
				float num = 0f;
				foreach (Hero item2 in list)
				{
					float num2 = GetTournamentSimulationScore(item2) * (0.8f + 0.2f * MBRandom.RandomFloat);
					if (num2 > num)
					{
						num = num2;
						hero = item2;
					}
				}
				Campaign.Current.TournamentManager.AddLeaderboardEntry(hero);
				hero.Clan.AddRenown(Campaign.Current.Models.TournamentModel.GetRenownReward(hero, null));
			}
		}

