		private bool CanAssignMoreRoleToHero(Hero hero)
		{
			int num = 0;
			if (Quartermaster == hero)
			{
				num++;
			}
			if (Scout == hero)
			{
				num++;
			}
			if (Surgeon == hero)
			{
				num++;
			}
			if (Engineer == hero)
			{
				num++;
			}
			if (FirstMate == hero)
			{
				num++;
			}
			if (Navigator == hero)
			{
				num++;
			}
			return num < Campaign.Current.Models.ClanMemberPartyRoleModel.MaximumPartyRoleAssignmentCount;
		}

