						if (leftSideElement2.Item1.Character == leftSideElement.Item1.Character && leftSideElement2.Item2 == leftSideElement.Item2)
						{
							int num6 = num5;
							item = leftSideElement2.Item1;
							num5 = num6 + item.Number;
