		{
			TextObject textObject = null;
			textObject = ((!IsNaval) ? GameTexts.FindText("str_patrol_party_name") : GameTexts.FindText("str_coastal_patrol_party_name"));
			textObject.SetTextVariable("SETTLEMENT", HomeSettlement.Name);
			return textObject;
		}

