		internal void Tick()
		{
			for (int num = _mapEvents.Count - 1; num >= 0; num--)
			{
				if (_mapEvents[num].IsFinalized)
				{
					_mapEvents.RemoveAt(num);
				}
				else if (_mapEvents[num].IsRaid || _mapEvents[num] != MobileParty.MainParty.MapEvent)
				{
					_mapEvents[num].Update();
				}
			}
		}

