		{
			if (MobileParty.MainParty.MapEvent == null)
			{
				throw new MBNotFoundException("Trying to finalize a non-existing map event.");
			}
			PartyBase.MainParty.MapEvent.FinalizeEvent();
			PlayerEncounter.Finish();
		}

