		private void RemoveShipFromSimulationList(Ship ship)
		{
			SimulationShipList.Remove(ship);
			for (int num = _siegeEngineList.Count - 1; num >= 0; num--)
			{
				if (_siegeEngineList[num].Item2 == ship)
				{
					_siegeEngineList.RemoveAt(num);
				}
			}
		}

