		{
			OnInitialize();
		}

		internal void BeforeFinalizeComponent()
		{
			OnBeforeFinalize();
		}

		internal void FinalizeComponent()
		{
			if (!_isFinished)
			{
				FinishComponent();
			}
			OnFinalize();
		}

		internal void FinishComponent()
		{
			_isFinished = true;
			OnFinish();
		}

