		public static void FillIssueCountsPerSettlement(Dictionary<Settlement, int> issueCountPerSettlement)
		{
			foreach (KeyValuePair<Hero, IssueBase> issue in Campaign.Current.IssueManager.Issues)
			{
				Settlement issueSettlement = issue.Value.IssueSettlement;
				if (issueSettlement != null)
				{
					if (!issueCountPerSettlement.ContainsKey(issueSettlement))
					{
						issueCountPerSettlement[issueSettlement] = 1;
					}
					else
					{
						issueCountPerSettlement[issueSettlement]++;
					}
				}
			}
		}

		public static IEnumerable<IssueBase> GetIssuesInSettlement(Settlement settlement, bool onlyNotables = true)
		{
			foreach (Hero notable in settlement.Notables)
			{
				if (notable.Issue != null)
				{
					yield return notable.Issue;
				}
			}
			if (onlyNotables)
			{
				yield break;
			}
			foreach (Hero item in settlement.HeroesWithoutParty)
			{
				if (item.Issue != null && !item.IsNotable)
				{
					yield return item.Issue;
				}
			}
			foreach (MobileParty settlementParty in settlement.Parties)
			{
				for (int i = 0; i < settlementParty.MemberRoster.Count; i++)
				{
					Hero hero = settlementParty.MemberRoster.GetCharacterAtIndex(i)?.HeroObject;
					if (hero != null && hero.Issue != null)
					{
						yield return hero.Issue;
					}
				}
			}
		}

		public static IssueBase GetIssueOfQuest(QuestBase quest)
		{
			foreach (KeyValuePair<Hero, IssueBase> issue in Campaign.Current.IssueManager.Issues)
			{
				if (issue.Value.IssueQuest == quest)
				{
					return issue.Value;
				}
			}
			return null;
		}

		public static void FillIssueCountsPerClan(Dictionary<Clan, int> issueCountPerClan, IEnumerable<Clan> clans)
		{
			foreach (Clan clan in clans)
			{
				int num = 0;
				foreach (Hero hero in clan.Heroes)
				{
					if (hero.Issue != null)
					{
						num++;
					}
				}
				issueCountPerClan.Add(clan, num);
			}
		}
	}
	public abstract class IssueCoolDownData
	{
		[SaveableField(0)]
		public readonly CampaignTime ExpireTime;

		protected virtual void AutoGeneratedInstanceCollectObjects(List<object> collectedObjects)
		{
			CampaignTime.AutoGeneratedStaticCollectObjectsCampaignTime(ExpireTime, collectedObjects);
		}

		internal static object AutoGeneratedGetMemberValueExpireTime(object o)
		{
			return ((IssueCoolDownData)o).ExpireTime;
		}

		protected IssueCoolDownData(CampaignTime expireTime)
		{
			ExpireTime = expireTime;
		}

		public virtual bool IsValid()
		{
			return !ExpireTime.IsPast;
		}

		public abstract bool IsRelatedTo(object obj);
	}
	public class HeroRelatedIssueCoolDownData : IssueCoolDownData
	{
		[SaveableField(1)]
		public readonly Hero RelatedHero;

		internal static void AutoGeneratedStaticCollectObjectsHeroRelatedIssueCoolDownData(object o, List<object> collectedObjects)
		{
			((HeroRelatedIssueCoolDownData)o).AutoGeneratedInstanceCollectObjects(collectedObjects);
		}

		protected override void AutoGeneratedInstanceCollectObjects(List<object> collectedObjects)
		{
			base.AutoGeneratedInstanceCollectObjects(collectedObjects);
			collectedObjects.Add(RelatedHero);
		}

		internal static object AutoGeneratedGetMemberValueRelatedHero(object o)
		{
			return ((HeroRelatedIssueCoolDownData)o).RelatedHero;
		}

		public HeroRelatedIssueCoolDownData(Hero hero, CampaignTime expireTime)
			: base(expireTime)
		{
			RelatedHero = hero;
		}

		public override bool IsRelatedTo(object obj)
		{
			if (obj is Hero hero)
			{
				return RelatedHero == hero;
			}
			return false;
		}

		public override bool IsValid()
		{
			if (base.IsValid() && RelatedHero != null)
			{
				return RelatedHero.IsAlive;
			}
			return false;
		}
	}
