				alternativeSolutionMeleeSkills.Add(DefaultSkills.Roguery);
				alternativeSolutionMeleeSkills.Add(DefaultSkills.Tactics);
				return (alternativeSolutionMeleeSkills.MaxBy(hero.GetSkillValue), 120);
