			{
				if (issueEffect == DefaultIssueEffects.IssueOwnerPower)
				{
					return -1f;
				}
				if (issueEffect == DefaultIssueEffects.SettlementSecurity)
				{
					return 1f;
				}
				return 0f;
			}

