			private int TournamentRoundGoal
			{
				get
				{
					if (_difficultyMultiplier > 0.7f)
					{
						return 5;
					}
					if (0.7f >= _difficultyMultiplier && _difficultyMultiplier > 0.5f)
					{
						return 4;
					}
					if (0.5f >= _difficultyMultiplier && _difficultyMultiplier > 0.2f)
					{
						return 3;
					}
					return 2;
				}
			}

