			protected override bool CanPlayerTakeQuestConditions(Hero issueGiver, out PreconditionFlags flag, out Hero relationHero, out SkillObject skill, out int requiredGold)
			{
				relationHero = null;
				skill = null;
				requiredGold = 0;
				flag = PreconditionFlags.None;
				if (issueGiver.GetRelationWithPlayer() < -10f)
				{
					flag |= PreconditionFlags.Relation;
					relationHero = issueGiver;
				}
				if (Hero.MainHero.IsKingdomLeader)
				{
					flag |= PreconditionFlags.MainHeroIsKingdomLeader;
				}
				if (issueGiver.MapFaction.IsAtWarWith(Hero.MainHero.MapFaction))
				{
					flag |= PreconditionFlags.AtWar;
				}
				if (Clan.PlayerClan.Tier < 2)
				{
					flag |= PreconditionFlags.ClanTier;
				}
				if (Clan.PlayerClan.Companions.Count >= Clan.PlayerClan.CompanionLimit)
				{
					flag |= PreconditionFlags.CompanionLimitReached;
				}
				return flag == PreconditionFlags.None;
			}

			public override bool IssueStayAliveConditions()
			{
				if (_youngHero.Age >= 18f && _youngHero.Age < (float)(23 - 200 / CampaignTime.DaysInYear) && _youngHero.PartyBelongedTo == null && _youngHero.PartyBelongedToAsPrisoner == null && _youngHero.IsActive && _youngHero.CurrentSettlement != null && _youngHero.Level <= 20 && base.IssueOwner.Clan != Clan.PlayerClan && _youngHero.Clan != Clan.PlayerClan)
				{
					if (_youngHero.Spouse != null)
					{
						return _youngHero.Children.IsEmpty();
					}
					return true;
				}
				return false;
			}

