			{
				CheckCompanionLimit();
			}

			private void OnPerkReset(Hero hero, PerkObject perk)
			{
				if (hero == Hero.MainHero)
				{
					CheckCompanionLimit();
				}
			}

			private void CheckCompanionLimit()
			{
				if (Clan.PlayerClan.Companions.Count > Clan.PlayerClan.CompanionLimit)
				{
					AddLog(CompanionLimitReachedQuestLogText);
					CompleteQuestWithCancel();
				}
			}

			private void OnGameLoadFinished()
			{
				if (Settlement.CurrentSettlement != null && Settlement.CurrentSettlement.HeroesWithoutParty.Contains(_youngHero))
				{
					SpawnYoungHeroInLordsHall();
				}
				CheckCompanionLimit();
			}

			private void OnSettlementEntered(MobileParty party, Settlement settlement, Hero hero)
			{
				if (party != null && party.IsMainParty && settlement.HeroesWithoutParty.Contains(_youngHero))
				{
					SpawnYoungHeroInLordsHall();
				}
			}

