		private void InitializeAll()
		{
			_oneHandedWrappedHandles.Initialize("{=looKU9Gl}Wrapped Handles", DefaultSkills.OneHanded, GetTierCost(1), _oneHandedBasher, "{=dY3GOmTN}{VALUE}% handling to one handed weapons.", PartyRole.Personal, 0.2f, EffectIncrementType.AddFactor, "{=0mBHB7mA}{VALUE} one handed skill to infantry troops in your formation.", PartyRole.Captain, 30f, EffectIncrementType.Add, TroopUsageFlags.Undefined, TroopUsageFlags.OneHandedUser);
			_oneHandedBasher.Initialize("{=6yEeYNRu}Basher", DefaultSkills.OneHanded, GetTierCost(1), _oneHandedWrappedHandles, "{=fFNNeqxu}{VALUE}% damage and longer stun duration with shield bashes.", PartyRole.Personal, 0.5f, EffectIncrementType.AddFactor, "{=goOE8oiI}{VALUE}% damage taken by infantry while in shield wall formation.", PartyRole.Captain, -0.04f, EffectIncrementType.AddFactor, TroopUsageFlags.Undefined, TroopUsageFlags.OnFoot);
			_oneHandedToBeBlunt.Initialize("{=SJ69EYuI}To Be Blunt", DefaultSkills.OneHanded, GetTierCost(2), _oneHandedSwiftStrike, "{=mzUa3duw}{VALUE}% damage with one handed axes and maces.", PartyRole.Personal, 0.05f, EffectIncrementType.AddFactor, "{=Ib9RYpMO}{VALUE} daily security to governed settlement.", PartyRole.Governor, 0.5f, EffectIncrementType.Add);
			_oneHandedSwiftStrike.Initialize("{=ciELES5v}Swift Strike", DefaultSkills.OneHanded, GetTierCost(2), _oneHandedToBeBlunt, "{=bW7DT97A}{VALUE}% swing speed with one handed weapons.", PartyRole.Personal, 0.02f, EffectIncrementType.AddFactor, "{=xwA6Om0Y}{VALUE} daily militia recruitment in the governed settlement.", PartyRole.Governor, 1f, EffectIncrementType.Add);
