			if (troop.Occupation == Occupation.Bandit)
			{
				num = 0.05f;
				skill = DefaultSkills.Roguery;
			}
			float xpAmount = (float)excessXp * num;
			obj.AddSkillXp(skill, xpAmount);
		}

