		{
			settlementComponent.Owner = Party;
			SettlementComponent = settlementComponent;
			if (SettlementComponent is Town town)
			{
				Town = town;
			}
			else if (SettlementComponent is Village village)
			{
				Village = village;
			}
			else if (SettlementComponent is Hideout hideout)
			{
				Hideout = hideout;
			}
		}

