				if (!_bound.IsTown)
				{
					return _tradeBound;
				}
				return _bound;
			}
			set
			{
				if (_tradeBound != value && !_bound.IsTown)
				{
					_tradeBound?.Town.RemoveTradeBoundVillageInternal(this);
					_tradeBound = value;
					_tradeBound?.Town.SetTradeBoundVillageInternal(this);
