			yield return base.Settlement.Party;
			foreach (MobileParty party in base.Settlement.Parties)
			{
				if (party.MapFaction == base.Settlement.MapFaction && ((!party.IsMilitia && !party.IsVillager) || battleType == MapEvent.BattleTypes.Raid || battleType == MapEvent.BattleTypes.IsForcingSupplies || battleType == MapEvent.BattleTypes.IsForcingVolunteers) && !party.IsCaravan)
				{
					yield return party.Party;
				}
			}
		}

		public PartyBase GetNextDefenderParty(ref int partyIndex, MapEvent.BattleTypes battleType)
		{
			partyIndex++;
			if (partyIndex == 0)
			{
				return base.Settlement.Party;
			}
			for (int i = partyIndex - 1; i < base.Settlement.Parties.Count; i++)
			{
				MobileParty mobileParty = base.Settlement.Parties[i];
				if (mobileParty.MapFaction == base.Settlement.MapFaction && !mobileParty.IsCaravan)
				{
					partyIndex = i + 1;
					return mobileParty.Party;
				}
			}
			return null;
		}

		public Village()
		{
			LastDemandSatisfiedTime = -1f;
			_marketData = new VillageMarketData(this);
		}

		public void DailyTick()
		{
			int hearthLevel = GetHearthLevel();
			Hearth += HearthChange;
			if (hearthLevel != GetHearthLevel())
			{
				base.Settlement.Party.SetLevelMaskIsDirty();
			}
			if (Hearth < 10f)
			{
				Hearth = 10f;
			}
			base.Owner.Settlement.Militia += MilitiaChange;
			if (base.Gold > 1000)
			{
				ChangeGold(1000 - base.Gold);
			}
		}

		public override void OnInit()
		{
			ChangeVillageStateAction.ApplyBySettingToNormal(base.Settlement);
			ChangeGold(1000);
		}

		public int GetWarehouseCapacity()
		{
			float num = Campaign.Current.Models.VillageProductionCalculatorModel.CalculateDailyFoodProductionAmount(this);
			foreach (var production in VillageType.Productions)
			{
				float resultNumber = Campaign.Current.Models.VillageProductionCalculatorModel.CalculateDailyProductionAmount(this, production.Item1).ResultNumber;
				num += resultNumber;
			}
			return TaleWorlds.Library.MathF.Ceiling(TaleWorlds.Library.MathF.Max(1f, num) * 5f);
		}

		public override int GetItemPrice(ItemObject item, MobileParty tradingParty = null, bool isSelling = false)
		{
			if (TradeBound == null)
			{
				return 1;
			}
			return TradeBound.Town.MarketData.GetPrice(item, tradingParty, isSelling);
		}

		public override int GetItemPrice(EquipmentElement itemRosterElement, MobileParty tradingParty = null, bool isSelling = false)
		{
			if (TradeBound == null)
			{
				return 1;
			}
			return TradeBound.Town.MarketData.GetPrice(itemRosterElement, tradingParty, isSelling);
		}

		public override string ToString()
		{
			return base.Name.ToString();
		}

		public override void Deserialize(MBObjectManager objectManager, XmlNode node)
		{
			base.Deserialize(objectManager, node);
			base.BackgroundCropPosition = float.Parse(node.Attributes["background_crop_position"].Value);
			base.BackgroundMeshName = node.Attributes["background_mesh"].Value;
			base.CastleBackgroundMeshName = node.Attributes["castle_background_mesh"].Value;
			base.WaitMeshName = node.Attributes["wait_mesh"].Value;
			if (Campaign.Current.CampaignGameLoadingType != Campaign.GameLoadingType.SavedCampaign)
			{
				Hearth = int.Parse(node.Attributes["hearth"].Value);
			}
			VillageType = (VillageType)objectManager.ReadObjectReferenceFromXml("village_type", typeof(VillageType), node);
			if (Campaign.Current.CampaignGameLoadingType != Campaign.GameLoadingType.SavedCampaign)
			{
				if (Bound != null && Bound.IsTown)
				{
					Bound.Town.RemoveTradeBoundVillageInternal(this);
				}
				Bound = (Settlement)objectManager.ReadObjectReferenceFromXml("bound", typeof(Settlement), node);
				if (Bound.IsTown)
				{
					Bound.Town.SetTradeBoundVillageInternal(this);
				}
			}
		}

		public bool IsProducing(ItemObject item)
		{
			foreach (var production in VillageType.Productions)
			{
				if (production.Item1 == item)
				{
					return true;
				}
			}
			return false;
		}

		public int GetHearthLevel()
		{
			if (Hearth >= 600f)
			{
				return 2;
			}
			if (Hearth >= 200f)
			{
				return 1;
			}
			return 0;
		}

		public override ProsperityLevel GetProsperityLevel()
		{
			if (GetHearthLevel() >= 2)
			{
				return ProsperityLevel.High;
			}
			if (GetHearthLevel() >= 1)
			{
				return ProsperityLevel.Mid;
			}
			return ProsperityLevel.Low;
		}
	}
	public sealed class VillageType : MBObjectBase
	{
		private MBList<(ItemObject, float)> _productions;

		public TextObject ShortName;

		public string MeshName;

		public string MeshNameUnderConstruction;

		public string MeshNameBurned;

		public static MBReadOnlyList<VillageType> All => Campaign.Current.AllVillageTypes;

		public MBReadOnlyList<(ItemObject, float)> Productions => _productions;

		public ItemObject PrimaryProduction
		{
			get
			{
				(ItemObject, float) tuple = _productions[0];
				float num = 0f;
				foreach (var production in _productions)
				{
					if (production.Item2 * (float)production.Item1.Value > num)
					{
						tuple = production;
						num = production.Item2 * (float)production.Item1.Value;
					}
				}
				return tuple.Item1;
			}
		}

		internal static void AutoGeneratedStaticCollectObjectsVillageType(object o, List<object> collectedObjects)
		{
			((VillageType)o).AutoGeneratedInstanceCollectObjects(collectedObjects);
		}

		protected override void AutoGeneratedInstanceCollectObjects(List<object> collectedObjects)
		{
			base.AutoGeneratedInstanceCollectObjects(collectedObjects);
		}

		public VillageType(string stringId)
			: base(stringId)
		{
		}

		public VillageType Initialize(TextObject shortName, string meshName, string meshNameUnderConstruction, string meshNameBurned, (ItemObject, float)[] productions)
		{
			ShortName = shortName;
			MeshName = meshName;
			MeshNameUnderConstruction = meshNameUnderConstruction;
			MeshNameBurned = meshNameBurned;
			_productions = productions.ToMBList();
			AfterInitialized();
			return this;
		}

		public override string ToString()
		{
			return ShortName.ToString();
		}

		public void AddProductions(IEnumerable<(ItemObject, float)> productions)
		{
			_productions = productions.Concat(_productions).ToMBList();
		}

		public float GetProductionPerDay(ItemObject item)
		{
			foreach (var production in _productions)
			{
				if (production.Item1 == item)
				{
					return production.Item2;
				}
			}
			return 0f;
		}

		public float GetProductionPerDay(ItemCategory itemCategory)
		{
			float num = 0f;
			foreach (var production in _productions)
			{
				if (production.Item1 != null && production.Item1.ItemCategory == itemCategory)
				{
					num += production.Item2;
				}
			}
			return num;
		}
	}
