		{
			int num = 0;
			string[] sceneNames = _sceneNames;
			for (int i = 0; i < sceneNames.Length; i++)
			{
				if (!string.IsNullOrEmpty(sceneNames[i]))
				{
					num++;
				}
			}
			return num;
		}

