		public bool IsAllyWithKingdom(Kingdom kingdom1, Kingdom kingdom2)
		{
			if (kingdom1 == null || kingdom2 == null || kingdom1 == kingdom2 || kingdom1.IsEliminated || kingdom2.IsEliminated)
			{
				return false;
			}
			Alliance foundAlliance;
			return TryGetAlliance(kingdom1, kingdom2, out foundAlliance);
		}

		public void StartAlliance(Kingdom proposerKingdom, Kingdom receiverKingdom)
		{
			if (IsAllyWithKingdom(proposerKingdom, receiverKingdom))
			{
				return;
			}
			StanceLink stanceWith = proposerKingdom.GetStanceWith(receiverKingdom);
			if (stanceWith.GetDailyTributeToPay(proposerKingdom) != 0)
			{
				stanceWith.SetDailyTributePaid(proposerKingdom, 0, 0);
			}
			if (stanceWith.GetDailyTributeToPay(proposerKingdom) != 0)
			{
				stanceWith.SetDailyTributePaid(proposerKingdom, 0, 0);
			}
			AddAlliance(proposerKingdom, receiverKingdom);
			CampaignEventDispatcher.Instance.OnAllianceStarted(proposerKingdom, receiverKingdom);
			foreach (IFaction item in proposerKingdom.FactionsAtWarWith.WhereQ((IFaction f) => f.IsKingdomFaction && !f.IsAtWarWith(receiverKingdom)).ToList())
			{
				if (proposerKingdom == Clan.PlayerClan.Kingdom && !Hero.MainHero.Clan.IsUnderMercenaryService)
				{
					OnCallToWarAgreementProposedByPlayerKingdom(receiverKingdom, (Kingdom)item);
					continue;
				}
				ProposeCallToWarAgreementDecision kingdomDecision = new ProposeCallToWarAgreementDecision(proposerKingdom.RulingClan, receiverKingdom, (Kingdom)item);
				proposerKingdom.AddDecision(kingdomDecision, ignoreInfluenceCost: true);
			}
			foreach (IFaction item2 in receiverKingdom.FactionsAtWarWith.WhereQ((IFaction f) => f.IsKingdomFaction && !f.IsAtWarWith(proposerKingdom)).ToList())
			{
				if (receiverKingdom == Clan.PlayerClan.Kingdom && !Hero.MainHero.Clan.IsUnderMercenaryService)
				{
					OnCallToWarAgreementProposedByPlayerKingdom(proposerKingdom, (Kingdom)item2);
					continue;
				}
				ProposeCallToWarAgreementDecision kingdomDecision2 = new ProposeCallToWarAgreementDecision(receiverKingdom.RulingClan, proposerKingdom, (Kingdom)item2);
				receiverKingdom.AddDecision(kingdomDecision2, ignoreInfluenceCost: true);
			}
		}

		public void EndAlliance(Kingdom kingdom1, Kingdom kingdom2)
		{
			foreach (CallToWarAgreement callToWarAgreement in GetCallToWarAgreements(kingdom1, kingdom2))
			{
				EndCallToWarAgreement(callToWarAgreement.CallingKingdom, callToWarAgreement.CalledKingdom, callToWarAgreement.KingdomToCallToWarAgainst);
			}
			RemoveAlliance(kingdom1, kingdom2);
			CampaignEventDispatcher.Instance.OnAllianceEnded(kingdom1, kingdom2);
		}

		public bool HasCalledToWar(Kingdom callingKingdom, Kingdom calledKingdom)
		{
			if (callingKingdom == null || calledKingdom == null || callingKingdom == calledKingdom || callingKingdom.IsEliminated || calledKingdom.IsEliminated || !calledKingdom.IsAllyWith(callingKingdom))
			{
				return false;
			}
			return _callToWarAgreements.AnyQ((CallToWarAgreement c) => c.CallingKingdom == callingKingdom && c.CalledKingdom == calledKingdom);
		}

		public bool IsAtWarByCallToWarAgreement(Kingdom calledKingdom, Kingdom kingdomToCallToWarAgainst, out Kingdom callingKingdom)
		{
			callingKingdom = null;
			if (kingdomToCallToWarAgainst == null || calledKingdom == null || kingdomToCallToWarAgainst == calledKingdom || kingdomToCallToWarAgainst.IsEliminated || calledKingdom.IsEliminated)
			{
				return false;
			}
			for (int i = 0; i < _callToWarAgreements.Count; i++)
			{
				CallToWarAgreement callToWarAgreement = _callToWarAgreements[i];
				if (callToWarAgreement.CalledKingdom == calledKingdom && callToWarAgreement.KingdomToCallToWarAgainst == kingdomToCallToWarAgainst)
				{
					callingKingdom = callToWarAgreement.CallingKingdom;
					return true;
				}
			}
			return false;
		}

		public void StartCallToWarAgreement(Kingdom callingKingdom, Kingdom calledKingdom, Kingdom kingdomToCallToWarAgainst, int callToWarCost, bool isPlayerPaying = false)
		{
			if (IsAllyWithKingdom(callingKingdom, calledKingdom) && !calledKingdom.IsAtWarWith(kingdomToCallToWarAgainst))
			{
				UpdateAllianceEndTime(callingKingdom, calledKingdom, AddCallToWarAgreement(callingKingdom, calledKingdom, kingdomToCallToWarAgainst).EndTime);
				if (isPlayerPaying)
				{
					Hero.MainHero.ChangeHeroGold(-callToWarCost);
					calledKingdom.CallToWarWallet += callToWarCost;
				}
				else
				{
					callingKingdom.CallToWarWallet -= callToWarCost;
					calledKingdom.CallToWarWallet += callToWarCost;
				}
				CampaignEventDispatcher.Instance.OnCallToWarAgreementStarted(callingKingdom, calledKingdom, kingdomToCallToWarAgainst);
				ApplyAcceptingCallToWarOfferBonus(callingKingdom, calledKingdom);
				DeclareWarAction.ApplyByCallToWarAgreement(calledKingdom, kingdomToCallToWarAgainst);
			}
		}

		public void EndCallToWarAgreement(Kingdom callingKingdom, Kingdom calledKingdom, Kingdom kingdomToCallToWarAgainst)
		{
			RemoveCallToWarAgreement(callingKingdom, calledKingdom, kingdomToCallToWarAgainst);
			CampaignEventDispatcher.Instance.OnCallToWarAgreementEnded(callingKingdom, calledKingdom, kingdomToCallToWarAgainst);
		}

		public void DenyCallToWarAgreement(Kingdom callingKingdom, Kingdom calledKingdom)
		{
			ApplyDenyingCallToWarOfferPenalty(callingKingdom, calledKingdom);
		}

		public List<Kingdom> GetKingdomsToCallToWarAgainst(Kingdom callingKingdom, Kingdom calledKingdom)
		{
			if (callingKingdom != calledKingdom)
			{
				return _callToWarAgreements.WhereQ((CallToWarAgreement c) => c.CallingKingdom == callingKingdom && c.CalledKingdom == calledKingdom).SelectQ((CallToWarAgreement x) => x.KingdomToCallToWarAgainst).ToListQ();
			}
			return new List<Kingdom>();
		}

		private Alliance AddAlliance(Kingdom kingdom1, Kingdom kingdom2)
		{
			Alliance alliance = new Alliance(kingdom1, kingdom2, CampaignTime.Now + Campaign.Current.Models.AllianceModel.MaxDurationOfAlliance);
			_alliances.Add(alliance);
			kingdom1.UpdateAlliedKingdoms();
			kingdom2.UpdateAlliedKingdoms();
			return alliance;
		}

		private void RemoveAlliance(Kingdom kingdom1, Kingdom kingdom2)
		{
			int num = _alliances.Count - 1;
			while (-1 < num)
			{
				Alliance alliance = _alliances[num];
				if ((alliance.Kingdom1 == kingdom1 && alliance.Kingdom2 == kingdom2) || (alliance.Kingdom2 == kingdom1 && alliance.Kingdom1 == kingdom2))
				{
					_alliances.RemoveAt(num);
					break;
				}
				num--;
			}
			kingdom1.UpdateAlliedKingdoms();
			kingdom2.UpdateAlliedKingdoms();
		}

		private CallToWarAgreement AddCallToWarAgreement(Kingdom callingKingdom, Kingdom calledKingdom, Kingdom kingdomToCallToWarAgainst)
		{
			CallToWarAgreement callToWarAgreement = new CallToWarAgreement(callingKingdom, calledKingdom, kingdomToCallToWarAgainst, CampaignTime.Now + Campaign.Current.Models.AllianceModel.MaxDurationOfWarParticipation);
			_callToWarAgreements.Add(callToWarAgreement);
			return callToWarAgreement;
		}

		private void RemoveCallToWarAgreement(Kingdom callingKingdom, Kingdom calledKingdom, Kingdom kingdomToCallToWarAgainst)
		{
			int num = _callToWarAgreements.Count - 1;
			while (-1 < num)
			{
				CallToWarAgreement callToWarAgreement = _callToWarAgreements[num];
				if (callToWarAgreement.CallingKingdom == callingKingdom && callToWarAgreement.CalledKingdom == calledKingdom && callToWarAgreement.KingdomToCallToWarAgainst == kingdomToCallToWarAgainst)
				{
					_callToWarAgreements.RemoveAt(num);
					break;
				}
				num--;
			}
		}

		private List<CallToWarAgreement> GetCallToWarAgreements(Kingdom kingdom1, Kingdom kingdom2)
		{
			if (kingdom1 != kingdom2)
			{
				return _callToWarAgreements.Where((CallToWarAgreement c) => (c.CallingKingdom == kingdom1 && c.CalledKingdom == kingdom2) || (c.CallingKingdom == kingdom2 && c.CalledKingdom == kingdom1)).ToListQ();
			}
			return new List<CallToWarAgreement>();
		}

		private bool TryGetAlliance(Kingdom kingdom1, Kingdom kingdom2, out Alliance foundAlliance)
		{
			bool result = false;
			foundAlliance = default(Alliance);
			foreach (Alliance alliance in _alliances)
			{
				if ((alliance.Kingdom1 == kingdom1 && alliance.Kingdom2 == kingdom2) || (alliance.Kingdom2 == kingdom1 && alliance.Kingdom1 == kingdom2))
				{
					foundAlliance = alliance;
					result = true;
					break;
				}
			}
			return result;
		}

		private void UpdateAllianceEndTime(Kingdom kingdom1, Kingdom kingdom2, CampaignTime newEndTime)
		{
			for (int i = 0; i < _alliances.Count; i++)
			{
				Alliance alliance = _alliances[i];
				if (((alliance.Kingdom1 == kingdom1 && alliance.Kingdom2 == kingdom2) || (alliance.Kingdom2 == kingdom1 && alliance.Kingdom1 == kingdom2)) && alliance.EndTime < newEndTime)
				{
					_alliances[i] = new Alliance(_alliances[i].Kingdom1, _alliances[i].Kingdom2, newEndTime);
					break;
				}
			}
		}

		private void AcceptStartingAlliance(Kingdom proposerKingdom)
		{
			StartAlliance(proposerKingdom, Clan.PlayerClan.Kingdom);
		}

		private void ConfirmAllianceOffer(Kingdom proposerKingdom)
		{
			if (Clan.PlayerClan.IsUnderMercenaryService)
			{
				AcceptStartingAlliance(proposerKingdom);
			}
			else
			{
				AddAllianceDecision(Clan.PlayerClan.Kingdom, proposerKingdom);
			}
		}

		private void ConfirmCallToWarAgreementProposalOffer(Kingdom proposedKingdom, Kingdom kingdomToCallToWarAgainst)
		{
			ProposeCallToWarAgreementDecision proposeCallToWarAgreementDecision = new ProposeCallToWarAgreementDecision(Clan.PlayerClan, proposedKingdom, kingdomToCallToWarAgainst);
			int callToWarCost = proposeCallToWarAgreementDecision.CallToWarCost;
			if (Clan.PlayerClan.IsUnderMercenaryService)
			{
				StartCallToWarAgreement(Clan.PlayerClan.Kingdom, proposedKingdom, kingdomToCallToWarAgainst, callToWarCost);
				return;
			}
			KingdomDecision kingdomDecision = Clan.PlayerClan.Kingdom.UnresolvedDecisions.FirstOrDefault((KingdomDecision s) => s is ProposeCallToWarAgreementDecision proposeCallToWarAgreementDecision2 && proposeCallToWarAgreementDecision2.CalledKingdom == proposedKingdom && proposeCallToWarAgreementDecision2.KingdomToCallToWarAgainst == kingdomToCallToWarAgainst);
			if (kingdomDecision != null)
			{
				Clan.PlayerClan.Kingdom.RemoveDecision(kingdomDecision);
			}
			Clan.PlayerClan.Kingdom.AddDecision(proposeCallToWarAgreementDecision, ignoreInfluenceCost: true);
		}

		private void ConfirmCallToWarAgreementOffer(Kingdom proposerKingdom, Kingdom kingdomToCallToWarAgainst)
		{
			AcceptCallToWarAgreementDecision acceptCallToWarAgreementDecision = new AcceptCallToWarAgreementDecision(Clan.PlayerClan, proposerKingdom, kingdomToCallToWarAgainst);
			int callToWarCost = acceptCallToWarAgreementDecision.CallToWarCost;
			if (Clan.PlayerClan.IsUnderMercenaryService)
			{
				StartCallToWarAgreement(proposerKingdom, Clan.PlayerClan.Kingdom, kingdomToCallToWarAgainst, callToWarCost);
				return;
			}
			KingdomDecision kingdomDecision = Clan.PlayerClan.Kingdom.UnresolvedDecisions.FirstOrDefault((KingdomDecision s) => s is AcceptCallToWarAgreementDecision acceptCallToWarAgreementDecision2 && acceptCallToWarAgreementDecision2.CallingKingdom == proposerKingdom && acceptCallToWarAgreementDecision2.KingdomToCallToWarAgainst == kingdomToCallToWarAgainst);
			if (kingdomDecision != null)
			{
				Clan.PlayerClan.Kingdom.RemoveDecision(kingdomDecision);
			}
			Clan.PlayerClan.Kingdom.AddDecision(acceptCallToWarAgreementDecision, ignoreInfluenceCost: true);
		}

		private void ApplyBrokenAlliancePenalty(Kingdom kingdom, Kingdom otherKingdom, DeclareWarAction.DeclareWarDetail detail)
		{
			Hero obj = ((detail == DeclareWarAction.DeclareWarDetail.CausedByPlayerHostility) ? Hero.MainHero : kingdom.Leader);
			ChangeRelationAction.ApplyRelationChangeBetweenHeroes(obj, otherKingdom.Leader, -100);
			if (obj == Hero.MainHero)
			{
				TraitLevelingHelper.OnAllianceBrokenThroughHostility();
			}
		}

		private void ApplyDenyingCallToWarOfferPenalty(Kingdom callingKingdom, Kingdom calledKingdom)
		{
			ChangeRelationAction.ApplyRelationChangeBetweenHeroes(calledKingdom.Leader, callingKingdom.Leader, -50);
		}

		private void ApplyAcceptingCallToWarOfferBonus(Kingdom callingKingdom, Kingdom calledKingdom)
		{
			ChangeRelationAction.ApplyRelationChangeBetweenHeroes(calledKingdom.Leader, callingKingdom.Leader, 10);
		}

		private void AddAllianceDecision(Kingdom kingdomToAddDecision, Kingdom kingdomToOffer)
		{
			KingdomDecision kingdomDecision = kingdomToAddDecision.UnresolvedDecisions.FirstOrDefault((KingdomDecision s) => s is StartAllianceDecision startAllianceDecision2 && startAllianceDecision2.KingdomToStartAllianceWith == kingdomToOffer);
			if (kingdomDecision != null)
			{
				kingdomToAddDecision.RemoveDecision(kingdomDecision);
			}
			StartAllianceDecision startAllianceDecision = new StartAllianceDecision(Campaign.Current.Models.AllianceModel.GetProposerClanForAllianceDecision(kingdomToAddDecision, kingdomToOffer), kingdomToOffer);
			if (startAllianceDecision.CanMakeDecision(out var _))
			{
				kingdomToAddDecision.AddDecision(startAllianceDecision, ignoreInfluenceCost: true);
			}
		}

		private static void RefreshAlliedKingdoms()
		{
			foreach (Kingdom item in Kingdom.All)
			{
				item.UpdateAlliedKingdoms();
			}
		}

		private void DailyTickClan(Clan clan)
		{
			if (clan.IsEliminated)
			{
				return;
			}
			clan.Aggressiveness -= 1f;
			if (clan.Kingdom == null || clan.Kingdom.RulingClan != clan)
			{
				return;
			}
			Kingdom kingdom = clan.Kingdom;
			if (kingdom.AlliedKingdoms.IsEmpty())
			{
				return;
			}
			for (int num = kingdom.AlliedKingdoms.Count - 1; num > -1; num--)
			{
				Kingdom kingdom2 = kingdom.AlliedKingdoms[num];
				if (TryGetAlliance(kingdom2, kingdom, out var foundAlliance))
				{
					List<CallToWarAgreement> callToWarAgreements = GetCallToWarAgreements(kingdom, kingdom2);
					for (int num2 = callToWarAgreements.Count - 1; num2 > -1; num2--)
					{
						CallToWarAgreement callToWarAgreement = callToWarAgreements[num2];
						if (callToWarAgreement.EndTime.IsPast)
						{
							EndCallToWarAgreement(callToWarAgreement.CallingKingdom, callToWarAgreement.CalledKingdom, callToWarAgreement.KingdomToCallToWarAgainst);
						}
					}
					if (foundAlliance.EndTime.IsPast)
					{
						EndAlliance(kingdom, kingdom2);
						if (kingdom == Clan.PlayerClan.Kingdom)
						{
							AddAllianceDecision(kingdom, kingdom2);
						}
						else
						{
							AddAllianceDecision(kingdom2, kingdom);
						}
					}
				}
			}
		}

		private void OnWarDeclared(IFaction faction1, IFaction faction2, DeclareWarAction.DeclareWarDetail detail)
		{
			if (!faction1.IsKingdomFaction || !faction2.IsKingdomFaction)
			{
				return;
			}
			Kingdom kingdom = (Kingdom)faction1;
			Kingdom kingdom2 = (Kingdom)faction2;
			if (kingdom.IsAllyWith(kingdom2))
			{
				ApplyBrokenAlliancePenalty(kingdom, kingdom2, detail);
				EndAlliance(kingdom, kingdom2);
			}
			foreach (Kingdom item in kingdom.AlliedKingdoms.ToList())
			{
				if (!item.IsAtWarWith(kingdom2))
				{
					if (kingdom == Clan.PlayerClan.Kingdom && !Hero.MainHero.Clan.IsUnderMercenaryService)
					{
						OnCallToWarAgreementProposedByPlayerKingdom(item, kingdom2);
						continue;
					}
					ProposeCallToWarAgreementDecision kingdomDecision = new ProposeCallToWarAgreementDecision(kingdom.RulingClan, item, kingdom2);
					kingdom.AddDecision(kingdomDecision, ignoreInfluenceCost: true);
				}
			}
			foreach (Kingdom item2 in kingdom2.AlliedKingdoms.ToList())
			{
				if (!item2.IsAtWarWith(kingdom))
				{
					if (kingdom2 == Clan.PlayerClan.Kingdom && !Hero.MainHero.Clan.IsUnderMercenaryService)
					{
						OnCallToWarAgreementProposedByPlayerKingdom(item2, kingdom);
						continue;
					}
					ProposeCallToWarAgreementDecision kingdomDecision2 = new ProposeCallToWarAgreementDecision(kingdom2.RulingClan, item2, kingdom);
					kingdom2.AddDecision(kingdomDecision2, ignoreInfluenceCost: true);
				}
			}
		}

		private void OnMakePeace(IFaction faction1, IFaction faction2, MakePeaceAction.MakePeaceDetail detail)
		{
			if (!faction1.IsKingdomFaction || !faction2.IsKingdomFaction)
			{
				return;
			}
			Kingdom kingdom1 = (Kingdom)faction1;
			Kingdom kingdom2 = (Kingdom)faction2;
			foreach (Kingdom ally2 in kingdom1.AlliedKingdoms)
			{
				if (_callToWarAgreements.AnyQ((CallToWarAgreement c) => c.CallingKingdom == kingdom1 && c.CalledKingdom == ally2 && c.KingdomToCallToWarAgainst == kingdom2))
				{
					EndCallToWarAgreement(kingdom1, ally2, kingdom2);
				}
			}
			foreach (Kingdom ally in kingdom2.AlliedKingdoms)
			{
				if (_callToWarAgreements.AnyQ((CallToWarAgreement c) => c.CallingKingdom == kingdom2 && c.CalledKingdom == ally && c.KingdomToCallToWarAgainst == kingdom1))
				{
					EndCallToWarAgreement(kingdom2, ally, kingdom1);
				}
			}
		}

		private void OnKingdomDestroyed(Kingdom kingdom)
		{
			foreach (Alliance item in _alliances.Where((Alliance a) => a.Kingdom1 == kingdom || a.Kingdom2 == kingdom).ToList())
			{
				EndAlliance(item.Kingdom1, item.Kingdom2);
			}
		}

		private void OnGameLoadFinished()
		{
			if (MBSaveLoad.IsUpdatingGameVersion && MBSaveLoad.LastLoadedGameVersion.IsOlderThan(ApplicationVersion.FromString("v1.4.0.110693")))
			{
				for (int i = 0; i < _callToWarAgreements.Count; i++)
				{
					CallToWarAgreement callToWarAgreement = _callToWarAgreements[i];
					UpdateAllianceEndTime(callToWarAgreement.CallingKingdom, callToWarAgreement.CalledKingdom, callToWarAgreement.EndTime);
				}
			}
		}

		private void OnNewGameCreated(CampaignGameStarter starter)
		{
			RefreshAlliedKingdoms();
		}

		private void OnGameLoaded(CampaignGameStarter starter)
		{
			RefreshAlliedKingdoms();
		}
	}
	public class BackstoryCampaignBehavior : CampaignBehaviorBase
	{
		public override void RegisterEvents()
		{
			CampaignEvents.OnNewGameCreatedEvent.AddNonSerializedListener(this, OnNewGameCreated);
		}

		public override void SyncData(IDataStore dataStore)
		{
		}

		public void OnNewGameCreated(CampaignGameStarter campaignGameStarter)
		{
			Hero heroObject = Game.Current.ObjectManager.GetObject<CharacterObject>("lord_1_7").HeroObject;
			Hero heroObject2 = Game.Current.ObjectManager.GetObject<CharacterObject>("lord_1_1").HeroObject;
			LogEntry.AddLogEntry(new CharacterInsultedLogEntry(heroObject, heroObject2, null, ActionNotes.ValorStrategyQuarrel), CampaignTime.Years(1075f) + CampaignTime.Weeks(3f) + CampaignTime.Days(2f));
			ChangeRelationAction.ApplyRelationChangeBetweenHeroes(heroObject, heroObject2, -50, showQuickNotification: false);
			Hero heroObject3 = Game.Current.ObjectManager.GetObject<CharacterObject>("lord_4_1").HeroObject;
			Hero heroObject4 = Game.Current.ObjectManager.GetObject<CharacterObject>("lord_4_16").HeroObject;
			LogEntry.AddLogEntry(new OverruleInfluenceLogEntry(heroObject3, heroObject4), CampaignTime.Years(1080f) + CampaignTime.Weeks(4f) + CampaignTime.Days(2f));
			Settlement @object = Game.Current.ObjectManager.GetObject<Settlement>("town_V6");
			LogEntry.AddLogEntry(new SettlementClaimedLogEntry(heroObject4, @object), CampaignTime.Years(1080f) + CampaignTime.Weeks(4f) + CampaignTime.Days(2f));
			ClaimSettlementAction.Apply(heroObject4, @object);
			Hero heroObject5 = Game.Current.ObjectManager.GetObject<CharacterObject>("lord_2_1").HeroObject;
			Hero heroObject6 = Game.Current.ObjectManager.GetObject<CharacterObject>("dead_lord_2_2").HeroObject;
			LogEntry.AddLogEntry(new CharacterKilledLogEntry(heroObject6, heroObject5, KillCharacterAction.KillCharacterActionDetail.Murdered), CampaignTime.Years(1080f) + CampaignTime.Weeks(4f) + CampaignTime.Days(2f));
			if (!heroObject6.Clan.IsMapFaction && heroObject6.Clan.Leader != null)
			{
				ChangeRelationAction.ApplyRelationChangeBetweenHeroes(heroObject5, heroObject6.Clan.Leader, -75, showQuickNotification: false);
			}
			Hero heroObject7 = Game.Current.ObjectManager.GetObject<CharacterObject>("lord_3_5").HeroObject;
			Hero nimr = Game.Current.ObjectManager.GetObject<CharacterObject>("dead_lord_3_1").HeroObject;
			LogEntry.AddLogEntry(new CharacterKilledLogEntry(nimr, heroObject7, KillCharacterAction.KillCharacterActionDetail.Murdered), CampaignTime.Years(1080f) + CampaignTime.Weeks(4f) + CampaignTime.Days(2f));
			foreach (Hero hero in nimr.Clan.Heroes)
			{
				if (hero.IsLord && hero.Age < (float)Campaign.Current.Models.AgeModel.MiddleAdultHoodAge && !hero.IsFemale && hero.GetTraitLevel(DefaultTraits.Mercy) < 1)
				{
					LogEntry.AddLogEntry(new CharacterInsultedLogEntry(hero, heroObject7, nimr.CharacterObject, ActionNotes.VengeanceQuarrel), CampaignTime.Years(1080f) + CampaignTime.Weeks(4f) + CampaignTime.Days(2f));
				}
			}
			foreach (Hero item in Hero.DeadOrDisabledHeroes.Where((Hero x) => x.Clan == nimr.Clan))
			{
				if (item.IsLord && item.Age < (float)Campaign.Current.Models.AgeModel.MiddleAdultHoodAge && !item.IsFemale && item.GetTraitLevel(DefaultTraits.Mercy) < 1)
				{
					LogEntry.AddLogEntry(new CharacterInsultedLogEntry(item, heroObject7, nimr.CharacterObject, ActionNotes.VengeanceQuarrel), CampaignTime.Years(1080f) + CampaignTime.Weeks(4f) + CampaignTime.Days(2f));
				}
			}
			if (nimr.Clan.Leader != null)
			{
				ChangeRelationAction.ApplyRelationChangeBetweenHeroes(heroObject7, nimr.Clan.Leader, -75, showQuickNotification: false);
			}
		}
	}
