	public class BanditSpawnCampaignBehavior : CampaignBehaviorBase
	{
		private const float BanditStartGoldPerBandit = 10f;

		private const float BanditLongTermGoldPerBandit = 50f;

		private const float HideoutInfestCooldownAfterFightInDays = 1.5f;

		private Dictionary<CultureObject, List<Hideout>> _hideouts = new Dictionary<CultureObject, List<Hideout>>();

		private Dictionary<Settlement, int> _banditCountsPerHideout = new Dictionary<Settlement, int>();

		private float BanditSpawnRadiusAsDays => 0.5f * Campaign.Current.EstimatedAverageBanditPartySpeed * (float)CampaignTime.HoursInDay;

		private float _radiusAroundPlayerPartySquared => MobileParty.MainParty.SeeingRange * MobileParty.MainParty.SeeingRange;

		private float _numberOfMinimumBanditPartiesInAHideoutToInfestIt => Campaign.Current.Models.BanditDensityModel.NumberOfMinimumBanditPartiesInAHideoutToInfestIt;

		private int _numberOfMaxBanditPartiesAroundEachHideout => Campaign.Current.Models.BanditDensityModel.NumberOfMaximumBanditPartiesAroundEachHideout;

		private int _numberOfMaxHideoutsAtEachBanditFaction => Campaign.Current.Models.BanditDensityModel.NumberOfMaximumHideoutsAtEachBanditFaction;

		private int _numberOfInitialHideoutsAtEachBanditFaction => Campaign.Current.Models.BanditDensityModel.NumberOfInitialHideoutsAtEachBanditFaction;

		private int _numberOfMaximumBanditPartiesInEachHideout => Campaign.Current.Models.BanditDensityModel.NumberOfMaximumBanditPartiesInEachHideout;

		private int _numberOfMaxBanditCountPerClanHideout => _numberOfMaxBanditPartiesAroundEachHideout + _numberOfMaximumBanditPartiesInEachHideout;

		public override void RegisterEvents()
		{
			CampaignEvents.MobilePartyCreated.AddNonSerializedListener(this, MobilePartyCreated);
			CampaignEvents.MobilePartyDestroyed.AddNonSerializedListener(this, MobilePartyDestroyed);
			CampaignEvents.SettlementEntered.AddNonSerializedListener(this, OnSettlementEntered);
			CampaignEvents.DailyTickEvent.AddNonSerializedListener(this, DailyTick);
			CampaignEvents.HourlyTickClanEvent.AddNonSerializedListener(this, HourlyTickClan);
			CampaignEvents.OnGameLoadedEvent.AddNonSerializedListener(this, OnGameLoaded);
			CampaignEvents.OnHomeHideoutChangedEvent.AddNonSerializedListener(this, OnHomeHideoutChanged);
			CampaignEvents.OnNewGameCreatedPartialFollowUpEvent.AddNonSerializedListener(this, OnNewGameCreatedPartialFollowUp);
		}

		private void MobilePartyDestroyed(MobileParty party, PartyBase destroyerParty)
		{
			if (party.IsBandit && party.ActualClan != null && (IsBanditFaction(party.ActualClan) || IsLooterFaction(party.ActualClan)))
			{
				int value = 0;
				_banditCountsPerHideout.TryGetValue(party.HomeSettlement, out value);
				_banditCountsPerHideout[party.HomeSettlement] = value - 1;
			}
		}

		private void MobilePartyCreated(MobileParty party)
		{
			if (party.IsBandit && party.ActualClan != null && (IsBanditFaction(party.ActualClan) || IsLooterFaction(party.ActualClan)))
			{
				int value = 0;
				_banditCountsPerHideout.TryGetValue(party.HomeSettlement, out value);
				_banditCountsPerHideout[party.HomeSettlement] = value + 1;
			}
		}

		private void OnGameLoaded(CampaignGameStarter starter)
		{
			CacheHideouts();
			CacheBanditCounts();
		}

		public override void SyncData(IDataStore dataStore)
		{
		}

		private void OnNewGameCreatedPartialFollowUp(CampaignGameStarter starter, int i)
		{
			switch (i)
			{
			case 10:
				CacheHideouts();
				if (_numberOfInitialHideoutsAtEachBanditFaction > 0)
				{
					InitializeInitialHideouts();
				}
				break;
			case 11:
				SpawnBanditsAroundHideoutAtNewGame();
				SpawnLootersAtNewGame();
				CacheBanditCounts();
				break;
			}
		}

		private void CacheHideouts()
		{
			foreach (Hideout item in Hideout.All)
			{
				if (!_hideouts.TryGetValue(item.Settlement.Culture, out var _))
				{
					_hideouts[item.Settlement.Culture] = new List<Hideout>();
				}
				_hideouts[item.Settlement.Culture].Add(item);
			}
		}

		private void CacheBanditCounts()
		{
			_banditCountsPerHideout = new Dictionary<Settlement, int>();
			foreach (MobileParty allBanditParty in MobileParty.AllBanditParties)
			{
				if (IsBanditFaction(allBanditParty.ActualClan) || IsLooterFaction(allBanditParty.ActualClan))
				{
					int value = 0;
					_banditCountsPerHideout.TryGetValue(allBanditParty.HomeSettlement, out value);
					_banditCountsPerHideout[allBanditParty.HomeSettlement] = value + 1;
				}
			}
		}

		public void InitializeInitialHideouts()
		{
			foreach (Clan banditFaction in Clan.BanditFactions)
			{
				if (IsBanditFaction(banditFaction))
				{
					SpawnHideoutsAndBanditsPartiallyOnNewGame(banditFaction);
				}
			}
		}

		private void SpawnHideoutsAndBanditsPartiallyOnNewGame(Clan banditClan)
		{
			for (int i = 0; i < _numberOfInitialHideoutsAtEachBanditFaction; i++)
			{
				FillANewHideoutWithBandits(banditClan);
			}
		}

		public void OnSettlementEntered(MobileParty mobileParty, Settlement settlement, Hero hero)
		{
			CheckForSpawningBanditBoss(settlement, mobileParty);
			if (!Campaign.Current.GameStarted || mobileParty == null || !mobileParty.IsBandit || !settlement.IsHideout)
			{
				return;
			}
			if (!settlement.Hideout.IsSpotted && settlement.Hideout.IsInfested && mobileParty.IsVisible)
			{
				settlement.Hideout.IsSpotted = true;
				settlement.Party.UpdateVisibilityAndInspected(MobileParty.MainParty.Position);
				CampaignEventDispatcher.Instance.OnHideoutSpotted(MobileParty.MainParty.Party, settlement.Party);
			}
			int num = 0;
			foreach (ItemRosterElement item in mobileParty.ItemRoster)
			{
				int num2 = (item.EquipmentElement.Item.IsFood ? MBRandom.RoundRandomized((float)mobileParty.MemberRoster.TotalManCount * ((3f + 6f * MBRandom.RandomFloat) / (float)item.EquipmentElement.Item.Value)) : 0);
				if (item.Amount > num2)
				{
					int num3 = item.Amount - num2;
					num += num3 * item.EquipmentElement.Item.Value;
				}
			}
			if (num > 0)
			{
				if (mobileParty.IsPartyTradeActive)
				{
					mobileParty.PartyTradeGold += (int)(0.25f * (float)num);
				}
				settlement.SettlementComponent.ChangeGold((int)(0.25f * (float)num));
			}
		}

		private void CheckForSpawningBanditBoss(Settlement settlement, MobileParty mobileParty)
		{
			if (settlement.IsHideout && settlement.Hideout.IsSpotted && settlement.Parties.Any((MobileParty x) => x.IsBandit || x.IsBanditBossParty))
			{
				CultureObject culture = settlement.Culture;
				MobileParty mobileParty2 = settlement.Parties.FirstOrDefault((MobileParty x) => x.IsBanditBossParty);
				if (mobileParty2 == null)
				{
					AddBossParty(settlement, culture);
				}
				else if (!mobileParty2.MemberRoster.Contains(culture.BanditBoss))
				{
					mobileParty2.MemberRoster.AddToCounts(culture.BanditBoss, 1);
				}
			}
		}

		private void AddBossParty(Settlement settlement, CultureObject culture)
		{
			PartyTemplateObject banditBossPartyTemplate = culture.BanditBossPartyTemplate;
			if (banditBossPartyTemplate != null)
			{
				AddBanditToHideout(settlement.Hideout, banditBossPartyTemplate, isBanditBossParty: true).Ai.DisableAi();
			}
		}

		public void DailyTick()
		{
			if (_numberOfMaxHideoutsAtEachBanditFaction > 0)
			{
				AddNewHideouts();
			}
			foreach (MobileParty allBanditParty in MobileParty.AllBanditParties)
			{
				if (!allBanditParty.IsPartyTradeActive)
				{
					continue;
				}
				allBanditParty.PartyTradeGold = (int)((double)allBanditParty.PartyTradeGold * 0.95 + (double)(50f * (float)allBanditParty.Party.MemberRoster.TotalManCount * 0.05f));
				if (!(MBRandom.RandomFloat < 0.03f) || allBanditParty.MapEvent == null)
				{
					continue;
				}
				foreach (ItemObject item in Items.All)
				{
					if (item.IsFood)
					{
						int num = (IsLooterFaction(allBanditParty.MapFaction) ? 8 : 16);
						int num2 = MBRandom.RoundRandomized((float)allBanditParty.MemberRoster.TotalManCount * (1f / (float)item.Value) * (float)num * MBRandom.RandomFloat * MBRandom.RandomFloat * MBRandom.RandomFloat * MBRandom.RandomFloat);
						if (num2 > 0)
						{
							allBanditParty.ItemRoster.AddToCounts(item, num2);
						}
					}
				}
			}
		}

		private void HourlyTickClan(Clan clan)
		{
			if (Campaign.Current.IsNight && clan.IsBanditFaction)
			{
				if (IsLooterFaction(clan))
				{
					SpawnLooters(clan, 0.07f, uniformDistribution: false);
				}
				else if (IsBanditFaction(clan))
				{
					SpawnBanditsAroundHideout(clan, 0.1f);
				}
			}
		}

		private void SpawnBanditsAroundHideout(Clan clan, float ratio)
		{
			int count = clan.WarPartyComponents.Count;
			int num = MBRandom.RoundRandomized((float)(GetInfestedHideoutCount(clan) * _numberOfMaxBanditCountPerClanHideout - count) * ratio);
			for (int i = 0; i < num; i++)
			{
				SpawnBanditParty(clan);
			}
		}

		private void SpawnLooters(Clan clan, float ratio, bool uniformDistribution)
		{
			int count = clan.WarPartyComponents.Count;
			int num = MBRandom.RoundRandomized((float)(GetCurrentLimitForLooters(clan) - count) * ratio);
			for (int i = 0; i < num; i++)
			{
				SpawnLooterParty(clan, uniformDistribution);
			}
		}

		private void AddNewHideouts()
		{
			List<((Clan, int), float)> list = new List<((Clan, int), float)>();
			foreach (Clan banditFaction in Clan.BanditFactions)
			{
				if (IsBanditFaction(banditFaction))
				{
					int infestedHideoutCount = GetInfestedHideoutCount(banditFaction);
					if (infestedHideoutCount < _numberOfMaxHideoutsAtEachBanditFaction)
					{
						list.Add(((banditFaction, infestedHideoutCount), 1f - (float)infestedHideoutCount / (float)_numberOfMaxHideoutsAtEachBanditFaction));
					}
				}
			}
			var (clan, num) = MBRandom.ChooseWeighted(list, out var _);
			if (clan != null)
			{
				float num2 = (((float)num < (float)_numberOfMaxHideoutsAtEachBanditFaction * 0.5f) ? (0.2f + (float)(_numberOfMaxHideoutsAtEachBanditFaction - num) * 0.1f) : (0.1f + 0.5f * TaleWorlds.Library.MathF.Pow(1f - 0.25f * ((float)num - (float)_numberOfMaxHideoutsAtEachBanditFaction * 0.5f), 3f)));
				if (MBRandom.RandomFloat < num2)
				{
					FillANewHideoutWithBandits(clan);
				}
			}
		}

		private void FillANewHideoutWithBandits(Clan faction)
		{
			Hideout hideout = SelectANonInfestedHideoutOfSameCultureByWeight(faction);
			if (hideout != null)
			{
				for (int i = 0; (float)i < _numberOfMinimumBanditPartiesInAHideoutToInfestIt; i++)
				{
					AddBanditToHideout(hideout);
				}
			}
		}

		public MobileParty AddBanditToHideout(Hideout hideoutComponent, PartyTemplateObject overridenPartyTemplate = null, bool isBanditBossParty = false)
		{
			if (hideoutComponent.Owner.Settlement.Culture.IsBandit)
			{
				Clan clan = null;
				foreach (Clan banditFaction in Clan.BanditFactions)
				{
					if (hideoutComponent.Owner.Settlement.Culture == banditFaction.Culture && (IsBanditFaction(banditFaction) || IsLooterFaction(banditFaction)))
					{
						clan = banditFaction;
					}
				}
				PartyTemplateObject pt = overridenPartyTemplate ?? clan.DefaultPartyTemplate;
				MobileParty mobileParty = BanditPartyComponent.CreateBanditParty(clan.StringId + "_1", clan, hideoutComponent, isBanditBossParty, pt, hideoutComponent.Owner.Settlement.GatePosition);
				InitializeBanditParty(mobileParty, clan);
				mobileParty.SetMoveGoToSettlement(hideoutComponent.Owner.Settlement, mobileParty.NavigationCapability, isTargetingThePort: false);
				mobileParty.RecalculateShortTermBehavior();
				EnterSettlementAction.ApplyForParty(mobileParty, hideoutComponent.Owner.Settlement);
				return mobileParty;
			}
			return null;
		}

		private Hideout SelectBanditHideout(Clan faction)
		{
			MBList<(Hideout, float)> mBList = new MBList<(Hideout, float)>();
			foreach (Hideout item in Hideout.All)
			{
				if (item.Settlement.Culture == faction.Culture && item.IsInfested)
				{
					mBList.Add((item, GetSpawnChanceInSettlement(item.Settlement)));
				}
			}
			if (mBList.Count != 0)
			{
				return MBRandom.ChooseWeighted(mBList);
			}
			return SelectAHideoutByCheckingCultureAndInfestedState(faction);
		}

		private float GetSpawnChanceInSettlement(Settlement settlement)
		{
			if (_banditCountsPerHideout.ContainsKey(settlement) && _banditCountsPerHideout[settlement] != 0)
			{
				return 1f / TaleWorlds.Library.MathF.Pow(_banditCountsPerHideout[settlement], 2f);
			}
			return 1f;
		}

		private void OnHomeHideoutChanged(BanditPartyComponent banditPartyComponent, Hideout oldHomeHideout)
		{
			int value = 0;
			_banditCountsPerHideout.TryGetValue(oldHomeHideout.Settlement, out value);
			_banditCountsPerHideout[oldHomeHideout.Settlement] = value - 1;
			value = 0;
			_banditCountsPerHideout.TryGetValue(banditPartyComponent.HomeSettlement, out value);
			_banditCountsPerHideout[banditPartyComponent.HomeSettlement] = value + 1;
		}

		private Hideout SelectAHideoutByCheckingCultureAndInfestedState(Clan faction)
		{
			List<Hideout> list = new List<Hideout>();
			bool flag = false;
			bool flag2 = false;
			foreach (Hideout item in Hideout.All)
			{
				bool flag3 = item.Settlement.Culture == faction.Culture;
				bool isInfested = item.IsInfested;
				if (!flag2 && flag3)
				{
					flag2 = true;
					list.Clear();
				}
				if (flag2 && !flag && isInfested)
				{
					flag = true;
					list.Clear();
				}
				if ((!flag2 || flag3) && (!flag || isInfested))
				{
					list.Add(item);
				}
			}
			return list.GetRandomElement();
		}

		private Hideout SelectANonInfestedHideoutOfSameCultureByWeight(Clan faction)
		{
			float averageDistanceBetweenClosestTwoTownsWithNavigationType = Campaign.Current.GetAverageDistanceBetweenClosestTwoTownsWithNavigationType(MobileParty.NavigationType.Default);
			float num = averageDistanceBetweenClosestTwoTownsWithNavigationType * 0.33f * averageDistanceBetweenClosestTwoTownsWithNavigationType * 0.33f;
			List<(Hideout, float)> list = new List<(Hideout, float)>();
			foreach (Hideout item in Hideout.All)
			{
				if (item.IsInfested || item.Settlement.Culture != faction.Culture)
				{
					continue;
				}
				int num2 = 1;
				if (item.Settlement.LastThreatTime.ElapsedDaysUntilNow > 1.5f)
				{
					float num3 = Campaign.MapDiagonalSquared;
					float num4 = Campaign.MapDiagonalSquared;
					foreach (Hideout item2 in Hideout.All)
					{
						if (item != item2 && item2.IsInfested)
						{
							float num5 = item.Settlement.Position.DistanceSquared(item2.Settlement.Position);
							if (item.Settlement.Culture == item2.Settlement.Culture && num5 < num3)
							{
								num3 = num5;
							}
							if (num5 < num4)
							{
								num4 = num5;
							}
						}
						num2 = (int)TaleWorlds.Library.MathF.Max(averageDistanceBetweenClosestTwoTownsWithNavigationType * 0.015f, num3 / num + averageDistanceBetweenClosestTwoTownsWithNavigationType * 0.076f * (num4 / num));
					}
				}
				list.Add((item, num2));
			}
			return MBRandom.ChooseWeighted(list);
		}

		public void SpawnBanditsAroundHideoutAtNewGame()
		{
			foreach (Clan banditFaction in Clan.BanditFactions)
			{
				if (IsBanditFaction(banditFaction))
				{
					SpawnBanditsAroundHideout(banditFaction, MBRandom.RandomFloatRanged(0.5f, 0.75f));
				}
			}
		}

		public void SpawnLootersAtNewGame()
		{
			foreach (Clan banditFaction in Clan.BanditFactions)
			{
				if (IsLooterFaction(banditFaction))
				{
					SpawnLooters(banditFaction, MBRandom.RandomFloatRanged(0.5f, 0.75f), uniformDistribution: true);
				}
			}
		}

		private void SpawnLooterParty(Clan selectedFaction, bool uniformDistribution)
		{
			Settlement settlement = SelectARandomSettlementForLooterParty(uniformDistribution);
			CampaignVec2 spawnPositionAroundSettlement = GetSpawnPositionAroundSettlement(selectedFaction, settlement);
			MobileParty mobileParty = BanditPartyComponent.CreateLooterParty(selectedFaction.StringId + "_1", selectedFaction, settlement, isBossParty: false, selectedFaction.DefaultPartyTemplate, spawnPositionAroundSettlement);
			InitializeBanditParty(mobileParty, selectedFaction);
			mobileParty.SetMovePatrolAroundPoint(mobileParty.Position, MobileParty.NavigationType.Default);
		}

		private void SpawnBanditParty(Clan selectedFaction)
		{
			Hideout hideout = SelectBanditHideout(selectedFaction);
			CampaignVec2 spawnPositionAroundSettlement = GetSpawnPositionAroundSettlement(selectedFaction, hideout.Settlement);
			MobileParty mobileParty = BanditPartyComponent.CreateBanditParty(selectedFaction.StringId + "_1", selectedFaction, hideout, isBossParty: false, selectedFaction.DefaultPartyTemplate, spawnPositionAroundSettlement);
			InitializeBanditParty(mobileParty, selectedFaction);
			mobileParty.SetMovePatrolAroundPoint(mobileParty.Position, mobileParty.NavigationCapability);
		}

		private static bool IsLooterFaction(IFaction faction)
		{
			if (!faction.Culture.CanHaveSettlement && !faction.HasNavalNavigationCapability)
			{
				return faction.StringId != "deserters";
			}
			return false;
		}

		private float GetSpawnRadiusForClan(Clan selectedFaction)
		{
			return BanditSpawnRadiusAsDays * (IsLooterFaction(selectedFaction) ? 1.5f : 1f);
		}

		private int GetInfestedHideoutCount(Clan banditFaction)
		{
			int num = 0;
			foreach (Hideout item in _hideouts[banditFaction.Culture])
			{
				if (item.IsInfested && item.MapFaction == banditFaction)
				{
					num++;
				}
			}
			return num;
		}

		private int GetCurrentLimitForLooters(Clan clan)
		{
			return Math.Min(Hideout.All.Count((Hideout x) => x.IsInfested) * 7, Campaign.Current.Models.BanditDensityModel.GetMaxSupportedNumberOfLootersForClan(clan));
		}

		private Settlement SelectARandomSettlementForLooterParty(bool uniformDistribution)
		{
			MBList<(Settlement, float)> mBList = new MBList<(Settlement, float)>();
			foreach (Settlement item in Settlement.All)
			{
				if (item.IsTown || item.IsVillage)
				{
					mBList.Add((item, GetSpawnChanceInSettlement(item)));
				}
			}
			return MBRandom.ChooseWeighted(mBList);
		}

		private void GiveFoodToBanditParty(MobileParty banditParty)
		{
			int num = (IsLooterFaction(banditParty.MapFaction) ? 8 : 16);
			foreach (ItemObject item in Items.All)
			{
				if (item.IsFood)
				{
					int num2 = MBRandom.RoundRandomized((float)banditParty.MemberRoster.TotalManCount * (1f / (float)item.Value) * (float)num * MBRandom.RandomFloat * MBRandom.RandomFloat * MBRandom.RandomFloat * MBRandom.RandomFloat);
					if (num2 > 0)
					{
						banditParty.ItemRoster.AddToCounts(item, num2);
					}
				}
			}
		}

		private CampaignVec2 GetSpawnPositionAroundSettlement(Clan clan, Settlement settlement)
		{
			CampaignVec2 campaignVec = NavigationHelper.FindPointAroundPosition(settlement.GatePosition, MobileParty.NavigationType.Default, GetSpawnRadiusForClan(clan));
			if (campaignVec.DistanceSquared(MobileParty.MainParty.Position) < _radiusAroundPlayerPartySquared)
			{
				for (int i = 0; i < 15; i++)
				{
					CampaignVec2 campaignVec2 = NavigationHelper.FindReachablePointAroundPosition(campaignVec, MobileParty.NavigationType.Default, GetSpawnRadiusForClan(clan));
					if (NavigationHelper.IsPositionValidForNavigationType(campaignVec2, MobileParty.NavigationType.Default))
					{
						float landRatio;
						float num = DistanceHelper.FindClosestDistanceFromMobilePartyToPoint(MobileParty.MainParty, campaignVec2, MobileParty.NavigationType.Default, out landRatio);
						if (num * num > _radiusAroundPlayerPartySquared)
						{
							campaignVec = campaignVec2;
							break;
						}
					}
				}
			}
			return campaignVec;
		}

		private bool IsBanditFaction(Clan clan)
		{
			if (!clan.HasNavalNavigationCapability && clan.IsBanditFaction)
			{
				return clan.Culture.CanHaveSettlement;
			}
			return false;
		}

		private void InitializeBanditParty(MobileParty banditParty, Clan faction)
		{
			banditParty.Party.SetVisualAsDirty();
			banditParty.ActualClan = faction;
			banditParty.Aggressiveness = 1f - 0.2f * MBRandom.RandomFloat;
			CreatePartyTrade(banditParty);
			GiveFoodToBanditParty(banditParty);
		}

		private static void CreatePartyTrade(MobileParty banditParty)
		{
			int initialGold = (int)(10f * (float)banditParty.Party.MemberRoster.TotalManCount * (0.5f + 1f * MBRandom.RandomFloat));
			banditParty.InitializePartyTrade(initialGold);
		}
	}
	public class BannerCampaignBehavior : CampaignBehaviorBase
	{
		private const int BannerLevel1CooldownDays = 4;

		private const int BannerLevel2CooldownDays = 8;

		private const int BannerLevel3CooldownDays = 12;

		private const float BannerItemUpdateChance = 0.1f;

		private const float GiveBannerItemChance = 0.25f;

		private Dictionary<Hero, CampaignTime> _heroNextBannerLootTime = new Dictionary<Hero, CampaignTime>();

		public override void RegisterEvents()
		{
			CampaignEvents.OnNewGameCreatedEvent.AddNonSerializedListener(this, OnNewGameCreated);
			CampaignEvents.OnGameLoadFinishedEvent.AddNonSerializedListener(this, GiveBannersToHeroes);
			CampaignEvents.DailyTickHeroEvent.AddNonSerializedListener(this, DailyTickHero);
			CampaignEvents.OnCollectLootsItemsEvent.AddNonSerializedListener(this, OnCollectLootItems);
			CampaignEvents.HeroComesOfAgeEvent.AddNonSerializedListener(this, OnHeroComesOfAge);
			CampaignEvents.HeroCreated.AddNonSerializedListener(this, OnHeroCreated);
			CampaignEvents.OnClanCreatedEvent.AddNonSerializedListener(this, OnClanCreated);
		}

		public override void SyncData(IDataStore dataStore)
		{
			dataStore.SyncData("_heroNextBannerLootTime", ref _heroNextBannerLootTime);
		}

		private void OnNewGameCreated(CampaignGameStarter campaignGameStarter)
		{
			GiveBannersToHeroes();
		}

		private void GiveBannersToHeroes()
		{
			foreach (Hero allAliveHero in Hero.AllAliveHeroes)
			{
				if (CanBannerBeGivenToHero(allAliveHero))
				{
					ItemObject randomBannerItemForHero = BannerHelper.GetRandomBannerItemForHero(allAliveHero);
					if (randomBannerItemForHero != null)
					{
						allAliveHero.BannerItem = new EquipmentElement(randomBannerItemForHero);
					}
				}
			}
		}

		private void DailyTickHero(Hero hero)
		{
			if (hero.Clan == Clan.PlayerClan)
			{
				return;
			}
			EquipmentElement bannerItem = hero.BannerItem;
			BannerItemModel bannerItemModel = Campaign.Current.Models.BannerItemModel;
			if (!bannerItem.IsInvalid() && bannerItemModel.CanBannerBeUpdated(bannerItem.Item) && MBRandom.RandomFloat < 0.1f)
			{
				int bannerLevel = ((BannerComponent)bannerItem.Item.ItemComponent).BannerLevel;
				int bannerItemLevelForHero = bannerItemModel.GetBannerItemLevelForHero(hero);
				if (bannerLevel != bannerItemLevelForHero)
				{
					ItemObject upgradeBannerForHero = GetUpgradeBannerForHero(hero, bannerItemLevelForHero);
					if (upgradeBannerForHero != null)
					{
						hero.BannerItem = new EquipmentElement(upgradeBannerForHero);
					}
				}
			}
			else if (bannerItem.IsInvalid() && CanBannerBeGivenToHero(hero) && MBRandom.RandomFloat < 0.25f && !hero.IsPrisoner)
			{
				ItemObject randomBannerItemForHero = BannerHelper.GetRandomBannerItemForHero(hero);
				if (randomBannerItemForHero != null)
				{
					hero.BannerItem = new EquipmentElement(randomBannerItemForHero);
				}
			}
		}

		private ItemObject GetUpgradeBannerForHero(Hero hero, int upgradeBannerLevel)
		{
			ItemObject item = hero.BannerItem.Item;
			foreach (ItemObject possibleRewardBannerItem in Campaign.Current.Models.BannerItemModel.GetPossibleRewardBannerItems())
			{
				BannerComponent bannerComponent = (BannerComponent)possibleRewardBannerItem.ItemComponent;
				if (possibleRewardBannerItem.Culture == item.Culture && bannerComponent.BannerLevel == upgradeBannerLevel && bannerComponent.BannerEffect == ((BannerComponent)item.ItemComponent).BannerEffect)
				{
					return possibleRewardBannerItem;
				}
			}
			return BannerHelper.GetRandomBannerItemForHero(hero);
		}

		private void OnCollectLootItems(PartyBase winnerParty, ItemRoster gainedLoots)
		{
			if (winnerParty != PartyBase.MainParty)
			{
				return;
			}
			MapEvent mapEvent = MobileParty.MainParty.MapEvent;
			ItemObject itemObject = null;
			itemObject = Campaign.Current.Models.BattleRewardModel.GetBannerRewardForWinningMapEvent(mapEvent);
			if (itemObject != null)
			{
				gainedLoots.AddToCounts(itemObject, 1);
			}
			Hero hero = null;
			MBReadOnlyList<MapEventParty> mBReadOnlyList = mapEvent.PartiesOnSide(mapEvent.DefeatedSide);
			if (mBReadOnlyList.Exists((MapEventParty x) => x.Party.IsMobile && x.Party.MobileParty.Army != null))
			{
				foreach (MapEventParty item in mBReadOnlyList)
				{
					if (item.Party.IsMobile && item.Party.MobileParty.Army != null && !item.Party.MobileParty.Army.ArmyOwner.BannerItem.IsInvalid() && CanBannerBeLootedFromHero(item.Party.MobileParty.Army.ArmyOwner))
					{
						hero = item.Party.MobileParty.Army.ArmyOwner;
						break;
					}
				}
			}
			if (hero == null)
			{
				hero = mBReadOnlyList.GetRandomElementWithPredicate((MapEventParty x) => x.Party.LeaderHero != null && !x.Party.LeaderHero.BannerItem.IsInvalid() && CanBannerBeLootedFromHero(x.Party.LeaderHero))?.Party.LeaderHero;
			}
			if (hero != null)
			{
				float bannerLootChanceFromDefeatedHero = Campaign.Current.Models.BattleRewardModel.GetBannerLootChanceFromDefeatedHero(hero);
				if (MBRandom.RandomFloat <= bannerLootChanceFromDefeatedHero)
				{
					LogBannerLootForHero(hero, ((BannerComponent)hero.BannerItem.Item.ItemComponent).BannerLevel);
					gainedLoots.AddToCounts(hero.BannerItem.Item, 1);
					hero.BannerItem = new EquipmentElement(null);
				}
			}
		}

		private void OnHeroComesOfAge(Hero hero)
		{
			if (CanBannerBeGivenToHero(hero))
			{
				ItemObject randomBannerItemForHero = BannerHelper.GetRandomBannerItemForHero(hero);
				if (randomBannerItemForHero != null)
				{
					hero.BannerItem = new EquipmentElement(randomBannerItemForHero);
				}
			}
		}

		private void OnHeroCreated(Hero hero, bool isBornNaturally = false)
		{
			if (CanBannerBeGivenToHero(hero))
			{
				ItemObject randomBannerItemForHero = BannerHelper.GetRandomBannerItemForHero(hero);
				if (randomBannerItemForHero != null)
				{
					hero.BannerItem = new EquipmentElement(randomBannerItemForHero);
				}
			}
		}

		private void OnClanCreated(Clan clan, bool isCompanion)
		{
			if (!isCompanion)
			{
				return;
			}
			Hero leader = clan.Leader;
			if (leader.BannerItem.IsInvalid())
			{
				ItemObject randomBannerItemForHero = BannerHelper.GetRandomBannerItemForHero(leader);
				if (randomBannerItemForHero != null)
				{
					leader.BannerItem = new EquipmentElement(randomBannerItemForHero);
				}
			}
		}

		private bool CanBannerBeLootedFromHero(Hero hero)
		{
			if (_heroNextBannerLootTime.ContainsKey(hero))
			{
				return _heroNextBannerLootTime[hero].IsPast;
			}
			return true;
		}

		private int GetCooldownDays(int bannerLevel)
		{
			if (bannerLevel == 1)
			{
				return 4;
			}
			if (bannerLevel == 1)
			{
				return 8;
			}
			return 12;
		}

		private void LogBannerLootForHero(Hero hero, int bannerLevel)
		{
			CampaignTime value = CampaignTime.DaysFromNow(GetCooldownDays(bannerLevel));
			if (!_heroNextBannerLootTime.ContainsKey(hero))
			{
				_heroNextBannerLootTime.Add(hero, value);
			}
			else
			{
				_heroNextBannerLootTime[hero] = value;
			}
		}

		private bool CanBannerBeGivenToHero(Hero hero)
		{
			int heroComesOfAge = Campaign.Current.Models.AgeModel.HeroComesOfAge;
			if (hero.Occupation == Occupation.Lord && hero.Age >= (float)heroComesOfAge && hero.BannerItem.IsInvalid())
			{
				return hero.Clan != Clan.PlayerClan;
			}
			return false;
		}
	}
	public class BattleCampaignBehavior : CampaignBehaviorBase
	{
		public override void RegisterEvents()
		{
			CampaignEvents.OnHeroCombatHitEvent.AddNonSerializedListener(this, OnHeroCombatHit);
			CampaignEvents.OnCollectLootsItemsEvent.AddNonSerializedListener(this, OnCollectLootItems);
		}

		private static void OnCollectLootItems(PartyBase winnerParty, ItemRoster gainedLoots)
		{
			if (!winnerParty.IsMobile || !winnerParty.MobileParty.HasPerk(DefaultPerks.Engineering.Metallurgy))
			{
				return;
			}
			foreach (ItemRosterElement item in gainedLoots.ToMBList())
			{
				ItemModifier itemModifier = item.EquipmentElement.ItemModifier;
				if (itemModifier == null || !(itemModifier.PriceMultiplier < 1f))
				{
					continue;
				}
				for (int i = 0; i < item.Amount; i++)
				{
					if (MBRandom.RandomFloat < DefaultPerks.Engineering.Metallurgy.PrimaryBonus)
					{
						gainedLoots.AddToCounts(item.EquipmentElement, -1);
						ItemRosterElement itemRosterElement = new ItemRosterElement(item.EquipmentElement.Item, 1);
						gainedLoots.Add(itemRosterElement);
					}
				}
			}
		}

		public override void SyncData(IDataStore dataStore)
		{
		}

		private static void OnHeroCombatHit(CharacterObject attacker, CharacterObject attacked, PartyBase party, WeaponComponentData attackerWeapon, bool isFatal, int xpGained)
		{
			if (!isFatal || attackerWeapon == null || party.MemberRoster.TotalRegulars <= 0 || !IsWeaponSuitableToGetBaptisedInBloodPerkBonus(attackerWeapon) || !attacker.HeroObject.GetPerkValue(DefaultPerks.TwoHanded.BaptisedInBlood))
			{
				return;
			}
			for (int i = 0; i < party.MemberRoster.Count; i++)
			{
				TroopRosterElement elementCopyAtIndex = party.MemberRoster.GetElementCopyAtIndex(i);
				if (!elementCopyAtIndex.Character.IsHero && elementCopyAtIndex.Character.IsInfantry)
				{
					party.MemberRoster.AddXpToTroopAtIndex(i, (int)DefaultPerks.TwoHanded.BaptisedInBlood.PrimaryBonus * elementCopyAtIndex.Number);
				}
			}
		}

		private static bool IsWeaponSuitableToGetBaptisedInBloodPerkBonus(WeaponComponentData attackerWeapon)
		{
			if (attackerWeapon.WeaponClass != WeaponClass.TwoHandedSword && attackerWeapon.WeaponClass != WeaponClass.TwoHandedPolearm && attackerWeapon.WeaponClass != WeaponClass.TwoHandedAxe)
			{
				return attackerWeapon.WeaponClass == WeaponClass.TwoHandedMace;
			}
			return true;
		}
	}
	public class BuildingsCampaignBehavior : CampaignBehaviorBase
	{
		public override void RegisterEvents()
		{
			CampaignEvents.OnSettlementOwnerChangedEvent.AddNonSerializedListener(this, OnSettlementOwnerChanged);
			CampaignEvents.OnNewGameCreatedEvent.AddNonSerializedListener(this, OnNewGameCreated);
			CampaignEvents.DailyTickSettlementEvent.AddNonSerializedListener(this, DailyTickSettlement);
			CampaignEvents.OnBuildingLevelChangedEvent.AddNonSerializedListener(this, OnBuildingLevelChanged);
		}

		private void OnSettlementOwnerChanged(Settlement settlement, bool openToClaim, Hero newOwner, Hero oldOwner, Hero capturerHero, ChangeOwnerOfSettlementAction.ChangeOwnerOfSettlementDetail detail)
		{
			if (settlement.Town != null && newOwner.Clan != Clan.PlayerClan)
			{
				settlement.Town.BuildingsInProgress.Clear();
			}
		}

		public override void SyncData(IDataStore dataStore)
		{
		}

		private void OnNewGameCreated(CampaignGameStarter starter)
		{
			BuildDevelopmentsAtGameStart();
		}

		private static void DecideDailyProject(Town town)
		{
			Building nextDailyBuilding = Campaign.Current.Models.BuildingScoreCalculationModel.GetNextDailyBuilding(town);
			if (nextDailyBuilding != null && nextDailyBuilding != town.CurrentDefaultBuilding)
			{
				BuildingHelper.ChangeDefaultBuilding(nextDailyBuilding, town);
			}
		}

		private static void DecideBuildingQueue(Town town)
		{
			if (town.BuildingsInProgress.IsEmpty())
			{
				Building nextBuilding = Campaign.Current.Models.BuildingScoreCalculationModel.GetNextBuilding(town);
				if (nextBuilding != null)
				{
					town.BuildingsInProgress.Enqueue(nextBuilding);
				}
			}
		}

		private void DailyTickSettlement(Settlement settlement)
		{
			if (!settlement.IsFortification)
			{
				return;
			}
			Town town = settlement.Town;
			foreach (Building building in town.Buildings)
			{
				if (town.Owner.Settlement.SiegeEvent == null)
				{
					building.HitPointChanged(10f);
				}
			}
			if (town.Owner.Settlement.OwnerClan != Clan.PlayerClan)
			{
				if (MBRandom.RandomFloat < 0.1f)
				{
					DecideBuildingQueue(town);
				}
				if (MBRandom.RandomFloat < 0.01f)
				{
					DecideDailyProject(town);
				}
			}
			if (!town.CurrentBuilding.BuildingType.IsDailyProject)
			{
				TickCurrentBuildingForTown(town);
			}
			else if (town.Governor != null && town.Governor.GetPerkValue(DefaultPerks.Charm.Virile) && MBRandom.RandomFloat <= DefaultPerks.Charm.Virile.SecondaryBonus)
			{
				Hero randomElement = settlement.Notables.GetRandomElement();
				if (randomElement != null)
				{
					ChangeRelationAction.ApplyRelationChangeBetweenHeroes(town.Governor.Clan.Leader, randomElement, 1, showQuickNotification: false);
				}
			}
		}

		private void TickCurrentBuildingForTown(Town town)
		{
			if (town.BuildingsInProgress.Peek().CurrentLevel == 3)
			{
				town.BuildingsInProgress.Dequeue();
			}
			if (town.Owner.Settlement.IsUnderSiege || town.BuildingsInProgress.IsEmpty())
			{
				return;
			}
			BuildingConstructionModel buildingConstructionModel = Campaign.Current.Models.BuildingConstructionModel;
			Building building = town.BuildingsInProgress.Peek();
			building.BuildingProgress += town.Construction;
			int num = (town.IsCastle ? buildingConstructionModel.CastleBoostCost : buildingConstructionModel.TownBoostCost);
			if (town.BoostBuildingProcess > 0)
			{
				town.BoostBuildingProcess -= num;
				if (town.BoostBuildingProcess < 0)
				{
					town.BoostBuildingProcess = 0;
				}
			}
			BuildingHelper.CheckIfBuildingIsComplete(building);
		}

		private void OnBuildingLevelChanged(Town town, Building building, int levelChange)
		{
			if (building.BuildingType.HasEffect(BuildingEffectEnum.GarrisonCapacity))
			{
				building.Town.Settlement.Town.GarrisonParty?.Party.MemberRoster.UpdateVersion();
			}
			if (building.BuildingType.HasEffect(BuildingEffectEnum.PrisonCapacity))
			{
				building.Town.Settlement.Party.PrisonRoster.UpdateVersion();
			}
			if (levelChange <= 0)
			{
				return;
			}
			if (town.Governor != null)
			{
				if ((town.IsTown || town.IsCastle) && town.Governor.GetPerkValue(DefaultPerks.Charm.MoralLeader))
				{
					foreach (Hero notable in town.Settlement.Notables)
					{
						ChangeRelationAction.ApplyRelationChangeBetweenHeroes(town.Settlement.OwnerClan.Leader, notable, TaleWorlds.Library.MathF.Round(DefaultPerks.Charm.MoralLeader.SecondaryBonus));
					}
				}
				if (town.Governor.GetPerkValue(DefaultPerks.Engineering.Foreman))
				{
					town.Prosperity += DefaultPerks.Engineering.Foreman.SecondaryBonus;
				}
			}
			SkillLevelingManager.OnSettlementProjectFinished(town.Settlement);
		}

		private static void BuildDevelopmentsAtGameStart()
		{
			foreach (Settlement item in Settlement.All)
			{
				if (!item.IsFortification)
				{
					continue;
				}
				Town town = item.Town;
				foreach (BuildingType buildingType in BuildingType.All)
				{
					if (town.Buildings.All((Building b) => b.BuildingType != buildingType) && Campaign.Current.Models.BuildingModel.CanAddBuildingTypeToTown(buildingType, town))
					{
						town.Buildings.Add(new Building(buildingType, town, 0f, buildingType.StartLevel));
					}
				}
				foreach (Building building in town.Buildings)
				{
					BuildingType buildingType2 = building.BuildingType;
					if (building.CurrentLevel < 3 && item.RandomFloat(1f) < buildingType2.VarianceChance)
					{
						TaleWorlds.Library.Debug.Print("Building variance roll success! SettlementId: " + item.StringId + " BuildingId: " + buildingType2.StringId + "Level: " + building.CurrentLevel);
						building.LevelUp();
						TaleWorlds.Library.Debug.Print("Building level increased to " + building.CurrentLevel + ".");
					}
				}
				DecideDailyProject(town);
				DecideBuildingQueue(town);
			}
		}
	}
	public class CampaignBattleRecoveryBehavior : CampaignBehaviorBase
	{
		public override void RegisterEvents()
		{
			CampaignEvents.MapEventEnded.AddNonSerializedListener(this, OnMapEventEnded);
			CampaignEvents.DailyTickPartyEvent.AddNonSerializedListener(this, DailyTickParty);
		}

		private void DailyTickParty(MobileParty party)
		{
			if (party.IsCurrentlyAtSea || !(MBRandom.RandomFloat < DefaultPerks.Medicine.Veterinarian.PrimaryBonus) || !party.HasPerk(DefaultPerks.Medicine.Veterinarian))
			{
				return;
			}
			ItemModifier @object = MBObjectManager.Instance.GetObject<ItemModifier>("lame_horse");
			int num = MBRandom.RandomInt(party.ItemRoster.Count);
			for (int i = num; i < party.ItemRoster.Count + num; i++)
			{
				int index = i % party.ItemRoster.Count;
				ItemObject itemAtIndex = party.ItemRoster.GetItemAtIndex(index);
				ItemRosterElement elementCopyAtIndex = party.ItemRoster.GetElementCopyAtIndex(index);
				if (elementCopyAtIndex.EquipmentElement.ItemModifier == @object)
				{
					party.ItemRoster.AddToCounts(elementCopyAtIndex.EquipmentElement, -1);
					party.ItemRoster.Add(new ItemRosterElement(itemAtIndex, 1));
					break;
				}
			}
		}

		public override void SyncData(IDataStore dataStore)
		{
		}

		private void OnMapEventEnded(MapEvent mapEvent)
		{
			CheckRecoveryForMapEventSide(mapEvent.AttackerSide);
			CheckRecoveryForMapEventSide(mapEvent.DefenderSide);
		}

		private void CheckRecoveryForMapEventSide(MapEventSide mapEventSide)
		{
			if (mapEventSide.MapEvent.EventType != MapEvent.BattleTypes.FieldBattle && mapEventSide.MapEvent.EventType != MapEvent.BattleTypes.Siege && mapEventSide.MapEvent.EventType != MapEvent.BattleTypes.SiegeOutside)
			{
				return;
			}
			foreach (MapEventParty party2 in mapEventSide.Parties)
			{
				PartyBase party = party2.Party;
				if (!party.IsMobile)
				{
					continue;
				}
				MobileParty mobileParty = party.MobileParty;
				foreach (TroopRosterElement item in party2.WoundedInBattle.GetTroopRoster())
				{
					int index = party2.WoundedInBattle.FindIndexOfTroop(item.Character);
					int elementNumber = party2.WoundedInBattle.GetElementNumber(index);
					if (mobileParty.HasPerk(DefaultPerks.Medicine.BattleHardened))
					{
						float num = DefaultPerks.Medicine.BattleHardened.PrimaryBonus;
						if (mobileParty.IsCurrentlyAtSea)
						{
							num *= 0.5f;
						}
						GiveTroopXp(item, elementNumber, party, TaleWorlds.Library.MathF.Round(num));
					}
				}
				foreach (TroopRosterElement item2 in party2.DiedInBattle.GetTroopRoster())
				{
					int index2 = party2.DiedInBattle.FindIndexOfTroop(item2.Character);
					int elementNumber2 = party2.DiedInBattle.GetElementNumber(index2);
					if (!mobileParty.IsCurrentlyAtSea && mobileParty.HasPerk(DefaultPerks.Medicine.Veterinarian) && item2.Character.IsMounted)
					{
						RecoverMountWithChance(item2, elementNumber2, party);
					}
				}
			}
		}

		private void RecoverMountWithChance(TroopRosterElement troopRosterElement, int count, PartyBase party)
		{
			EquipmentElement equipmentElement = troopRosterElement.Character.Equipment[10];
			if (equipmentElement.Item == null)
			{
				return;
			}
			for (int i = 0; i < count; i++)
			{
				if (MBRandom.RandomFloat < DefaultPerks.Medicine.Veterinarian.SecondaryBonus)
				{
					party.ItemRoster.AddToCounts(equipmentElement.Item, 1);
				}
			}
		}

		private void GiveTroopXp(TroopRosterElement troopRosterElement, int count, PartyBase partyBase, int xp)
		{
			partyBase.MemberRoster.AddXpToTroop(troopRosterElement.Character, xp * count);
		}
	}
	public class CampaignBehaviorManager : ICampaignBehaviorManager
	{
		private List<CampaignBehaviorBase> _campaignBehaviors;

		[SaveableField(1)]
		private readonly CampaignBehaviorDataStore _campaignBehaviorDataStore;

		public CampaignBehaviorManager(IEnumerable<CampaignBehaviorBase> inputComponents)
		{
			SetBehaviors(inputComponents);
			_campaignBehaviorDataStore = new CampaignBehaviorDataStore();
			CampaignEvents.OnBeforeSaveEvent.AddNonSerializedListener(this, OnBeforeSave);
		}

		public void InitializeCampaignBehaviors(IEnumerable<CampaignBehaviorBase> inputComponents)
		{
			SetBehaviors(inputComponents);
			CampaignEvents.OnBeforeSaveEvent.AddNonSerializedListener(this, OnBeforeSave);
		}

		private void SetBehaviors(IEnumerable<CampaignBehaviorBase> inputComponents)
		{
			_campaignBehaviors = inputComponents.ToList();
		}

		public void RegisterEvents()
		{
			foreach (CampaignBehaviorBase campaignBehavior in _campaignBehaviors)
			{
				campaignBehavior.RegisterEvents();
			}
		}

		private void OnBeforeSave()
		{
			_campaignBehaviorDataStore.ClearBehaviorData();
			foreach (CampaignBehaviorBase campaignBehavior in _campaignBehaviors)
			{
				_campaignBehaviorDataStore.SaveBehaviorData(campaignBehavior);
			}
		}

		public void LoadBehaviorData()
		{
			foreach (CampaignBehaviorBase campaignBehavior in _campaignBehaviors)
			{
				_campaignBehaviorDataStore.LoadBehaviorData(campaignBehavior);
			}
			_campaignBehaviorDataStore.ClearBehaviorData();
		}

		public T GetBehavior<T>()
		{
			foreach (CampaignBehaviorBase campaignBehavior in _campaignBehaviors)
			{
				CampaignBehaviorBase current;
				if ((current = campaignBehavior) is T)
				{
					return (T)(object)current;
				}
			}
			return default(T);
		}

		public IEnumerable<T> GetBehaviors<T>()
		{
			return _campaignBehaviors.OfType<T>();
		}

		public void AddBehavior(CampaignBehaviorBase campaignBehavior)
		{
			_campaignBehaviors.Add(campaignBehavior);
			campaignBehavior.RegisterEvents();
		}

		public void RemoveBehavior<T>() where T : CampaignBehaviorBase
		{
			for (int num = _campaignBehaviors.Count - 1; num >= 0; num--)
			{
				if (_campaignBehaviors[num] is T val)
				{
					_campaignBehaviors.Remove(val);
					CampaignEventDispatcher.Instance.RemoveListeners(val);
					break;
				}
			}
		}

		public void ClearBehaviors()
		{
			_campaignBehaviors.Clear();
		}

		internal static void AutoGeneratedStaticCollectObjectsCampaignBehaviorManager(object o, List<object> collectedObjects)
		{
			((CampaignBehaviorManager)o).AutoGeneratedInstanceCollectObjects(collectedObjects);
		}

		protected virtual void AutoGeneratedInstanceCollectObjects(List<object> collectedObjects)
		{
			collectedObjects.Add(_campaignBehaviorDataStore);
		}

		internal static object AutoGeneratedGetMemberValue_campaignBehaviorDataStore(object o)
		{
			return ((CampaignBehaviorManager)o)._campaignBehaviorDataStore;
		}
	}
