			Hero.MainHero.SetBirthDay(CampaignTime.YearsFromNow(-50f));
		}

		private void AgeSelectionElderOptionOnConsequence(CharacterCreationManager characterCreationManager)
		{
			characterCreationManager.CharacterCreationContent.StartingAge = 50;
			ApplyMainHeroEquipment(characterCreationManager);
		}

		private void ApplyMainHeroEquipment(CharacterCreationManager characterCreationManager)
		{
			NarrativeMenu narrativeMenuWithId = characterCreationManager.GetNarrativeMenuWithId("narrative_age_selection_menu");
			NarrativeMenuCharacter narrativeMenuCharacter = null;
			foreach (NarrativeMenuCharacter character in narrativeMenuWithId.Characters)
			{
				if (character.StringId.Equals("player_age_selection_character"))
				{
					narrativeMenuCharacter = character;
					break;
				}
			}
			CharacterObject.PlayerCharacter.Equipment.FillFrom(narrativeMenuCharacter.Equipment.DefaultEquipment);
			CharacterObject.PlayerCharacter.FirstCivilianEquipment.FillFrom(narrativeMenuCharacter.Equipment.GetRandomCivilianEquipment());
		}

		public void SetHeroAge(float age)
		{
			Hero.MainHero.SetBirthDay(CampaignTime.YearsFromNow(0f - age));
		}
	}
	public class CharacterDevelopmentCampaignBehavior : CampaignBehaviorBase
	{
		public override void RegisterEvents()
		{
			CampaignEvents.DailyTickHeroEvent.AddNonSerializedListener(this, DailyTickHero);
			CampaignEvents.OnCharacterCreationIsOverEvent.AddNonSerializedListener(this, OnCharacterCreationIsOver);
			CampaignEvents.OnHeroActivatedEvent.AddNonSerializedListener(this, OnHeroActivated);
		}

		public override void SyncData(IDataStore dataStore)
		{
		}

		private void DailyTickHero(Hero hero)
		{
			if (ShouldDevelopCharacterStats(hero))
			{
				hero.HeroDeveloper.DevelopCharacterStats();
			}
		}

		private void OnCharacterCreationIsOver()
		{
			if (!CampaignOptions.AutoAllocateClanMemberPerks)
			{
				return;
			}
			foreach (Hero aliveHero in Campaign.Current.AliveHeroes)
			{
				if (!aliveHero.IsChild && aliveHero.Clan == Clan.PlayerClan && aliveHero != Hero.MainHero)
				{
					aliveHero.HeroDeveloper.DevelopCharacterStats();
				}
			}
		}

		private void OnHeroActivated(Hero hero, Hero.CharacterStates previousState)
		{
			if (ShouldDevelopCharacterStats(hero))
			{
				hero.HeroDeveloper.DevelopCharacterStats();
			}
		}

		private bool ShouldDevelopCharacterStats(Hero hero)
		{
			if (!hero.IsChild && hero.IsAlive && (hero.Clan != Clan.PlayerClan || (hero != Hero.MainHero && CampaignOptions.AutoAllocateClanMemberPerks)))
			{
				return hero.PartyBelongedTo?.MapEvent == null;
			}
			return false;
		}
	}
	public class CharacterRelationCampaignBehavior : CampaignBehaviorBase
	{
		private const int RelationPenaltyFactor = 6;

		private const int RelationIncreaseBetweenHeroesAfterMarriage = 30;

		private const int RelationChangeForLeavingWithRebellion = -40;

		private const int RelationChangeForLeaveKingdom = -20;

		private const int RaidDefenseRelationGainWithVillageNotable = 5;

		private const float ChanceForRelationChange = 0.05f;

		public override void RegisterEvents()
		{
			CampaignEvents.OnSettlementOwnerChangedEvent.AddNonSerializedListener(this, OnSettlementOwnerChanged);
			CampaignEvents.DailyTickEvent.AddNonSerializedListener(this, DailyTick);
			CampaignEvents.OnNewGameCreatedEvent.AddNonSerializedListener(this, UpdateFriendshipAndEnemies);
			CampaignEvents.RaidCompletedEvent.AddNonSerializedListener(this, OnRaidCompleted);
			CampaignEvents.DailyTickPartyEvent.AddNonSerializedListener(this, DailyTickParty);
			CampaignEvents.MapEventEnded.AddNonSerializedListener(this, MapEventEnded);
			CampaignEvents.OnPrisonerDonatedToSettlementEvent.AddNonSerializedListener(this, OnPrisonerDonatedToSettlement);
			CampaignEvents.HeroRelationChanged.AddNonSerializedListener(this, OnHeroRelationChanged);
			CampaignEvents.BeforeHeroesMarried.AddNonSerializedListener(this, OnHeroesMarried);
			CampaignEvents.OnHeroUnregisteredEvent.AddNonSerializedListener(this, OnHeroUnregistered);
			CampaignEvents.HeroKilledEvent.AddNonSerializedListener(this, OnHeroKilled);
			CampaignEvents.OnClanChangedKingdomEvent.AddNonSerializedListener(this, OnClanChangedKingdom);
