			LogEntry.AddLogEntry(new EndCallToWarAgreementLogEntry(callingKingdom, calledKingdom, kingdomToCallToWarAgainst));
		}

		private void OnCallToWarAgreementStarted(Kingdom callingKingdom, Kingdom calledKingdom, Kingdom kingdomToCallToWarAgainst)
		{
			LogEntry.AddLogEntry(new StartCallToWarAgreementLogEntry(callingKingdom, calledKingdom, kingdomToCallToWarAgainst));
		}

		private void OnAllianceEndedEvent(Kingdom kingdom1, Kingdom kingdom2)
		{
			LogEntry.AddLogEntry(new EndAllianceLogEntry(kingdom1, kingdom2));
		}

		private void OnAllianceStartedEvent(Kingdom kingdom1, Kingdom kingdom2)
		{
			LogEntry.AddLogEntry(new StartAllianceLogEntry(kingdom1, kingdom2));
		}

		private static TextObject GetTraitChangedText(TraitObject traitObject, int level, int previousLevel)
		{
			TextObject variable;
			TextObject textObject;
			if (level != 0)
			{
				variable = GameTexts.FindText("str_trait_name_" + traitObject.StringId.ToLower(), (level + TaleWorlds.Library.MathF.Abs(traitObject.MinValue)).ToString());
				textObject = GameTexts.FindText("str_trait_gained_text");
			}
			else
			{
				variable = GameTexts.FindText("str_trait_name_" + traitObject.StringId.ToLower(), (previousLevel + TaleWorlds.Library.MathF.Abs(traitObject.MinValue)).ToString());
				textObject = GameTexts.FindText("str_trait_lost_text");
			}
			textObject.SetCharacterProperties("HERO", Hero.MainHero.CharacterObject);
			textObject.SetTextVariable("TRAIT_NAME", variable);
			return textObject;
		}
	}
	public class DesertersCampaignBehavior : CampaignBehaviorBase
	{
		public const int MinimumDeserterPartyCount = 15;

		public const int MaximumDeserterPartyCount = 40;

		private const int MaxDeserterPartyCountAfterBattle = 3;

		private const int MaxDeserterPartyCountAfterArmyBattle = 5;

		private Clan _deserterClan;

		public static int MergePartiesMaxSize => 120;

		private float DesertersSpawnRadiusAroundVillages => 0.2f * Campaign.Current.EstimatedAverageBanditPartySpeed * (float)CampaignTime.HoursInDay;

		private Clan DeserterClan
		{
			get
			{
				if (_deserterClan == null)
				{
					_deserterClan = Clan.FindFirst((Clan x) => x.StringId == "deserters");
				}
				return _deserterClan;
			}
		}

		public override void RegisterEvents()
		{
			CampaignEvents.MapEventEnded.AddNonSerializedListener(this, MapEventEnded);
			CampaignEvents.HourlyTickPartyEvent.AddNonSerializedListener(this, HourlyTickParty);
		}

		private void HourlyTickParty(MobileParty party)
		{
			if (!IsDeserterParty(party) || !CanPartyMerge(party) || party.MemberRoster.TotalRegulars >= MergePartiesMaxSize)
			{
				return;
			}
			LocatableSearchData<MobileParty> data = MobileParty.StartFindingLocatablesAroundPosition(party.Position.ToVec2(), GetMergeDistance(party));
			for (MobileParty mobileParty = MobileParty.FindNextLocatable(ref data); mobileParty != null; mobileParty = MobileParty.FindNextLocatable(ref data))
			{
				if (IsDeserterParty(mobileParty) && mobileParty != party && CanPartyMerge(mobileParty) && mobileParty.MemberRoster.TotalRegulars + party.MemberRoster.TotalRegulars <= MergePartiesMaxSize && MBRandom.RandomFloat < 0.05f)
				{
					MergeParties(party, mobileParty);
					break;
				}
			}
		}

		private bool CanPartyMerge(MobileParty mobileParty)
		{
			if (mobileParty.IsActive && mobileParty.MapEvent == null && !mobileParty.IsCurrentlyUsedByAQuest && !mobileParty.IsCurrentlyEngagingParty)
			{
				return !mobileParty.IsFleeing();
			}
			return false;
		}

		private void MergeParties(MobileParty party, MobileParty nearbyParty)
		{
			TaleWorlds.Library.Debug.Print($"Deserter parties {party.StringId} of {party.MemberRoster.TotalManCount} and {nearbyParty.StringId} of {nearbyParty.MemberRoster.TotalManCount} merged.");
			party.MemberRoster.Add(nearbyParty.MemberRoster);
			foreach (TroopRosterElement item in nearbyParty.PrisonRoster.GetTroopRoster())
			{
				if (item.Character.HeroObject != null)
				{
					TransferPrisonerAction.Apply(item.Character, nearbyParty.Party, party.Party);
				}
			}
			if (party.PrisonRoster.Count > 0)
			{
				party.PrisonRoster.Add(nearbyParty.PrisonRoster);
			}
			party.PartyTradeGold += nearbyParty.PartyTradeGold;
			party.ItemRoster.Add(nearbyParty.ItemRoster);
			DestroyPartyAction.Apply(null, nearbyParty);
			PartyBaseHelper.SortRoster(party);
		}

		private void MapEventEnded(MapEvent mapEvent)
		{
			if (mapEvent.IsNavalMapEvent || (!mapEvent.IsFieldBattle && !mapEvent.IsSiegeAssault && !mapEvent.IsSiegeOutside && !mapEvent.IsSallyOut) || !mapEvent.HasWinner || DeserterClan == null || DeserterClan.WarPartyComponents.Count >= Campaign.Current.Models.BanditDensityModel.GetMaxSupportedNumberOfLootersForClan(DeserterClan))
			{
				return;
			}
			MapEventSide mapEventSide = mapEvent.GetMapEventSide(mapEvent.DefeatedSide);
			TroopRoster troopRoster = TroopRoster.CreateDummyTroopRoster();
			foreach (MapEventParty party in mapEventSide.Parties)
			{
				if (CanPartyGenerateDeserters(party))
				{
					troopRoster.Add(party.RoutedInBattle);
					troopRoster.Add(party.DiedInBattle);
				}
			}
			if (MBRandom.RandomFloat < 0.9f)
			{
				troopRoster.RemoveIf((TroopRosterElement x) => x.Character.IsHero);
				if (troopRoster.TotalManCount >= 15)
				{
					TrySpawnDeserters(mapEvent, troopRoster);
				}
			}
		}

		private bool CanPartyGenerateDeserters(MapEventParty mapEventParty)
		{
			if (mapEventParty.Party.IsMobile && mapEventParty.Party.MobileParty.IsLordParty && mapEventParty.Party.MobileParty.ActualClan != null)
			{
				return !mapEventParty.Party.MobileParty.ActualClan.IsMinorFaction;
			}
			return false;
		}

		private void TrySpawnDeserters(MapEvent mapEvent, TroopRoster routedTroops)
		{
			int maxDeserterPartyCountForMapEvent = GetMaxDeserterPartyCountForMapEvent(mapEvent);
			List<TroopRoster> rostersSuitableForDeserters = GetRostersSuitableForDeserters(routedTroops, maxDeserterPartyCountForMapEvent);
			List<Settlement> list = SelectRandomSettlementsForDeserters(mapEvent, rostersSuitableForDeserters.Count);
			for (int i = 0; i < rostersSuitableForDeserters.Count; i++)
			{
				SpawnDesertersParty(mapEvent, rostersSuitableForDeserters[i], list[i]);
			}
		}

		private int GetMaxDeserterPartyCountForMapEvent(MapEvent mapEvent)
		{
			bool num = mapEvent.AttackerSide.Parties.Any((MapEventParty x) => CanPartyGenerateDeserters(x) && x.Party.MobileParty.Army != null && (x.Party.MobileParty.AttachedTo != null || x.Party.MobileParty.Army.LeaderParty == x.Party.MobileParty));
			bool flag = mapEvent.DefenderSide.Parties.Any((MapEventParty x) => CanPartyGenerateDeserters(x) && x.Party.MobileParty.Army != null && (x.Party.MobileParty.AttachedTo != null || x.Party.MobileParty.Army.LeaderParty == x.Party.MobileParty));
			if (num && flag)
			{
				return 5;
			}
			return 3;
		}

		private List<TroopRoster> GetRostersSuitableForDeserters(TroopRoster routedTroops, int maxPartyCount)
		{
			int totalManCount = routedTroops.TotalManCount;
			int maxSupportedNumberOfLootersForClan = Campaign.Current.Models.BanditDensityModel.GetMaxSupportedNumberOfLootersForClan(DeserterClan);
			int val = Math.Min(maxPartyCount, maxSupportedNumberOfLootersForClan - DeserterClan.WarPartyComponents.Count);
			int val2 = totalManCount / 15;
			int num = Math.Min(val, val2);
			List<TroopRoster> list = new List<TroopRoster>();
			for (int i = 0; i < num; i++)
			{
				list.Add(routedTroops.RemoveNumberOfNonHeroTroopsRandomly(Math.Min(routedTroops.TotalManCount / (num - i), 40)));
			}
			return list;
		}

		public override void SyncData(IDataStore dataStore)
		{
		}

		private void SpawnDesertersParty(MapEvent mapEvent, TroopRoster troops, Settlement settlement)
		{
			CampaignVec2 deserterSpawnPosition = GetDeserterSpawnPosition(settlement);
			MobileParty mobileParty = BanditPartyComponent.CreateLooterParty(DeserterClan.StringId + "_1", DeserterClan, settlement, isBossParty: false, null, deserterSpawnPosition);
			mobileParty.MemberRoster.Add(troops);
			InitializeDeserterParty(mobileParty);
			mobileParty.SetMovePatrolAroundPoint(mobileParty.Position, MobileParty.NavigationType.Default);
			PartyBaseHelper.SortRoster(mobileParty);
		}

		private List<Settlement> SelectRandomSettlementsForDeserters(MapEvent mapEvent, int count)
		{
			CampaignVec2 point = mapEvent.Position;
			List<Settlement> list = FindSettlementsAroundPoint(in point, (Settlement x) => x.IsVillage, MobileParty.NavigationType.Default, GetMaxVillageDistance());
			if (list.Count > count)
			{
				list.Shuffle();
				return list.Take(count).ToList();
			}
			if (list.Count == 0)
			{
				point = mapEvent.Position;
				list.Add(SettlementHelper.FindNearestSettlementToPoint(in point, (Settlement x) => x.IsVillage));
			}
			int count2 = list.Count;
			for (int i = 0; i < count - count2; i++)
			{
				list.Add(list[MBRandom.RandomInt(0, count2 - 1)]);
			}
			return list;
		}

		private static List<Settlement> FindSettlementsAroundPoint(in CampaignVec2 point, Func<Settlement, bool> condition, MobileParty.NavigationType navCapabilities, float maxDistance)
		{
			List<Settlement> list = new List<Settlement>();
			foreach (Settlement item in Settlement.All)
			{
				if ((condition == null || condition(item)) && item.Position.Distance(point) < maxDistance)
				{
					list.Add(item);
				}
			}
			return list;
		}

		private float GetMaxVillageDistance()
		{
			return Campaign.Current.EstimatedAverageBanditPartySpeed * (float)CampaignTime.HoursInDay / 2f;
		}

		private CampaignVec2 GetDeserterSpawnPosition(Settlement settlement)
		{
			CampaignVec2 campaignVec = NavigationHelper.FindPointAroundPosition(settlement.GatePosition, MobileParty.NavigationType.Default, DesertersSpawnRadiusAroundVillages);
			float num = MobileParty.MainParty.SeeingRange * MobileParty.MainParty.SeeingRange;
			if (campaignVec.DistanceSquared(MobileParty.MainParty.Position) < num)
			{
				for (int i = 0; i < 15; i++)
				{
					CampaignVec2 campaignVec2 = NavigationHelper.FindReachablePointAroundPosition(campaignVec, MobileParty.NavigationType.Default, DesertersSpawnRadiusAroundVillages);
					if (NavigationHelper.IsPositionValidForNavigationType(campaignVec2, MobileParty.NavigationType.Default))
					{
						float landRatio;
						float num2 = DistanceHelper.FindClosestDistanceFromMobilePartyToPoint(MobileParty.MainParty, campaignVec2, MobileParty.NavigationType.Default, out landRatio);
						if (num2 * num2 > num)
						{
							campaignVec = campaignVec2;
							break;
						}
					}
				}
			}
			return campaignVec;
		}

		private void InitializeDeserterParty(MobileParty banditParty)
		{
			banditParty.Party.SetVisualAsDirty();
			banditParty.ActualClan = DeserterClan;
			banditParty.Aggressiveness = 1f - 0.2f * MBRandom.RandomFloat;
			CreatePartyTrade(banditParty);
			GiveFoodToBanditParty(banditParty);
		}

		private static void CreatePartyTrade(MobileParty banditParty)
		{
			int initialGold = (int)(10f * (float)banditParty.Party.MemberRoster.TotalManCount * (0.5f + 1f * MBRandom.RandomFloat));
			banditParty.InitializePartyTrade(initialGold);
		}

		private void GiveFoodToBanditParty(MobileParty banditParty)
		{
			foreach (ItemObject item in Items.All)
			{
				if (item.IsFood)
				{
					int num = MBRandom.RoundRandomized((float)banditParty.MemberRoster.TotalManCount * (1f / (float)item.Value) * 8f * MBRandom.RandomFloat * MBRandom.RandomFloat * MBRandom.RandomFloat * MBRandom.RandomFloat);
					if (num > 0)
					{
						banditParty.ItemRoster.AddToCounts(item, num);
					}
				}
			}
		}

		private float GetMergeDistance(MobileParty mobileParty)
		{
			return mobileParty._lastCalculatedSpeed * 2f;
		}

		private bool IsDeserterParty(MobileParty mobileParty)
		{
			if (mobileParty.ActualClan != null)
			{
				return mobileParty.ActualClan == DeserterClan;
			}
			return false;
		}
	}
	public class DesertionCampaignBehavior : CampaignBehaviorBase
	{
		public override void RegisterEvents()
		{
			CampaignEvents.DailyTickPartyEvent.AddNonSerializedListener(this, DailyTickParty);
		}

		public override void SyncData(IDataStore dataStore)
		{
		}

		private void DailyTickParty(MobileParty mobileParty)
		{
			if (mobileParty.IsActive && !mobileParty.IsCurrentlyAtSea && !mobileParty.IsDisbanding && mobileParty.Party.MapEvent == null && (mobileParty.IsLordParty || mobileParty.IsCaravan || mobileParty.IsGarrison) && mobileParty.MemberRoster.TotalRegulars > 0)
			{
				CheckDesertionForParty(mobileParty);
			}
		}

		private static void CheckDesertionForParty(MobileParty mobileParty)
		{
			TroopRoster troopsToDesert = Campaign.Current.Models.PartyDesertionModel.GetTroopsToDesert(mobileParty);
			if (troopsToDesert.Count <= 0)
			{
				return;
			}
			int numberOfAllMembers = mobileParty.Party.NumberOfAllMembers;
			foreach (TroopRosterElement item in troopsToDesert.GetTroopRoster())
			{
				mobileParty.MemberRoster.AddToCounts(item.Character, -item.Number, insertAtFront: false, -item.WoundedNumber);
			}
			int numberOfAllMembers2 = mobileParty.Party.NumberOfAllMembers;
			if ((float)troopsToDesert.TotalManCount > (float)numberOfAllMembers * 0.4f && numberOfAllMembers > 10)
			{
				TaleWorlds.Library.Debug.Print($"[High Desertion Alert]  Deserted troop count for party: {mobileParty.StringId} is: {troopsToDesert.TotalManCount}, remaining troop count: {numberOfAllMembers2}, all member count before desertion: {numberOfAllMembers}");
			}
			CampaignEventDispatcher.Instance.OnTroopsDeserted(mobileParty, troopsToDesert);
			if (numberOfAllMembers2 == 0)
			{
				DestroyPartyAction.Apply(null, mobileParty);
			}
		}
	}
	public class DisbandPartyCampaignBehavior : CampaignBehaviorBase, IDisbandPartyCampaignBehavior, ICampaignBehavior
	{
		private const int DisbandDelayTimeAsDays = 1;

		private const float RemoveDisbandingPartyAfterHoldForDays = 0.125f;

		private const int DisbandPartySizeLimitForAIParties = 10;

		private Dictionary<MobileParty, CampaignTime> _partiesThatWaitingToDisband = new Dictionary<MobileParty, CampaignTime>();

		public override void RegisterEvents()
		{
			CampaignEvents.OnGameLoadFinishedEvent.AddNonSerializedListener(this, OnGameLoadFinished);
			CampaignEvents.OnPartyDisbandStartedEvent.AddNonSerializedListener(this, OnPartyDisbandStarted);
			CampaignEvents.OnPartyDisbandCanceledEvent.AddNonSerializedListener(this, OnPartyDisbandCanceled);
			CampaignEvents.HourlyTickEvent.AddNonSerializedListener(this, HourlyTick);
			CampaignEvents.MobilePartyDestroyed.AddNonSerializedListener(this, OnMobilePartyDestroyed);
			CampaignEvents.OnHeroTeleportationRequestedEvent.AddNonSerializedListener(this, OnHeroTeleportationRequested);
			CampaignEvents.HeroPrisonerTaken.AddNonSerializedListener(this, OnHeroPrisonerTaken);
			CampaignEvents.OnPartyDisbandedEvent.AddNonSerializedListener(this, OnPartyDisbanded);
			CampaignEvents.OnSessionLaunchedEvent.AddNonSerializedListener(this, OnSessionLaunched);
			CampaignEvents.DailyTickPartyEvent.AddNonSerializedListener(this, DailyTickParty);
			CampaignEvents.OnSettlementLeftEvent.AddNonSerializedListener(this, OnSettlementLeft);
			CampaignEvents.HourlyTickPartyEvent.AddNonSerializedListener(this, HourlyTickParty);
		}

		public bool IsPartyWaitingForDisband(MobileParty party)
		{
			return _partiesThatWaitingToDisband.ContainsKey(party);
		}

		public override void SyncData(IDataStore dataStore)
		{
			dataStore.SyncData("_partiesThatWaitingToDisband", ref _partiesThatWaitingToDisband);
		}

		private void OnGameLoadFinished()
		{
			foreach (Kingdom item in Kingdom.All)
			{
				for (int num = item.Armies.Count - 1; num >= 0; num--)
				{
					Army army = item.Armies[num];
					for (int num2 = army.Parties.Count - 1; num2 >= 0; num2--)
					{
						MobileParty mobileParty = army.Parties[num2];
						if (army.LeaderParty != mobileParty && mobileParty.LeaderHero == null)
						{
							DisbandPartyAction.StartDisband(mobileParty);
							mobileParty.Army = null;
						}
					}
					if (army.LeaderParty.LeaderHero == null)
					{
						DisbandPartyAction.StartDisband(army.LeaderParty);
					}
				}
			}
		}

		private void OnSessionLaunched(CampaignGameStarter campaignGameStarter)
		{
			AddDialogs(campaignGameStarter);
		}

		private void OnPartyDisbandStarted(MobileParty party)
		{
			if (party.ActualClan != Clan.PlayerClan && party.MemberRoster.Count >= 10)
			{
				Hero hero = null;
				foreach (Hero hero2 in party.ActualClan.Heroes)
				{
					if (hero2.PartyBelongedTo == null && hero2.IsActive && hero2.DeathMark == KillCharacterAction.KillCharacterActionDetail.None && hero2.CurrentSettlement != null && hero2.GovernorOf == null && (!hero2.CurrentSettlement.IsUnderSiege || !hero2.CurrentSettlement.IsUnderRaid))
					{
						hero = hero2;
						break;
					}
				}
				if (hero != null)
				{
					TeleportHeroAction.ApplyDelayedTeleportToPartyAsPartyLeader(hero, party);
				}
				else
				{
					_partiesThatWaitingToDisband.Add(party, CampaignTime.DaysFromNow(1f));
				}
				return;
			}
			if (party.IsCaravan && party.ActualClan == Clan.PlayerClan)
			{
				party.Ai.SetDoNotMakeNewDecisions(doNotMakeNewDecisions: true);
				GetTargetSettlementForDisbandingParty(party, out var targetSettlement, out var bestNavigationType, out var isTargetingPort);
				if (targetSettlement != null)
				{
					party.SetMoveGoToSettlement(targetSettlement, bestNavigationType, isTargetingPort);
				}
			}
			if (party.ActualClan == Clan.PlayerClan && party.LeaderHero != null)
			{
				_ = party.LeaderHero;
				party.RemovePartyLeader();
				TaleWorlds.Library.Debug.FailedAssert("Player Clan's party should not have a leader hero after party disband started!", "C:\\BuildAgent\\work\\mb3\\Source\\Bannerlord\\TaleWorlds.CampaignSystem\\CampaignBehaviors\\DisbandPartyCampaignBehavior.cs", "OnPartyDisbandStarted", 137);
			}
			CampaignTime value = (party.IsCurrentlyAtSea ? CampaignTime.Never : CampaignTime.DaysFromNow(1f));
			_partiesThatWaitingToDisband.Add(party, value);
		}

		private void OnPartyDisbandCanceled(MobileParty party)
		{
			if (_partiesThatWaitingToDisband.ContainsKey(party))
			{
				_partiesThatWaitingToDisband.Remove(party);
			}
		}

		private void HourlyTick()
		{
			List<MobileParty> list = new List<MobileParty>();
			foreach (KeyValuePair<MobileParty, CampaignTime> item in _partiesThatWaitingToDisband)
			{
				if (item.Value.IsPast || (item.Value == CampaignTime.Never && (!item.Key.IsCurrentlyAtSea || item.Key.CurrentSettlement != null)))
				{
					item.Key.IsDisbanding = true;
					list.Add(item.Key);
				}
			}
			foreach (MobileParty item2 in list)
			{
				_partiesThatWaitingToDisband.Remove(item2);
			}
		}

		private void OnMobilePartyDestroyed(MobileParty mobileParty, PartyBase destroyerParty)
		{
			if (_partiesThatWaitingToDisband.ContainsKey(mobileParty))
			{
				_partiesThatWaitingToDisband.Remove(mobileParty);
			}
		}

		private void OnHeroTeleportationRequested(Hero hero, Settlement targetSettlement, MobileParty targetParty, TeleportHeroAction.TeleportationDetail detail)
		{
			if (targetParty != null && detail == TeleportHeroAction.TeleportationDetail.DelayedTeleportToPartyAsPartyLeader && _partiesThatWaitingToDisband.ContainsKey(targetParty))
			{
				_partiesThatWaitingToDisband.Remove(targetParty);
			}
		}

		private void OnHeroPrisonerTaken(PartyBase capturer, Hero prisoner)
		{
			if (prisoner != Hero.MainHero)
			{
				return;
			}
			foreach (WarPartyComponent warPartyComponent in Clan.PlayerClan.WarPartyComponents)
			{
				if (warPartyComponent.MobileParty != null && warPartyComponent.MobileParty.LeaderHero == null)
				{
					CampaignEventDispatcher.Instance.OnPartyLeaderChangeOfferCanceled(warPartyComponent.MobileParty);
				}
			}
		}

		private void DailyTickParty(MobileParty mobileParty)
		{
			if (mobileParty.IsDisbanding && mobileParty.MapEvent == null && mobileParty.IsActive)
			{
				CheckDisbandedPartyDaily(mobileParty, mobileParty.TargetSettlement);
			}
		}

		private void OnSettlementLeft(MobileParty mobileParty, Settlement settlement)
		{
			if (mobileParty.IsCaravan && mobileParty.ActualClan == Clan.PlayerClan && !mobileParty.IsDisbanding && _partiesThatWaitingToDisband.ContainsKey(mobileParty) && mobileParty.CurrentSettlement == null && mobileParty.TargetSettlement != null)
			{
				GetTargetSettlementForDisbandingParty(mobileParty, out var targetSettlement, out var bestNavigationType, out var isTargetingPort);
				if (targetSettlement != null)
				{
					mobileParty.SetMoveGoToSettlement(targetSettlement, bestNavigationType, isTargetingPort);
				}
			}
		}

		private void HourlyTickParty(MobileParty party)
		{
			if (_partiesThatWaitingToDisband.ContainsKey(party) && !party.IsCurrentlyAtSea && _partiesThatWaitingToDisband[party] == CampaignTime.Never)
			{
				_partiesThatWaitingToDisband[party] = CampaignTime.DaysFromNow(1f);
				Campaign.Current.CampaignInformationManager.NewMapNoticeAdded(new PartyLeaderChangeNotification(party, new TextObject("{=QSaufZ9i}One of your parties has lost its leader. It will disband after a day has passed. You can assign a new clan member to lead it, if you wish to keep the party.")));
			}
			if (party.DefaultBehavior == AiBehavior.Hold && party.Ai.DoNotMakeNewDecisions && (party.IsDisbanding || _partiesThatWaitingToDisband.ContainsKey(party)))
			{
				GetTargetSettlementForDisbandingParty(party, out var targetSettlement, out var bestNavigationType, out var isTargetingPort);
				if (targetSettlement != null)
				{
					party.SetMoveGoToSettlement(targetSettlement, bestNavigationType, isTargetingPort);
				}
			}
		}

		private void GetTargetSettlementForDisbandingParty(MobileParty mobileParty, out Settlement targetSettlement, out MobileParty.NavigationType bestNavigationType, out bool isTargetingPort)
		{
			float num = 0f;
			targetSettlement = null;
			bestNavigationType = MobileParty.NavigationType.None;
			isTargetingPort = false;
			foreach (Settlement settlement2 in mobileParty.MapFaction.Settlements)
			{
				if (settlement2.IsFortification)
				{
					if (settlement2 == mobileParty.CurrentSettlement)
					{
						bestNavigationType = mobileParty.NavigationCapability;
						isTargetingPort = !mobileParty.HasLandNavigationCapability;
						targetSettlement = settlement2;
						break;
					}
					CalculateTargetSettlementScore(mobileParty, settlement2, out var bestNavigationType2, out var bestScore, out var isTargetingPort2);
					if (bestScore > num)
					{
						targetSettlement = settlement2;
						num = bestScore;
						bestNavigationType = bestNavigationType2;
						isTargetingPort = isTargetingPort2;
					}
				}
			}
			if (targetSettlement == null)
			{
				float maxDistance = Campaign.Current.GetAverageDistanceBetweenClosestTwoTownsWithNavigationType((!mobileParty.IsCurrentlyAtSea) ? MobileParty.NavigationType.Default : MobileParty.NavigationType.Naval) * 2f;
				int num2 = -1;
				do
				{
					num2 = SettlementHelper.FindNextSettlementAroundMobileParty(mobileParty, mobileParty.NavigationCapability, maxDistance, num2, (Settlement s) => s.OwnerClan != null && !s.OwnerClan.IsAtWarWith(mobileParty.MapFaction) && s.IsFortification);
					if (num2 >= 0)
					{
						Settlement settlement = Settlement.All[num2];
						CalculateTargetSettlementScore(mobileParty, settlement, out var bestNavigationType3, out var bestScore2, out var isTargetingPort3);
						if (bestScore2 > num)
						{
							targetSettlement = settlement;
							num = bestScore2;
							bestNavigationType = bestNavigationType3;
							isTargetingPort = isTargetingPort3;
						}
					}
				}
				while (num2 >= 0);
			}
			if (targetSettlement == null)
			{
				targetSettlement = SettlementHelper.FindNearestFortificationToMobileParty(mobileParty, mobileParty.NavigationCapability, (Settlement x) => x.OwnerClan != null && !x.OwnerClan.IsAtWarWith(mobileParty.MapFaction));
			}
		}

		private void CalculateTargetSettlementScore(MobileParty disbandParty, Settlement settlement, out MobileParty.NavigationType bestNavigationType, out float bestScore, out bool isTargetingPort)
		{
			isTargetingPort = false;
			AiHelper.GetBestNavigationTypeAndAdjustedDistanceOfSettlementForMobileParty(disbandParty, settlement, isTargetingPort: false, out bestNavigationType, out var bestNavigationDistance, out var isFromPort);
			if (settlement.HasPort && disbandParty.HasNavalNavigationCapability)
			{
				AiHelper.GetBestNavigationTypeAndAdjustedDistanceOfSettlementForMobileParty(disbandParty, settlement, isTargetingPort: true, out var bestNavigationType2, out var bestNavigationDistance2, out isFromPort);
				if (bestNavigationDistance2 < bestNavigationDistance)
				{
					bestNavigationDistance = bestNavigationDistance2;
					bestNavigationType = bestNavigationType2;
					isTargetingPort = true;
				}
			}
			float num = TaleWorlds.Library.MathF.Pow(1f - 0.95f * (TaleWorlds.Library.MathF.Min(Campaign.MapDiagonal, bestNavigationDistance) / Campaign.MapDiagonal), 3f);
			float num2 = ((disbandParty.Party.Owner?.Clan == settlement.OwnerClan) ? 1f : ((disbandParty.Party.Owner?.MapFaction == settlement.MapFaction) ? 0.1f : 0.01f));
			float num3 = ((disbandParty.DefaultBehavior == AiBehavior.GoToSettlement && disbandParty.TargetSettlement == settlement) ? 1f : 0.3f);
			bestScore = num * num2 * num3;
		}

		private void OnPartyDisbanded(MobileParty disbandParty, Settlement relatedSettlement)
		{
			if (relatedSettlement == null || disbandParty.IsCustomParty)
			{
				return;
			}
			if (relatedSettlement.IsFortification)
			{
				if (!relatedSettlement.IsUnderSiege)
				{
					MergeDisbandPartyToFortification(disbandParty, relatedSettlement);
				}
			}
			else if (relatedSettlement.IsVillage && relatedSettlement.Village.VillageState == Village.VillageStates.Normal)
			{
				MergeDisbandPartyToVillage(disbandParty, relatedSettlement);
			}
		}

		private void MergeDisbandPartyToFortification(MobileParty disbandParty, Settlement relatedSettlement)
		{
			if (disbandParty.PrisonRoster.TotalHeroes > 0)
			{
				TroopRoster troopRoster = null;
				foreach (TroopRosterElement item in disbandParty.PrisonRoster.GetTroopRoster())
				{
					if (item.Character.HeroObject == null)
					{
						continue;
					}
					if (item.Character.HeroObject.MapFaction.IsAtWarWith(relatedSettlement.MapFaction))
					{
						if (troopRoster == null)
						{
							troopRoster = TroopRoster.CreateDummyTroopRoster();
						}
						TransferPrisonerAction.Apply(item.Character, disbandParty.Party, relatedSettlement.Party);
						troopRoster.Add(item);
					}
					else
					{
						EndCaptivityAction.ApplyByEscape(item.Character.HeroObject);
					}
				}
				if (troopRoster != null)
				{
					CampaignEventDispatcher.Instance.OnPrisonerDonatedToSettlement(disbandParty, troopRoster.ToFlattenedRoster(), relatedSettlement);
				}
			}
			if (disbandParty.PrisonRoster.TotalManCount > 0)
			{
				SellPrisonersAction.ApplyForAllPrisoners(disbandParty.Party, relatedSettlement.Party);
			}
			if (disbandParty.MemberRoster.TotalManCount <= 0)
			{
				return;
			}
			if (disbandParty.MapFaction == relatedSettlement.MapFaction)
			{
				if (relatedSettlement.Town.GarrisonParty == null)
				{
					relatedSettlement.AddGarrisonParty();
				}
				float num = 0f;
				foreach (TroopRosterElement item2 in disbandParty.MemberRoster.GetTroopRoster())
				{
					num += (float)item2.Number * Campaign.Current.Models.PrisonerDonationModel.CalculateInfluenceGainAfterTroopDonation(disbandParty.Party, item2.Character, relatedSettlement);
				}
				relatedSettlement.Town.GarrisonParty.Party.MemberRoster.Add(disbandParty.MemberRoster);
				GainKingdomInfluenceAction.ApplyForDonatePrisoners(disbandParty, num);
			}
			disbandParty.MemberRoster.Clear();
		}

		private void MergeDisbandPartyToVillage(MobileParty disbandParty, Settlement settlement)
		{
			if (disbandParty.PrisonRoster.TotalHeroes > 0)
			{
				foreach (TroopRosterElement item in disbandParty.PrisonRoster.GetTroopRoster())
				{
					if (item.Character.HeroObject != null)
					{
						EndCaptivityAction.ApplyByEscape(item.Character.HeroObject);
					}
				}
			}
			if (disbandParty.PrisonRoster.TotalManCount > 0)
			{
				disbandParty.PrisonRoster.Clear();
			}
			if (disbandParty.MemberRoster.TotalManCount > 0)
			{
				float num = (float)disbandParty.MemberRoster.TotalManCount * 0.5f;
				settlement.Militia += num;
			}
		}

		private void CheckDisbandedPartyDaily(MobileParty disbandParty, Settlement settlement)
		{
			if (disbandParty.MemberRoster.Count == 0)
			{
				DestroyPartyAction.Apply(null, disbandParty);
			}
			else if (settlement == null && disbandParty.StationaryStartTime.ElapsedDaysUntilNow >= 0.125f)
			{
				Settlement currentSettlementOfMobilePartyForAICalculation = MobilePartyHelper.GetCurrentSettlementOfMobilePartyForAICalculation(disbandParty);
				if (currentSettlementOfMobilePartyForAICalculation != null)
				{
					DestroyPartyAction.ApplyForDisbanding(disbandParty, currentSettlementOfMobilePartyForAICalculation);
					return;
				}
				if (disbandParty.MemberRoster.TotalHeroes > 0)
				{
					foreach (TroopRosterElement item in disbandParty.MemberRoster.GetTroopRoster())
					{
						if (item.Character.IsHero && !item.Character.IsPlayerCharacter && !item.Character.HeroObject.IsDead)
						{
							MakeHeroFugitiveAction.Apply(item.Character.HeroObject);
						}
					}
				}
				DestroyPartyAction.Apply(null, disbandParty);
			}
			else if (settlement != null && settlement == disbandParty.CurrentSettlement)
			{
				DestroyPartyAction.ApplyForDisbanding(disbandParty, settlement);
			}
		}

