	public class DiscardItemsCampaignBehavior : CampaignBehaviorBase
	{
		public override void RegisterEvents()
		{
			CampaignEvents.OnItemsDiscardedByPlayerEvent.AddNonSerializedListener(this, OnItemsDiscardedByPlayer);
			CampaignEvents.HourlyTickPartyEvent.AddNonSerializedListener(this, OnHourlyTickParty);
		}

		private void OnHourlyTickParty(MobileParty mobileParty)
		{
			if (mobileParty.IsLordParty && !mobileParty.IsMainParty && mobileParty.LeaderHero != null)
			{
				HandlePartyInventory(mobileParty.Party);
			}
		}

		private void OnItemsDiscardedByPlayer(ItemRoster roster)
		{
			int xpBonusForDiscardingItems = Campaign.Current.Models.ItemDiscardModel.GetXpBonusForDiscardingItems(roster);
			if ((float)xpBonusForDiscardingItems > 0f)
			{
				MobilePartyHelper.PartyAddSharedXp(MobileParty.MainParty, xpBonusForDiscardingItems);
			}
		}

		public override void SyncData(IDataStore dataStore)
		{
		}

		private void HandlePartyInventory(PartyBase party)
		{
			if (party.IsMobile && party.MobileParty.IsLordParty && !party.MobileParty.IsMainParty && !party.MobileParty.IsCurrentlyAtSea)
			{
				int num = party.ItemRoster.NumberOfLivestockAnimals + party.ItemRoster.NumberOfPackAnimals + TaleWorlds.Library.MathF.Max(0, party.ItemRoster.NumberOfMounts - party.NumberOfMenWithHorse);
				if (num > party.MemberRoster.TotalManCount)
				{
					DiscardAnimalsCausingHerdingPenalty(party.MobileParty, num - TaleWorlds.Library.MathF.Max(0, party.ItemRoster.NumberOfMounts - party.NumberOfMenWithHorse));
				}
				if (party.MobileParty.TotalWeightCarried > (float)party.MobileParty.InventoryCapacity)
				{
					DiscardOverburdeningItemsForParty(party.MobileParty, party.MobileParty.TotalWeightCarried - (float)party.MobileParty.InventoryCapacity);
				}
			}
		}

		private void DiscardAnimalsCausingHerdingPenalty(MobileParty mobileParty, int amount)
		{
			int numberOfAnimalsToDiscard = amount;
			int num = mobileParty.ItemRoster.Count - 1;
			while (num >= 0 && numberOfAnimalsToDiscard > 0)
			{
				if (mobileParty.ItemRoster[num].EquipmentElement.Item.IsAnimal)
				{
					DiscardAnimal(mobileParty, mobileParty.ItemRoster[num], ref numberOfAnimalsToDiscard);
				}
				num--;
			}
			int num2 = mobileParty.ItemRoster.Count - 1;
			while (num2 >= 0 && numberOfAnimalsToDiscard > 0)
			{
				if (mobileParty.ItemRoster[num2].EquipmentElement.Item.IsMountable && mobileParty.ItemRoster[num2].EquipmentElement.Item.HorseComponent.IsPackAnimal)
				{
					DiscardAnimal(mobileParty, mobileParty.ItemRoster[num2], ref numberOfAnimalsToDiscard);
				}
				num2--;
			}
			int num3 = mobileParty.ItemRoster.Count - 1;
			while (num3 >= 0 && numberOfAnimalsToDiscard > 0)
			{
				if (mobileParty.ItemRoster[num3].EquipmentElement.Item.IsMountable)
				{
					DiscardAnimal(mobileParty, mobileParty.ItemRoster[num3], ref numberOfAnimalsToDiscard);
				}
				num3--;
			}
		}

		private void DiscardOverburdeningItemsForParty(MobileParty mobileParty, float totalWeightToDiscard)
		{
			int num = (int)(mobileParty.FoodChange * -20f);
			float weightLeftToDiscard = totalWeightToDiscard;
			int num2 = mobileParty.ItemRoster.Count - 1;
			while (num2 >= 0 && weightLeftToDiscard > 0f)
			{
				if (num > 0 && mobileParty.ItemRoster[num2].EquipmentElement.Item.IsFood)
				{
					if (mobileParty.ItemRoster[num2].Amount > num)
					{
						int discardLimit = mobileParty.ItemRoster[num2].Amount - num;
						num = 0;
						DiscardNecessaryAmountOfItems(mobileParty, mobileParty.ItemRoster[num2], ref weightLeftToDiscard, discardLimit);
					}
					else
					{
						num -= mobileParty.ItemRoster[num2].Amount;
					}
				}
				else
				{
					DiscardNecessaryAmountOfItems(mobileParty, mobileParty.ItemRoster[num2], ref weightLeftToDiscard);
				}
				num2--;
			}
		}

		private void DiscardNecessaryAmountOfItems(MobileParty mobileParty, ItemRosterElement itemRosterElement, ref float weightLeftToDiscard, int discardLimit = int.MaxValue)
		{
			float equipmentElementWeight = itemRosterElement.EquipmentElement.GetEquipmentElementWeight();
			int num = MBMath.ClampInt((itemRosterElement.GetRosterElementWeight() <= weightLeftToDiscard) ? itemRosterElement.Amount : TaleWorlds.Library.MathF.Ceiling(weightLeftToDiscard / equipmentElementWeight), 0, discardLimit);
			weightLeftToDiscard -= equipmentElementWeight * (float)num;
			mobileParty.ItemRoster.AddToCounts(itemRosterElement.EquipmentElement, -num);
		}

		private void DiscardAnimal(MobileParty mobileParty, ItemRosterElement itemRosterElement, ref int numberOfAnimalsToDiscard)
		{
			int num = ((itemRosterElement.Amount > numberOfAnimalsToDiscard) ? numberOfAnimalsToDiscard : itemRosterElement.Amount);
			numberOfAnimalsToDiscard -= num;
			mobileParty.ItemRoster.AddToCounts(itemRosterElement.EquipmentElement, -num);
		}
	}
	internal class DisorganizedStateCampaignBehavior : CampaignBehaviorBase
	{
		private bool _checkForEvent;

		public override void RegisterEvents()
		{
			CampaignEvents.MapEventStarted.AddNonSerializedListener(this, OnMapEventStarted);
			CampaignEvents.MapEventEnded.AddNonSerializedListener(this, OnMapEventEnd);
			CampaignEvents.PartyRemovedFromArmyEvent.AddNonSerializedListener(this, OnPartyRemovedFromArmy);
			CampaignEvents.GameMenuOptionSelectedEvent.AddNonSerializedListener(this, OnGameMenuOptionSelected);
		}

		private void OnGameMenuOptionSelected(GameMenu gameMenu, GameMenuOption gameMenuOption)
		{
			if (!_checkForEvent || (!(gameMenuOption.IdString == "str_order_attack") && !(gameMenuOption.IdString == "attack")))
			{
				return;
			}
			foreach (MapEventParty party in MobileParty.MainParty.MapEvent.DefenderSide.Parties)
			{
				if (Campaign.Current.Models.PartyImpairmentModel.CanGetDisorganized(party.Party))
				{
					party.Party.MobileParty.SetDisorganized(isDisorganized: true);
				}
			}
		}

		private void OnMapEventStarted(MapEvent mapEvent, PartyBase attackerParty, PartyBase defenderParty)
		{
			if (!mapEvent.IsSallyOut)
			{
				return;
			}
			if (!mapEvent.AttackerSide.IsMainPartyAmongParties())
			{
				foreach (MapEventParty party in mapEvent.DefenderSide.Parties)
				{
					if (Campaign.Current.Models.PartyImpairmentModel.CanGetDisorganized(party.Party))
					{
						party.Party.MobileParty.SetDisorganized(isDisorganized: true);
					}
				}
				return;
			}
			_checkForEvent = true;
		}

		private void OnPartyRemovedFromArmy(MobileParty mobileParty)
		{
			if (Campaign.Current.Models.PartyImpairmentModel.CanGetDisorganized(mobileParty.Party))
			{
				mobileParty.SetDisorganized(isDisorganized: true);
			}
		}

		private void OnMapEventEnd(MapEvent mapEvent)
		{
			if ((mapEvent.AttackerSide.Parties.Sum((MapEventParty x) => x.HealthyManCountAtStart) != mapEvent.AttackerSide.Parties.Sum((MapEventParty x) => x.Party.NumberOfHealthyMembers) || mapEvent.DefenderSide.Parties.Sum((MapEventParty x) => x.HealthyManCountAtStart) != mapEvent.DefenderSide.Parties.Sum((MapEventParty x) => x.Party.NumberOfHealthyMembers)) && !mapEvent.IsHideoutBattle)
			{
				foreach (PartyBase involvedParty in mapEvent.InvolvedParties)
				{
					if (involvedParty.IsActive)
					{
						MobileParty mobileParty = involvedParty.MobileParty;
						if ((mobileParty == null || !mobileParty.IsMainParty || !mapEvent.DiplomaticallyFinished || !mapEvent.AttackerSide.MapFaction.IsAtWarWith(mapEvent.DefenderSide.MapFaction)) && (!mapEvent.IsSallyOut || involvedParty.MapEventSide.MissionSide == BattleSideEnum.Defender) && Campaign.Current.Models.PartyImpairmentModel.CanGetDisorganized(involvedParty) && (mapEvent.RetreatingSide == BattleSideEnum.None || mapEvent.RetreatingSide != involvedParty.Side))
						{
							involvedParty.MobileParty.SetDisorganized(isDisorganized: true);
						}
					}
				}
			}
			_checkForEvent = false;
		}

		public override void SyncData(IDataStore dataStore)
		{
			dataStore.SyncData("_checkForEvent", ref _checkForEvent);
		}
	}
	public class DynamicBodyCampaignBehavior : CampaignBehaviorBase
	{
		private const float DailyBuildDecrease = -0.015f;

		private const float DailyBuildIncrease = 0.025f;

		private const float DailyWeightDecreaseWhenStarving = -0.1f;

		private const float DailyWeightDecreaseWhenNotStarving = -0.025f;

		private const float DailyWeightIncrease = 0.025f;

		private CampaignTime _lastSettlementVisitTime;

		private CampaignTime _lastEncounterTime;

		private float _unmodifiedWeight = -1f;

		private float _unmodifiedBuild = -1f;

		private CampaignTime LastSettlementVisitTime
		{
			get
			{
				if (Hero.MainHero.CurrentSettlement != null)
				{
					_lastSettlementVisitTime = CampaignTime.Now;
				}
				return _lastSettlementVisitTime;
			}
			set
			{
				_lastSettlementVisitTime = value;
			}
		}

		private float MaxPlayerWeight => TaleWorlds.Library.MathF.Min(1f, _unmodifiedWeight * 1.3f);

		private float MinPlayerWeight => TaleWorlds.Library.MathF.Max(0f, _unmodifiedWeight * 0.7f);

		private float MaxPlayerBuild => TaleWorlds.Library.MathF.Min(1f, _unmodifiedBuild * 1.3f);

		private float MinPlayerBuild => TaleWorlds.Library.MathF.Max(0f, _unmodifiedBuild * 0.7f);

		private void DailyTick()
		{
			bool flag = LastSettlementVisitTime.ElapsedDaysUntilNow < 1f;
			bool flag2 = Hero.MainHero.PartyBelongedTo != null && Hero.MainHero.PartyBelongedTo.Party.IsStarving;
			float num = ((Hero.MainHero.CurrentSettlement == null && flag2) ? (-0.1f) : (flag ? 0.025f : (-0.025f)));
			Hero.MainHero.Weight = MBMath.ClampFloat(Hero.MainHero.Weight + num, MinPlayerWeight, MaxPlayerWeight);
			float num2 = ((MapEvent.PlayerMapEvent != null || PlayerSiege.PlayerSiegeEvent != null || _lastEncounterTime.ElapsedDaysUntilNow < 2f) ? 0.025f : (-0.015f));
			Hero.MainHero.Build = MBMath.ClampFloat(Hero.MainHero.Build + num2, MinPlayerBuild, MaxPlayerBuild);
		}

		private void OnSettlementLeft(MobileParty party, Settlement settlement)
		{
			if (party != null && party.IsMainParty)
			{
				LastSettlementVisitTime = CampaignTime.Now;
			}
		}

		private void OnMapEventEnded(MapEvent mapEvent)
		{
			if (mapEvent.IsPlayerMapEvent)
			{
				_lastEncounterTime = CampaignTime.Now;
			}
		}

		private void OnPlayerBodyPropertiesChanged()
		{
			_unmodifiedBuild = Hero.MainHero.Build;
			_unmodifiedWeight = Hero.MainHero.Weight;
		}

		private void OnPlayerCharacterChanged(Hero oldPlayer, Hero newPlayer, MobileParty newMainParty, bool isMainPartyChanged)
		{
			_unmodifiedBuild = newPlayer.Build;
			_unmodifiedWeight = newPlayer.Weight;
		}

		private void OnHeroCreated(Hero hero, bool bornNaturally)
		{
			if (!bornNaturally)
			{
				DynamicBodyProperties dynamicBodyPropertiesBetweenMinMaxRange = CharacterHelper.GetDynamicBodyPropertiesBetweenMinMaxRange(hero.CharacterObject);
				hero.Weight = dynamicBodyPropertiesBetweenMinMaxRange.Weight;
				hero.Build = dynamicBodyPropertiesBetweenMinMaxRange.Build;
			}
		}

		private void OnNewGameCreatedPartialFollowUpEnd(CampaignGameStarter starter)
		{
			_lastSettlementVisitTime = CampaignTime.Now;
			_lastEncounterTime = CampaignTime.Now;
			OnPlayerBodyPropertiesChanged();
		}

		public override void RegisterEvents()
		{
			CampaignEvents.OnSettlementLeftEvent.AddNonSerializedListener(this, OnSettlementLeft);
			CampaignEvents.DailyTickEvent.AddNonSerializedListener(this, DailyTick);
			CampaignEvents.MapEventEnded.AddNonSerializedListener(this, OnMapEventEnded);
			CampaignEvents.HeroCreated.AddNonSerializedListener(this, OnHeroCreated);
			CampaignEvents.OnPlayerBodyPropertiesChangedEvent.AddNonSerializedListener(this, OnPlayerBodyPropertiesChanged);
			CampaignEvents.OnCharacterCreationIsOverEvent.AddNonSerializedListener(this, OnPlayerBodyPropertiesChanged);
			CampaignEvents.OnPlayerCharacterChangedEvent.AddNonSerializedListener(this, OnPlayerCharacterChanged);
			CampaignEvents.OnNewGameCreatedPartialFollowUpEndEvent.AddNonSerializedListener(this, OnNewGameCreatedPartialFollowUpEnd);
		}

		public override void SyncData(IDataStore dataStore)
		{
			dataStore.SyncData("_lastSettlementVisitTime", ref _lastSettlementVisitTime);
			dataStore.SyncData("_lastEncounterTime", ref _lastEncounterTime);
			dataStore.SyncData("_unmodifiedWeight", ref _unmodifiedWeight);
			dataStore.SyncData("_unmodifiedBuild", ref _unmodifiedBuild);
		}
	}
	public class EducationCampaignBehavior : CampaignBehaviorBase, IEducationLogic
	{
		private enum ChildAgeState : short
		{
			Invalid = -1,
			Year2 = 0,
			Year5 = 1,
			Year8 = 2,
			Year11 = 3,
			Year14 = 4,
			Year16 = 5,
			Count = 6,
			First = 0,
			Last = 5
		}

		private class EducationOption
		{
			public delegate bool EducationOptionConditionDelegate(EducationOption option, List<EducationOption> previousOptions);

			public delegate bool EducationOptionConsequenceDelegate(EducationOption option);

			public readonly EducationOptionConditionDelegate Condition;

			private readonly EducationOptionConsequenceDelegate _consequence;

			public readonly TextObject Title;

			public readonly TextObject Description;

			public readonly TextObject Effect;

			public readonly CharacterAttribute[] Attributes;

			public readonly SkillObject[] Skills;

			public readonly EducationCharacterProperties ChildProperties;

			public readonly EducationCharacterProperties SpecialCharacterProperties;

			public readonly int RandomValue;

			public void OnConsequence(Hero child)
			{
				_consequence?.Invoke(this);
				CharacterAttribute[] attributes = Attributes;
				foreach (CharacterAttribute attrib in attributes)
				{
					child.HeroDeveloper.AddAttribute(attrib, 1, checkUnspentPoints: false);
				}
				SkillObject[] skills = Skills;
				foreach (SkillObject skill in skills)
				{
					child.HeroDeveloper.AddFocus(skill, 1, checkUnspentFocusPoints: false);
					child.HeroDeveloper.ChangeSkillLevel(skill, 15);
				}
			}

			public EducationOption(TextObject title, TextObject description, TextObject effect, EducationOptionConditionDelegate condition, EducationOptionConsequenceDelegate consequence, CharacterAttribute[] attributes, SkillObject[] skills, EducationCharacterProperties childProperties, EducationCharacterProperties specialCharacterProperties = default(EducationCharacterProperties))
			{
				Title = title;
				Description = description;
				Condition = condition;
				_consequence = consequence;
				Attributes = attributes ?? new CharacterAttribute[0];
				Skills = skills ?? new SkillObject[0];
				Effect = GetEffectText(effect ?? TextObject.GetEmpty());
				ChildProperties = childProperties;
				SpecialCharacterProperties = specialCharacterProperties;
				RandomValue = MBRandom.RandomInt(0, int.MaxValue);
			}

			private TextObject GetEffectText(TextObject effect)
			{
				TextObject textObject = new TextObject("{=JfBTbsX2}{EFFECT_DESCRIPTION}{NEW_LINE_1}{SKILL_DESCRIPTION}{NEW_LINE_2}{ATTRIBUTE_DESCRIPTION}");
				TextObject textObject2;
				if (Skills.Length == 1)
				{
					textObject2 = new TextObject("{=I88vSwpb}{SKILL1} gains {NUMBER_FP} Focus Point and {NUMBER_SP} Skill Points.");
					textObject2.SetTextVariable("SKILL1", Skills[0].Name);
				}
				else if (Skills.Length == 2)
				{
					textObject2 = new TextObject("{=bvRVu0fO}{SKILL1} and {SKILL2} gain {NUMBER_FP} Focus Point and {NUMBER_SP} Skill Points.");
					textObject2.SetTextVariable("SKILL1", Skills[0].Name);
					textObject2.SetTextVariable("SKILL2", Skills[1].Name);
				}
				else
				{
					textObject2 = TextObject.GetEmpty();
				}
				TextObject textObject3;
				if (Attributes.Length == 1)
				{
					textObject3 = new TextObject("{=bm2DzxEl}{ATTRIBUTE1} is increased by {NUMBER_AP}.");
					textObject3.SetTextVariable("ATTRIBUTE1", Attributes.ElementAt(0).Name);
				}
				else if (Attributes.Length == 2)
				{
					textObject3 = new TextObject("{=2sQQh02s}{ATTRIBUTE1} and {ATTRIBUTE2} are increased by {NUMBER_AP}.");
					textObject3.SetTextVariable("ATTRIBUTE1", Attributes[0].Name);
					textObject3.SetTextVariable("ATTRIBUTE2", Attributes[1].Name);
				}
				else
				{
					textObject3 = TextObject.GetEmpty();
				}
				if (!TextObject.IsNullOrEmpty(textObject3))
				{
					textObject3.SetTextVariable("NUMBER_AP", 1);
				}
				if (!TextObject.IsNullOrEmpty(textObject2))
				{
					textObject2.SetTextVariable("NUMBER_FP", 1);
					textObject2.SetTextVariable("NUMBER_SP", 15);
				}
				textObject.SetTextVariable("SKILL_DESCRIPTION", textObject2);
				textObject.SetTextVariable("ATTRIBUTE_DESCRIPTION", textObject3);
				textObject.SetTextVariable("EFFECT_DESCRIPTION", effect);
				if (!effect.IsEmpty() && (!textObject2.IsEmpty() || !textObject3.IsEmpty()))
				{
					textObject.SetTextVariable("NEW_LINE_1", "\n");
				}
				else
				{
					textObject.SetTextVariable("NEW_LINE_1", TextObject.GetEmpty());
				}
				if (!textObject2.IsEmpty() && !textObject3.IsEmpty())
				{
					textObject.SetTextVariable("NEW_LINE_2", "\n");
				}
				else
				{
					textObject.SetTextVariable("NEW_LINE_2", TextObject.GetEmpty());
				}
				return textObject;
			}
		}

		private class EducationStage
		{
			private List<List<EducationPage>> _superPages;

			public readonly ChildAgeState Target;

			public int PageCount => _superPages.Count;

			public EducationStage(ChildAgeState targetAge)
