			EducationCharacterProperties childProperties6 = new EducationCharacterProperties("act_childhood_ready_bow", "bow_roman_a", useOffHand: true);
			EducationCharacterProperties childProperties7 = new EducationCharacterProperties("act_childhood_manners");
			educationPage.AddOption(new EducationOption(new TextObject("{=m4kr4RXD}{?CHILD.GENDER}her{?}his{\\?} strength."), new TextObject("{=QbwNmxrn}You told {?CHILD.GENDER}her{?}him{\\?} that skill and brains are all very well, but in many situations there is no substitute for sheer brute might."), null, null, null, new CharacterAttribute[1] { DefaultCharacterAttributes.Vigor }, null, childProperties2));
			educationPage.AddOption(new EducationOption(new TextObject("{=3fvj2Eti}{?CHILD.GENDER}her{?}his{\\?} endurance."), new TextObject("{=GARAmzFT}To thrive you must learn to travel faster, work longer, and fight harder than anyone who stands against you."), null, null, null, new CharacterAttribute[1] { DefaultCharacterAttributes.Endurance }, null, childProperties3));
			educationPage.AddOption(new EducationOption(new TextObject("{=Gitd3DN8}a thirst for knowledge."), new TextObject("{=JHMHcZEp}You have seen many marvels on your travels and heard of many more, and one day, you believe, the philosophers of science will rule the world."), null, null, null, new CharacterAttribute[1] { DefaultCharacterAttributes.Intelligence }, null, childProperties4));
			educationPage.AddOption(new EducationOption(new TextObject("{=7P3wiojT}a sharp mind."), new TextObject("{=78dta9Ys}You told {?CHILD.GENDER}her{?}him{\\?} that it is cheaper, safer and wiser to win a battle without fighting, if it is possible to do so."), null, null, null, new CharacterAttribute[1] { DefaultCharacterAttributes.Cunning }, null, childProperties5));
			educationPage.AddOption(new EducationOption(new TextObject("{=LEoZ2DV5}a good eye and a steady hand."), new TextObject("{=8mk6gwvh}You told {?CHILD.GENDER}her{?}him{\\?} that a good eye can spot dangers from afar, and a steady hand can take them down before they get close."), null, null, null, new CharacterAttribute[1] { DefaultCharacterAttributes.Control }, null, childProperties6));
			educationPage.AddOption(new EducationOption(new TextObject("{=ulFmGvtj}an interest in people."), new TextObject("{=HaAjWFrt}You told {?CHILD.GENDER}her{?}him{\\?} that understanding people's motivations and turning them to your advantage is the difference between a warrior and a king."), null, null, null, new CharacterAttribute[1] { DefaultCharacterAttributes.Social }, null, childProperties7));
