			educationPage2.AddOption(new EducationOption(DefaultSkills.Tactics.Name, new TextObject("{=2s6cH2kE}Even the finest swordsman can perish if his lord is ignorant of the difference between necessary risks and reckless, unnecessary ones."), null, null, null, null, new SkillObject[1] { DefaultSkills.Tactics }, childProperties9));
