	public class FactionDiscontinuationCampaignBehavior : CampaignBehaviorBase
	{
		private const float SurvivalDurationForIndependentClanInDays = 28f;

		private Dictionary<Clan, CampaignTime> _independentClans = new Dictionary<Clan, CampaignTime>();

		public override void RegisterEvents()
		{
			CampaignEvents.OnSettlementOwnerChangedEvent.AddNonSerializedListener(this, OnSettlementOwnerChanged);
			CampaignEvents.OnClanChangedKingdomEvent.AddNonSerializedListener(this, OnClanChangedKingdom);
			CampaignEvents.DailyTickClanEvent.AddNonSerializedListener(this, DailyTickClan);
			CampaignEvents.OnGameLoadFinishedEvent.AddNonSerializedListener(this, OnGameLoadFinished);
		}

		public void OnSettlementOwnerChanged(Settlement settlement, bool openToClaim, Hero newOwner, Hero oldOwner, Hero capturerHero, ChangeOwnerOfSettlementAction.ChangeOwnerOfSettlementDetail detail)
		{
			if (_independentClans.ContainsKey(newOwner.Clan))
			{
				_independentClans.Remove(newOwner.Clan);
			}
			if (CanClanBeDiscontinued(oldOwner.Clan))
			{
				AddIndependentClan(oldOwner.Clan);
			}
			Kingdom kingdom = oldOwner.Clan.Kingdom;
			if (kingdom != null && CanKingdomBeDiscontinued(kingdom))
			{
				DiscontinueKingdom(kingdom);
			}
		}

		public void OnClanChangedKingdom(Clan clan, Kingdom oldKingdom, Kingdom newKingdom, ChangeKingdomAction.ChangeKingdomActionDetail detail, bool showNotification = true)
		{
			if (newKingdom == null)
			{
				if (CanClanBeDiscontinued(clan))
				{
					AddIndependentClan(clan);
				}
			}
			else if (_independentClans.ContainsKey(clan))
			{
				_independentClans.Remove(clan);
			}
			if (clan == Clan.PlayerClan && oldKingdom != null && CanKingdomBeDiscontinued(oldKingdom))
			{
				DiscontinueKingdom(oldKingdom);
			}
		}

		private void DailyTickClan(Clan clan)
		{
			if (_independentClans.ContainsKey(clan) && _independentClans[clan].IsPast)
			{
				DiscontinueClan(clan);
			}
		}

		private bool CanKingdomBeDiscontinued(Kingdom kingdom)
		{
			bool result = !kingdom.IsEliminated && kingdom != Clan.PlayerClan.Kingdom && kingdom.Settlements.IsEmpty();
			if (result)
			{
				CampaignEventDispatcher.Instance.CanKingdomBeDiscontinued(kingdom, ref result);
			}
			return result;
		}

		private void DiscontinueKingdom(Kingdom kingdom)
		{
			foreach (Clan item in new List<Clan>(kingdom.Clans))
			{
				FinalizeMapEvents(item);
				ChangeKingdomAction.ApplyByLeaveByKingdomDestruction(item);
			}
			kingdom.RulingClan = null;
			DestroyKingdomAction.Apply(kingdom);
		}

		private void FinalizeMapEvents(Clan clan)
		{
			foreach (WarPartyComponent item in clan.WarPartyComponents.ToList())
			{
				if (item?.Party.IsActive ?? false)
				{
					if (item.MobileParty.MapEvent != null)
					{
						item.MobileParty.MapEvent.FinalizeEvent();
					}
					if (item.MobileParty.SiegeEvent != null)
					{
						item.MobileParty.SiegeEvent.FinalizeSiegeEvent();
					}
				}
			}
			foreach (Settlement settlement in clan.Settlements)
			{
				if (settlement.Party.MapEvent != null)
				{
					settlement.Party.MapEvent.FinalizeEvent();
				}
				if (settlement.Party.SiegeEvent != null)
				{
					settlement.Party.SiegeEvent.FinalizeSiegeEvent();
				}
			}
		}

		private bool CanClanBeDiscontinued(Clan clan)
		{
			if (clan.Kingdom == null && !clan.IsRebelClan && !clan.IsBanditFaction && !clan.IsMinorFaction && clan != Clan.PlayerClan)
			{
				return clan.Settlements.IsEmpty();
			}
			return false;
		}

		private void DiscontinueClan(Clan clan)
		{
			DestroyClanAction.Apply(clan);
			_independentClans.Remove(clan);
		}

		private void AddIndependentClan(Clan clan)
		{
			if (!_independentClans.ContainsKey(clan))
			{
				_independentClans.Add(clan, CampaignTime.DaysFromNow(28f));
			}
		}

		public override void SyncData(IDataStore dataStore)
		{
			dataStore.SyncData("_independentClans", ref _independentClans);
		}

		private void OnGameLoadFinished()
		{
			if (!(MBSaveLoad.LastLoadedGameVersion < ApplicationVersion.FromString("v1.2.2")))
			{
				return;
			}
			foreach (Kingdom item in Kingdom.All)
			{
				if (!item.IsEliminated && CanKingdomBeDiscontinued(item))
				{
					DiscontinueKingdom(item);
				}
			}
		}
	}
	public class FindingItemOnMapBehavior : CampaignBehaviorBase
	{
		public override void RegisterEvents()
		{
			CampaignEvents.DailyTickPartyEvent.AddNonSerializedListener(this, DailyTickParty);
		}

		public override void SyncData(IDataStore dataStore)
		{
		}

		public void DailyTickParty(MobileParty party)
		{
			if (!(MBRandom.RandomFloat < DefaultPerks.Scouting.BeastWhisperer.PrimaryBonus) || !party.HasPerk(DefaultPerks.Scouting.BeastWhisperer))
			{
				return;
			}
			TerrainType faceTerrainType = Campaign.Current.MapSceneWrapper.GetFaceTerrainType(party.CurrentNavigationFace);
			if (faceTerrainType != TerrainType.Steppe && faceTerrainType != TerrainType.Plain)
			{
				return;
			}
			ItemObject randomElementWithPredicate = Items.All.GetRandomElementWithPredicate((ItemObject x) => x.IsMountable && !x.NotMerchandise);
			if (randomElementWithPredicate != null)
			{
				party.ItemRoster.AddToCounts(randomElementWithPredicate, 1);
				if (party.IsMainParty)
				{
					TextObject textObject = new TextObject("{=vl9bawa7}{COUNT} {?(COUNT > 1)}{PLURAL(ANIMAL_NAME)} are{?}{ANIMAL_NAME} is{\\?} added to your party.");
					textObject.SetTextVariable("COUNT", 1);
					textObject.SetTextVariable("ANIMAL_NAME", randomElementWithPredicate.Name);
					InformationManager.DisplayMessage(new InformationMessage(textObject.ToString()));
				}
			}
		}
	}
	public class FoodConsumptionBehavior : CampaignBehaviorBase
	{
		private int _lastItemVersion = -1;

		public override void RegisterEvents()
		{
			CampaignEvents.OnNewGameCreatedPartialFollowUpEndEvent.AddNonSerializedListener(this, OnNewGameCreatedPartialFollowUpEnd);
			CampaignEvents.DailyTickPartyEvent.AddNonSerializedListener(this, DailyTickParty);
			CampaignEvents.TickEvent.AddNonSerializedListener(this, OnTick);
			CampaignEvents.PartyAttachedAnotherParty.AddNonSerializedListener(this, OnPartyAttachedParty);
		}

		private void OnNewGameCreatedPartialFollowUpEnd(CampaignGameStarter starter)
		{
			foreach (Settlement item in Settlement.All)
			{
				if (item.IsFortification)
				{
					item.Town.FoodStocks = item.Town.FoodStocksUpperLimit();
				}
			}
		}

		public override void SyncData(IDataStore dataStore)
		{
			dataStore.SyncData("_lastItemVersion", ref _lastItemVersion);
		}

		public void DailyTickParty(MobileParty party)
		{
			CheckAnimalBreeding(party);
			if (Campaign.Current.Models.MobilePartyFoodConsumptionModel.DoesPartyConsumeFood(party))
			{
				PartyConsumeFood(party);
			}
		}

		private void OnPartyAttachedParty(MobileParty mobileParty)
		{
			if (MobileParty.MainParty.Army == null || mobileParty.Army != MobileParty.MainParty.Army)
			{
				return;
			}
			if (mobileParty.Party.IsStarving)
			{
				PartyConsumeFood(mobileParty, starvingCheck: true);
				return;
			}
			if (MobileParty.MainParty.Army.LeaderParty.Party.IsStarving)
			{
				PartyConsumeFood(MobileParty.MainParty.Army.LeaderParty, starvingCheck: true);
			}
			foreach (MobileParty attachedParty in MobileParty.MainParty.Army.LeaderParty.AttachedParties)
			{
				if (attachedParty.Party.IsStarving && mobileParty != attachedParty)
				{
					PartyConsumeFood(attachedParty, starvingCheck: true);
				}
			}
		}

		public void OnTick(float dt)
		{
			if (PartyBase.MainParty.IsStarving)
			{
				int versionNo = PartyBase.MainParty.ItemRoster.VersionNo;
				if (_lastItemVersion != versionNo)
				{
					_lastItemVersion = versionNo;
					PartyConsumeFood(MobileParty.MainParty, starvingCheck: true);
				}
			}
		}

		private void PartyConsumeFood(MobileParty mobileParty, bool starvingCheck = false)
		{
			bool isStarving = mobileParty.Party.IsStarving;
			float foodChange = mobileParty.FoodChange;
			float num = ((foodChange < 0f) ? (0f - foodChange) : 0f);
			int num2 = ((mobileParty.Party.RemainingFoodPercentage >= 0) ? mobileParty.Party.RemainingFoodPercentage : 0);
			int num3 = TaleWorlds.Library.MathF.Round(num * 100f);
			num2 -= num3;
			MakeFoodConsumption(mobileParty, ref num2);
			if (num2 < 0 && mobileParty.ItemRoster.TotalFood > 0 && SlaughterLivestock(mobileParty, num2))
			{
				MakeFoodConsumption(mobileParty, ref num2);
				if (mobileParty.IsMainParty)
				{
					MBInformationManager.AddQuickInformation(new TextObject("{=WTwafRTH}Your party has slaughtered some animals to eat."));
				}
			}
			if (num2 < 0 && mobileParty.Army != null && (mobileParty.AttachedTo == mobileParty.Army.LeaderParty || mobileParty.Army.LeaderParty == mobileParty))
			{
				Dictionary<Hero, float> dictionary = new Dictionary<Hero, float>();
				Hero leaderHero = mobileParty.LeaderHero;
				do
				{
					MobileParty mobileParty2 = null;
					float num4 = 1f;
					MobileParty leaderParty = mobileParty.Army.LeaderParty;
					if (leaderParty != mobileParty && !leaderParty.Party.IsStarving && leaderParty.ItemRoster.TotalFood > 0)
					{
						float num5 = (float)leaderParty.ItemRoster.TotalFood / TaleWorlds.Library.MathF.Abs(leaderParty.FoodChange);
						if (num5 > num4)
						{
							num4 = num5;
							mobileParty2 = leaderParty;
						}
					}
					foreach (MobileParty attachedParty in leaderParty.AttachedParties)
					{
						if (attachedParty != mobileParty && !attachedParty.Party.IsStarving && attachedParty.ItemRoster.TotalFood > 0)
						{
							float num6 = (float)attachedParty.ItemRoster.TotalFood / TaleWorlds.Library.MathF.Abs(attachedParty.FoodChange);
							if (num6 > num4)
							{
								num4 = num6;
								mobileParty2 = attachedParty;
							}
						}
					}
					ItemRosterElement itemRosterElement = default(ItemRosterElement);
					if (mobileParty2 == null)
					{
						break;
					}
					int num7 = 10000;
					bool flag = false;
					foreach (ItemRosterElement item in mobileParty2.ItemRoster)
					{
						if (item.EquipmentElement.Item.IsFood && item.EquipmentElement.Item.Value < num7)
						{
							itemRosterElement = item;
							num7 = item.EquipmentElement.Item.Value;
							flag = true;
						}
					}
					if (!flag)
					{
						foreach (ItemRosterElement item2 in mobileParty2.ItemRoster)
						{
							if (item2.EquipmentElement.Item.HasHorseComponent && item2.EquipmentElement.Item.HorseComponent.IsLiveStock && item2.EquipmentElement.Item.Value < num7)
							{
								itemRosterElement = item2;
								num7 = item2.EquipmentElement.Item.Value;
								flag = true;
							}
						}
					}
					if (!flag)
					{
						break;
					}
					mobileParty2.ItemRoster.AddToCounts(itemRosterElement.EquipmentElement, -1);
					num2 += 100;
					if (itemRosterElement.EquipmentElement.Item.HasHorseComponent && itemRosterElement.EquipmentElement.Item.HorseComponent.IsLiveStock)
					{
						int meatCount = itemRosterElement.EquipmentElement.Item.HorseComponent.MeatCount;
						mobileParty2.ItemRoster.AddToCounts(DefaultItems.Meat, meatCount - 1);
					}
					Hero leaderHero2 = mobileParty2.LeaderHero;
					if (leaderHero != null && leaderHero2 != null)
					{
						float num8 = 0.2f;
						GainKingdomInfluenceAction.ApplyForGivingFood(leaderHero2, leaderHero, num8);
						if (dictionary.TryGetValue(leaderHero2, out var value))
						{
							dictionary[leaderHero2] = value + num8;
						}
						else
						{
							dictionary.Add(leaderHero2, num8);
						}
					}
				}
				while (num2 < 0);
				foreach (KeyValuePair<Hero, float> item3 in dictionary)
				{
					CampaignEventDispatcher.Instance.OnHeroSharedFoodWithAnother(item3.Key, leaderHero, item3.Value);
				}
			}
			mobileParty.Party.RemainingFoodPercentage = num2;
			bool isStarving2 = mobileParty.Party.IsStarving;
			if ((int)Campaign.Current.Models.CampaignTimeModel.CampaignStartTime.ToDays != (int)CampaignTime.Now.ToDays)
			{
				if (isStarving && isStarving2)
				{
					int dailyStarvationMoralePenalty = Campaign.Current.Models.PartyMoraleModel.GetDailyStarvationMoralePenalty(mobileParty.Party);
					mobileParty.RecentEventsMorale += dailyStarvationMoralePenalty;
					if (mobileParty.IsMainParty)
					{
						MBTextManager.SetTextVariable("MORALE_PENALTY", -dailyStarvationMoralePenalty);
						MBInformationManager.AddQuickInformation(new TextObject("{=qhL5o55i}Your party is starving. You lose {MORALE_PENALTY} morale."));
						CampaignEventDispatcher.Instance.OnMainPartyStarving();
						if ((int)CampaignTime.Now.ToDays % 3 == 0 && mobileParty.MemberRoster.TotalManCount > 1)
						{
							TraitLevelingHelper.OnPartyStarved();
						}
					}
				}
				if (mobileParty.MemberRoster.TotalManCount > 1)
				{
					SkillLevelingManager.OnFoodConsumed(mobileParty, isStarving2);
					if (!isStarving && !isStarving2 && mobileParty.IsMainParty && mobileParty.Morale >= 90f && mobileParty.MemberRoster.TotalRegulars >= 20 && (int)CampaignTime.Now.ToDays % 10 == 0)
					{
						TraitLevelingHelper.OnPartyTreatedWell();
					}
				}
			}
			CampaignEventDispatcher.Instance.OnPartyConsumedFood(mobileParty);
		}

		private bool SlaughterLivestock(MobileParty party, int partyRemainingFoodPercentage)
		{
			int num = 0;
			ItemRoster itemRoster = party.ItemRoster;
			int num2 = itemRoster.Count - 1;
			while (num2 >= 0 && num * 100 < -partyRemainingFoodPercentage)
			{
				ItemObject itemAtIndex = itemRoster.GetItemAtIndex(num2);
				HorseComponent horseComponent = itemAtIndex.HorseComponent;
				if (horseComponent != null && horseComponent.IsLiveStock)
				{
					while (num * 100 < -partyRemainingFoodPercentage)
					{
						itemRoster.AddToCounts(itemAtIndex, -1);
						num += itemAtIndex.HorseComponent.MeatCount;
						if (itemRoster.FindIndexOfItem(itemAtIndex) == -1)
						{
							break;
						}
					}
				}
				num2--;
			}
			if (num > 0)
			{
				itemRoster.AddToCounts(DefaultItems.Meat, num);
				return true;
			}
			return false;
		}

		private void CheckAnimalBreeding(MobileParty party)
		{
			if (MBRandom.RandomFloat < DefaultPerks.Riding.Breeder.PrimaryBonus && !party.IsCurrentlyAtSea && party.HasPerk(DefaultPerks.Riding.Breeder) && (party.ItemRoster.NumberOfLivestockAnimals > 1 || party.ItemRoster.NumberOfPackAnimals > 1 || party.ItemRoster.NumberOfMounts > 1))
			{
				int num = party.ItemRoster.NumberOfLivestockAnimals + party.ItemRoster.NumberOfPackAnimals + party.ItemRoster.NumberOfMounts;
				ItemRosterElement randomElementWithPredicate = party.ItemRoster.GetRandomElementWithPredicate((ItemRosterElement x) => x.EquipmentElement.Item.HasHorseComponent);
				int num2 = TaleWorlds.Library.MathF.Round(TaleWorlds.Library.MathF.Max(1f, (float)num / 50f));
				party.ItemRoster.AddToCounts(randomElementWithPredicate.EquipmentElement.Item, num2);
				if (party.IsMainParty)
				{
					TextObject textObject = new TextObject("{=vl9bawa7}{COUNT} {?(COUNT > 1)}{PLURAL(ANIMAL_NAME)} are{?}{ANIMAL_NAME} is{\\?} added to your party.");
					textObject.SetTextVariable("COUNT", num2);
					textObject.SetTextVariable("ANIMAL_NAME", randomElementWithPredicate.EquipmentElement.Item.Name);
					InformationManager.DisplayMessage(new InformationMessage(textObject.ToString()));
				}
			}
		}

		private void MakeFoodConsumption(MobileParty party, ref int partyRemainingFoodPercentage)
		{
			ItemRoster itemRoster = party.ItemRoster;
			int num = 0;
			for (int i = 0; i < itemRoster.Count; i++)
			{
				if (itemRoster.GetItemAtIndex(i).IsFood)
				{
					num++;
				}
			}
			bool flag = false;
			while (num > 0 && partyRemainingFoodPercentage < 0)
			{
				int num2 = MBRandom.RandomInt(num);
				bool flag2 = false;
				int num3 = 0;
				int num4 = itemRoster.Count - 1;
				while (num4 >= 0 && !flag2)
				{
					if (itemRoster.GetItemAtIndex(num4).IsFood)
					{
						int elementNumber = itemRoster.GetElementNumber(num4);
						if (elementNumber > 0)
						{
							num3++;
							if (num2 < num3)
							{
								itemRoster.AddToCounts(itemRoster.GetItemAtIndex(num4), -1);
								partyRemainingFoodPercentage += 100;
								if (elementNumber == 1)
								{
									num--;
								}
								flag2 = true;
								flag = true;
							}
						}
					}
					num4--;
				}
				if (flag)
				{
					party.Party.OnConsumedFood();
				}
			}
		}
	}
	public class GarrisonRecruitmentCampaignBehavior : CampaignBehaviorBase, IGarrisonRecruitmentBehavior
	{
		public struct VolunteerTroop : IComparable
		{
			public Hero OwnerNotable;

			public int NotableVolunteerArrayIndex;

			public int Wage;

			public VolunteerTroop(Hero ownerNotable, int notableVolunteerArrayIndex)
			{
				OwnerNotable = ownerNotable;
				NotableVolunteerArrayIndex = notableVolunteerArrayIndex;
				Wage = Campaign.Current.Models.PartyWageModel.GetCharacterWage(ownerNotable.VolunteerTypes[notableVolunteerArrayIndex]);
			}

			public int CompareTo(object obj)
			{
				VolunteerTroop volunteerTroop = (VolunteerTroop)obj;
				int num = Wage.CompareTo(volunteerTroop.Wage);
				if (num == 0)
				{
					num = volunteerTroop.NotableVolunteerArrayIndex.CompareTo(NotableVolunteerArrayIndex);
				}
				if (num == 0)
				{
					num = volunteerTroop.OwnerNotable.Id.CompareTo(OwnerNotable.Id);
				}
				return num;
			}
		}

		private SortedSet<VolunteerTroop> _volunteerListCache = new SortedSet<VolunteerTroop>();

		public override void RegisterEvents()
		{
			CampaignEvents.DailyTickSettlementEvent.AddNonSerializedListener(this, OnDailySettlementTick);
		}

		private static CharacterObject GetBasicTroopForTown(Town town)
		{
			return town.MapFaction.BasicTroop;
		}

		private void OnDailySettlementTick(Settlement settlement)
		{
			if (settlement.IsFortification)
			{
				Town town = settlement.Town;
				if (SettlementCheckGarrisonChangeCommonCondition(settlement))
				{
					TickGarrisonChangeForTown(town);
				}
				if (CanSettlementAutoRecruit(settlement))
				{
					TickAutoRecruitmentGarrisonChange(town);
				}
				if (town.GarrisonParty != null)
				{
					HandleGarrisonXpChange(town);
				}
			}
		}

		private void TickAutoRecruitmentGarrisonChange(Town town)
		{
			float resultNumber = GetAutoRecruitmentGarrisonChangeExplainedNumber(town).ResultNumber;
			if (resultNumber > 0f)
			{
				if (town.GarrisonParty == null)
				{
					town.Owner.Settlement.AddGarrisonParty();
				}
				for (int i = 0; (float)i < resultNumber; i++)
				{
					VolunteerTroop volunteerTroop = _volunteerListCache.ElementAt(i);
					Hero ownerNotable = volunteerTroop.OwnerNotable;
					int notableVolunteerArrayIndex = volunteerTroop.NotableVolunteerArrayIndex;
					town.GarrisonParty.MemberRoster.AddToCounts(ownerNotable.VolunteerTypes[notableVolunteerArrayIndex], 1);
					town.Settlement.OwnerClan.AutoRecruitmentExpenses += Campaign.Current.Models.PartyWageModel.GetTroopRecruitmentCost(ownerNotable.VolunteerTypes[notableVolunteerArrayIndex], town.Settlement.OwnerClan.Leader).RoundedResultNumber;
					ownerNotable.VolunteerTypes[notableVolunteerArrayIndex] = null;
				}
			}
		}

		private void TickGarrisonChangeForTown(Town town)
		{
			int num = (int)GetBaseGarrisonChangeExplainedNumber(town).ResultNumber;
			if (num > 0)
			{
				if (town.GarrisonParty == null)
				{
					town.Owner.Settlement.AddGarrisonParty();
				}
				town.GarrisonParty.MemberRoster.AddToCounts(GetBasicTroopForTown(town), num);
			}
		}

		private void HandleGarrisonXpChange(Town town)
		{
			int num = Campaign.Current.Models.DailyTroopXpBonusModel.CalculateDailyTroopXpBonus(town);
			float num2 = Campaign.Current.Models.DailyTroopXpBonusModel.CalculateGarrisonXpBonusMultiplier(town);
			if (num <= 0)
			{
				return;
			}
			foreach (TroopRosterElement item in town.GarrisonParty.MemberRoster.GetTroopRoster())
			{
				town.GarrisonParty.MemberRoster.AddXpToTroop(item.Character, TaleWorlds.Library.MathF.Round((float)num * num2 * (float)item.Number));
			}
		}

		private void RepopulateVolunteerListCache(Town town)
		{
			_volunteerListCache.Clear();
			foreach (Hero notable in town.Settlement.Notables)
			{
				if (!notable.IsAlive)
				{
					continue;
				}
				int num = Campaign.Current.Models.VolunteerModel.MaximumIndexGarrisonCanRecruitFromHero(town.Settlement, notable);
				for (int i = 0; i < num; i++)
				{
					if (notable.VolunteerTypes[i] != null)
					{
						VolunteerTroop item = new VolunteerTroop(notable, i);
						_volunteerListCache.Add(item);
					}
				}
			}
			foreach (Village boundVillage in town.Settlement.BoundVillages)
			{
				if (boundVillage.VillageState != 0)
				{
					continue;
				}
				foreach (Hero notable2 in boundVillage.Settlement.Notables)
				{
					if (!notable2.IsAlive)
					{
						continue;
					}
					int num2 = Campaign.Current.Models.VolunteerModel.MaximumIndexGarrisonCanRecruitFromHero(town.Settlement, notable2);
					for (int j = 0; j < num2; j++)
					{
						if (notable2.VolunteerTypes[j] != null)
						{
							VolunteerTroop item2 = new VolunteerTroop(notable2, j);
							_volunteerListCache.Add(item2);
						}
					}
				}
			}
		}

		private ExplainedNumber GetAutoRecruitmentGarrisonChangeExplainedNumber(Town town)
		{
			ExplainedNumber result = new ExplainedNumber(0f, includeDescriptions: true);
			RepopulateVolunteerListCache(town);
			int num = town.GarrisonParty?.GetAvailableWageBudget() ?? town.Settlement.GarrisonWagePaymentLimit;
			if (num > 0)
			{
				int num2 = 0;
				int num3 = 0;
				int count = _volunteerListCache.Count;
				result.Add(count, new TextObject("{=Uzsnek6O}Auto Recruitment"));
				foreach (VolunteerTroop item in _volunteerListCache)
				{
					num2 += item.Wage;
					if (num2 >= num)
					{
						break;
					}
					num3++;
				}
				if ((float)num3 < result.LimitMaxValue)
				{
					result.LimitMax(num3, new TextObject("{=7GJOWuUO}Wage Limit"));
				}
				int num4 = ((town.GarrisonParty == null) ? ((int)Campaign.Current.Models.PartySizeLimitModel.CalculateGarrisonPartySizeLimit(town.Settlement).ResultNumber) : (town.GarrisonParty.Party.PartySizeLimit - town.GarrisonParty.Party.NumberOfAllMembers));
				if ((float)num4 < result.LimitMaxValue)
				{
					result.LimitMax(num4, new TextObject("{=mp68RYnD}Party Size Limit"));
				}
				int maximumDailyAutoRecruitmentCount = Campaign.Current.Models.SettlementGarrisonModel.GetMaximumDailyAutoRecruitmentCount(town);
				if ((float)maximumDailyAutoRecruitmentCount < result.LimitMaxValue)
				{
					result.LimitMax(maximumDailyAutoRecruitmentCount, new TextObject("{=91fnSU2A}Maximum Auto Recruitment"));
				}
			}
			return result;
		}

		private ExplainedNumber GetBaseGarrisonChangeExplainedNumber(Town town, bool includeDescriptions = false)
		{
			ExplainedNumber result = Campaign.Current.Models.SettlementGarrisonModel.CalculateBaseGarrisonChange(town.Settlement, includeDescriptions);
			int num = ((town.GarrisonParty == null) ? ((int)Campaign.Current.Models.PartySizeLimitModel.CalculateGarrisonPartySizeLimit(town.Settlement).ResultNumber) : (town.GarrisonParty.Party.PartySizeLimit - town.GarrisonParty.Party.NumberOfAllMembers));
			if (result.LimitMaxValue > (float)num)
			{
				result.LimitMax(num, new TextObject("{=mp68RYnD}Party Size Limit"));
			}
			int characterWage = Campaign.Current.Models.PartyWageModel.GetCharacterWage(GetBasicTroopForTown(town));
			int num2 = (town.GarrisonParty?.GetAvailableWageBudget() ?? town.Settlement.GarrisonWagePaymentLimit) / characterWage;
			if (result.LimitMaxValue > (float)num2)
			{
				result.LimitMax(num2, new TextObject("{=7GJOWuUO}Wage Limit"));
			}
			return result;
		}

		public ExplainedNumber GetGarrisonChangeExplainedNumber(Town town)
		{
			ExplainedNumber result = new ExplainedNumber(0f, includeDescriptions: true);
			ExplainedNumber baseGarrisonChangeExplainedNumber = GetBaseGarrisonChangeExplainedNumber(town, includeDescriptions: true);
			result.AddFromExplainedNumber(baseGarrisonChangeExplainedNumber, new TextObject("{=basevalue}Base"));
			if (CanSettlementAutoRecruit(town.Settlement))
			{
				ExplainedNumber autoRecruitmentGarrisonChangeExplainedNumber = GetAutoRecruitmentGarrisonChangeExplainedNumber(town);
				result.AddFromExplainedNumber(autoRecruitmentGarrisonChangeExplainedNumber, new TextObject("{=Uzsnek6O}Auto Recruitment"));
			}
			return result;
		}

		private bool CanSettlementAutoRecruit(Settlement settlement)
		{
			if (settlement.Town.GarrisonAutoRecruitmentIsEnabled && settlement.Town.FoodChange > 0f)
			{
				return SettlementCheckGarrisonChangeCommonCondition(settlement);
			}
			return false;
		}

		private bool SettlementCheckGarrisonChangeCommonCondition(Settlement settlement)
		{
			if (settlement.Party.MapEvent == null)
			{
				return settlement.Party.SiegeEvent == null;
			}
			return false;
		}

		public override void SyncData(IDataStore dataStore)
		{
		}
	}
	public class GarrisonTroopsCampaignBehavior : CampaignBehaviorBase
	{
		private struct ArmyGarrisonTransferDataArgs
		{
			public Settlement Settlement;

			public List<(MobileParty, int)> ArmyPartiesIdealPartySizes;

			public int TotalIdealPartySize;

			public int TotalMenCount;

			public int SettlementFinalMenCount;

			public int SettlementCurrentMenCount;

			public bool IsLeavingTroopsToGarrison;

			public List<(MobileParty, int)> GetTroopsToLeaveDataForArmy()
			{
				List<(MobileParty, int)> list = new List<(MobileParty, int)>();
				for (int i = 0; i < ArmyPartiesIdealPartySizes.Count; i++)
				{
					(MobileParty, int) tuple = ArmyPartiesIdealPartySizes[i];
					MobileParty item = tuple.Item1;
					int item2 = tuple.Item2;
					float num = (float)item2 / (float)TotalIdealPartySize;
					int val = MBMath.ClampInt(MBRandom.RoundRandomized((float)TotalMenCount * num), 30, item2);
					int numberOfRegularMembers = item.Party.NumberOfRegularMembers;
					val = Math.Min(val, numberOfRegularMembers);
					int num2 = numberOfRegularMembers - val;
					if (num2 > 0)
					{
						list.Add((item, num2));
					}
				}
				int num3 = list.Sum(((MobileParty, int) s) => s.Item2);
				int num4 = Math.Max(SettlementFinalMenCount - SettlementCurrentMenCount, 0);
				if (num3 > num4)
				{
					float num5 = (float)num4 / (float)num3;
					for (int num6 = list.Count - 1; num6 >= 0; num6--)
					{
						list[num6] = (list[num6].Item1, MBRandom.RoundRandomized((float)list[num6].Item2 * num5));
						if (list[num6].Item2 == 0)
						{
							list.RemoveAt(num6);
						}
					}
				}
				return list;
			}

			public List<(MobileParty, int)> GetTroopsToTakeDataForArmy()
			{
				List<(MobileParty, int)> list = new List<(MobileParty, int)>();
				if (SettlementFinalMenCount < SettlementCurrentMenCount)
				{
					for (int i = 0; i < ArmyPartiesIdealPartySizes.Count; i++)
					{
						(MobileParty, int) tuple = ArmyPartiesIdealPartySizes[i];
						var (mobileParty, _) = tuple;
						if (mobileParty.LeaderHero.Clan == Settlement.OwnerClan && !mobileParty.IsWageLimitExceeded())
						{
							int item = tuple.Item2;
							float num = (float)item / (float)TotalIdealPartySize;
							int val = MBMath.ClampInt(MBRandom.RoundRandomized((float)TotalMenCount * num), 30, item);
							int numberOfRegularMembers = mobileParty.Party.NumberOfRegularMembers;
							int val2 = Math.Max(val, numberOfRegularMembers) - numberOfRegularMembers;
							int val3 = Math.Max(item - numberOfRegularMembers, 0);
							val2 = Math.Min(val2, val3);
							if (val2 > 0)
							{
								list.Add((mobileParty, val2));
							}
						}
					}
					int num2 = list.Sum(((MobileParty, int) s) => s.Item2);
					int num3 = Math.Max(SettlementCurrentMenCount - SettlementFinalMenCount, 0);
					if (num2 > num3)
					{
						float num4 = (float)num3 / (float)num2;
						for (int num5 = list.Count - 1; num5 >= 0; num5--)
						{
							list[num5] = (list[num5].Item1, MBRandom.RoundRandomized((float)list[num5].Item2 * num4));
							if (list[num5].Item2 == 0)
							{
								list.RemoveAt(num5);
							}
						}
					}
				}
				return list;
			}
		}

		private struct PartyGarrisonTransferDataArgs
		{
			public Settlement Settlement;

			public MobileParty MobileParty;

			public int PartyIdealPartySize;

			public int SettlementIdealPartySize;

			public int TotalIdealPartySize;

			public int TotalMenCount;

			public int PartyCurrentMenCount;

			public int SettlementFinalMenCount;

			public int SettlementCurrentMenCount;

			public bool IsLeavingTroopsToGarrison;

			public int GetNumberOfTroopsToLeaveForParty()
			{
				int result = 0;
				if (SettlementFinalMenCount > SettlementCurrentMenCount)
				{
					float num = (float)PartyIdealPartySize / (float)TotalIdealPartySize;
					int val = MBMath.ClampInt(MBRandom.RoundRandomized((float)TotalMenCount * num), 30, PartyIdealPartySize);
					int partyCurrentMenCount = PartyCurrentMenCount;
					val = Math.Min(val, partyCurrentMenCount);
					result = partyCurrentMenCount - val;
					int val2 = Math.Max(SettlementIdealPartySize - SettlementCurrentMenCount, 0);
					result = Math.Min(result, val2);
				}
				return result;
			}

			public int GetNumberOfTroopsToTakeForParty()
			{
				int result = 0;
				if (MobileParty.LeaderHero.Clan == Settlement.OwnerClan && !MobileParty.IsWageLimitExceeded() && SettlementFinalMenCount < SettlementCurrentMenCount)
				{
					float num = (float)PartyIdealPartySize / (float)TotalIdealPartySize;
					int val = MBMath.ClampInt(MBRandom.RoundRandomized((float)TotalMenCount * num), 30, PartyIdealPartySize);
					int partyCurrentMenCount = PartyCurrentMenCount;
					result = Math.Max(val, partyCurrentMenCount) - partyCurrentMenCount;
					int val2 = Math.Max(PartyIdealPartySize - partyCurrentMenCount, 0);
					result = Math.Min(result, val2);
					int val3 = SettlementCurrentMenCount - SettlementFinalMenCount;
					result = Math.Min(result, val3);
				}
				return result;
			}
		}

		private const int PartyMinMenNumberAfterDonation = 30;

		private const int MinGarrisonNumberForTown = 125;

		private const int MinGarrisonNumberForCastle = 75;

		private const int MaxGarrisonNumberForTown = 750;

		private const int MaxGarrisonNumberForCastle = 500;

		private Settlement _newlyConqueredFortification;

		public override void RegisterEvents()
		{
			CampaignEvents.SettlementEntered.AddNonSerializedListener(this, OnSettlementEntered);
			CampaignEvents.OnNewGameCreatedPartialFollowUpEvent.AddNonSerializedListener(this, OnNewGameCreatedPartialFollowUpEvent);
			CampaignEvents.OnSettlementOwnerChangedEvent.AddNonSerializedListener(this, OnSettlementOwnerChanged);
		}

		public override void SyncData(IDataStore dataStore)
		{
		}

		private void OnNewGameCreatedPartialFollowUpEvent(CampaignGameStarter starter, int i)
		{
			List<Settlement> list = Campaign.Current.Settlements.WhereQ((Settlement x) => x.IsFortification).ToList();
			int count = list.Count;
			int num = count / 100 + ((count % 100 > i) ? 1 : 0);
			int num2 = count / 100 * i;
			for (int j = 0; j < i; j++)
			{
				num2 += ((count % 100 > j) ? 1 : 0);
			}
			for (int k = 0; k < num; k++)
			{
				Settlement settlement = list[num2 + k];
				settlement.AddGarrisonParty();
				FillGarrisonPartyOnNewGame(settlement.Town);
			}
		}

		private void FillGarrisonPartyOnNewGame(Town fortification)
		{
			PartyTemplateObject defaultPartyTemplate = fortification.Culture.DefaultPartyTemplate;
			float num = 1f + fortification.Prosperity / 1300f;
			int num2 = TaleWorlds.Library.MathF.Round(70f * num);
			for (int i = 0; i < num2; i++)
			{
				int index = 0;
				float num3 = 0f;
				for (int j = 0; j < defaultPartyTemplate.Stacks.Count; j++)
				{
					num3 += (defaultPartyTemplate.Stacks[j].Character.IsRanged ? 6f : ((!defaultPartyTemplate.Stacks[j].Character.IsMounted) ? 2f : 1f)) * ((float)(defaultPartyTemplate.Stacks[j].MaxValue + defaultPartyTemplate.Stacks[j].MinValue) / 2f);
				}
				float num4 = MBRandom.RandomFloat * num3;
				for (int k = 0; k < defaultPartyTemplate.Stacks.Count; k++)
				{
					num4 -= (defaultPartyTemplate.Stacks[k].Character.IsRanged ? 6f : ((!defaultPartyTemplate.Stacks[k].Character.IsMounted) ? 2f : 1f)) * ((float)(defaultPartyTemplate.Stacks[k].MaxValue + defaultPartyTemplate.Stacks[k].MinValue) / 2f);
					if (num4 < 0f)
					{
						index = k;
						break;
					}
				}
				CharacterObject character = defaultPartyTemplate.Stacks[index].Character;
				fortification.GarrisonParty.AddElementToMemberRoster(character, 1);
			}
		}

		private void OnSettlementOwnerChanged(Settlement settlement, bool openToClaim, Hero newOwner, Hero oldOwner, Hero capturerHero, ChangeOwnerOfSettlementAction.ChangeOwnerOfSettlementDetail detail)
		{
			if (openToClaim && detail == ChangeOwnerOfSettlementAction.ChangeOwnerOfSettlementDetail.BySiege && settlement != null)
			{
				_newlyConqueredFortification = settlement;
			}
		}

		private void OnSettlementEntered(MobileParty mobileParty, Settlement settlement, Hero hero)
		{
			if (!Campaign.Current.GameStarted || mobileParty == null || !mobileParty.IsLordParty || mobileParty.IsDisbanding || mobileParty.LeaderHero == null || !settlement.IsFortification || !DiplomacyHelper.IsSameFactionAndNotEliminated(mobileParty.MapFaction, settlement.MapFaction) || (settlement.OwnerClan == Clan.PlayerClan && settlement != _newlyConqueredFortification))
			{
				return;
			}
			if (mobileParty.Army != null)
			{
				if (mobileParty.Army.LeaderParty == mobileParty)
				{
					ManageGarrisonForArmy(mobileParty, settlement);
				}
			}
			else if (!mobileParty.IsMainParty)
			{
				ManageGarrisonForParty(mobileParty, settlement);
			}
		}

		private void ManageGarrisonForArmy(MobileParty armyLeaderParty, Settlement settlement)
		{
			CollectArmyGarrisonTransferDataArgs(armyLeaderParty, settlement, out var armyGarrionTransferDataArgs);
			if (armyGarrionTransferDataArgs.IsLeavingTroopsToGarrison)
			{
				TryToLeaveTroopsToGarrisonForArmy(in armyGarrionTransferDataArgs);
			}
			else
			{
				TryToTakeTroopsFromGarrisonForArmy(in armyGarrionTransferDataArgs);
			}
			_newlyConqueredFortification = null;
		}

		private void CollectArmyGarrisonTransferDataArgs(MobileParty armyLeaderParty, Settlement settlement, out ArmyGarrisonTransferDataArgs armyGarrionTransferDataArgs)
		{
			armyGarrionTransferDataArgs = default(ArmyGarrisonTransferDataArgs);
			int val = CalculateSettlementGarrisonPartySizeLimitWithFoodAndWage(settlement);
			int num = CalculateSettlementIdealPartySizeWithEffects(settlement);
			List<(MobileParty, int)> list = CalculateMobilePartiesIdealPartySizes(armyLeaderParty);
			int num2 = settlement.Town.GarrisonParty?.Party.NumberOfRegularMembers ?? 0;
			int num3 = num2;
			int num4 = num;
			foreach (var item in list)
			{
				num3 += item.Item1.Party.NumberOfRegularMembers;
				num4 += item.Item2;
			}
			float num5 = (float)num / (float)num4;
			int val2 = MBRandom.RoundRandomized((float)num3 * num5);
			int minValue = (settlement.IsTown ? 125 : 75);
			int maxValue = (settlement.IsTown ? 750 : 500);
			val2 = Math.Min(val2, val);
			val2 = MBMath.ClampInt(val2, minValue, maxValue);
			armyGarrionTransferDataArgs.Settlement = settlement;
			armyGarrionTransferDataArgs.ArmyPartiesIdealPartySizes = list;
			armyGarrionTransferDataArgs.TotalIdealPartySize = num4;
			armyGarrionTransferDataArgs.TotalMenCount = num3;
			armyGarrionTransferDataArgs.SettlementCurrentMenCount = num2;
			armyGarrionTransferDataArgs.SettlementFinalMenCount = val2;
			armyGarrionTransferDataArgs.IsLeavingTroopsToGarrison = val2 > num2;
			if (settlement.Town.GarrisonParty != null && settlement.Town.GarrisonParty.IsWageLimitExceeded())
			{
				armyGarrionTransferDataArgs.IsLeavingTroopsToGarrison = false;
			}
		}

		private void TryToLeaveTroopsToGarrisonForArmy(in ArmyGarrisonTransferDataArgs armyGarrisonTransferDataArgs)
		{
			foreach (var (mobileParty, numberOfTroopsToLeave) in armyGarrisonTransferDataArgs.GetTroopsToLeaveDataForArmy())
			{
				LeaveTroopsToGarrison(mobileParty, armyGarrisonTransferDataArgs.Settlement, numberOfTroopsToLeave, archersAreHighPriority: true);
			}
		}

		private void TryToTakeTroopsFromGarrisonForArmy(in ArmyGarrisonTransferDataArgs armyGarrisonTransferDataArgs)
		{
			foreach (var (mobileParty, numberOfTroopsToTake) in armyGarrisonTransferDataArgs.GetTroopsToTakeDataForArmy())
			{
				TakeTroopsFromGarrison(mobileParty, armyGarrisonTransferDataArgs.Settlement, numberOfTroopsToTake, archersAreHighPriority: false);
			}
		}

		private int CalculateSettlementIdealPartySizeWithEffects(Settlement settlement)
		{
			int num = CalculateSettlementGarrisonPartySizeLimitWithFoodAndWage(settlement);
			float num2 = (settlement.IsTown ? GetProsperityEffectForTown(settlement.Town) : 1f);
			float num3 = 1f;
			if (_newlyConqueredFortification != null)
			{
				num3 = (settlement.IsTown ? 1.75f : 1.33f);
			}
			float num4 = num2 * num3;
			return MBRandom.RoundRandomized((float)num * num4);
		}

		private void ManageGarrisonForParty(MobileParty mobileParty, Settlement settlement)
		{
			CollectPartyGarrisonTransferData(mobileParty, settlement, out var partyGarrisonTransferDataArgs);
			if (partyGarrisonTransferDataArgs.IsLeavingTroopsToGarrison)
			{
				TryToLeaveTroopsToGarrisonForParty(in partyGarrisonTransferDataArgs);
			}
			else
			{
				TryToTakeTroopsFromGarrisonForParty(in partyGarrisonTransferDataArgs);
			}
			_newlyConqueredFortification = null;
		}

		private void CollectPartyGarrisonTransferData(MobileParty mobileParty, Settlement settlement, out PartyGarrisonTransferDataArgs partyGarrisonTransferDataArgs)
		{
			partyGarrisonTransferDataArgs = default(PartyGarrisonTransferDataArgs);
			int num = CalculateSettlementGarrisonPartySizeLimitWithFoodAndWage(settlement);
			int num2 = CalculateSettlementIdealPartySizeWithEffects(settlement);
			int num3 = CalculateMobilePartySizeLimitWithFoodAndWage(mobileParty);
			int num4 = settlement.Town.GarrisonParty?.Party.NumberOfRegularMembers ?? 0;
			int num5 = mobileParty.Party.NumberOfRegularMembers + num4;
			int num6 = num2 + num3;
			float num7 = (float)num2 / (float)num6;
			int val = MBRandom.RoundRandomized((float)num5 * num7);
			int minValue = (settlement.IsTown ? 125 : 75);
			int maxValue = (settlement.IsTown ? 750 : 500);
			val = Math.Min(val, num);
			val = MBMath.ClampInt(val, minValue, maxValue);
			partyGarrisonTransferDataArgs.Settlement = settlement;
			partyGarrisonTransferDataArgs.MobileParty = mobileParty;
			partyGarrisonTransferDataArgs.PartyIdealPartySize = num3;
			partyGarrisonTransferDataArgs.SettlementIdealPartySize = num;
			partyGarrisonTransferDataArgs.TotalIdealPartySize = num6;
			partyGarrisonTransferDataArgs.PartyCurrentMenCount = mobileParty.Party.NumberOfRegularMembers;
			partyGarrisonTransferDataArgs.SettlementCurrentMenCount = num4;
			partyGarrisonTransferDataArgs.TotalMenCount = num5;
			partyGarrisonTransferDataArgs.SettlementFinalMenCount = val;
			partyGarrisonTransferDataArgs.IsLeavingTroopsToGarrison = val > num4;
			if ((settlement.Town.GarrisonParty != null && settlement.Town.GarrisonParty.IsWageLimitExceeded()) || (mobileParty.LeaderHero.Clan == Clan.PlayerClan && _newlyConqueredFortification == null))
			{
				partyGarrisonTransferDataArgs.IsLeavingTroopsToGarrison = false;
			}
		}

		private void TryToLeaveTroopsToGarrisonForParty(in PartyGarrisonTransferDataArgs partyGarrisonTransferDataArgs)
		{
			int numberOfTroopsToLeaveForParty = partyGarrisonTransferDataArgs.GetNumberOfTroopsToLeaveForParty();
			if (numberOfTroopsToLeaveForParty > 0)
			{
				LeaveTroopsToGarrison(partyGarrisonTransferDataArgs.MobileParty, partyGarrisonTransferDataArgs.Settlement, numberOfTroopsToLeaveForParty, archersAreHighPriority: true);
			}
		}

		private void TryToTakeTroopsFromGarrisonForParty(in PartyGarrisonTransferDataArgs partyGarrisonTransferDataArgs)
		{
			int numberOfTroopsToTakeForParty = partyGarrisonTransferDataArgs.GetNumberOfTroopsToTakeForParty();
			if (numberOfTroopsToTakeForParty > 0)
			{
				TakeTroopsFromGarrison(partyGarrisonTransferDataArgs.MobileParty, partyGarrisonTransferDataArgs.Settlement, numberOfTroopsToTakeForParty, archersAreHighPriority: false);
			}
		}

		private List<(MobileParty, int)> CalculateMobilePartiesIdealPartySizes(MobileParty armyLeaderParty)
		{
			List<(MobileParty, int)> list = new List<(MobileParty, int)>();
			List<MobileParty> list2 = new List<MobileParty>();
			if (armyLeaderParty != MobileParty.MainParty && (armyLeaderParty.LeaderHero.Clan != Clan.PlayerClan || _newlyConqueredFortification != null))
			{
				list2.Add(armyLeaderParty);
			}
			foreach (MobileParty attachedParty in armyLeaderParty.AttachedParties)
			{
				if (attachedParty != MobileParty.MainParty && attachedParty.LeaderHero != null && (attachedParty.LeaderHero.Clan != Clan.PlayerClan || _newlyConqueredFortification != null))
				{
					list2.Add(attachedParty);
				}
			}
			foreach (MobileParty item2 in list2)
			{
				int item = CalculateMobilePartySizeLimitWithFoodAndWage(item2);
				list.Add((item2, item));
			}
			return list;
		}

		private int CalculateMobilePartySizeLimitWithFoodAndWage(MobileParty mobileParty)
		{
			int partySizeLimit = mobileParty.Party.PartySizeLimit;
			int a = TaleWorlds.Library.MathF.Round((float)mobileParty.PaymentLimit / Campaign.Current.AverageWage);
			int num = 2;
			int numberOfMenOnMapToEatOneFood = Campaign.Current.Models.MobilePartyFoodConsumptionModel.NumberOfMenOnMapToEatOneFood;
			float num2 = ((mobileParty.Army != null) ? mobileParty.Army.Parties.Sum((MobileParty s) => s.Food) : mobileParty.Food);
			int a2 = TaleWorlds.Library.MathF.Round((float)numberOfMenOnMapToEatOneFood * num2 / (float)num);
			return TaleWorlds.Library.MathF.Min(b: TaleWorlds.Library.MathF.Max(a2, 30), a: TaleWorlds.Library.MathF.Min(a, partySizeLimit));
		}

		private int CalculateMaxGarrisonSizeTownCanFeed(Town town, bool includeMarketStocks = true)
		{
			SettlementFoodModel settlementFoodModel = Campaign.Current.Models.SettlementFoodModel;
			if (settlementFoodModel == null)
			{
				return 0;
			}
			float resultNumber = settlementFoodModel.CalculateTownFoodStocksChange(town, includeMarketStocks).ResultNumber;
			int num = town.GarrisonParty?.Party.NumberOfRegularMembers ?? 0;
			float num2 = 0f;
			float num3 = 0f;
			if (town.Governor != null)
			{
				if (town.IsUnderSiege)
				{
					if (town.Governor.GetPerkValue(DefaultPerks.Steward.Gourmet))
					{
						num3 += DefaultPerks.Steward.Gourmet.SecondaryBonus;
					}
					if (town.Governor.GetPerkValue(DefaultPerks.Medicine.TriageTent))
					{
						num2 += DefaultPerks.Medicine.TriageTent.SecondaryBonus;
					}
				}
				if (town.Governor.GetPerkValue(DefaultPerks.Steward.MasterOfWarcraft))
				{
					num2 += DefaultPerks.Steward.MasterOfWarcraft.SecondaryBonus;
				}
			}
			int num4 = 0;
			float num5 = (0f - town.Prosperity) / (float)settlementFoodModel.NumberOfProsperityToEatOneFood;
			float num6 = 1f;
			float num7 = num5 * num6;
			if (resultNumber < num7)
			{
				if (_newlyConqueredFortification != null)
				{
					return (int)MBMath.Map(town.Prosperity, 0f, 8000f, 150f, 300f);
				}
				int num8 = TaleWorlds.Library.MathF.Round(TaleWorlds.Library.MathF.Abs(resultNumber - num7) * (float)settlementFoodModel.NumberOfMenOnGarrisonToEatOneFood / (1f + num2 + num3));
				return Math.Max(num - num8, 0);
			}
			int num9 = TaleWorlds.Library.MathF.Round((TaleWorlds.Library.MathF.Abs(num7) + resultNumber) * (float)settlementFoodModel.NumberOfMenOnGarrisonToEatOneFood / (1f + num2 + num3));
			return num + num9;
		}

		private int CalculateSettlementGarrisonPartySizeLimitWithFoodAndWage(Settlement settlement)
		{
			int a = (int)Campaign.Current.Models.PartySizeLimitModel.CalculateGarrisonPartySizeLimit(settlement).ResultNumber;
			float num = FactionHelper.FindIdealGarrisonStrengthPerWalledCenter(settlement.OwnerClan.MapFaction as Kingdom, settlement.OwnerClan);
			List<float> list = new List<float>();
			float num2;
			if (settlement.OwnerClan.Kingdom != null)
			{
				foreach (Clan clan in settlement.OwnerClan.Kingdom.Clans)
				{
					list.Add(FactionHelper.OwnerClanEconomyEffectOnGarrisonSizeConstant(clan));
				}
				num2 = list.Average();
			}
			else
			{
				num2 = FactionHelper.OwnerClanEconomyEffectOnGarrisonSizeConstant(settlement.OwnerClan);
			}
			float num3 = FactionHelper.SettlementProsperityEffectOnGarrisonSizeConstant(settlement.Town);
			float num4 = FactionHelper.SettlementFoodPotentialEffectOnGarrisonSizeConstant(settlement);
			float num5 = num2 * num3 * num4;
			float num6 = 1.5f;
			int b = TaleWorlds.Library.MathF.Round(num5 * num * num6);
			int b2 = CalculateMaxGarrisonSizeTownCanFeed(settlement.Town);
			return TaleWorlds.Library.MathF.Min(TaleWorlds.Library.MathF.Min(a, b2), b);
		}

		private float GetProsperityEffectForTown(Town town)
		{
			return MBMath.Map(town.Prosperity, 0f, 8000f, 1f, 1.35f);
		}

		private CharacterObject GetASuitableCharacterFromPartyRosterByWeight(TroopRoster troopRoster, bool archersAreHighPriority)
		{
			List<(CharacterObject, float)> list = new List<(CharacterObject, float)>();
			for (int i = 0; i < troopRoster.Count; i++)
			{
				TroopRosterElement elementCopyAtIndex = troopRoster.GetElementCopyAtIndex(i);
				if (!elementCopyAtIndex.Character.IsHero)
				{
					if (archersAreHighPriority && elementCopyAtIndex.Character.IsRanged)
					{
						list.Add((elementCopyAtIndex.Character, elementCopyAtIndex.Number * 4));
					}
					else
					{
						list.Add((elementCopyAtIndex.Character, elementCopyAtIndex.Number));
					}
				}
			}
			if (!list.IsEmpty())
			{
				return MBRandom.ChooseWeighted(list);
			}
			return null;
		}

		private void LeaveTroopsToGarrison(MobileParty mobileParty, Settlement settlement, int numberOfTroopsToLeave, bool archersAreHighPriority)
		{
			TroopRoster troopRoster = TroopRoster.CreateDummyTroopRoster();
			for (int i = 0; i < numberOfTroopsToLeave; i++)
			{
				CharacterObject aSuitableCharacterFromPartyRosterByWeight = GetASuitableCharacterFromPartyRosterByWeight(mobileParty.MemberRoster, archersAreHighPriority);
				if (aSuitableCharacterFromPartyRosterByWeight == null)
				{
					break;
				}
				foreach (TroopRosterElement item in mobileParty.MemberRoster.GetTroopRoster())
				{
					if (item.Character == aSuitableCharacterFromPartyRosterByWeight)
					{
						if (settlement.Town.GarrisonParty == null)
						{
							settlement.AddGarrisonParty();
						}
						if (item.WoundedNumber > 0)
						{
							settlement.Town.GarrisonParty.MemberRoster.AddToCounts(aSuitableCharacterFromPartyRosterByWeight, 1, insertAtFront: false, 1);
							troopRoster.AddToCounts(aSuitableCharacterFromPartyRosterByWeight, 1, insertAtFront: false, 1);
							mobileParty.MemberRoster.AddToCounts(aSuitableCharacterFromPartyRosterByWeight, -1, insertAtFront: false, -1);
						}
						else
						{
							settlement.Town.GarrisonParty.MemberRoster.AddToCounts(aSuitableCharacterFromPartyRosterByWeight, 1);
							troopRoster.AddToCounts(aSuitableCharacterFromPartyRosterByWeight, 1);
							mobileParty.MemberRoster.AddToCounts(aSuitableCharacterFromPartyRosterByWeight, -1);
						}
						break;
					}
				}
			}
			if (troopRoster.Count > 0)
			{
				CampaignEventDispatcher.Instance.OnTroopGivenToSettlement(mobileParty.LeaderHero, settlement, troopRoster);
				ApplyKingdomInfluenceBonusForLeavingTroopToGarrison(mobileParty, settlement, troopRoster);
			}
		}

		private void TakeTroopsFromGarrison(MobileParty mobileParty, Settlement settlement, int numberOfTroopsToTake, bool archersAreHighPriority)
		{
			for (int i = 0; i < numberOfTroopsToTake; i++)
			{
				CharacterObject aSuitableCharacterFromPartyRosterByWeight = GetASuitableCharacterFromPartyRosterByWeight(settlement.Town.GarrisonParty.MemberRoster, archersAreHighPriority);
				if (aSuitableCharacterFromPartyRosterByWeight == null)
				{
					break;
				}
				foreach (TroopRosterElement item in settlement.Town.GarrisonParty.MemberRoster.GetTroopRoster())
				{
					if (item.Character == aSuitableCharacterFromPartyRosterByWeight)
					{
						if (item.Number - item.WoundedNumber > 0)
						{
							mobileParty.MemberRoster.AddToCounts(aSuitableCharacterFromPartyRosterByWeight, 1);
							settlement.Town.GarrisonParty.MemberRoster.AddToCounts(aSuitableCharacterFromPartyRosterByWeight, -1);
						}
						else
						{
							mobileParty.MemberRoster.AddToCounts(aSuitableCharacterFromPartyRosterByWeight, 1, insertAtFront: false, 1);
							settlement.Town.GarrisonParty.MemberRoster.AddToCounts(aSuitableCharacterFromPartyRosterByWeight, -1, insertAtFront: false, -1);
						}
						break;
					}
				}
			}
		}

		private void ApplyKingdomInfluenceBonusForLeavingTroopToGarrison(MobileParty mobileParty, Settlement settlement, TroopRoster troopsToBeTransferred)
		{
			if (mobileParty.LeaderHero == null || settlement.OwnerClan == mobileParty.LeaderHero.Clan)
			{
				return;
			}
			float num = 0f;
			foreach (TroopRosterElement item in troopsToBeTransferred.GetTroopRoster())
			{
				float troopPower = Campaign.Current.Models.MilitaryPowerModel.GetTroopPower(item.Character, BattleSideEnum.Defender, MapEvent.PowerCalculationContext.Siege, 0f);
				num += troopPower * (float)item.Number;
			}
			GainKingdomInfluenceAction.ApplyForLeavingTroopToGarrison(mobileParty.LeaderHero, num / 3f);
		}
	}
	public class GovernorCampaignBehavior : CampaignBehaviorBase
	{
