		public override void SyncData(IDataStore dataStore)
		{
		}

		private void RefreshLocationOfHeroesForPlayersCurrentSettlement()
		{
			if (LocationComplex.Current == null || Settlement.CurrentSettlement == null || (!Settlement.CurrentSettlement.IsFortification && !Settlement.CurrentSettlement.IsVillage) || LocationComplex.Current != Settlement.CurrentSettlement.LocationComplex)
			{
				return;
			}
			Settlement currentSettlement = Settlement.CurrentSettlement;
			List<Hero> list = currentSettlement.HeroesWithoutParty.ToList();
			Hero hero = (currentSettlement.MapFaction.IsKingdomFaction ? ((Kingdom)currentSettlement.MapFaction).Leader : currentSettlement.OwnerClan.Leader);
			Hero hero2 = hero?.Spouse;
			if (hero != null)
			{
				list.Add(hero);
			}
			if (hero2 != null)
			{
				list.Add(hero2);
			}
			list.AddRange(Clan.PlayerClan.AliveLords);
			list.AddRange(Hero.MainHero.CompanionsInParty);
			list.AddRange(from x in currentSettlement.SettlementComponent.GetPrisonerHeroes()
				select x.HeroObject);
			foreach (MobileParty party in currentSettlement.Parties)
			{
				if (party.LeaderHero != null && party.LeaderHero != Hero.MainHero)
				{
					list.Add(party.LeaderHero);
				}
			}
			foreach (Hero item in list)
			{
				RefreshLocationOfHeroForSettlement(item, currentSettlement);
			}
		}

		private void RefreshLocationOfHeroForSettlement(Hero hero, Settlement settlement)
		{
			Location locationOfCharacter = settlement.LocationComplex.GetLocationOfCharacter(hero);
			HeroAgentLocationModel.HeroLocationDetail heroSpawnDetail;
			Location locationForHero = Campaign.Current.Models.HeroAgentLocationModel.GetLocationForHero(hero, settlement, out heroSpawnDetail);
			if (locationOfCharacter == null && locationForHero != null)
			{
				LocationCharacter locationCharacter = CreateLocationCharacterForHero(hero, settlement, heroSpawnDetail);
				locationForHero.AddCharacter(locationCharacter);
			}
			else if (locationOfCharacter != null && locationOfCharacter != locationForHero)
			{
				LocationCharacter locationCharacterOfHero = settlement.LocationComplex.GetLocationCharacterOfHero(hero);
				settlement.LocationComplex.ChangeLocation(locationCharacterOfHero, locationOfCharacter, locationForHero);
			}
		}

		private void SetAgentDataProperties(Hero hero, HeroAgentLocationModel.HeroLocationDetail locationReason, ref AgentData agentData)
		{
			Monster monster = new Monster();
			monster = ((locationReason != HeroAgentLocationModel.HeroLocationDetail.PlayerClanMember && locationReason != HeroAgentLocationModel.HeroLocationDetail.MainPartyCompanion) ? FaceGen.GetMonsterWithSuffix(hero.CharacterObject.Race, "_settlement") : FaceGen.GetBaseMonsterFromRace(hero.CharacterObject.Race));
			agentData.Monster(monster);
			agentData.NoHorses(noHorses: true);
			if (locationReason != HeroAgentLocationModel.HeroLocationDetail.Wanderer)
			{
				uint color = (uint)(((int?)hero.MapFaction?.Color) ?? (-3357781));
				uint color2 = (uint)(((int?)hero.MapFaction?.Color) ?? (-3357781));
				agentData.ClothingColor1(color).ClothingColor2(color2);
			}
		}

		private LocationCharacter CreateLocationCharacterForHero(Hero hero, Settlement settlement, HeroAgentLocationModel.HeroLocationDetail heroLocationDetail)
		{
			AgentData agentData = null;
			switch (heroLocationDetail)
			{
			case HeroAgentLocationModel.HeroLocationDetail.NobleBelongingToNoParty:
			case HeroAgentLocationModel.HeroLocationDetail.Prisoner:
				agentData = new AgentData(new SimpleAgentOrigin(hero.CharacterObject));
				break;
			case HeroAgentLocationModel.HeroLocationDetail.PlayerClanMember:
			case HeroAgentLocationModel.HeroLocationDetail.MainPartyCompanion:
				agentData = new AgentData(new PartyAgentOrigin(PartyBase.MainParty, hero.CharacterObject));
				break;
			case HeroAgentLocationModel.HeroLocationDetail.PartyLeader:
				agentData = new AgentData(new PartyAgentOrigin(hero.PartyBelongedTo.Party, hero.CharacterObject));
				break;
			default:
				agentData = new AgentData(new PartyAgentOrigin(null, hero.CharacterObject));
				break;
			}
			SetAgentDataProperties(hero, heroLocationDetail, ref agentData);
			LocationCharacter.AddBehaviorsDelegate addBehaviorsDelegate = ((heroLocationDetail == HeroAgentLocationModel.HeroLocationDetail.PlayerClanMember || heroLocationDetail == HeroAgentLocationModel.HeroLocationDetail.MainPartyCompanion) ? new LocationCharacter.AddBehaviorsDelegate(SandBoxManager.Instance.AgentBehaviorManager.AddCompanionBehaviors) : new LocationCharacter.AddBehaviorsDelegate(SandBoxManager.Instance.AgentBehaviorManager.AddFixedCharacterBehaviors));
			string text = "";
			bool forceSpawnOnSpecialTargetTag = false;
			switch (heroLocationDetail)
			{
			case HeroAgentLocationModel.HeroLocationDetail.SettlementKingQueen:
				text = "sp_throne";
				break;
			case HeroAgentLocationModel.HeroLocationDetail.Prisoner:
				text = "sp_prisoner";
				forceSpawnOnSpecialTargetTag = true;
				break;
			case HeroAgentLocationModel.HeroLocationDetail.Notable:
			{
				if (!settlement.IsFortification)
				{
					break;
				}
				text = (hero.IsArtisan ? "sp_notable_artisan" : (hero.IsMerchant ? "sp_notable_merchant" : (hero.IsPreacher ? "sp_notable_preacher" : (hero.IsGangLeader ? "sp_notable_gangleader" : (hero.IsRuralNotable ? "sp_notable_rural_notable" : ((hero.GovernorOf == hero.CurrentSettlement.Town) ? "sp_governor" : "sp_notable"))))));
				MBReadOnlyList<Workshop> ownedWorkshops = hero.OwnedWorkshops;
				if (ownedWorkshops.Count == 0)
				{
					break;
				}
				for (int i = 0; i < ownedWorkshops.Count; i++)
				{
					if (!ownedWorkshops[i].WorkshopType.IsHidden)
					{
						text = text + "_" + ownedWorkshops[i].Tag;
						break;
					}
				}
				break;
			}
			case HeroAgentLocationModel.HeroLocationDetail.PartylessHeroInsideVillage:
				text = "sp_notable_rural_notable";
				break;
			case HeroAgentLocationModel.HeroLocationDetail.Wanderer:
				text = "npc_common";
				break;
			default:
				text = "sp_notable";
				break;
			}
			bool fixedLocation = heroLocationDetail != HeroAgentLocationModel.HeroLocationDetail.PartylessHeroInsideVillage;
			LocationCharacter.CharacterRelations characterRelation = LocationCharacter.CharacterRelations.Neutral;
			if (heroLocationDetail == HeroAgentLocationModel.HeroLocationDetail.PlayerClanMember || heroLocationDetail == HeroAgentLocationModel.HeroLocationDetail.MainPartyCompanion)
			{
				characterRelation = LocationCharacter.CharacterRelations.Friendly;
			}
			string actionSetCode = "";
			switch (heroLocationDetail)
			{
			case HeroAgentLocationModel.HeroLocationDetail.SettlementKingQueen:
			case HeroAgentLocationModel.HeroLocationDetail.NobleBelongingToNoParty:
			case HeroAgentLocationModel.HeroLocationDetail.PartyLeader:
				actionSetCode = ActionSetCode.GenerateActionSetNameWithSuffix(agentData.AgentMonster, hero.IsFemale, "_lord");
				break;
			case HeroAgentLocationModel.HeroLocationDetail.Prisoner:
				actionSetCode = ActionSetCode.GenerateActionSetNameWithSuffix(agentData.AgentMonster, hero.IsFemale, "_villager");
				break;
			case HeroAgentLocationModel.HeroLocationDetail.Notable:
				if (settlement.IsFortification)
				{
					string text2 = null;
					text2 = (hero.IsArtisan ? "_villager_artisan" : (hero.IsMerchant ? "_villager_merchant" : (hero.IsPreacher ? "_villager_preacher" : (hero.IsGangLeader ? "_villager_gangleader" : (hero.IsRuralNotable ? "_villager_ruralnotable" : (hero.IsFemale ? "_lord" : "_villager_merchant"))))));
					actionSetCode = ActionSetCode.GenerateActionSetNameWithSuffix(agentData.AgentMonster, hero.IsFemale, text2);
				}
				break;
			case HeroAgentLocationModel.HeroLocationDetail.PartylessHeroInsideVillage:
				actionSetCode = null;
				break;
			case HeroAgentLocationModel.HeroLocationDetail.Wanderer:
				actionSetCode = ((settlement.Culture.StringId.ToLower() == "aserai" || settlement.Culture.StringId.ToLower() == "khuzait") ? ActionSetCode.GenerateActionSetNameWithSuffix(agentData.AgentMonster, hero.IsFemale, "_warrior_in_aserai_tavern") : ActionSetCode.GenerateActionSetNameWithSuffix(agentData.AgentMonster, hero.IsFemale, "_warrior_in_tavern"));
				break;
			case HeroAgentLocationModel.HeroLocationDetail.PlayerClanMember:
			case HeroAgentLocationModel.HeroLocationDetail.MainPartyCompanion:
				actionSetCode = null;
				break;
			default:
				TaleWorlds.Library.Debug.FailedAssert("action Set Code is not set properly with a location reason!", "C:\\BuildAgent\\work\\mb3\\Source\\Bannerlord\\TaleWorlds.CampaignSystem\\CampaignBehaviors\\HeroAgentSpawnCampaignBehavior.cs", "CreateLocationCharacterForHero", 280);
				break;
			}
			bool useCivilianEquipment = true;
			switch (heroLocationDetail)
			{
			case HeroAgentLocationModel.HeroLocationDetail.PlayerClanMember:
			case HeroAgentLocationModel.HeroLocationDetail.MainPartyCompanion:
				useCivilianEquipment = !PlayerEncounter.LocationEncounter.Settlement.IsVillage;
				break;
			case HeroAgentLocationModel.HeroLocationDetail.PartyLeader:
				useCivilianEquipment = !settlement.IsVillage;
				break;
			}
			bool isVisualTracked = heroLocationDetail == HeroAgentLocationModel.HeroLocationDetail.PlayerClanMember || heroLocationDetail == HeroAgentLocationModel.HeroLocationDetail.MainPartyCompanion;
			return new LocationCharacter(agentData, addBehaviorsDelegate, text, fixedLocation, characterRelation, actionSetCode, useCivilianEquipment, isFixedCharacter: false, null, isHidden: false, isVisualTracked, overrideBodyProperties: true, null, forceSpawnOnSpecialTargetTag);
		}

		private void OnGovernorChanged(Town town, Hero oldGovernor, Hero newGovernor)
		{
			if (LocationComplex.Current != null)
			{
				if (oldGovernor != null)
				{
					RefreshLocationOfHeroForSettlement(oldGovernor, town.Settlement);
				}
				if (newGovernor != null)
				{
					RefreshLocationOfHeroForSettlement(newGovernor, town.Settlement);
				}
			}
		}

		private void OnMissionEnded(IMission mission)
		{
			if (LocationComplex.Current != null && PlayerEncounter.LocationEncounter != null && Settlement.CurrentSettlement != null && !Hero.MainHero.IsPrisoner && !Settlement.CurrentSettlement.IsUnderSiege)
			{
				RefreshLocationOfHeroesForPlayersCurrentSettlement();
			}
		}

		public void OnSettlementEntered(MobileParty mobileParty, Settlement settlement, Hero hero)
		{
			if (LocationComplex.Current != null && PlayerEncounter.LocationEncounter != null && settlement.LocationComplex == LocationComplex.Current)
			{
				RefreshLocationOfHeroesForPlayersCurrentSettlement();
			}
		}

		public void OnSettlementLeft(MobileParty mobileParty, Settlement settlement)
		{
			if (LocationComplex.Current != null && PlayerEncounter.LocationEncounter != null && settlement.LocationComplex == LocationComplex.Current && mobileParty != MobileParty.MainParty && mobileParty.LeaderHero != null)
			{
				RefreshLocationOfHeroForSettlement(mobileParty.LeaderHero, settlement);
			}
		}

		private void OnGameLoadFinished()
		{
			if (!Hero.MainHero.IsPrisoner && Settlement.CurrentSettlement != null && !Settlement.CurrentSettlement.IsUnderSiege)
			{
				RefreshLocationOfHeroesForPlayersCurrentSettlement();
			}
		}

		private void OnHeroPrisonerTaken(PartyBase capturerParty, Hero prisoner)
		{
			if (capturerParty.IsSettlement)
			{
				OnPrisonersChangeInSettlement(capturerParty.Settlement, null, prisoner, takenFromDungeon: false);
			}
		}

		public void OnPrisonersChangeInSettlement(Settlement settlement, FlattenedTroopRoster prisonerRoster, Hero prisonerHero, bool takenFromDungeon)
		{
			if (settlement == null || !settlement.IsFortification || LocationComplex.Current != settlement.LocationComplex)
			{
				return;
			}
			if (prisonerHero != null && prisonerHero != Hero.OneToOneConversationHero)
			{
				RefreshLocationOfHeroForSettlement(prisonerHero, settlement);
			}
			if (prisonerRoster == null)
			{
				return;
			}
			foreach (FlattenedTroopRosterElement item in prisonerRoster)
			{
				if (item.Troop.IsHero && prisonerHero != Hero.OneToOneConversationHero)
				{
					RefreshLocationOfHeroForSettlement(item.Troop.HeroObject, settlement);
				}
			}
		}
	}
	public class HeroKnownInformationCampaignBehavior : CampaignBehaviorBase
	{
		public override void RegisterEvents()
		{
			CampaignEvents.DailyTickHeroEvent.AddNonSerializedListener(this, OnDailyTickHero);
			CampaignEvents.ConversationEnded.AddNonSerializedListener(this, ConversationEnded);
			CampaignEvents.OnAgentJoinedConversationEvent.AddNonSerializedListener(this, OnAgentJoinedConversation);
			CampaignEvents.OnPlayerMetHeroEvent.AddNonSerializedListener(this, OnPlayerMetHero);
			CampaignEvents.BeforeHeroesMarried.AddNonSerializedListener(this, OnHeroesMarried);
			CampaignEvents.HeroCreated.AddNonSerializedListener(this, OnHeroCreated);
			CampaignEvents.OnGameLoadFinishedEvent.AddNonSerializedListener(this, OnGameLoadFinishedEvent);
			CampaignEvents.OnCharacterCreationIsOverEvent.AddNonSerializedListener(this, OnCharacterCreationIsOver);
			CampaignEvents.OnPlayerLearnsAboutHeroEvent.AddNonSerializedListener(this, OnPlayerLearnsAboutHero);
			CampaignEvents.NearbyPartyAddedToPlayerMapEvent.AddNonSerializedListener(this, OnNearbyPartyAddedToPlayerMapEvent);
			CampaignEvents.GameMenuOpened.AddNonSerializedListener(this, OnGameMenuChanged);
			CampaignEvents.AfterMissionStarted.AddNonSerializedListener(this, OnAfterMissionStarted);
			CampaignEvents.MapEventStarted.AddNonSerializedListener(this, OnMapEventStarted);
			CampaignEvents.PartyAttachedAnotherParty.AddNonSerializedListener(this, OnPartyAttachedAnotherParty);
			CampaignEvents.OnPlayerJoinedTournamentEvent.AddNonSerializedListener(this, OnPlayerJoinedTournament);
			CampaignEvents.OnMarriageOfferedToPlayerEvent.AddNonSerializedListener(this, OnMarriageOfferedToPlayer);
		}

		private void OnMarriageOfferedToPlayer(Hero suitor, Hero maiden)
		{
			if (suitor.Clan == Clan.PlayerClan)
			{
				maiden.IsKnownToPlayer = true;
			}
			else
			{
				suitor.IsKnownToPlayer = true;
			}
		}

		private void OnPlayerJoinedTournament(Town town, bool isParticipant)
		{
			foreach (CharacterObject participantCharacter in Campaign.Current.TournamentManager.GetTournamentGame(town).GetParticipantCharacters(town.Settlement, includePlayer: false))
			{
				if (participantCharacter.IsHero && !participantCharacter.HeroObject.IsKnownToPlayer)
				{
					participantCharacter.HeroObject.IsKnownToPlayer = true;
				}
			}
		}

		private void OnNearbyPartyAddedToPlayerMapEvent(MobileParty mobileParty)
		{
			if (mobileParty.LeaderHero != null)
			{
				mobileParty.LeaderHero.IsKnownToPlayer = true;
			}
		}

		private void OnPartyAttachedAnotherParty(MobileParty party)
		{
			if (party == MobileParty.MainParty)
			{
				if (party.AttachedTo.LeaderHero != null)
				{
					party.AttachedTo.LeaderHero.IsKnownToPlayer = true;
				}
				{
					foreach (MobileParty attachedParty in party.AttachedTo.AttachedParties)
					{
						if (attachedParty.LeaderHero != null)
						{
							attachedParty.LeaderHero.IsKnownToPlayer = true;
						}
					}
					return;
				}
			}
			if ((party.AttachedTo == MobileParty.MainParty || party.AttachedTo == MobileParty.MainParty.AttachedTo) && party.LeaderHero != null)
			{
				party.LeaderHero.IsKnownToPlayer = true;
			}
		}

		private void OnPartyAttachedToAnotherParty(MobileParty mobileParty)
		{
			if (mobileParty == MobileParty.MainParty)
			{
				if (mobileParty.AttachedTo.LeaderHero != null)
				{
					mobileParty.AttachedTo.LeaderHero.IsKnownToPlayer = true;
				}
				{
					foreach (MobileParty attachedParty in mobileParty.AttachedTo.AttachedParties)
					{
						if (attachedParty.LeaderHero != null)
						{
							attachedParty.LeaderHero.IsKnownToPlayer = true;
						}
					}
					return;
				}
			}
			if ((mobileParty.AttachedTo == MobileParty.MainParty || mobileParty.AttachedTo == MobileParty.MainParty.AttachedTo) && mobileParty.LeaderHero != null)
			{
				mobileParty.LeaderHero.IsKnownToPlayer = true;
			}
		}

		private void OnMapEventStarted(MapEvent mapEvent, PartyBase attackerParty, PartyBase defenderParty)
		{
			if (MapEvent.PlayerMapEvent != mapEvent)
			{
				return;
			}
			foreach (PartyBase involvedParty in mapEvent.InvolvedParties)
			{
				if (involvedParty.LeaderHero != null)
				{
					involvedParty.LeaderHero.IsKnownToPlayer = true;
				}
			}
		}

		private void OnPlayerLearnsAboutHero(Hero hero)
		{
			UpdateHeroLocation(hero);
			if (hero.Clan != Clan.PlayerClan)
			{
				TextObject textObject = new TextObject("{=oSghSUxp}You've learned about {?IS_RULER}{RULER_NAME_AND_TITLE}{?}{HERO.NAME}{\\?}.");
				textObject.SetTextVariable("IS_RULER", hero.IsKingdomLeader ? 1 : 0);
				if (hero.IsKingdomLeader)
				{
					TextObject textObject2 = GameTexts.FindText("str_faction_ruler_name_with_title", hero.MapFaction.Culture.StringId);
					textObject2.SetCharacterProperties("RULER", hero.CharacterObject);
					textObject.SetTextVariable("RULER_NAME_AND_TITLE", textObject2);
				}
				else
				{
					textObject.SetCharacterProperties("HERO", hero.CharacterObject);
				}
				InformationManager.DisplayMessage(new InformationMessage(textObject.ToString()));
			}
		}

		private void OnAfterMissionStarted(IMission mission)
		{
			if (CampaignMission.Current.Location != null)
			{
				LearnAboutLocationCharacters(CampaignMission.Current.Location);
			}
		}

		private void OnGameMenuChanged(MenuCallbackArgs args)
		{
			foreach (Location menuLocation in Campaign.Current.GameMenuManager.MenuLocations)
			{
				LearnAboutLocationCharacters(menuLocation);
			}
		}

		private void LearnAboutLocationCharacters(Location location)
		{
			foreach (LocationCharacter character in location.GetCharacterList())
			{
				if (character.Character.IsHero && character.Character.HeroObject.CurrentSettlement == Settlement.CurrentSettlement)
				{
					character.Character.HeroObject.IsKnownToPlayer = true;
				}
			}
		}

		private void OnPlayerMetHero(Hero hero)
		{
			hero.IsKnownToPlayer = true;
		}

		private void OnDailyTickHero(Hero hero)
		{
			UpdateHeroLocation(hero);
		}

		private void OnAgentJoinedConversation(IAgent agent)
		{
			CharacterObject characterObject = (CharacterObject)agent.Character;
			if (characterObject.IsHero)
			{
				UpdateHeroLocation(characterObject.HeroObject);
				characterObject.HeroObject.IsKnownToPlayer = true;
			}
			Hero hero = MobileParty.ConversationParty?.CaravanPartyComponent?.Owner;
			if (hero != null)
			{
				hero.IsKnownToPlayer = true;
			}
		}

		private void UpdateHeroLocation(Hero hero)
		{
			if (hero.IsKnownToPlayer)
			{
				if (hero.IsActive || hero.IsPrisoner)
				{
					Settlement closestSettlement = HeroHelper.GetClosestSettlement(hero);
					if (closestSettlement != null)
					{
						hero.UpdateLastKnownClosestSettlement(closestSettlement);
					}
				}
			}
			else
			{
				hero.UpdateLastKnownClosestSettlement(null);
			}
		}

		private void OnCharacterCreationIsOver()
		{
			foreach (Hero allAliveHero in Hero.AllAliveHeroes)
			{
				UpdateHeroLocation(allAliveHero);
			}
		}

		private void OnGameLoadFinishedEvent()
		{
			if (!MBSaveLoad.IsUpdatingGameVersion || !(MBSaveLoad.LastLoadedGameVersion < ApplicationVersion.FromString("e1.8.1.0")))
			{
				return;
			}
			foreach (Hero hero in Clan.PlayerClan.Heroes)
			{
				hero.SetHasMet();
			}
			foreach (Hero allAliveHero in Hero.AllAliveHeroes)
			{
				if (allAliveHero.LastKnownClosestSettlement == null)
				{
					UpdateHeroLocation(allAliveHero);
				}
				if (allAliveHero.HasMet)
				{
					allAliveHero.IsKnownToPlayer = true;
				}
			}
		}

		private void OnHeroesMarried(Hero hero1, Hero hero2, bool showNotification)
		{
			if (hero1 == Hero.MainHero)
			{
				hero2.SetHasMet();
			}
			if (hero2 == Hero.MainHero)
			{
				hero1.SetHasMet();
			}
		}

		private void OnHeroCreated(Hero hero, bool isBornNaturally)
		{
			if (hero.Clan == Clan.PlayerClan)
			{
				hero.SetHasMet();
			}
		}

		private void ConversationEnded(IEnumerable<CharacterObject> conversationCharacters)
		{
			foreach (CharacterObject conversationCharacter in conversationCharacters)
			{
				if (conversationCharacter.IsHero)
				{
					bool result = true;
					CampaignEventDispatcher.Instance.CanPlayerMeetWithHeroAfterConversation(conversationCharacter.HeroObject, ref result);
					if (result)
					{
						conversationCharacter.HeroObject.SetHasMet();
					}
				}
			}
		}

		public override void SyncData(IDataStore dataStore)
		{
		}
	}
	public class HeroSpawnCampaignBehavior : CampaignBehaviorBase
	{
		private const float MinimumScoreForSafeSettlement = 10f;

		public override void RegisterEvents()
		{
			CampaignEvents.OnNewGameCreatedEvent.AddNonSerializedListener(this, OnNewGameCreated);
			CampaignEvents.OnNewGameCreatedPartialFollowUpEvent.AddNonSerializedListener(this, OnNewGameCreatedPartialFollowUp);
			CampaignEvents.OnNewGameCreatedPartialFollowUpEndEvent.AddNonSerializedListener(this, OnNewGameCreatedPartialFollowUpEnd);
			CampaignEvents.OnGovernorChangedEvent.AddNonSerializedListener(this, OnGovernorChanged);
			CampaignEvents.DailyTickClanEvent.AddNonSerializedListener(this, OnNonBanditClanDailyTick);
			CampaignEvents.HeroComesOfAgeEvent.AddNonSerializedListener(this, OnHeroComesOfAge);
			CampaignEvents.DailyTickHeroEvent.AddNonSerializedListener(this, OnHeroDailyTick);
			CampaignEvents.CompanionRemoved.AddNonSerializedListener(this, OnCompanionRemoved);
		}

		public override void SyncData(IDataStore dataStore)
		{
		}

		private void OnNewGameCreatedPartialFollowUp(CampaignGameStarter starter, int i)
		{
			if (i == 0)
			{
				int heroComesOfAge = Campaign.Current.Models.AgeModel.HeroComesOfAge;
				foreach (Clan item in Clan.All)
				{
					foreach (Hero hero in item.Heroes)
					{
						if (hero.Age >= (float)heroComesOfAge && hero.IsAlive && !hero.IsDisabled)
						{
							hero.ChangeState(Hero.CharacterStates.Active);
						}
					}
				}
			}
			int num = Clan.NonBanditFactions.Count();
			int num2 = num / 100 + ((num % 100 > i) ? 1 : 0);
			int num3 = num / 100;
			for (int j = 0; j < i; j++)
			{
				num3 += ((num % 100 > j) ? 1 : 0);
			}
			for (int k = 0; k < num2; k++)
			{
				TrySpawnHeroesAndParties(Clan.NonBanditFactions.ElementAt(num3 + k), isNewGame: true);
			}
		}

		private void OnNewGameCreated(CampaignGameStarter starter)
		{
			foreach (Clan nonBanditFaction in Clan.NonBanditFactions)
			{
				if (!nonBanditFaction.IsEliminated && nonBanditFaction.IsMinorFaction && nonBanditFaction != Clan.PlayerClan)
				{
					SpawnMinorFactionHeroes(nonBanditFaction, firstTime: true);
					CheckAndAssignClanLeader(nonBanditFaction);
					nonBanditFaction.ConsiderAndUpdateHomeSettlement();
				}
			}
		}

		private void OnNewGameCreatedPartialFollowUpEnd(CampaignGameStarter starter)
		{
			foreach (Hero allAliveHero in Hero.AllAliveHeroes)
			{
				if (allAliveHero.IsActive)
				{
					AssignSettlementToHeroOnGameStart(allAliveHero);
				}
			}
		}

		private void OnHeroComesOfAge(Hero hero)
		{
			if (!hero.IsDisabled && hero.HeroState != Hero.CharacterStates.Active && !hero.IsTraveling)
			{
				hero.ChangeState(Hero.CharacterStates.Active);
				TeleportHeroAction.ApplyImmediateTeleportToSettlement(hero, hero.HomeSettlement);
			}
		}

		private void OnCompanionRemoved(Hero companion, RemoveCompanionAction.RemoveCompanionDetail detail)
		{
			if (!companion.IsFugitive && !companion.IsDead && detail != RemoveCompanionAction.RemoveCompanionDetail.ByTurningToLord && detail != RemoveCompanionAction.RemoveCompanionDetail.Death && companion.DeathMark == KillCharacterAction.KillCharacterActionDetail.None)
			{
				Settlement targetSettlement = FindASuitableSettlementToTeleportForHero(companion);
				TeleportHeroAction.ApplyImmediateTeleportToSettlement(companion, targetSettlement);
			}
		}

		private void AssignSettlementToHeroOnGameStart(Hero hero)
		{
			if (hero.CurrentSettlement == null && hero.PartyBelongedTo == null && !hero.IsSpecial && hero.GovernorOf == null)
			{
				if (MobileParty.MainParty.MemberRoster.Contains(hero.CharacterObject))
				{
					MobileParty.MainParty.MemberRoster.RemoveTroop(hero.CharacterObject);
					MobileParty.MainParty.MemberRoster.AddToCounts(hero.CharacterObject, 1);
				}
				else
				{
					Settlement targetSettlement = FindASuitableSettlementToTeleportForHero(hero);
					TeleportHeroAction.ApplyImmediateTeleportToSettlement(hero, targetSettlement);
				}
			}
		}

		private void OnHeroDailyTick(Hero hero)
		{
			Settlement settlement = null;
			if (hero.IsFugitive || hero.IsReleased)
			{
				if (!hero.IsSpecial && (hero.IsPlayerCompanion || MBRandom.RandomFloat < 0.3f || (hero.CurrentSettlement != null && hero.CurrentSettlement.MapFaction.IsAtWarWith(hero.MapFaction))))
				{
					settlement = FindASuitableSettlementToTeleportForHero(hero);
				}
			}
			else if (hero.IsActive && CanHeroMoveToAnotherSettlement(hero))
			{
				settlement = FindASuitableSettlementToTeleportForHero(hero, 10f);
			}
			if (settlement != null)
			{
				TeleportHeroAction.ApplyImmediateTeleportToSettlement(hero, settlement);
				if (!hero.IsActive)
				{
					hero.ChangeState(Hero.CharacterStates.Active);
				}
			}
		}

		private void OnNonBanditClanDailyTick(Clan clan)
		{
			TrySpawnHeroesAndParties(clan, isNewGame: false);
		}

		private void TrySpawnHeroesAndParties(Clan clan, bool isNewGame)
		{
			if (!clan.IsEliminated && clan != Clan.PlayerClan)
			{
				if (clan.IsMinorFaction)
				{
					SpawnMinorFactionHeroes(clan, firstTime: false);
				}
				ConsiderSpawningLordParties(clan, isNewGame);
			}
		}

		private bool CanHeroMoveToAnotherSettlement(Hero hero)
		{
			if (hero.Clan != Clan.PlayerClan && !hero.IsTemplate && hero.IsAlive && !hero.IsNotable && !hero.IsHumanPlayerCharacter && !hero.IsPartyLeader && !hero.IsPrisoner && hero.HeroState != Hero.CharacterStates.Disabled && hero.GovernorOf == null && hero.PartyBelongedTo == null && !hero.IsWanderer && hero.PartyBelongedToAsPrisoner == null && hero.CharacterObject.Occupation != Occupation.Special && hero.Age >= (float)Campaign.Current.Models.AgeModel.HeroComesOfAge && (hero.CurrentSettlement?.Town == null || (!hero.CurrentSettlement.Town.HasTournament && !hero.CurrentSettlement.IsUnderSiege)))
			{
				return hero.CanMoveToSettlement();
			}
			return false;
		}

		private float GetHeroPartyCommandScore(Hero hero)
		{
			return 3f * (float)hero.GetSkillValue(DefaultSkills.Tactics) + 2f * (float)hero.GetSkillValue(DefaultSkills.Leadership) + (float)hero.GetSkillValue(DefaultSkills.Scouting) + (float)hero.GetSkillValue(DefaultSkills.Steward) + (float)hero.GetSkillValue(DefaultSkills.OneHanded) + (float)hero.GetSkillValue(DefaultSkills.TwoHanded) + (float)hero.GetSkillValue(DefaultSkills.Polearm) + (float)hero.GetSkillValue(DefaultSkills.Riding) + ((hero.Clan.Leader == hero) ? 1000f : 0f) + ((hero.GovernorOf == null) ? 500f : 0f) + (float)(hero.IsNoncombatant ? (-5000) : 0);
		}

		private void ConsiderSpawningLordParties(Clan clan, bool isNewGame)
		{
			int partyLimitForTier = Campaign.Current.Models.ClanTierModel.GetPartyLimitForTier(clan, clan.Tier);
			int count = clan.WarPartyComponents.Count;
			if (count >= partyLimitForTier)
			{
				return;
			}
			int num = partyLimitForTier - count;
			for (int i = 0; i < num; i++)
			{
				Hero bestAvailableCommander = GetBestAvailableCommander(clan);
				if (bestAvailableCommander == null)
				{
					break;
				}
				float num2 = CalculateScoreToCreateParty(clan);
				if (GetHeroPartyCommandScore(bestAvailableCommander) + num2 > 100f)
				{
					MobileParty mobileParty = SpawnLordParty(bestAvailableCommander, isNewGame);
					if (mobileParty != null)
					{
						GiveInitialItemsToParty(mobileParty);
					}
				}
			}
		}

		private float CalculateScoreToCreateParty(Clan clan)
		{
			return (float)(clan.Fiefs.Count * 100 - clan.WarPartyComponents.Count * 100) + (float)clan.Gold * 0.01f + (clan.IsMinorFaction ? 200f : 0f) + ((clan.WarPartyComponents.Count > 0) ? 0f : 200f);
		}

		private Hero GetBestAvailableCommander(Clan clan)
		{
			Hero hero = null;
			float num = 0f;
			foreach (Hero hero2 in clan.Heroes)
			{
				if (hero2.IsActive && hero2.IsAlive && hero2.PartyBelongedTo == null && hero2.PartyBelongedToAsPrisoner == null && hero2.CanLeadParty() && hero2.Age > (float)Campaign.Current.Models.AgeModel.HeroComesOfAge && hero2.CharacterObject.Occupation == Occupation.Lord)
				{
					float heroPartyCommandScore = GetHeroPartyCommandScore(hero2);
					if (heroPartyCommandScore > num)
					{
						num = heroPartyCommandScore;
						hero = hero2;
					}
				}
			}
			if (hero != null)
			{
				return hero;
			}
			if (clan != Clan.PlayerClan)
			{
				foreach (Hero hero3 in clan.Heroes)
				{
					if (hero3.IsActive && hero3.IsAlive && hero3.PartyBelongedTo == null && hero3.PartyBelongedToAsPrisoner == null && hero3.Age > (float)Campaign.Current.Models.AgeModel.HeroComesOfAge && hero3.CharacterObject.Occupation == Occupation.Lord)
					{
						float heroPartyCommandScore2 = GetHeroPartyCommandScore(hero3);
						if (heroPartyCommandScore2 > num)
						{
							num = heroPartyCommandScore2;
							hero = hero3;
						}
					}
				}
			}
			return hero;
		}

		private MobileParty SpawnLordParty(Hero hero, bool isNewGame)
		{
			if (hero.GovernorOf != null)
			{
				ChangeGovernorAction.RemoveGovernorOf(hero);
			}
			Settlement settlement = SettlementHelper.GetBestSettlementToSpawnAround(hero);
			if (settlement == null || settlement.MapFaction != hero.MapFaction)
			{
				settlement = hero.MapFaction.InitialHomeSettlement;
			}
			if (settlement == null)
			{
				settlement = Settlement.All.First((Settlement x) => x.Culture == hero.Culture);
			}
			MobileParty mobileParty = MobilePartyHelper.SpawnLordParty(hero, settlement.GatePosition, Campaign.Current.GetAverageDistanceBetweenClosestTwoTownsWithNavigationType(MobileParty.NavigationType.Default) / 2f);
			if (isNewGame)
			{
				int num = (int)((float)(mobileParty.Party.PartySizeLimit - mobileParty.MemberRoster.TotalManCount) * MBRandom.RandomFloatRanged(0.75f, 0.9f));
				PartyTemplateObject defaultPartyTemplate = mobileParty.LordPartyComponent.Owner.Clan.DefaultPartyTemplate;
				List<(CharacterObject, float)> list = new List<(CharacterObject, float)>();
				foreach (PartyTemplateStack stack in defaultPartyTemplate.Stacks)
				{
					list.Add((stack.Character, (float)(stack.MinValue + stack.MaxValue) / 2f));
				}
				for (int i = 0; i < num; i++)
				{
					CharacterObject element = MBRandom.ChooseWeighted(list);
					mobileParty.AddElementToMemberRoster(element, 1);
				}
			}
			return mobileParty;
		}

		private void GiveInitialItemsToParty(MobileParty heroParty)
		{
			float num = 2f * Campaign.Current.EstimatedAverageLordPartySpeed * (float)CampaignTime.HoursInDay;
			foreach (Settlement settlement in Campaign.Current.Settlements)
			{
				if (!settlement.IsVillage)
				{
					continue;
				}
				float estimatedLandRatio;
				float distance = Campaign.Current.Models.MapDistanceModel.GetDistance(heroParty, settlement, isTargetingPort: false, heroParty.NavigationCapability, out estimatedLandRatio);
				if (!(distance < num))
				{
					continue;
				}
				foreach (var production in settlement.Village.VillageType.Productions)
				{
					ItemObject item = production.Item1;
					float item2 = production.Item2;
					float num2 = ((item.ItemType == ItemObject.ItemTypeEnum.Horse && item.HorseComponent.IsRideable && !item.HorseComponent.IsPackAnimal) ? 7f : (item.IsFood ? 0.1f : 0f));
					float num3 = ((float)heroParty.MemberRoster.TotalManCount + 2f) / 200f;
					float num4 = 1f - distance / num;
					int num5 = MBRandom.RoundRandomized(num2 * item2 * num4 * num3);
					if (num5 > 0)
					{
						heroParty.ItemRoster.AddToCounts(item, num5);
					}
				}
			}
		}

		private void CheckAndAssignClanLeader(Clan clan)
		{
			if (clan.Leader == null || clan.Leader.IsDead)
			{
				Hero hero = clan.AliveLords.FirstOrDefault();
				if (hero != null)
				{
					clan.SetLeader(hero);
				}
				else
				{
					TaleWorlds.Library.Debug.FailedAssert("Cant find a lord to assign as leader to minor faction.", "C:\\BuildAgent\\work\\mb3\\Source\\Bannerlord\\TaleWorlds.CampaignSystem\\CampaignBehaviors\\HeroSpawnCampaignBehavior.cs", "CheckAndAssignClanLeader", 438);
				}
			}
		}

		private void CreateMinorFactionHeroFromTemplate(CharacterObject template, Clan faction)
		{
			Hero hero = HeroCreator.CreateSpecialHero(template, null, faction, null, Campaign.Current.GameStarted ? 19 : (-1));
			hero.ChangeState(Campaign.Current.GameStarted ? Hero.CharacterStates.Active : Hero.CharacterStates.NotSpawned);
			hero.IsMinorFactionHero = true;
		}

		private void SpawnMinorFactionHeroes(Clan clan, bool firstTime)
		{
			int num = Campaign.Current.Models.MinorFactionsModel.MinorFactionHeroLimit - clan.AliveLords.Count;
			if (num <= 0)
			{
				return;
			}
			if (firstTime)
			{
				for (int i = 0; i < clan.MinorFactionCharacterTemplates.Count; i++)
				{
					if (num <= 0)
					{
						break;
					}
					CharacterObject template = clan.MinorFactionCharacterTemplates[i];
					CreateMinorFactionHeroFromTemplate(template, clan);
					num--;
				}
			}
			if (num <= 0)
			{
				return;
			}
			if (clan.MinorFactionCharacterTemplates == null || clan.MinorFactionCharacterTemplates.IsEmpty())
			{
				TaleWorlds.Library.Debug.FailedAssert($"{clan.Name} templates are empty!", "C:\\BuildAgent\\work\\mb3\\Source\\Bannerlord\\TaleWorlds.CampaignSystem\\CampaignBehaviors\\HeroSpawnCampaignBehavior.cs", "SpawnMinorFactionHeroes", 475);
				return;
			}
			for (int j = 0; j < num; j++)
			{
				if (MBRandom.RandomFloat < Campaign.Current.Models.MinorFactionsModel.DailyMinorFactionHeroSpawnChance)
				{
					CharacterObject randomElementInefficiently = clan.MinorFactionCharacterTemplates.GetRandomElementInefficiently();
					CreateMinorFactionHeroFromTemplate(randomElementInefficiently, clan);
				}
			}
		}

		private void OnGovernorChanged(Town fortification, Hero oldGovernor, Hero newGovernor)
		{
			if (oldGovernor != null && oldGovernor.Clan != null)
			{
				foreach (Hero hero in oldGovernor.Clan.Heroes)
				{
					hero.UpdateHomeSettlement();
				}
			}
			if (newGovernor == null || newGovernor.Clan == null || (oldGovernor != null && newGovernor.Clan == oldGovernor.Clan))
			{
				return;
			}
			foreach (Hero hero2 in newGovernor.Clan.Heroes)
			{
				hero2.UpdateHomeSettlement();
			}
		}

		private Settlement FindASuitableSettlementToTeleportForHero(Hero hero, float minimumScore = 0f)
		{
			Settlement settlement = null;
			if (hero.IsNotable)
			{
				TaleWorlds.Library.Debug.FailedAssert("Notables should not use here anymore, make sure this case is intended", "C:\\BuildAgent\\work\\mb3\\Source\\Bannerlord\\TaleWorlds.CampaignSystem\\CampaignBehaviors\\HeroSpawnCampaignBehavior.cs", "FindASuitableSettlementToTeleportForHero", 519);
				settlement = hero.BornSettlement;
			}
			else
			{
				List<(Settlement, float)> list = new List<(Settlement, float)>(hero.MapFaction.Fiefs.Count);
				foreach (Town fief in hero.MapFaction.Fiefs)
				{
					float moveScoreForHero = GetMoveScoreForHero(hero, fief);
					list.Add((fief.Settlement, (moveScoreForHero >= minimumScore) ? moveScoreForHero : 0f));
				}
				settlement = MBRandom.ChooseWeighted(list);
				if (settlement == null)
				{
					List<Settlement> list2 = new List<Settlement>();
					List<Settlement> list3 = new List<Settlement>();
					foreach (Town allFief in Town.AllFiefs)
					{
						if (allFief.MapFaction.IsAtWarWith(hero.MapFaction))
						{
							if (allFief.IsTown)
							{
								list3.Add(allFief.Settlement);
							}
						}
						else
						{
							list2.Add(allFief.Settlement);
						}
					}
					foreach (Settlement item in list2)
					{
						float moveScoreForHero2 = GetMoveScoreForHero(hero, item.Town);
						list.Add((item, (moveScoreForHero2 >= minimumScore) ? moveScoreForHero2 : 0f));
					}
					settlement = MBRandom.ChooseWeighted(list);
					if (settlement == null)
					{
						list.Clear();
						foreach (Settlement item2 in list3)
						{
							float moveScoreForHero3 = GetMoveScoreForHero(hero, item2.Town);
							list.Add((item2, (moveScoreForHero3 >= minimumScore) ? moveScoreForHero3 : 0f));
						}
						settlement = MBRandom.ChooseWeighted(list);
					}
				}
			}
			return settlement;
		}

		private float GetMoveScoreForHero(Hero hero, Town fief)
		{
			Clan clan = hero.Clan;
			float num = 1E-06f;
			if (!fief.IsUnderSiege && !fief.MapFaction.IsAtWarWith(hero.MapFaction) && (!fief.IsCastle || hero.Occupation != Occupation.Wanderer || hero.IsPlayerCompanion))
			{
				num = (DiplomacyHelper.IsSameFactionAndNotEliminated(fief.MapFaction, hero.MapFaction) ? 0.01f : 1E-05f);
				if (fief.MapFaction == hero.MapFaction)
				{
					num += 10f;
					if (fief.IsTown)
					{
						num += 100f;
					}
					if (fief.OwnerClan == clan)
					{
						num += (fief.IsTown ? 500f : 100f);
					}
					if (fief.HasTournament)
					{
						num += 400f;
					}
				}
				foreach (Hero item in fief.Settlement.HeroesWithoutParty)
				{
					if (clan != null && item.Clan == clan)
					{
						num += (fief.IsTown ? 100f : 10f);
					}
				}
				if (hero.IsFugitive && hero.HomeSettlement?.Town == fief)
				{
					num += 100f;
				}
				if (fief.Settlement.IsStarving)
				{
					num *= 0.1f;
				}
				if (hero.CurrentSettlement == fief.Settlement)
				{
					num *= 3f;
				}
			}
			return num;
		}
	}
	public class HideoutCampaignBehavior : CampaignBehaviorBase, IHideoutCampaignBehavior
	{
		private const int HideoutClearRelationEffect = 2;

		private const int HideoutLootTargetValueMultiplier = 135;

		private int _minimumHideoutLootTargetValue = 350;

		private const int MaximumHideoutLootTargetValue = 4750;

		private const int MaximumHideoutExtraLootTypeCount = 5;

		private const float HideoutSendTroopsWaitTargetHour = 6f;

		private float _hideoutWaitProgressHours;

		private float _hideoutWaitTargetHours;

		private float _hideoutSendTroopsWaitProgressHour;

		private int _initialHideoutPopulation;

		private List<ItemObject> _potentialLootItems = new List<ItemObject>();

		private static float IncreaseRelationWithVillageNotableMaximumDistanceAsDays => 0.5f;

		private int CanAttackHideoutStart => Campaign.Current.Models.HideoutModel.CanAttackHideoutStartTime;

		private int CanAttackHideoutEnd => Campaign.Current.Models.HideoutModel.CanAttackHideoutEndTime;

		public override void RegisterEvents()
		{
			CampaignEvents.HourlyTickSettlementEvent.AddNonSerializedListener(this, HourlyTickSettlement);
			CampaignEvents.OnNewGameCreatedEvent.AddNonSerializedListener(this, OnNewGameCreated);
			CampaignEvents.OnGameLoadedEvent.AddNonSerializedListener(this, OnGameLoaded);
			CampaignEvents.OnSessionLaunchedEvent.AddNonSerializedListener(this, OnSessionLaunched);
			CampaignEvents.OnHideoutSpottedEvent.AddNonSerializedListener(this, OnHideoutSpotted);
			CampaignEvents.OnHideoutBattleCompletedEvent.AddNonSerializedListener(this, OnHideoutBattleCompleted);
			CampaignEvents.OnCollectLootsItemsEvent.AddNonSerializedListener(this, OnCollectLootItems);
		}

		public void OnNewGameCreated(CampaignGameStarter campaignGameStarter)
		{
			AddGameMenus(campaignGameStarter);
		}

		public void OnGameLoaded(CampaignGameStarter campaignGameStarter)
		{
			AddGameMenus(campaignGameStarter);
		}

		public void HourlyTickSettlement(Settlement settlement)
		{
			if (settlement.IsHideout && settlement.Hideout.IsInfested && !settlement.Hideout.IsSpotted)
			{
				float hideoutSpottingDistance = Campaign.Current.Models.MapVisibilityModel.GetHideoutSpottingDistance();
				float num = MobileParty.MainParty.Position.DistanceSquared(settlement.Position);
				float num2 = 1f - num / (hideoutSpottingDistance * hideoutSpottingDistance);
				if (num2 > 0f && settlement.Parties.Count > 0 && MBRandom.RandomFloat < num2 && !settlement.Hideout.IsSpotted)
				{
					settlement.Hideout.IsSpotted = true;
					settlement.IsVisible = true;
					CampaignEventDispatcher.Instance.OnHideoutSpotted(MobileParty.MainParty.Party, settlement.Party);
				}
			}
		}

		private void OnHideoutSpotted(PartyBase party, PartyBase hideout)
		{
			SkillLevelingManager.OnHideoutSpotted(party.MobileParty, hideout);
		}

		private int GetItemValueForHideoutLoot(ItemObject itemToLoot)
		{
			return Campaign.Current.Models.TradeItemPriceFactorModel.GetTheoreticalMaxItemMarketValue(itemToLoot) + 1;
		}

		private void OnHideoutBattleCompleted(BattleSideEnum winnerSide, HideoutEventComponent hideoutEventComponent, HideoutEventComponent.HideoutBattleEndState battleEndState)
		{
			if (battleEndState != HideoutEventComponent.HideoutBattleEndState.Victory && battleEndState != HideoutEventComponent.HideoutBattleEndState.SendTroops)
			{
				_initialHideoutPopulation = 0;
			}
		}

		private void OnCollectLootItems(PartyBase winnerParty, ItemRoster gainedLoots)
		{
			if (winnerParty == PartyBase.MainParty && !PlayerEncounter.Current.ForceHideoutSendTroops)
			{
				MapEvent mapEvent = MobileParty.MainParty.MapEvent;
				if (mapEvent.IsHideoutBattle && mapEvent.MapEventSettlement == Settlement.CurrentSettlement && IsItNighttimeNow())
				{
					int num = 0;
					foreach (MapEventParty party in mapEvent.GetMapEventSide(mapEvent.PlayerSide).Parties)
					{
						if (party.Party == PartyBase.MainParty)
						{
							num = party.PlunderedGold;
							break;
						}
					}
					int totalLootedValue = 0;
					float targetValue = num * (_initialHideoutPopulation * 135);
					targetValue = TaleWorlds.Library.MathF.Clamp(targetValue, _minimumHideoutLootTargetValue, 4750f);
					if ((float)totalLootedValue < targetValue)
					{
						ItemObject itemObject = null;
						for (int i = 0; i < _potentialLootItems.Count; i++)
						{
							if (gainedLoots.Count >= 5)
							{
								break;
							}
							if (!((float)totalLootedValue < targetValue))
							{
								break;
							}
							itemObject = _potentialLootItems[i];
							int itemValueForHideoutLoot = GetItemValueForHideoutLoot(itemObject);
							if ((float)itemValueForHideoutLoot <= targetValue - (float)totalLootedValue)
							{
								gainedLoots.AddToCounts(itemObject, 1);
								totalLootedValue += itemValueForHideoutLoot;
							}
						}
						do
						{
							itemObject = gainedLoots.GetRandomElementWithPredicate((ItemRosterElement x) => !x.EquipmentElement.Item.NotMerchandise && !x.EquipmentElement.IsQuestItem && !x.EquipmentElement.Item.IsBannerItem && (float)GetItemValueForHideoutLoot(x.EquipmentElement.Item) <= targetValue - (float)totalLootedValue).EquipmentElement.Item;
							if (itemObject != null)
							{
								gainedLoots.AddToCounts(itemObject, 1);
								totalLootedValue += GetItemValueForHideoutLoot(itemObject);
							}
						}
						while (itemObject != null);
					}
				}
			}
			_initialHideoutPopulation = 0;
		}

		public override void SyncData(IDataStore dataStore)
		{
			dataStore.SyncData("_hideoutWaitProgressHours", ref _hideoutWaitProgressHours);
			dataStore.SyncData("_hideoutWaitTargetHours", ref _hideoutWaitTargetHours);
			dataStore.SyncData("_hideoutSendTroopsWaitProgressHour", ref _hideoutSendTroopsWaitProgressHour);
		}

		private void OnSessionLaunched(CampaignGameStarter campaignGameStarter)
		{
			foreach (ItemObject objectType in Campaign.Current.ObjectManager.GetObjectTypeList<ItemObject>())
			{
				if (objectType.IsTradeGood)
				{
					int itemValueForHideoutLoot = GetItemValueForHideoutLoot(objectType);
					if (itemValueForHideoutLoot >= _minimumHideoutLootTargetValue && itemValueForHideoutLoot <= 4750)
					{
						_potentialLootItems.Add(objectType);
					}
				}
			}
			_potentialLootItems = _potentialLootItems.OrderByDescending((ItemObject x) => x.Value).ToList();
			if (_potentialLootItems.Count > 0)
			{
				_minimumHideoutLootTargetValue = GetItemValueForHideoutLoot(_potentialLootItems[_potentialLootItems.Count - 1]);
			}
		}

