				Building preemptiveWorkBuilding = GetPreemptiveWorkBuilding();
				return preemptiveWorkBuilding != null && preemptiveWorkBuilding.CurrentLevel == preemptiveWorkBuilding.BuildingType.StartLevel;
			});
			incident75.AddOption("{=9e8I99t3}Transfer ownership to the farmers to encourage such enterprise, even if others may take advantage of you in the future.", new List<IncidentEffect>
