						MobileParty mobileParty = BanditPartyComponent.CreateBanditParty("incident_tiller_and_wanderer_bandit_revenge_" + i, tillerAndWandererBanditPartyClan, hideout, isBossParty: false, null, initialPosition);
						mobileParty.MemberRoster.AddToCounts(tillerAndWandererBanditPartyClan.Culture.BanditBandit, MobileParty.MainParty.RandomIntWithSeed((uint)_activeIncidentSeed, 5, 17));
