				Town seededRandomElement = IncidentHelper.GetSeededRandomElement(Town.AllTowns.Where((Town x) => x.Workshops.Any((Workshop y) => y.Owner == Hero.MainHero)).ToList(), _activeIncidentSeed);
				if (seededRandomElement == null)
