		public class Number
		{
			public int Value;

			public Number(int value)
			{
				Value = value;
			}

			public IEnumerable<Number> GetBetween(int start, int end)
			{
				int i = start;
				while (i < end + 1)
				{
					yield return new Number(i);
					int num = i + 1;
					i = num;
				}
			}
		}

