		{
			ChangeClanInfluenceAction.Apply(Clan.PlayerClan, -Campaign.Current.Models.ArmyManagementCalculationModel.CalculatePartyInfluenceCost(MobileParty.MainParty, Hero.OneToOneConversationHero.PartyBelongedTo));
