		private bool conversation_lord_can_recruit_on_condition()
		{
			if (Hero.MainHero.MapFaction.Leader == Hero.MainHero)
			{
				MBTextManager.SetTextVariable("RECRUIT_START", new TextObject("{=Fr7wzk97}I am the rightful ruler of this land. I would like your support."));
			}
			else if (Hero.MainHero.MapFaction == Hero.OneToOneConversationHero.MapFaction)
			{
				StringHelpers.SetCharacterProperties("CURRENT_LIEGE", Hero.OneToOneConversationHero.MapFaction.Leader.CharacterObject);
				MBTextManager.SetTextVariable("RECRUIT_START", "{=V7qF7uas}I should lead our people, not {CURRENT_LIEGE.NAME}.");
			}
			else
			{
				StringHelpers.SetCharacterProperties("NEW_LIEGE", Hero.MainHero.MapFaction.Leader.CharacterObject);
				MBTextManager.SetTextVariable("RECRUIT_START", new TextObject("{=UwPs3wmj}My liege {NEW_LIEGE.NAME} would welcome your support. Join us!"));
			}
			return true;
		}

		private void start_lord_defection_persuasion_on_consequence()
		{
			Hero newLiege = Hero.MainHero.MapFaction.Leader;
			if (Hero.MainHero.MapFaction == Hero.OneToOneConversationHero.MapFaction)
			{
				newLiege = Hero.MainHero;
			}
			_allReservations = GetPersuasionTasksForDefection(Hero.OneToOneConversationHero, newLiege);
			_maximumScoreCap = (float)_allReservations.Count * 1f;
			float num = 0f;
			foreach (PersuasionTask allReservation in _allReservations)
			{
				foreach (PersuasionAttempt previousDefectionPersuasionAttempt in _previousDefectionPersuasionAttempts)
				{
					if (previousDefectionPersuasionAttempt.Matches(Hero.OneToOneConversationHero, allReservation.ReservationType))
					{
						switch (previousDefectionPersuasionAttempt.Result)
						{
						case PersuasionOptionResult.Success:
							num += _successValue;
							break;
						case PersuasionOptionResult.CriticalSuccess:
							num += _criticalSuccessValue;
							break;
						case PersuasionOptionResult.CriticalFailure:
							num -= _criticalFailValue;
							break;
						case PersuasionOptionResult.Failure:
							num -= 0f;
							break;
						}
					}
				}
			}
			ConversationManager.StartPersuasion(_maximumScoreCap, _successValue, _failValue, _criticalSuccessValue, _criticalFailValue, num);
		}

		private void OnDailyTick()
		{
			RemoveOldAttempts();
		}

		private void conversation_clear_persuasion_on_consequence()
		{
			ClearPersuasion();
		}

		private void conversation_leave_faction_barter_consequence()
		{
			BarterManager.Instance.StartBarterOffer(Hero.MainHero, Hero.OneToOneConversationHero, PartyBase.MainParty, Hero.OneToOneConversationHero.PartyBelongedTo?.Party, null, BarterManager.Instance.InitializeJoinFactionBarterContext, 0, isAIBarter: false, new Barterable[1]
			{
				new JoinKingdomAsClanBarterable(Hero.OneToOneConversationHero, Clan.PlayerClan.Kingdom, isDefecting: true)
			});
			_allReservations = null;
			ConversationManager.EndPersuasion();
			if (Hero.OneToOneConversationHero.PartyBelongedTo != null && !Hero.OneToOneConversationHero.PartyBelongedTo.MapFaction.IsAtWarWith(MobileParty.MainParty.MapFaction))
			{
				PlayerEncounter.LeaveEncounter = true;
			}
		}

		private bool CanAttemptToPersuade(Hero targetHero, int reservationType)
		{
			foreach (PersuasionAttempt previousDefectionPersuasionAttempt in _previousDefectionPersuasionAttempts)
			{
				if (previousDefectionPersuasionAttempt.Matches(targetHero, reservationType) && !previousDefectionPersuasionAttempt.IsSuccesful() && previousDefectionPersuasionAttempt.GameTime.ElapsedWeeksUntilNow < 1f)
				{
					return false;
				}
			}
			return true;
		}

		private void RemoveOldAttempts()
		{
			for (int num = _previousDefectionPersuasionAttempts.Count - 1; num >= 0; num--)
			{
				if (_previousDefectionPersuasionAttempts[num].GameTime.ElapsedYearsUntilNow > 1f)
				{
					_previousDefectionPersuasionAttempts.RemoveAt(num);
				}
			}
		}
	}
	public class MapTracksCampaignBehavior : CampaignBehaviorBase, IMapTracksCampaignBehavior, ICampaignBehavior
	{
		private class TrackPool
		{
			private Stack<Track> _stack;

			private int MaxSize { get; }

			public int Size => _stack?.Count ?? 0;

			public TrackPool(int size)
			{
				MaxSize = size;
				_stack = new Stack<Track>();
				for (int i = 0; i < size; i++)
				{
					_stack.Push(new Track());
				}
			}

			public Track RequestTrack(MobileParty party, CampaignVec2 trackPosition, Vec2 trackDirection)
			{
				Track track = ((_stack.Count > 0) ? _stack.Pop() : new Track());
				int num = party.Party.NumberOfAllMembers;
				int num2 = party.Party.NumberOfHealthyMembers;
				int num3 = party.Party.NumberOfMenWithHorse;
				int num4 = party.Party.NumberOfMenWithoutHorse;
				int num5 = party.Party.NumberOfPackAnimals;
				int num6 = party.Party.NumberOfPrisoners;
				TextObject partyName = party.Name;
				if (party.Army != null && party.Army.LeaderParty == party)
				{
					partyName = party.ArmyName;
					foreach (MobileParty attachedParty in party.Army.LeaderParty.AttachedParties)
					{
						num += attachedParty.Party.NumberOfAllMembers;
						num2 += attachedParty.Party.NumberOfHealthyMembers;
						num3 += attachedParty.Party.NumberOfMenWithHorse;
						num4 += attachedParty.Party.NumberOfMenWithoutHorse;
						num5 += attachedParty.Party.NumberOfPackAnimals;
						num6 += attachedParty.Party.NumberOfPrisoners;
					}
				}
				track.Position = trackPosition;
				track.Direction = trackDirection.RotationInRadians;
				track.PartyType = Track.GetPartyTypeEnum(party);
				track.PartyName = partyName;
				track.Culture = party.Party.Culture;
				if (track.Culture == null)
				{
					string message = $"Track culture is null for {party.StringId}: {party.Name}";
					TaleWorlds.Library.Debug.Print(message);
					TaleWorlds.Library.Debug.FailedAssert(message, "C:\\BuildAgent\\work\\mb3\\Source\\Bannerlord\\TaleWorlds.CampaignSystem\\CampaignBehaviors\\MapTracksCampaignBehavior.cs", "RequestTrack", 62);
				}
				track.Speed = party.Speed;
				track.Life = Campaign.Current.Models.MapTrackModel.GetTrackLife(party);
				track.IsEnemy = FactionManager.IsAtWarAgainstFaction(Hero.MainHero.MapFaction, party.MapFaction);
				track.NumberOfAllMembers = num;
				track.NumberOfHealthyMembers = num2;
				track.NumberOfMenWithHorse = num3;
				track.NumberOfMenWithoutHorse = num4;
				track.NumberOfPackAnimals = num5;
				track.NumberOfPrisoners = num6;
				track.IsPointer = false;
				track.IsDetected = false;
				track.CreationTime = CampaignTime.Now;
				return track;
			}

			public Track RequestMapArrow(TextObject pointerName, CampaignVec2 trackPosition, Vec2 trackDirection, float life)
			{
				Track obj = ((_stack.Count > 0) ? _stack.Pop() : new Track());
				obj.Position = trackPosition;
				obj.Direction = trackDirection.RotationInRadians;
				obj.PartyName = pointerName;
				obj.Life = life;
				obj.IsPointer = true;
				obj.IsDetected = true;
				obj.CreationTime = CampaignTime.Now;
				return obj;
			}

			public void ReleaseTrack(Track track)
			{
				track.Reset();
				if (_stack.Count < MaxSize)
				{
					_stack.Push(track);
				}
			}

			public override string ToString()
			{
				return $"TrackPool: {Size}";
			}
		}

		private const float PartyTrackPositionDelta = 5f;

		private List<Track> _allTracks = new List<Track>();

		private MBList<Track> _detectedTracksCache = new MBList<Track>();

		private Dictionary<MobileParty, CampaignVec2> _trackDataDictionary = new Dictionary<MobileParty, CampaignVec2>();

		private MBCampaignEvent _quarterHourlyTick;

		private LocatorGrid<Track> _trackLocator = new LocatorGrid<Track>();

		private TrackPool _trackPool;

		public MBReadOnlyList<Track> DetectedTracks => _detectedTracksCache;

		public MapTracksCampaignBehavior()
		{
			_trackPool = new TrackPool(2048);
		}

		public override void RegisterEvents()
		{
			CampaignEvents.HourlyTickEvent.AddNonSerializedListener(this, OnHourlyTick);
			CampaignEvents.OnGameLoadFinishedEvent.AddNonSerializedListener(this, GameLoadFinished);
			CampaignEvents.HourlyTickPartyEvent.AddNonSerializedListener(this, OnHourlyTickParty);
			CampaignEvents.MobilePartyDestroyed.AddNonSerializedListener(this, OnMobilePartyDestroyed);
			CampaignEvents.OnNewGameCreatedEvent.AddNonSerializedListener(this, OnNewGameCreated);
		}

		private void OnMobilePartyDestroyed(MobileParty mobileParty, PartyBase destroyerParty)
		{
			if (_trackDataDictionary.ContainsKey(mobileParty))
			{
				_trackDataDictionary.Remove(mobileParty);
			}
		}

		private void OnNewGameCreated(CampaignGameStarter gameStarted)
		{
			AddEventHandler();
		}

		public override void SyncData(IDataStore dataStore)
		{
			dataStore.SyncData("_allTracks", ref _allTracks);
			dataStore.SyncData("_trackDataDictionary2", ref _trackDataDictionary);
			if (!dataStore.IsLoading || !MBSaveLoad.IsUpdatingGameVersion || !MBSaveLoad.LastLoadedGameVersion.IsOlderThan(ApplicationVersion.FromString("v1.3.0")))
			{
				return;
			}
			Dictionary<MobileParty, Vec2> data = new Dictionary<MobileParty, Vec2>();
			dataStore.SyncData("_trackDataDictionary", ref data);
			if (!data.Any())
			{
				return;
			}
			foreach (KeyValuePair<MobileParty, Vec2> item in data)
			{
				_trackDataDictionary.Add(item.Key, new CampaignVec2(item.Value, isOnLand: true));
			}
		}

		private void OnHourlyTickParty(MobileParty mobileParty)
		{
			if (Campaign.Current.Models.MapTrackModel.CanPartyLeaveTrack(mobileParty))
			{
				CampaignVec2 campaignVec = CampaignVec2.Zero;
				if (_trackDataDictionary.ContainsKey(mobileParty))
				{
					campaignVec = _trackDataDictionary[mobileParty];
				}
				if (campaignVec.DistanceSquared(mobileParty.Position.ToVec2()) > 5f && IsTrackDropped(mobileParty))
				{
					CampaignVec2 position = mobileParty.Position;
					Vec2 trackDirection = mobileParty.Position.ToVec2() - campaignVec.ToVec2();
					trackDirection.Normalize();
					AddTrack(mobileParty, position, trackDirection);
					_trackDataDictionary[mobileParty] = position;
				}
			}
		}

		private void OnHourlyTick()
		{
			RemoveExpiredTracks();
		}

		private void GameLoadFinished()
		{
			_allTracks.RemoveAll((Track x) => x.IsExpired);
			_detectedTracksCache = _allTracks.Where((Track x) => x.IsDetected).ToMBList();
			AddEventHandler();
			foreach (Track allTrack in _allTracks)
			{
				_trackLocator.UpdateLocator(allTrack);
			}
			foreach (MobileParty item in _trackDataDictionary.Keys.ToList())
			{
				if (!item.IsActive)
				{
					_trackDataDictionary.Remove(item);
				}
			}
		}

		private void AddEventHandler()
		{
			_quarterHourlyTick = CampaignPeriodicEventManager.CreatePeriodicEvent(CampaignTime.Hours(0.25f), CampaignTime.Hours(0.1f));
			_quarterHourlyTick.AddHandler(QuarterHourlyTick);
		}

		private void QuarterHourlyTick(MBCampaignEvent campaignEvent, object[] delegateParams)
		{
			if (!PartyBase.MainParty.IsValid)
			{
				return;
			}
			int num = ((MobileParty.MainParty.EffectiveScout != null) ? MobileParty.MainParty.EffectiveScout.GetSkillValue(DefaultSkills.Scouting) : 0);
			if (num == 0)
			{
				return;
			}
			float maxTrackSpottingDistanceForMainParty = Campaign.Current.Models.MapTrackModel.GetMaxTrackSpottingDistanceForMainParty();
			LocatableSearchData<Track> data = _trackLocator.StartFindingLocatablesAroundPosition(MobileParty.MainParty.Position.ToVec2(), maxTrackSpottingDistanceForMainParty);
			for (Track track = _trackLocator.FindNextLocatable(ref data); track != null; track = _trackLocator.FindNextLocatable(ref data))
			{
				if (!track.IsDetected && _allTracks.Contains(track) && Campaign.Current.Models.MapTrackModel.GetTrackDetectionDifficultyForMainParty(track, maxTrackSpottingDistanceForMainParty) < (float)num)
				{
					TrackDetected(track);
				}
			}
		}

		private void RemoveExpiredTracks()
		{
			for (int num = _allTracks.Count - 1; num >= 0; num--)
			{
				Track track = _allTracks[num];
				if (track.IsExpired)
				{
					_allTracks.Remove(track);
					if (_detectedTracksCache.Contains(track))
					{
						_detectedTracksCache.Remove(track);
						CampaignEventDispatcher.Instance.TrackLost(track);
					}
					_trackLocator.RemoveLocatable(track);
					_trackPool.ReleaseTrack(track);
				}
			}
		}

		private void TrackDetected(Track track)
		{
			track.IsDetected = true;
			_detectedTracksCache.Add(track);
			CampaignEventDispatcher.Instance.TrackDetected(track);
			SkillLevelingManager.OnTrackDetected(track);
		}

		public bool IsTrackDropped(MobileParty mobileParty)
		{
			float skipTrackChance = Campaign.Current.Models.MapTrackModel.GetSkipTrackChance(mobileParty);
			if (MBRandom.RandomFloat < skipTrackChance)
			{
				return false;
			}
			float num = mobileParty.Position.DistanceSquared(MobileParty.MainParty.Position);
			float num2 = (MobileParty.MainParty.IsActive ? (MobileParty.MainParty._lastCalculatedSpeed * Campaign.Current.Models.MapTrackModel.MaxTrackLife) : 0f);
			if (num2 * num2 > num)
			{
				return true;
			}
			return false;
		}

		public void AddTrack(MobileParty party, CampaignVec2 trackPosition, Vec2 trackDirection)
		{
			Track track = _trackPool.RequestTrack(party, trackPosition, trackDirection);
			_allTracks.Add(track);
			_trackLocator.UpdateLocator(track);
		}

		public void AddMapArrow(TextObject pointerName, CampaignVec2 trackPosition, Vec2 trackDirection, float life)
		{
			Track track = _trackPool.RequestMapArrow(pointerName, trackPosition, trackDirection, life);
			_allTracks.Add(track);
			_trackLocator.UpdateLocator(track);
			TrackDetected(track);
		}
	}
	public class MapWeatherCampaignBehavior : CampaignBehaviorBase
	{
		private WeatherNode[] _weatherNodes;

		private MBCampaignEvent _weatherTickEvent;

		private int[] _weatherNodeDataShuffledIndices;

		private int _lastUpdatedNodeIndex;

		public WeatherNode[] AllWeatherNodes => _weatherNodes;

		private int DimensionSquared => Campaign.Current.DefaultWeatherNodeDimension * Campaign.Current.DefaultWeatherNodeDimension;

		public override void RegisterEvents()
		{
			CampaignEvents.OnSessionLaunchedEvent.AddNonSerializedListener(this, OnSessionLaunchedEvent);
		}

		private void OnSessionLaunchedEvent(CampaignGameStarter obj)
		{
			InitializeTheBehavior();
			for (int i = 0; i < DimensionSquared; i++)
			{
				UpdateWeatherNodeWithIndex(i);
			}
		}

		public override void SyncData(IDataStore dataStore)
		{
			dataStore.SyncData("_lastUpdatedNodeIndex", ref _lastUpdatedNodeIndex);
		}

		private void CreateAndShuffleDataIndicesDeterministic()
		{
			_weatherNodeDataShuffledIndices = new int[DimensionSquared];
			for (int i = 0; i < DimensionSquared; i++)
			{
				_weatherNodeDataShuffledIndices[i] = i;
			}
			MBFastRandom mBFastRandom = new MBFastRandom((uint)Campaign.Current.UniqueGameId.GetDeterministicHashCode());
			for (int j = 0; j < 20; j++)
			{
				for (int k = 0; k < DimensionSquared; k++)
				{
					int num = mBFastRandom.Next(DimensionSquared);
					int num2 = _weatherNodeDataShuffledIndices[k];
					_weatherNodeDataShuffledIndices[k] = _weatherNodeDataShuffledIndices[num];
					_weatherNodeDataShuffledIndices[num] = num2;
				}
			}
		}

		private void InitializeTheBehavior()
		{
			CreateAndShuffleDataIndicesDeterministic();
			_weatherNodes = new WeatherNode[DimensionSquared];
			Vec2 terrainSize = Campaign.Current.MapSceneWrapper.GetTerrainSize();
			int defaultWeatherNodeDimension = Campaign.Current.DefaultWeatherNodeDimension;
			int num = defaultWeatherNodeDimension;
			int num2 = defaultWeatherNodeDimension;
			for (int i = 0; i < num2; i++)
			{
				for (int j = 0; j < num; j++)
				{
					float a = (float)i / (float)defaultWeatherNodeDimension * terrainSize.X;
					float b = (float)j / (float)defaultWeatherNodeDimension * terrainSize.Y;
					Vec2 pos = new Vec2(a, b);
					CampaignVec2 position = new CampaignVec2(pos, isOnLand: true);
					if (!position.IsValid())
					{
						position = new CampaignVec2(pos, isOnLand: false);
					}
					_weatherNodes[i * defaultWeatherNodeDimension + j] = new WeatherNode(position);
				}
			}
			AddEventHandler();
		}

		private void AddEventHandler()
		{
			long numTicks = Campaign.Current.Models.MapWeatherModel.WeatherUpdateFrequency.NumTicks - CampaignTime.Now.NumTicks % Campaign.Current.Models.MapWeatherModel.WeatherUpdateFrequency.NumTicks;
			_weatherTickEvent = CampaignPeriodicEventManager.CreatePeriodicEvent(Campaign.Current.Models.MapWeatherModel.WeatherUpdateFrequency, new CampaignTime(numTicks));
			_weatherTickEvent.AddHandler(WeatherUpdateTick);
		}

		private void WeatherUpdateTick(MBCampaignEvent campaignEvent, params object[] delegateParams)
		{
			UpdateWeatherNodeWithIndex(_weatherNodeDataShuffledIndices[_lastUpdatedNodeIndex]);
			_lastUpdatedNodeIndex++;
			if (_lastUpdatedNodeIndex == _weatherNodes.Length)
			{
				_lastUpdatedNodeIndex = 0;
			}
		}

		private void UpdateWeatherNodeWithIndex(int index)
		{
			WeatherNode weatherNode = _weatherNodes[index];
			MapWeatherModel.WeatherEvent currentWeatherEvent = weatherNode.CurrentWeatherEvent;
			MapWeatherModel.WeatherEvent weatherEvent = Campaign.Current.Models.MapWeatherModel.UpdateWeatherForPosition(weatherNode.Position, CampaignTime.Now);
			MapWeatherModel.WeatherEventEffectOnTerrain weatherEffectOnTerrainForPosition = Campaign.Current.Models.MapWeatherModel.GetWeatherEffectOnTerrainForPosition(weatherNode.Position.ToVec2());
			if (currentWeatherEvent != weatherEvent || weatherEffectOnTerrainForPosition == MapWeatherModel.WeatherEventEffectOnTerrain.Wet)
			{
				weatherNode.SetVisualDirty();
			}
			else if (currentWeatherEvent == MapWeatherModel.WeatherEvent.Clear && MBRandom.NondeterministicRandomFloat < 0.1f)
			{
				weatherNode.SetVisualDirty();
			}
		}
	}
	public class MarriageOfferCampaignBehavior : CampaignBehaviorBase, IMarriageOfferCampaignBehavior, ICampaignBehavior
	{
		private const int MarriageOfferCooldownDurationAsDays = 7;

		private const int OfferRelationGainAmountWithTheMarriageClan = 10;

		private const float MapNotificationAutoDeclineDurationInDays = 2f;

		private readonly TextObject MarriageOfferPanelExplanationText = new TextObject("{=CZwrlJMJ}A courier with a marriage offer for {CLAN_MEMBER.NAME} from {OFFERING_CLAN_NAME} has arrived.");

		private readonly TextObject MarriagePreparationStartedText = new TextObject("{=yz78jqbx}Ceremony is being prepared and will be conducted as soon as possible.");

		private readonly TextObject MarriagePreparationCanceledText = new TextObject("{=dp044PNk}Due to the untimely death of {DEAD_HERO}, {?DEAD_HERO.GENDER}her{?}his{\\\\?} marriage with {OTHER_HERO} has been cancelled.");

		private Hero _currentOfferedPlayerClanHero;

		private Hero _currentOfferedOtherClanHero;

		private CampaignTime _lastMarriageOfferTime;

		private Dictionary<Hero, Hero> _acceptedMarriageOffersThatWaitingForAvailability = new Dictionary<Hero, Hero>();

		internal bool IsThereActiveMarriageOffer
		{
			get
			{
				if (_currentOfferedPlayerClanHero != null)
				{
					return _currentOfferedOtherClanHero != null;
				}
				return false;
			}
		}

		public override void RegisterEvents()
		{
			CampaignEvents.DailyTickClanEvent.AddNonSerializedListener(this, DailyTickClan);
			CampaignEvents.OnMarriageOfferedToPlayerEvent.AddNonSerializedListener(this, OnMarriageOfferedToPlayer);
			CampaignEvents.OnMarriageOfferCanceledEvent.AddNonSerializedListener(this, OnMarriageOfferCanceled);
			CampaignEvents.HourlyTickEvent.AddNonSerializedListener(this, HourlyTick);
			CampaignEvents.HeroPrisonerTaken.AddNonSerializedListener(this, OnHeroPrisonerTaken);
			CampaignEvents.BeforeHeroesMarried.AddNonSerializedListener(this, OnHeroesMarried);
			CampaignEvents.HeroKilledEvent.AddNonSerializedListener(this, OnHeroKilled);
			CampaignEvents.ArmyCreated.AddNonSerializedListener(this, OnArmyCreated);
			CampaignEvents.MapEventStarted.AddNonSerializedListener(this, OnMapEventStarted);
			CampaignEvents.CharacterBecameFugitiveEvent.AddNonSerializedListener(this, CharacterBecameFugitive);
			CampaignEvents.WarDeclared.AddNonSerializedListener(this, OnWarDeclared);
			CampaignEvents.HeroRelationChanged.AddNonSerializedListener(this, OnHeroRelationChanged);
			CampaignEvents.OnClanChangedKingdomEvent.AddNonSerializedListener(this, OnClanChangedKingdom);
		}

		public override void SyncData(IDataStore dataStore)
		{
			dataStore.SyncData("_currentOfferedPlayerClanHero", ref _currentOfferedPlayerClanHero);
			dataStore.SyncData("_currentOfferedOtherClanHero", ref _currentOfferedOtherClanHero);
			dataStore.SyncData("_lastMarriageOfferTime", ref _lastMarriageOfferTime);
			dataStore.SyncData("_acceptedMarriageOffersThatWaitingForAvailability", ref _acceptedMarriageOffersThatWaitingForAvailability);
		}

		public void CreateMarriageOffer(Hero currentOfferedPlayerClanHero, Hero currentOfferedOtherClanHero)
		{
			_currentOfferedPlayerClanHero = currentOfferedPlayerClanHero;
			_currentOfferedOtherClanHero = currentOfferedOtherClanHero;
			_lastMarriageOfferTime = CampaignTime.Now;
			MarriageOfferPanelExplanationText.SetCharacterProperties("CLAN_MEMBER", _currentOfferedPlayerClanHero.CharacterObject);
			MarriageOfferPanelExplanationText.SetTextVariable("OFFERING_CLAN_NAME", _currentOfferedOtherClanHero.Clan.Name);
			Campaign.Current.CampaignInformationManager.NewMapNoticeAdded(new MarriageOfferMapNotification(_currentOfferedPlayerClanHero, _currentOfferedOtherClanHero, MarriageOfferPanelExplanationText));
		}

		public MBBindingList<TextObject> GetMarriageAcceptedConsequences()
		{
			MBBindingList<TextObject> mBBindingList = new MBBindingList<TextObject>();
			TextObject textObject = GameTexts.FindText("str_marriage_consequence_hero_join_clan");
			if (Campaign.Current.Models.MarriageModel.GetClanAfterMarriage(_currentOfferedPlayerClanHero, _currentOfferedOtherClanHero) == _currentOfferedPlayerClanHero.Clan)
			{
				textObject.SetCharacterProperties("HERO", _currentOfferedOtherClanHero.CharacterObject);
				textObject.SetTextVariable("CLAN_NAME", _currentOfferedPlayerClanHero.Clan.Name);
			}
			else
			{
				textObject.SetCharacterProperties("HERO", _currentOfferedPlayerClanHero.CharacterObject);
				textObject.SetTextVariable("CLAN_NAME", _currentOfferedOtherClanHero.Clan.Name);
			}
			mBBindingList.Add(textObject);
			TextObject textObject2 = GameTexts.FindText("str_marriage_consequence_clan_relation");
			textObject2.SetTextVariable("CLAN_NAME", _currentOfferedOtherClanHero.Clan.Name);
			textObject2.SetTextVariable("AMOUNT", 10.ToString("+0;-#"));
			mBBindingList.Add(textObject2);
			return mBBindingList;
		}

		private void DailyTickClan(Clan consideringClan)
		{
			if (!CanOfferMarriageForClan(consideringClan))
			{
				return;
			}
			MobileParty.NavigationType navigationType = ((!consideringClan.HasNavalNavigationCapability) ? MobileParty.NavigationType.Default : MobileParty.NavigationType.All);
			float distance = Campaign.Current.Models.MapDistanceModel.GetDistance(Clan.PlayerClan.FactionMidSettlement, consideringClan.FactionMidSettlement, isFromPort: false, isTargetingPort: false, navigationType);
			if (!(MBRandom.RandomFloat >= distance / Campaign.Current.Models.MapDistanceModel.GetMaximumDistanceBetweenTwoConnectedSettlements(navigationType) - 0.5f))
			{
				return;
			}
			foreach (Hero hero in Clan.PlayerClan.Heroes)
			{
				if (hero != Hero.MainHero && hero.CanMarry() && !_acceptedMarriageOffersThatWaitingForAvailability.ContainsKey(hero) && ConsiderMarriageForPlayerClanMember(hero, consideringClan))
				{
					break;
				}
			}
		}

		private void MarryHeroesViaOffer(Hero playerClanHero, Hero otherClanHero, bool showSceneNotification)
		{
			if (playerClanHero != Hero.MainHero && showSceneNotification)
			{
				Hero groomHero = (playerClanHero.IsFemale ? otherClanHero : playerClanHero);
				Hero brideHero = (playerClanHero.IsFemale ? playerClanHero : otherClanHero);
				MBInformationManager.ShowSceneNotification(new MarriageSceneNotificationItem(groomHero, brideHero, CampaignTime.Now));
			}
			ChangeRelationAction.ApplyPlayerRelation(otherClanHero.Clan.Leader, 10);
			MarriageAction.Apply(playerClanHero, otherClanHero);
		}

		public void OnMarriageOfferAcceptedOnPopUp()
		{
			if (Campaign.Current.Models.MarriageModel.IsCoupleSuitableForMarriage(_currentOfferedPlayerClanHero, _currentOfferedOtherClanHero))
			{
				MarryHeroesViaOffer(_currentOfferedPlayerClanHero, _currentOfferedOtherClanHero, showSceneNotification: true);
			}
			else
			{
				_acceptedMarriageOffersThatWaitingForAvailability.Add(_currentOfferedPlayerClanHero, _currentOfferedOtherClanHero);
				InformationManager.ShowInquiry(new InquiryData(string.Empty, MarriagePreparationStartedText.ToString(), isAffirmativeOptionShown: true, isNegativeOptionShown: false, GameTexts.FindText("str_ok").ToString(), string.Empty, null, null));
			}
			FinalizeMarriageOffer();
		}

		public void OnMarriageOfferedToPlayer(Hero suitor, Hero maiden)
		{
		}

		public void OnMarriageOfferDeclinedOnPopUp()
		{
			CampaignEventDispatcher.Instance.OnMarriageOfferCanceled(_currentOfferedPlayerClanHero.IsFemale ? _currentOfferedOtherClanHero : _currentOfferedPlayerClanHero, _currentOfferedPlayerClanHero.IsFemale ? _currentOfferedPlayerClanHero : _currentOfferedOtherClanHero);
		}

		public void OnMarriageOfferCanceled(Hero suitor, Hero maiden)
		{
			FinalizeMarriageOffer();
		}

		public bool IsHeroEngaged(Hero hero)
		{
			foreach (KeyValuePair<Hero, Hero> item in _acceptedMarriageOffersThatWaitingForAvailability)
			{
				if (item.Key == hero || item.Value == hero)
				{
					return true;
				}
			}
			return false;
		}

		private void HourlyTick()
		{
			if (IsThereActiveMarriageOffer && _lastMarriageOfferTime.ElapsedDaysUntilNow >= 2f)
			{
				CampaignEventDispatcher.Instance.OnMarriageOfferCanceled(_currentOfferedPlayerClanHero.IsFemale ? _currentOfferedOtherClanHero : _currentOfferedPlayerClanHero, _currentOfferedPlayerClanHero.IsFemale ? _currentOfferedPlayerClanHero : _currentOfferedOtherClanHero);
			}
			MarriageModel marriageModel = Campaign.Current.Models.MarriageModel;
			List<Hero> list = new List<Hero>();
			foreach (KeyValuePair<Hero, Hero> item in _acceptedMarriageOffersThatWaitingForAvailability)
			{
				Hero key = item.Key;
				Hero value = item.Value;
				if (marriageModel.IsCoupleSuitableForMarriage(key, value))
				{
					MarryHeroesViaOffer(key, value, showSceneNotification: false);
					list.Add(key);
				}
				else if (!marriageModel.ShouldNpcMarriageBetweenClansBeAllowed(Clan.PlayerClan, value.Clan))
				{
					list.Add(key);
				}
			}
			foreach (Hero item2 in list)
			{
				_acceptedMarriageOffersThatWaitingForAvailability.Remove(item2);
			}
		}

		private void OnHeroPrisonerTaken(PartyBase capturer, Hero prisoner)
		{
			if (IsThereActiveMarriageOffer && (prisoner == Hero.MainHero || prisoner == _currentOfferedPlayerClanHero || prisoner == _currentOfferedOtherClanHero))
			{
				CampaignEventDispatcher.Instance.OnMarriageOfferCanceled(_currentOfferedPlayerClanHero.IsFemale ? _currentOfferedOtherClanHero : _currentOfferedPlayerClanHero, _currentOfferedPlayerClanHero.IsFemale ? _currentOfferedPlayerClanHero : _currentOfferedOtherClanHero);
			}
		}

		private void OnHeroesMarried(Hero hero1, Hero hero2, bool showNotification = true)
		{
			if (IsThereActiveMarriageOffer && ((hero1 == _currentOfferedPlayerClanHero && hero2 == _currentOfferedOtherClanHero) || (hero1 == _currentOfferedOtherClanHero && hero2 == _currentOfferedPlayerClanHero)))
			{
				CampaignEventDispatcher.Instance.OnMarriageOfferCanceled(_currentOfferedPlayerClanHero.IsFemale ? _currentOfferedOtherClanHero : _currentOfferedPlayerClanHero, _currentOfferedPlayerClanHero.IsFemale ? _currentOfferedPlayerClanHero : _currentOfferedOtherClanHero);
			}
		}

		private void OnHeroKilled(Hero victim, Hero killer, KillCharacterAction.KillCharacterActionDetail detail, bool showNotification = true)
		{
			if (IsThereActiveMarriageOffer && (victim == Hero.MainHero || victim == _currentOfferedPlayerClanHero || victim == _currentOfferedOtherClanHero))
			{
				CampaignEventDispatcher.Instance.OnMarriageOfferCanceled(_currentOfferedPlayerClanHero.IsFemale ? _currentOfferedOtherClanHero : _currentOfferedPlayerClanHero, _currentOfferedPlayerClanHero.IsFemale ? _currentOfferedPlayerClanHero : _currentOfferedOtherClanHero);
			}
			Hero hero = null;
			foreach (KeyValuePair<Hero, Hero> item in _acceptedMarriageOffersThatWaitingForAvailability)
			{
				if (item.Key == victim || item.Value == victim)
				{
					hero = item.Key;
				}
			}
			if (hero != null)
			{
				Hero hero2 = null;
				Hero hero3 = null;
				if (hero.IsDead)
				{
					hero2 = hero;
					hero3 = _acceptedMarriageOffersThatWaitingForAvailability[hero];
				}
				else if (_acceptedMarriageOffersThatWaitingForAvailability[hero].IsDead)
				{
					hero2 = _acceptedMarriageOffersThatWaitingForAvailability[hero];
					hero3 = hero;
				}
				MarriagePreparationCanceledText.SetCharacterProperties("DEAD_HERO", hero2.CharacterObject);
				MarriagePreparationCanceledText.SetTextVariable("OTHER_HERO", hero3.Name);
				InformationManager.ShowInquiry(new InquiryData(string.Empty, MarriagePreparationCanceledText.ToString(), isAffirmativeOptionShown: true, isNegativeOptionShown: false, GameTexts.FindText("str_ok").ToString(), string.Empty, null, null));
				_acceptedMarriageOffersThatWaitingForAvailability.Remove(hero);
			}
		}

		private void OnArmyCreated(Army army)
		{
			if (IsThereActiveMarriageOffer && (_currentOfferedPlayerClanHero.PartyBelongedTo?.Army != null || _currentOfferedOtherClanHero.PartyBelongedTo?.Army != null))
			{
				CampaignEventDispatcher.Instance.OnMarriageOfferCanceled(_currentOfferedPlayerClanHero.IsFemale ? _currentOfferedOtherClanHero : _currentOfferedPlayerClanHero, _currentOfferedPlayerClanHero.IsFemale ? _currentOfferedPlayerClanHero : _currentOfferedOtherClanHero);
