			}
		}

		private void CharacterBecameFugitive(Hero hero, bool showNotification)
		{
			if (IsThereActiveMarriageOffer && (!_currentOfferedPlayerClanHero.IsActive || !_currentOfferedOtherClanHero.IsActive))
