		{
			if (IsThereActiveMarriageOffer && (!Campaign.Current.Models.MarriageModel.IsCoupleSuitableForMarriage(_currentOfferedPlayerClanHero, _currentOfferedOtherClanHero) || !Campaign.Current.Models.MarriageModel.ShouldNpcMarriageBetweenClansBeAllowed(Clan.PlayerClan, _currentOfferedOtherClanHero.Clan)))
			{
				CampaignEventDispatcher.Instance.OnMarriageOfferCanceled(_currentOfferedPlayerClanHero.IsFemale ? _currentOfferedOtherClanHero : _currentOfferedPlayerClanHero, _currentOfferedPlayerClanHero.IsFemale ? _currentOfferedPlayerClanHero : _currentOfferedOtherClanHero);
			}
		}

		private void OnHeroRelationChanged(Hero effectiveHero, Hero effectiveHeroGainedRelationWith, int relationChange, bool showNotification, ChangeRelationAction.ChangeRelationDetail detail, Hero originalHero, Hero originalGainedRelationWith)
		{
			if (IsThereActiveMarriageOffer && (effectiveHero.Clan == _currentOfferedPlayerClanHero.Clan || effectiveHero.Clan == _currentOfferedOtherClanHero.Clan) && (effectiveHeroGainedRelationWith.Clan == _currentOfferedPlayerClanHero.Clan || effectiveHeroGainedRelationWith.Clan == _currentOfferedOtherClanHero.Clan) && !Campaign.Current.Models.MarriageModel.ShouldNpcMarriageBetweenClansBeAllowed(_currentOfferedPlayerClanHero.Clan, _currentOfferedOtherClanHero.Clan))
			{
				CampaignEventDispatcher.Instance.OnMarriageOfferCanceled(_currentOfferedPlayerClanHero.IsFemale ? _currentOfferedOtherClanHero : _currentOfferedPlayerClanHero, _currentOfferedPlayerClanHero.IsFemale ? _currentOfferedPlayerClanHero : _currentOfferedOtherClanHero);
			}
		}

		private void OnClanChangedKingdom(Clan clan, Kingdom oldKingdom, Kingdom newKingdom, ChangeKingdomAction.ChangeKingdomActionDetail detail, bool showNotification = true)
		{
			if (IsThereActiveMarriageOffer && (_currentOfferedPlayerClanHero.Clan == clan || _currentOfferedOtherClanHero.Clan == clan) && !Campaign.Current.Models.MarriageModel.ShouldNpcMarriageBetweenClansBeAllowed(_currentOfferedPlayerClanHero.Clan, _currentOfferedOtherClanHero.Clan))
			{
				CampaignEventDispatcher.Instance.OnMarriageOfferCanceled(_currentOfferedPlayerClanHero.IsFemale ? _currentOfferedOtherClanHero : _currentOfferedPlayerClanHero, _currentOfferedPlayerClanHero.IsFemale ? _currentOfferedPlayerClanHero : _currentOfferedOtherClanHero);
			}
		}

		private bool CanOfferMarriageForClan(Clan consideringClan)
		{
			if (!IsThereActiveMarriageOffer && _lastMarriageOfferTime.ElapsedDaysUntilNow >= 7f && !Hero.MainHero.IsPrisoner && !MobileParty.MainParty.IsInRaftState && consideringClan != Clan.PlayerClan && Campaign.Current.Models.MarriageModel.IsClanSuitableForMarriage(consideringClan))
			{
				return Campaign.Current.Models.MarriageModel.ShouldNpcMarriageBetweenClansBeAllowed(Clan.PlayerClan, consideringClan);
			}
			return false;
		}

		private bool ConsiderMarriageForPlayerClanMember(Hero playerClanHero, Clan consideringClan)
		{
			MarriageModel marriageModel = Campaign.Current.Models.MarriageModel;
			foreach (Hero hero in consideringClan.Heroes)
			{
				float num = marriageModel.NpcCoupleMarriageChance(playerClanHero, hero);
				if (!(num > 0f) || !(MBRandom.RandomFloat < num))
				{
					continue;
				}
				foreach (Romance.RomanticState romanticState in Romance.RomanticStateList)
				{
					if (romanticState.Level >= Romance.RomanceLevelEnum.MatchMadeByFamily && (romanticState.Person1 == playerClanHero || romanticState.Person2 == playerClanHero || romanticState.Person1 == hero || romanticState.Person2 == hero))
					{
						return false;
					}
				}
				CreateMarriageOffer(playerClanHero, hero);
				return true;
			}
			return false;
		}

		private void FinalizeMarriageOffer()
		{
			_currentOfferedPlayerClanHero = null;
			_currentOfferedOtherClanHero = null;
		}
	}
	public class MilitiasCampaignBehavior : CampaignBehaviorBase
	{
		public override void RegisterEvents()
		{
			CampaignEvents.OnNewGameCreatedPartialFollowUpEvent.AddNonSerializedListener(this, OnNewGameCreatedPartialFollowUp);
			CampaignEvents.AfterSiegeCompletedEvent.AddNonSerializedListener(this, OnAfterSiegeCompleted);
		}

		private void OnNewGameCreatedPartialFollowUp(CampaignGameStarter starter, int i)
		{
			int count = Town.AllTowns.Count;
			int count2 = Town.AllCastles.Count;
			int count3 = Village.All.Count;
			int num = count / 100 + ((count % 100 > i) ? 1 : 0);
			int num2 = count2 / 100 + ((count2 % 100 > i) ? 1 : 0);
			int num3 = count3 / 100 + ((count3 % 100 > i) ? 1 : 0);
			int num4 = count / 100 * i;
			int num5 = count2 / 100 * i;
			int num6 = count3 / 100 * i;
			for (int j = 0; j < i; j++)
			{
				num4 += ((count % 100 > j) ? 1 : 0);
				num5 += ((count2 % 100 > j) ? 1 : 0);
				num6 += ((count3 % 100 > j) ? 1 : 0);
			}
			for (int k = 0; k < num; k++)
			{
				Town.AllTowns[num4 + k].Settlement.Militia = Town.AllTowns[num4 + k].Settlement.Town.MilitiaChange * 45f;
			}
			for (int l = 0; l < num2; l++)
			{
				Town.AllCastles[num5 + l].Settlement.Militia = Town.AllCastles[num5 + l].Settlement.Town.MilitiaChange * 45f;
			}
			for (int m = 0; m < num3; m++)
			{
				Village.All[num6 + m].Settlement.Militia = Village.All[num6 + m].Settlement.Village.MilitiaChange * 45f;
			}
		}

		private void OnAfterSiegeCompleted(Settlement siegeSettlement, MobileParty attackerParty, bool isWin, MapEvent.BattleTypes battleType)
		{
			if ((battleType == MapEvent.BattleTypes.SallyOut || battleType == MapEvent.BattleTypes.Siege) && isWin)
			{
				siegeSettlement.Militia += Campaign.Current.Models.SettlementMilitiaModel.MilitiaToSpawnAfterSiege(siegeSettlement.Town);
			}
		}

		public override void SyncData(IDataStore dataStore)
		{
		}
	}
	public class MobilePartyTrainingBehavior : CampaignBehaviorBase
	{
		public override void RegisterEvents()
		{
			CampaignEvents.HourlyTickPartyEvent.AddNonSerializedListener(this, HourlyTickParty);
			CampaignEvents.DailyTickPartyEvent.AddNonSerializedListener(this, OnDailyTickParty);
			CampaignEvents.PlayerUpgradedTroopsEvent.AddNonSerializedListener(this, OnPlayerUpgradedTroops);
		}

		private void OnPlayerUpgradedTroops(CharacterObject troop, CharacterObject upgrade, int number)
		{
			SkillLevelingManager.OnUpgradeTroops(PartyBase.MainParty, troop, upgrade, number);
		}

		private void HourlyTickParty(MobileParty mobileParty)
		{
			if (mobileParty.LeaderHero != null)
			{
				if (mobileParty.BesiegerCamp != null)
				{
					SkillLevelingManager.OnSieging(mobileParty);
				}
				if (mobileParty.Army != null && mobileParty.Army.LeaderParty == mobileParty && mobileParty.AttachedParties.Count > 0)
				{
					SkillLevelingManager.OnLeadingArmy(mobileParty);
				}
				if (mobileParty.IsActive)
				{
					WorkSkills(mobileParty);
				}
			}
		}

		private void OnDailyTickParty(MobileParty mobileParty)
		{
			foreach (TroopRosterElement item in mobileParty.MemberRoster.GetTroopRoster())
			{
				ExplainedNumber effectiveDailyExperience = Campaign.Current.Models.PartyTrainingModel.GetEffectiveDailyExperience(mobileParty, item);
				if (!item.Character.IsHero)
				{
					mobileParty.Party.MemberRoster.AddXpToTroop(item.Character, TaleWorlds.Library.MathF.Round(effectiveDailyExperience.ResultNumber * (float)item.Number));
				}
			}
			if (mobileParty.IsDisbanding || !mobileParty.HasPerk(DefaultPerks.Bow.Trainer))
			{
				return;
			}
			Hero hero = null;
			int num = int.MaxValue;
			foreach (TroopRosterElement item2 in mobileParty.MemberRoster.GetTroopRoster())
			{
				if (item2.Character.IsHero)
				{
					int skillValue = item2.Character.HeroObject.GetSkillValue(DefaultSkills.Bow);
					if (skillValue < num)
					{
						num = skillValue;
						hero = item2.Character.HeroObject;
					}
				}
			}
			hero?.AddSkillXp(DefaultSkills.Bow, DefaultPerks.Bow.Trainer.PrimaryBonus);
		}

		private void CheckScouting(MobileParty mobileParty)
		{
			if (mobileParty.EffectiveScout != null && !mobileParty.IsCurrentlyAtSea)
			{
				TerrainType faceTerrainType = Campaign.Current.MapSceneWrapper.GetFaceTerrainType(mobileParty.CurrentNavigationFace);
				if (mobileParty != MobileParty.MainParty)
				{
					SkillLevelingManager.OnAIPartiesTravel(mobileParty.EffectiveScout, mobileParty.IsCaravan, faceTerrainType);
				}
				SkillLevelingManager.OnTraverseTerrain(mobileParty, faceTerrainType);
			}
		}

		private void WorkSkills(MobileParty mobileParty)
		{
			if (mobileParty.IsMoving)
			{
				CheckScouting(mobileParty);
				if (CampaignTime.Now.GetHourOfDay % 4 == 1)
				{
					CheckMovementSkills(mobileParty);
				}
			}
		}

		private void CheckMovementSkills(MobileParty mobileParty)
		{
			if (mobileParty == MobileParty.MainParty)
			{
				if (!mobileParty.IsCurrentlyAtSea)
				{
					foreach (TroopRosterElement item in mobileParty.MemberRoster.GetTroopRoster())
					{
						if (item.Character.IsHero)
						{
							if (item.Character.Equipment.Horse.IsEmpty)
							{
								SkillLevelingManager.OnTravelOnFoot(item.Character.HeroObject, mobileParty._lastCalculatedSpeed);
							}
							else
							{
								SkillLevelingManager.OnTravelOnHorse(item.Character.HeroObject, mobileParty._lastCalculatedSpeed);
							}
						}
					}
					return;
				}
				SkillLevelingManager.OnTravelOnWater(mobileParty, mobileParty._lastCalculatedSpeed);
			}
			else if (mobileParty.LeaderHero != null)
			{
				if (mobileParty.IsCurrentlyAtSea)
				{
					SkillLevelingManager.OnTravelOnWater(mobileParty, mobileParty._lastCalculatedSpeed);
				}
				else if (mobileParty.LeaderHero.CharacterObject.Equipment.Horse.IsEmpty)
				{
					SkillLevelingManager.OnTravelOnFoot(mobileParty.LeaderHero, mobileParty._lastCalculatedSpeed);
				}
				else
				{
					SkillLevelingManager.OnTravelOnHorse(mobileParty.LeaderHero, mobileParty._lastCalculatedSpeed);
				}
			}
		}

		public override void SyncData(IDataStore dataStore)
		{
		}
	}
	public class NotableHelperCharacterCampaignBehavior : CampaignBehaviorBase
	{
		private bool _addNotableHelperCharacters;

		public override void RegisterEvents()
		{
			CampaignEvents.LocationCharactersAreReadyToSpawnEvent.AddNonSerializedListener(this, LocationCharactersAreReadyToSpawn);
			CampaignEvents.OnMissionEndedEvent.AddNonSerializedListener(this, OnMissionEnded);
			CampaignEvents.SettlementEntered.AddNonSerializedListener(this, OnSettlementEntered);
		}

		public override void SyncData(IDataStore dataStore)
		{
		}

		private void OnMissionEnded(IMission mission)
		{
			if (LocationComplex.Current != null && PlayerEncounter.LocationEncounter != null && Settlement.CurrentSettlement != null && !Hero.MainHero.IsPrisoner && !Settlement.CurrentSettlement.IsUnderSiege)
			{
				_addNotableHelperCharacters = true;
			}
		}

		private void OnSettlementEntered(MobileParty mobileParty, Settlement settlement, Hero hero)
		{
			if (LocationComplex.Current != null && PlayerEncounter.LocationEncounter != null && mobileParty != null && mobileParty == MobileParty.MainParty)
			{
				_addNotableHelperCharacters = true;
			}
		}

		private void LocationCharactersAreReadyToSpawn(Dictionary<string, int> unusedUsablePointCount)
		{
			Settlement settlement = PlayerEncounter.LocationEncounter.Settlement;
			Location locationWithId = LocationComplex.Current.GetLocationWithId("center");
			Location locationWithId2 = LocationComplex.Current.GetLocationWithId("village_center");
			if (_addNotableHelperCharacters && (CampaignMission.Current.Location == locationWithId || CampaignMission.Current.Location == locationWithId2))
			{
				SpawnNotableHelperCharacters(settlement);
				_addNotableHelperCharacters = false;
			}
		}

		private void SpawnNotableHelperCharacters(Settlement settlement)
		{
			int num = settlement.Notables.Count((Hero x) => x.IsGangLeader);
			int characterToSpawnCount = settlement.Notables.Count((Hero x) => x.IsPreacher);
			int characterToSpawnCount2 = settlement.Notables.Count((Hero x) => x.IsArtisan);
			int characterToSpawnCount3 = settlement.Notables.Count((Hero x) => x.IsRuralNotable || x.IsHeadman);
			int characterToSpawnCount4 = settlement.Notables.Count((Hero x) => x.IsMerchant);
			SpawnNotableHelperCharacter(settlement.Culture.GangleaderBodyguard, "_gangleader_bodyguard", "sp_gangleader_bodyguard", num * 2);
			SpawnNotableHelperCharacter(settlement.Culture.PreacherNotary, "_merchant_notary", "sp_preacher_notary", characterToSpawnCount);
			SpawnNotableHelperCharacter(settlement.Culture.ArtisanNotary, "_merchant_notary", "sp_artisan_notary", characterToSpawnCount2);
			SpawnNotableHelperCharacter(settlement.Culture.RuralNotableNotary, "_merchant_notary", "sp_rural_notable_notary", characterToSpawnCount3);
			SpawnNotableHelperCharacter(settlement.Culture.MerchantNotary, "_merchant_notary", "sp_merchant_notary", characterToSpawnCount4);
		}

		private void SpawnNotableHelperCharacter(CharacterObject character, string actionSetSuffix, string tag, int characterToSpawnCount)
		{
			Location location = LocationComplex.Current.GetLocationWithId("center") ?? LocationComplex.Current.GetLocationWithId("village_center");
			while (characterToSpawnCount > 0)
			{
				Monster monsterWithSuffix = FaceGen.GetMonsterWithSuffix(character.Race, "_settlement");
				Campaign.Current.Models.AgeModel.GetAgeLimitForLocation(character, out var minimumAge, out var maximumAge, "Notary");
				AgentData agentData = new AgentData(new SimpleAgentOrigin(character)).Monster(monsterWithSuffix).NoHorses(noHorses: true).Age(MBRandom.RandomInt(minimumAge, maximumAge));
				LocationCharacter locationCharacter = new LocationCharacter(agentData, SandBoxManager.Instance.AgentBehaviorManager.AddWandererBehaviors, tag, fixedLocation: true, LocationCharacter.CharacterRelations.Neutral, ActionSetCode.GenerateActionSetNameWithSuffix(agentData.AgentMonster, agentData.AgentIsFemale, actionSetSuffix), useCivilianEquipment: true);
				location.AddCharacter(locationCharacter);
				characterToSpawnCount--;
			}
		}
	}
	public class NotablePowerManagementBehavior : CampaignBehaviorBase
	{
		private const int GoldLimitForNotablesToStartGainingPower = 10000;

		private const int GoldLimitForNotablesToStartLosingPower = 5000;

		private const int GoldNeededToGainOnePower = 500;

		public override void RegisterEvents()
		{
			CampaignEvents.HeroCreated.AddNonSerializedListener(this, OnHeroCreated);
			CampaignEvents.DailyTickHeroEvent.AddNonSerializedListener(this, DailyTickHero);
			CampaignEvents.RaidCompletedEvent.AddNonSerializedListener(this, OnRaidCompleted);
		}

		private void OnHeroCreated(Hero hero, bool isMaternal)
		{
			if (hero.IsNotable)
			{
				hero.AddPower(Campaign.Current.Models.NotablePowerModel.GetInitialPower(hero));
			}
		}

		private void DailyTickHero(Hero hero)
		{
			if (hero.IsAlive && hero.IsNotable)
			{
				hero.AddPower(Campaign.Current.Models.NotablePowerModel.CalculateDailyPowerChangeForHero(hero).ResultNumber);
				BalanceGoldAndPowerOfNotable(hero);
			}
		}

		private void OnRaidCompleted(BattleSideEnum winnerSide, RaidEventComponent mapEvent)
		{
			foreach (Hero notable in mapEvent.MapEventSettlement.Notables)
			{
				notable.AddPower(-5f);
			}
		}

		private void BalanceGoldAndPowerOfNotable(Hero notable)
		{
			if (notable.Gold > 10500)
			{
				int num = (notable.Gold - 10000) / 500;
				GiveGoldAction.ApplyBetweenCharacters(notable, null, num * 500, disableNotification: true);
				notable.AddPower(num);
			}
			else if (notable.Gold < 4500 && notable.Power > 0f)
			{
				int num2 = (5000 - notable.Gold) / 500;
				GiveGoldAction.ApplyBetweenCharacters(null, notable, num2 * 500, disableNotification: true);
				notable.AddPower(-num2);
			}
		}

		public override void SyncData(IDataStore dataStore)
		{
		}
	}
	public class NotablesCampaignBehavior : CampaignBehaviorBase
	{
