		private List<OrderOfBattleFormationData> _siegeFormationInfos;

		private List<OrderOfBattleFormationData> _siegeArmyFormationInfos;

		private List<OrderOfBattleFormationData> _fieldBattleFormationInfos;

		private List<OrderOfBattleFormationData> _fieldBattleArmyFormationInfos;

		public OrderOfBattleCampaignBehavior()
		{
			_siegeFormationInfos = new List<OrderOfBattleFormationData>();
			_siegeArmyFormationInfos = new List<OrderOfBattleFormationData>();
			_fieldBattleFormationInfos = new List<OrderOfBattleFormationData>();
			_fieldBattleArmyFormationInfos = new List<OrderOfBattleFormationData>();
		}

		public override void RegisterEvents()
		{
			CampaignEvents.OnHeroUnregisteredEvent.AddNonSerializedListener(this, OnHeroUnregistered);
		}

		public override void SyncData(IDataStore dataStore)
		{
			if (dataStore.SyncData("_siegeFormationInfos", ref _siegeFormationInfos) && _siegeFormationInfos == null)
			{
				_siegeFormationInfos = new List<OrderOfBattleFormationData>();
			}
			if (dataStore.SyncData("_siegeArmyFormationInfos", ref _siegeArmyFormationInfos) && _siegeArmyFormationInfos == null)
			{
				_siegeArmyFormationInfos = new List<OrderOfBattleFormationData>();
			}
			if (dataStore.SyncData("_formationInfos", ref _fieldBattleFormationInfos) && _fieldBattleFormationInfos == null)
			{
				_fieldBattleFormationInfos = new List<OrderOfBattleFormationData>();
			}
			if (dataStore.SyncData("_fieldBattleArmyFormationInfos", ref _fieldBattleArmyFormationInfos) && _fieldBattleArmyFormationInfos == null)
			{
				_fieldBattleArmyFormationInfos = new List<OrderOfBattleFormationData>();
			}
		}

		public OrderOfBattleFormationData GetFormationDataAtIndex(int formationIndex, bool isSiegeBattle, bool isInArmy)
		{
			if (isSiegeBattle)
			{
				if (isInArmy)
				{
					if (_siegeArmyFormationInfos.Count > formationIndex)
					{
						return _siegeArmyFormationInfos[formationIndex];
					}
					return null;
				}
				if (_siegeFormationInfos.Count > formationIndex)
				{
					return _siegeFormationInfos[formationIndex];
				}
				return null;
			}
			if (isInArmy)
			{
				if (_fieldBattleArmyFormationInfos.Count > formationIndex)
				{
					return _fieldBattleArmyFormationInfos[formationIndex];
				}
				return null;
			}
			if (_fieldBattleFormationInfos.Count > formationIndex)
			{
				return _fieldBattleFormationInfos[formationIndex];
			}
			return null;
		}

		public void SetFormationInfos(List<OrderOfBattleFormationData> formationInfos, bool isSiegeBattle, bool isInArmy)
		{
			if (isSiegeBattle)
			{
				if (isInArmy)
				{
					_siegeArmyFormationInfos = new List<OrderOfBattleFormationData>(formationInfos);
				}
				else
				{
					_siegeFormationInfos = new List<OrderOfBattleFormationData>(formationInfos);
				}
			}
			else if (isInArmy)
			{
				_fieldBattleArmyFormationInfos = new List<OrderOfBattleFormationData>(formationInfos);
			}
			else
			{
				_fieldBattleFormationInfos = new List<OrderOfBattleFormationData>(formationInfos);
			}
		}

		private void OnHeroUnregistered(Hero hero)
		{
			for (int num = _siegeFormationInfos.Count - 1; num >= 0; num--)
			{
				OrderOfBattleFormationData orderOfBattleFormationData = _siegeFormationInfos[num];
				if (orderOfBattleFormationData.Captain != hero)
				{
					Hero[] heroTroops = orderOfBattleFormationData.HeroTroops;
					if (heroTroops == null || !heroTroops.Contains(hero))
					{
						continue;
					}
				}
				Hero[] heroTroops2 = orderOfBattleFormationData.HeroTroops?.Where((Hero t) => t != hero).ToArray();
				Hero captain = ((orderOfBattleFormationData.Captain == hero) ? null : orderOfBattleFormationData.Captain);
				_siegeFormationInfos[num] = new OrderOfBattleFormationData(captain, heroTroops2, orderOfBattleFormationData.FormationClass, orderOfBattleFormationData.PrimaryClassWeight, orderOfBattleFormationData.SecondaryClassWeight, orderOfBattleFormationData.Filters);
			}
			for (int num2 = _fieldBattleFormationInfos.Count - 1; num2 >= 0; num2--)
			{
				OrderOfBattleFormationData orderOfBattleFormationData2 = _fieldBattleFormationInfos[num2];
				if (orderOfBattleFormationData2.Captain != hero)
				{
					Hero[] heroTroops3 = orderOfBattleFormationData2.HeroTroops;
					if (heroTroops3 == null || !heroTroops3.Contains(hero))
					{
						continue;
					}
				}
				Hero[] heroTroops4 = orderOfBattleFormationData2.HeroTroops?.Where((Hero t) => t != hero).ToArray();
				Hero captain2 = ((orderOfBattleFormationData2.Captain == hero) ? null : orderOfBattleFormationData2.Captain);
				_fieldBattleFormationInfos[num2] = new OrderOfBattleFormationData(captain2, heroTroops4, orderOfBattleFormationData2.FormationClass, orderOfBattleFormationData2.PrimaryClassWeight, orderOfBattleFormationData2.SecondaryClassWeight, orderOfBattleFormationData2.Filters);
			}
		}
	}
	public class ParleyCampaignBehavior : CampaignBehaviorBase, IParleyCampaignBehavior
	{
		private PartyBase _parleyedParty;

		public override void RegisterEvents()
		{
			CampaignEvents.OnSessionLaunchedEvent.AddNonSerializedListener(this, OnSessionLaunched);
		}

		public override void SyncData(IDataStore dataStore)
		{
			dataStore.SyncData("_parleyedParty", ref _parleyedParty);
		}

		public void StartParley(PartyBase partyBase)
		{
			if (partyBase.IsSettlement)
			{
				_parleyedParty = partyBase;
				GameMenu.ActivateGameMenu("request_meeting_parley");
			}
			else
			{
				TaleWorlds.Library.Debug.FailedAssert("MobileParty parley not implemented yet!", "C:\\BuildAgent\\work\\mb3\\Source\\Bannerlord\\TaleWorlds.CampaignSystem\\CampaignBehaviors\\ParleyCampaignBehavior.cs", "StartParley", 35);
			}
		}

		private void OnSessionLaunched(CampaignGameStarter campaignGameStarter)
		{
			AddMenus(campaignGameStarter);
		}

		private void AddMenus(CampaignGameStarter campaignGameStarter)
		{
			campaignGameStarter.AddGameMenu("request_meeting_parley", "{=pBAx7jTM}With whom do you want to meet?", game_menu_town_menu_request_meeting_on_init);
			campaignGameStarter.AddGameMenuOption("request_meeting_parley", "request_meeting_with", "{=!}{HERO_TO_MEET.LINK}", game_menu_request_meeting_with_on_condition, game_menu_request_meeting_with_on_consequence, isLeave: false, -1, isRepeatable: true);
			campaignGameStarter.AddGameMenuOption("request_meeting_parley", "meeting_town_leave", "{=3sRdGQou}Leave", game_meeting_town_leave_on_condition, game_menu_request_meeting_town_leave_on_consequence, isLeave: true);
			campaignGameStarter.AddGameMenuOption("request_meeting_parley", "meeting_castle_leave", "{=3sRdGQou}Leave", game_meeting_castle_leave_on_condition, game_menu_request_meeting_castle_leave_on_consequence, isLeave: true);
		}

		private void game_menu_town_menu_request_meeting_on_init(MenuCallbackArgs args)
		{
			List<Hero> heroesToMeetInTown = TownHelpers.GetHeroesToMeetInTown(_parleyedParty.Settlement);
			args.MenuContext.SetRepeatObjectList(heroesToMeetInTown);
			args.MenuContext.SetBackgroundMeshName(_parleyedParty.Settlement.SettlementComponent.WaitMeshName);
		}

		private bool game_menu_request_meeting_with_on_condition(MenuCallbackArgs args)
		{
			args.optionLeaveType = GameMenuOption.LeaveType.Conversation;
			Hero hero = args.MenuContext.GetCurrentRepeatableObject() as Hero;
			if (_parleyedParty != null && hero != null)
			{
				StringHelpers.SetCharacterProperties("HERO_TO_MEET", hero.CharacterObject);
				MenuHelper.SetIssueAndQuestDataForHero(args, hero);
				return true;
			}
			return false;
		}

		private void game_menu_request_meeting_town_leave_on_consequence(MenuCallbackArgs args)
		{
			SettlementMenuLeaveConsequenceCommon();
		}

		private void game_menu_request_meeting_castle_leave_on_consequence(MenuCallbackArgs args)
		{
			SettlementMenuLeaveConsequenceCommon();
		}

		private void SettlementMenuLeaveConsequenceCommon()
		{
			GameMenu.ExitToLast();
			_parleyedParty = null;
		}

		private void game_menu_request_meeting_with_on_consequence(MenuCallbackArgs args)
		{
			string sceneLevel;
			string meetingScene = GetMeetingScene(out sceneLevel);
			Hero hero = (Hero)args.MenuContext.GetSelectedObject();
			ConversationCharacterData playerCharacterData = new ConversationCharacterData(Hero.MainHero.CharacterObject, PartyBase.MainParty);
			ConversationCharacterData conversationPartnerData = new ConversationCharacterData(hero.CharacterObject, hero.PartyBelongedTo?.Party, noHorse: true);
			CampaignMission.OpenConversationMission(playerCharacterData, conversationPartnerData, meetingScene, sceneLevel);
		}

		private string GetMeetingScene(out string sceneLevel)
		{
			string sceneID = GameSceneDataManager.Instance.MeetingScenes.GetRandomElementWithPredicate((MeetingSceneData x) => x.Culture == _parleyedParty.Settlement.Culture).SceneID;
			if (string.IsNullOrEmpty(sceneID))
			{
				sceneID = GameSceneDataManager.Instance.MeetingScenes.GetRandomElement().SceneID;
			}
			sceneLevel = "";
			if (_parleyedParty.Settlement.IsFortification)
			{
				sceneLevel = Campaign.Current.Models.LocationModel.GetUpgradeLevelTag(_parleyedParty.Settlement.Town.GetWallLevel());
			}
			return sceneID;
		}

		private bool game_meeting_town_leave_on_condition(MenuCallbackArgs args)
		{
			args.optionLeaveType = GameMenuOption.LeaveType.Leave;
			return _parleyedParty.Settlement.IsTown;
		}

		private bool game_meeting_castle_leave_on_condition(MenuCallbackArgs args)
		{
			args.optionLeaveType = GameMenuOption.LeaveType.Leave;
			return _parleyedParty.Settlement.IsCastle;
		}

		public PartyBase GetParleyedParty()
		{
			return _parleyedParty;
		}
	}
	public class PartiesBuyFoodCampaignBehavior : CampaignBehaviorBase
	{
		public override void RegisterEvents()
		{
			CampaignEvents.SettlementEntered.AddNonSerializedListener(this, OnSettlementEntered);
			CampaignEvents.HourlyTickPartyEvent.AddNonSerializedListener(this, HourlyTickParty);
		}

		public override void SyncData(IDataStore dataStore)
		{
		}

		private void TryBuyingFood(MobileParty mobileParty, Settlement settlement)
		{
			if (Campaign.Current.GameStarted && mobileParty.LeaderHero != null && (settlement.IsTown || settlement.IsVillage) && Campaign.Current.Models.MobilePartyFoodConsumptionModel.DoesPartyConsumeFood(mobileParty) && (mobileParty.Army == null || mobileParty.AttachedTo == null || mobileParty.Army.LeaderParty == mobileParty) && (settlement.IsVillage || (mobileParty.MapFaction != null && !mobileParty.MapFaction.IsAtWarWith(settlement.MapFaction))) && settlement.ItemRoster.TotalFood > 0)
			{
				float num = 0f;
				PartyFoodBuyingModel partyFoodBuyingModel = Campaign.Current.Models.PartyFoodBuyingModel;
				num = (settlement.IsVillage ? partyFoodBuyingModel.MinimumDaysFoodToLastWhileBuyingFoodFromVillage : partyFoodBuyingModel.MinimumDaysFoodToLastWhileBuyingFoodFromTown);
				if (mobileParty.Army == null || (mobileParty.AttachedTo == null && mobileParty.Army.LeaderParty != mobileParty))
				{
					BuyFoodInternal(mobileParty, settlement, CalculateFoodCountToBuy(mobileParty, num));
				}
				else
				{
					BuyFoodForArmy(mobileParty, settlement, num);
				}
			}
		}

		private int CalculateFoodCountToBuy(MobileParty mobileParty, float minimumDaysToLast)
		{
			if (mobileParty.FoodChange.ApproximatelyEqualsTo(0f))
			{
				return 0;
			}
			float num = (float)mobileParty.TotalFoodAtInventory / (0f - mobileParty.FoodChange);
			float num2 = minimumDaysToLast - num;
			if (num2 > 0f)
			{
				return (int)((0f - mobileParty.FoodChange) * num2);
			}
			return 0;
		}

		private void BuyFoodInternal(MobileParty mobileParty, Settlement settlement, int numberOfFoodItemsNeededToBuy)
		{
			if (mobileParty.IsMainParty)
			{
				return;
			}
			for (int i = 0; i < numberOfFoodItemsNeededToBuy; i++)
			{
				Campaign.Current.Models.PartyFoodBuyingModel.FindItemToBuy(mobileParty, settlement, out var itemRosterElement, out var itemElementsPrice);
				if (itemRosterElement.EquipmentElement.Item != null)
				{
					if (itemElementsPrice <= (float)mobileParty.PartyTradeGold)
					{
						SellItemsAction.Apply(settlement.Party, mobileParty.Party, itemRosterElement, 1);
					}
					if (itemRosterElement.EquipmentElement.Item.HasHorseComponent && itemRosterElement.EquipmentElement.Item.HorseComponent.IsLiveStock)
					{
						i += itemRosterElement.EquipmentElement.Item.HorseComponent.MeatCount - 1;
					}
					continue;
				}
				break;
			}
		}

		private void BuyFoodForArmy(MobileParty mobileParty, Settlement settlement, float minimumDaysToLast)
		{
			float num = mobileParty.Army.LeaderParty.FoodChange;
			foreach (MobileParty attachedParty in mobileParty.Army.LeaderParty.AttachedParties)
			{
				num += attachedParty.FoodChange;
			}
			List<(int, int)> list = new List<(int, int)>(mobileParty.Army.Parties.Count);
			float num2 = mobileParty.Army.LeaderParty.FoodChange / num;
			int num3 = CalculateFoodCountToBuy(mobileParty.Army.LeaderParty, minimumDaysToLast);
			list.Add(((int)((float)settlement.ItemRoster.TotalFood * num2), num3));
			int num4 = num3;
			foreach (MobileParty attachedParty2 in mobileParty.Army.LeaderParty.AttachedParties)
			{
				num2 = attachedParty2.FoodChange / num;
				num3 = CalculateFoodCountToBuy(attachedParty2, minimumDaysToLast);
				list.Add(((int)((float)settlement.ItemRoster.TotalFood * num2), num3));
				num4 += num3;
			}
			bool flag = settlement.ItemRoster.TotalFood < num4;
			int num5 = 0;
			foreach (var item in list)
			{
				int num6;
				if (flag)
				{
					(num6, _) = item;
				}
				else
				{
					num6 = item.Item2;
				}
				int numberOfFoodItemsNeededToBuy = num6;
				MobileParty mobileParty2 = ((num5 == 0) ? mobileParty.Army.LeaderParty : mobileParty.Army.LeaderParty.AttachedParties[num5 - 1]);
				if (!mobileParty2.IsMainParty)
				{
					BuyFoodInternal(mobileParty2, settlement, numberOfFoodItemsNeededToBuy);
				}
				num5++;
			}
		}

		public void HourlyTickParty(MobileParty mobileParty)
		{
			Settlement currentSettlementOfMobilePartyForAICalculation = MobilePartyHelper.GetCurrentSettlementOfMobilePartyForAICalculation(mobileParty);
			if (currentSettlementOfMobilePartyForAICalculation != null)
			{
				TryBuyingFood(mobileParty, currentSettlementOfMobilePartyForAICalculation);
			}
		}

		public void OnSettlementEntered(MobileParty mobileParty, Settlement settlement, Hero hero)
		{
			if (mobileParty != null)
			{
				TryBuyingFood(mobileParty, settlement);
			}
		}
	}
	public class PartiesBuyHorseCampaignBehavior : CampaignBehaviorBase
	{
		private float _averageHorsePrice;

		public override void RegisterEvents()
		{
			CampaignEvents.SettlementEntered.AddNonSerializedListener(this, OnSettlementEntered);
			CampaignEvents.DailyTickEvent.AddNonSerializedListener(this, OnDailyTick);
			CampaignEvents.OnGameLoadedEvent.AddNonSerializedListener(this, OnGameStarted);
			CampaignEvents.OnNewGameCreatedEvent.AddNonSerializedListener(this, OnGameStarted);
		}

		public override void SyncData(IDataStore dataStore)
		{
		}

		private void OnGameStarted(CampaignGameStarter obj)
		{
			CalculateAverageHorsePrice();
		}

		private void OnDailyTick()
		{
			CalculateAverageHorsePrice();
		}

		private void CalculateAverageHorsePrice()
		{
			int num = 0;
			int num2 = 0;
			for (int i = 0; i < Items.All.Count; i++)
			{
				ItemObject itemObject = Items.All[i];
				if (itemObject.ItemCategory == DefaultItemCategories.Horse)
				{
					num += itemObject.Value;
					num2++;
				}
			}
			if (num2 == 0)
			{
				_averageHorsePrice = 0f;
			}
			else
			{
				_averageHorsePrice = num / num2;
			}
		}

		public void OnSettlementEntered(MobileParty mobileParty, Settlement settlement, Hero hero)
		{
			if (mobileParty != null && mobileParty.MapFaction != null && !mobileParty.MapFaction.IsAtWarWith(settlement.MapFaction) && mobileParty != MobileParty.MainParty && mobileParty.IsLordParty && mobileParty.LeaderHero != null && !mobileParty.IsDisbanding && settlement.IsTown)
			{
				int num = TaleWorlds.Library.MathF.Min(100000, mobileParty.PartyTradeGold);
				int numberOfMounts = mobileParty.Party.NumberOfMounts;
				if (numberOfMounts > mobileParty.Party.NumberOfRegularMembers)
				{
					return;
				}
				Town town = settlement.Town;
				if (town.MarketData.GetItemCountOfCategory(DefaultItemCategories.Horse) == 0)
				{
					return;
				}
				float num2 = _averageHorsePrice * (float)numberOfMounts / (float)num;
				if (num2 < 0.08f)
				{
					float randomFloat = MBRandom.RandomFloat;
					float randomFloat2 = MBRandom.RandomFloat;
					float randomFloat3 = MBRandom.RandomFloat;
					float num3 = (0.08f - num2) * (float)num * randomFloat * randomFloat2 * randomFloat3;
					if (num3 > (float)(mobileParty.Party.NumberOfRegularMembers - numberOfMounts) * _averageHorsePrice)
					{
						num3 = (float)(mobileParty.Party.NumberOfRegularMembers - numberOfMounts) * _averageHorsePrice;
					}
					BuyHorses(mobileParty, town, num3);
				}
			}
			if (mobileParty == null || mobileParty == MobileParty.MainParty || !mobileParty.IsLordParty || mobileParty.LeaderHero == null || mobileParty.IsDisbanding || !settlement.IsTown)
			{
				return;
			}
			float num4 = 0f;
			for (int num5 = mobileParty.ItemRoster.Count - 1; num5 >= 0; num5--)
			{
				ItemRosterElement subject = mobileParty.ItemRoster[num5];
				if (subject.EquipmentElement.Item.IsMountable)
				{
					num4 += (float)(subject.Amount * subject.EquipmentElement.Item.Value);
				}
				else if (!subject.EquipmentElement.Item.IsFood)
				{
					SellItemsAction.Apply(mobileParty.Party, settlement.Party, subject, subject.Amount, settlement);
				}
			}
			int num6 = TaleWorlds.Library.MathF.Min(100000, mobileParty.PartyTradeGold);
			if (!(num4 > (float)num6 * 0.1f))
			{
				return;
			}
			for (int i = 0; i < 10; i++)
			{
				ItemRosterElement subject2 = default(ItemRosterElement);
				int num7 = 0;
				for (int j = 0; j < mobileParty.ItemRoster.Count; j++)
				{
					ItemRosterElement itemRosterElement = mobileParty.ItemRoster[j];
					if (itemRosterElement.EquipmentElement.Item.IsMountable && itemRosterElement.EquipmentElement.Item.Value > num7)
					{
						num7 = itemRosterElement.EquipmentElement.Item.Value;
						subject2 = itemRosterElement;
					}
				}
				if (num7 > 0)
				{
					SellItemsAction.Apply(mobileParty.Party, settlement.Party, subject2, 1, settlement);
					num4 -= (float)num7;
					if (num4 < (float)num6 * 0.1f)
					{
						break;
					}
					continue;
				}
				break;
			}
		}

		private void BuyHorses(MobileParty mobileParty, Town town, float budget)
		{
			for (int i = 0; i < 2; i++)
			{
				int num = -1;
				int num2 = 100000;
				ItemRoster itemRoster = town.Owner.ItemRoster;
				for (int j = 0; j < itemRoster.Count; j++)
				{
					if (itemRoster.GetItemAtIndex(j).ItemCategory == DefaultItemCategories.Horse)
					{
						int itemPrice = town.GetItemPrice(itemRoster.GetElementCopyAtIndex(j).EquipmentElement, mobileParty);
						if (itemPrice < num2)
						{
							num2 = itemPrice;
							num = j;
						}
					}
				}
				if (num >= 0)
				{
					ItemRosterElement elementCopyAtIndex = itemRoster.GetElementCopyAtIndex(num);
					int num3 = elementCopyAtIndex.Amount;
					if ((float)(num3 * num2) > budget)
					{
						num3 = TaleWorlds.Library.MathF.Ceiling(budget / (float)num2);
					}
					int numberOfMounts = mobileParty.Party.NumberOfMounts;
					if (num3 > mobileParty.Party.NumberOfRegularMembers - numberOfMounts)
					{
						num3 = mobileParty.Party.NumberOfRegularMembers - numberOfMounts;
					}
					if (num3 > 0)
					{
						SellItemsAction.Apply(town.Owner, mobileParty.Party, elementCopyAtIndex, num3, town.Owner.Settlement);
					}
				}
			}
		}
	}
	public class PartiesSellLootCampaignBehavior : CampaignBehaviorBase
	{
		public override void RegisterEvents()
		{
			CampaignEvents.SettlementEntered.AddNonSerializedListener(this, OnSettlementEntered);
		}

		public override void SyncData(IDataStore dataStore)
		{
		}

		public void OnSettlementEntered(MobileParty mobileParty, Settlement settlement, Hero hero)
		{
			if (!Campaign.Current.GameStarted || mobileParty == null || FactionManager.IsAtWarAgainstFaction(mobileParty.MapFaction, settlement.MapFaction) || mobileParty.IsMainParty || !mobileParty.IsLordParty || mobileParty.IsDisbanding || !settlement.IsTown)
			{
				return;
			}
			int gold = settlement.SettlementComponent.Gold;
			for (int i = 0; i < mobileParty.ItemRoster.Count; i++)
			{
				ItemRosterElement subject = mobileParty.ItemRoster[i];
				ItemObject item = subject.EquipmentElement.Item;
				ItemModifier itemModifier = subject.EquipmentElement.ItemModifier;
				int amount = subject.Amount;
				if (!item.IsFood && (item.ItemType != ItemObject.ItemTypeEnum.Horse || !item.HorseComponent.IsRideable || itemModifier != null || item.HorseComponent.IsPackAnimal))
				{
					int itemPrice = settlement.Town.GetItemPrice(subject.EquipmentElement, mobileParty, isSelling: true);
					int num = ((itemPrice * amount < gold) ? amount : (gold / itemPrice));
					if (num > 0)
					{
						SellItemsAction.Apply(mobileParty.Party, settlement.Party, subject, num, settlement);
					}
				}
			}
		}
	}
	public class PartiesSellPrisonerCampaignBehavior : CampaignBehaviorBase
	{
		public override void RegisterEvents()
		{
			CampaignEvents.SettlementEntered.AddNonSerializedListener(this, OnSettlementEntered);
			CampaignEvents.DailyTickSettlementEvent.AddNonSerializedListener(this, DailyTickSettlement);
		}

		public override void SyncData(IDataStore dataStore)
		{
		}

		private void OnSettlementEntered(MobileParty mobileParty, Settlement settlement, Hero hero)
		{
			if (mobileParty == null || mobileParty.IsMainParty || !settlement.IsFortification || mobileParty.MapFaction == null || mobileParty.IsDisbanding || mobileParty.MapFaction.IsAtWarWith(settlement.MapFaction) || (mobileParty.PrisonRoster.TotalRegulars <= 0 && (mobileParty.PrisonRoster.TotalHeroes <= 0 || !mobileParty.PrisonRoster.GetTroopRoster().Exists((TroopRosterElement x) => x.Character != CharacterObject.PlayerCharacter && x.Character.HeroObject.MapFaction.IsAtWarWith(settlement.MapFaction)))))
			{
				return;
			}
			TroopRoster troopRoster = TroopRoster.CreateDummyTroopRoster();
			foreach (TroopRosterElement item in mobileParty.PrisonRoster.GetTroopRoster())
			{
				if (!item.Character.IsHero || (!item.Character.IsPlayerCharacter && item.Character.HeroObject.MapFaction.IsAtWarWith(settlement.MapFaction)))
				{
					troopRoster.Add(item);
				}
			}
			SellPrisonersAction.ApplyForSelectedPrisoners(mobileParty.Party, settlement.Party, troopRoster);
		}

		private void DailyTickSettlement(Settlement settlement)
		{
			if (!settlement.IsFortification)
			{
				return;
			}
			TroopRoster prisonRoster = settlement.Party.PrisonRoster;
			if (prisonRoster.TotalRegulars <= 0)
			{
				return;
			}
			int num = ((settlement.Owner == Hero.MainHero) ? (prisonRoster.TotalManCount - settlement.Party.PrisonerSizeLimit) : MBRandom.RoundRandomized((float)prisonRoster.TotalRegulars * 0.1f));
			if (num <= 0)
			{
				return;
			}
			TroopRoster troopRoster = TroopRoster.CreateDummyTroopRoster();
			IEnumerable<TroopRosterElement> enumerable;
			if (settlement.Owner != Hero.MainHero)
			{
				enumerable = prisonRoster.GetTroopRoster().AsEnumerable();
			}
			else
			{
				IEnumerable<TroopRosterElement> enumerable2 = from t in prisonRoster.GetTroopRoster()
					orderby t.Character.Tier
					select t;
				enumerable = enumerable2;
			}
			foreach (TroopRosterElement item in enumerable)
			{
				if (!item.Character.IsHero)
				{
					int num2 = Math.Min(num, item.Number);
					num -= num2;
					troopRoster.AddToCounts(item.Character, num2);
					if (num <= 0)
					{
						break;
					}
				}
			}
			if (troopRoster.TotalManCount > 0)
			{
				SellPrisonersAction.ApplyForSelectedPrisoners(settlement.Party, null, troopRoster);
			}
		}
	}
	public class PartyDiplomaticHandlerCampaignBehavior : CampaignBehaviorBase
	{
		private IFaction _lastFactionMadePeaceWithCausedPlayerToLeaveEvent;

		public override void RegisterEvents()
		{
			CampaignEvents.OnMapEventContinuityNeedsUpdateEvent.AddNonSerializedListener(this, OnMapEventContinuityNeedsUpdate);
			CampaignEvents.OnSettlementOwnerChangedEvent.AddNonSerializedListener(this, OnSettlementOwnerChanged);
			CampaignEvents.OnClanChangedKingdomEvent.AddNonSerializedListener(this, OnClanChangedKingdom);
			CampaignEvents.OnSessionLaunchedEvent.AddNonSerializedListener(this, OnSessionLaunched);
		}

		private void OnSessionLaunched(CampaignGameStarter gameSystemInitializer)
		{
			gameSystemInitializer.AddGameMenu("hostile_action_end_by_peace", "{=1rbg3Hz2}The {FACTION_1} and {FACTION_2} are no longer enemies.", game_menu_hostile_action_end_by_peace_on_init);
			gameSystemInitializer.AddGameMenuOption("hostile_action_end_by_peace", "hostile_action_en_by_peace_end", "{=WVkc4UgX}Continue.", delegate(MenuCallbackArgs args)
			{
				args.optionLeaveType = GameMenuOption.LeaveType.Leave;
				return true;
			}, player_encounter_finished_with_diplomatic_change_consequence, isLeave: true);
			gameSystemInitializer.AddGameMenu("village_raid_diplomatically_ended", "{=CnNUOM9Q}The owner of this fief and your kingdom are no longer enemies.", game_menu_hostile_action_end_by_peace_on_init);
			gameSystemInitializer.AddGameMenuOption("village_raid_diplomatically_ended", "leave", "{=3sRdGQou}Leave", delegate(MenuCallbackArgs args)
			{
				args.optionLeaveType = GameMenuOption.LeaveType.Leave;
				return MobileParty.MainParty.Army == null || MobileParty.MainParty.Army.LeaderParty == MobileParty.MainParty;
			}, player_encounter_finished_with_diplomatic_change_consequence, isLeave: true);
		}

		private static void player_encounter_finished_with_diplomatic_change_consequence(MenuCallbackArgs args)
		{
			if (PlayerEncounter.Current != null)
			{
				PlayerEncounter.Finish();
			}
			else
			{
				GameMenu.ExitToLast();
			}
		}

		private void OnClanChangedKingdom(Clan clan, Kingdom oldKingdom, Kingdom newKingdom, ChangeKingdomAction.ChangeKingdomActionDetail detail, bool arg5)
		{
			if (newKingdom != null)
			{
				CampaignEventDispatcher.Instance.OnMapEventContinuityNeedsUpdate(newKingdom);
			}
			else
			{
				CampaignEventDispatcher.Instance.OnMapEventContinuityNeedsUpdate(clan);
			}
		}

		private void OnMapEventContinuityNeedsUpdate(IFaction faction)
		{
			CheckMapEvents(faction);
			CheckSiegeEvents(faction);
			CheckFactionPartiesAndSettlements(faction);
		}

		private void OnSettlementOwnerChanged(Settlement settlement, bool openToClaim, Hero newOwner, Hero oldOwner, Hero capturerHero, ChangeOwnerOfSettlementAction.ChangeOwnerOfSettlementDetail detail)
		{
			if (detail != ChangeOwnerOfSettlementAction.ChangeOwnerOfSettlementDetail.BySiege && settlement.SiegeEvent != null)
			{
				CheckSiegeEventContinuity(settlement.SiegeEvent);
			}
			if (PlayerEncounter.Current != null && PlayerEncounter.Current.EncounterSettlementAux != null)
			{
				foreach (Village boundVillage in settlement.BoundVillages)
				{
					if (boundVillage.Settlement == PlayerEncounter.Current.EncounterSettlementAux && boundVillage.Settlement.IsUnderRaid && !Clan.PlayerClan.IsAtWarWith(newOwner.MapFaction))
					{
						_lastFactionMadePeaceWithCausedPlayerToLeaveEvent = oldOwner.MapFaction;
						GameMenu.ActivateGameMenu("village_raid_diplomatically_ended");
						break;
					}
				}
			}
			CheckSettlementSuitabilityForParties(settlement.Parties);
		}

		private void CheckFactionPartiesAndSettlements(IFaction faction)
		{
			CheckSettlementSuitabilityForParties(faction.WarPartyComponents.Select((WarPartyComponent x) => x.MobileParty));
			foreach (Settlement settlement in faction.Settlements)
			{
				CheckSettlementSuitabilityForParties(settlement.Parties);
			}
		}

		private void CheckMapEvents(IFaction faction)
		{
			MBReadOnlyList<MapEvent> obj = Campaign.Current.MapEventManager?.MapEvents;
			List<MapEvent> list = new List<MapEvent>();
			foreach (MapEvent item in obj)
			{
				if (!item.IsFinalized && item.InvolvedParties.Any((PartyBase x) => x.MapFaction == faction))
				{
					list.Add(item);
				}
			}
			foreach (MapEvent item2 in list)
			{
				List<MapEventParty> list2 = item2.AttackerSide.Parties.ToList();
				MapEventState state = item2.State;
				bool flag = false;
				foreach (MapEventParty item3 in list2)
				{
					if (!item2.CanPartyJoinBattle(item3.Party, BattleSideEnum.Attacker))
					{
						flag = flag || item2.IsPlayerMapEvent;
						if (item3.Party != PartyBase.MainParty)
						{
							item3.Party.MapEventSide = null;
						}
					}
				}
				if (state != MapEventState.WaitingRemoval && item2.State == MapEventState.WaitingRemoval)
				{
					item2.DiplomaticallyFinished = true;
				}
				if (flag)
				{
					if (PlayerEncounter.Current != null)
					{
						PlayerEncounter.Finish();
					}
					else
					{
						GameMenu.ExitToLast();
					}
				}
			}
		}

		private void CheckSiegeEvents(IFaction faction)
		{
			MBReadOnlyList<SiegeEvent> obj = Campaign.Current.SiegeEventManager?.SiegeEvents;
			List<SiegeEvent> list = new List<SiegeEvent>();
			foreach (SiegeEvent item in obj)
			{
				if (!item.ReadyToBeRemoved && item.GetInvolvedPartiesForEventType(item.GetCurrentBattleType()).Any((PartyBase x) => x.MapFaction == faction))
				{
					list.Add(item);
				}
			}
			foreach (SiegeEvent item2 in list)
			{
				CheckSiegeEventContinuity(item2);
			}
		}

		private void CheckSiegeEventContinuity(SiegeEvent siegeEvent)
		{
			bool flag = siegeEvent == PlayerSiege.PlayerSiegeEvent;
			List<PartyBase> list = siegeEvent.BesiegerCamp.GetInvolvedPartiesForEventType(siegeEvent.GetCurrentBattleType()).ToList();
			bool flag2 = false;
			for (int i = 0; i < list.Count; i++)
			{
				PartyBase partyBase = list[i];
				if (!siegeEvent.CanPartyJoinSide(partyBase, BattleSideEnum.Attacker))
				{
					if (flag && !flag2 && partyBase == PartyBase.MainParty)
					{
						flag2 = true;
						_lastFactionMadePeaceWithCausedPlayerToLeaveEvent = siegeEvent.BesiegedSettlement.MapFaction;
					}
					partyBase.MobileParty.BesiegerCamp = null;
				}
			}
			if (!siegeEvent.ReadyToBeRemoved && siegeEvent.BesiegerCamp.GetInvolvedPartiesForEventType(siegeEvent.GetCurrentBattleType()).Any((PartyBase x) => x != PartyBase.MainParty))
			{
				List<MobileParty> list2 = siegeEvent.BesiegedSettlement.Parties.ToList();
				for (int j = 0; j < list2.Count; j++)
				{
					PartyBase party = list2[j].Party;
					if (siegeEvent.BesiegedSettlement.MapFaction != party.MapFaction && !siegeEvent.CanPartyJoinSide(party, BattleSideEnum.Defender))
					{
						if (flag && !flag2 && party == PartyBase.MainParty)
						{
							flag2 = true;
							_lastFactionMadePeaceWithCausedPlayerToLeaveEvent = siegeEvent.BesiegerCamp.LeaderParty.MapFaction;
						}
						else if (party.MobileParty.Army == null || party.MobileParty.Army.LeaderParty == party.MobileParty)
						{
							LeaveSettlementAction.ApplyForParty(party.MobileParty);
						}
					}
				}
			}
			if (flag2)
			{
				GameMenu.ActivateGameMenu("hostile_action_end_by_peace");
			}
		}

		private void CheckSettlementSuitabilityForParties(IEnumerable<MobileParty> parties)
		{
			foreach (MobileParty item in parties.ToList())
			{
				if (item.CurrentSettlement == null || !item.MapFaction.IsAtWarWith(item.CurrentSettlement.MapFaction))
				{
					continue;
				}
				if (item != MobileParty.MainParty)
				{
					if (item.Army != null && item.Army.LeaderParty != item)
					{
						continue;
					}
					if (item.Army != null && item.Army.Parties.Contains(MobileParty.MainParty))
					{
						GameMenu.SwitchToMenu("army_left_settlement_due_to_war_declaration");
						continue;
					}
					if (item.IsTransitionInProgress)
					{
						item.CancelNavigationTransition();
					}
					LeaveSettlementAction.ApplyForParty(item);
				}
				else if (item.CurrentSettlement.IsFortification)
				{
					GameMenu.SwitchToMenu("fortification_crime_rating");
				}
			}
		}

		[GameMenuInitializationHandler("hostile_action_end_by_peace")]
		public static void hostile_action_end_by_peace_on_init(MenuCallbackArgs args)
		{
			if (MobileParty.MainParty.BesiegedSettlement != null)
			{
				args.MenuContext.SetBackgroundMeshName(MobileParty.MainParty.BesiegedSettlement.SettlementComponent.WaitMeshName);
			}
			else if (MobileParty.MainParty.LastVisitedSettlement != null)
			{
				args.MenuContext.SetBackgroundMeshName(MobileParty.MainParty.LastVisitedSettlement.SettlementComponent.WaitMeshName);
			}
			else if (PlayerEncounter.EncounterSettlement != null)
			{
				args.MenuContext.SetBackgroundMeshName(PlayerEncounter.EncounterSettlement.SettlementComponent.WaitMeshName);
			}
			else
			{
				TaleWorlds.Library.Debug.FailedAssert("No menu background to initialize!", "C:\\BuildAgent\\work\\mb3\\Source\\Bannerlord\\TaleWorlds.CampaignSystem\\CampaignBehaviors\\PartyDiplomaticHandlerCampaignBehavior.cs", "hostile_action_end_by_peace_on_init", 297);
			}
		}

		private void game_menu_hostile_action_end_by_peace_on_init(MenuCallbackArgs args)
		{
			if (_lastFactionMadePeaceWithCausedPlayerToLeaveEvent == null)
			{
				IEnumerable<IFaction> source = Kingdom.All.Union<IFaction>(Clan.All);
				IFaction mapFaction = MobileParty.MainParty.MapFaction;
				StanceLink stanceLink = (from x in source
					where x != mapFaction
					select x.GetStanceWith(mapFaction) into x
					where !x.IsAtWar
					orderby x.PeaceDeclarationDate.ElapsedHoursUntilNow
					select x).FirstOrDefault();
				_lastFactionMadePeaceWithCausedPlayerToLeaveEvent = ((stanceLink.Faction1 != Clan.PlayerClan.MapFaction) ? stanceLink.Faction1 : stanceLink.Faction2);
			}
			GameTexts.SetVariable("FACTION_1", Clan.PlayerClan.MapFaction.EncyclopediaLinkWithName);
			GameTexts.SetVariable("FACTION_2", _lastFactionMadePeaceWithCausedPlayerToLeaveEvent.EncyclopediaLinkWithName);
			if (PlayerEncounter.Battle != null)
			{
				PlayerEncounter.Battle.DiplomaticallyFinished = true;
			}
		}

		public override void SyncData(IDataStore dataStore)
		{
			dataStore.SyncData("_lastFactionMadePeaceWithCausedPlayerToLeaveEvent", ref _lastFactionMadePeaceWithCausedPlayerToLeaveEvent);
		}
	}
	public class PartyHealCampaignBehavior : CampaignBehaviorBase
	{
		private Dictionary<PartyBase, float> _overflowedHealingForRegulars = new Dictionary<PartyBase, float>();

		private Dictionary<PartyBase, float> _overflowedHealingForHeroes = new Dictionary<PartyBase, float>();

		private Dictionary<PartyBase, float> _overflowedHealingForPrisonerRegulars = new Dictionary<PartyBase, float>();

		private Dictionary<PartyBase, float> _overflowedHealingForPrisonerHeroes = new Dictionary<PartyBase, float>();

		public override void RegisterEvents()
		{
			CampaignEvents.HourlyTickClanEvent.AddNonSerializedListener(this, OnClanHourlyTick);
			CampaignEvents.HourlyTickEvent.AddNonSerializedListener(this, OnHourlyTick);
			CampaignEvents.MobilePartyDestroyed.AddNonSerializedListener(this, OnMobilePartyDestroyed);
			CampaignEvents.MapEventEnded.AddNonSerializedListener(this, OnMapEventEnded);
			CampaignEvents.OnQuarterDailyPartyTick.AddNonSerializedListener(this, OnQuarterDailyPartyTick);
			CampaignEvents.OnPlayerBattleEndEvent.AddNonSerializedListener(this, OnPlayerBattleEnd);
			CampaignEvents.DailyTickSettlementEvent.AddNonSerializedListener(this, OnDailyTickSettlement);
		}

		private void OnMobilePartyDestroyed(MobileParty mobileParty, PartyBase destroyerParty)
		{
			if (_overflowedHealingForRegulars.ContainsKey(mobileParty.Party))
			{
				_overflowedHealingForRegulars.Remove(mobileParty.Party);
				if (_overflowedHealingForHeroes.ContainsKey(mobileParty.Party))
				{
					_overflowedHealingForHeroes.Remove(mobileParty.Party);
				}
				if (_overflowedHealingForPrisonerRegulars.ContainsKey(mobileParty.Party))
				{
					_overflowedHealingForPrisonerRegulars.Remove(mobileParty.Party);
				}
				if (_overflowedHealingForPrisonerHeroes.ContainsKey(mobileParty.Party))
				{
					_overflowedHealingForPrisonerHeroes.Remove(mobileParty.Party);
				}
			}
		}

		public void OnMapEventEnded(MapEvent mapEvent)
		{
			if (!mapEvent.IsPlayerMapEvent)
			{
				OnBattleEndCheckPerkEffects(mapEvent);
			}
		}

		private void OnPlayerBattleEnd(MapEvent mapEvent)
		{
			OnBattleEndCheckPerkEffects(mapEvent);
		}

		private void OnBattleEndCheckPerkEffects(MapEvent mapEvent)
		{
			if (!mapEvent.HasWinner)
			{
				return;
			}
			foreach (PartyBase involvedParty in mapEvent.InvolvedParties)
			{
				if (involvedParty.MemberRoster.TotalHeroes <= 0)
				{
					continue;
				}
				foreach (TroopRosterElement item in involvedParty.MemberRoster.GetTroopRoster())
				{
					if (item.Character.IsHero)
					{
						Hero heroObject = item.Character.HeroObject;
						int roundedResultNumber = Campaign.Current.Models.PartyHealingModel.GetBattleEndHealingAmount(involvedParty, heroObject).RoundedResultNumber;
						if (roundedResultNumber > 0)
						{
							heroObject.Heal(roundedResultNumber);
						}
					}
				}
			}
		}

		public override void SyncData(IDataStore dataStore)
		{
			dataStore.SyncData("_overflowedHealingForRegulars", ref _overflowedHealingForRegulars);
			dataStore.SyncData("_overflowedHealingForHeroes", ref _overflowedHealingForHeroes);
			dataStore.SyncData("_overflowedHealingForPrisonerRegulars", ref _overflowedHealingForPrisonerRegulars);
			dataStore.SyncData("_overflowedHealingForPrisonerHeroes", ref _overflowedHealingForPrisonerHeroes);
		}

		private void OnHourlyTick()
		{
			TryHealOrWoundParty(MobileParty.MainParty.Party, CampaignTime.HoursInDay);
		}

		private void OnClanHourlyTick(Clan clan)
		{
			if (clan.IsBanditFaction)
			{
				return;
			}
			foreach (Hero hero in clan.Heroes)
			{
				float f = 0f;
				bool num = hero.PartyBelongedTo == null && hero.PartyBelongedToAsPrisoner == null;
				bool flag = hero.HeroState == Hero.CharacterStates.Dead || hero.HeroState == Hero.CharacterStates.NotSpawned || hero.HeroState == Hero.CharacterStates.Disabled;
				if (num && !flag)
				{
					f = Campaign.Current.Models.PartyHealingModel.GetDailyHealingHpForHeroes(null, isPrisoners: false).ResultNumber / (float)CampaignTime.HoursInDay;
				}
				int a = MBRandom.RoundRandomized(f);
				if (!hero.IsHealthFull())
				{
					int num2 = TaleWorlds.Library.MathF.Min(a, hero.MaxHitPoints - hero.HitPoints);
					hero.HitPoints += num2;
				}
			}
		}

		private void OnQuarterDailyPartyTick(MobileParty mobileParty)
		{
			if (!mobileParty.IsMainParty)
			{
				TryHealOrWoundParty(mobileParty.Party, 4f);
			}
		}

		private void OnDailyTickSettlement(Settlement settlement)
		{
			TryHealOrWoundParty(settlement.Party, 1f);
		}

		private void TryHealOrWoundParty(PartyBase partyBase, float healFrequencyPerDay)
		{
			if (partyBase.IsActive && partyBase.MapEvent == null)
			{
				TryToHealOrWoundMembers(partyBase, healFrequencyPerDay);
				TryToHealOrWoundPrisoners(partyBase, healFrequencyPerDay);
			}
		}

		private void TryToHealOrWoundPrisoners(PartyBase partyBase, float healFrequencyPerDay)
		{
			if (!_overflowedHealingForPrisonerHeroes.TryGetValue(partyBase, out var value))
			{
				_overflowedHealingForPrisonerHeroes.Add(partyBase, 0f);
			}
			if (!_overflowedHealingForPrisonerRegulars.TryGetValue(partyBase, out var value2))
			{
				_overflowedHealingForPrisonerRegulars.Add(partyBase, 0f);
			}
			float num = Campaign.Current.Models.PartyHealingModel.GetDailyHealingHpForHeroes(partyBase, isPrisoners: true).ResultNumber / healFrequencyPerDay;
			float num2 = Campaign.Current.Models.PartyHealingModel.GetDailyHealingForRegulars(partyBase, isPrisoner: true).ResultNumber / healFrequencyPerDay;
			value += num;
			value2 += num2;
			if ((int)value != 0)
			{
				ManageHealingOfPrisonerHeroes(partyBase, ref value);
			}
			if ((int)value2 != 0)
			{
				ManageHealingOfPrisonerRegulars(partyBase, ref value2);
			}
			_overflowedHealingForPrisonerHeroes[partyBase] = value;
			_overflowedHealingForPrisonerRegulars[partyBase] = value2;
		}

		private void TryToHealOrWoundMembers(PartyBase partyBase, float healFrequencyPerDay)
		{
			if (!_overflowedHealingForHeroes.TryGetValue(partyBase, out var value))
			{
				_overflowedHealingForHeroes.Add(partyBase, 0f);
			}
			if (!_overflowedHealingForRegulars.TryGetValue(partyBase, out var value2))
			{
				_overflowedHealingForRegulars.Add(partyBase, 0f);
			}
			float num = partyBase.HealingRateForMemberHeroes / healFrequencyPerDay;
			float num2 = partyBase.HealingRateForMemberRegulars / healFrequencyPerDay;
			value += num;
			value2 += num2;
			if (value >= 1f)
			{
				HealMemberHeroes(partyBase, ref value);
			}
			else if (value <= -1f)
			{
				ReduceHpMemberHeroes(partyBase, ref value);
			}
			if (value2 >= 1f)
			{
				HealMemberRegulars(partyBase, ref value2);
			}
			else if (value2 <= -1f)
			{
				ReduceHpMemberRegulars(partyBase, ref value2);
			}
			_overflowedHealingForHeroes[partyBase] = value;
			_overflowedHealingForRegulars[partyBase] = value2;
		}

		private void ManageHealingOfPrisonerRegulars(PartyBase partyBase, ref float prisonerRegularsHealingValue)
		{
			TroopRoster prisonRoster = partyBase.PrisonRoster;
			if (prisonRoster.TotalWoundedRegulars == 0)
			{
				prisonerRegularsHealingValue = 0f;
				return;
			}
			int num = TaleWorlds.Library.MathF.Floor(prisonerRegularsHealingValue);
			prisonerRegularsHealingValue -= num;
			int num2 = MBRandom.RandomInt(prisonRoster.Count);
			for (int i = 0; i < prisonRoster.Count; i++)
			{
				if (num <= 0)
				{
					break;
				}
				int index = (num2 + i) % prisonRoster.Count;
				if (prisonRoster.GetCharacterAtIndex(index).IsRegular && prisonRoster.GetElementWoundedNumber(index) > 0)
				{
					int num3 = TaleWorlds.Library.MathF.Min(num, prisonRoster.GetElementWoundedNumber(index));
					if (num3 > 0)
					{
						prisonRoster.AddToCountsAtIndex(index, 0, -num3);
						num -= num3;
					}
				}
			}
		}

		private void ManageHealingOfPrisonerHeroes(PartyBase partyBase, ref float prisonerHeroesHealingValue)
		{
			int num = TaleWorlds.Library.MathF.Floor(prisonerHeroesHealingValue);
			prisonerHeroesHealingValue -= num;
			TroopRoster prisonRoster = partyBase.PrisonRoster;
			if (prisonRoster.TotalHeroes <= 0)
			{
				return;
			}
			for (int i = 0; i < prisonRoster.Count; i++)
			{
				Hero heroObject = prisonRoster.GetCharacterAtIndex(i).HeroObject;
				if (heroObject != null && heroObject.HitPoints < heroObject.WoundedHealthLimit)
				{
					int healAmount = Math.Min(num, heroObject.WoundedHealthLimit - heroObject.HitPoints);
					heroObject.Heal(healAmount);
				}
			}
		}

		private static void HealMemberHeroes(PartyBase partyBase, ref float heroesHealingValue)
		{
			int num = TaleWorlds.Library.MathF.Floor(heroesHealingValue);
			heroesHealingValue -= num;
			TroopRoster memberRoster = partyBase.MemberRoster;
			if (memberRoster.TotalHeroes <= 0)
			{
				return;
			}
			for (int i = 0; i < memberRoster.Count; i++)
			{
				Hero heroObject = memberRoster.GetCharacterAtIndex(i).HeroObject;
				if (heroObject != null && !heroObject.IsHealthFull())
				{
					heroObject.Heal(num, addXp: true);
				}
			}
		}

		private static void ReduceHpMemberHeroes(PartyBase partyBase, ref float heroesHealingValue)
		{
			int a = TaleWorlds.Library.MathF.Ceiling(heroesHealingValue);
			heroesHealingValue = 0f - (0f - heroesHealingValue) % 1f;
			for (int i = 0; i < partyBase.MemberRoster.Count; i++)
			{
				Hero heroObject = partyBase.MemberRoster.GetCharacterAtIndex(i).HeroObject;
				if (heroObject != null && heroObject.HitPoints > 0)
				{
					int num = TaleWorlds.Library.MathF.Min(a, heroObject.HitPoints);
					heroObject.HitPoints += num;
				}
			}
		}

		private static void HealMemberRegulars(PartyBase partyBase, ref float regularsHealingValue)
		{
			TroopRoster memberRoster = partyBase.MemberRoster;
			if (memberRoster.TotalWoundedRegulars == 0)
			{
				regularsHealingValue = 0f;
				return;
			}
			int num = TaleWorlds.Library.MathF.Floor(regularsHealingValue);
			regularsHealingValue -= num;
			int num2 = 0;
			float num3 = 0f;
			int num4 = MBRandom.RandomInt(memberRoster.Count);
			for (int i = 0; i < memberRoster.Count; i++)
			{
				if (num <= 0)
				{
					break;
				}
				int index = (num4 + i) % memberRoster.Count;
				CharacterObject characterAtIndex = memberRoster.GetCharacterAtIndex(index);
				if (characterAtIndex.IsRegular)
				{
					int num5 = TaleWorlds.Library.MathF.Min(num, memberRoster.GetElementWoundedNumber(index));
					if (num5 > 0)
					{
						memberRoster.AddToCountsAtIndex(index, 0, -num5);
						num -= num5;
						num2 += num5;
						num3 += (float)(characterAtIndex.Tier * num5);
					}
				}
			}
			if (num2 > 0)
			{
				SkillLevelingManager.OnRegularTroopHealedWhileWaiting(partyBase.MobileParty, num2, num3 / (float)num2);
			}
		}

		private static void ReduceHpMemberRegulars(PartyBase partyBase, ref float regularsHealingValue)
		{
			TroopRoster memberRoster = partyBase.MemberRoster;
			if (memberRoster.TotalRegulars - memberRoster.TotalWoundedRegulars == 0)
			{
				regularsHealingValue = 0f;
				return;
			}
			int num = TaleWorlds.Library.MathF.Floor(0f - regularsHealingValue);
			regularsHealingValue = 0f - (0f - regularsHealingValue) % 1f;
			int num2 = MBRandom.RandomInt(memberRoster.Count);
			for (int i = 0; i < memberRoster.Count; i++)
			{
				if (num <= 0)
				{
					break;
				}
				int index = (num2 + i) % memberRoster.Count;
				if (memberRoster.GetCharacterAtIndex(index).IsRegular)
				{
					int num3 = TaleWorlds.Library.MathF.Min(memberRoster.GetElementNumber(index) - memberRoster.GetElementWoundedNumber(index), num);
					if (num3 > 0)
					{
						memberRoster.AddToCountsAtIndex(index, 0, num3);
						num -= num3;
					}
				}
			}
		}
	}
	public class PartyRolesCampaignBehavior : CampaignBehaviorBase
	{
		public override void RegisterEvents()
		{
			CampaignEvents.HeroKilledEvent.AddNonSerializedListener(this, OnHeroKilled);
			CampaignEvents.OnGovernorChangedEvent.AddNonSerializedListener(this, OnGovernorChanged);
			CampaignEvents.MobilePartyCreated.AddNonSerializedListener(this, OnPartySpawned);
			CampaignEvents.CompanionRemoved.AddNonSerializedListener(this, OnCompanionRemoved);
			CampaignEvents.OnHeroGetsBusyEvent.AddNonSerializedListener(this, OnHeroGetsBusy);
			CampaignEvents.HeroPrisonerTaken.AddNonSerializedListener(this, OnHeroPrisonerTaken);
			CampaignEvents.OnHeroChangedClanEvent.AddNonSerializedListener(this, OnHeroChangedClan);
		}

		public override void SyncData(IDataStore dataStore)
		{
		}

		private void OnHeroKilled(Hero victim, Hero killer, KillCharacterAction.KillCharacterActionDetail detail, bool showNotification = true)
		{
			if (victim.Clan == Clan.PlayerClan)
			{
				RemoveAllPartyRolesOfHeroIfExist(victim);
			}
		}

		private void OnHeroPrisonerTaken(PartyBase party, Hero prisoner)
		{
			if (prisoner.Clan == Clan.PlayerClan)
			{
				RemoveAllPartyRolesOfHeroIfExist(prisoner);
			}
		}

		private void OnGovernorChanged(Town fortification, Hero oldGovernor, Hero newGovernor)
		{
			if (newGovernor?.Clan == Clan.PlayerClan)
			{
				RemoveAllPartyRolesOfHeroIfExist(newGovernor);
			}
		}

		private void OnPartySpawned(MobileParty spawnedParty)
		{
			if (!spawnedParty.IsLordParty || spawnedParty.ActualClan != Clan.PlayerClan)
			{
				return;
			}
			foreach (TroopRosterElement item in spawnedParty.MemberRoster.GetTroopRoster())
			{
				if (item.Character.IsHero)
				{
					RemoveAllPartyRolesOfHeroIfExist(item.Character.HeroObject);
				}
			}
		}

		private void OnCompanionRemoved(Hero companion, RemoveCompanionAction.RemoveCompanionDetail detail)
		{
			RemoveAllPartyRolesOfHeroIfExist(companion);
		}

		private void OnHeroGetsBusy(Hero hero, HeroGetsBusyReasons heroGetsBusyReason)
		{
			if (hero.Clan == Clan.PlayerClan)
			{
				RemoveAllPartyRolesOfHeroIfExist(hero);
			}
		}

		private void OnHeroChangedClan(Hero hero, Clan oldClan)
		{
			if (oldClan == Clan.PlayerClan)
			{
				RemoveAllPartyRolesOfHeroIfExist(hero);
			}
		}

		private void RemoveAllPartyRolesOfHeroIfExist(Hero hero)
		{
			foreach (WarPartyComponent warPartyComponent in Clan.PlayerClan.WarPartyComponents)
			{
				warPartyComponent.MobileParty.RemoveAllPartyRolesOfHero(hero);
			}
		}
	}
	public class PartyUpgraderCampaignBehavior : CampaignBehaviorBase
	{
		private readonly struct TroopUpgradeArgs
		{
			public readonly CharacterObject Target;

			public readonly CharacterObject UpgradeTarget;

			public readonly int PossibleUpgradeCount;

			public readonly int UpgradeGoldCost;

			public readonly int UpgradeXpCost;

			public readonly float UpgradeChance;

			public TroopUpgradeArgs(CharacterObject target, CharacterObject upgradeTarget, int possibleUpgradeCount, int upgradeGoldCost, int upgradeXpCost, float upgradeChance)
			{
				Target = target;
				UpgradeTarget = upgradeTarget;
				PossibleUpgradeCount = possibleUpgradeCount;
				UpgradeGoldCost = upgradeGoldCost;
				UpgradeXpCost = upgradeXpCost;
				UpgradeChance = upgradeChance;
			}
		}

		public override void RegisterEvents()
		{
			CampaignEvents.MapEventEnded.AddNonSerializedListener(this, MapEventEnded);
			CampaignEvents.DailyTickPartyEvent.AddNonSerializedListener(this, DailyTickParty);
		}

		private void MapEventEnded(MapEvent mapEvent)
		{
			foreach (PartyBase involvedParty in mapEvent.InvolvedParties)
			{
				UpgradeReadyTroops(involvedParty);
			}
		}

		public void DailyTickParty(MobileParty party)
		{
			if (party.MapEvent == null)
			{
				UpgradeReadyTroops(party.Party);
			}
		}

		public override void SyncData(IDataStore dataStore)
		{
		}

		private TroopUpgradeArgs SelectPossibleUpgrade(List<TroopUpgradeArgs> possibleUpgrades)
		{
			TroopUpgradeArgs result = possibleUpgrades[0];
			if (possibleUpgrades.Count > 1)
			{
				float num = 0f;
				foreach (TroopUpgradeArgs possibleUpgrade in possibleUpgrades)
				{
					num += possibleUpgrade.UpgradeChance;
				}
				float num2 = num * MBRandom.RandomFloat;
				foreach (TroopUpgradeArgs possibleUpgrade2 in possibleUpgrades)
				{
					num2 -= possibleUpgrade2.UpgradeChance;
					if (num2 <= 0f)
					{
						result = possibleUpgrade2;
						break;
					}
				}
			}
			return result;
		}

		private List<TroopUpgradeArgs> GetPossibleUpgradeTargets(PartyBase party, TroopRosterElement element)
		{
			PartyWageModel partyWageModel = Campaign.Current.Models.PartyWageModel;
			List<TroopUpgradeArgs> list = new List<TroopUpgradeArgs>();
			CharacterObject character = element.Character;
			int num = element.Number - element.WoundedNumber;
			if (num > 0)
			{
				PartyTroopUpgradeModel partyTroopUpgradeModel = Campaign.Current.Models.PartyTroopUpgradeModel;
				for (int i = 0; i < character.UpgradeTargets.Length; i++)
				{
					num = element.Number - element.WoundedNumber;
					CharacterObject characterObject = character.UpgradeTargets[i];
					int upgradeXpCost = character.GetUpgradeXpCost(party, i);
					if (upgradeXpCost > 0)
					{
						num = TaleWorlds.Library.MathF.Min(num, element.Xp / upgradeXpCost);
						if (num == 0)
						{
							continue;
						}
					}
					if (characterObject.Tier > character.Tier && party.MobileParty.HasLimitedWage() && party.MobileParty.TotalWage + num * (partyWageModel.GetCharacterWage(characterObject) - partyWageModel.GetCharacterWage(character)) > party.MobileParty.PaymentLimit)
					{
						num = TaleWorlds.Library.MathF.Max(0, TaleWorlds.Library.MathF.Min(num, (party.MobileParty.PaymentLimit - party.MobileParty.TotalWage) / (partyWageModel.GetCharacterWage(characterObject) - partyWageModel.GetCharacterWage(character))));
						if (num == 0)
						{
							continue;
						}
					}
					int upgradeGoldCost = character.GetUpgradeGoldCost(party, i);
					if (party.LeaderHero != null && upgradeGoldCost != 0 && num * upgradeGoldCost > party.MobileParty.PartyTradeGold)
					{
						num = party.MobileParty.PartyTradeGold / upgradeGoldCost;
						if (num == 0)
						{
							continue;
						}
					}
					if ((!party.Culture.IsBandit || characterObject.Culture.IsBandit) && (character.Occupation != Occupation.Bandit || partyTroopUpgradeModel.CanPartyUpgradeTroopToTarget(party, character, characterObject)))
					{
						float upgradeChanceForTroopUpgrade = Campaign.Current.Models.PartyTroopUpgradeModel.GetUpgradeChanceForTroopUpgrade(party, character, i);
						list.Add(new TroopUpgradeArgs(character, characterObject, num, upgradeGoldCost, upgradeXpCost, upgradeChanceForTroopUpgrade));
					}
				}
			}
			return list;
		}

		private void ApplyEffects(PartyBase party, TroopUpgradeArgs upgradeArgs)
		{
			if (party.Owner != null && party.Owner.IsAlive)
			{
				SkillLevelingManager.OnUpgradeTroops(party, upgradeArgs.Target, upgradeArgs.UpgradeTarget, upgradeArgs.PossibleUpgradeCount);
				GiveGoldAction.ApplyBetweenCharacters(party.Owner, null, upgradeArgs.UpgradeGoldCost * upgradeArgs.PossibleUpgradeCount, disableNotification: true);
			}
			else if (party.LeaderHero != null && party.LeaderHero.IsAlive)
			{
				SkillLevelingManager.OnUpgradeTroops(party, upgradeArgs.Target, upgradeArgs.UpgradeTarget, upgradeArgs.PossibleUpgradeCount);
				GiveGoldAction.ApplyBetweenCharacters(party.LeaderHero, null, upgradeArgs.UpgradeGoldCost * upgradeArgs.PossibleUpgradeCount, disableNotification: true);
			}
		}

		private void UpgradeTroop(PartyBase party, int rosterIndex, TroopUpgradeArgs upgradeArgs)
		{
			TroopRoster memberRoster = party.MemberRoster;
			CharacterObject upgradeTarget = upgradeArgs.UpgradeTarget;
			int possibleUpgradeCount = upgradeArgs.PossibleUpgradeCount;
			int num = upgradeArgs.UpgradeXpCost * possibleUpgradeCount;
			memberRoster.SetElementXp(rosterIndex, memberRoster.GetElementXp(rosterIndex) - num);
			memberRoster.AddToCounts(upgradeArgs.Target, -possibleUpgradeCount);
			memberRoster.AddToCounts(upgradeTarget, possibleUpgradeCount);
			if (possibleUpgradeCount > 0)
			{
				ApplyEffects(party, upgradeArgs);
			}
		}

		public void UpgradeReadyTroops(PartyBase party)
		{
			if (party == PartyBase.MainParty || !party.IsActive)
			{
				return;
			}
			TroopRoster memberRoster = party.MemberRoster;
			PartyTroopUpgradeModel partyTroopUpgradeModel = Campaign.Current.Models.PartyTroopUpgradeModel;
			for (int i = 0; i < memberRoster.Count; i++)
			{
				TroopRosterElement elementCopyAtIndex = memberRoster.GetElementCopyAtIndex(i);
				if (partyTroopUpgradeModel.IsTroopUpgradeable(party, elementCopyAtIndex.Character))
				{
					List<TroopUpgradeArgs> possibleUpgradeTargets = GetPossibleUpgradeTargets(party, elementCopyAtIndex);
					if (possibleUpgradeTargets.Count > 0)
					{
						TroopUpgradeArgs upgradeArgs = SelectPossibleUpgrade(possibleUpgradeTargets);
						UpgradeTroop(party, i, upgradeArgs);
					}
				}
			}
		}
	}
	public class PatrolPartiesCampaignBehavior : CampaignBehaviorBase, IPatrolPartiesCampaignBehavior
	{
		private const float BasePatrolScore = 1.25f;

		private const float VisitHomeSettlementPartySizeRatioThreshold = 5f;

		private const float VisitHomeSettlementBaseScore = 0.15f;

		private const float ConsiderReplenishPartySizeRatioThreshold = 0.15f;

		private const float BaseReplenishmentChance = 0.005f;

		private Dictionary<Settlement, CampaignTime> _partyGenerationQueue = new Dictionary<Settlement, CampaignTime>();

		private Dictionary<Settlement, CampaignTime> _lastHomeSettlementVisitTimes = new Dictionary<Settlement, CampaignTime>();

		private Dictionary<Settlement, CampaignTime> _lastHomeSettlementVisitTimesCoastal = new Dictionary<Settlement, CampaignTime>();

		private Dictionary<Settlement, CampaignTime> _interactedPatrolParties = new Dictionary<Settlement, CampaignTime>();

		public override void RegisterEvents()
		{
			CampaignEvents.DailyTickSettlementEvent.AddNonSerializedListener(this, DailyTickSettlement);
			CampaignEvents.OnSettlementOwnerChangedEvent.AddNonSerializedListener(this, OnSettlementOwnerChangedEvent);
			CampaignEvents.OnNewGameCreatedPartialFollowUpEvent.AddNonSerializedListener(this, OnNewGameCreated);
			CampaignEvents.AiHourlyTickEvent.AddNonSerializedListener(this, AiHourlyTick);
			CampaignEvents.SettlementEntered.AddNonSerializedListener(this, SettlementEntered);
			CampaignEvents.OnSettlementLeftEvent.AddNonSerializedListener(this, OnSettlementLeft);
			CampaignEvents.MobilePartyDestroyed.AddNonSerializedListener(this, MobilePartyDestroyed);
			CampaignEvents.MobilePartyCreated.AddNonSerializedListener(this, MobilePartyCreated);
			CampaignEvents.HourlyTickPartyEvent.AddNonSerializedListener(this, HourlyTickParty);
			CampaignEvents.OnBuildingLevelChangedEvent.AddNonSerializedListener(this, OnBuildingLevelChanged);
			CampaignEvents.OnSessionLaunchedEvent.AddNonSerializedListener(this, OnSessionLaunched);
		}

		private void OnBuildingLevelChanged(Town town, Building building, int levelChange)
		{
			if (building.BuildingType == DefaultBuildingTypes.SettlementGuardHouse)
			{
				if (building.CurrentLevel == 1 && levelChange > 0 && CanSettlementSpawnNewPartyCurrently(town.Settlement, includeReason: false, out var _))
				{
					UpdateSettlementQueue(town.Settlement, CampaignTime.Zero);
				}
				if (town.Settlement.PatrolParty != null)
				{
					town.Settlement.PatrolParty.Party.MemberRoster.UpdateVersion();
				}
			}
		}

		private void DailyTickSettlement(Settlement settlement)
		{
			if (CanSettlementSpawnNewPartyCurrently(settlement, includeReason: false, out var _))
			{
				if (!_partyGenerationQueue.TryGetValue(settlement, out var value))
				{
					UpdateSettlementQueue(settlement, CampaignTime.Now + Campaign.Current.Models.SettlementPatrolModel.GetPatrolPartySpawnDuration(settlement, naval: false));
				}
				else if (value.IsPast)
				{
					SpawnPatrolParty(settlement);
				}
			}
			else
			{
				UpdateSettlementParties(settlement);
			}
		}

		private void HourlyTickParty(MobileParty mobileParty)
		{
			if (!mobileParty.IsPatrolParty)
			{
				return;
			}
			if (mobileParty.CurrentSettlement == mobileParty.HomeSettlement && !mobileParty.CurrentSettlement.IsUnderSiege && mobileParty.HomeSettlement.Party.MapEvent == null)
			{
				GetLastHomeSettlementVisitTime(mobileParty, out var campaignTime);
				float elapsedHoursUntilNow = campaignTime.ElapsedHoursUntilNow;
				if (MBRandom.RandomFloat < elapsedHoursUntilNow * elapsedHoursUntilNow * 0.005f && mobileParty.PartySizeRatio < 1f)
				{
					ReplenishParty(mobileParty);
				}
			}
			if (mobileParty.CurrentSettlement == null && mobileParty.TargetSettlement == mobileParty.HomeSettlement && mobileParty.DefaultBehavior == AiBehavior.GoToSettlement && !mobileParty.TargetSettlement.IsUnderSiege)
			{
				mobileParty.Ai.SetInitiative(0.1f, 1f, 1f);
			}
		}

		private void ReplenishParty(MobileParty party)
		{
			PartyTemplateObject partyTemplateForPatrolParty = Campaign.Current.Models.SettlementPatrolModel.GetPartyTemplateForPatrolParty(party.CurrentSettlement, party.PatrolPartyComponent.IsNaval);
			TroopRoster troopRoster = Campaign.Current.Models.PartySizeLimitModel.FindAppropriateInitialRosterForMobileParty(party, partyTemplateForPatrolParty);
			party.MemberRoster.Clear();
			party.MemberRoster.Add(troopRoster);
			SortRoster(party);
		}

		private void SortRoster(MobileParty mobileParty)
		{
			mobileParty.PatrolPartyComponent.SortRoster();
		}

		private void OnSessionLaunched(CampaignGameStarter starter)
		{
			AddDialogs(starter);
		}

		private void OnNewGameCreated(CampaignGameStarter starter, int index)
		{
			if (index != 50)
			{
				return;
			}
			foreach (Town allFief in Town.AllFiefs)
			{
				if (CanSettlementSpawnNewPartyCurrently(allFief.Settlement, includeReason: false, out var _))
				{
					SpawnPatrolParty(allFief.Settlement);
				}
			}
		}

		private void AddDialogs(CampaignGameStarter starter)
		{
			starter.AddDialogLine("patrol_talk_start_patrol_party", "start", "patrol_talk_start_1", "{=!}{PATROL_PARTY_GREETING}", patrol_talk_on_condition, patrol_talk_on_consequence);
			starter.AddPlayerLine("patrol_talk_start_enemy_1", "patrol_talk_start_1", "patrol_talk_start_attack", "{=!}{PLAYER_ATTACK_TEXT}", patrol_talk_on_condition_player_is_attacker, null);
			starter.AddPlayerLine("patrol_talk_start_enemy_2", "patrol_talk_start_1", "close_window", "{=5KGuQb5C}We'll see who slays whom here.", patrol_talk_on_condition_player_is_not_attacker, null);
			starter.AddDialogLine("patrol_talk_start_enemy_attack", "patrol_talk_start_attack", "patrol_talk_start_attack_final", "{=dQfha0al}You'll answer to the {?OWNER.GENDER}lady{?}lord{\\?} of {SETTLEMENT_LINK}, then!", patrol_talk_on_condition_enemy_attack, null);
			starter.AddDialogLine("patrol_talk_start_neutral_attack", "patrol_talk_start_attack", "patrol_talk_start_attack_final", "{=dQfha0al}You'll answer to the {?OWNER.GENDER}lady{?}lord{\\?} of {SETTLEMENT_LINK}, then!", patrol_talk_on_condition_non_enemy_attack, null);
			starter.AddPlayerLine("patrol_talk_start_attack_final", "patrol_talk_start_attack_final", "patrol_talk_start_attack_final_response", "{=z7fFBuqt}I'll take that chance. Men, attack!", null, patrol_attack_on_consequence);
			starter.AddPlayerLine("patrol_talk_start_attack_final_decline", "patrol_talk_start_attack_final", "close_window", "{=uJuOTHnb}On second thought, be on your way.", patrol_talk_on_condition_dont_attack, patrol_talk_start_enemy_leave_on_consequence);
			starter.AddDialogLine("patrol_talk_start_attack_final_response", "patrol_talk_start_attack_final_response", "close_window", "{=4VfGEtuS}Curse you!", null, null);
			starter.AddPlayerLine("patrol_talk_start_ask_hideout", "patrol_talk_start_1", "patrol_talk_start_hideout", "{=y6aBcAFF}You might know if any bandits have made their lairs around here, then?", patrol_talk_on_condition_hideout, null);
			starter.AddDialogLine("patrol_talk_hideout", "patrol_talk_start_hideout", "start", "{=!}{HIDEOUT_TEXT}", patrol_talk_hideout_on_condition, null);
			starter.AddPlayerLine("patrol_talk_start_ask_security", "patrol_talk_start_1", "patrol_talk_start_security", "{=!}{SECURITY_QUESTION}", patrol_talk_on_condition_security_start, null);
			starter.AddDialogLine("patrol_talk_security", "patrol_talk_start_security", "start", "{=!}{SECURITY_TEXT}", patrol_talk_on_condition_security, null);
			starter.AddPlayerLine("patrol_talk_start_leave", "patrol_talk_start_1", "close_window", "{=tqh6ydEW}Carry on, then.", patrol_talk_start_enemy_leave_on_condition, patrol_talk_start_enemy_leave_on_consequence);
		}

		private bool patrol_talk_on_condition_dont_attack()
		{
			if (MobileParty.ConversationParty != null && MobileParty.ConversationParty.IsPatrolParty)
			{
				return PlayerEncounter.PlayerIsAttacker;
			}
			return false;
		}

		private bool patrol_talk_start_enemy_leave_on_condition()
		{
			if (MobileParty.ConversationParty != null && MobileParty.ConversationParty.IsPatrolParty)
			{
				if (MobileParty.ConversationParty.MapFaction.IsAtWarWith(MobileParty.MainParty.MapFaction))
				{
					return PlayerEncounter.PlayerIsAttacker;
				}
				return true;
			}
			return false;
		}

		private void patrol_attack_on_consequence()
		{
			BeHostileAction.ApplyEncounterHostileAction(PartyBase.MainParty, MobileParty.ConversationParty.Party);
		}

		private bool patrol_talk_hideout_on_condition()
		{
			TextObject textObject = null;
			textObject = (MobileParty.ConversationParty.MapFaction.IsAtWarWith(MobileParty.MainParty.MapFaction) ? new TextObject("{=IjcuJggo}Listen... We don't want to fight you, but that doesn't mean we should sit here bandying words and passing the time of day.") : (IsThereHideoutNearSettlement(MobileParty.ConversationParty.HomeSettlement) ? new TextObject("{=H0DiZ3fk}We've heard talk that some have holed up a short distance of here. If you could find them and roust them out, you'd be doing us all a service.") : ((!(MobileParty.ConversationParty.HomeSettlement.OwnerClan.Culture.StringId == "nord") && !(MobileParty.ConversationParty.HomeSettlement.OwnerClan.Culture.StringId == "battania")) ? new TextObject("{=PI6kC7Mp}We've heard of none near here, Heaven be praised.") : new TextObject("{=wWYyOARQ}We've heard of none near here, the gods be praised."))));
