	public class PoliticalStagnationAndBorderIncidentCampaignBehavior : CampaignBehaviorBase
	{
		private const float ThreatUpdateTimeThresholdInHours = 3f;

		private Dictionary<Settlement, CampaignTime> _lastUpdateTimePerSettlement;

		public override void RegisterEvents()
		{
			CampaignEvents.DailyTickEvent.AddNonSerializedListener(this, DailyTick);
			CampaignEvents.HourlyTickSettlementEvent.AddNonSerializedListener(this, HourlyTickSettlement);
			CampaignEvents.OnNewGameCreatedPartialFollowUpEndEvent.AddNonSerializedListener(this, NewGameCreated);
			CampaignEvents.OnGameLoadFinishedEvent.AddNonSerializedListener(this, LoadFinished);
		}

		private void LoadFinished()
		{
			if (_lastUpdateTimePerSettlement == null)
			{
				InitializeDictionary();
			}
		}

		private void NewGameCreated(CampaignGameStarter obj)
		{
			InitializeDictionary();
		}

		private void InitializeDictionary()
		{
			_lastUpdateTimePerSettlement = new Dictionary<Settlement, CampaignTime>();
			foreach (Settlement item in Settlement.All)
			{
				if (item.IsFortification || item.IsVillage)
				{
					_lastUpdateTimePerSettlement.Add(item, CampaignTime.Now - CampaignTime.Hours(MBRandom.RandomFloat * 3f));
				}
			}
		}

		public override void SyncData(IDataStore dataStore)
		{
			dataStore.SyncData("_lastUpdateTimePerSettlement", ref _lastUpdateTimePerSettlement);
		}

		public void HourlyTickSettlement(Settlement settlement)
		{
			if (_lastUpdateTimePerSettlement.ContainsKey(settlement) && _lastUpdateTimePerSettlement[settlement].ElapsedHoursUntilNow > 3f)
			{
				UpdateNearbyValues(settlement, isCheckingNavalValues: false);
				settlement.NearbyLandThreatIntensity *= 0.85f;
				settlement.NearbyLandAllyIntensity *= 0.8f;
				if (settlement.HasPort)
				{
					UpdateNearbyValues(settlement, isCheckingNavalValues: true);
					settlement.NearbyNavalThreatIntensity *= 0.85f;
					settlement.NearbyNavalAllyIntensity *= 0.8f;
				}
				_lastUpdateTimePerSettlement[settlement] = CampaignTime.Now;
			}
		}

		private void UpdateNearbyValues(Settlement settlement, bool isCheckingNavalValues)
		{
			float settlementNearbyThreatAndAllyCheckRadius = Campaign.Current.Models.MobilePartyAIModel.GetSettlementNearbyThreatAndAllyCheckRadius(settlement, isCheckingNavalValues);
			LocatableSearchData<MobileParty> data = MobileParty.StartFindingLocatablesAroundPosition((isCheckingNavalValues ? settlement.PortPosition : settlement.GatePosition).ToVec2(), settlementNearbyThreatAndAllyCheckRadius);
			for (MobileParty mobileParty = MobileParty.FindNextLocatable(ref data); mobileParty != null; mobileParty = MobileParty.FindNextLocatable(ref data))
			{
				if (!mobileParty.IsGarrison && !mobileParty.IsMilitia && mobileParty.IsActive)
				{
					if (mobileParty.Ai.IsAlerted && mobileParty.MapFaction == settlement.MapFaction && (mobileParty.IsCaravan || mobileParty.IsVillager))
					{
						if (mobileParty.IsCurrentlyAtSea && isCheckingNavalValues)
						{
							settlement.NearbyNavalThreatIntensity += 0.6f;
						}
						else if (!isCheckingNavalValues)
						{
							settlement.NearbyLandThreatIntensity += 0.6f;
						}
					}
					if (mobileParty.Aggressiveness > 0f)
					{
						if (mobileParty.CurrentSettlement == null && mobileParty.Army == null && (mobileParty.IsBandit || FactionManager.IsAtWarAgainstFaction(mobileParty.MapFaction, settlement.MapFaction)))
						{
							float threatValueOfEnemyToSettlement = GetThreatValueOfEnemyToSettlement(mobileParty, settlement);
							if (mobileParty.IsCurrentlyAtSea && isCheckingNavalValues)
							{
								settlement.NearbyNavalThreatIntensity += threatValueOfEnemyToSettlement * 3f;
							}
							else if (!isCheckingNavalValues)
							{
								settlement.NearbyLandThreatIntensity += threatValueOfEnemyToSettlement * 3f;
							}
						}
						else if (mobileParty.MapFaction == settlement.MapFaction)
						{
							bool flag = mobileParty.DefaultBehavior == AiBehavior.PatrolAroundPoint && !mobileParty.TargetPosition.IsOnLand;
							float num = GetThreatValueOfParty(mobileParty);
							if (flag)
							{
								num *= 0.5f;
							}
							if ((mobileParty.IsCurrentlyAtSea || flag) && isCheckingNavalValues)
							{
								settlement.NearbyNavalAllyIntensity += num * 3f;
							}
							else if (!isCheckingNavalValues)
							{
								settlement.NearbyLandAllyIntensity += num * 3f;
							}
						}
					}
				}
			}
		}

		private float GetThreatValueOfParty(MobileParty mobileParty)
		{
			return TaleWorlds.Library.MathF.Min(1f, mobileParty.Party.EstimatedStrength / 400f * TaleWorlds.Library.MathF.Min(1f, mobileParty.Aggressiveness));
		}

		private float GetThreatValueOfEnemyToSettlement(MobileParty mobileParty, Settlement settlement)
		{
			float num = GetThreatValueOfParty(mobileParty);
			if (mobileParty == MobileParty.MainParty)
			{
				num *= 2f;
			}
			if (!mobileParty.IsLordParty)
			{
				num *= 0.5f;
			}
			if (mobileParty.DefaultBehavior == AiBehavior.PatrolAroundPoint && mobileParty.TargetSettlement == settlement)
			{
				num *= 2f;
			}
			if (mobileParty.MapEvent != null && mobileParty.MapEvent.IsFieldBattle)
			{
				num = 3f * num;
			}
			return num;
		}

		public void DailyTick()
		{
			foreach (Kingdom item in Kingdom.All)
			{
				UpdatePoliticallyStagnation(item);
			}
		}

		private static void UpdatePoliticallyStagnation(Kingdom kingdom)
		{
			float num = 1f + (float)TaleWorlds.Library.MathF.Min(60, kingdom.Fiefs.Count) * 0.2f;
			float num2 = 2f + (float)TaleWorlds.Library.MathF.Min(60, kingdom.Fiefs.Count) * 0.6f;
			int num3 = 1;
			foreach (Kingdom item in Kingdom.All)
			{
				if (FactionManager.IsAtWarAgainstFaction(kingdom, item))
				{
					if ((float)item.Fiefs.Count >= num2)
					{
						num3 = -2;
						break;
					}
					if ((float)item.Fiefs.Count >= num)
					{
						num3 = -1;
					}
				}
			}
			kingdom.PoliticalStagnation += num3;
			if (kingdom.PoliticalStagnation < 0)
			{
				kingdom.PoliticalStagnation = 0;
			}
			else if (kingdom.PoliticalStagnation > 300)
			{
				kingdom.PoliticalStagnation = 300;
			}
		}
	}
	public class PregnancyCampaignBehavior : CampaignBehaviorBase
	{
		public class PregnancyCampaignBehaviorTypeDefiner : SaveableTypeDefiner
		{
			public PregnancyCampaignBehaviorTypeDefiner()
				: base(110000)
			{
			}

			protected override void DefineClassTypes()
			{
				AddClassDefinition(typeof(Pregnancy), 2);
			}

			protected override void DefineContainerDefinitions()
			{
				ConstructContainerDefinition(typeof(List<Pregnancy>));
			}
		}

		internal class Pregnancy
		{
			[SaveableField(1)]
			public readonly Hero Mother;

			[SaveableField(2)]
			public readonly Hero Father;

			[SaveableField(3)]
			public readonly CampaignTime DueDate;

			public Pregnancy(Hero pregnantHero, Hero father, CampaignTime dueDate)
			{
				Mother = pregnantHero;
				Father = father;
				DueDate = dueDate;
			}

			internal static void AutoGeneratedStaticCollectObjectsPregnancy(object o, List<object> collectedObjects)
			{
				((Pregnancy)o).AutoGeneratedInstanceCollectObjects(collectedObjects);
			}

			protected virtual void AutoGeneratedInstanceCollectObjects(List<object> collectedObjects)
			{
				collectedObjects.Add(Mother);
				collectedObjects.Add(Father);
				CampaignTime.AutoGeneratedStaticCollectObjectsCampaignTime(DueDate, collectedObjects);
			}

			internal static object AutoGeneratedGetMemberValueMother(object o)
			{
				return ((Pregnancy)o).Mother;
			}

			internal static object AutoGeneratedGetMemberValueFather(object o)
			{
				return ((Pregnancy)o).Father;
			}

			internal static object AutoGeneratedGetMemberValueDueDate(object o)
			{
				return ((Pregnancy)o).DueDate;
			}
		}

		private List<Pregnancy> _heroPregnancies = new List<Pregnancy>();

		public override void RegisterEvents()
		{
			CampaignEvents.HeroKilledEvent.AddNonSerializedListener(this, OnHeroKilled);
			CampaignEvents.DailyTickHeroEvent.AddNonSerializedListener(this, DailyTickHero);
			CampaignEvents.OnChildConceivedEvent.AddNonSerializedListener(this, ChildConceived);
		}

		private void DailyTickHero(Hero hero)
		{
			if (hero.IsFemale && !CampaignOptions.IsLifeDeathCycleDisabled && hero.IsAlive && hero.Age > (float)Campaign.Current.Models.AgeModel.HeroComesOfAge && (hero.Clan == null || !hero.Clan.IsRebelClan))
			{
				if (hero.Age > (float)Campaign.Current.Models.AgeModel.HeroComesOfAge && hero.Spouse != null && hero.Spouse.IsAlive && !hero.IsPregnant)
				{
					RefreshSpouseVisit(hero);
				}
				if (hero.IsPregnant)
				{
					CheckOffspringsToDeliver(hero);
				}
			}
		}

		private void CheckOffspringsToDeliver(Hero hero)
		{
			Pregnancy pregnancy = _heroPregnancies.Find((Pregnancy x) => x.Mother == hero);
			if (pregnancy == null)
			{
				hero.IsPregnant = false;
			}
			else
			{
				CheckOffspringToDeliver(pregnancy);
			}
		}

		private void RefreshSpouseVisit(Hero hero)
		{
			if (CheckAreNearby(hero, hero.Spouse) && MBRandom.RandomFloat <= Campaign.Current.Models.PregnancyModel.GetDailyChanceOfPregnancyForHero(hero))
			{
				MakePregnantAction.Apply(hero);
			}
		}

		private bool CheckAreNearby(Hero hero, Hero spouse)
		{
			GetLocation(hero, out var heroSettlement, out var heroParty);
			GetLocation(spouse, out var heroSettlement2, out var heroParty2);
			if ((heroSettlement != null && heroSettlement == heroSettlement2) || (heroParty != null && heroParty == heroParty2))
			{
				return true;
			}
			if (hero.Clan != Hero.MainHero.Clan && MBRandom.RandomFloat < 0.2f)
			{
				return true;
			}
			return false;
		}

		private void GetLocation(Hero hero, out Settlement heroSettlement, out MobileParty heroParty)
		{
			heroSettlement = hero.CurrentSettlement;
			heroParty = hero.PartyBelongedTo;
			if (heroParty?.AttachedTo != null)
			{
				heroParty = heroParty.AttachedTo;
			}
			if (heroSettlement == null)
			{
				heroSettlement = heroParty?.CurrentSettlement;
			}
		}

		private void CheckOffspringToDeliver(Pregnancy pregnancy)
		{
			PregnancyModel pregnancyModel = Campaign.Current.Models.PregnancyModel;
			if (pregnancy.DueDate.IsFuture || !pregnancy.Mother.IsAlive)
			{
				return;
			}
			Hero mother = pregnancy.Mother;
			bool num = MBRandom.RandomFloat <= pregnancyModel.DeliveringTwinsProbability;
			List<Hero> list = new List<Hero>();
			int num2 = ((!num) ? 1 : 2);
			int num3 = 0;
			for (int i = 0; i < num2; i++)
			{
				if (!(MBRandom.RandomFloat <= pregnancyModel.StillbirthProbability))
				{
					bool isOffspringFemale = MBRandom.RandomFloat <= pregnancyModel.DeliveringFemaleOffspringProbability;
					Hero item = HeroCreator.DeliverOffSpring(mother, pregnancy.Father, isOffspringFemale);
					list.Add(item);
				}
				else
				{
					TextObject textObject = new TextObject("{=pw4cUPEn}{MOTHER.LINK} has delivered stillborn.");
					StringHelpers.SetCharacterProperties("MOTHER", mother.CharacterObject, textObject);
					InformationManager.DisplayMessage(new InformationMessage(textObject.ToString()));
					num3++;
				}
			}
			CampaignEventDispatcher.Instance.OnGivenBirth(mother, list, num3);
			mother.IsPregnant = false;
			_heroPregnancies.Remove(pregnancy);
			if (mother != Hero.MainHero && MBRandom.RandomFloat <= pregnancyModel.MaternalMortalityProbabilityInLabor)
			{
				KillCharacterAction.ApplyInLabor(mother);
			}
		}

		private void ChildConceived(Hero mother)
		{
			_heroPregnancies.Add(new Pregnancy(mother, mother.Spouse, CampaignTime.DaysFromNow(Campaign.Current.Models.PregnancyModel.PregnancyDurationInDays)));
		}

		public void OnHeroKilled(Hero victim, Hero killer, KillCharacterAction.KillCharacterActionDetail detail, bool showNotification)
		{
			if (victim.IsFemale && _heroPregnancies.Any((Pregnancy pregnancy) => pregnancy.Mother == victim))
			{
				_heroPregnancies.RemoveAll((Pregnancy pregnancy) => pregnancy.Mother == victim);
			}
		}

		public override void SyncData(IDataStore dataStore)
		{
			dataStore.SyncData("_heroPregnancies", ref _heroPregnancies);
		}
	}
	public class PrisonerCaptureCampaignBehavior : CampaignBehaviorBase
	{
		public override void RegisterEvents()
		{
			CampaignEvents.OnSettlementOwnerChangedEvent.AddNonSerializedListener(this, OnSettlementOwnerChanged);
			CampaignEvents.WarDeclared.AddNonSerializedListener(this, OnWarDeclared);
			CampaignEvents.OnClanChangedKingdomEvent.AddNonSerializedListener(this, OnClanChangedKingdom);
		}

		public override void SyncData(IDataStore dataStore)
		{
		}

		private void OnClanChangedKingdom(Clan clan, Kingdom oldKingdom, Kingdom newKingdom, ChangeKingdomAction.ChangeKingdomActionDetail detail, bool showNotification)
		{
			for (int i = 0; i < clan.Settlements.Count; i++)
			{
				Settlement settlement = clan.Settlements[i];
				if (settlement.IsFortification)
				{
					HandleSettlementHeroes(settlement);
				}
			}
		}

		private void OnWarDeclared(IFaction faction1, IFaction faction2, DeclareWarAction.DeclareWarDetail detail)
		{
			for (int i = 0; i < faction1.Settlements.Count; i++)
			{
				Settlement settlement = faction1.Settlements[i];
				if (settlement.IsFortification)
				{
					HandleSettlementHeroes(settlement);
				}
			}
			for (int j = 0; j < faction2.Settlements.Count; j++)
			{
				Settlement settlement2 = faction2.Settlements[j];
				if (settlement2.IsFortification)
				{
					HandleSettlementHeroes(settlement2);
				}
			}
		}

		private void OnSettlementOwnerChanged(Settlement settlement, bool openToClaim, Hero newOwner, Hero oldOwner, Hero capturerHero, ChangeOwnerOfSettlementAction.ChangeOwnerOfSettlementDetail detail)
		{
			if (settlement.IsFortification)
			{
				HandleSettlementHeroes(settlement);
			}
		}

		private void HandleSettlementHeroes(Settlement settlement)
		{
			for (int num = settlement.HeroesWithoutParty.Count - 1; num >= 0; num--)
			{
				Hero hero = settlement.HeroesWithoutParty[num];
				if (SettlementHeroCaptureCommonCondition(hero))
				{
					TakePrisonerAction.Apply(hero.CurrentSettlement.Party, hero);
				}
			}
			for (int num2 = settlement.Parties.Count - 1; num2 >= 0; num2--)
			{
				MobileParty mobileParty = settlement.Parties[num2];
				if (mobileParty.IsLordParty && (mobileParty.Army == null || (mobileParty.Army != null && mobileParty.Army.LeaderParty == mobileParty && !mobileParty.Army.Parties.Contains(MobileParty.MainParty))) && mobileParty.MapEvent == null && SettlementHeroCaptureCommonCondition(mobileParty.LeaderHero))
				{
					LeaveSettlementAction.ApplyForParty(mobileParty);
				}
			}
		}

		private bool SettlementHeroCaptureCommonCondition(Hero hero)
		{
			if (hero != null && hero != Hero.MainHero && !hero.IsWanderer && !hero.IsNotable && hero.HeroState != Hero.CharacterStates.Prisoner && hero.HeroState != Hero.CharacterStates.Dead && hero.MapFaction != null && hero.CurrentSettlement != null)
			{
				return hero.MapFaction.IsAtWarWith(hero.CurrentSettlement.MapFaction);
			}
			return false;
		}
	}
	public class PrisonerRecruitCampaignBehavior : CampaignBehaviorBase
	{
		private Dictionary<CharacterObject, float> PrisonerTalkRecords = new Dictionary<CharacterObject, float>();

		public override void RegisterEvents()
		{
			CampaignEvents.OnSessionLaunchedEvent.AddNonSerializedListener(this, OnSessionLaunched);
		}

		public override void SyncData(IDataStore dataStore)
		{
			dataStore.SyncData("PrisonerTalkRecords", ref PrisonerTalkRecords);
		}

		public void OnSessionLaunched(CampaignGameStarter campaignGameStarter)
		{
			AddDialogs(campaignGameStarter);
		}

		protected void AddDialogs(CampaignGameStarter campaignGameStarter)
		{
			campaignGameStarter.AddDialogLine("conversation_prisoner_chat_start", "start", "prisoner_recruit_start_player", "{=k7ebznzr}Yes?", conversation_prisoner_chat_start_on_condition, null);
			campaignGameStarter.AddPlayerLine("conversation_prisoner_chat_player", "prisoner_recruit_start_player", "prisoner_recruit_start_response", "{=ksZXyDJG}Don't do anything stupid, like trying to run away. I will be watching you.", null, null);
			campaignGameStarter.AddDialogLine("conversation_prisoner_chat_response", "prisoner_recruit_start_response", "close_window", "{=Oe1bTJp6}No, I swear I won't.", null, null);
			campaignGameStarter.AddDialogLine("conversation_prisoner_recruit_start_1", "start", "prisoner_recruit_start", "{=!}I'm going to take a chance on you, to give you a chance to walk free, if you like.", conversation_prisoner_recruit_start_on_condition, null);
			campaignGameStarter.AddPlayerLine("conversation_prisoner_recruit_start", "prisoner_recruit_start", "prisoner_recruit", "{=!}Are you willing to join us? To fight alongside us?", null, null);
			campaignGameStarter.AddDialogLine("prisoner_recruit_1", "prisoner_recruit", "close_window", "{=!}Aye. I would do that.", conversation_prisoner_recruit_on_condition, null);
			campaignGameStarter.AddDialogLine("prisoner_recruit_2", "prisoner_recruit", "close_window", "{=!}No. I'm no traitor.", conversation_prisoner_recruit_no_on_condition, null);
			campaignGameStarter.AddDialogLine("prisoner_recruit_3", "prisoner_recruit", "close_window", "{=!}You heard me the first time. You know where to stick your offer.", null, null);
		}

		private bool conversation_prisoner_chat_start_on_condition()
		{
			bool flag = (CharacterObject.OneToOneConversationCharacter.IsHero && (Hero.OneToOneConversationHero.PartyBelongedTo == null || !Hero.OneToOneConversationHero.PartyBelongedTo.IsActive)) || (CharacterObject.OneToOneConversationCharacter.Occupation != Occupation.PrisonGuard && CharacterObject.OneToOneConversationCharacter.Occupation != Occupation.Guard && CharacterObject.OneToOneConversationCharacter.Occupation != Occupation.CaravanGuard && MobileParty.ConversationParty != null && MobileParty.ConversationParty.IsMainParty);
			return MobileParty.MainParty.PrisonRoster.Contains(CharacterObject.OneToOneConversationCharacter) && flag;
		}

		private bool conversation_prisoner_recruit_start_on_condition()
		{
			bool flag = !CharacterObject.OneToOneConversationCharacter.IsHero && CharacterObject.OneToOneConversationCharacter.Occupation != Occupation.PrisonGuard && CharacterObject.OneToOneConversationCharacter.Occupation != Occupation.Guard && CharacterObject.OneToOneConversationCharacter.Occupation != Occupation.CaravanGuard && MobileParty.ConversationParty != null && MobileParty.ConversationParty.IsMainParty;
			bool num = MobileParty.MainParty.PrisonRoster.Contains(CharacterObject.OneToOneConversationCharacter);
			if (num && !PrisonerTalkRecords.ContainsKey(CharacterObject.OneToOneConversationCharacter))
			{
				PrisonerTalkRecords.Add(CharacterObject.OneToOneConversationCharacter, -1f);
			}
			return num && flag;
		}

		public bool conversation_prisoner_recruit_on_condition()
		{
			bool flag = false;
			if (PrisonerTalkRecords.TryGetValue(CharacterObject.OneToOneConversationCharacter, out var value) && (value < 0f || Campaign.CurrentTime - value >= 5f))
			{
				flag = MBRandom.RandomInt(MBMath.ClampInt(150 - CharacterObject.PlayerCharacter.GetSkillValue(DefaultSkills.Steward), 1, 150)) < 30;
				if (flag)
				{
					PrisonerTalkRecords.Remove(CharacterObject.OneToOneConversationCharacter);
					int num = MobileParty.MainParty.PrisonRoster.FindIndexOfTroop(CharacterObject.OneToOneConversationCharacter);
					if (num != -1)
					{
						TroopRosterElement elementCopyAtIndex = MobileParty.MainParty.PrisonRoster.GetElementCopyAtIndex(num);
						MobileParty.MainParty.PrisonRoster.AddToCounts(elementCopyAtIndex.Character, -elementCopyAtIndex.Number);
						MobileParty.MainParty.MemberRoster.AddToCounts(elementCopyAtIndex.Character, elementCopyAtIndex.Number);
					}
				}
			}
			return flag;
		}

		public bool conversation_prisoner_recruit_no_on_condition()
		{
			bool result = false;
			if (PrisonerTalkRecords.TryGetValue(CharacterObject.OneToOneConversationCharacter, out var value) && value < 0f)
			{
				PrisonerTalkRecords[CharacterObject.OneToOneConversationCharacter] = Campaign.CurrentTime;
				result = true;
			}
			return result;
		}
	}
	public class PrisonerReleaseCampaignBehavior : CampaignBehaviorBase
	{
		public override void RegisterEvents()
		{
			CampaignEvents.OnGameLoadedEvent.AddNonSerializedListener(this, OnGameLoaded);
			CampaignEvents.DailyTickHeroEvent.AddNonSerializedListener(this, DailyHeroTick);
			CampaignEvents.HourlyTickPartyEvent.AddNonSerializedListener(this, HourlyPartyTick);
			CampaignEvents.MakePeace.AddNonSerializedListener(this, OnMakePeaceEvent);
			CampaignEvents.OnClanChangedKingdomEvent.AddNonSerializedListener(this, ClanChangedKingdom);
			CampaignEvents.OnSettlementOwnerChangedEvent.AddNonSerializedListener(this, OnSettlementOwnerChanged);
		}

		private void OnGameLoaded(CampaignGameStarter campaignGameStarter)
		{
			if (!MBSaveLoad.IsUpdatingGameVersion || !(MBSaveLoad.LastLoadedGameVersion < ApplicationVersion.FromString("v1.2.0")))
			{
				return;
			}
			foreach (Hero allAliveHero in Hero.AllAliveHeroes)
			{
				if (allAliveHero == Hero.MainHero)
				{
					continue;
				}
				if (allAliveHero.IsPrisoner)
				{
					bool flag = allAliveHero.PartyBelongedToAsPrisoner != null && allAliveHero.PartyBelongedToAsPrisoner.IsMobile && allAliveHero.PartyBelongedToAsPrisoner.MobileParty.IsMilitia;
					bool flag2 = allAliveHero.PartyBelongedToAsPrisoner != null && !allAliveHero.PartyBelongedToAsPrisoner.MapFaction.IsAtWarWith(allAliveHero.MapFaction);
					if (allAliveHero.PartyBelongedToAsPrisoner == null)
					{
						if (allAliveHero.CurrentSettlement == null)
						{
							MakeHeroFugitiveAction.Apply(allAliveHero);
						}
					}
					else if (flag || flag2)
					{
						EndCaptivityAction.ApplyByEscape(allAliveHero);
						MakeHeroFugitiveAction.Apply(allAliveHero);
					}
				}
				else if (allAliveHero.PartyBelongedToAsPrisoner != null)
				{
					allAliveHero.PartyBelongedToAsPrisoner.PrisonRoster.RemoveTroop(allAliveHero.CharacterObject);
					MakeHeroFugitiveAction.Apply(allAliveHero);
				}
			}
		}

		private void ClanChangedKingdom(Clan clan, Kingdom oldKingdom, Kingdom newKingdom, ChangeKingdomAction.ChangeKingdomActionDetail detail, bool showNotification = true)
		{
			if (detail == ChangeKingdomAction.ChangeKingdomActionDetail.CreateKingdom)
			{
				return;
			}
			ReleasePrisonersInternal(clan);
			if (oldKingdom != null)
			{
				ReleasePrisonersInternal(oldKingdom);
				foreach (IFaction item in oldKingdom.FactionsAtWarWith)
				{
					ReleasePrisonersInternal(item);
				}
			}
			if (newKingdom != null)
			{
				OnAfterClanJoinedKingdom(clan, newKingdom);
				ReleasePrisonersInternal(newKingdom);
			}
		}

		private void OnAfterClanJoinedKingdom(Clan clan, Kingdom newKingdom)
		{
			foreach (Kingdom item in Kingdom.All)
			{
				if (item != newKingdom && item.IsAtWarWith(clan) && !item.IsAtWarWith(newKingdom))
				{
					OnMakePeace(clan, item);
				}
			}
		}

		private void OnMakePeaceEvent(IFaction side1Faction, IFaction side2Faction, MakePeaceAction.MakePeaceDetail detail)
		{
			OnMakePeace(side1Faction, side2Faction);
		}

		private void OnMakePeace(IFaction side1Faction, IFaction side2Faction)
		{
			ReleasePrisonersInternal(side1Faction);
			ReleasePrisonersInternal(side2Faction);
		}

		private static void ReleasePrisonersInternal(IFaction faction)
		{
			foreach (Settlement settlement in faction.Settlements)
			{
				for (int num = settlement.Party.PrisonRoster.Count - 1; num >= 0; num--)
				{
					if (settlement.Party.PrisonRoster.GetElementNumber(num) > 0)
					{
						TroopRosterElement elementCopyAtIndex = settlement.Party.PrisonRoster.GetElementCopyAtIndex(num);
						if (elementCopyAtIndex.Character.IsHero && elementCopyAtIndex.Character.HeroObject != Hero.MainHero && !elementCopyAtIndex.Character.HeroObject.MapFaction.IsAtWarWith(faction.MapFaction))
						{
							EndCaptivityAction.ApplyByPeace(elementCopyAtIndex.Character.HeroObject);
							CampaignEventDispatcher.Instance.OnPrisonersChangeInSettlement(settlement, null, elementCopyAtIndex.Character.HeroObject, takenFromDungeon: true);
						}
					}
				}
			}
			Clan clan = ((faction.IsClan || faction.IsMinorFaction) ? ((Clan)faction) : null);
			Kingdom kingdom = (faction.IsKingdomFaction ? ((Kingdom)faction) : null);
			if (clan != null)
			{
				ReleasePrisonersForClan(clan, faction);
			}
			else
			{
				if (kingdom == null)
				{
					return;
				}
				foreach (Clan clan2 in kingdom.Clans)
				{
					ReleasePrisonersForClan(clan2, faction);
				}
			}
		}

		private static void ReleasePrisonersForClan(Clan clan, IFaction faction)
		{
			foreach (Hero aliveLord in clan.AliveLords)
			{
				foreach (CaravanPartyComponent ownedCaravan in aliveLord.OwnedCaravans)
				{
					ReleasePartyPrisoners(ownedCaravan.MobileParty, faction);
				}
			}
			foreach (Hero companion in clan.Companions)
			{
				foreach (CaravanPartyComponent ownedCaravan2 in companion.OwnedCaravans)
				{
					ReleasePartyPrisoners(ownedCaravan2.MobileParty, faction);
				}
			}
			foreach (WarPartyComponent warPartyComponent in clan.WarPartyComponents)
			{
				ReleasePartyPrisoners(warPartyComponent.MobileParty, faction);
			}
			foreach (Settlement settlement in clan.Settlements)
			{
				if (settlement.IsVillage && settlement.Village.VillagerPartyComponent != null)
				{
					ReleasePartyPrisoners(settlement.Village.VillagerPartyComponent.MobileParty, faction);
				}
				else if ((settlement.IsCastle || settlement.IsTown) && settlement.Town.GarrisonParty != null)
				{
					ReleasePartyPrisoners(settlement.Town.GarrisonParty, faction);
				}
			}
		}

		private static void ReleasePartyPrisoners(MobileParty mobileParty, IFaction faction)
		{
			for (int num = mobileParty.PrisonRoster.Count - 1; num >= 0; num--)
			{
				if (mobileParty.Party.PrisonRoster.GetElementNumber(num) > 0)
				{
					TroopRosterElement elementCopyAtIndex = mobileParty.Party.PrisonRoster.GetElementCopyAtIndex(num);
					if (elementCopyAtIndex.Character.IsHero && elementCopyAtIndex.Character.HeroObject != Hero.MainHero && !elementCopyAtIndex.Character.HeroObject.MapFaction.IsAtWarWith(faction.MapFaction))
					{
						if (elementCopyAtIndex.Character.HeroObject.PartyBelongedToAsPrisoner == mobileParty.Party)
						{
							EndCaptivityAction.ApplyByPeace(elementCopyAtIndex.Character.HeroObject);
						}
						else
						{
							mobileParty.Party.PrisonRoster.RemoveTroop(elementCopyAtIndex.Character);
						}
					}
				}
			}
		}

		public override void SyncData(IDataStore dataStore)
		{
		}

		private void DailyHeroTick(Hero hero)
		{
			if (!hero.IsPrisoner || hero.PartyBelongedToAsPrisoner == null || hero == Hero.MainHero)
			{
				return;
			}
			float num = 0.04f;
			if (hero.PartyBelongedToAsPrisoner.IsMobile && hero.PartyBelongedToAsPrisoner.MobileParty.CurrentSettlement == null)
			{
				num *= 5f - TaleWorlds.Library.MathF.Pow(TaleWorlds.Library.MathF.Min(81, hero.PartyBelongedToAsPrisoner.NumberOfHealthyMembers), 0.25f);
			}
			if (hero.PartyBelongedToAsPrisoner == PartyBase.MainParty || (hero.PartyBelongedToAsPrisoner.IsSettlement && hero.PartyBelongedToAsPrisoner.Settlement.OwnerClan == Clan.PlayerClan) || (hero.PartyBelongedToAsPrisoner.IsMobile && hero.PartyBelongedToAsPrisoner.MobileParty.CurrentSettlement != null && hero.PartyBelongedToAsPrisoner.MobileParty.CurrentSettlement.OwnerClan == Clan.PlayerClan))
			{
				num *= 0.5f;
			}
			ExplainedNumber stat = new ExplainedNumber(num);
			if (hero.PartyBelongedToAsPrisoner.IsSettlement && hero.PartyBelongedToAsPrisoner.Settlement.Town != null && hero.PartyBelongedToAsPrisoner.Settlement.Town.Governor != null)
			{
				Town town = hero.PartyBelongedToAsPrisoner.Settlement.Town;
				if (hero.PartyBelongedToAsPrisoner.Settlement.IsTown || hero.PartyBelongedToAsPrisoner.Settlement.IsCastle)
				{
					if (town.Governor.GetPerkValue(DefaultPerks.Roguery.SweetTalker))
					{
						stat.AddFactor(DefaultPerks.Roguery.SweetTalker.SecondaryBonus, DefaultPerks.Roguery.SweetTalker.Description);
					}
					if (town.Governor.GetPerkValue(DefaultPerks.Engineering.DungeonArchitect))
					{
						stat.AddFactor(DefaultPerks.Engineering.DungeonArchitect.SecondaryBonus, DefaultPerks.Engineering.DungeonArchitect.Description);
					}
					if (town.Governor.GetPerkValue(DefaultPerks.Riding.MountedPatrols))
					{
						stat.AddFactor(DefaultPerks.Riding.MountedPatrols.SecondaryBonus, DefaultPerks.Riding.MountedPatrols.Description);
					}
				}
			}
			if (hero.PartyBelongedToAsPrisoner.IsMobile)
			{
				if (hero.GetPerkValue(DefaultPerks.Roguery.FleetFooted))
				{
					stat.AddFactor(DefaultPerks.Roguery.FleetFooted.SecondaryBonus);
				}
				if (hero.PartyBelongedToAsPrisoner.MobileParty.HasPerk(DefaultPerks.Riding.MountedPatrols))
				{
					PerkHelper.AddPerkBonusForParty(DefaultPerks.Riding.MountedPatrols, hero.PartyBelongedToAsPrisoner.MobileParty, isPrimaryBonus: true, ref stat);
				}
				if (hero.PartyBelongedToAsPrisoner.MobileParty.HasPerk(DefaultPerks.Roguery.RansomBroker))
				{
					PerkHelper.AddPerkBonusForParty(DefaultPerks.Roguery.RansomBroker, hero.PartyBelongedToAsPrisoner.MobileParty, isPrimaryBonus: false, ref stat);
				}
			}
			if (hero.PartyBelongedToAsPrisoner.IsMobile && !hero.PartyBelongedToAsPrisoner.MobileParty.IsCurrentlyAtSea)
			{
				PerkHelper.AddPerkBonusForParty(DefaultPerks.Scouting.KeenSight, hero.PartyBelongedToAsPrisoner.MobileParty, isPrimaryBonus: false, ref stat);
			}
			if (MBRandom.RandomFloat < stat.ResultNumber)
			{
				EndCaptivityAction.ApplyByEscape(hero);
			}
		}

		private void HourlyPartyTick(MobileParty mobileParty)
		{
			int prisonerSizeLimit = mobileParty.Party.PrisonerSizeLimit;
			if (mobileParty.MapEvent != null || mobileParty.SiegeEvent != null || mobileParty.PrisonRoster.TotalManCount <= prisonerSizeLimit)
			{
				return;
			}
			int num = mobileParty.PrisonRoster.TotalManCount - prisonerSizeLimit;
			for (int i = 0; i < num; i++)
			{
				bool flag = mobileParty.PrisonRoster.TotalRegulars > 0;
				float randomFloat = MBRandom.RandomFloat;
				int num2 = (flag ? ((int)((float)mobileParty.PrisonRoster.TotalRegulars * randomFloat)) : ((int)((float)mobileParty.PrisonRoster.TotalManCount * randomFloat)));
				CharacterObject character = null;
				foreach (TroopRosterElement item in mobileParty.PrisonRoster.GetTroopRoster())
				{
					if (!item.Character.IsHero || !flag)
					{
						num2 -= item.Number;
						if (num2 <= 0)
						{
							character = item.Character;
							break;
						}
					}
				}
				ApplyEscapeChanceToExceededPrisoners(character, mobileParty);
			}
		}

		private void ApplyEscapeChanceToExceededPrisoners(CharacterObject character, MobileParty capturerParty)
		{
			ExplainedNumber explainedNumber = new ExplainedNumber(0.1f);
			if (!capturerParty.IsCurrentlyAtSea && capturerParty.HasPerk(DefaultPerks.Athletics.Stamina, checkSecondaryRole: true))
			{
				explainedNumber.AddFactor(-0.1f, DefaultPerks.Athletics.Stamina.Name);
			}
			if (!capturerParty.IsGarrison && !capturerParty.IsMilitia && !character.IsPlayerCharacter && MBRandom.RandomFloat < explainedNumber.ResultNumber)
			{
				if (character.IsHero)
				{
					EndCaptivityAction.ApplyByEscape(character.HeroObject);
				}
				else
				{
					capturerParty.PrisonRoster.AddToCounts(character, -1);
				}
			}
		}

		private void OnSettlementOwnerChanged(Settlement settlement, bool openToClaim, Hero newOwner, Hero oldOwner, Hero capturerHero, ChangeOwnerOfSettlementAction.ChangeOwnerOfSettlementDetail detail)
		{
			foreach (TroopRosterElement item in settlement.Party.PrisonRoster.GetTroopRoster())
			{
				if (item.Character.IsHero && item.Character.HeroObject != Hero.MainHero && !item.Character.HeroObject.MapFaction.IsAtWarWith(settlement.MapFaction))
				{
					if (item.Character.HeroObject.PartyBelongedToAsPrisoner == settlement.Party && item.Character.HeroObject.IsPrisoner)
					{
						EndCaptivityAction.ApplyByReleasedAfterBattle(item.Character.HeroObject);
					}
					else
					{
						settlement.Party.PrisonRoster.RemoveTroop(item.Character, item.Number);
					}
				}
			}
		}
	}
	public class RansomOfferCampaignBehavior : CampaignBehaviorBase
	{
		private const float RansomOfferInitialChance = 0.2f;

		private const float RansomOfferChanceAfterRefusal = 0.12f;

		private const float RansomOfferChanceForPrisonersKeptByAI = 0.1f;

		private const float MapNotificationAutoDeclineDurationInDays = 2f;

		private const int AmountOfGoldLeftAfterRansom = 1000;

		private static TextObject RansomOfferDescriptionText = new TextObject("{=ZqJ92UN4}A courier with a ransom offer for the freedom of {CAPTIVE_HERO.NAME} has arrived.");

		private static TextObject RansomPanelDescriptionNpcHeldPrisonerText = new TextObject("{=4fXpOe4N}A courier arrives from the {CLAN_NAME}. They hold {CAPTIVE_HERO.NAME} and are demanding {GOLD_AMOUNT}{GOLD_ICON} in ransom.");

		private static TextObject RansomPanelDescriptionPlayerHeldPrisonerText = new TextObject("{=PutoRsWp}A courier arrives from the {CLAN_NAME}. They offer you {GOLD_AMOUNT}{GOLD_ICON} in ransom if you will free {CAPTIVE_HERO.NAME}.");

		private List<Hero> _heroesWithDeclinedRansomOffers = new List<Hero>();

		private Hero _currentRansomHero;

		private Hero _currentRansomPayer;

		private CampaignTime _currentRansomOfferDate;

		private static TextObject RansomPanelTitleText => new TextObject("{=ho5EndaV}Decision");

		private static TextObject RansomPanelAffirmativeText => new TextObject("{=Y94H6XnK}Accept");

		private static TextObject RansomPanelNegativeText => new TextObject("{=cOgmdp9e}Decline");

		public override void RegisterEvents()
		{
			CampaignEvents.DailyTickHeroEvent.AddNonSerializedListener(this, DailyTickHero);
			CampaignEvents.OnRansomOfferedToPlayerEvent.AddNonSerializedListener(this, OnRansomOffered);
			CampaignEvents.HeroKilledEvent.AddNonSerializedListener(this, OnHeroKilled);
			CampaignEvents.HeroPrisonerReleased.AddNonSerializedListener(this, OnHeroPrisonerReleased);
			CampaignEvents.HourlyTickEvent.AddNonSerializedListener(this, HourlyTick);
			CampaignEvents.PrisonersChangeInSettlement.AddNonSerializedListener(this, OnPrisonersChangeInSettlement);
			CampaignEvents.HeroPrisonerTaken.AddNonSerializedListener(this, OnHeroPrisonerTaken);
		}

		private void OnHeroPrisonerTaken(PartyBase party, Hero hero)
		{
			HandleDeclineRansomOffer(hero);
		}

		private void DailyTickHero(Hero hero)
		{
			if (hero.IsPrisoner && hero.Clan != null && hero.PartyBelongedToAsPrisoner != null && hero.PartyBelongedToAsPrisoner.MapFaction != null && !hero.PartyBelongedToAsPrisoner.MapFaction.IsBanditFaction && hero != Hero.MainHero && hero.Clan.AliveLords.Count > 1 && hero.MapFaction != null)
			{
				ConsiderRansomPrisoner(hero);
			}
		}

		private void ConsiderRansomPrisoner(Hero hero)
		{
			Clan captorClanOfPrisoner = GetCaptorClanOfPrisoner(hero);
			if (captorClanOfPrisoner == null)
			{
				return;
			}
			Hero hero2 = ((hero.Clan.Leader != hero) ? hero.Clan.Leader : hero.Clan.AliveLords.Where((Hero t) => t != hero.Clan.Leader).GetRandomElementInefficiently());
			if (hero2 == Hero.MainHero && hero2.IsPrisoner)
			{
				return;
			}
			if (captorClanOfPrisoner == Clan.PlayerClan || hero.Clan == Clan.PlayerClan)
			{
				if (_currentRansomHero != null || MobileParty.MainParty.IsInRaftState)
				{
					return;
				}
				float num = ((!_heroesWithDeclinedRansomOffers.Contains(hero)) ? 0.2f : 0.12f);
				if (MBRandom.RandomFloat < num)
				{
					float num2 = (float)new SetPrisonerFreeBarterable(hero, captorClanOfPrisoner.Leader, hero.PartyBelongedToAsPrisoner, hero2).GetUnitValueForFaction(hero.Clan) * 1.1f;
					if (num2 > 1E-05f && (float)(hero2.Gold + 1000) >= num2)
					{
						SetCurrentRansomHero(hero, hero2);
						StringHelpers.SetCharacterProperties("CAPTIVE_HERO", hero.CharacterObject, RansomOfferDescriptionText);
						Campaign.Current.CampaignInformationManager.NewMapNoticeAdded(new RansomOfferMapNotification(hero, RansomOfferDescriptionText));
					}
				}
			}
			else if (MBRandom.RandomFloat < 0.1f)
			{
				SetPrisonerFreeBarterable setPrisonerFreeBarterable = new SetPrisonerFreeBarterable(hero, captorClanOfPrisoner.Leader, hero.PartyBelongedToAsPrisoner, hero2);
				if (setPrisonerFreeBarterable.GetValueForFaction(captorClanOfPrisoner) + setPrisonerFreeBarterable.GetValueForFaction(hero.Clan) > 0)
				{
					Campaign.Current.BarterManager.ExecuteAiBarter(captorClanOfPrisoner, hero.Clan, captorClanOfPrisoner.Leader, hero2, setPrisonerFreeBarterable);
				}
			}
		}

		private Clan GetCaptorClanOfPrisoner(Hero hero)
		{
			Clan clan = null;
			if (hero.PartyBelongedToAsPrisoner.IsMobile)
			{
				if ((hero.PartyBelongedToAsPrisoner.MobileParty.IsMilitia || hero.PartyBelongedToAsPrisoner.MobileParty.IsGarrison || hero.PartyBelongedToAsPrisoner.MobileParty.IsCaravan || hero.PartyBelongedToAsPrisoner.MobileParty.IsVillager) && hero.PartyBelongedToAsPrisoner.Owner != null)
				{
					if (hero.PartyBelongedToAsPrisoner.Owner.IsNotable)
					{
						return hero.PartyBelongedToAsPrisoner.Owner.CurrentSettlement.OwnerClan;
					}
					return hero.PartyBelongedToAsPrisoner.Owner.Clan;
				}
				if (hero.PartyBelongedToAsPrisoner.MobileParty.IsPatrolParty)
				{
					return hero.PartyBelongedToAsPrisoner.MobileParty.HomeSettlement.OwnerClan;
				}
				return hero.PartyBelongedToAsPrisoner.MobileParty.ActualClan;
			}
			return hero.PartyBelongedToAsPrisoner.Settlement.OwnerClan;
		}

		public void SetCurrentRansomHero(Hero hero, Hero ransomPayer = null)
		{
			_currentRansomHero = hero;
			_currentRansomPayer = ransomPayer;
			_currentRansomOfferDate = ((hero != null) ? CampaignTime.Now : CampaignTime.Never);
		}

		private void OnRansomOffered(Hero captiveHero)
		{
			Clan captorClanOfPrisoner = GetCaptorClanOfPrisoner(captiveHero);
			Clan clan = ((captiveHero.Clan == Clan.PlayerClan) ? captorClanOfPrisoner : captiveHero.Clan);
			Hero ransomPayer = ((captiveHero.Clan.Leader != captiveHero) ? captiveHero.Clan.Leader : captiveHero.Clan.AliveLords.Where((Hero t) => t != captiveHero.Clan.Leader).GetRandomElementInefficiently());
			int ransomPrice = (int)((float)new SetPrisonerFreeBarterable(captiveHero, captorClanOfPrisoner.Leader, captiveHero.PartyBelongedToAsPrisoner, ransomPayer).GetUnitValueForFaction(captiveHero.Clan) * 1.1f);
			TextObject textObject = ((captorClanOfPrisoner == Clan.PlayerClan) ? RansomPanelDescriptionPlayerHeldPrisonerText : RansomPanelDescriptionNpcHeldPrisonerText);
			textObject.SetTextVariable("CLAN_NAME", clan.Name);
			textObject.SetTextVariable("GOLD_AMOUNT", ransomPrice);
			textObject.SetTextVariable("GOLD_ICON", "{=!}<img src=\"General\\Icons\\Coin@2x\" extend=\"6\">");
			StringHelpers.SetCharacterProperties("CAPTIVE_HERO", captiveHero.CharacterObject, textObject);
			Campaign.Current.TimeControlMode = CampaignTimeControlMode.Stop;
			InformationManager.ShowInquiry(new InquiryData(RansomPanelTitleText.ToString(), textObject.ToString(), isAffirmativeOptionShown: true, isNegativeOptionShown: true, RansomPanelAffirmativeText.ToString(), RansomPanelNegativeText.ToString(), delegate
			{
				AcceptRansomOffer(ransomPrice);
			}, DeclineRansomOffer, "", 0f, null, () => IsAffirmativeOptionEnabled(ransomPayer, ransomPrice)), pauseGameActiveState: true);
		}

		private (bool, string) IsAffirmativeOptionEnabled(Hero ransomPayer, int ransomPrice)
		{
			if (ransomPayer == Hero.MainHero && ransomPayer.Gold < ransomPrice)
			{
				return (false, "{=d0kbtGYn}You don't have enough gold.");
			}
			return (true, string.Empty);
		}

		private void AcceptRansomOffer(int ransomPrice)
		{
			if (_heroesWithDeclinedRansomOffers.Contains(_currentRansomHero))
			{
				_heroesWithDeclinedRansomOffers.Remove(_currentRansomHero);
			}
			if (_currentRansomPayer.Gold < ransomPrice + 1000 && _currentRansomPayer != Hero.MainHero)
			{
				_currentRansomPayer.Gold = ransomPrice + 1000;
			}
			GiveGoldAction.ApplyBetweenCharacters(_currentRansomPayer, GetCaptorClanOfPrisoner(_currentRansomHero).Leader, ransomPrice);
			EndCaptivityAction.ApplyByRansom(_currentRansomHero, _currentRansomHero.Clan.Leader);
			Campaign.Current.CampaignBehaviorManager.GetBehavior<IStatisticsCampaignBehavior>()?.OnPlayerAcceptedRansomOffer(ransomPrice);
		}

		private void DeclineRansomOffer()
		{
			if (_currentRansomHero.IsPrisoner && _currentRansomHero.IsAlive && !_heroesWithDeclinedRansomOffers.Contains(_currentRansomHero))
			{
				_heroesWithDeclinedRansomOffers.Add(_currentRansomHero);
			}
			SetCurrentRansomHero(null);
		}

		private void OnHeroKilled(Hero victim, Hero killer, KillCharacterAction.KillCharacterActionDetail detail, bool showNotification = true)
		{
			HandleDeclineRansomOffer(victim);
		}

		private void HandleDeclineRansomOffer(Hero victim)
		{
			if (_currentRansomHero != null && (victim == _currentRansomHero || victim == Hero.MainHero))
			{
				CampaignEventDispatcher.Instance.OnRansomOfferCancelled(_currentRansomHero);
				DeclineRansomOffer();
			}
		}

		private void OnPrisonersChangeInSettlement(Settlement settlement, FlattenedTroopRoster roster, Hero prisoner, bool takenFromDungeon)
		{
			if (takenFromDungeon || _currentRansomHero == null)
			{
				return;
			}
			if (prisoner == _currentRansomHero)
			{
				CampaignEventDispatcher.Instance.OnRansomOfferCancelled(_currentRansomHero);
				DeclineRansomOffer();
			}
			else
			{
				if (roster == null)
				{
					return;
				}
				foreach (FlattenedTroopRosterElement item in roster)
				{
					if (item.Troop.IsHero && item.Troop.HeroObject == _currentRansomHero)
					{
						CampaignEventDispatcher.Instance.OnRansomOfferCancelled(_currentRansomHero);
						DeclineRansomOffer();
						break;
					}
				}
			}
		}

		private void OnHeroPrisonerReleased(Hero prisoner, PartyBase party, IFaction capturerFaction, EndCaptivityDetail detail, bool showNotification)
		{
			HandleDeclineRansomOffer(prisoner);
		}

		private void HourlyTick()
		{
			if (_currentRansomHero != null && _currentRansomOfferDate.ElapsedDaysUntilNow >= 2f)
			{
				CampaignEventDispatcher.Instance.OnRansomOfferCancelled(_currentRansomHero);
				DeclineRansomOffer();
			}
		}

		public override void SyncData(IDataStore dataStore)
		{
			dataStore.SyncData("_heroesWithDeclinedRansomOffers", ref _heroesWithDeclinedRansomOffers);
			dataStore.SyncData("_currentRansomHero", ref _currentRansomHero);
			dataStore.SyncData("_currentRansomPayer", ref _currentRansomPayer);
			dataStore.SyncData("_currentRansomOfferDate", ref _currentRansomOfferDate);
		}
	}
	public class RebellionsCampaignBehavior : CampaignBehaviorBase
	{
		private const int UpdateClanAfterDays = 30;

		private const int LoyaltyAfterRebellion = 100;

		private const int InitialRelationPenalty = -80;

		private const int InitialRelationBoostWithOtherFactions = 10;

		private const int InitialRelationBoost = 60;

		private const int InitialRelationBetweenRebelHeroes = 10;

		private const int RebelClanStartingRenownMin = 200;

		private const int RebelClanStartingRenownMax = 300;

		private const int RebelHeroAgeMin = 25;

		private const int RebelHeroAgeMax = 40;

		private const float MilitiaGarrisonRatio = 1.4f;

		private const float ThrowGarrisonTroopToPrisonPercentage = 0.5f;

		private const float ThrowMilitiaTroopToGarrisonPercentage = 0.6f;

		private const float DailyRebellionCheckChance = 0.25f;

		private Dictionary<Clan, int> _rebelClansAndDaysPassedAfterCreation;

		private Dictionary<CultureObject, Dictionary<int, int>> _cultureIconIdAndFrequencies;

		private bool _rebellionEnabled = true;

		public RebellionsCampaignBehavior()
		{
			_rebelClansAndDaysPassedAfterCreation = new Dictionary<Clan, int>();
			_cultureIconIdAndFrequencies = new Dictionary<CultureObject, Dictionary<int, int>>();
		}

		public override void RegisterEvents()
		{
			CampaignEvents.DailyTickSettlementEvent.AddNonSerializedListener(this, DailyTickSettlement);
			CampaignEvents.DailyTickClanEvent.AddNonSerializedListener(this, DailyTickClan);
			CampaignEvents.OnNewGameCreatedPartialFollowUpEndEvent.AddNonSerializedListener(this, OnNewGameCreatedPartialFollowUpEnd);
			CampaignEvents.OnGameLoadFinishedEvent.AddNonSerializedListener(this, OnGameLoaded);
			CampaignEvents.OnClanDestroyedEvent.AddNonSerializedListener(this, OnClanDestroyed);
			CampaignEvents.OnSiegeEventStartedEvent.AddNonSerializedListener(this, OnSiegeStarted);
		}

		private void OnSiegeStarted(SiegeEvent siegeEvent)
		{
			if (siegeEvent.BesiegedSettlement.IsTown)
			{
				CheckAndSetTownRebelliousState(siegeEvent.BesiegedSettlement);
			}
		}

		public override void SyncData(IDataStore dataStore)
		{
			dataStore.SyncData("_rebelClansAndDaysPassedAfterCreation", ref _rebelClansAndDaysPassedAfterCreation);
			dataStore.SyncData("_iconIdAndFrequency", ref _cultureIconIdAndFrequencies);
		}

		private void OnNewGameCreatedPartialFollowUpEnd(CampaignGameStarter starter)
		{
			InitializeIconIdAndFrequencies();
		}

		private void OnGameLoaded()
		{
			InitializeIconIdAndFrequencies();
			if (!MBSaveLoad.IsUpdatingGameVersion || !(MBSaveLoad.LastLoadedGameVersion < ApplicationVersion.FromString("e1.7.3.0")))
			{
				return;
			}
			foreach (Settlement item in Settlement.All)
			{
				if (!item.IsTown && item.InRebelliousState)
				{
					item.Town.InRebelliousState = false;
					CampaignEventDispatcher.Instance.TownRebelliousStateChanged(item.Town, rebelliousState: false);
				}
			}
		}

		private void DailyTickSettlement(Settlement settlement)
		{
			if (_rebellionEnabled && settlement.IsTown && settlement.Party.MapEvent == null && settlement.Party.SiegeEvent == null && !settlement.OwnerClan.IsRebelClan && Settlement.CurrentSettlement != settlement)
			{
				CheckAndSetTownRebelliousState(settlement);
				if (MBRandom.RandomFloat < 0.25f && CheckRebellionEvent(settlement))
				{
					StartRebellionEvent(settlement);
				}
			}
			if (settlement.IsTown && settlement.OwnerClan.IsRebelClan)
			{
				float num = MBMath.Map(_rebelClansAndDaysPassedAfterCreation[settlement.OwnerClan] - 1, 0f, 30f, Campaign.Current.Models.SettlementLoyaltyModel.LoyaltyBoostAfterRebellionStartValue, 0f);
				settlement.Town.Loyalty += num;
			}
		}

		private void CheckAndSetTownRebelliousState(Settlement settlement)
		{
			bool inRebelliousState = settlement.Town.InRebelliousState;
			settlement.Town.InRebelliousState = settlement.Town.Loyalty <= (float)Campaign.Current.Models.SettlementLoyaltyModel.RebelliousStateStartLoyaltyThreshold;
			if (inRebelliousState != settlement.Town.InRebelliousState)
			{
				CampaignEventDispatcher.Instance.TownRebelliousStateChanged(settlement.Town, settlement.Town.InRebelliousState);
			}
		}

		private void OnClanDestroyed(Clan destroyedClan)
		{
			if (_rebelClansAndDaysPassedAfterCreation.ContainsKey(destroyedClan))
			{
				_rebelClansAndDaysPassedAfterCreation.Remove(destroyedClan);
			}
			if (destroyedClan.IsRebelClan)
			{
				for (int num = destroyedClan.Heroes.Count - 1; num >= 0; num--)
				{
					Hero hero = destroyedClan.Heroes[num];
					Campaign.Current.CampaignObjectManager.UnregisterDeadHero(hero);
				}
			}
		}

		private void DailyTickClan(Clan clan)
		{
			if (_rebelClansAndDaysPassedAfterCreation.ContainsKey(clan))
			{
				_rebelClansAndDaysPassedAfterCreation[clan]++;
				if (_rebelClansAndDaysPassedAfterCreation[clan] >= 30 && clan.Leader != null && clan.Settlements.Count > 0)
				{
					TextObject textObject = new TextObject("{=aKaGaOQx}{CLAN_LEADER.NAME}{.o} Clan");
					StringHelpers.SetCharacterProperties("CLAN_LEADER", clan.Leader.CharacterObject, textObject);
					clan.ChangeClanName(textObject, textObject);
					clan.IsRebelClan = false;
					_rebelClansAndDaysPassedAfterCreation.Remove(clan);
					CampaignEventDispatcher.Instance.OnRebelliousClanDisbandedAtSettlement(clan.HomeSettlement, clan);
				}
			}
			if (!clan.IsRebelClan || clan.Settlements.Count != 0 || clan.Heroes.Count <= 0 || clan.IsEliminated)
			{
				return;
			}
			for (int num = clan.Heroes.Count - 1; num >= 0; num--)
			{
				Hero hero = clan.Heroes[num];
				if (hero.IsAlive)
				{
					if (hero.IsPrisoner && hero.PartyBelongedToAsPrisoner != null && hero.PartyBelongedToAsPrisoner != PartyBase.MainParty && hero.PartyBelongedToAsPrisoner.LeaderHero != null)
					{
						KillCharacterAction.ApplyByExecution(hero, hero.PartyBelongedToAsPrisoner.LeaderHero, showNotification: true, isForced: true);
					}
					else if (hero.PartyBelongedTo == null)
					{
						KillCharacterAction.ApplyByRemove(hero);
					}
					else if (_rebelClansAndDaysPassedAfterCreation[clan] > 90 && hero.PartyBelongedTo != null && hero.PartyBelongedTo.MapEvent == null)
					{
						KillCharacterAction.ApplyByRemove(hero);
					}
				}
			}
		}

		private static bool CheckRebellionEvent(Settlement settlement)
		{
			if (settlement.Town.Loyalty <= (float)Campaign.Current.Models.SettlementLoyaltyModel.RebellionStartLoyaltyThreshold)
			{
				float militia = settlement.Militia;
				float num = settlement.Town.GarrisonParty?.Party.CalculateCurrentStrength() ?? 0f;
				foreach (MobileParty party in settlement.Parties)
				{
					if (party.IsLordParty && DiplomacyHelper.IsSameFactionAndNotEliminated(party.MapFaction, settlement.MapFaction))
					{
						num += party.Party.CalculateCurrentStrength();
					}
				}
				return militia >= num * 1.4f;
			}
			return false;
		}

		public void StartRebellionEvent(Settlement settlement)
		{
			Clan ownerClan = settlement.OwnerClan;
			CreateRebelPartyAndClan(settlement);
			ApplyRebellionConsequencesToSettlement(settlement);
			CampaignEventDispatcher.Instance.OnRebellionFinished(settlement, ownerClan);
			settlement.Town.FoodStocks = settlement.Town.FoodStocksUpperLimit();
			settlement.Militia = 100f;
		}

		private void ApplyRebellionConsequencesToSettlement(Settlement settlement)
		{
			Dictionary<TroopRosterElement, int> dictionary = new Dictionary<TroopRosterElement, int>();
			foreach (TroopRosterElement item in settlement.Town.GarrisonParty.MemberRoster.GetTroopRoster())
			{
				for (int i = 0; i < item.Number; i++)
				{
					if (MBRandom.RandomFloat < 0.5f)
					{
						if (dictionary.ContainsKey(item))
						{
							dictionary[item]++;
						}
						else
						{
							dictionary.Add(item, 1);
						}
					}
				}
			}
			settlement.Town.GarrisonParty.MemberRoster.Clear();
			foreach (KeyValuePair<TroopRosterElement, int> item2 in dictionary)
			{
				settlement.Party.AddPrisoner(item2.Key.Character, item2.Value);
			}
			settlement.Town.GarrisonParty.AddElementToMemberRoster(settlement.Culture.RangedMilitiaTroop, (int)(settlement.Militia * (MBRandom.RandomFloatRanged(-0.1f, 0.1f) + 0.6f)));
			settlement.Militia = 0f;
			if (settlement.MilitiaPartyComponent != null)
			{
				DestroyPartyAction.Apply(null, settlement.MilitiaPartyComponent.MobileParty);
			}
			settlement.Town.GarrisonParty.MemberRoster.AddToCounts(settlement.OwnerClan.Culture.BasicTroop, 50);
			settlement.Town.GarrisonParty.MemberRoster.AddToCounts((settlement.OwnerClan.Culture.BasicTroop.UpgradeTargets.Length != 0) ? settlement.OwnerClan.Culture.BasicTroop.UpgradeTargets.GetRandomElement() : settlement.OwnerClan.Culture.BasicTroop, 25);
			settlement.Town.Loyalty = 100f;
			settlement.Town.InRebelliousState = false;
		}

		private void CreateRebelPartyAndClan(Settlement settlement)
		{
			MBReadOnlyList<CharacterObject> rebelliousHeroTemplates = settlement.Culture.RebelliousHeroTemplates;
			List<Hero> list = new List<Hero>
			{
				CreateRebelLeader(rebelliousHeroTemplates.GetRandomElement(), settlement),
				CreateRebelGovernor(rebelliousHeroTemplates.GetRandomElement(), settlement),
				CreateRebelSupporterHero(rebelliousHeroTemplates.GetRandomElement(), settlement),
				CreateRebelSupporterHero(rebelliousHeroTemplates.GetRandomElement(), settlement)
			};
			int clanIdForNewRebelClan = GetClanIdForNewRebelClan(settlement.Culture);
			Clan clan = Clan.CreateSettlementRebelClan(settlement, list[0], clanIdForNewRebelClan);
			clan.IsNoble = true;
			clan.AddRenown(MBRandom.RandomInt(200, 300));
			foreach (Hero item in list)
			{
				item.Clan = clan;
			}
			_rebelClansAndDaysPassedAfterCreation.Add(clan, 1);
			foreach (Hero item2 in list)
			{
				item2.ChangeState(Hero.CharacterStates.Active);
			}
			MobileParty mobileParty = MobilePartyHelper.SpawnLordParty(list[0], settlement);
			MobilePartyHelper.SpawnLordParty(list[2], settlement);
			MobilePartyHelper.SpawnLordParty(list[3], settlement);
			IFaction mapFaction = settlement.MapFaction;
			DeclareWarAction.ApplyByRebellion(clan, mapFaction);
			foreach (Hero item3 in list)
			{
				ChangeRelationAction.ApplyRelationChangeBetweenHeroes(mapFaction.Leader, item3, MBRandom.RandomInt(-85, -75));
				foreach (Kingdom item4 in Kingdom.All)
				{
					if (item4.IsEliminated || item4.Culture == mapFaction.Culture)
					{
						continue;
					}
					int num = 0;
					foreach (Town fief in item4.Fiefs)
					{
						num += ((!fief.IsTown) ? 1 : 2);
					}
					int num2 = (int)(MBRandom.RandomFloat * MBRandom.RandomFloat * 30f - (float)num);
					int value = ((item4.Culture == clan.Culture) ? (num2 + MBRandom.RandomInt(55, 65)) : num2);
					item4.Leader.SetPersonalRelation(item3, value);
				}
				foreach (Hero item5 in list)
				{
					if (item3 != item5)
					{
						ChangeRelationAction.ApplyRelationChangeBetweenHeroes(item3, item5, MBRandom.RandomInt(5, 15));
					}
				}
			}
			ChangeOwnerOfSettlementAction.ApplyByRebellion(mobileParty.LeaderHero, settlement);
			ChangeGovernorAction.Apply(settlement.Town, list[1]);
			EnterSettlementAction.ApplyForParty(mobileParty, settlement);
			mobileParty.Ai.DisableForHours(5);
			list[0].ChangeHeroGold(50000);
			CampaignEventDispatcher.Instance.OnClanCreated(clan, isCompanion: false);
		}

		private Hero CreateRebelLeader(CharacterObject templateCharacter, Settlement settlement)
		{
			return CreateRebelHeroInternal(templateCharacter, settlement, new Dictionary<SkillObject, int>
			{
				{
					DefaultSkills.Steward,
					MBRandom.RandomInt(100, 175)
				},
				{
					DefaultSkills.Leadership,
					MBRandom.RandomInt(125, 175)
				},
				{
					DefaultSkills.OneHanded,
					MBRandom.RandomInt(125, 175)
