		{
			MBTextManager.SetTextVariable("RANDOM_HIRE_SENTENCE", GameTexts.FindText("str_mercenary_tavern_talk_hire", MBRandom.RandomInt(4).ToString()));
			return true;
		}
	}
	public class RecruitPrisonersCampaignBehavior : CampaignBehaviorBase
	{
		public override void RegisterEvents()
		{
			CampaignEvents.OnMainPartyPrisonerRecruitedEvent.AddNonSerializedListener(this, OnMainPartyPrisonerRecruited);
			CampaignEvents.DailyTickPartyEvent.AddNonSerializedListener(this, DailyTickAIMobileParty);
			CampaignEvents.HourlyTickEvent.AddNonSerializedListener(this, HourlyTickMainParty);
		}

		private void HourlyTickMainParty()
		{
			MobileParty mainParty = MobileParty.MainParty;
			TroopRoster memberRoster = mainParty.MemberRoster;
			TroopRoster prisonRoster = mainParty.PrisonRoster;
			if (memberRoster.Count == 0 || memberRoster.TotalManCount <= 0 || prisonRoster.Count == 0 || prisonRoster.TotalRegulars <= 0 || mainParty.MapEvent != null)
			{
				return;
			}
			int num = MBRandom.RandomInt(0, prisonRoster.Count);
			bool flag = false;
			for (int i = num; i < prisonRoster.Count + num; i++)
			{
				int index = i % prisonRoster.Count;
				CharacterObject characterAtIndex = prisonRoster.GetCharacterAtIndex(index);
				if (characterAtIndex.IsRegular)
				{
					CharacterObject characterObject = characterAtIndex;
					int elementNumber = mainParty.PrisonRoster.GetElementNumber(index);
					int num2 = Campaign.Current.Models.PrisonerRecruitmentCalculationModel.CalculateRecruitableNumber(mainParty.Party, characterObject);
					if (!flag && num2 < elementNumber)
					{
						flag = GenerateConformityForTroop(mainParty, characterObject);
					}
				}
				if (flag)
				{
					break;
				}
			}
		}

		private void DailyTickAIMobileParty(MobileParty mobileParty)
		{
			if (mobileParty.IsMainParty || !mobileParty.IsLordParty || mobileParty.MapEvent != null)
			{
				return;
			}
			TroopRoster prisonRoster = mobileParty.PrisonRoster;
			if (prisonRoster.Count == 0 || prisonRoster.TotalRegulars <= 0)
			{
				return;
			}
			int num = MBRandom.RandomInt(0, prisonRoster.Count);
			bool flag = false;
			for (int i = num; i < prisonRoster.Count + num; i++)
			{
				int index = i % prisonRoster.Count;
				CharacterObject characterAtIndex = prisonRoster.GetCharacterAtIndex(index);
				if (!characterAtIndex.IsRegular)
				{
					continue;
				}
				CharacterObject characterObject = characterAtIndex;
				int elementNumber = mobileParty.PrisonRoster.GetElementNumber(index);
				int num2 = Campaign.Current.Models.PrisonerRecruitmentCalculationModel.CalculateRecruitableNumber(mobileParty.Party, characterObject);
				if (!flag && num2 < elementNumber)
				{
					flag = GenerateConformityForTroop(mobileParty, characterObject, CampaignTime.HoursInDay);
				}
				if (Campaign.Current.Models.PrisonerRecruitmentCalculationModel.ShouldPartyRecruitPrisoners(mobileParty.Party))
				{
					if (IsPrisonerRecruitable(mobileParty, characterObject, out var conformityNeeded))
					{
						int num3 = mobileParty.Party.PartySizeLimit - mobileParty.MemberRoster.TotalManCount;
						int a = TaleWorlds.Library.MathF.Min((num3 > 0) ? ((num3 > num2) ? num2 : num3) : 0, prisonRoster.GetElementNumber(characterObject));
						int characterWage = Campaign.Current.Models.PartyWageModel.GetCharacterWage(characterObject);
						a = TaleWorlds.Library.MathF.Min(a, mobileParty.GetAvailableWageBudget() / characterWage);
						if (a > 0)
						{
							RecruitPrisonersAi(mobileParty, characterObject, a, conformityNeeded);
						}
					}
				}
				else if (flag)
				{
					break;
				}
			}
		}

		private bool GenerateConformityForTroop(MobileParty mobileParty, CharacterObject troop, int hours = 1)
		{
			int xpAmount = Campaign.Current.Models.PrisonerRecruitmentCalculationModel.GetConformityChangePerHour(mobileParty.Party, troop).RoundedResultNumber * hours;
			mobileParty.PrisonRoster.AddXpToTroop(troop, xpAmount);
			return true;
		}

		private void ApplyPrisonerRecruitmentEffects(MobileParty mobileParty, CharacterObject troop, int num)
		{
			int prisonerRecruitmentMoraleEffect = Campaign.Current.Models.PrisonerRecruitmentCalculationModel.GetPrisonerRecruitmentMoraleEffect(mobileParty.Party, troop, num);
			mobileParty.RecentEventsMorale += prisonerRecruitmentMoraleEffect;
		}

		private void RecruitPrisonersAi(MobileParty mobileParty, CharacterObject troop, int num, int conformityCost)
		{
			mobileParty.PrisonRoster.GetElementNumber(troop);
			mobileParty.PrisonRoster.GetElementXp(troop);
			mobileParty.PrisonRoster.AddToCounts(troop, -num, insertAtFront: false, 0, -conformityCost * num);
			mobileParty.MemberRoster.AddToCounts(troop, num);
			CampaignEventDispatcher.Instance.OnTroopRecruited(mobileParty.LeaderHero, null, null, troop, num);
			ApplyPrisonerRecruitmentEffects(mobileParty, troop, num);
		}

		private bool IsPrisonerRecruitable(MobileParty mobileParty, CharacterObject character, out int conformityNeeded)
		{
			return Campaign.Current.Models.PrisonerRecruitmentCalculationModel.IsPrisonerRecruitable(mobileParty.Party, character, out conformityNeeded);
		}

		private void OnMainPartyPrisonerRecruited(FlattenedTroopRoster flattenedTroopRosters)
		{
			foreach (CharacterObject troop in flattenedTroopRosters.Troops)
			{
				CampaignEventDispatcher.Instance.OnUnitRecruited(troop, 1);
				ApplyPrisonerRecruitmentEffects(MobileParty.MainParty, troop, 1);
			}
		}

		public override void SyncData(IDataStore dataStore)
		{
		}
	}
	public class RetrainOutlawPartyMembersBehavior : CampaignBehaviorBase, IRetrainOutlawPartyMembersCampaignBehavior, ICampaignBehavior
	{
		private Dictionary<CharacterObject, int> _retrainTable = new Dictionary<CharacterObject, int>();

		private int GetRetrainedNumberInternal(CharacterObject character)
		{
			if (!_retrainTable.TryGetValue(character, out var value))
			{
				return 0;
			}
			return value;
		}

		private int SetRetrainedNumberInternal(CharacterObject character, int numberRetrained)
		{
			return _retrainTable[character] = numberRetrained;
		}

		public override void RegisterEvents()
		{
			CampaignEvents.DailyTickEvent.AddNonSerializedListener(this, DailyTick);
		}

		private void DailyTick()
		{
			if (!(MBRandom.RandomFloat > 0.5f))
			{
				return;
			}
			int num = MBRandom.RandomInt(MobileParty.MainParty.MemberRoster.Count);
			bool flag = false;
			for (int i = 0; i < MobileParty.MainParty.MemberRoster.Count; i++)
			{
				if (flag)
				{
					break;
				}
				int index = (i + num) % MobileParty.MainParty.MemberRoster.Count;
				CharacterObject characterAtIndex = MobileParty.MainParty.MemberRoster.GetCharacterAtIndex(index);
				if (characterAtIndex.Occupation == Occupation.Bandit)
				{
					int elementNumber = MobileParty.MainParty.MemberRoster.GetElementNumber(index);
					int retrainedNumberInternal = GetRetrainedNumberInternal(characterAtIndex);
					if (retrainedNumberInternal < elementNumber && !flag)
					{
						retrainedNumberInternal++;
						SetRetrainedNumberInternal(characterAtIndex, retrainedNumberInternal);
					}
					else if (retrainedNumberInternal > elementNumber)
					{
						SetRetrainedNumberInternal(characterAtIndex, elementNumber);
					}
				}
			}
		}

		public override void SyncData(IDataStore dataStore)
		{
			dataStore.SyncData("_retrainTable", ref _retrainTable);
		}

		public int GetRetrainedNumber(CharacterObject character)
		{
			if (character.Occupation == Occupation.Bandit)
			{
				int retrainedNumberInternal = GetRetrainedNumberInternal(character);
				int troopCount = MobileParty.MainParty.MemberRoster.GetTroopCount(character);
				return TaleWorlds.Library.MathF.Min(retrainedNumberInternal, troopCount);
			}
			return 0;
		}

		public void SetRetrainedNumber(CharacterObject character, int number)
		{
			SetRetrainedNumberInternal(character, number);
		}
	}
	public class RomanceCampaignBehavior : CampaignBehaviorBase
	{
		public enum RomanticPreference
		{
			Conventional,
			Moralist,
			AttractedToBravery,
			Macchiavellian,
			Romantic,
			Companionship,
			MadAndBad,
			Security,
			PreferencesEnd
		}

		private enum RomanceReservationType
		{
			TravelChat,
			TravelLesson,
			Aspirations,
			Compatibility,
			Attraction,
			Family,
			MaterialWealth,
			NoObjection
		}

		private enum RomanceReservationDescription
		{
			CompatibilityINeedSomeoneUpright,
			CompatibilityNeedSomethingInCommon,
			CompatibiliyINeedSomeoneDangerous,
			CompatibilityStrongPoliticalBeliefs,
			AttractionYoureNotMyType,
			AttractionYoureGoodEnough,
			AttractionIAmDrawnToYou,
			PropertyYouSeemRichEnough,
			PropertyWeNeedToBeComfortable,
			PropertyIWantRealWealth,
			PropertyHowCanIMarryAnAdventuress,
			FamilyApprovalIAmGladYouAreFriendsWithOurFamily,
			FamilyApprovalYouNeedToBeFriendsWithOurFamily,
			FamilyApprovalHowCanYouBeEnemiesWithOurFamily,
			FamilyApprovalItWouldBeBestToBefriendOurFamily
		}

		private const PersuasionDifficulty _difficulty = PersuasionDifficulty.Medium;

		private List<PersuasionTask> _allReservations;

		[SaveableField(1)]
		private List<PersuasionAttempt> _previousRomancePersuasionAttempts;

		private Hero _playerProposalHero;

		private Hero _proposedSpouseForPlayerRelative;

		private float _maximumScoreCap;

		private const float _successValue = 1f;

		private const float _criticalSuccessValue = 2f;

		private const float _criticalFailValue = 2f;

		private const float _failValue = 0f;

		private CampaignTime RomanceCourtshipAttemptCooldown => CampaignTime.DaysFromNow(-1f);

		public RomanceCampaignBehavior()
		{
			_previousRomancePersuasionAttempts = new List<PersuasionAttempt>();
		}

		public override void RegisterEvents()
		{
			CampaignEvents.OnSessionLaunchedEvent.AddNonSerializedListener(this, OnSessionLaunched);
			CampaignEvents.DailyTickEvent.AddNonSerializedListener(this, DailyTick);
			CampaignEvents.DailyTickClanEvent.AddNonSerializedListener(this, DailyTickClan);
		}

		private void DailyTickClan(Clan clan)
		{
			CheckNpcMarriages(clan);
		}

		private void CheckNpcMarriages(Clan consideringClan)
		{
			if (!IsClanSuitableForNpcMarriage(consideringClan))
			{
				return;
			}
			MarriageModel marriageModel = Campaign.Current.Models.MarriageModel;
			foreach (Hero item in consideringClan.AliveLords.ToList())
			{
				if (!item.CanMarry())
				{
					continue;
				}
				Clan clan = Clan.All[MBRandom.RandomInt(Clan.All.Count)];
				if (!IsClanSuitableForNpcMarriage(clan) || !marriageModel.ShouldNpcMarriageBetweenClansBeAllowed(consideringClan, clan))
				{
					continue;
				}
				foreach (Hero item2 in clan.AliveLords.ToList())
				{
					float num = marriageModel.NpcCoupleMarriageChance(item, item2);
					if (!(num > 0f) || !(MBRandom.RandomFloat < num))
					{
						continue;
					}
					bool flag = false;
					foreach (Romance.RomanticState romanticState in Romance.RomanticStateList)
					{
						if (romanticState.Level >= Romance.RomanceLevelEnum.MatchMadeByFamily && (romanticState.Person1 == item || romanticState.Person2 == item || romanticState.Person1 == item2 || romanticState.Person2 == item2))
						{
							flag = true;
							break;
						}
					}
					if (!flag)
					{
						MarriageAction.Apply(item, item2);
						return;
					}
				}
			}
		}

		private bool IsClanSuitableForNpcMarriage(Clan clan)
		{
			if (clan != Clan.PlayerClan)
			{
				return Campaign.Current.Models.MarriageModel.IsClanSuitableForMarriage(clan);
			}
			return false;
		}

		public override void SyncData(IDataStore dataStore)
		{
			dataStore.SyncData("previousRomancePersuasionAttempts", ref _previousRomancePersuasionAttempts);
		}

		public void OnSessionLaunched(CampaignGameStarter campaignGameStarter)
		{
			AddDialogs(campaignGameStarter);
		}

		private PersuasionTask GetCurrentPersuasionTask()
		{
			foreach (PersuasionTask allReservation in _allReservations)
			{
				if (!allReservation.Options.All((PersuasionOptionArgs x) => x.IsBlocked))
				{
					return allReservation;
				}
			}
			return _allReservations[_allReservations.Count - 1];
		}

		private void RemoveUnneededPersuasionAttempts()
		{
			foreach (PersuasionAttempt item in _previousRomancePersuasionAttempts.ToList())
			{
				if (item.PersuadedHero.Spouse != null || !item.PersuadedHero.IsAlive)
				{
					_previousRomancePersuasionAttempts.Remove(item);
				}
			}
		}

		protected void AddDialogs(CampaignGameStarter starter)
		{
			starter.AddPlayerLine("lord_special_request_flirt", "lord_talk_speak_diplomacy_2", "lord_start_courtship_response", "{=!}{FLIRTATION_LINE}", conversation_player_can_open_courtship_on_condition, conversation_player_opens_courtship_on_consequence);
			starter.AddPlayerLine("hero_romance_task_pt1", "hero_main_options", "hero_courtship_task_1_begin_reservations", "{=bHZyublA}So... I'm glad to have the chance to spend some time together.", conversation_romance_at_stage_1_discussions_on_condition, conversation_start_courtship_persuasion_pt1_on_consequence);
			starter.AddPlayerLine("hero_romance_task_pt2", "hero_main_options", "hero_courtship_task_2_begin_reservations", "{=nGsQeTll}Perhaps we should discuss a future together...", conversation_romance_at_stage_2_discussions_on_condition, conversation_continue_courtship_stage_2_on_consequence);
			starter.AddPlayerLine("hero_romance_task_pt3a", "hero_main_options", "hero_courtship_final_barter", "{=2aW6NC3Q}Let us discuss the final terms of our marriage.", conversation_finalize_courtship_for_hero_on_condition, null);
