					HandlePlayerDeathDuringSiegeAftermath();
				}
			}
			else if (_wasPlayerArmyMember)
			{
				GameMenu.SwitchToMenu("menu_settlement_taken_player_army_member");
			}
			else
			{
				GameMenu.SwitchToMenu("menu_settlement_taken_player_participant");
			}
		}

