		{
			campaignGameSystemStarter.AddGameMenuOption("menu_siege_strategies", "menu_siege_strategies_ambush", "{=LEKzuGzi}Ambush", menu_siege_strategies_ambush_condition, menu_siege_strategies_ambush_on_consequence);
