		protected void AddGameMenus(CampaignGameStarter campaignGameSystemStarter)
		{
			campaignGameSystemStarter.AddWaitGameMenu("menu_siege_strategies", "{=!}{CURRENT_STRATEGY}", game_menu_siege_strategies_on_init, null, null, game_menu_siege_strategies_on_tick, GameMenu.MenuAndOptionType.WaitMenuHideProgressAndHoursOption, GameMenu.MenuOverlayType.Encounter);
			campaignGameSystemStarter.AddGameMenuOption("menu_siege_strategies", "menu_siege_strategies_lead_assault", "{=mjOcwUSA}Lead an assault", game_menu_siege_strategies_lead_assault_on_condition, menu_siege_strategies_lead_assault_on_consequence);
			campaignGameSystemStarter.AddGameMenuOption("menu_siege_strategies", "menu_siege_strategies_order_troops", "{=TtGJqRI5}Send troops", game_menu_siege_strategies_order_assault_on_condition, menu_order_an_assault_on_consequence);
			campaignGameSystemStarter.AddGameMenuOption("menu_siege_strategies", "menu_siege_strategies_request_parley", "{=2xVbLS5r}Request a parley", menu_defender_side_request_audience_on_condition, menu_defender_side_request_audience_on_consequence);
			campaignGameSystemStarter.AddGameMenuOption("menu_siege_strategies", "menu_siege_strategies_leave", "{=3sRdGQou}Leave", menu_siege_leave_on_condition, menu_siege_leave_on_consequence, isLeave: true, 10);
			campaignGameSystemStarter.AddGameMenuOption("menu_siege_strategies", "menu_siege_strategies_leave_army", "{=hSdJ0UUv}Leave Army", menu_siege_strategies_passive_wait_leave_on_condition, menu_siege_strategies_passive_wait_leave_on_consequence, isLeave: true);
			campaignGameSystemStarter.AddGameMenu("menu_siege_strategies_break_siege", "{=!}{SIEGE_LEAVE_TEXT}", menu_break_siege_on_init, GameMenu.MenuOverlayType.Encounter);
			campaignGameSystemStarter.AddGameMenuOption("menu_siege_strategies_break_siege", "menu_siege_strategies_break_siege_return", "{=25ifdWOy}Return to siege", return_siege_on_condition, delegate
			{
				GameMenu.SwitchToMenu("menu_siege_strategies");
			});
			campaignGameSystemStarter.AddGameMenuOption("menu_siege_strategies_break_siege", "menu_siege_strategies_break_siege_go_on", "{=TGYJUUn0}Go on.", leave_siege_on_condition, menu_end_besieging_on_consequence, isLeave: true);
			campaignGameSystemStarter.AddGameMenu("menu_siege_safe_passage_accepted", "Besiegers have agreed to allow safe passage for your party.", null);
			campaignGameSystemStarter.AddGameMenuOption("menu_siege_safe_passage_accepted", "menu_siege_safe_passage_accepted_leave", "Leave", leave_siege_on_condition, menu_siege_leave_on_consequence, isLeave: true);
		}

		private void game_menu_siege_strategies_on_tick(MenuCallbackArgs args, CampaignTime dt)
		{
			string genericStateMenu = Campaign.Current.Models.EncounterGameMenuModel.GetGenericStateMenu();
			if (genericStateMenu != "menu_siege_strategies")
			{
				if (!string.IsNullOrEmpty(genericStateMenu))
				{
					GameMenu.SwitchToMenu(genericStateMenu);
				}
				else
				{
					GameMenu.ExitToLast();
				}
			}
			else
			{
				args.MenuContext.GameMenu.GetText().SetTextVariable("CURRENT_STRATEGY", _currentSiegeDescription);
				Campaign.Current.GameMenuManager.RefreshMenuOptionConditions(args.MenuContext);
			}
		}

		private void game_menu_siege_strategies_on_init(MenuCallbackArgs args)
		{
			MBTextManager.SetTextVariable("CURRENT_STRATEGY", _currentSiegeDescription);
		}

		private static void menu_siege_strategies_lead_assault_on_consequence(MenuCallbackArgs args)
		{
			if (PlayerEncounter.IsActive)
			{
				PlayerEncounter.LeaveEncounter = false;
			}
			else
			{
				EncounterManager.StartSettlementEncounter(MobileParty.MainParty, PlayerSiege.PlayerSiegeEvent.BesiegedSettlement);
			}
			GameMenu.SwitchToMenu("assault_town");
		}

		private static void menu_order_an_assault_on_consequence(MenuCallbackArgs args)
		{
			if (PlayerEncounter.IsActive)
			{
				PlayerEncounter.LeaveEncounter = false;
			}
			else
			{
				PlayerEncounter.Start();
				PlayerEncounter.Current.SetupFields(PartyBase.MainParty, PlayerSiege.PlayerSiegeEvent.BesiegedSettlement.Party);
			}
			GameMenu.SwitchToMenu("assault_town_order_attack");
		}

		private bool menu_siege_leave_on_condition(MenuCallbackArgs args)
		{
			args.optionLeaveType = GameMenuOption.LeaveType.Leave;
			if (MobileParty.MainParty.Army != null && MobileParty.MainParty.Army.LeaderParty != MobileParty.MainParty)
			{
				return false;
			}
			if (PlayerSiege.PlayerSiegeEvent != null && PlayerSiege.PlayerSide == BattleSideEnum.Defender && !MobileParty.MainParty.MapFaction.IsAtWarWith(PlayerSiege.PlayerSiegeEvent.BesiegerCamp.MapFaction))
			{
				return true;
			}
			if (PlayerSiege.PlayerSiegeEvent != null)
			{
				return PlayerSiege.PlayerSide == BattleSideEnum.Attacker;
			}
			return false;
		}

		private bool menu_siege_strategies_passive_wait_leave_on_condition(MenuCallbackArgs args)
		{
			args.optionLeaveType = GameMenuOption.LeaveType.Leave;
			if (PlayerSiege.PlayerSiegeEvent == null || PlayerSiege.PlayerSide != BattleSideEnum.Attacker)
			{
				return false;
			}
			if (MobileParty.MainParty.Army != null)
			{
				return MobileParty.MainParty.Army.LeaderParty != MobileParty.MainParty;
			}
			return false;
		}

		private void menu_break_siege_on_init(MenuCallbackArgs args)
		{
			if (MobileParty.MainParty.SiegeEvent.BesiegerCamp.LeaderParty == MobileParty.MainParty)
			{
				MBTextManager.SetTextVariable("SIEGE_LEAVE_TEXT", _removeSiegeCompletelyText);
			}
			else
			{
				MBTextManager.SetTextVariable("SIEGE_LEAVE_TEXT", _leaveSiegeText);
			}
			Campaign.Current.TimeControlMode = CampaignTimeControlMode.Stop;
		}

		private bool return_siege_on_condition(MenuCallbackArgs args)
		{
			args.optionLeaveType = GameMenuOption.LeaveType.Continue;
			return true;
		}

		private bool leave_siege_on_condition(MenuCallbackArgs args)
		{
			args.optionLeaveType = GameMenuOption.LeaveType.Leave;
			return true;
		}

		private void menu_siege_strategies_passive_wait_leave_on_consequence(MenuCallbackArgs args)
		{
			GameMenu.ExitToLast();
			if (PlayerSiege.PlayerSiegeEvent != null)
			{
				PlayerSiege.FinalizePlayerSiege();
			}
			MobileParty.MainParty.BesiegerCamp = null;
			MobileParty.MainParty.Army = null;
		}

		private static bool game_menu_siege_strategies_order_assault_on_condition(MenuCallbackArgs args)
		{
			args.optionLeaveType = GameMenuOption.LeaveType.OrderTroopsToAttack;
			if (MobileParty.MainParty.BesiegedSettlement == null)
			{
				return false;
			}
			if (Campaign.Current.Models.EncounterModel.GetLeaderOfSiegeEvent(MobileParty.MainParty.BesiegedSettlement.SiegeEvent, PlayerSiege.PlayerSide) == Hero.MainHero)
			{
				Settlement settlement = PlayerEncounter.EncounteredParty?.Settlement ?? PlayerSiege.PlayerSiegeEvent.BesiegedSettlement;
				if (PlayerSiege.PlayerSide == BattleSideEnum.Attacker && !settlement.SiegeEvent.BesiegerCamp.IsPreparationComplete)
				{
					args.IsEnabled = false;
					args.Tooltip = _waitSiegeEquipmentsText;
				}
				else
				{
					bool flag = MobileParty.MainParty.MemberRoster.GetTroopRoster().Any((TroopRosterElement x) => x.Character.IsHero ? (x.Character != CharacterObject.PlayerCharacter && !x.Character.HeroObject.IsWounded) : (x.Number > x.WoundedNumber));
					if (!flag && MobileParty.MainParty.Army != null && MobileParty.MainParty.Army.LeaderParty == MobileParty.MainParty)
					{
						foreach (MobileParty attachedParty in MobileParty.MainParty.Army.LeaderParty.AttachedParties)
						{
							flag = attachedParty.MemberRoster.GetTroopRoster().Any((TroopRosterElement x) => x.Character.IsHero ? (x.Character != CharacterObject.PlayerCharacter && !x.Character.HeroObject.IsWounded) : (x.Number > x.WoundedNumber));
							if (flag)
							{
								break;
							}
						}
					}
					args.Tooltip = TooltipHelper.GetSendTroopsPowerContextTooltipForSiege();
					if (!flag)
					{
						args.IsEnabled = false;
						args.Tooltip = new TextObject("{=ao9bhAhf}You are not leading any troops");
					}
					else if (!MobilePartyHelper.CanPartyAttackWithCurrentMorale(MobileParty.MainParty))
					{
						args.Tooltip = new TextObject("{=xnRtINwH}Your men lack the courage to continue the battle without you. (Low Morale)");
						args.IsEnabled = false;
					}
				}
			}
			else
			{
				args.IsEnabled = false;
				args.Tooltip = new TextObject("{=1Hd19nq5}You are not in command of this siege.");
			}
			return true;
		}

		private static bool game_menu_siege_strategies_lead_assault_on_condition(MenuCallbackArgs args)
		{
			args.optionLeaveType = GameMenuOption.LeaveType.LeadAssault;
			if (MobileParty.MainParty.BesiegedSettlement == null)
			{
				return false;
			}
			if (Campaign.Current.Models.EncounterModel.GetLeaderOfSiegeEvent(MobileParty.MainParty.BesiegedSettlement.SiegeEvent, PlayerSiege.PlayerSide) == Hero.MainHero)
			{
				Settlement settlement = PlayerEncounter.EncounteredParty?.Settlement ?? PlayerSiege.PlayerSiegeEvent.BesiegedSettlement;
				if (PlayerSiege.PlayerSide == BattleSideEnum.Attacker && !settlement.SiegeEvent.BesiegerCamp.IsPreparationComplete)
				{
					args.IsEnabled = false;
					args.Tooltip = _waitSiegeEquipmentsText;
				}
				else if (Hero.MainHero.IsWounded)
				{
					args.IsEnabled = false;
					args.Tooltip = _woundedAssaultText;
				}
			}
			else
			{
				args.IsEnabled = false;
				args.Tooltip = _noCommandText;
			}
			return true;
		}

		private static void LeaveSiege()
		{
			MobileParty.MainParty.BesiegerCamp = null;
			if (PlayerEncounter.Current != null)
			{
				PlayerEncounter.Finish();
			}
			else
			{
				GameMenu.ExitToLast();
			}
		}

		private static void menu_siege_leave_on_consequence(MenuCallbackArgs args)
		{
			if (MobileParty.MainParty.BesiegerCamp == null)
			{
				if (PlayerEncounter.Current != null && MobileParty.MainParty.CurrentSettlement != null)
				{
					if (MobileParty.MainParty.Army != null)
					{
						MobileParty.MainParty.Army = null;
					}
					PlayerSiege.FinalizePlayerSiege();
					PlayerEncounter.LeaveSettlement();
					PlayerEncounter.Finish();
				}
				else
				{
					GameMenu.ExitToLast();
				}
			}
			else if (MobileParty.MainParty.BesiegerCamp.LeaderParty == MobileParty.MainParty)
			{
				GameMenu.SwitchToMenu("menu_siege_strategies_break_siege");
			}
			else
			{
				LeaveSiege();
			}
		}

		private static void menu_end_besieging_on_consequence(MenuCallbackArgs args)
		{
			LeaveSiege();
		}

		private static bool menu_defender_side_request_audience_on_condition(MenuCallbackArgs args)
		{
			if (PlayerSiege.PlayerSiegeEvent == null || PlayerSiege.PlayerSide != 0)
			{
				return false;
			}
			if (PlayerSiege.PlayerSiegeEvent != null && PlayerSiege.PlayerSide == BattleSideEnum.Defender && !MobileParty.MainParty.MapFaction.IsAtWarWith(PlayerSiege.PlayerSiegeEvent.BesiegerCamp.MapFaction))
			{
				return false;
			}
			Settlement settlement = Settlement.CurrentSettlement ?? PlayerSiege.PlayerSiegeEvent.BesiegedSettlement;
			if (settlement.SiegeEvent != null && !settlement.SiegeEvent.BesiegerCamp.GetInvolvedPartiesForEventType().Any((PartyBase party) => party.LeaderHero != null && party.MobileParty.IsLordParty))
			{
				args.IsEnabled = false;
				args.Tooltip = new TextObject("{=rO704KOG}There is no one with the authority to talk to you.");
			}
			if (PlayerSiege.PlayerSiegeEvent.BesiegerCamp.LeaderParty.MapEvent != null)
			{
				args.IsEnabled = false;
				args.Tooltip = new TextObject("{=1UO0yMBr}You can not parley during an ongoing battle.");
			}
			args.optionLeaveType = GameMenuOption.LeaveType.Conversation;
			return true;
		}

		private static void menu_defender_side_request_audience_on_consequence(MenuCallbackArgs args)
		{
			GameMenu.SwitchToMenu("request_meeting_with_besiegers");
		}

		private void SetTactic(SiegeEvent siegeEvent, BattleSideEnum side, SiegeStrategy strategy)
		{
			siegeEvent.GetSiegeEventSide(side).SetSiegeStrategy(strategy);
		}

		private void SetDefaultTactics(SiegeEvent siegeEvent, BattleSideEnum side)
		{
			Hero leaderOfSiegeEvent = Campaign.Current.Models.EncounterModel.GetLeaderOfSiegeEvent(siegeEvent, side);
			SiegeStrategy strategy = null;
			if (leaderOfSiegeEvent == Hero.MainHero)
			{
				strategy = DefaultSiegeStrategies.Custom;
			}
			else
			{
				IEnumerable<SiegeStrategy> obj = ((side == BattleSideEnum.Attacker) ? DefaultSiegeStrategies.AllAttackerStrategies : DefaultSiegeStrategies.AllDefenderStrategies);
				float num = float.MinValue;
				foreach (SiegeStrategy item in obj)
				{
					float num2 = Campaign.Current.Models.SiegeEventModel.GetSiegeStrategyScore(siegeEvent, side, item) * (0.5f + 0.5f * MBRandom.RandomFloat);
					if (num2 > num)
					{
						num = num2;
						strategy = item;
					}
				}
			}
			SetTactic(siegeEvent, side, strategy);
		}

		[GameMenuInitializationHandler("menu_siege_strategies")]
		private static void game_menu_siege_strategies_background_on_init(MenuCallbackArgs args)
		{
			args.MenuContext.SetBackgroundMeshName("wait_besieging");
		}
	}
	public class TeleportationCampaignBehavior : CampaignBehaviorBase, ITeleportationCampaignBehavior, ICampaignBehavior
	{
		public class TeleportationCampaignBehaviorTypeDefiner : SaveableTypeDefiner
		{
			public TeleportationCampaignBehaviorTypeDefiner()
				: base(151000)
			{
			}

			protected override void DefineClassTypes()
			{
				AddClassDefinition(typeof(TeleportationData), 1);
			}

			protected override void DefineContainerDefinitions()
			{
				ConstructContainerDefinition(typeof(List<TeleportationData>));
			}
		}

		internal class TeleportationData
		{
			[SaveableField(1)]
			public Hero TeleportingHero;

			[SaveableField(2)]
			public CampaignTime TeleportationTime;

			[SaveableField(3)]
			public Settlement TargetSettlement;

			[SaveableField(4)]
			public bool IsGovernor;

			[SaveableField(5)]
			public MobileParty TargetParty;

			[SaveableField(6)]
			public bool IsPartyLeader;

			public TeleportationData(Hero teleportingHero, Settlement targetSettlement, bool isGovernor)
			{
				TeleportingHero = teleportingHero;
				TeleportationTime = CampaignTime.HoursFromNow(Campaign.Current.Models.DelayedTeleportationModel.GetTeleportationDelayAsHours(teleportingHero, targetSettlement.Party).ResultNumber);
				TargetSettlement = targetSettlement;
				IsGovernor = isGovernor;
				TargetParty = null;
				IsPartyLeader = false;
			}

			public TeleportationData(Hero teleportingHero, MobileParty targetParty, bool isPartyLeader)
			{
				TeleportingHero = teleportingHero;
				TeleportationTime = CampaignTime.HoursFromNow(Campaign.Current.Models.DelayedTeleportationModel.GetTeleportationDelayAsHours(teleportingHero, targetParty.Party).ResultNumber);
				TargetParty = targetParty;
				IsPartyLeader = isPartyLeader;
				TargetSettlement = null;
				IsGovernor = false;
			}

			internal static void AutoGeneratedStaticCollectObjectsTeleportationData(object o, List<object> collectedObjects)
			{
				((TeleportationData)o).AutoGeneratedInstanceCollectObjects(collectedObjects);
			}

			protected virtual void AutoGeneratedInstanceCollectObjects(List<object> collectedObjects)
			{
				collectedObjects.Add(TeleportingHero);
				CampaignTime.AutoGeneratedStaticCollectObjectsCampaignTime(TeleportationTime, collectedObjects);
				collectedObjects.Add(TargetSettlement);
				collectedObjects.Add(TargetParty);
			}

			internal static object AutoGeneratedGetMemberValueTeleportingHero(object o)
			{
				return ((TeleportationData)o).TeleportingHero;
			}

			internal static object AutoGeneratedGetMemberValueTeleportationTime(object o)
			{
				return ((TeleportationData)o).TeleportationTime;
			}

			internal static object AutoGeneratedGetMemberValueTargetSettlement(object o)
			{
				return ((TeleportationData)o).TargetSettlement;
			}

			internal static object AutoGeneratedGetMemberValueIsGovernor(object o)
			{
				return ((TeleportationData)o).IsGovernor;
			}

			internal static object AutoGeneratedGetMemberValueTargetParty(object o)
			{
				return ((TeleportationData)o).TargetParty;
			}

			internal static object AutoGeneratedGetMemberValueIsPartyLeader(object o)
			{
				return ((TeleportationData)o).IsPartyLeader;
			}
		}

		private List<TeleportationData> _teleportationList = new List<TeleportationData>();

		private TextObject _partyLeaderChangeNotificationText => new TextObject("{=QSaufZ9i}One of your parties has lost its leader. It will disband after a day has passed. You can assign a new clan member to lead it, if you wish to keep the party.");

		public override void RegisterEvents()
		{
			CampaignEvents.HourlyTickEvent.AddNonSerializedListener(this, HourlyTick);
			CampaignEvents.DailyTickPartyEvent.AddNonSerializedListener(this, DailyTickParty);
			CampaignEvents.HeroComesOfAgeEvent.AddNonSerializedListener(this, OnHeroComesOfAge);
			CampaignEvents.MobilePartyDestroyed.AddNonSerializedListener(this, OnMobilePartyDestroyed);
			CampaignEvents.OnSettlementOwnerChangedEvent.AddNonSerializedListener(this, OnSettlementOwnerChanged);
			CampaignEvents.HeroKilledEvent.AddNonSerializedListener(this, OnHeroKilled);
			CampaignEvents.OnPartyDisbandStartedEvent.AddNonSerializedListener(this, OnPartyDisbandStarted);
			CampaignEvents.OnGovernorChangedEvent.AddNonSerializedListener(this, OnGovernorChanged);
			CampaignEvents.OnHeroTeleportationRequestedEvent.AddNonSerializedListener(this, OnHeroTeleportationRequested);
			CampaignEvents.OnPartyDisbandedEvent.AddNonSerializedListener(this, OnPartyDisbanded);
			CampaignEvents.OnClanLeaderChangedEvent.AddNonSerializedListener(this, OnClanLeaderChanged);
			CampaignEvents.HeroPrisonerTaken.AddNonSerializedListener(this, HeroPrisonerTaken);
		}

		public override void SyncData(IDataStore dataStore)
		{
			dataStore.SyncData("_teleportationList", ref _teleportationList);
		}

		public bool GetTargetOfTeleportingHero(Hero teleportingHero, out bool isGovernor, out bool isPartyLeader, out IMapPoint target)
		{
			isGovernor = false;
			isPartyLeader = false;
			target = null;
			for (int i = 0; i < _teleportationList.Count; i++)
			{
				TeleportationData teleportationData = _teleportationList[i];
				if (teleportationData.TeleportingHero == teleportingHero)
				{
					if (teleportationData.TargetSettlement != null)
					{
						isGovernor = teleportationData.IsGovernor;
						target = teleportationData.TargetSettlement;
						return true;
					}
					if (teleportationData.TargetParty != null)
					{
						isPartyLeader = teleportationData.IsPartyLeader;
						target = teleportationData.TargetParty;
						return true;
					}
				}
			}
			return false;
		}

		public CampaignTime GetHeroArrivalTimeToDestination(Hero teleportingHero)
		{
			return _teleportationList.FirstOrDefaultQ((TeleportationData x) => x.TeleportingHero == teleportingHero)?.TeleportationTime ?? CampaignTime.Never;
		}

		private void HourlyTick()
		{
			for (int num = _teleportationList.Count - 1; num >= 0; num--)
			{
				TeleportationData teleportationData = _teleportationList[num];
				if (teleportationData.TeleportationTime.IsPast && Campaign.Current.Models.DelayedTeleportationModel.CanPerformImmediateTeleport(teleportationData.TeleportingHero, teleportationData.TargetParty, teleportationData.TargetSettlement))
				{
					TeleportationData data = teleportationData;
					RemoveTeleportationData(teleportationData, isCanceled: false);
					ApplyImmediateTeleport(data);
				}
			}
		}

		private void DailyTickParty(MobileParty mobileParty)
		{
			if (mobileParty.IsActive && mobileParty.Army == null && mobileParty.MapEvent == null && mobileParty.LeaderHero != null && mobileParty.LeaderHero.IsNoncombatant && mobileParty.LeaderHero.DeathMark == KillCharacterAction.KillCharacterActionDetail.None && mobileParty.ActualClan != null && mobileParty.ActualClan != Clan.PlayerClan && mobileParty.ActualClan.Leader != mobileParty.LeaderHero && !mobileParty.IsInRaftState && (!mobileParty.IsCurrentlyAtSea || mobileParty.CurrentSettlement != null))
			{
				MBList<Hero> mBList = mobileParty.ActualClan.Heroes.WhereQ((Hero h) => h.IsActive && h.IsCommander && h.PartyBelongedTo == null).ToMBList();
				if (!mBList.IsEmpty())
				{
					Hero leaderHero = mobileParty.LeaderHero;
					mobileParty.RemovePartyLeader();
					MakeHeroFugitiveAction.Apply(leaderHero);
					TeleportHeroAction.ApplyDelayedTeleportToPartyAsPartyLeader(mBList.GetRandomElementInefficiently(), mobileParty);
				}
			}
		}

		private void OnHeroComesOfAge(Hero hero)
		{
			if (hero.Clan == Clan.PlayerClan || hero.IsNoncombatant)
			{
				return;
			}
			foreach (WarPartyComponent warPartyComponent in hero.Clan.WarPartyComponents)
			{
				MobileParty mobileParty = warPartyComponent.MobileParty;
				if (mobileParty != null && mobileParty.Army == null && mobileParty.MapEvent == null && mobileParty.LeaderHero != null && mobileParty.LeaderHero.IsNoncombatant && (!mobileParty.IsCurrentlyAtSea || mobileParty.CurrentSettlement != null))
				{
					Hero leaderHero = mobileParty.LeaderHero;
					mobileParty.RemovePartyLeader();
					MakeHeroFugitiveAction.Apply(leaderHero);
					TeleportHeroAction.ApplyDelayedTeleportToPartyAsPartyLeader(hero, warPartyComponent.Party.MobileParty);
					break;
				}
			}
		}

		private void OnMobilePartyDestroyed(MobileParty mobileParty, PartyBase destroyerParty)
		{
			for (int num = _teleportationList.Count - 1; num >= 0; num--)
			{
				TeleportationData teleportationData = _teleportationList[num];
				if (teleportationData.TargetParty != null && teleportationData.TargetParty == mobileParty)
				{
					RemoveTeleportationData(teleportationData, isCanceled: true, disbandTargetParty: false);
				}
			}
		}

		private void OnSettlementOwnerChanged(Settlement settlement, bool openToClaim, Hero newOwner, Hero oldOwner, Hero capturerHero, ChangeOwnerOfSettlementAction.ChangeOwnerOfSettlementDetail detail)
		{
			for (int num = _teleportationList.Count - 1; num >= 0; num--)
			{
				TeleportationData teleportationData = _teleportationList[num];
				if (teleportationData.TargetSettlement != null && teleportationData.TargetSettlement == settlement && newOwner.Clan != teleportationData.TeleportingHero.Clan)
				{
					RemoveTeleportationData(teleportationData, isCanceled: true);
				}
			}
		}

		private void OnHeroKilled(Hero victim, Hero killer, KillCharacterAction.KillCharacterActionDetail detail, bool showNotification = true)
		{
			for (int num = _teleportationList.Count - 1; num >= 0; num--)
			{
				TeleportationData teleportationData = _teleportationList[num];
				if (teleportationData.TeleportingHero == victim)
				{
					RemoveTeleportationData(teleportationData, isCanceled: true);
				}
			}
		}

		private void OnPartyDisbandStarted(MobileParty disbandParty)
		{
			if (disbandParty.ActualClan == Clan.PlayerClan && disbandParty.LeaderHero == null && (disbandParty.IsLordParty || disbandParty.IsCaravan) && !disbandParty.IsCurrentlyAtSea)
			{
				Campaign.Current.CampaignInformationManager.NewMapNoticeAdded(new PartyLeaderChangeNotification(disbandParty, _partyLeaderChangeNotificationText));
			}
			for (int num = _teleportationList.Count - 1; num >= 0; num--)
			{
				TeleportationData teleportationData = _teleportationList[num];
				if (teleportationData.TargetParty != null && teleportationData.TargetParty == disbandParty)
				{
					RemoveTeleportationData(teleportationData, isCanceled: true, disbandTargetParty: false);
				}
			}
		}

		private void OnGovernorChanged(Town fortification, Hero oldGovernor, Hero newGovernor)
		{
			for (int num = _teleportationList.Count - 1; num >= 0; num--)
			{
				TeleportationData teleportationData = _teleportationList[num];
				if (teleportationData.TeleportingHero != newGovernor && teleportationData.IsGovernor && teleportationData.TargetSettlement.Town == fortification)
				{
					teleportationData.IsGovernor = false;
				}
			}
		}

		private void OnHeroTeleportationRequested(Hero hero, Settlement targetSettlement, MobileParty targetParty, TeleportHeroAction.TeleportationDetail detail)
		{
			switch (detail)
			{
			case TeleportHeroAction.TeleportationDetail.DelayedTeleportToSettlement:
			case TeleportHeroAction.TeleportationDetail.DelayedTeleportToSettlementAsGovernor:
				_teleportationList.Add(new TeleportationData(hero, targetSettlement, detail == TeleportHeroAction.TeleportationDetail.DelayedTeleportToSettlementAsGovernor));
				break;
			case TeleportHeroAction.TeleportationDetail.DelayedTeleportToPartyAsPartyLeader:
			{
				for (int num2 = _teleportationList.Count - 1; num2 >= 0; num2--)
				{
					TeleportationData teleportationData2 = _teleportationList[num2];
					if (teleportationData2.TargetParty == targetParty && teleportationData2.IsPartyLeader)
					{
						RemoveTeleportationData(teleportationData2, isCanceled: true, disbandTargetParty: false);
					}
				}
				goto case TeleportHeroAction.TeleportationDetail.DelayedTeleportToParty;
			}
			case TeleportHeroAction.TeleportationDetail.DelayedTeleportToParty:
				_teleportationList.Add(new TeleportationData(hero, targetParty, detail == TeleportHeroAction.TeleportationDetail.DelayedTeleportToPartyAsPartyLeader));
				break;
			case TeleportHeroAction.TeleportationDetail.ImmediateTeleportToSettlement:
			{
				for (int num = _teleportationList.Count - 1; num >= 0; num--)
				{
					TeleportationData teleportationData = _teleportationList[num];
					if (hero == teleportationData.TeleportingHero && teleportationData.TargetSettlement == targetSettlement)
					{
						RemoveTeleportationData(teleportationData, isCanceled: true, disbandTargetParty: false);
					}
				}
				break;
			}
			}
		}

		private void OnPartyDisbanded(MobileParty disbandParty, Settlement relatedSettlement)
		{
			for (int num = _teleportationList.Count - 1; num >= 0; num--)
			{
				TeleportationData teleportationData = _teleportationList[num];
				if (teleportationData.TargetParty != null && teleportationData.TargetParty == disbandParty)
				{
					RemoveTeleportationData(teleportationData, isCanceled: true);
				}
			}
		}

		private void OnClanLeaderChanged(Hero oldLeader, Hero newLeader)
		{
			for (int num = _teleportationList.Count - 1; num >= 0; num--)
			{
				TeleportationData teleportationData = _teleportationList[num];
				if (teleportationData.TeleportingHero == newLeader && !teleportationData.IsPartyLeader)
				{
					RemoveTeleportationData(teleportationData, isCanceled: true);
				}
			}
		}

		private void HeroPrisonerTaken(PartyBase capturer, Hero prisoner)
		{
			for (int num = _teleportationList.Count - 1; num >= 0; num--)
			{
				TeleportationData teleportationData = _teleportationList[num];
				if (teleportationData.TeleportingHero == prisoner)
				{
					RemoveTeleportationData(teleportationData, isCanceled: true);
				}
			}
		}

		private void RemoveTeleportationData(TeleportationData data, bool isCanceled, bool disbandTargetParty = true)
		{
			_teleportationList.Remove(data);
			if (!isCanceled)
			{
				return;
			}
			if (data.TeleportingHero.IsTraveling && data.TeleportingHero.DeathMark == KillCharacterAction.KillCharacterActionDetail.None)
			{
				MakeHeroFugitiveAction.Apply(data.TeleportingHero);
			}
			if (data.TargetParty == null)
			{
				return;
			}
			if (data.TargetParty.ActualClan == Clan.PlayerClan)
			{
				CampaignEventDispatcher.Instance.OnPartyLeaderChangeOfferCanceled(data.TargetParty);
			}
			if (disbandTargetParty && data.TargetParty.IsActive && data.IsPartyLeader)
			{
				IDisbandPartyCampaignBehavior behavior = Campaign.Current.CampaignBehaviorManager.GetBehavior<IDisbandPartyCampaignBehavior>();
				if (behavior != null && !behavior.IsPartyWaitingForDisband(data.TargetParty))
				{
					DisbandPartyAction.StartDisband(data.TargetParty);
				}
			}
		}

		private void ApplyImmediateTeleport(TeleportationData data)
		{
			if (data.TargetSettlement != null)
			{
				if (data.IsGovernor)
				{
					data.TargetSettlement.Town.Governor = data.TeleportingHero;
					TeleportHeroAction.ApplyImmediateTeleportToSettlement(data.TeleportingHero, data.TargetSettlement);
				}
				else
				{
					TeleportHeroAction.ApplyImmediateTeleportToSettlement(data.TeleportingHero, data.TargetSettlement);
				}
			}
			else if (data.TargetParty != null)
			{
				if (data.IsPartyLeader)
				{
					TeleportHeroAction.ApplyImmediateTeleportToPartyAsPartyLeader(data.TeleportingHero, data.TargetParty);
				}
				else
				{
					TeleportHeroAction.ApplyImmediateTeleportToParty(data.TeleportingHero, data.TargetParty);
				}
			}
		}
	}
	public class TownSecurityCampaignBehavior : CampaignBehaviorBase
	{
		public override void RegisterEvents()
		{
			CampaignEvents.MapEventEnded.AddNonSerializedListener(this, MapEventEnded);
			CampaignEvents.OnSiegeEventEndedEvent.AddNonSerializedListener(this, SiegeEventEnded);
			CampaignEvents.OnHideoutDeactivatedEvent.AddNonSerializedListener(this, OnHideoutDeactivated);
		}

		private void OnHideoutDeactivated(Settlement hideout)
		{
			SettlementSecurityModel model = Campaign.Current.Models.SettlementSecurityModel;
			foreach (Settlement item in Settlement.All.Where((Settlement t) => t.IsTown && t.Position.DistanceSquared(hideout.Position) < model.HideoutClearedSecurityEffectRadius * model.HideoutClearedSecurityEffectRadius).ToList())
			{
				item.Town.Security += model.HideoutClearedSecurityGain;
			}
		}

		private void MapEventEnded(MapEvent mapEvent)
		{
			if (!mapEvent.IsFieldBattle || !mapEvent.HasWinner)
			{
				return;
			}
			SettlementSecurityModel model = Campaign.Current.Models.SettlementSecurityModel;
			foreach (Settlement town in Settlement.All.Where((Settlement t) => t.IsTown && t.Position.DistanceSquared(mapEvent.Position) < model.MapEventSecurityEffectRadius * model.MapEventSecurityEffectRadius).ToList())
			{
				if (mapEvent.Winner.Parties.Any((MapEventParty party) => party.Party.IsMobile && party.Party.MobileParty.IsBandit) && mapEvent.InvolvedParties.Any((PartyBase party) => ValidCivilianPartyCondition(party, mapEvent, town.MapFaction)))
				{
					float sumOfAttackedPartyStrengths = mapEvent.StrengthOfSide[(int)mapEvent.DefeatedSide];
					town.Town.Security += model.GetLootedNearbyPartySecurityEffect(town.Town, sumOfAttackedPartyStrengths);
				}
				else if (mapEvent.InvolvedParties.Any((PartyBase party) => ValidBanditPartyCondition(party, mapEvent)))
				{
					float sumOfAttackedPartyStrengths2 = mapEvent.StrengthOfSide[(int)mapEvent.DefeatedSide];
					town.Town.Security += model.GetNearbyBanditPartyDefeatedSecurityEffect(town.Town, sumOfAttackedPartyStrengths2);
				}
			}
		}

		private bool ValidCivilianPartyCondition(PartyBase party, MapEvent mapEvent, IFaction mapFaction)
		{
			if (party.IsMobile)
			{
				if (party.Side == mapEvent.WinningSide || !party.MobileParty.IsVillager || !DiplomacyHelper.IsSameFactionAndNotEliminated(party.MapFaction, mapFaction))
				{
					if (party.MobileParty.IsCaravan)
					{
						return !party.MapFaction.IsAtWarWith(mapFaction);
					}
					return false;
				}
				return true;
			}
			return false;
		}

		private bool ValidBanditPartyCondition(PartyBase party, MapEvent mapEvent)
		{
			if (party.Side != mapEvent.WinningSide)
			{
				return party.MobileParty?.IsBandit ?? false;
			}
			return false;
		}

		private void SiegeEventEnded(SiegeEvent siegeEvent)
		{
		}

		public override void SyncData(IDataStore dataStore)
		{
		}
	}
	public class TradeAgreementsCampaignBehavior : CampaignBehaviorBase, ITradeAgreementsCampaignBehavior
	{
		public class TradeAgreementsCampaignBehaviorTypeDefiner : SaveableTypeDefiner
		{
			public TradeAgreementsCampaignBehaviorTypeDefiner()
				: base(312260)
			{
			}

			protected override void DefineStructTypes()
			{
				AddStructDefinition(typeof(TradeAgreement), 1);
			}

			protected override void DefineContainerDefinitions()
			{
				ConstructContainerDefinition(typeof(List<TradeAgreement>));
			}
		}

		public struct TradeAgreement
		{
			[SaveableField(1)]
			public readonly Kingdom Kingdom1;

			[SaveableField(2)]
			public readonly Kingdom Kingdom2;

			[SaveableField(3)]
			public readonly CampaignTime EndTime;

			[SaveableField(4)]
			public int Kingdom1GoldGained;

			[SaveableField(5)]
			public int Kingdom2GoldGained;

			[SaveableField(6)]
			public int Kingdom1GoldGainedTotal;

			[SaveableField(7)]
			public int Kingdom2GoldGainedTotal;

			public TradeAgreement(Kingdom kingdom1, Kingdom kingdom2, CampaignTime endTime)
			{
				this = default(TradeAgreement);
				Kingdom1 = kingdom1;
				Kingdom2 = kingdom2;
				EndTime = endTime;
				Kingdom1GoldGained = 0;
				Kingdom2GoldGained = 0;
				Kingdom1GoldGainedTotal = 0;
				Kingdom2GoldGainedTotal = 0;
			}

			public TradeAgreement AddGainedGoldToKingdom(Kingdom kingdom, int gold)
			{
				if (kingdom == Kingdom1)
				{
					Kingdom1GoldGained += gold;
					Kingdom1GoldGainedTotal += gold;
				}
				else
				{
					Kingdom2GoldGained += gold;
					Kingdom2GoldGainedTotal += gold;
				}
				return this;
			}

			public TradeAgreement OnGoldSharedInKingdom(Kingdom kingdom, int gold)
			{
				if (kingdom == Kingdom1)
				{
					Kingdom1GoldGained -= gold;
				}
				else
				{
					Kingdom2GoldGained -= gold;
				}
				return this;
			}

			public static void AutoGeneratedStaticCollectObjectsTradeAgreement(object o, List<object> collectedObjects)
			{
				((TradeAgreement)o).AutoGeneratedInstanceCollectObjects(collectedObjects);
			}

			private void AutoGeneratedInstanceCollectObjects(List<object> collectedObjects)
			{
				collectedObjects.Add(Kingdom1);
				collectedObjects.Add(Kingdom2);
				CampaignTime.AutoGeneratedStaticCollectObjectsCampaignTime(EndTime, collectedObjects);
			}

