					}
				}
				float num5 = TaleWorlds.Library.MathF.Sqrt(num3);
				float num6 = Campaign.Current.EstimatedAverageLordPartySpeed * (float)CampaignTime.HoursInDay;
				num2 = ((num5 < num6 * 0.5f) ? (1f - TaleWorlds.Library.MathF.Max(0f, num5 - num6 * 0.15f) / num6 * 0.3f) : 0f);
			}
			if (!flag && !(num2 > 0f))
