				{
					StringHelpers.SetCharacterProperties("HERO", _otherHero.CharacterObject);
					textObject = new TextObject("{=BJbbahYe}Let {HERO.NAME} Go");
				}
				else
				{
					textObject = new TextObject("{=QKNWsJRb}Let {PARTY} Go");
