			get
			{
				Banner banner = _banner;
				if (banner == null)
				{
					if (Party == null)
					{
						if (!_troop.IsHero)
						{
							return null;
						}
						return _troop.HeroObject.MapFaction.Banner;
					}
					if (Party.LeaderHero == null)
					{
						return Party.MapFaction.Banner;
					}
					banner = Party.LeaderHero.ClanBanner;
				}
				return banner;
			}
		}

