namespace TaleWorlds.CampaignSystem.Actions
{
	public static class AddCompanionAction
	{
		private static void ApplyInternal(Clan clan, Hero companion)
		{
			if (companion.CompanionOf != null)
			{
				RemoveCompanionAction.ApplyByFire(companion.CompanionOf, companion);
			}
			companion.CompanionOf = clan;
			CampaignEventDispatcher.Instance.OnNewCompanionAdded(companion);
		}

		public static void Apply(Clan clan, Hero companion)
		{
			ApplyInternal(clan, companion);
		}
	}
	public static class AddHeroToPartyAction
	{
		private static void ApplyInternal(Hero hero, MobileParty newParty, bool showNotification = true)
		{
			hero.PartyBelongedTo?.MemberRoster.AddToCounts(hero.CharacterObject, -1);
			hero.StayingInSettlement = null;
			_ = hero.IsNotable;
			if (hero.GovernorOf != null)
			{
				ChangeGovernorAction.RemoveGovernorOf(hero);
			}
			newParty.AddElementToMemberRoster(hero.CharacterObject, 1);
			CampaignEventDispatcher.Instance.OnHeroJoinedParty(hero, newParty);
			if (showNotification && newParty == MobileParty.MainParty && hero.IsPlayerCompanion)
			{
				TextObject textObject = GameTexts.FindText("str_companion_added");
				StringHelpers.SetCharacterProperties("COMPANION", hero.CharacterObject, textObject);
				MBInformationManager.AddQuickInformation(textObject);
			}
		}

		public static void Apply(Hero hero, MobileParty party, bool showNotification = true)
		{
			ApplyInternal(hero, party, showNotification);
		}
	}
	public static class AdoptHeroAction
	{
		private static void ApplyInternal(Hero adoptedHero)
		{
			if (Hero.MainHero.IsFemale)
			{
				adoptedHero.Mother = Hero.MainHero;
			}
			else
			{
				adoptedHero.Father = Hero.MainHero;
			}
			adoptedHero.Clan = Clan.PlayerClan;
		}

		public static void Apply(Hero adoptedHero)
		{
			ApplyInternal(adoptedHero);
		}
	}
	public static class ApplyHeirSelectionAction
	{
		private static void ApplyInternal(Hero heir, bool isRetirement = false)
		{
			if (heir.PartyBelongedTo != null && heir.PartyBelongedTo.IsCaravan)
			{
				Settlement settlement = SettlementHelper.FindNearestSettlementToMobileParty(heir.PartyBelongedTo, MobileParty.NavigationType.All, (Settlement s) => (s.IsTown || s.IsCastle) && !FactionManager.IsAtWarAgainstFaction(s.MapFaction, heir.MapFaction));
				if (settlement == null)
				{
					settlement = SettlementHelper.FindNearestSettlementToMobileParty(heir.PartyBelongedTo, MobileParty.NavigationType.All, (Settlement s) => s.IsVillage || (!s.IsHideout && !s.IsFortification));
				}
				DestroyPartyAction.Apply(null, heir.PartyBelongedTo);
				TeleportHeroAction.ApplyImmediateTeleportToSettlement(heir, settlement);
			}
			TransferCaravanOwnerships(heir);
			ChangeClanLeaderAction.ApplyWithSelectedNewLeader(Clan.PlayerClan, heir);
			if (isRetirement)
			{
				DisableHeroAction.Apply(Hero.MainHero);
				if (heir.PartyBelongedTo != MobileParty.MainParty)
				{
					MobileParty.MainParty.MemberRoster.RemoveTroop(CharacterObject.PlayerCharacter);
				}
				LogEntry.AddLogEntry(new PlayerRetiredLogEntry(Hero.MainHero));
				TextObject textObject = new TextObject("{=0MTzaxau}{?CHARACTER.GENDER}She{?}He{\\?} retired from adventuring, and was last seen with a group of mountain hermits living a life of quiet contemplation.");
				textObject.SetCharacterProperties("CHARACTER", Hero.MainHero.CharacterObject);
				Hero.MainHero.EncyclopediaText = textObject;
			}
			else
			{
				KillCharacterAction.ApplyByDeathMarkForced(Hero.MainHero, showNotification: true);
			}
			if (heir.CurrentSettlement != null && heir.PartyBelongedTo != null)
			{
				LeaveSettlementAction.ApplyForCharacterOnly(heir);
				LeaveSettlementAction.ApplyForParty(heir.PartyBelongedTo);
			}
			for (int num = Hero.MainHero.OwnedWorkshops.Count - 1; num >= 0; num--)
			{
				ChangeOwnerOfWorkshopAction.ApplyByDeath(Hero.MainHero.OwnedWorkshops[num], heir);
			}
			if (heir.PartyBelongedTo != MobileParty.MainParty)
			{
				for (int num2 = MobileParty.MainParty.MemberRoster.Count - 1; num2 >= 0; num2--)
				{
					TroopRosterElement elementCopyAtIndex = MobileParty.MainParty.MemberRoster.GetElementCopyAtIndex(num2);
					if (elementCopyAtIndex.Character.IsHero && elementCopyAtIndex.Character.HeroObject != Hero.MainHero)
					{
						MakeHeroFugitiveAction.Apply(elementCopyAtIndex.Character.HeroObject);
					}
				}
			}
			if (MobileParty.MainParty.Army != null)
			{
				DisbandArmyAction.ApplyByUnknownReason(MobileParty.MainParty.Army);
			}
			ChangePlayerCharacterAction.Apply(heir);
			Campaign.Current.TimeControlMode = CampaignTimeControlMode.Stop;
		}

		public static void ApplyByDeath(Hero heir)
		{
			ApplyInternal(heir);
		}

		public static void ApplyByRetirement(Hero heir)
		{
			ApplyInternal(heir, isRetirement: true);
		}

		private static void TransferCaravanOwnerships(Hero newLeader)
		{
			foreach (Hero hero in Clan.PlayerClan.Heroes)
			{
				if (hero.PartyBelongedTo != null && hero.PartyBelongedTo.IsCaravan)
				{
					CaravanPartyComponent.TransferCaravanOwnership(hero.PartyBelongedTo, newLeader, hero.PartyBelongedTo.HomeSettlement);
				}
			}
		}
	}
	public static class BeHostileAction
	{
		private const float MinorCoercionValue = 1f;

		private const float MajorCoercionValue = 2f;

		private const float EncounterValue = 6f;

		private static void ApplyInternal(PartyBase attackerParty, PartyBase defenderParty, float value)
		{
			if (defenderParty.IsMobile && defenderParty.MobileParty.MapFaction == null)
			{
				return;
			}
			int num = (int)(-1f * value);
			int relationChange = (int)(-5f * value);
			int relationChange2 = (int)(-1f * value);
			int num2 = (int)(-4f * value);
			int relationChange3 = (int)(-4f * value);
			int num3 = (int)(-10f * value);
			int num4 = (int)(-2f * value);
			bool flag = attackerParty.MapFaction.IsAtWarWith(defenderParty.MapFaction);
			Hero leaderHero = attackerParty.LeaderHero;
			if (defenderParty.IsSettlement)
			{
				if (!defenderParty.Settlement.IsVillage || flag)
				{
					return;
				}
				if (num2 < 0)
				{
					ChangeRelationAction.ApplyRelationChangeBetweenHeroes(leaderHero, defenderParty.Settlement.OwnerClan.Leader, num2);
					foreach (Hero notable in defenderParty.Settlement.Notables)
					{
						ChangeRelationAction.ApplyRelationChangeBetweenHeroes(leaderHero, notable, relationChange3);
					}
				}
				ApplyGeneralConsequencesOnPeace(attackerParty, defenderParty, value);
			}
			else
			{
				if (defenderParty.MobileParty == null)
				{
					return;
				}
				if (defenderParty.MobileParty.IsVillager)
				{
					if (flag)
					{
						foreach (Hero notable2 in defenderParty.MobileParty.HomeSettlement.Notables)
						{
							ChangeRelationAction.ApplyRelationChangeBetweenHeroes(leaderHero, notable2, relationChange2);
						}
						return;
					}
					if (num < 0)
					{
						ChangeRelationAction.ApplyRelationChangeBetweenHeroes(leaderHero, defenderParty.MobileParty.HomeSettlement.OwnerClan.Leader, num);
						foreach (Hero notable3 in defenderParty.MobileParty.HomeSettlement.Notables)
						{
							ChangeRelationAction.ApplyRelationChangeBetweenHeroes(leaderHero, notable3, relationChange);
						}
					}
					ApplyGeneralConsequencesOnPeace(attackerParty, defenderParty, value);
				}
				else
				{
					if (!defenderParty.MobileParty.IsCaravan)
					{
						return;
					}
					if (flag)
					{
						if (num4 < 0 && defenderParty.Owner != null)
						{
							ChangeRelationAction.ApplyRelationChangeBetweenHeroes(leaderHero, defenderParty.Owner, num4);
						}
						return;
					}
					if (num3 < 0 && defenderParty.Owner != null)
					{
						ChangeRelationAction.ApplyRelationChangeBetweenHeroes(leaderHero, defenderParty.Owner, num3);
					}
					ApplyGeneralConsequencesOnPeace(attackerParty, defenderParty, value);
				}
			}
		}

		private static void ApplyGeneralConsequencesOnPeace(PartyBase attackerParty, PartyBase defenderParty, float value)
		{
			float num = -25f * value;
			float num2 = 10f * value;
			int num3 = (int)(-2f * value);
			float num4 = -50f * value;
			bool isClan = attackerParty.MapFaction.IsClan;
			bool isKingdomLeader = attackerParty.LeaderHero.IsKingdomLeader;
			bool isUnderMercenaryService = attackerParty.LeaderHero.Clan.IsUnderMercenaryService;
			Hero leaderHero = attackerParty.LeaderHero;
			if (leaderHero.Equals(Hero.MainHero))
			{
				if (num < 0f)
				{
					TraitLevelingHelper.OnHostileAction((int)num);
				}
				if (num2 > 0f)
				{
					ChangeCrimeRatingAction.Apply(defenderParty.MapFaction, num2);
				}
			}
			if (isClan)
			{
				return;
			}
			if (isKingdomLeader)
			{
				if (num4 < 0f)
				{
					GainKingdomInfluenceAction.ApplyForDefault(attackerParty.MobileParty.LeaderHero, num4);
				}
			}
			else if (isUnderMercenaryService)
			{
				if (num3 < 0)
				{
					ChangeRelationAction.ApplyRelationChangeBetweenHeroes(leaderHero, leaderHero.MapFaction.Leader, num3);
				}
				if (value.ApproximatelyEqualsTo(6f))
				{
					ChangeKingdomAction.ApplyByLeaveKingdomAsMercenary(leaderHero.Clan);
				}
			}
			else
			{
				if (num3 < 0 && attackerParty.MapFaction != null && defenderParty.MapFaction != null)
				{
					ChangeRelationAction.ApplyRelationChangeBetweenHeroes(leaderHero, defenderParty.MapFaction.Leader, num3);
				}
				if (num4 < 0f)
				{
					GainKingdomInfluenceAction.ApplyForDefault(attackerParty.MobileParty.LeaderHero, num4);
				}
			}
		}

