	public static class DestroyClanAction
	{
		private enum DestroyClanActionDetails
		{
			Default,
			RebellionFailure,
			ClanLeaderDeath
		}

		private static void ApplyInternal(Clan destroyedClan, DestroyClanActionDetails details)
		{
			CampaignEventDispatcher.Instance.OnClanDestroyed(destroyedClan);
			destroyedClan.DeactivateClan();
			foreach (WarPartyComponent item in destroyedClan.WarPartyComponents.ToList())
			{
				PartyBase destroyerParty = null;
				if (item.MobileParty.MapEvent != null)
				{
					destroyerParty = item.MobileParty.MapEventSide.OtherSide.LeaderParty;
					if (item.MobileParty.MapEvent != MobileParty.MainParty.MapEvent)
					{
						item.MobileParty.MapEventSide = null;
					}
				}
				DestroyPartyAction.Apply(destroyerParty, item.MobileParty);
			}
			List<Hero> list = destroyedClan.Heroes.Where((Hero x) => x.IsAlive).ToList();
			for (int i = 0; i < list.Count; i++)
			{
				Hero hero = list[i];
				if (details != DestroyClanActionDetails.ClanLeaderDeath || hero != destroyedClan.Leader)
				{
					KillCharacterAction.ApplyByRemove(hero);
				}
			}
			if (details != DestroyClanActionDetails.ClanLeaderDeath && destroyedClan.Leader != null && destroyedClan.Leader.IsAlive && destroyedClan.Leader.DeathMark == KillCharacterAction.KillCharacterActionDetail.None)
			{
				KillCharacterAction.ApplyByRemove(destroyedClan.Leader);
			}
			if (!destroyedClan.Settlements.IsEmpty())
			{
				Clan clan = FactionHelper.ChooseHeirClanForFiefs(destroyedClan);
				foreach (Settlement item2 in destroyedClan.Settlements.ToList())
				{
					if (item2.IsTown || item2.IsCastle)
					{
						Hero randomElementWithPredicate = clan.AliveLords.GetRandomElementWithPredicate((Hero x) => !x.IsChild);
						ChangeOwnerOfSettlementAction.ApplyByDestroyClan(item2, randomElementWithPredicate);
					}
				}
			}
			FactionManager.Instance.RemoveFactionsFromCampaignWars(destroyedClan);
			if (destroyedClan.Kingdom != null)
			{
				ChangeKingdomAction.ApplyByLeaveKingdomByClanDestruction(destroyedClan);
			}
			if (destroyedClan.IsRebelClan)
			{
				Campaign.Current.CampaignObjectManager.RemoveClan(destroyedClan);
			}
		}

		public static void Apply(Clan destroyedClan)
		{
			ApplyInternal(destroyedClan, DestroyClanActionDetails.Default);
		}

		public static void ApplyByFailedRebellion(Clan failedRebellionClan)
		{
			ApplyInternal(failedRebellionClan, DestroyClanActionDetails.RebellionFailure);
		}

		public static void ApplyByClanLeaderDeath(Clan destroyedClan)
		{
			ApplyInternal(destroyedClan, DestroyClanActionDetails.ClanLeaderDeath);
		}
	}
	public static class DestroyKingdomAction
	{
		private static void ApplyInternal(Kingdom destroyedKingdom, bool isKingdomLeaderDeath = false)
		{
			destroyedKingdom.DeactivateKingdom();
			foreach (Clan item in destroyedKingdom.Clans.ToList())
			{
				if (!item.IsEliminated)
				{
					if (isKingdomLeaderDeath)
					{
						DestroyClanAction.ApplyByClanLeaderDeath(item);
					}
					else
					{
						DestroyClanAction.Apply(item);
					}
					destroyedKingdom.RemoveClanInternal(item);
				}
			}
			Campaign.Current.FactionManager.RemoveFactionsFromCampaignWars(destroyedKingdom);
			CampaignEventDispatcher.Instance.OnKingdomDestroyed(destroyedKingdom);
		}

		public static void Apply(Kingdom destroyedKingdom)
		{
			ApplyInternal(destroyedKingdom);
		}

		public static void ApplyByKingdomLeaderDeath(Kingdom destroyedKingdom)
		{
			ApplyInternal(destroyedKingdom, isKingdomLeaderDeath: true);
		}
	}
	public static class DestroyPartyAction
	{
		private static void ApplyInternal(PartyBase destroyerParty, MobileParty destroyedParty)
		{
			if (destroyedParty != MobileParty.MainParty)
			{
				if (!destroyedParty.IsActive)
				{
					TaleWorlds.Library.Debug.Print("Trying to destroy an inactive party with id: " + destroyedParty.StringId);
					TaleWorlds.Library.Debug.FailedAssert("destroyedParty.IsActive", "C:\\BuildAgent\\work\\mb3\\Source\\Bannerlord\\TaleWorlds.CampaignSystem\\Actions\\DestroyPartyAction.cs", "ApplyInternal", 17);
				}
				if (destroyedParty.IsCaravan && destroyedParty.Party.Owner != null && destroyedParty.Party.Owner.GetPerkValue(DefaultPerks.Trade.InsurancePlans))
				{
					GiveGoldAction.ApplyBetweenCharacters(null, destroyedParty.Party.Owner, (int)DefaultPerks.Trade.InsurancePlans.PrimaryBonus);
				}
				CampaignEventDispatcher.Instance.OnMobilePartyDestroyed(destroyedParty, destroyerParty);
				CampaignEventDispatcher.Instance.OnMapInteractableDestroyed(destroyedParty.Party);
				destroyedParty.RemoveParty();
			}
		}

		public static void Apply(PartyBase destroyerParty, MobileParty destroyedParty)
		{
			ApplyInternal(destroyerParty, destroyedParty);
		}

		public static void ApplyForDisbanding(MobileParty disbandedParty, Settlement relatedSettlement)
		{
			if (disbandedParty.CurrentSettlement != null)
			{
				LeaveSettlementAction.ApplyForParty(disbandedParty);
			}
			CampaignEventDispatcher.Instance.OnPartyDisbanded(disbandedParty, relatedSettlement);
			ApplyInternal(null, disbandedParty);
		}
	}
