	public static class EnterSettlementAction
	{
		private enum EnterSettlementDetail
		{
			WarParty,
			PartyEntersAlley,
			Character,
			Prisoner
		}

		private static void ApplyInternal(Hero hero, MobileParty mobileParty, Settlement settlement, EnterSettlementDetail detail, object subject = null, bool isPlayerInvolved = false)
		{
			if (mobileParty != null && mobileParty.IsDisbanding && mobileParty.TargetSettlement == settlement)
			{
				DestroyPartyAction.ApplyForDisbanding(mobileParty, settlement);
			}
			else
			{
				CampaignEventDispatcher.Instance.OnBeforeSettlementEntered(mobileParty, settlement, hero);
				CampaignEventDispatcher.Instance.OnSettlementEntered(mobileParty, settlement, hero);
				CampaignEventDispatcher.Instance.OnAfterSettlementEntered(mobileParty, settlement, hero);
				if (detail == EnterSettlementDetail.Prisoner)
				{
					if (hero != null)
					{
						CampaignEventDispatcher.Instance.OnPrisonersChangeInSettlement(settlement, null, hero, takenFromDungeon: false);
					}
					if (mobileParty != null)
					{
						CampaignEventDispatcher.Instance.OnPrisonersChangeInSettlement(settlement, mobileParty.PrisonRoster.ToFlattenedRoster(), null, takenFromDungeon: false);
					}
				}
				Hero hero2 = ((mobileParty != null) ? mobileParty.LeaderHero : hero);
				if (hero2 != null)
				{
					float currentTime = Campaign.CurrentTime;
					if (hero2.Clan == settlement.OwnerClan && hero2.Clan?.Leader == hero2)
					{
						settlement.LastVisitTimeOfOwner = currentTime;
					}
				}
				if (mobileParty == MobileParty.MainParty && MobileParty.MainParty.Army != null && MobileParty.MainParty.Army.LeaderParty == MobileParty.MainParty)
				{
					foreach (MobileParty attachedParty in MobileParty.MainParty.Army.LeaderParty.AttachedParties)
					{
						ApplyForParty(attachedParty, settlement);
					}
				}
				if (hero != null && mobileParty == null && hero.PartyBelongedTo == null && hero.PartyBelongedToAsPrisoner == null && hero.Clan == Clan.PlayerClan && hero.GovernorOf == null)
				{
					CampaignEventDispatcher.Instance.OnHeroGetsBusy(hero, HeroGetsBusyReasons.BecomeEmissary);
				}
			}
			if (mobileParty != null && mobileParty.IsFleeing())
			{
				mobileParty.Ai.DisableForHours(5);
			}
			if (hero == Hero.MainHero || mobileParty == MobileParty.MainParty)
			{
				TaleWorlds.Library.Debug.Print($"Player has entered {settlement.StringId}: {settlement}");
			}
		}

		public static void ApplyForParty(MobileParty mobileParty, Settlement settlement)
		{
			if (mobileParty != null && mobileParty.Army != null && mobileParty.Army.LeaderParty != null && mobileParty.Army.LeaderParty != mobileParty && mobileParty.Army.LeaderParty.CurrentSettlement == settlement && mobileParty.AttachedTo == null)
			{
				mobileParty.Army.AddPartyToMergedParties(mobileParty);
			}
			bool isCurrentlyAtSea = mobileParty.IsCurrentlyAtSea;
			if (!settlement.IsVillage && mobileParty.HasLandNavigationCapability)
			{
				mobileParty.IsCurrentlyAtSea = false;
			}
			mobileParty.CurrentSettlement = settlement;
			if (isCurrentlyAtSea && !mobileParty.IsCurrentlyAtSea && mobileParty.Ships.Any() && !mobileParty.Anchor.IsAtSettlement(settlement))
			{
				mobileParty.Anchor.SetSettlement(settlement);
			}
			settlement.SettlementComponent.OnPartyEntered(mobileParty);
			ApplyInternal(mobileParty.LeaderHero, mobileParty, settlement, EnterSettlementDetail.WarParty);
		}

		public static void ApplyForPartyEntersAlley(MobileParty party, Settlement settlement, Alley alley, bool isPlayerInvolved = false)
		{
			ApplyInternal(null, party, settlement, EnterSettlementDetail.PartyEntersAlley, alley, isPlayerInvolved);
		}

		public static void ApplyForCharacterOnly(Hero hero, Settlement settlement)
		{
			hero.StayingInSettlement = settlement;
			ApplyInternal(hero, null, settlement, EnterSettlementDetail.Character);
		}

		public static void ApplyForPrisoner(Hero hero, Settlement settlement)
		{
			hero.ChangeState(Hero.CharacterStates.Prisoner);
			ApplyInternal(hero, null, settlement, EnterSettlementDetail.Prisoner);
		}
	}
	public static class GainKingdomInfluenceAction
	{
		private enum InfluenceGainingReason
		{
			Default,
			BeingAtArmy,
			Battle,
			Raiding,
			Besieging,
			CaptureSettlement,
			JoinFaction,
			GivingFood,
			LeaveGarrison,
			BoardGameWon,
			ClanSupport,
			DonatePrisoners,
			SiegeSafePassage
		}

		private static void ApplyInternal(Hero hero, MobileParty party, float gainedInfluence, InfluenceGainingReason detail)
		{
			Clan clan = null;
			if (hero != null)
			{
				if (hero.CompanionOf != null)
				{
					clan = hero.CompanionOf;
				}
				else if (hero.Clan != null)
				{
					clan = hero.Clan;
				}
			}
			else if (party.ActualClan != null)
			{
				clan = party.ActualClan;
			}
			else if (party.Owner != null)
			{
				clan = party.Owner.Clan;
			}
			if (clan == null || clan.Kingdom == null)
			{
				return;
			}
			MobileParty mobileParty = party ?? hero.PartyBelongedTo;
			if (detail != InfluenceGainingReason.BeingAtArmy && detail == InfluenceGainingReason.ClanSupport)
			{
				gainedInfluence = 0.5f;
			}
			if (detail != 0 && detail != InfluenceGainingReason.GivingFood && detail != InfluenceGainingReason.JoinFaction && detail != InfluenceGainingReason.ClanSupport && ((Kingdom)clan.MapFaction).ActivePolicies.Contains(DefaultPolicies.MilitaryCoronae))
			{
				gainedInfluence *= 1.2f;
			}
			ExplainedNumber stat = new ExplainedNumber(gainedInfluence);
			if (detail == InfluenceGainingReason.Battle && gainedInfluence > 0f)
			{
				PerkHelper.AddPerkBonusForParty(DefaultPerks.Tactics.PreBattleManeuvers, mobileParty, isPrimaryBonus: true, ref stat);
			}
			if (detail == InfluenceGainingReason.CaptureSettlement && (hero != null || mobileParty.LeaderHero != null))
			{
				Hero hero2 = hero ?? mobileParty.LeaderHero;
				PerkHelper.AddPerkBonusForCharacter(DefaultPerks.Tactics.Besieged, hero2.CharacterObject, isPrimaryBonus: false, ref stat);
			}
			gainedInfluence = stat.ResultNumber;
			ChangeClanInfluenceAction.Apply(clan, gainedInfluence);
			int num = (int)gainedInfluence;
			if (TaleWorlds.Library.MathF.Abs(num) > 0)
			{
				if ((detail == InfluenceGainingReason.DonatePrisoners && party == MobileParty.MainParty) || (detail == InfluenceGainingReason.Battle && hero == Hero.MainHero))
				{
					TextObject textObject = GameTexts.FindText("str_influence_gain_message");
					textObject.SetTextVariable("INFLUENCE", num);
					textObject.SetTextVariable("NEW_INFLUENCE", (int)clan.Influence);
					InformationManager.DisplayMessage(new InformationMessage(textObject.ToString()));
				}
				if (detail == InfluenceGainingReason.SiegeSafePassage && hero == Hero.MainHero)
				{
					TextObject textObject2 = GameTexts.FindText("str_leave_siege_lose_influence_message");
					textObject2.SetTextVariable("INFLUENCE", -num);
					InformationManager.DisplayMessage(new InformationMessage(textObject2.ToString()));
				}
			}
		}

		public static void ApplyForBattle(Hero hero, float value)
		{
			ApplyInternal(hero, null, value, InfluenceGainingReason.Battle);
		}

		public static void ApplyForGivingFood(Hero hero1, Hero hero2, float value)
		{
			ApplyInternal(hero1, null, value, InfluenceGainingReason.GivingFood);
			ApplyInternal(hero2, null, 0f - value, InfluenceGainingReason.GivingFood);
		}

		public static void ApplyForDefault(Hero hero, float value)
		{
			ApplyInternal(hero, null, value, InfluenceGainingReason.Default);
		}

