	public static class MarriageAction
	{
		private static void ApplyInternal(Hero firstHero, Hero secondHero, bool showNotification)
		{
			if (!Campaign.Current.Models.MarriageModel.IsCoupleSuitableForMarriage(firstHero, secondHero))
			{
				TaleWorlds.Library.Debug.Print("MarriageAction.Apply() called for not suitable couple: " + firstHero.StringId + " and " + secondHero.StringId);
				return;
			}
			firstHero.Spouse = secondHero;
			secondHero.Spouse = firstHero;
			ChangeRelationAction.ApplyRelationChangeBetweenHeroes(firstHero, secondHero, Campaign.Current.Models.MarriageModel.GetEffectiveRelationIncrease(firstHero, secondHero), showQuickNotification: false);
			Clan clanAfterMarriage = Campaign.Current.Models.MarriageModel.GetClanAfterMarriage(firstHero, secondHero);
			if (clanAfterMarriage != firstHero.Clan)
			{
				Hero hero = firstHero;
				firstHero = secondHero;
				secondHero = hero;
			}
			CampaignEventDispatcher.Instance.OnBeforeHeroesMarried(firstHero, secondHero, showNotification);
			if (firstHero.Clan != clanAfterMarriage)
			{
				HandleClanChangeAfterMarriageForHero(firstHero, clanAfterMarriage);
			}
			if (secondHero.Clan != clanAfterMarriage)
			{
				HandleClanChangeAfterMarriageForHero(secondHero, clanAfterMarriage);
			}
			Romance.EndAllCourtships(firstHero);
			Romance.EndAllCourtships(secondHero);
			ChangeRomanticStateAction.Apply(firstHero, secondHero, Romance.RomanceLevelEnum.Marriage);
		}

		private static void HandleClanChangeAfterMarriageForHero(Hero hero, Clan clanAfterMarriage)
		{
			Clan clan = hero.Clan;
			if (hero.GovernorOf != null)
			{
				ChangeGovernorAction.RemoveGovernorOf(hero);
			}
			if (hero.PartyBelongedTo != null)
			{
				if (clan.Kingdom != clanAfterMarriage.Kingdom)
				{
					if (hero.PartyBelongedTo.Army != null)
					{
						if (hero.PartyBelongedTo.Army.LeaderParty == hero.PartyBelongedTo)
						{
							DisbandArmyAction.ApplyByUnknownReason(hero.PartyBelongedTo.Army);
						}
						else
						{
							hero.PartyBelongedTo.Army = null;
						}
					}
					IFaction kingdom = clanAfterMarriage.Kingdom;
					FactionHelper.FinishAllRelatedHostileActionsOfNobleToFaction(hero, kingdom ?? clanAfterMarriage);
				}
				MobileParty partyBelongedTo = hero.PartyBelongedTo;
				bool num = hero.PartyBelongedTo.LeaderHero == hero;
				partyBelongedTo.MemberRoster.RemoveTroop(hero.CharacterObject);
				MakeHeroFugitiveAction.Apply(hero);
				if (num && partyBelongedTo.IsLordParty)
				{
					DisbandPartyAction.StartDisband(partyBelongedTo);
				}
			}
			hero.Clan = clanAfterMarriage;
			foreach (Hero hero2 in clan.Heroes)
			{
				hero2.UpdateHomeSettlement();
			}
			foreach (Hero hero3 in clanAfterMarriage.Heroes)
			{
				hero3.UpdateHomeSettlement();
			}
		}

		public static void Apply(Hero firstHero, Hero secondHero, bool showNotification = true)
		{
			ApplyInternal(firstHero, secondHero, showNotification);
		}
	}
	public static class PayForCrimeAction
	{
		private static void ApplyInternal(IFaction faction, CrimeModel.PaymentMethod paymentMethod)
		{
			bool flag = false;
			if (paymentMethod.HasAnyFlag(CrimeModel.PaymentMethod.Gold))
			{
				GiveGoldAction.ApplyBetweenCharacters(Hero.MainHero, null, (int)GetClearCrimeCost(faction, CrimeModel.PaymentMethod.Gold));
				SkillLevelingManager.OnBribeGiven((int)GetClearCrimeCost(faction, CrimeModel.PaymentMethod.Gold));
			}
			if (paymentMethod.HasAnyFlag(CrimeModel.PaymentMethod.Influence))
			{
				ChangeClanInfluenceAction.Apply(Clan.PlayerClan, 0f - GetClearCrimeCost(faction, CrimeModel.PaymentMethod.Influence));
			}
			if (paymentMethod.HasAnyFlag(CrimeModel.PaymentMethod.Punishment))
			{
				if (TaleWorlds.Library.MathF.Clamp(1f - (float)Hero.MainHero.HitPoints * 0.01f, 0.001f, 1f) * 0.25f > MBRandom.RandomFloat)
				{
					flag = true;
					KillCharacterAction.ApplyByMurder(Hero.MainHero);
				}
				else
				{
					Hero.MainHero.MakeWounded();
					float num = 0.5f;
					if (MBRandom.RandomFloat < num)
					{
						SkillLevelingManager.OnMainHeroTortured();
					}
				}
			}
			if (paymentMethod.HasAnyFlag(CrimeModel.PaymentMethod.Execution))
			{
				flag = true;
				KillCharacterAction.ApplyByMurder(Hero.MainHero);
			}
			if (!flag)
			{
				float num2 = TaleWorlds.Library.MathF.Min(faction.MainHeroCrimeRating, Campaign.Current.Models.CrimeModel.GetCrimeRatingAfterPunishment());
				ChangeCrimeRatingAction.Apply(faction, num2 - faction.MainHeroCrimeRating);
			}
		}

		public static float GetClearCrimeCost(IFaction faction, CrimeModel.PaymentMethod paymentMethod)
		{
			return Campaign.Current.Models.CrimeModel.GetCost(faction, paymentMethod, Campaign.Current.Models.CrimeModel.GetMinAcceptableCrimeRating(faction));
		}

		public static void Apply(IFaction faction, CrimeModel.PaymentMethod paymentMethod)
		{
			ApplyInternal(faction, paymentMethod);
		}
	}
	public class RaftStateChangeAction
	{
		private static void ApplyInternal(MobileParty mobileParty, bool isRaftState)
		{
			mobileParty.IsInRaftState = isRaftState;
			if (mobileParty.Army != null)
			{
				mobileParty.Army = null;
			}
			if (isRaftState)
			{
				mobileParty.MovePartyToTheClosestLand();
				mobileParty.Ai.DisableAi();
				if (mobileParty.Party.PrisonRoster.TotalManCount > 0)
				{
					if (mobileParty.Party.PrisonRoster.TotalHeroes > 0)
					{
						foreach (TroopRosterElement item in mobileParty.PrisonRoster.GetTroopRoster())
						{
							if (item.Character.IsHero)
							{
								EndCaptivityAction.ApplyByEscape(item.Character.HeroObject);
							}
						}
					}
					mobileParty.PrisonRoster.Clear();
				}
			}
			else
			{
				mobileParty.Ai.EnableAi();
				mobileParty.RecalculateShortTermBehavior();
				mobileParty.Ai.DefaultBehaviorNeedsUpdate = true;
				mobileParty.Ai.RethinkAtNextHourlyTick = true;
			}
			CampaignEventDispatcher.Instance.OnMobilePartyRaftStateChanged(mobileParty);
		}

		public static void ActivateRaftStateForParty(MobileParty mobileParty)
		{
			ApplyInternal(mobileParty, isRaftState: true);
		}

		public static void DeactivateRaftStateForParty(MobileParty mobileParty)
		{
			ApplyInternal(mobileParty, isRaftState: false);
		}
	}
	public static class RemoveCompanionAction
	{
		public enum RemoveCompanionDetail
		{
			Fire,
			Death,
			AfterQuest,
			ByTurningToLord
		}

		private static void ApplyInternal(Clan clan, Hero companion, RemoveCompanionDetail detail)
		{
			PartyBase partyBase = companion.PartyBelongedTo?.Party;
			companion.CompanionOf = null;
			if (partyBase != null && partyBase.IsMobile && detail != RemoveCompanionDetail.ByTurningToLord)
			{
				bool num = partyBase.LeaderHero == companion;
				partyBase.MemberRoster.AddToCounts(companion.CharacterObject, -1);
				if (num)
				{
					partyBase.MobileParty.SetMoveModeHold();
					partyBase.MobileParty.Ai.RethinkAtNextHourlyTick = true;
					if (partyBase.MemberRoster.Count == 0)
					{
						DestroyPartyAction.Apply(null, partyBase.MobileParty);
					}
					else
					{
						DisbandPartyAction.StartDisband(partyBase.MobileParty);
					}
				}
			}
			if (detail == RemoveCompanionDetail.Fire)
			{
				if (companion.PartyBelongedToAsPrisoner != null)
				{
					EndCaptivityAction.ApplyByEscape(companion);
				}
				else
				{
					MakeHeroFugitiveAction.Apply(companion);
				}
				if (companion.IsWanderer)
				{
					companion.ResetEquipments();
				}
			}
			if (companion.GovernorOf != null)
			{
				ChangeGovernorAction.RemoveGovernorOf(companion);
			}
			CampaignEventDispatcher.Instance.OnCompanionRemoved(companion, detail);
		}

		public static void ApplyByFire(Clan clan, Hero companion)
		{
			ApplyInternal(clan, companion, RemoveCompanionDetail.Fire);
