	public static class SellGoodsForTradeAction
	{
		private enum SellGoodsForTradeActionDetail
		{
			VillagerTrade,
			LordTrade
		}

		private static void ApplyInternal(Settlement settlement, MobileParty mobileParty, SellGoodsForTradeActionDetail detail)
		{
			Town town = settlement.Town;
			if (town == null)
			{
				return;
			}
			List<(EquipmentElement, int)> list = new List<(EquipmentElement, int)>();
			if (detail != 0)
			{
				return;
			}
			int num = 10000;
			ItemObject itemObject = null;
			for (int i = 0; i < mobileParty.ItemRoster.Count; i++)
			{
				ItemRosterElement elementCopyAtIndex = mobileParty.ItemRoster.GetElementCopyAtIndex(i);
				if (elementCopyAtIndex.EquipmentElement.Item.ItemCategory == DefaultItemCategories.PackAnimal && elementCopyAtIndex.EquipmentElement.Item.Value < num)
				{
					num = elementCopyAtIndex.EquipmentElement.Item.Value;
					itemObject = elementCopyAtIndex.EquipmentElement.Item;
				}
			}
			for (int num2 = mobileParty.ItemRoster.Count - 1; num2 >= 0; num2--)
			{
				ItemRosterElement elementCopyAtIndex2 = mobileParty.ItemRoster.GetElementCopyAtIndex(num2);
				int itemPrice = town.GetItemPrice(elementCopyAtIndex2.EquipmentElement, mobileParty, isSelling: true);
				int num3 = mobileParty.ItemRoster.GetElementNumber(num2);
				if (elementCopyAtIndex2.EquipmentElement.Item == itemObject)
				{
					int num4 = (int)(0.5f * (float)mobileParty.MemberRoster.TotalManCount);
					num3 -= num4;
				}
				if (num3 > 0)
				{
					int num5 = TaleWorlds.Library.MathF.Min(num3, town.Gold / itemPrice);
					if (num5 > 0)
					{
						mobileParty.PartyTradeGold += num5 * itemPrice;
						EquipmentElement equipmentElement = elementCopyAtIndex2.EquipmentElement;
						town.ChangeGold(-num5 * itemPrice);
						settlement.ItemRoster.AddToCounts(equipmentElement, num5);
						mobileParty.ItemRoster.AddToCounts(equipmentElement, -num5);
						list.Add((equipmentElement, num5));
					}
				}
			}
			if (!list.IsEmpty() && mobileParty.IsCaravan)
			{
				CampaignEventDispatcher.Instance.OnCaravanTransactionCompleted(mobileParty, town, list);
			}
		}

		public static void ApplyByVillagerTrade(Settlement settlement, MobileParty villagerParty)
		{
			ApplyInternal(settlement, villagerParty, SellGoodsForTradeActionDetail.VillagerTrade);
		}
	}
	public static class SellItemsAction
	{
		private static void ApplyInternal(PartyBase sellerParty, PartyBase buyerParty, ItemRosterElement itemRosterElement, int number, Settlement currentSettlement)
		{
			if (currentSettlement == null)
			{
				if (sellerParty.Settlement != null)
				{
					currentSettlement = sellerParty.Settlement;
				}
				else
				{
					if (buyerParty.Settlement == null)
					{
						throw new MBInvalidParameterException("currentSettlement");
					}
					currentSettlement = buyerParty.Settlement;
				}
			}
			Town town = currentSettlement.Town;
			if (town == null)
			{
				if (!currentSettlement.IsVillage)
				{
					throw new MBException();
				}
				town = ((currentSettlement.Village.TradeBound != null) ? currentSettlement.Village.TradeBound.Town : currentSettlement.Village.Bound.Town);
			}
			MobileParty mobileParty = buyerParty?.MobileParty;
			bool isSelling = false;
			if (mobileParty == null)
			{
				mobileParty = sellerParty?.MobileParty;
				isSelling = true;
			}
			if (mobileParty == null)
			{
				return;
			}
			int num = 0;
			for (int i = 0; i < number; i++)
			{
				int itemPrice = town.GetItemPrice(itemRosterElement.EquipmentElement, mobileParty, isSelling);
				num += itemPrice;
				sellerParty.ItemRoster.AddToCounts(itemRosterElement.EquipmentElement, -1);
				buyerParty?.ItemRoster.AddToCounts(itemRosterElement.EquipmentElement, 1);
			}
			if (buyerParty != null && buyerParty.IsSettlement)
			{
				if (mobileParty.IsCaravan)
				{
					if (Campaign.Current.GameStarted)
					{
						GiveGoldAction.ApplyForSettlementToParty(buyerParty.Settlement, sellerParty, num);
					}
				}
				else
				{
					GiveGoldAction.ApplyForSettlementToCharacter(buyerParty.Settlement, sellerParty.LeaderHero, num);
				}
			}
			else if (sellerParty != null && sellerParty.IsSettlement)
			{
				int num2 = MBRandom.RoundRandomized((float)num * (sellerParty.Settlement.IsTown ? Campaign.Current.Models.SettlementTaxModel.GetTownTaxRatio(sellerParty.Settlement.Town) : Campaign.Current.Models.SettlementTaxModel.GetVillageTaxRatio(sellerParty.Settlement.Village)));
				if (mobileParty.IsCaravan)
				{
					if (Campaign.Current.GameStarted)
					{
						GiveGoldAction.ApplyForPartyToSettlement(buyerParty, sellerParty.Settlement, num);
					}
				}
				else if (buyerParty != null)
				{
					GiveGoldAction.ApplyForCharacterToSettlement(buyerParty.LeaderHero, sellerParty.Settlement, num);
				}
				else
				{
					sellerParty.Settlement.SettlementComponent.ChangeGold(num);
				}
				sellerParty.Settlement.SettlementComponent.ChangeGold(-num2);
				if (sellerParty.Settlement.Town != null)
				{
					float townCommissionChangeBasedOnSecurity = Campaign.Current.Models.SettlementTaxModel.GetTownCommissionChangeBasedOnSecurity(sellerParty.Settlement.Town, num2);
					sellerParty.Settlement.Town.TradeTaxAccumulated += (int)townCommissionChangeBasedOnSecurity;
				}
			}
			else if (sellerParty.MobileParty.CurrentSettlement != null)
			{
				if (sellerParty.IsMobile && sellerParty.MobileParty.IsCaravan && sellerParty.Owner != null)
				{
					GiveGoldAction.ApplyForPartyToParty(buyerParty, sellerParty, num);
				}
				else if (buyerParty != null)
				{
					GiveGoldAction.ApplyBetweenCharacters(buyerParty.LeaderHero, sellerParty.LeaderHero, num);
				}
			}
		}

		public static void Apply(PartyBase receiverParty, PartyBase payerParty, ItemRosterElement subject, int number, Settlement currentSettlement = null)
		{
			ApplyInternal(receiverParty, payerParty, subject, number, currentSettlement);
		}
	}
	public static class SellPrisonersAction
	{
		private static void ApplyInternal(PartyBase sellerParty, PartyBase buyerParty, TroopRoster prisoners, bool applyConsequences)
		{
			Settlement settlement = sellerParty.Settlement ?? buyerParty?.Settlement;
			TroopRoster troopRoster = TroopRoster.CreateDummyTroopRoster();
			int num = 0;
			bool flag = false;
			foreach (TroopRosterElement item in prisoners.GetTroopRoster())
			{
				CharacterObject character = item.Character;
				if (!character.IsHero)
				{
					if (applyConsequences)
					{
						sellerParty.PrisonRoster.AddToCounts(character, -item.Number, insertAtFront: false, -item.WoundedNumber);
					}
				}
				else if (character.HeroObject != Hero.MainHero)
				{
					if (buyerParty != null)
					{
						if (!buyerParty.MapFaction.IsAtWarWith(character.HeroObject.MapFaction))
						{
							if (character.HeroObject.Clan == Clan.PlayerClan)
							{
								EndCaptivityAction.ApplyByReleasedByCompensation(character.HeroObject);
							}
							else
							{
								EndCaptivityAction.ApplyByRansom(character.HeroObject, null);
							}
						}
						else
						{
							if (sellerParty.MapFaction == buyerParty.MapFaction && sellerParty != PartyBase.MainParty)
							{
								flag = true;
								troopRoster.Add(item);
							}
							TransferPrisonerAction.Apply(character, sellerParty, buyerParty);
						}
					}
					else
					{
						EndCaptivityAction.ApplyByRansom(character.HeroObject, null);
					}
					if (settlement != null)
					{
						CampaignEventDispatcher.Instance.OnPrisonersChangeInSettlement(settlement, null, character.HeroObject, takenFromDungeon: false);
					}
				}
				if (applyConsequences && !flag && character != Hero.MainHero.CharacterObject)
				{
					int num2 = Campaign.Current.Models.RansomValueCalculationModel.PrisonerRansomValue(character, sellerParty?.LeaderHero);
					num += item.Number * num2;
				}
			}
			if (applyConsequences && !flag && num > 0)
			{
				if (sellerParty.IsMobile)
				{
					Hero recipientHero = null;
					if (sellerParty.LeaderHero != null && sellerParty.LeaderHero.HeroState == Hero.CharacterStates.Active)
					{
						recipientHero = sellerParty.LeaderHero;
					}
					else if (sellerParty.Owner != null && sellerParty.Owner.HeroState == Hero.CharacterStates.Active)
					{
						recipientHero = sellerParty.Owner;
					}
					else if (sellerParty.MobileParty.ActualClan?.Leader != null)
					{
						recipientHero = sellerParty.MobileParty.ActualClan.Leader;
					}
					GiveGoldAction.ApplyBetweenCharacters(null, recipientHero, num);
				}
				else
				{
					bool disableNotification = buyerParty?.Settlement?.OwnerClan != Clan.PlayerClan;
					GiveGoldAction.ApplyForPartyToSettlement(null, sellerParty.Settlement, num, disableNotification);
				}
			}
			if (sellerParty.IsMobile)
			{
				SkillLevelingManager.OnPrisonerSell(sellerParty.MobileParty, in prisoners);
			}
			CampaignEventDispatcher.Instance.OnPrisonerSold(sellerParty, buyerParty, prisoners);
			if (settlement != null && troopRoster.Count > 0)
			{
				CampaignEventDispatcher.Instance.OnPrisonerDonatedToSettlement(sellerParty.MobileParty, troopRoster.ToFlattenedRoster(), settlement);
			}
		}

		public static void ApplyForAllPrisoners(PartyBase sellerParty, PartyBase buyerParty)
		{
			ApplyInternal(sellerParty, buyerParty, sellerParty.PrisonRoster.CloneRosterData(), applyConsequences: true);
		}

		public static void ApplyForSelectedPrisoners(PartyBase sellerParty, PartyBase buyerParty, TroopRoster prisoners)
		{
			ApplyInternal(sellerParty, buyerParty, prisoners, applyConsequences: true);
		}

		public static void ApplyByPartyScreen(TroopRoster prisoners)
		{
			ApplyInternal(PartyBase.MainParty, Hero.MainHero.CurrentSettlement.Party, prisoners, applyConsequences: false);
		}
	}
	public static class SetPartyAiAction
	{
		private enum SetPartyAiActionDetail
		{
			GoToSettlement,
			PatrolAroundSettlement,
			PatrolAroundPoint,
			RaidSettlement,
			BesiegeSettlement,
			EngageParty,
			GoAroundParty,
			DefendParty,
			EscortParty,
			MoveToNearestLand
		}

		private static void ApplyInternal(MobileParty owner, Settlement settlement, MobileParty mobileParty, CampaignVec2 position, SetPartyAiActionDetail detail, MobileParty.NavigationType navigationType, bool isFromPort, bool isTargetingPort)
		{
			switch (detail)
			{
			case SetPartyAiActionDetail.GoToSettlement:
				if (owner.DefaultBehavior != AiBehavior.GoToSettlement || owner.TargetSettlement != settlement || navigationType != owner.DesiredAiNavigationType || owner.IsTargetingPort != isTargetingPort || owner.StartTransitionNextFrameToExitFromPort != isFromPort)
				{
					if (isFromPort && !owner.IsTransitionInProgress)
					{
						owner.StartTransitionNextFrameToExitFromPort = true;
					}
					owner.SetMoveGoToSettlement(settlement, navigationType, isTargetingPort);
				}
				if (owner.Army != null && owner.Army.LeaderParty == owner)
				{
					owner.Army.ArmyType = Army.ArmyTypes.Defender;
					owner.Army.AiBehaviorObject = settlement;
				}
				break;
			case SetPartyAiActionDetail.PatrolAroundSettlement:
				if (owner.DefaultBehavior != AiBehavior.PatrolAroundPoint || owner.TargetSettlement != settlement || navigationType != owner.DesiredAiNavigationType || owner.IsTargetingPort != isTargetingPort || owner.StartTransitionNextFrameToExitFromPort != isFromPort)
				{
					if (isFromPort && !owner.IsTransitionInProgress)
					{
						owner.StartTransitionNextFrameToExitFromPort = true;
					}
					owner.SetMovePatrolAroundSettlement(settlement, navigationType, isTargetingPort);
				}
				if (owner.Army != null && owner.Army.LeaderParty == owner)
				{
					owner.Army.ArmyType = Army.ArmyTypes.Defender;
					owner.Army.AiBehaviorObject = settlement;
				}
				break;
			case SetPartyAiActionDetail.RaidSettlement:
				if (owner.DefaultBehavior != AiBehavior.RaidSettlement || owner.TargetSettlement != settlement || navigationType != owner.DesiredAiNavigationType || owner.StartTransitionNextFrameToExitFromPort != isFromPort)
				{
					if (isFromPort && !owner.IsTransitionInProgress)
					{
						owner.StartTransitionNextFrameToExitFromPort = true;
					}
					owner.SetMoveRaidSettlement(settlement, navigationType, isTargetingPort);
					if (owner.Army != null && owner.Army.LeaderParty == owner)
					{
						owner.Army.ArmyType = Army.ArmyTypes.Raider;
						owner.Army.AiBehaviorObject = settlement;
					}
				}
				break;
			case SetPartyAiActionDetail.BesiegeSettlement:
				if (owner.DefaultBehavior != AiBehavior.BesiegeSettlement || owner.TargetSettlement != settlement || navigationType != owner.DesiredAiNavigationType || owner.StartTransitionNextFrameToExitFromPort != isFromPort)
				{
					if (isFromPort && !owner.IsTransitionInProgress)
					{
						owner.StartTransitionNextFrameToExitFromPort = true;
					}
					owner.SetMoveBesiegeSettlement(settlement, navigationType);
					if (owner.Army != null && owner.Army.LeaderParty == owner)
					{
						owner.Army.ArmyType = Army.ArmyTypes.Besieger;
						owner.Army.AiBehaviorObject = settlement;
					}
				}
				break;
			case SetPartyAiActionDetail.GoAroundParty:
				if (owner.DefaultBehavior != AiBehavior.GoAroundParty || owner != mobileParty || navigationType != owner.DesiredAiNavigationType || owner.StartTransitionNextFrameToExitFromPort != isFromPort)
				{
					if (isFromPort && !owner.IsTransitionInProgress)
					{
						owner.StartTransitionNextFrameToExitFromPort = true;
					}
					owner.SetMoveGoAroundParty(mobileParty, navigationType);
				}
				break;
			case SetPartyAiActionDetail.EngageParty:
				if (owner.DefaultBehavior != AiBehavior.EngageParty || owner != mobileParty || navigationType != owner.DesiredAiNavigationType || owner.StartTransitionNextFrameToExitFromPort != isFromPort)
				{
					if (isFromPort && !owner.IsTransitionInProgress)
					{
						owner.StartTransitionNextFrameToExitFromPort = true;
					}
					owner.SetMoveEngageParty(mobileParty, navigationType);
				}
				break;
			case SetPartyAiActionDetail.DefendParty:
				if (owner.DefaultBehavior != AiBehavior.DefendSettlement || owner != mobileParty || navigationType != owner.DesiredAiNavigationType || owner.StartTransitionNextFrameToExitFromPort != isFromPort || owner.IsTargetingPort != isTargetingPort)
				{
					if (isFromPort && !owner.IsTransitionInProgress)
					{
						owner.StartTransitionNextFrameToExitFromPort = true;
					}
					owner.SetMoveDefendSettlement(settlement, isTargetingPort, navigationType);
					if (owner.Army != null && owner.Army.LeaderParty == owner)
					{
						owner.Army.ArmyType = Army.ArmyTypes.Defender;
						owner.Army.AiBehaviorObject = settlement;
					}
				}
				break;
			case SetPartyAiActionDetail.EscortParty:
				if (owner.DefaultBehavior != AiBehavior.EscortParty || owner.TargetParty != mobileParty || navigationType != owner.DesiredAiNavigationType || owner.StartTransitionNextFrameToExitFromPort != isFromPort || owner.IsTargetingPort != isTargetingPort)
				{
					if (isFromPort && !owner.IsTransitionInProgress)
					{
						owner.StartTransitionNextFrameToExitFromPort = true;
					}
					owner.SetMoveEscortParty(mobileParty, navigationType, isTargetingPort);
				}
				break;
			case SetPartyAiActionDetail.MoveToNearestLand:
				if (owner.DefaultBehavior != AiBehavior.MoveToNearestLandOrPort)
				{
					owner.SetMoveToNearestLand(settlement);
				}
				break;
			case SetPartyAiActionDetail.PatrolAroundPoint:
				if (owner.DefaultBehavior != AiBehavior.PatrolAroundPoint || navigationType != owner.DesiredAiNavigationType)
				{
					owner.SetMovePatrolAroundPoint(position, navigationType);
				}
				break;
			}
		}

