	public static class StartBattleAction
	{
		private static void ApplyInternal(PartyBase attackerParty, PartyBase defenderParty, object subject, MapEvent.BattleTypes battleType)
		{
			if (defenderParty.MapEvent == null)
			{
				Campaign.Current.Models.EncounterModel.CreateMapEventComponentForEncounter(attackerParty, defenderParty, battleType);
				if (defenderParty.MapEvent == null)
				{
					return;
				}
			}
			else
			{
				BattleSideEnum side = BattleSideEnum.Attacker;
				if (defenderParty.Side == BattleSideEnum.Attacker)
				{
					side = BattleSideEnum.Defender;
				}
				attackerParty.MapEventSide = defenderParty.MapEvent.GetMapEventSide(side);
			}
			if (defenderParty.MapEvent.IsPlayerMapEvent && !defenderParty.MapEvent.IsSallyOut && PlayerEncounter.Current != null && MobileParty.MainParty.CurrentSettlement != null)
			{
				PlayerEncounter.Current.InterruptEncounter("encounter_interrupted");
			}
			bool flag = (attackerParty.MobileParty?.Army == null || attackerParty.MobileParty?.Army.LeaderParty == attackerParty.MobileParty) && (defenderParty.MobileParty?.Army == null || defenderParty.MobileParty?.Army.LeaderParty == defenderParty.MobileParty);
			if (flag && defenderParty.IsSettlement && defenderParty.MapEvent != null && defenderParty.MapEvent.DefenderSide.Parties.Count > 1)
			{
				flag = false;
			}
			CampaignEventDispatcher.Instance.OnStartBattle(attackerParty, defenderParty, subject, flag);
		}

		public static void Apply(PartyBase attackerParty, PartyBase defenderParty)
		{
			MapEvent.BattleTypes battleTypes = MapEvent.BattleTypes.None;
			object obj = null;
			Settlement settlement;
			if (defenderParty.MapEvent == null)
			{
				if (attackerParty.MobileParty != null && attackerParty.MobileParty.IsGarrison)
				{
					settlement = attackerParty.MobileParty.CurrentSettlement;
					battleTypes = (attackerParty.MobileParty.IsTargetingPort ? MapEvent.BattleTypes.BlockadeSallyOutBattle : MapEvent.BattleTypes.SallyOut);
				}
				else if (attackerParty.MobileParty.CurrentSettlement != null)
				{
					settlement = attackerParty.MobileParty.CurrentSettlement;
				}
				else if (defenderParty.MobileParty.CurrentSettlement != null)
				{
					settlement = defenderParty.MobileParty.CurrentSettlement;
				}
				else if (attackerParty.MobileParty.BesiegedSettlement != null)
				{
					settlement = attackerParty.MobileParty.BesiegedSettlement;
					if (!defenderParty.IsSettlement)
					{
						battleTypes = MapEvent.BattleTypes.SiegeOutside;
					}
				}
				else if (defenderParty.MobileParty.BesiegedSettlement != null)
				{
					settlement = defenderParty.MobileParty.BesiegedSettlement;
					battleTypes = MapEvent.BattleTypes.SiegeOutside;
				}
				else
				{
					battleTypes = MapEvent.BattleTypes.FieldBattle;
					settlement = null;
				}
				if (settlement != null && battleTypes == MapEvent.BattleTypes.None)
				{
					if (settlement.IsTown)
					{
						battleTypes = MapEvent.BattleTypes.Siege;
						if (attackerParty.IsMobile && defenderParty.SiegeEvent != null && attackerParty.SiegeEvent != null && attackerParty.MobileParty.IsCurrentlyAtSea && attackerParty.MobileParty.IsTargetingPort)
						{
							battleTypes = MapEvent.BattleTypes.BlockadeBattle;
						}
					}
					else if (settlement.IsHideout)
					{
						battleTypes = MapEvent.BattleTypes.Hideout;
					}
					else if (settlement.IsVillage)
					{
						battleTypes = MapEvent.BattleTypes.FieldBattle;
					}
					else
					{
						TaleWorlds.Library.Debug.FailedAssert("Missing settlement type in StartBattleAction.GetGameAction", "C:\\BuildAgent\\work\\mb3\\Source\\Bannerlord\\TaleWorlds.CampaignSystem\\Actions\\StartBattleAction.cs", "Apply", 135);
					}
				}
			}
			else
			{
				Settlement mapEventSettlement = defenderParty.MapEvent.MapEventSettlement;
				if (defenderParty.MapEvent.IsFieldBattle)
				{
					battleTypes = MapEvent.BattleTypes.FieldBattle;
				}
				else if (defenderParty.MapEvent.IsRaid)
				{
					battleTypes = MapEvent.BattleTypes.Raid;
					if (defenderParty.MobileParty.IsCurrentlyAtSea && attackerParty.MobileParty.IsCurrentlyAtSea && !mapEventSettlement.GetInvolvedPartiesForEventType(MapEvent.BattleTypes.Raid).AnyQ((PartyBase t) => t.NumberOfHealthyMembers > 0))
					{
						defenderParty.MapEventSide = null;
						battleTypes = MapEvent.BattleTypes.FieldBattle;
					}
				}
				else if (defenderParty.MapEvent.IsSiegeAssault)
				{
					battleTypes = MapEvent.BattleTypes.Siege;
				}
				else if (defenderParty.MapEvent.IsSallyOut)
				{
					battleTypes = MapEvent.BattleTypes.SallyOut;
				}
				else if (defenderParty.MapEvent.IsSiegeOutside)
				{
					battleTypes = MapEvent.BattleTypes.SiegeOutside;
				}
				else if (defenderParty.MapEvent.IsBlockade)
				{
					battleTypes = MapEvent.BattleTypes.BlockadeBattle;
				}
				else if (defenderParty.MapEvent.IsBlockadeSallyOut)
				{
					battleTypes = MapEvent.BattleTypes.BlockadeSallyOutBattle;
				}
				else
				{
					TaleWorlds.Library.Debug.FailedAssert("Missing mapEventType?", "C:\\BuildAgent\\work\\mb3\\Source\\Bannerlord\\TaleWorlds.CampaignSystem\\Actions\\StartBattleAction.cs", "Apply", 180);
				}
				settlement = mapEventSettlement;
			}
			obj = obj ?? settlement;
			ApplyInternal(attackerParty, defenderParty, obj, battleTypes);
		}

		public static void ApplyStartBattle(MobileParty attackerParty, MobileParty defenderParty)
		{
			ApplyInternal(attackerParty.Party, defenderParty.Party, null, MapEvent.BattleTypes.FieldBattle);
		}

		public static void ApplyStartRaid(MobileParty attackerParty, Settlement settlement)
		{
			ApplyInternal(attackerParty.Party, settlement.Party, settlement, MapEvent.BattleTypes.Raid);
		}

		public static void ApplyStartSallyOut(Settlement settlement, MobileParty defenderParty)
		{
			ApplyInternal(settlement.Town.GarrisonParty.Party, defenderParty.Party, settlement, MapEvent.BattleTypes.SallyOut);
		}

		public static void ApplyStartAssaultAgainstWalls(MobileParty attackerParty, Settlement settlement)
		{
			ApplyInternal(attackerParty.Party, settlement.Party, settlement, MapEvent.BattleTypes.Siege);
		}
	}
	public static class StartMercenaryServiceAction
	{
		public enum StartMercenaryServiceActionDetails
		{
			ApplyByDefault
		}

		private static void ApplyStart(Clan clan, Kingdom kingdom, int awardMultiplier, StartMercenaryServiceActionDetails details)
		{
			if (clan.IsUnderMercenaryService)
			{
				EndMercenaryServiceAction.EndByLeavingKingdom(clan);
			}
			clan.MercenaryAwardMultiplier = awardMultiplier;
			clan.Kingdom = kingdom;
			clan.StartMercenaryService();
			if (clan == Clan.PlayerClan)
			{
				Campaign.Current.KingdomManager.PlayerMercenaryServiceNextRenewalDay = Campaign.CurrentTime + 30f * (float)CampaignTime.HoursInDay;
			}
			CampaignEventDispatcher.Instance.OnMercenaryServiceStarted(clan, details);
		}

		public static void ApplyByDefault(Clan clan, Kingdom kingdom, int awardMultiplier)
		{
			ApplyStart(clan, kingdom, awardMultiplier, StartMercenaryServiceActionDetails.ApplyByDefault);
		}
	}
	public static class TakePrisonerAction
	{
		private static void ApplyInternal(PartyBase capturerParty, Hero prisonerCharacter, bool isEventCalled = true)
		{
			if (prisonerCharacter.PartyBelongedTo != null)
			{
				if (prisonerCharacter.PartyBelongedTo.LeaderHero == prisonerCharacter)
				{
					prisonerCharacter.PartyBelongedTo.RemovePartyLeader();
				}
				prisonerCharacter.PartyBelongedTo.MemberRoster.RemoveTroop(prisonerCharacter.CharacterObject);
			}
			prisonerCharacter.CaptivityStartTime = CampaignTime.Now;
			prisonerCharacter.ChangeState(Hero.CharacterStates.Prisoner);
			capturerParty.AddPrisoner(prisonerCharacter.CharacterObject, 1);
			if (prisonerCharacter == Hero.MainHero)
			{
				if (MobileParty.MainParty.IsDisorganized)
				{
					MobileParty.MainParty.SetDisorganized(isDisorganized: false);
				}
				PlayerCaptivity.StartCaptivity(capturerParty);
				if (MobileParty.MainParty.IsCurrentlyAtSea)
				{
					for (int num = MobileParty.MainParty.Ships.Count - 1; num >= 0; num--)
					{
						DestroyShipAction.Apply(MobileParty.MainParty.Ships[num]);
					}
				}
			}
			if (prisonerCharacter.StayingInSettlement != null)
			{
				prisonerCharacter.StayingInSettlement = null;
			}
			if (isEventCalled)
			{
				CampaignEventDispatcher.Instance.OnHeroPrisonerTaken(capturerParty, prisonerCharacter);
			}
		}

		public static void Apply(PartyBase capturerParty, Hero prisonerCharacter)
		{
			ApplyInternal(capturerParty, prisonerCharacter);
		}

		public static void ApplyByTakenFromPartyScreen(FlattenedTroopRoster roster)
		{
			foreach (FlattenedTroopRosterElement item in roster)
			{
				if (item.Troop.IsHero)
				{
					ApplyInternal(PartyBase.MainParty, item.Troop.HeroObject);
				}
			}
			CampaignEventDispatcher.Instance.OnPrisonerTaken(roster);
		}
	}
	public static class TeleportHeroAction
	{
		public enum TeleportationDetail
		{
			ImmediateTeleportToSettlement,
			ImmediateTeleportToParty,
			ImmediateTeleportToPartyAsPartyLeader,
			DelayedTeleportToSettlement,
			DelayedTeleportToParty,
			DelayedTeleportToSettlementAsGovernor,
			DelayedTeleportToPartyAsPartyLeader
		}

		private static void ApplyInternal(Hero hero, Settlement targetSettlement, MobileParty targetParty, TeleportationDetail detail)
		{
			CampaignEventDispatcher.Instance.OnHeroTeleportationRequested(hero, targetSettlement, targetParty, detail);
			switch (detail)
			{
			default:
				return;
			case TeleportationDetail.ImmediateTeleportToSettlement:
				if (targetSettlement == null)
				{
					return;
				}
				if (!hero.IsActive)
				{
					hero.ChangeState(Hero.CharacterStates.Active);
				}
				if (hero.CurrentSettlement != null)
				{
					LeaveSettlementAction.ApplyForCharacterOnly(hero);
				}
				if (hero.PartyBelongedTo != null)
				{
					if (!hero.PartyBelongedTo.IsActive || hero.PartyBelongedTo.IsCurrentlyEngagingParty || hero.PartyBelongedTo.MapEvent != null)
					{
						return;
					}
					hero.PartyBelongedTo.MemberRoster.RemoveTroop(hero.CharacterObject);
				}
				EnterSettlementAction.ApplyForCharacterOnly(hero, targetSettlement);
				return;
			case TeleportationDetail.ImmediateTeleportToParty:
				if (hero.IsTraveling)
				{
					hero.ChangeState(Hero.CharacterStates.Active);
				}
				AddHeroToPartyAction.Apply(hero, targetParty);
				return;
			case TeleportationDetail.ImmediateTeleportToPartyAsPartyLeader:
				if (hero.IsTraveling)
				{
					hero.ChangeState(Hero.CharacterStates.Active);
				}
				AddHeroToPartyAction.Apply(hero, targetParty);
				targetParty.ChangePartyLeader(hero);
				targetParty.PartyComponent.ClearCachedName();
				targetParty.Party.SetCustomName(null);
				targetParty.Party.SetVisualAsDirty();
				if (targetParty.IsDisbanding)
				{
					DisbandPartyAction.CancelDisband(targetParty);
				}
				if (targetParty.Ai.DoNotMakeNewDecisions)
				{
					targetParty.Ai.SetDoNotMakeNewDecisions(doNotMakeNewDecisions: false);
				}
				return;
			case TeleportationDetail.DelayedTeleportToSettlement:
				if (hero.CurrentSettlement == targetSettlement)
				{
					ApplyImmediateTeleportToSettlement(hero, targetSettlement);
					return;
				}
				break;
			case TeleportationDetail.DelayedTeleportToParty:
			case TeleportationDetail.DelayedTeleportToSettlementAsGovernor:
			case TeleportationDetail.DelayedTeleportToPartyAsPartyLeader:
				break;
			}
			if (hero.GovernorOf != null)
			{
				ChangeGovernorAction.RemoveGovernorOf(hero);
			}
			if (hero.CurrentSettlement != null && hero.CurrentSettlement != targetSettlement)
			{
				LeaveSettlementAction.ApplyForCharacterOnly(hero);
			}
			if (hero.PartyBelongedTo != null)
			{
				if (!hero.PartyBelongedTo.IsActive || (hero.PartyBelongedTo.IsCurrentlyEngagingParty && hero.PartyBelongedTo.MapEvent != null))
				{
					return;
				}
				hero.PartyBelongedTo.MemberRoster.RemoveTroop(hero.CharacterObject);
			}
			if (detail == TeleportationDetail.DelayedTeleportToPartyAsPartyLeader)
			{
				TextObject textObject = new TextObject("{=ithcVNfA}{CLAN_NAME}{.o} Party");
				textObject.SetTextVariable("CLAN_NAME", (targetParty.ActualClan != null) ? targetParty.ActualClan.Name : CampaignData.NeutralFactionName);
				targetParty.Party.SetCustomName(textObject);
			}
			hero.ChangeState(Hero.CharacterStates.Traveling);
		}

		public static void ApplyImmediateTeleportToSettlement(Hero heroToBeMoved, Settlement targetSettlement)
		{
			ApplyInternal(heroToBeMoved, targetSettlement, null, TeleportationDetail.ImmediateTeleportToSettlement);
		}

		public static void ApplyImmediateTeleportToParty(Hero heroToBeMoved, MobileParty party)
		{
			ApplyInternal(heroToBeMoved, null, party, TeleportationDetail.ImmediateTeleportToParty);
		}

		public static void ApplyImmediateTeleportToPartyAsPartyLeader(Hero heroToBeMoved, MobileParty party)
		{
			ApplyInternal(heroToBeMoved, null, party, TeleportationDetail.ImmediateTeleportToPartyAsPartyLeader);
		}

		public static void ApplyDelayedTeleportToSettlement(Hero heroToBeMoved, Settlement targetSettlement)
		{
			ApplyInternal(heroToBeMoved, targetSettlement, null, TeleportationDetail.DelayedTeleportToSettlement);
		}

		public static void ApplyDelayedTeleportToParty(Hero heroToBeMoved, MobileParty party)
		{
			ApplyInternal(heroToBeMoved, null, party, TeleportationDetail.DelayedTeleportToParty);
		}

		public static void ApplyDelayedTeleportToSettlementAsGovernor(Hero heroToBeMoved, Settlement targetSettlement)
		{
			ApplyInternal(heroToBeMoved, targetSettlement, null, TeleportationDetail.DelayedTeleportToSettlementAsGovernor);
		}

		public static void ApplyDelayedTeleportToPartyAsPartyLeader(Hero heroToBeMoved, MobileParty party)
		{
			ApplyInternal(heroToBeMoved, null, party, TeleportationDetail.DelayedTeleportToPartyAsPartyLeader);
		}
	}
	public static class TransferPrisonerAction
	{
		private static void ApplyInternal(CharacterObject prisonerTroop, PartyBase prisonerOwnerParty, PartyBase newParty)
		{
			if (prisonerTroop.HeroObject == Hero.MainHero)
			{
				PlayerCaptivity.CaptorParty = newParty;
				return;
			}
			prisonerOwnerParty.PrisonRoster.AddToCounts(prisonerTroop, -1);
			newParty.AddPrisoner(prisonerTroop, 1);
		}

		public static void Apply(CharacterObject prisonerTroop, PartyBase prisonerOwnerParty, PartyBase newParty)
		{
			ApplyInternal(prisonerTroop, prisonerOwnerParty, newParty);
		}
	}
}
